window.STEPS=Object.assign(window.STEPS||{},{"ns-0047f48feafb":{"길":"접선 길이가 같다는 성질로 OR을 a로 나타내고 유리화로 극한을 구한다","단계":[{"제목":"OP의 길이와 접선 길이 표시","힌트":"$\\overline{\\mathrm{OP}}$의 길이는? 접점 R, S, I에서 각 꼭짓점까지의 길이를 $d$로 나타내면?","식":["$\\overline{\\mathrm{OP}}=\\sqrt{12^2+5^2}=13$","$\\overline{\\mathrm{PR}}=\\overline{\\mathrm{PI}}=13-d,\\ \\overline{\\mathrm{OS}}=d,\\ \\overline{\\mathrm{QS}}=\\overline{\\mathrm{QI}}=a-d$"],"설명":"원 밖의 한 점에서 그은 두 접선의 길이는 같다. S는 변 OQ 위의 접점, I는 변 PQ 위의 접점이다. $\\overline{\\mathrm{OQ}}=a$이므로 $\\overline{\\mathrm{QS}}=a-d$이다.","확인":"13","스킬":"S7"},{"제목":"PQ로 식을 세워 d 구하기","힌트":"$\\overline{\\mathrm{PQ}}$를 접선 길이의 합과 좌표 거리로 각각 나타내 같게 놓으면?","식":["$\\overline{\\mathrm{PQ}}=(13-d)+(a-d)=\\sqrt{(a-12)^2+5^2}$","$d=\\frac{1}{2}\\left\\{(a+13)-\\sqrt{(a-12)^2+25}\\right\\}$"],"설명":"$\\overline{\\mathrm{PQ}}$는 $\\overline{\\mathrm{PI}}+\\overline{\\mathrm{IQ}}$이고, 두 점 P, Q의 거리 공식으로도 나타난다. 두 식을 같게 놓고 $d$에 대해 푼다.","확인":null,"스킬":"S7","고비":true},{"제목":"분자의 유리화","힌트":"$(a+13)-\\sqrt{(a-12)^2+25}$에 켤레식을 곱하면 분자는 $\\square\\,a$ 꼴이다. 이 수는?","식":["$(a+13)^2-\\left\\{(a-12)^2+25\\right\\}=50a$","$d=\\frac{1}{2}\\cdot\\frac{50a}{(a+13)+\\sqrt{(a-12)^2+25}}$"],"설명":"$a\\to\\infty$에서 $\\infty-\\infty$ 꼴이므로 켤레식 $(a+13)+\\sqrt{(a-12)^2+25}$를 분자와 분모에 곱한다. $a^2$ 항이 모두 사라진다.","확인":"50","스킬":"A5"},{"제목":"극한값 계산","힌트":"분모와 분자를 $a$로 나눈 뒤 $a\\to\\infty$를 보내면?","식":["$\\lim_{a\\to\\infty}\\frac{25a}{(a+13)+\\sqrt{(a-12)^2+25}}=\\lim_{a\\to\\infty}\\frac{25}{\\left(1+\\frac{13}{a}\\right)+\\sqrt{\\left(1-\\frac{12}{a}\\right)^2+\\frac{25}{a^2}}}$","$=\\frac{25}{1+1}=\\frac{25}{2}$"],"설명":"$a>0$이므로 분모를 $a$로 나눌 때 근호 안은 $a^2$으로 나뉘어 $\\sqrt{\\cdots}$ 전체를 $a$로 나눈 것과 같다. $\\frac{1}{a}$ 꼴은 모두 0으로 간다.","확인":"25/2","스킬":"A5"}]},"ns-00482a43d9c0":{"길":"보기마다 반례 하나 또는 조임정리로 참과 거짓을 가린다","단계":[{"제목":"반례로 거짓인 ㄱ, ㄹ 가리기","힌트":"ㄱ은 곱이 0이 되는 계단 모양의 두 함수, ㄹ은 일차함수 두 개로 반례를 만들면?","식":["ㄱ은 $f(x)=1\\ (x\\ge 0),\\ 0\\ (x<0)$, $g(x)=0\\ (x\\ge 0),\\ 1\\ (x<0)$이면 $f(x)g(x)=0$","ㄹ은 $f(x)=x-a,\\ g(x)=x-b\\ (a\\ne b)$이면 $\\frac{f(x)}{g(x)}\\to 0$이지만 $g(x)\\to a-b\\ne 0$"],"설명":"ㄱ의 $f$, $g$는 $x=0$에서 좌극한과 우극한이 달라 극한이 없지만 곱은 항상 0이어서 극한이 존재한다. ㄹ은 $x\\to a$에서 $f\\to 0$이고 $\\frac{f}{g}\\to\\frac{0}{a-b}=0$인데 $g$는 0으로 가지 않는다. 둘 다 거짓이다.","확인":"2","스킬":"C3"},{"제목":"참인 ㄴ, ㅁ, ㅂ 확인","힌트":"ㄴ은 연속의 정의, ㅁ은 분자의 두 절댓값, ㅂ은 부등식을 극한으로 옮기면 각각 참인가?","식":["ㄴ은 $\\lim_{x\\to 0}\\left|f(x)\\right|=\\left|f(0)\\right|$","ㅁ은 $\\lim_{h\\to 0}\\frac{|h|-|-h|}{2h}=\\lim_{h\\to 0}\\frac{0}{2h}=0$","ㅂ은 $0<f(x)<g(x)$, $g(x)\\to 0$이므로 조임정리로 $f(x)\\to 0$"],"설명":"ㄴ은 $\\lim_{x\\to 0}f(x)=f(0)$이므로 절댓값을 씌워도 같은 값으로 간다. ㅁ은 $f(1+h)=|h|$, $f(1-h)=|-h|$이므로 분자가 항상 0이다. ㅂ은 $f(x)$가 0과 $g(x)$ 사이에 끼어 있다. 셋 모두 참이다.","확인":"3","스킬":"C3"},{"제목":"ㄷ의 참 거짓 판정","힌트":"$\\frac{f(2x)-f(x)}{x}$의 극한을 조건으로 구하고, 미분계수의 정의로도 나타내면?","식":["$-x^2\\le\\frac{f(2x)-f(x)}{x}\\le x^2$에서 $x\\to 0$이면 극한은 $0$","$\\frac{f(2x)-f(x)}{x}=2\\cdot\\frac{f(2x)-f(0)}{2x}-\\frac{f(x)-f(0)}{x}\\to f'(0)$","$f'(0)=0$"],"설명":"조건을 $x$로 나눈 식에 조임정리를 쓰면 가운데 식의 극한이 0이다. 한편 $f$가 $x=0$에서 미분가능하므로 가운데 식은 $2f'(0)-f'(0)=f'(0)$으로 수렴한다. 따라서 $f'(0)=0$이고 ㄷ은 참이다.","확인":null,"스킬":"D1","고비":true},{"제목":"참인 보기의 개수","힌트":"참인 보기를 모두 세면?","식":["ㄴ, ㄷ, ㅁ, ㅂ이 참이므로 $3+1=4$"],"설명":"ㄴ, ㅁ, ㅂ 세 개에 ㄷ 하나를 더한다.","확인":"4","스킬":"C3"}]},"ns-081eb7a5b5f3":{"길":"네 삼각형이 합동임을 이용해 f(t)를 t로 나타내고 극한을 구한다","단계":[{"제목":"네 삼각형의 합동","힌트":"곡선과 두 원은 원점을 중심으로 $90^\\circ$ 돌려도 겹친다. 네 삼각형의 넓이는 어떤 관계인가?","식":["$\\triangle\\mathrm{AJH}=\\triangle\\mathrm{BKC}=\\triangle\\mathrm{DLE}=\\triangle\\mathrm{FIG}$","$f(t)=4\\triangle\\mathrm{AJH}$"],"설명":"곡선 $|y|=\\frac{t}{|x|}$와 두 원은 원점을 중심으로 $90^\\circ$ 회전해도 자기 자신과 겹친다. 이 회전이 $\\triangle\\mathrm{AJH}$를 나머지 세 삼각형으로 차례로 옮기므로 네 삼각형은 합동이다.","확인":null,"스킬":"G10"},{"제목":"세 꼭짓점의 좌표","힌트":"A를 $\\left(a,\\frac{t}{a}\\right)$로 놓으면 H와 J의 좌표는?","식":["$\\mathrm{A}\\left(a,\\frac{t}{a}\\right),\\ \\mathrm{H}\\left(a,-\\frac{t}{a}\\right)$","$\\mathrm{J}\\left(0,\\sqrt{2-t}\\right)$"],"설명":"A는 곡선 위의 점이고 H는 A를 $x$축에 대해 대칭시킨 점이다. J는 반지름이 $\\sqrt{2-t}$인 원 $O_2$가 $y$축과 만나는 점이다.","확인":null,"스킬":"G10"},{"제목":"삼각형 AJH의 넓이","힌트":"밑변을 $\\overline{\\mathrm{AH}}$로 잡으면 높이는 무엇인가?","식":["$\\overline{\\mathrm{AH}}=\\frac{2t}{a}$, 높이는 $a$","$\\triangle\\mathrm{AJH}=\\frac{1}{2}\\cdot\\frac{2t}{a}\\cdot a=t$"],"설명":"$\\overline{\\mathrm{AH}}$는 $x$좌표가 $a$인 수직선 위에 있고 J는 $y$축 위에 있으므로 높이는 A의 $x$좌표의 절댓값 $a$이다. $a$가 약분되어 넓이는 $t$이다.","확인":null,"스킬":"G10","고비":true},{"제목":"극한값 계산","힌트":"$f(t)$를 $t$로 나타내고 $t\\to 2-$를 보내면?","식":["$f(t)=4t$","$\\lim_{t\\to 2-}f(t)=4\\cdot 2=8$"],"설명":"네 삼각형의 넓이가 모두 $t$이므로 $f(t)=4t$이다. 일차식이므로 $t=2$를 그대로 대입한다.","확인":"8","스킬":"G10"}]},"ns-095059f657b0":{"길":"접점 Q의 좌표를 구해 넓이비를 a/b로 바꾸고 극한을 구한다","단계":[{"제목":"접점 Q와 접선의 방정식","힌트":"Q$(a,b)$에서 원에 그은 접선의 방정식은?","식":["$a^2+b^2=\\frac{1}{2t^2}$","$ax+by=\\frac{1}{2t^2}$"],"설명":"원 $x^2+y^2=r^2$ 위의 점 $(a,b)$에서의 접선은 $ax+by=r^2$이다. 여기서 $r^2=\\frac{1}{2t^2}$이다.","확인":null,"스킬":"S5"},{"제목":"점 P를 대입해 a 구하기","힌트":"접선이 $\\mathrm{P}\\left(t+\\frac{1}{t},0\\right)$을 지난다. $a$는?","식":["$a\\cdot\\frac{t^2+1}{t}=\\frac{1}{2t^2}$","$a=\\frac{1}{2t\\left(t^2+1\\right)}$"],"설명":"P의 $y$좌표가 0이므로 $by$ 항이 사라지고 $a$만 남는다.","확인":null,"스킬":"S5","고비":true},{"제목":"b 구하기","힌트":"$b^2=\\frac{1}{2t^2}-a^2$을 정리하면?","식":["$b^2=\\frac{1}{2t^2}-\\frac{1}{4t^2\\left(t^2+1\\right)^2}=\\frac{2\\left(t^2+1\\right)^2-1}{4t^2\\left(t^2+1\\right)^2}$","$b=\\frac{\\sqrt{2t^4+4t^2+1}}{2t\\left(t^2+1\\right)}$"],"설명":"Q는 제1사분면의 점이므로 $b>0$이다. $2\\left(t^2+1\\right)^2-1=2t^4+4t^2+1$이다.","확인":null,"스킬":"S5"},{"제목":"넓이의 비를 a와 b로 나타내기","힌트":"$\\overline{\\mathrm{OR}}=\\overline{\\mathrm{OS}}=\\frac{1}{\\sqrt{2}t}$이다. $\\mathrm{A}(t)$와 $\\mathrm{B}(t)$를 $a$, $b$로 나타내면?","식":["$\\mathrm{A}(t)=\\frac{1}{2}\\cdot\\frac{1}{\\sqrt{2}t}\\cdot a,\\ \\mathrm{B}(t)=\\frac{1}{2}\\cdot\\frac{1}{\\sqrt{2}t}\\cdot b$","$\\frac{t^2\\mathrm{A}(t)}{\\mathrm{B}(t)}=\\frac{t^2a}{b}=\\frac{t^2}{\\sqrt{2t^4+4t^2+1}}$"],"설명":"삼각형 ORQ는 밑변 OR이 $y$축 위에 있어 높이가 Q의 $x$좌표 $a$이다. 삼각형 OQS는 밑변 OS가 $x$축 위에 있어 높이가 Q의 $y$좌표 $b$이다.","확인":null,"스킬":"G10"},{"제목":"극한값 계산","힌트":"분모를 $t^2$ 안으로 넣어 $t\\to\\infty$를 보내면?","식":["$\\frac{t^2}{\\sqrt{2t^4+4t^2+1}}=\\frac{1}{\\sqrt{2+\\frac{4}{t^2}+\\frac{1}{t^4}}}$","$\\to\\frac{1}{\\sqrt{2}}=\\frac{\\sqrt{2}}{2}$"],"설명":"$t>1$이므로 $t^2=\\sqrt{t^4}$이다. 분모와 분자를 $t^2$으로 나누면 $\\frac{1}{t^2}$ 꼴이 모두 0으로 간다.","확인":null,"스킬":"S5"}]},"ns-121a0f4bb705":{"길":"공통인수를 먼저 뽑아 f, g를 정하고 조건으로 계수를 구한다","단계":[{"제목":"공통근 찾기","힌트":"(나)에서 $h(a)=0$이면 $g(a)$는? (다)에서 극한이 존재하려면 $h(3)$은?","식":["$g(a)=f(a)h(a)=0,\\ f(a)=g(a)=0$","$h(3)=0,\\ g(3)=f(3)h(3)=0$"],"설명":"(가)에서 $g=fh$이므로 $h(a)=0$이면 $g(a)=0$이고 (나)에서 $f(a)=g(a)=0$이다. (다)는 $x\\to 3$일 때 분모가 0이므로 분자 $h(x)$도 0으로 가야 하고 $h$가 연속이므로 $h(3)=0$이다.","확인":null,"스킬":"D11"},{"제목":"f, g를 인수로 나타내기","힌트":"$g(x)=(x-a)(x-b)$, $f(x)=(x-a)\\left(x^2+px+q\\right)$로 놓으면 $h(x)$는?","식":["$h(x)=\\frac{g(x)}{f(x)}=\\frac{x-b}{x^2+px+q}$","$h(a)=0$이므로 $a-b=0$","$g(3)=0$이므로 $a=3,\\ g(x)=(x-3)^2$"],"설명":"$f$와 $g$가 모두 $x-a$를 인수로 가지므로 약분하면 $h(x)=\\frac{x-b}{x^2+px+q}$이다. $h$가 연속이므로 $h(a)$는 이 식의 값이고 0이 되려면 $b=a$이다.","확인":null,"스킬":"A4","고비":true},{"제목":"(다)로 3p+q 구하기","힌트":"$h(x)=\\frac{x-3}{x^2+px+q}$이다. $\\lim_{x\\to 3}\\frac{h(x)}{x-3}$를 계산하면?","식":["$\\lim_{x\\to 3}\\frac{h(x)}{x-3}=\\frac{1}{9+3p+q}=\\frac{1}{21}$","$3p+q=12$"],"설명":"$f(x)=(x-3)\\left(x^2+px+q\\right)$이므로 $h(x)=\\frac{(x-3)^2}{(x-3)\\left(x^2+px+q\\right)}=\\frac{x-3}{x^2+px+q}$이다. 따라서 $\\frac{h(x)}{x-3}=\\frac{1}{x^2+px+q}$이다.","확인":"12","스킬":"D3"},{"제목":"h(0)=-1로 p, q 구하기","힌트":"$h(0)=\\frac{-3}{q}=-1$에서 $q$를, 이어서 $p$를 구하면?","식":["$h(0)=\\frac{0-3}{q}=-1,\\ q=3$","$3p+3=12,\\ p=3$"],"설명":"$h(0)=-1$에서 $q$가 먼저 정해지고, 앞 단계의 $3p+q=12$에 대입하면 $p$가 정해진다.","확인":"3","스킬":"A3"},{"제목":"h(5) 계산","힌트":"$h(x)=\\frac{x-3}{x^2+3x+3}$에 $x=5$를 넣으면?","식":["$h(5)=\\frac{5-3}{25+15+3}=\\frac{2}{43}$"],"설명":"분모 $x^2+3x+3$은 판별식이 $9-12<0$이어서 항상 양수이므로 $h$는 실수 전체에서 연속이다.","확인":"2/43","스킬":"A3"}]},"ns-15120fa379aa":{"길":"B의 x좌표 a 하나로 r과 k를 나타내고 유리화로 극한을 구한다","단계":[{"제목":"B의 좌표로 r과 A 나타내기","힌트":"B$\\left(a,\\sqrt{3a}\\right)$가 원 위에 있다. $r$을 $a$로 나타내면?","식":["$a^2+3a=r^2$","$r=\\sqrt{a^2+3a},\\ \\mathrm{A}\\left(0,\\sqrt{a^2+3a}\\right)$"],"설명":"B는 원과 $y=\\sqrt{3x}$의 교점이므로 $x^2+y^2=r^2$에 $y=\\sqrt{3a}$를 넣는다. A는 원과 $y$축의 교점이므로 $y$좌표가 $r$이다. $r\\to 0+$이면 $a\\to 0+$이다.","확인":null,"스킬":"S4"},{"제목":"직선 AB의 x절편 k","힌트":"직선 AB를 $y$절편 $r$, $x$절편 $k$로 놓고 B를 대입하면 $k$는?","식":["$\\frac{x}{k}+\\frac{y}{r}=1$에 $\\mathrm{B}\\left(a,\\sqrt{3a}\\right)$를 대입","$\\frac{a}{k}+\\frac{\\sqrt{3a}}{r}=1,\\ k=\\frac{ar}{r-\\sqrt{3a}}$"],"설명":"직선 AB가 $\\mathrm{A}(0,r)$, $\\mathrm{C}(k,0)$을 지나므로 $\\frac{x}{k}+\\frac{y}{r}=1$로 쓸 수 있다. B를 넣어 $k$에 대해 푼다. $r^2=a^2+3a>3a$이므로 $r>\\sqrt{3a}$이고 $k>0$이다.","확인":null,"스킬":"S4","고비":true},{"제목":"분모의 유리화","힌트":"분모 $r-\\sqrt{3a}$에 켤레식을 곱하면 분모는?","식":["$r^2-3a=a^2$","$k=\\frac{ar\\left(r+\\sqrt{3a}\\right)}{a^2}=\\frac{r\\left(r+\\sqrt{3a}\\right)}{a}$"],"설명":"$a\\to 0+$이면 분모와 분자가 모두 0으로 가는 꼴이므로 켤레식 $r+\\sqrt{3a}$를 곱한다. $r^2=a^2+3a$이므로 $r^2-3a=a^2$이다.","확인":null,"스킬":"A5"},{"제목":"극한값 계산","힌트":"$r=\\sqrt{a}\\sqrt{a+3}$로 쓰고 $\\sqrt{a}$를 약분하면?","식":["$k=\\frac{\\sqrt{a}\\sqrt{a+3}\\cdot\\sqrt{a}\\left(\\sqrt{a+3}+\\sqrt{3}\\right)}{a}=\\sqrt{a+3}\\left(\\sqrt{a+3}+\\sqrt{3}\\right)$","$\\lim_{a\\to 0+}k=\\sqrt{3}\\left(\\sqrt{3}+\\sqrt{3}\\right)=6$"],"설명":"$r+\\sqrt{3a}=\\sqrt{a}\\left(\\sqrt{a+3}+\\sqrt{3}\\right)$이므로 분자에 $a$가 생겨 분모 $a$와 약분된다. 이제 $a=0$을 대입할 수 있다.","확인":"6","스킬":"A5"}]},"ns-15af65d32016":{"길":"T를 각 θ로 놓고 PQ와 PA를 cosθ로 나타낸다","단계":[{"제목":"P의 좌표와 PA","힌트":"T$(\\cos\\theta,\\sin\\theta)$로 놓으면 P의 좌표와 $t$는?","식":["$\\mathrm{T}(\\cos\\theta,\\ \\sin\\theta),\\ \\mathrm{P}(\\cos\\theta,\\ 0)$","$t=\\overline{\\mathrm{PA}}=1-\\cos\\theta$"],"설명":"T는 제1사분면에 있는 단위원 위의 점이다. P는 T에서 $x$축에 내린 수선의 발이므로 $x$좌표가 T와 같다.","확인":null,"스킬":"T5"},{"제목":"접선과 x축의 교점 Q","힌트":"점 T에서의 접선의 방정식에 $y=0$을 넣으면 Q의 $x$좌표는?","식":["$x\\cos\\theta+y\\sin\\theta=1$","$\\mathrm{Q}\\left(\\frac{1}{\\cos\\theta},\\ 0\\right)$"],"설명":"단위원 위의 점 $(\\cos\\theta,\\sin\\theta)$에서의 접선은 $x\\cos\\theta+y\\sin\\theta=1$이다. $y=0$이면 $x=\\frac{1}{\\cos\\theta}$이다.","확인":null,"스킬":"S5","고비":true},{"제목":"길이의 비를 cosθ로 나타내기","힌트":"$c=\\cos\\theta$로 놓고 $\\frac{\\overline{\\mathrm{PQ}}}{\\overline{\\mathrm{PA}}}$를 정리하면?","식":["$\\overline{\\mathrm{PQ}}=\\frac{1}{c}-c=\\frac{1-c^2}{c}$","$\\frac{\\overline{\\mathrm{PQ}}}{\\overline{\\mathrm{PA}}}=\\frac{1-c^2}{c(1-c)}=\\frac{1+c}{c}$"],"설명":"Q는 P보다 오른쪽에 있으므로 $\\overline{\\mathrm{PQ}}=\\frac{1}{c}-c$이다. $c<1$이므로 $1-c$로 약분할 수 있다.","확인":null,"스킬":"T5"},{"제목":"극한값 계산","힌트":"$t=1-c$이므로 $t\\to\\frac{1}{2}$일 때 $c$는? 그때 $\\frac{1+c}{c}$는?","식":["$c=1-t\\to\\frac{1}{2}$","$\\frac{1+c}{c}\\to\\frac{\\frac{3}{2}}{\\frac{1}{2}}=3$"],"설명":"$\\frac{1+c}{c}$는 $c=\\frac{1}{2}$에서 연속이므로 $c$의 극한값을 그대로 대입한다.","확인":"3","스킬":"T5"}]},"ns-185cceba37d5":{"길":"주기 4와 홀함수 성질로 모든 극한을 그림의 구간으로 옮겨 읽는다","단계":[{"제목":"주기와 대칭으로 구간 옮기기","힌트":"$f(x+4)=f(x)$와 $f(-x)=-f(x)$를 쓰면 $-2<x<0$에서 $f$는 어떻게 되는가?","식":["$-1<x<0$에서 $f(x)=-f(-x)=x$","$-2<x<-1$에서 $f(x)=-f(-x)=-x$","$f$, $g$는 모두 주기가 $4$이므로 $x$를 $x\\pm 4$로 옮겨 그림의 구간에서 읽는다"],"설명":"그림은 $0\\le x\\le 2$에서의 $f$와 $0\\le x\\le 4$에서의 $g$이다. $f$는 홀함수라서 음수 쪽은 $f(x)=-f(-x)$로 읽고, 나머지 구간은 주기 4로 옮겨 읽는다.","확인":null,"스킬":"T2"},{"제목":"ㄱ의 앞 극한","힌트":"$x\\to -1+$일 때 $f(x)$는 어느 값에 어느 쪽에서 가까워지는가? 그 값을 다시 $f$에 넣으면?","식":["$-1<x<0$에서 $f(x)=x$이므로 $f(x)\\to -1+$","$\\lim_{x\\to -1+}f(f(x))=\\lim_{y\\to -1+}f(y)=-1$"],"설명":"안쪽 함수의 값이 $-1$에 오른쪽에서 가까워지므로 바깥 함수는 $-1<y<0$에서의 식 $f(y)=y$를 따른다.","확인":"-1","스킬":"T6"},{"제목":"ㄱ의 뒤 극한과 판정","힌트":"$x\\to -2-$일 때 $x+4\\to 2-$이다. $g(x)$가 가까워지는 값과 방향을 읽고 $g$에 다시 넣으면?","식":["$g(x)=g(x+4)\\to 2+$","$\\lim_{x\\to -2-}g(g(x))=\\lim_{y\\to 2+}g(y)=3$","ㄱ의 좌변은 $-1+3=2\\ne 4$"],"설명":"그림에서 $x\\to 2-$일 때 $g(x)$는 2보다 큰 값에서 2로 가까워진다. $2<y<3$에서는 $g(y)=3$이다. ㄱ의 좌변이 4가 아니므로 ㄱ은 거짓이다.","확인":"2","스킬":"T6"},{"제목":"ㄴ의 좌극한과 우극한","힌트":"$x\\to 3+$와 $x\\to 3-$에서 $g(x)$는 각각 어떻게 되고, 그 값을 $f$에 넣으면?","식":["$x\\to 3+$이면 $g(x)\\to 1+$이므로 $f(g(x))\\to -1$","$x\\to 3-$이면 $g(x)=3$이므로 $f(g(x))=f(3)=f(-1)=-f(1)=-1$","좌극한과 우극한이 같으므로 ㄴ은 참"],"설명":"$1<y<2$에서 $f(y)=-y$이므로 $y\\to 1+$이면 $f(y)\\to -1$이다. $f(3)$은 주기 4로 $f(-1)$로 옮기고 홀함수 성질로 $-f(1)$로 바꾼다.","확인":null,"스킬":"T6"},{"제목":"ㄷ의 첫째 항과 둘째 항","힌트":"$x\\to -\\infty$이면 $k+\\frac{1}{x}\\to k-$이다. $k=1,2$일 때 $g(f(t))$의 극한은?","식":["$k=1$이면 $f(t)=t\\to 1-$이므로 $g(f(t))\\to 1$","$k=2$이면 $f(t)=-t\\to -2+$이므로 $g(f(t))=g(f(t)+4)\\to 3$"],"설명":"$k=1$이면 $t\\to 1-$에서 $f(t)\\to 1-$이고 $g(s)$는 $s\\to 1-$에서 1로 간다. $k=2$이면 $t\\to 2-$에서 $f(t)\\to -2+$이고, $g(s)=g(s+4)$에서 $s+4\\to 2+$이므로 $g=3$이다. 두 값의 합은 4이다.","확인":"4","스킬":"T2"},{"제목":"ㄷ의 셋째 항과 넷째 항","힌트":"$k=3,4$일 때 $t\\to k-$에서 $f(t)$를 주기로 옮겨 구하면?","식":["$k=3$이면 $f(t)=f(t-4)=-(t-4)\\to 1+$이므로 $g(f(t))\\to 1$","$k=4$이면 $f(t)=f(t-4)=t-4\\to 0-$이므로 $g(f(t))=g(f(t)+4)\\to 2$"],"설명":"$k=3$이면 $t-4\\in(-2,-1)$에서 $f=-x$ 꼴이므로 $f(t)\\to 1+$이고 $g$는 $s\\to 1+$에서 1로 간다. $k=4$이면 $t-4\\in(-1,0)$에서 $f(x)=x$이므로 $f(t)\\to 0-$이고, $g(s)=g(s+4)$에서 $s+4\\to 4-$이므로 $g=2$이다. 두 값의 합은 3이다.","확인":"3","스킬":"T2","고비":true},{"제목":"ㄷ의 판정과 선지 고르기","힌트":"네 항을 모두 더하면 ㄷ의 값은? 참인 보기는?","식":["ㄷ의 좌변은 $1+3+1+2=7$이므로 참","참인 보기는 ㄴ, ㄷ"],"설명":"ㄱ은 거짓이고 ㄴ, ㄷ은 참이다. 이와 같은 선지를 고른다.","확인":null,"스킬":"T2"}]},"ns-1ba53f2bb7ca":{"길":"부등식을 x²으로 나눠 a=10을 얻고 f, g를 정해 p의 범위를 구한다","단계":[{"제목":"f(x)의 꼴 정하기","힌트":"(가)에서 $x\\to 0+$일 때 $f(0)$은? (나)로 $f$의 차수와 최고차항의 계수는?","식":["$\\lim_{x\\to 0+}\\left(ax^2+4x\\right)=\\lim_{x\\to 0+}\\left(ax^2+5x\\right)=0$이므로 $f(0)=0$","$\\lim_{x\\to\\infty}\\frac{f(x)}{2x^2}=5$이므로 $f(x)=10x^2+px$"],"설명":"다항함수는 연속이므로 조임정리로 $f(0)=0$이다. $\\frac{f(x)}{2x^2}$이 0이 아닌 값 5로 수렴하므로 $f$는 이차이고 최고차항이 $10x^2$이다.","확인":null,"스킬":"C9"},{"제목":"g(x)의 꼴 정하기","힌트":"$\\lim_{x\\to 1}\\frac{g(x)}{x-1}=a$가 존재하려면 $g(1)$은? 그때 $g(x)$는?","식":["$g(1)=0,\\ g(x)=(x-1)(x-\\alpha)$","$\\lim_{x\\to 1}(x-\\alpha)=1-\\alpha=a$","$g(x)=(x-1)(x+a-1)$"],"설명":"분모가 0으로 가는데 극한이 존재하므로 분자 $g(x)$도 0으로 가야 한다. 따라서 $g(x)$는 $x-1$을 인수로 갖는다.","확인":null,"스킬":"D11"},{"제목":"조임정리로 a 구하기","힌트":"(가)에 $f(x)=10x^2+px$를 넣고 $x^2$으로 나눠 $x\\to\\infty$를 보내면 $a$는?","식":["$(p-5)x\\le(a-10)x^2\\le(p-4)x$에서 $\\frac{p-5}{x}\\le a-10\\le\\frac{p-4}{x}$","$x\\to\\infty$이면 $0\\le a-10\\le 0$이므로 $a=10$"],"설명":"$ax^2+4x\\le 10x^2+px$와 $10x^2+px\\le ax^2+5x$를 각각 정리해 합친 것이 위 식이다. $x>0$이므로 $x^2$으로 나눌 수 있고 양 끝이 모두 0으로 간다.","확인":"10","스킬":"C9","고비":true},{"제목":"p의 범위와 g(x) 구하기","힌트":"$a=10$을 (가)에 넣으면 $p$의 범위는? $g(x)$는?","식":["$10x^2+4x\\le 10x^2+px\\le 10x^2+5x$에서 $4\\le p\\le 5$","$g(x)=(x-1)(x+9)=x^2+8x-9$"],"설명":"$x>0$이므로 부등식을 $x$로 나누면 $4\\le p\\le 5$이다. $g(x)$에는 $a=10$을 넣는다.","확인":null,"스킬":"C9"},{"제목":"k의 범위와 M+N","힌트":"$\\lim_{x\\to\\infty}\\frac{f(x)-ax^2}{g(x)-x^2+5}$를 $p$로 나타내면? $M+N$은?","식":["$\\lim_{x\\to\\infty}\\frac{px}{8x-4}=\\frac{p}{8}=k$","$\\frac{4}{8}\\le k\\le\\frac{5}{8},\\ M+N=\\frac{9}{8}$"],"설명":"$f(x)-ax^2=px$이고 $g(x)-x^2+5=8x-4$이다. $4\\le p\\le 5$에서 $k$의 최솟값 $M=\\frac{1}{2}$, 최댓값 $N=\\frac{5}{8}$이 나온다.","확인":"9/8","스킬":"A3"}]},"ns-1e26047c9820":{"길":"분자와 분모의 차수를 비교해 삼차를 정하고 계수를 차례로 구한다","단계":[{"제목":"차수 비교로 n 정하기","힌트":"$f$가 $n$차이면 분모와 분자의 차수는 각각 몇 차인가?","식":["$x^3f(x)$는 $n+3$차","$\\left\\{f(x)\\right\\}^2-f\\left(x^2\\right)=\\left(a_n^2-a_n\\right)x^{2n}+\\cdots$는 $2n$차","$n+3=2n,\\ n=3$"],"설명":"최고차항의 계수 $a_n$이 0도 1도 아니므로 $a_n^2-a_n\\ne 0$이다. 극한이 0이 아닌 값 4로 수렴하려면 분자와 분모의 차수가 같아야 한다.","확인":"3","스킬":"A11","고비":true},{"제목":"최고차항의 계수 a3","힌트":"분자와 분모의 최고차항 계수의 비로 극한을 쓰면 $a_3$은?","식":["$\\lim_{x\\to\\infty}\\frac{\\left\\{f(x)\\right\\}^2-f\\left(x^2\\right)}{x^3f(x)}=\\frac{a_3^2-a_3}{a_3}=a_3-1=4$","$a_3=5$"],"설명":"차수가 같은 두 다항식의 비의 극한은 최고차항 계수의 비이다. 분자의 최고차항 계수는 $a_3^2-a_3$, 분모는 $a_3$이다.","확인":"5","스킬":"A11"},{"제목":"(나)로 나머지 계수 정하기","힌트":"$f(x)=5x^3+a_2x^2+a_1x+a_0$에서 $f'(x)$를 구하고 $\\lim_{x\\to 0}\\frac{f'(x)}{x}=2$를 쓰면 $a_2$는?","식":["$f'(x)=15x^2+2a_2x+a_1$","$f'(0)=a_1=0,\\ \\frac{f'(x)}{x}=15x+2a_2\\to 2a_2=2$","$a_2=1$"],"설명":"분모가 0으로 가는데 극한이 존재하므로 $f'(0)=0$이다. $a_1=0$이면 $\\frac{f'(x)}{x}=15x+2a_2$이고 $x\\to 0$에서 $2a_2$로 간다.","확인":"1","스킬":"D11"},{"제목":"미분계수 계산","힌트":"$f'(x)=15x^2+2x$에 $x=1$을 넣으면?","식":["$f'(1)=15+2=17$"],"설명":"$a_1=0$, $a_2=1$을 넣어 $f'(x)$를 완성한 뒤 $x=1$을 대입한다.","확인":"17","스킬":"D1"}]},"ns-1fcf4c967316":{"길":"중점 C와 점 D의 좌표로 f(t)를 t의 일차식으로 만들고 약분한다","단계":[{"제목":"선분 AB의 중점 C의 좌표","힌트":"A$(t,\\ \\sqrt{2}t)$, B$(2t,\\ 0)$의 중점의 좌표는?","식":["$\\frac{t+2t}{2}=\\frac{3}{2}t,\\ \\frac{\\sqrt{2}t+0}{2}=\\frac{\\sqrt{2}}{2}t$","$\\mathrm{C}\\left(\\frac{3}{2}t,\\ \\frac{\\sqrt{2}}{2}t\\right)$"],"설명":"중점의 좌표는 두 점의 좌표의 평균이다.","확인":null,"스킬":"S4"},{"제목":"직선 CD와 점 D의 좌표","힌트":"AB의 기울기가 $-\\sqrt{2}$이면 AB에 수직인 CD의 기울기는?","식":["AB의 기울기 $-\\sqrt{2}$, CD의 기울기 $\\frac{1}{\\sqrt{2}}$","$y=\\frac{1}{\\sqrt{2}}\\left(x-\\frac{3}{2}t\\right)+\\frac{\\sqrt{2}}{2}t$에 $x=2t$를 대입","$\\mathrm{D}\\left(2t,\\ \\frac{3\\sqrt{2}}{4}t\\right)$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$이다. 직선 CD가 점 C를 지나므로 $x=2t$일 때의 $y$좌표가 D의 $y$좌표이다.","확인":null,"스킬":"S4","고비":true},{"제목":"f(t)의 식","힌트":"C와 D의 $x$좌표의 차와 $y$좌표의 차로 거리를 구하면?","식":["$f(t)=\\sqrt{\\left(\\frac{t}{2}\\right)^{2}+\\left(\\frac{\\sqrt{2}}{4}t\\right)^{2}}=\\sqrt{\\frac{3}{8}t^{2}}$","$f(t)=\\frac{\\sqrt{6}}{4}t$"],"설명":"$x$좌표의 차는 $\\frac{t}{2}$, $y$좌표의 차는 $\\frac{3\\sqrt{2}}{4}t-\\frac{\\sqrt{2}}{2}t=\\frac{\\sqrt{2}}{4}t$이다. $t>0$이므로 $\\sqrt{t^{2}}=t$이다.","확인":null,"스킬":"S4"},{"제목":"분자의 인수분해와 극한","힌트":"$f(t)-\\frac{\\sqrt{6}}{2}$를 $t-2$로 묶으면?","식":["$f(t)-\\frac{\\sqrt{6}}{2}=\\frac{\\sqrt{6}}{4}(t-2)$","$\\lim_{t\\to2}\\frac{\\frac{\\sqrt{6}}{4}(t-2)}{(t-2)(t+2)}=\\frac{\\sqrt{6}}{4}\\cdot\\frac{1}{4}=\\frac{\\sqrt{6}}{16}$"],"설명":"$\\frac{\\sqrt{6}}{2}=\\frac{\\sqrt{6}}{4}\\cdot2$이므로 분자가 $t-2$를 인수로 갖는다. $t\\neq2$에서 약분한 뒤 $t\\to2$를 대입한다.","확인":null,"스킬":"D11"}]},"ns-2009cc3815d9":{"길":"P를 (t, 1-t)로 놓고 내접 조건으로 PQ를 구해 유리화한다","단계":[{"제목":"P의 좌표와 선분 PA의 길이","힌트":"P가 직선 $y=-x+1$ 위의 점이므로 $x$좌표를 $t$로 두면 P의 좌표는?","식":["$\\mathrm{P}(t,\\ 1-t),\\ \\mathrm{A}(1,\\ 0)$","$\\overline{\\mathrm{PA}}=\\sqrt{(1-t)^{2}+(1-t)^{2}}=\\sqrt{2}(1-t)$"],"설명":"직선이 $x$축과 만나는 점이 A이므로 $\\mathrm{A}(1,0)$이다. P는 선분 AB 위이므로 $0<t<1$이고 $1-t>0$이다.","확인":null,"스킬":"S4"},{"제목":"내접하는 두 원에서 PQ의 길이","힌트":"P를 중심으로 하는 원이 원 $x^{2}+y^{2}=1$에 안쪽에서 접할 때 O, P, Q의 위치 관계는?","식":["O, P, Q는 한 직선 위이고 $\\overline{\\mathrm{PQ}}=1-\\overline{\\mathrm{OP}}$","$\\overline{\\mathrm{PQ}}=1-\\sqrt{t^{2}+(1-t)^{2}}=1-\\sqrt{2t^{2}-2t+1}$"],"설명":"두 원이 접하면 두 중심과 접점은 한 직선 위에 있다. $\\overline{\\mathrm{OQ}}=1$이고 P가 원 안에 있으므로 $\\overline{\\mathrm{PQ}}=\\overline{\\mathrm{OQ}}-\\overline{\\mathrm{OP}}$이다.","확인":null,"스킬":"S5","고비":true},{"제목":"분모의 유리화와 극한","힌트":"분모 $1-\\sqrt{2t^{2}-2t+1}$에 켤레식을 곱하면 분모는?","식":["$\\frac{\\sqrt{2}(1-t)}{1-\\sqrt{2t^{2}-2t+1}}=\\frac{\\sqrt{2}(1-t)\\left(1+\\sqrt{2t^{2}-2t+1}\\right)}{2t(1-t)}$","$\\alpha=\\lim_{t\\to1-}\\frac{\\sqrt{2}\\left(1+\\sqrt{2t^{2}-2t+1}\\right)}{2t}=\\sqrt{2}$"],"설명":"P가 A에 가까워지면 $t\\to1-$이고 분모와 분자가 모두 $0$으로 간다. 켤레식을 곱하면 분모가 $1-(2t^{2}-2t+1)=2t(1-t)$가 되어 $1-t$가 약분된다.","확인":null,"스킬":"A5"},{"제목":"$10\\alpha^{2}$의 값","힌트":"$\\alpha=\\sqrt{2}$일 때 $10\\alpha^{2}$은?","식":["$10\\alpha^{2}=10\\times(\\sqrt{2})^{2}=20$"],"설명":"$\\alpha^{2}=2$이므로 $10\\alpha^{2}=20$이다.","확인":"20","스킬":"A5"}]},"ns-24074ad8f705":{"길":"QO=QP를 식으로 써서 q를 t로 나타내고 극한을 취한다","단계":[{"제목":"P, Q의 좌표와 QO=QP","힌트":"P$\\left(t,\\ \\frac{3}{4}t^{2}\\right)$, Q$(0,\\ q)$일 때 원의 반지름 $\\overline{\\mathrm{QO}}$, $\\overline{\\mathrm{QP}}$를 식으로 쓰면?","식":["$\\mathrm{P}\\left(t,\\ \\frac{3}{4}t^{2}\\right),\\ \\mathrm{Q}(0,\\ q)$","$q^{2}=t^{2}+\\left(\\frac{3}{4}t^{2}-q\\right)^{2}$"],"설명":"원이 O와 P를 지나므로 중심 Q에서 두 점까지의 거리가 같다. $\\overline{\\mathrm{QO}}^{2}=q^{2}$이고 $\\overline{\\mathrm{QP}}^{2}=t^{2}+\\left(\\frac{3}{4}t^{2}-q\\right)^{2}$이다.","확인":null,"스킬":"S4"},{"제목":"q를 t로 나타내기","힌트":"우변을 전개하면 양변의 $q^{2}$이 없어진다. $q$에 대해 풀면?","식":["$0=t^{2}+\\frac{9}{16}t^{4}-\\frac{3}{2}t^{2}q$","$q=\\frac{2}{3}+\\frac{3}{8}t^{2}$"],"설명":"전개하면 $q^{2}$이 소거되어 $q$의 일차식이 된다. P가 원점이 아니므로 $t\\neq0$이고, $t^{2}$으로 나누어 정리한다.","확인":null,"스킬":"S4","고비":true},{"제목":"P→O일 때 a의 값","힌트":"P가 O에 가까워지면 $t$는 어디로 가는가?","식":["$a=\\lim_{t\\to0}\\left(\\frac{2}{3}+\\frac{3}{8}t^{2}\\right)=\\frac{2}{3}$"],"설명":"P가 곡선을 따라 O에 가까워지면 $t\\to0$이고, Q의 $y$좌표 $q$는 $a$에 가까워진다.","확인":"2/3","스킬":"S4"}]},"ns-28e89449b4d7":{"길":"보기마다 극한이 0이거나 발산하는 경우를 따져 참과 거짓을 가린다","단계":[{"제목":"ㄱ의 참 거짓 판정","힌트":"$\\lim f(x)=0$인 경우를 생각하면 $g(x)$의 극한에 대해 무엇을 알 수 있는가?","식":["$\\lim_{x\\to a}f(x)=0$이면 $\\lim_{x\\to a}f(x)g(x)=0$이 되어도 $g(x)$는 발산할 수 있다.","ㄱ은 거짓"],"설명":"$f(x)$가 $0$으로 가면 곱의 극한은 $g(x)$의 극한과 관계없이 존재할 수 있다. 그래서 $\\lim g(x)$의 존재를 보장하지 못한다.","확인":null,"스킬":"C3"},{"제목":"ㄴ의 참 거짓 판정","힌트":"$\\frac{f(x)}{g(x)}=h(x)$로 놓으면 $f(x)$를 $g(x)$와 $h(x)$로 어떻게 나타내는가?","식":["$\\lim_{x\\to a}g(x)=\\alpha,\\ \\lim_{x\\to a}\\frac{f(x)}{g(x)}=\\beta$","$f(x)=g(x)h(x)$이므로 $\\lim_{x\\to a}f(x)=\\alpha\\beta$","ㄴ은 참"],"설명":"극한값이 존재하는 두 함수의 곱의 극한은 각 극한값의 곱이다. $f(x)=g(x)h(x)$로 쓰면 $f(x)$의 극한이 존재한다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄷ, ㄹ의 반례와 옳은 보기 고르기","힌트":"ㄷ, ㄹ의 조건을 만족하면서 극한이 존재하지 않는 함수를 만들 수 있는가?","식":["ㄷ: $f(x)=(x-a)^{2}+\\frac{1}{x-a},\\ g(x)=x-a+\\frac{1}{x-a}$이면 $f(x)-g(x)=(x-a)^{2}-(x-a)\\to0$이나 $f$, $g$는 발산","ㄹ: $f(x)=\\frac{1}{|x-a|}-|x-a|,\\ g(x)=\\frac{1}{|x-a|},\\ h(x)=\\frac{1}{|x-a|}+|x-a|$이면 $f<g<h$이고 $h-f=2|x-a|\\to0$이나 $g$는 발산","옳은 것은 ㄴ뿐"],"설명":"ㄷ은 차의 극한이 $0$이어도 두 함수가 각각 발산할 수 있다. ㄹ은 $f$와 $h$가 함께 발산하면 그 사이의 $g$도 발산할 수 있다. $x=a$ 에서의 값은 $f<g<h$ 가 되게 따로 정한다. 따라서 옳은 것은 ㄴ뿐이다.","확인":null,"스킬":"C3"}]},"ns-3287f5ea1d1f":{"길":"각 보기마다 1/x 꼴이나 구간별 함수로 반례를 만들어 옳은 것의 개수를 센다","단계":[{"제목":"ㄱ, ㄷ의 반례","힌트":"$\\frac{1}{x}$ 꼴 함수로 조건을 만족하면서 극한이 존재하지 않는 경우를 만들면?","식":["ㄱ: $f(x)=\\frac{1}{x},\\ g(x)=-\\frac{1}{x}$이면 $\\lim_{x\\to0}\\{f(x)+g(x)\\}=0$이나 $f$, $g$는 발산","ㄷ: $f(x)=x,\\ g(x)=\\frac{1}{x}$이면 $\\lim_{x\\to0}f(x)g(x)=1$이나 $g$는 발산"],"설명":"ㄱ은 합의 극한이 있어도 각각은 발산할 수 있다. ㄷ은 $f$의 극한과 곱의 극한이 있어도 $g$가 발산할 수 있다. 둘 다 거짓이다.","확인":null,"스킬":"C3"},{"제목":"ㄴ의 반례","힌트":"$f$가 발산하는데도 $\\frac{g(x)}{f(x)}$의 극한이 존재하는 경우를 만들면?","식":["$g(x)=x,\\ f(x)=\\frac{1}{x}$","$\\lim_{x\\to0}g(x)=0,\\ \\lim_{x\\to0}\\frac{g(x)}{f(x)}=\\lim_{x\\to0}x^{2}=0$이나 $f$는 발산"],"설명":"$\\frac{g(x)}{f(x)}=x^{2}$이므로 두 조건이 모두 성립하지만 $f(x)=\\frac{1}{x}$는 $x\\to0$에서 극한이 없다. ㄴ은 거짓이다.","확인":null,"스킬":"C3"},{"제목":"ㄹ의 반례","힌트":"$x=0$의 좌우에서 $f(x)$의 값이 달라도 $f(f(f(x)))$의 극한이 존재하게 만들면?","식":["$f(x)=\\begin{cases}1&(x\\ge0)\\\\-2x-1&(x<0)\\end{cases}$","$x\\to0+$: $f(f(f(x)))=1$, $x\\to0-$: $f(x)\\to-1,\\ f(f(x))\\to1,\\ f(f(f(x)))=1$","$\\lim_{x\\to0}f(f(f(x)))=1$이나 $\\lim_{x\\to0}f(x)$는 좌극한 $-1$, 우극한 $1$"],"설명":"$x<0$이면 $f(x)$는 $-1$ 근처의 음수이고 $f(f(x))$는 $1$ 근처의 양수가 되어, 한 번 더 $f$를 취하면 $1$이다. 양쪽 극한이 같아 합성의 극한은 존재하지만 $f$ 자체의 극한은 없다.","확인":"1","스킬":"C3","고비":true},{"제목":"옳은 보기의 개수","힌트":"네 보기 중 반례가 없는 것은 몇 개인가?","식":["ㄱ, ㄴ, ㄷ, ㄹ 모두 거짓","옳은 것은 $0$개"],"설명":"네 보기 모두 반례가 있으므로 옳은 것은 하나도 없다.","확인":"0","스킬":"C3"}]},"ns-33cfa3e7bdc0":{"길":"f(3)=0으로 f를 정하고 g에서 (x-3)을 차례로 뽑아 계수를 구한다","단계":[{"제목":"f(x)의 꼴 정하기","힌트":"$g(3)=0$이므로 $f(3)\\neq0$이면 (나)의 극한값은 얼마가 되는가?","식":["$f(3)\\neq0$이면 $\\lim=\\frac{f(3)-0}{f(3)+0}=1\\neq\\frac{1}{2}$이므로 $f(3)=0$","$f(x)=(x-3)(x+k)$에서 $D=(k+3)^{2}\\le0$, $k=-3$"],"설명":"(가)에서 모든 실수 $x$에 대해 $f(x)\\ge0$이므로 판별식 $D\\le0$이다. $f(x)=x^{2}+(k-3)x-3k$이므로 $D=(k-3)^{2}+12k=(k+3)^{2}$이고 $f(x)=(x-3)^{2}$이다.","확인":"-3","스킬":"A4"},{"제목":"Q(3)=0 알아내기","힌트":"$g(x)=(x-3)Q(x)$로 놓고 약분한 뒤 $Q(3)\\neq0$이면 극한값은?","식":["$\\lim_{x\\to3}\\frac{(x-3)^{2}-(x-3)Q(x)}{(x-3)^{2}+(x-3)Q(x)}=\\lim_{x\\to3}\\frac{(x-3)-Q(x)}{(x-3)+Q(x)}$","$Q(3)\\neq0$이면 극한값이 $-1$이므로 $Q(3)=0$"],"설명":"분모와 분자를 $(x-3)$으로 약분하면 $x=3$을 대입할 수 있다. $Q(3)\\neq0$이면 값이 $\\frac{-Q(3)}{Q(3)}=-1$이 되어 $\\frac{1}{2}$이 될 수 없다.","확인":"0","스킬":"D11","고비":true},{"제목":"Q(x)의 꼴과 m의 값","힌트":"$Q(x)=(x-3)(x+m)$으로 놓고 약분하면 극한은 $m$의 식으로 어떻게 되는가?","식":["$\\lim_{x\\to3}\\frac{1-(x+m)}{1+(x+m)}=\\frac{-2-m}{4+m}=\\frac{1}{2}$","$m=-\\frac{8}{3}$"],"설명":"$Q(3)=0$이므로 $Q(x)$는 $(x-3)$을 인수로 가진다. 한 번 더 약분한 뒤 $x=3$을 대입해 $m$에 대한 식을 푼다.","확인":"-8/3","스킬":"D11"},{"제목":"g(4)의 값","힌트":"$g(x)=(x-3)^{2}\\left(x-\\frac{8}{3}\\right)$에 $x=4$를 대입하면?","식":["$g(x)=(x-3)^{2}\\left(x-\\frac{8}{3}\\right)$","$g(4)=1^{2}\\cdot\\frac{4}{3}=\\frac{4}{3}$"],"설명":"$g(x)=(x-3)Q(x)=(x-3)^{2}(x+m)$이고 $m=-\\frac{8}{3}$이다. 최고차항의 계수가 $1$인 삼차함수이다.","확인":"4/3","스킬":"A4"}]},"ns-356ff925d23b":{"길":"OQ=OP로 Q를 t로 나타내고 직선 PQ의 y절편을 유리화한다","단계":[{"제목":"점 P, Q의 좌표","힌트":"P$(t,\\ 2t^{2})$일 때 $\\overline{\\mathrm{OP}}$를 구해 Q의 $x$좌표로 쓰면?","식":["$\\overline{\\mathrm{OP}}=\\sqrt{t^{2}+4t^{4}}=t\\sqrt{1+4t^{2}}$","$\\mathrm{Q}\\left(t\\sqrt{1+4t^{2}},\\ 0\\right)$"],"설명":"Q는 $x$축의 양의 부분 위에 있고 $\\overline{\\mathrm{OQ}}=\\overline{\\mathrm{OP}}$이므로 Q의 $x$좌표가 $\\overline{\\mathrm{OP}}$이다. $t>0$이다.","확인":null,"스킬":"S4"},{"제목":"직선 PQ와 R의 y좌표","힌트":"R은 직선 PQ가 $y$축과 만나는 점이다. 직선 PQ의 식에 $x=0$을 넣으면?","식":["직선 PQ의 기울기 $\\frac{0-2t^{2}}{t\\sqrt{1+4t^{2}}-t}=-\\frac{2t}{\\sqrt{1+4t^{2}}-1}$","R의 $y$좌표 $=\\frac{2t^{2}\\sqrt{1+4t^{2}}}{\\sqrt{1+4t^{2}}-1}$"],"설명":"직선 PQ가 Q를 지나므로 $y=m\\left(x-t\\sqrt{1+4t^{2}}\\right)$이다. $x=0$을 넣으면 $y=-m\\,t\\sqrt{1+4t^{2}}$이다.","확인":null,"스킬":"S4","고비":true},{"제목":"분모의 유리화","힌트":"분모 $\\sqrt{1+4t^{2}}-1$에 켤레식을 곱하면 분모는?","식":["$\\frac{2t^{2}\\sqrt{1+4t^{2}}\\left(\\sqrt{1+4t^{2}}+1\\right)}{\\left(1+4t^{2}\\right)-1}=\\frac{2t^{2}\\sqrt{1+4t^{2}}\\left(\\sqrt{1+4t^{2}}+1\\right)}{4t^{2}}$","$=\\frac{\\sqrt{1+4t^{2}}\\left(\\sqrt{1+4t^{2}}+1\\right)}{2}$"],"설명":"$t\\to0$이면 분모와 분자가 모두 $0$으로 가므로 켤레식을 곱한다. 분모가 $4t^{2}$이 되어 $t^{2}$이 약분된다.","확인":null,"스킬":"A5"},{"제목":"극한값 k","힌트":"$t\\to0$이면 $\\sqrt{1+4t^{2}}$는 어떤 값에 가까워지는가?","식":["$k=\\lim_{t\\to0}\\frac{\\sqrt{1+4t^{2}}\\left(\\sqrt{1+4t^{2}}+1\\right)}{2}=\\frac{1\\cdot2}{2}=1$"],"설명":"P가 O에 가까워지면 $t\\to0$이고 $\\sqrt{1+4t^{2}}\\to1$이다.","확인":"1","스킬":"A5"}]},"ns-3648caf2e597":{"길":"보기마다 극한의 차 성질로 보이거나 반례를 만들어 가린다","단계":[{"제목":"ㄱ의 판정","힌트":"$g(x)$를 $f(x)$와 $f(x)-g(x)$로 나타내면?","식":["$g(x)=f(x)-\\{f(x)-g(x)\\}$","$\\lim_{x\\to0}g(x)=\\lim_{x\\to0}f(x)-\\lim_{x\\to0}\\{f(x)-g(x)\\}$","ㄱ은 참"],"설명":"극한값이 존재하는 두 함수의 차의 극한도 존재한다. 따라서 $g(x)$의 극한이 존재한다.","확인":null,"스킬":"C3"},{"제목":"ㄴ의 판정","힌트":"$x\\to0$에서 $\\frac{x}{g(x)}$, $\\frac{f(x)}{g(x)}$가 수렴하는데 $f(x)$는 발산하는 경우가 있는가?","식":["$f(x)=g(x)=\\frac{1}{x}$이면 $\\lim_{x\\to0}\\frac{x}{g(x)}=\\lim_{x\\to0}x^{2}=0$, $\\lim_{x\\to0}\\frac{f(x)}{g(x)}=1$","$\\lim_{x\\to0}f(x)$는 발산하므로 ㄴ은 거짓"],"설명":"$g(x)$가 $0$으로 갈 때는 분모가 $0$으로 가므로 $f(x)$의 극한을 알 수 없다. 반례 하나로 거짓임을 보인다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄷ의 판정과 선지 고르기","힌트":"$f(x)=x$일 때 $g(x)$가 발산해도 두 조건이 성립하는가?","식":["$f(x)=x,\\ g(x)=\\frac{1}{x}$이면 $\\lim_{x\\to0}\\frac{f(x)}{x}=1$, $\\lim_{x\\to0}f(x)g(x)=1$","$\\lim_{x\\to0}g(x)$는 발산하므로 ㄷ은 거짓, 옳은 것은 ㄱ뿐"],"설명":"$f(x)$가 $0$으로 가면 곱 $f(x)g(x)$는 $g(x)$가 발산해도 수렴할 수 있다.","확인":null,"스킬":"C3"}]},"ns-36b55f5b196d":{"길":"원의 반지름과 직각삼각형 APH로 b²을 a의 식으로 나타낸다","단계":[{"제목":"반지름과 세 선분의 길이","힌트":"$y$축에 접하는 원의 반지름이 $a$이면 $\\overline{\\mathrm{PA}}$와 $\\overline{\\mathrm{AH}}$는?","식":["P를 중심으로 하는 원의 반지름은 $a$","$\\overline{\\mathrm{PA}}=a+1,\\ \\overline{\\mathrm{PH}}=b,\\ \\overline{\\mathrm{AH}}=4-a$"],"설명":"$y$축에 접하는 원의 반지름은 중심의 $x$좌표 $a$이다. 두 원이 외접하므로 중심 사이의 거리는 반지름의 합 $a+1$이다. H는 $(a,\\ 0)$이다.","확인":null,"스킬":"S5"},{"제목":"직각삼각형 APH로 b²을 구하기","힌트":"직각삼각형 APH에서 빗변 PA로 피타고라스 정리를 쓰면?","식":["$b^{2}+(4-a)^{2}=(a+1)^{2}$","$b^{2}=10a-15$"],"설명":"$a^{2}-8a+16+b^{2}=a^{2}+2a+1$에서 $a^{2}$이 소거되어 $b^{2}$이 $a$의 일차식이 된다.","확인":null,"스킬":"S3","고비":true},{"제목":"극한값 계산","힌트":"$b\\to\\infty$이면 $a$는 어떻게 되는가?","식":["$b^{2}=10a-15$이므로 $b\\to\\infty$이면 $a\\to\\infty$","$\\lim_{a\\to\\infty}\\frac{10a-15}{a+1}=10$"],"설명":"$\\overline{\\mathrm{PH}}^{2}=b^{2}=10a-15$이고 $\\overline{\\mathrm{PA}}=a+1$이다. 분모와 분자를 $a$로 나누면 $\\frac{10-\\frac{15}{a}}{1+\\frac{1}{a}}$이다.","확인":"10","스킬":"S3"}]},"ns-3792142ee671":{"길":"a, b가 1인지 아닌지로 경우를 나누어 극한이 존재하는 순서쌍을 찾는다","단계":[{"제목":"a≠1, b≠1인 경우","힌트":"$a\\neq1$, $b\\neq1$이면 $x=1$에서 분모가 $0$인가?","식":["$\\lim_{x\\to1}\\frac{2x^{2}-3x+a}{(x-a)(x-b)}=\\frac{a-1}{(1-a)(1-b)}=\\frac{1}{b-1}$","$\\frac{1}{b-1}=c$에서 $b=2,\\ c=1,\\ a=0,\\ 2,\\ 3,\\ 4$","$a+b+c=3,\\ 5,\\ 6,\\ 7$"],"설명":"분모가 $0$이 아니므로 $x=1$을 그대로 대입한다. $\\frac{1}{b-1}$이 정수이면 $b-1=\\pm1$이고, $c\\ge0$이므로 $b-1=1$이다.","확인":null,"스킬":"C2","고비":true},{"제목":"a=1, b≠1인 경우","힌트":"$a=1$이면 분자 $2x^{2}-3x+1$을 인수분해하면?","식":["$\\frac{2x^{2}-3x+1}{(x-1)(x-b)}=\\frac{(x-1)(2x-1)}{(x-1)(x-b)}$","$\\lim_{x\\to1}\\frac{2x-1}{x-b}=\\frac{1}{1-b}=c$에서 $b=0,\\ c=1$","$a+b+c=2$"],"설명":"분자가 $x-1$을 인수로 가져 약분된다. $\\frac{1}{1-b}$이 $0$ 이상의 정수이면 $1-b=1$이다.","확인":"2","스킬":"C2"},{"제목":"b=1인 경우","힌트":"$b=1$이면 $x\\to1$일 때 분모는 어떻게 되는가?","식":["$a\\neq1$: 분모 $\\to0$이므로 분자 $\\to0$이어야 하고, $-1+a=0$에서 $a=1$이라 모순","$a=1$: $\\lim_{x\\to1}\\frac{2x-1}{x-1}=\\lim_{x\\to1}\\left(2+\\frac{1}{x-1}\\right)$은 발산"],"설명":"$b=1$이면 분모가 $x\\to1$에서 $0$으로 가므로 극한이 존재하려면 분자도 $0$으로 가야 한다. 두 경우 모두 조건을 만족하지 못한다.","확인":null,"스킬":"D11"},{"제목":"최댓값과 최솟값의 합","힌트":"가능한 $a+b+c$의 값 중 가장 큰 값과 가장 작은 값은?","식":["가능한 $a+b+c$의 값 $2,\\ 3,\\ 5,\\ 6,\\ 7$","최댓값 $7$, 최솟값 $2$이므로 합은 $9$"],"설명":"세 경우에서 나온 값을 모두 모아 비교한다.","확인":"9","스킬":"C2"}]},"ns-391bc7bb4248":{"길":"OQ=OP로 Q를 t로 나타내고 직선 PQ의 y절편을 유리화해 극한을 구한다","단계":[{"제목":"점 P, Q의 좌표","힌트":"P$(t,\\ 3t^{2})$일 때 $\\overline{\\mathrm{OP}}$를 구해 Q의 $x$좌표로 쓰면?","식":["$\\overline{\\mathrm{OP}}=\\sqrt{t^{2}+9t^{4}}=t\\sqrt{1+9t^{2}}$","$\\mathrm{Q}\\left(t\\sqrt{1+9t^{2}},\\ 0\\right)$"],"설명":"Q는 $x$축 위에 있고 $\\overline{\\mathrm{OQ}}=\\overline{\\mathrm{OP}}$이다. 그림에서 Q는 $x$축의 양의 부분에 있으므로 Q의 $x$좌표는 $t\\sqrt{1+9t^{2}}$이다.","확인":null,"스킬":"S4"},{"제목":"직선 PQ와 R의 y좌표","힌트":"직선 PQ의 식에 $x=0$을 넣으면 R의 $y$좌표는?","식":["$y-3t^{2}=-\\frac{3t^{2}}{t\\sqrt{1+9t^{2}}-t}(x-t)$","$x=0$이면 $y=3t^{2}+\\frac{3t^{2}}{\\sqrt{1+9t^{2}}-1}$"],"설명":"점 P를 지나고 기울기가 $m$인 직선에 $x=0$을 넣으면 $y=3t^{2}-mt$이다. $m=-\\frac{3t^{2}}{t\\sqrt{1+9t^{2}}-t}$이므로 $-mt=\\frac{3t^{2}}{\\sqrt{1+9t^{2}}-1}$이다.","확인":null,"스킬":"S4","고비":true},{"제목":"유리화와 극한","힌트":"$\\frac{3t^{2}}{\\sqrt{1+9t^{2}}-1}$의 분모에 켤레식을 곱하면?","식":["$\\frac{3t^{2}}{\\sqrt{1+9t^{2}}-1}=\\frac{3t^{2}\\left(\\sqrt{1+9t^{2}}+1\\right)}{9t^{2}}=\\frac{\\sqrt{1+9t^{2}}+1}{3}$","$f(t)=3t^{2}+\\frac{\\sqrt{1+9t^{2}}+1}{3}\\to\\frac{2}{3}\\ (t\\to0)$","R이 가까워지는 점은 $\\left(0,\\ \\frac{2}{3}\\right)$"],"설명":"$t\\to0$에서 분모와 분자가 모두 $0$으로 가므로 켤레식을 곱한다. 분모가 $9t^{2}$이 되어 $t^{2}$이 약분된다.","확인":null,"스킬":"A5"}]},"ns-3ba495742ddf":{"길":"주기 4로 조건을 만족하는 n의 꼴을 정하고 100 이하의 합을 구한다","단계":[{"제목":"한 주기에서 조건을 만족하는 n","힌트":"그래프에서 $n=0,\\ \\pm1,\\ \\pm2$의 좌극한과 우극한의 절댓값의 합을 구하면?","식":["$n=\\pm1$: $|-1|+|-1|=2,\\ |1|+|1|=2$","$n=\\pm2$: $|1|+|-1|=2$","$n=0$: $|0|+|0|=0\\neq2$"],"설명":"$n=2$의 극한은 주기 $4$로 $n=-2$에서 읽는다. $x\\to-2-$와 $x\\to2-$의 극한은 $1$이고 $x\\to-2+$와 $x\\to2+$의 극한은 $-1$이다.","확인":null,"스킬":"T2","고비":true},{"제목":"자연수 n의 꼴","힌트":"$f(x+4)=f(x)$이면 조건을 만족하는 $n$에 $4$를 더해도 조건이 유지되는가?","식":["조건을 만족하는 $n$: $-2,\\ -1,\\ 1,\\ 2$이므로 $4$로 나눈 나머지가 $1,\\ 2,\\ 3$","$n=4k-3,\\ 4k-2,\\ 4k-1$ ($k=1,\\ 2,\\ \\cdots,\\ 25$)"],"설명":"주기가 $4$이므로 $n$에 $4$를 더해도 극한이 같다. $-1$은 $3$과 같은 위치이고 $0$과 같은 위치인 $4$의 배수는 조건을 만족하지 않는다. $100$ 이하이므로 $k$는 $25$까지이다.","확인":null,"스킬":"T2"},{"제목":"조건을 만족하는 n의 합","힌트":"세 꼴의 합을 시그마로 나타내면?","식":["$\\sum_{k=1}^{25}(4k-3)+\\sum_{k=1}^{25}(4k-2)+\\sum_{k=1}^{25}(4k-1)=12\\sum_{k=1}^{25}k-150$","$=12\\cdot325-150=3750$"],"설명":"세 시그마를 합하면 $4k$가 세 번 더해져 $12k$가 되고, 상수항은 $-(3+2+1)\\times25=-150$이다. $\\sum_{k=1}^{25}k=325$이다.","확인":"3750","스킬":"P6"}]},"ns-3fa58b707d1a":{"길":"접선의 방정식에 P를 대입해 Q의 x좌표를 구하고 넓이를 식으로 쓴다","단계":[{"제목":"접점 Q의 x좌표","힌트":"Q$(x_{1},\\ y_{1})$에서 원 $x^{2}+y^{2}=t$의 접선의 방정식은?","식":["접선 $x_{1}x+y_{1}y=t$","P$\\left(t+\\frac{1}{t},\\ 0\\right)$를 대입: $x_{1}\\left(t+\\frac{1}{t}\\right)=t$","$x_{1}=\\frac{t^{2}}{t^{2}+1}$"],"설명":"원 $x^{2}+y^{2}=t$ 위의 점 $(x_{1},\\ y_{1})$에서의 접선은 $x_{1}x+y_{1}y=t$이다. 접선이 $x$축 위의 점 P를 지나므로 $y=0$을 넣는다.","확인":null,"스킬":"S5","고비":true},{"제목":"삼각형 ORQ의 넓이 S(t)","힌트":"OR을 밑변으로 보면 높이는 무엇인가?","식":["$\\mathrm{R}(0,\\ \\sqrt{t})$, 높이 $=x_{1}$","$S(t)=\\frac{1}{2}\\cdot\\sqrt{t}\\cdot\\frac{t^{2}}{t^{2}+1}$"],"설명":"R은 원과 $y$축의 양의 부분의 교점이므로 $\\overline{\\mathrm{OR}}=\\sqrt{t}$이다. OR이 $y$축 위에 있으므로 Q에서 OR까지의 거리는 Q의 $x$좌표 $x_{1}$이다.","확인":null,"스킬":"S4"},{"제목":"극한값 계산","힌트":"$\\frac{4S(t)}{\\sqrt{t}}$를 $t$의 식으로 나타내면?","식":["$\\frac{4S(t)}{\\sqrt{t}}=\\frac{2t^{2}}{t^{2}+1}$","$\\lim_{t\\to\\infty}\\frac{2t^{2}}{t^{2}+1}=2$"],"설명":"분모와 분자를 $t^{2}$으로 나누면 $\\frac{2}{1+\\frac{1}{t^{2}}}$이고 $t\\to\\infty$이면 $\\frac{1}{t^{2}}\\to0$이다.","확인":"2","스킬":"S5"}]},"ns-42109a6cfb12":{"길":"ㄱ은 극한의 차로 보이고 ㄴ, ㄷ은 반례를 만든다","단계":[{"제목":"ㄱ의 판정","힌트":"$g(x)$를 $f(x)+g(x)$와 $f(x)$로 나타내면?","식":["$g(x)=\\{f(x)+g(x)\\}-f(x)$","$\\lim_{x\\to a}g(x)=\\lim_{x\\to a}\\{f(x)+g(x)\\}-\\lim_{x\\to a}f(x)=\\alpha-\\beta$","ㄱ은 참"],"설명":"극한값이 존재하는 두 함수의 차의 극한도 존재한다.","확인":null,"스킬":"C3"},{"제목":"ㄴ의 판정","힌트":"$f(x)\\to0$이면서 $f(x)g(x)$가 수렴하는데 $g(x)$는 발산하는 경우가 있는가?","식":["$f(x)=x-1,\\ g(x)=\\frac{1}{x-1}$이면 $\\lim_{x\\to1}f(x)=0,\\ \\lim_{x\\to1}f(x)g(x)=1$","$\\lim_{x\\to1}g(x)$는 존재하지 않으므로 ㄴ은 거짓"],"설명":"$f(x)$가 $0$으로 가면 곱이 수렴해도 $g(x)$의 극한은 정해지지 않는다. 반례로 거짓임을 보인다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄷ의 판정과 선지 고르기","힌트":"$g(x)$가 $f(x)$와 $h(x)$ 사이에 있어도 $x\\to\\infty$에서 발산할 수 있는가?","식":["$f(x)=\\left|x+\\frac{1}{3x}\\right|,\\ g(x)=\\left|x+\\frac{1}{2x}\\right|,\\ h(x)=\\left|x+\\frac{1}{x}\\right|$이면 $\\lim_{x\\to\\infty}\\{h(x)-f(x)\\}=0$","$\\lim_{x\\to\\infty}g(x)$는 존재하지 않으므로 ㄷ은 거짓, 옳은 것은 ㄱ뿐"],"설명":"$h(x)-f(x)$가 $0$으로 가도 $f$, $g$, $h$가 모두 커지면 $g(x)$는 수렴하지 않는다.","확인":null,"스킬":"C3"}]},"ns-43df60b257a9":{"길":"직선과 원의 교점 P의 좌표로 BH, PH를 구해 S(t)를 만든다","단계":[{"제목":"직선 AB의 방정식과 교점의 방정식","힌트":"A$(0,\\ t)$, B$(-1,\\ 0)$을 지나는 직선을 원의 방정식에 대입하면?","식":["직선 AB: $y=tx+t$","$x^{2}+(tx+t)^{2}=1$에서 $(1+t^{2})x^{2}+2t^{2}x+(t^{2}-1)=0$","$(x+1)\\{(1+t^{2})x+(t^{2}-1)\\}=0$"],"설명":"기울기가 $\\frac{t-0}{0-(-1)}=t$이고 $y$절편이 $t$이다. 교점 중 B$(-1,0)$은 $x=-1$이므로 $(x+1)$이 인수로 나온다.","확인":null,"스킬":"A4"},{"제목":"점 P의 좌표","힌트":"B가 아닌 교점의 $x$좌표를 구한 뒤 $y$좌표는?","식":["$x=-1$ 또는 $x=\\frac{1-t^{2}}{1+t^{2}}$","$\\mathrm{P}\\left(\\frac{1-t^{2}}{1+t^{2}},\\ \\frac{2t}{1+t^{2}}\\right)$"],"설명":"P는 B가 아닌 교점이므로 $x=\\frac{1-t^{2}}{1+t^{2}}$이다. $y=tx+t=t\\cdot\\frac{1-t^{2}}{1+t^{2}}+t=\\frac{2t}{1+t^{2}}$이다.","확인":null,"스킬":"A4","고비":true},{"제목":"삼각형 PBH의 넓이 S(t)","힌트":"밑변 BH와 높이 PH는 P의 좌표로 어떻게 나타내는가?","식":["$\\overline{\\mathrm{BH}}=1+\\frac{1-t^{2}}{1+t^{2}}=\\frac{2}{1+t^{2}},\\ \\overline{\\mathrm{PH}}=\\frac{2t}{1+t^{2}}$","$S(t)=\\frac{1}{2}\\cdot\\frac{2}{1+t^{2}}\\cdot\\frac{2t}{1+t^{2}}=\\frac{2t}{(1+t^{2})^{2}}$"],"설명":"H는 P에서 $x$축에 내린 수선의 발이므로 H의 $x$좌표는 P의 $x$좌표와 같다. B의 $x$좌표가 $-1$이므로 $\\overline{\\mathrm{BH}}=x_{\\mathrm{P}}+1$이다.","확인":null,"스킬":"G10"},{"제목":"극한값 계산","힌트":"$\\frac{t^{3}\\times S(t)}{4}$를 $t$의 식으로 나타내면?","식":["$\\frac{t^{3}\\cdot S(t)}{4}=\\frac{2t^{4}}{4(1+t^{2})^{2}}$","$\\lim_{t\\to\\infty}\\frac{2t^{4}}{4(1+t^{2})^{2}}=\\frac{1}{2}$"],"설명":"분모를 전개하면 최고차항이 $4t^{4}$이다. 분모와 분자를 $t^{4}$으로 나누면 $\\frac{2}{4\\left(\\frac{1}{t^{2}}+1\\right)^{2}}$이다.","확인":"1/2","스킬":"A4"}]},"ns-440fa42dc992":{"길":"각 그래프의 x=0 근처 좌극한과 우극한을 비교해 극한이 없는 것을 지운다","단계":[{"제목":"x=0에서 극한이 없는 그래프 가리기","힌트":"각 그래프에서 $x\\to0$일 때 좌극한과 우극한이 같은 유한한 값인가?","식":["(가), (다): $x\\to0$에서 함숫값이 한없이 커지거나 작아져 발산","(나): $\\lim_{x\\to0-}f(x)\\neq\\lim_{x\\to0+}f(x)$","(마): 정수마다 좌극한과 우극한이 달라 극한이 없음"],"설명":"극한이 존재하려면 좌극한과 우극한이 같은 유한한 값이어야 한다. (가), (다)는 $y$축에 한없이 가까워지고, (나), (마)는 그래프가 끊겨 있다.","확인":null,"스킬":"C2"},{"제목":"(라)의 극한 확인","힌트":"$x=0$에 빈 점과 따로 찍힌 점이 있으면 극한은 함숫값 $f(0)$과 관계가 있는가?","식":["(라): $\\lim_{x\\to0-}f(x)=\\lim_{x\\to0+}f(x)$이므로 $x=0$에서도 극한이 존재","모든 실수 $a$에서 극한이 존재하는 것은 (라)"],"설명":"극한은 $x$가 $a$에 가까워질 때의 값이므로 $f(a)$와 관계없다. (라)는 $x=0$ 이외에서 끊기지 않고 $x=0$에서 좌극한과 우극한이 같다.","확인":null,"스킬":"C2","고비":true}]},"ns-465e6c9e1084":{"길":"f(a)=0임을 알아내 인수로 약분하고 두 근의 차를 구한다","단계":[{"제목":"f(x)의 최고차항의 계수","힌트":"$\\lim_{x\\to\\infty}\\frac{f(x)}{x^{2}-1}=1$이면 이차함수 $f(x)$의 최고차항의 계수는?","식":["분모의 최고차항 $x^{2}$, 극한값 $1$이므로 $f(x)$의 최고차항의 계수는 $1$"],"설명":"분모와 분자의 차수가 같고 극한값이 $1$이므로 최고차항의 계수의 비가 $1$이다.","확인":null,"스킬":"A4"},{"제목":"f(a)=0 알아내기","힌트":"$f(a)\\neq0$이면 $\\lim_{x\\to a}$의 값은 얼마가 되는가?","식":["$f(a)\\neq0$이면 $\\lim_{x\\to a}\\frac{f(x)+4a-4x}{f(x)+2x-2a}=\\frac{f(a)}{f(a)}=1\\neq\\frac{4}{3}$","$f(a)=0$이므로 $f(x)=(x-a)(x-b)$"],"설명":"$x=a$를 대입하면 분자와 분모에 $4a-4x$, $2x-2a$는 모두 $0$이 되므로 $f(a)$만 남는다. 극한값이 $\\frac{4}{3}$이려면 $f(a)=0$이어야 한다.","확인":null,"스킬":"D11","고비":true},{"제목":"극한에서 b와 a의 관계","힌트":"분자와 분모를 $(x-a)$로 약분하고 $x=a$를 대입하면?","식":["$\\lim_{x\\to a}\\frac{(x-a)(x-b-4)}{(x-a)(x-b+2)}=\\frac{a-b-4}{a-b+2}=\\frac{4}{3}$","$3(a-b-4)=4(a-b+2)$에서 $b=a+20$"],"설명":"$f(x)+4a-4x=f(x)-4(x-a)=(x-a)(x-b-4)$이고 $f(x)+2x-2a=(x-a)(x-b+2)$이다.","확인":"20","스킬":"D11"},{"제목":"두 근의 차","힌트":"두 근 $a$, $a+20$에서 $\\frac{|\\beta-\\alpha|}{4}$를 구하면?","식":["$\\frac{|(a+20)-a|}{4}=5$"],"설명":"$f(x)=0$의 두 근이 $a$와 $a+20$이므로 두 근의 차는 $20$이다.","확인":"5","스킬":"A4"}]},"ns-490f9a0a65d5":{"길":"f, g가 모두 x(x-1)을 인수로 가짐을 보이고 (다)로 나머지 계수를 정한다","단계":[{"제목":"f(1)=g(1)=0 알아내기","힌트":"(다)의 둘째 극한에서 $f(1)+g(1)$의 값은? 그리고 (나)에서는?","식":["(다): $\\lim_{x\\to1}\\frac{f(x)+g(x)}{x-1}=1$에서 분모 $\\to0$이므로 $f(1)+g(1)=0$","(나): $f(x)g(x)$가 $(x-1)^{2}$으로 나누어떨어지므로 $f(1)=0$ 또는 $g(1)=0$","$f(1)=g(1)=0$"],"설명":"둘 중 하나가 $0$이고 합이 $0$이므로 나머지 하나도 $0$이다. 따라서 $f(x)$, $g(x)$ 모두 $x-1$을 인수로 갖는다.","확인":null,"스킬":"A4","고비":true},{"제목":"f(x), g(x)의 꼴","힌트":"(가)와 위의 결과로 $f(x)$, $g(x)$를 인수의 곱으로 쓰면?","식":["$f(x)=x(x-1)(x-a),\\ g(x)=x(x-1)(x-b)$"],"설명":"$f(0)=g(0)=0$이므로 $x$를 인수로 갖고, $f(1)=g(1)=0$이므로 $x-1$도 인수로 갖는다. 삼차이고 최고차항의 계수가 $1$이므로 나머지 인수는 $x-a$, $x-b$이다.","확인":null,"스킬":"A4"},{"제목":"(다)로 a, b 구하기","힌트":"첫째 극한과 둘째 극한에서 $a$, $b$의 관계식을 각각 구하면?","식":["$\\lim_{x\\to\\infty}\\frac{f(x)-g(x)}{x^{2}}=\\lim_{x\\to\\infty}\\frac{x(x-1)(b-a)}{x^{2}}=b-a=1$","$\\lim_{x\\to1}\\frac{f(x)+g(x)}{x-1}=\\lim_{x\\to1}x(2x-a-b)=2-a-b=1$","$a=0,\\ b=1$"],"설명":"$f(x)-g(x)=x(x-1)(b-a)$이고 $f(x)+g(x)=x(x-1)(2x-a-b)$이다. 두 식 $b-a=1$, $a+b=1$을 연립한다.","확인":null,"스킬":"A3"},{"제목":"f(3)+g(3)의 값","힌트":"$a=0$, $b=1$일 때 $f(x)$, $g(x)$를 구해 $x=3$을 대입하면?","식":["$f(x)=x^{2}(x-1),\\ g(x)=x(x-1)^{2}$","$f(3)+g(3)=18+12=30$"],"설명":"$f(3)=3^{2}\\cdot2=18$, $g(3)=3\\cdot2^{2}=12$이다.","확인":"30","스킬":"A3"}]},"ns-4967d029700c":{"길":"최고차항끼리 비교해 차수와 계수를 정하고 (나)로 이차항의 계수를 구한다","단계":[{"제목":"f(x)의 차수 정하기","힌트":"$\\{f(x)\\}^{2}-f(x^{2})$의 최고차항과 $x^{3}f(x)$의 최고차항의 차수는 어떤 관계인가?","식":["$f(x)=ax^{n}+Q(x)$, 분자의 최고차항 $(a^{2}-a)x^{2n}$, 분모의 최고차항 $ax^{n+3}$","$2n=n+3$, $n=3$"],"설명":"$a\\neq1$이므로 $a^{2}-a\\neq0$이다. 극한값이 $1$이면 분자와 분모의 차수가 같아야 한다.","확인":null,"스킬":"A3","고비":true},{"제목":"최고차항의 계수 a","힌트":"분자와 분모의 최고차항의 계수의 비가 $1$이 되려면?","식":["$\\frac{a^{2}-a}{a}=1$에서 $a=2$","$f(x)=2x^{3}+Q(x)$ ($Q(x)$는 이차 이하의 다항식)"],"설명":"최고차항끼리의 비가 극한값이다. $a\\neq0$이므로 $a^{2}-a=a$를 풀어 $a=2$를 얻는다.","확인":null,"스킬":"A3"},{"제목":"(나)에서 Q(x)의 일차항","힌트":"$f\\,'(x)=6x^{2}+Q\\,'(x)$에서 $\\lim_{x\\to0}\\frac{f\\,'(x)}{x}$가 존재하려면 $f\\,'(0)$은?","식":["$f\\,'(0)=Q\\,'(0)=0$","$Q(x)=px^{2}+q$ (일차항 없음)"],"설명":"분모가 $0$으로 가는데 극한이 존재하므로 분자 $f\\,'(x)$도 $0$으로 가야 한다. $Q'(0)$은 $Q(x)$의 일차항의 계수이다.","확인":null,"스킬":"D11"},{"제목":"이차항의 계수 p","힌트":"$f\\,'(x)=6x^{2}+2px$를 $x$로 나눈 극한은?","식":["$\\lim_{x\\to0}\\frac{6x^{2}+2px}{x}=\\lim_{x\\to0}(6x+2p)=2p=1$","$p=\\frac{1}{2}$"],"설명":"$\\frac{f\\,'(x)}{x}=6x+2p$이므로 $x\\to0$이면 $2p$이다.","확인":"1/2","스킬":"D13"},{"제목":"$f\\,'(1)$의 값","힌트":"$f(x)=2x^{3}+\\frac{1}{2}x^{2}+q$를 미분해 $x=1$을 대입하면?","식":["$f\\,'(x)=6x^{2}+x$","$f\\,'(1)=6+1=7$"],"설명":"상수항 $q$는 미분하면 사라지므로 $f\\,'(1)$은 $q$와 관계없다.","확인":"7","스킬":"D1"}]},"ns-4a82a59ba7f0":{"길":"a가 4보다 큰지 작은지로 절댓값을 풀어 극한을 구한다","단계":[{"제목":"a>4, a=4인 경우","힌트":"$x=4$ 근처에서 $|x-a|$의 부호는 $a$와 $4$의 크기에 따라 어떻게 달라지는가?","식":["$a>4$: $|x-a|=a-x$이므로 $\\lim_{x\\to4}\\frac{-(x-4)}{(x-4)(x+4)}=-\\frac{1}{8}$","$-\\frac{1}{8}=\\frac{b}{16}$에서 $b=-2$이므로 자연수가 아님","$a=4$: $\\frac{|x-4|}{x^{2}-16}$의 극한은 존재하지 않음"],"설명":"$x$가 $4$ 근처이면 $x<a$이므로 $|x-a|=a-x$이고 분자는 $(a-x)-(a-4)=-(x-4)$이다. $a=4$이면 분자가 $|x-4|$라 좌극한과 우극한이 다르다.","확인":null,"스킬":"C2","고비":true},{"제목":"a<4인 경우","힌트":"$a<4$이면 $x=4$ 근처에서 $|x-a|$를 어떻게 쓰는가?","식":["$|x-a|=x-a$이므로 $\\lim_{x\\to4}\\frac{(x-a)-(4-a)}{x^{2}-16}=\\lim_{x\\to4}\\frac{1}{x+4}=\\frac{1}{8}$","$\\frac{1}{8}=\\frac{b}{16}$에서 $b=2$"],"설명":"$x$가 $4$ 근처이면 $x>a$이므로 $|x-a|=x-a$이고 분자는 $x-4$이다. $x-4$가 약분된다.","확인":"2","스킬":"C2"},{"제목":"a+b의 최댓값","힌트":"$a<4$인 자연수 $a$의 최댓값은?","식":["$a=1,\\ 2,\\ 3$ 중 최대 $a=3$","$a+b=3+2=5$"],"설명":"$a>4$와 $a=4$는 조건을 만족하지 못하므로 $a<4$일 때만 생각한다. $b=2$로 일정하므로 $a$가 클수록 $a+b$가 크다.","확인":"5","스킬":"C2"}]},"ns-4bae89346aa5":{"길":"각의 이등분선 위의 점은 두 변까지의 거리가 같음을 이용해 f(t)를 구한다","단계":[{"제목":"$\\angle\\mathrm{AOB}$의 이등분선 OP","힌트":"각의 이등분선 위의 점에서 두 변까지의 거리는 어떤 관계인가?","식":["P$(x,\\ y)$에서 직선 OA와 $x$축까지의 거리가 같다: $\\frac{|4x-3y|}{5}=y$","$4x-3y=5y$, 곧 $y=\\frac{1}{2}x$"],"설명":"직선 OA의 방정식은 $4x-3y=0$이다. 이등분선 OP의 기울기가 양수이므로 $4x-3y=5y$를 택한다.","확인":null,"스킬":"S7"},{"제목":"직선 AB까지의 거리 조건","힌트":"P$\\left(f,\\ \\frac{f}{2}\\right)$에서 직선 AB까지의 거리는 $x$축까지의 거리와 같다. 직선 AB의 일반형은?","식":["직선 AB: $4x+(t-3)y-4t=0$","$\\frac{\\left|4f+\\frac{1}{2}f(t-3)-4t\\right|}{\\sqrt{16+(t-3)^{2}}}=\\frac{1}{2}f$"],"설명":"P는 $\\angle\\mathrm{ABO}$의 이등분선 위의 점이므로 직선 AB와 $x$축까지의 거리가 같고, 그 값은 P의 $y$좌표 $\\frac{f}{2}$이다. $\\sqrt{16+(t-3)^{2}}=\\sqrt{t^{2}-6t+25}$이다.","확인":null,"스킬":"S7","고비":true},{"제목":"f(t)의 식","힌트":"절댓값 안의 식의 부호를 정하고 $f$에 대해 풀면?","식":["P는 삼각형 안쪽이므로 $4f+\\frac{1}{2}f(t-3)-4t<0$이고 $4t-4f-\\frac{1}{2}f(t-3)=\\frac{1}{2}f\\sqrt{t^{2}-6t+25}$","$f(t)=\\frac{8t}{t+5+\\sqrt{t^{2}-6t+25}}$"],"설명":"$4x+(t-3)y-4t$의 값은 원점에서 $-4t<0$이다. P는 원점과 같은 쪽(삼각형 안쪽)에 있으므로 음수이다. $f$로 묶으면 $4t=\\frac{1}{2}f\\left(t+5+\\sqrt{t^{2}-6t+25}\\right)$이다.","확인":null,"스킬":"S4"},{"제목":"극한값 계산","힌트":"분모와 분자를 $t$로 나누면?","식":["$f(t)=\\frac{8}{1+\\frac{5}{t}+\\sqrt{1-\\frac{6}{t}+\\frac{25}{t^{2}}}}$","$\\lim_{t\\to\\infty}f(t)=\\frac{8}{1+0+1}=4$"],"설명":"$t\\to\\infty$이면 $\\frac{5}{t}$, $\\frac{6}{t}$, $\\frac{25}{t^{2}}$이 모두 $0$으로 간다.","확인":"4","스킬":"S7"}]},"ns-4c2cb847657e":{"길":"두 원의 반지름을 t로 나타내 넓이의 비의 극한을 구한다","단계":[{"제목":"원 $O_{1}$의 넓이 $S(t)$","힌트":"원 $O_{1}$의 반지름 $\\overline{\\mathrm{OP}}$를 $t$로 나타내면?","식":["$\\overline{\\mathrm{OP}}=\\sqrt{t^{2}+t^{4}}$","$S(t)=\\pi\\left(t^{2}+t^{4}\\right)$"],"설명":"원의 넓이는 $\\pi\\times(\\text{반지름})^{2}$이다. $\\overline{\\mathrm{OP}}^{2}=t^{2}+(t^{2})^{2}$이다.","확인":null,"스킬":"S4"},{"제목":"점 R의 좌표 a","힌트":"원 $O_{2}$가 원점을 지나므로 $\\overline{\\mathrm{RO}}$와 $\\overline{\\mathrm{RP}}$의 관계는?","식":["$\\overline{\\mathrm{RO}}=\\overline{\\mathrm{RP}}$에서 $a^{2}=t^{2}+(t^{2}-a)^{2}$","$a=\\frac{t^{2}+1}{2}$"],"설명":"$\\overline{\\mathrm{RO}}=a$이고 $\\overline{\\mathrm{RP}}^{2}=t^{2}+(t^{2}-a)^{2}$이다. 전개하면 $a^{2}$이 소거되어 $2at^{2}=t^{2}+t^{4}$이고 $t\\neq0$이므로 $a=\\frac{1+t^{2}}{2}$이다.","확인":null,"스킬":"S4","고비":true},{"제목":"원 $O_{2}$의 넓이 $T(t)$","힌트":"반지름이 $a$이므로 $T(t)$는?","식":["$T(t)=\\pi a^{2}=\\pi\\left(\\frac{t^{2}+1}{2}\\right)^{2}=\\frac{\\pi\\left(t^{4}+2t^{2}+1\\right)}{4}$"],"설명":"원 $O_{2}$의 반지름은 $\\overline{\\mathrm{RO}}=a$이다.","확인":null,"스킬":"S4"},{"제목":"넓이의 비의 극한","힌트":"$\\frac{S(t)}{T(t)}$를 $t$의 식으로 나타내고 최고차항을 비교하면?","식":["$\\frac{S(t)}{T(t)}=\\frac{4\\left(t^{4}+t^{2}\\right)}{t^{4}+2t^{2}+1}$","$\\lim_{t\\to\\infty}\\frac{S(t)}{T(t)}=4$"],"설명":"$\\pi$가 약분되고, 분모와 분자의 차수가 같으므로 최고차항의 계수의 비가 극한값이다.","확인":"4","스킬":"S3"}]},"ns-4c52f5ee3987":{"길":"보기마다 x=0에서 좌극한과 우극한을 구해 조건에 맞는지 가른다","단계":[{"제목":"ㄱ의 좌극한과 우극한","힌트":"$x\\to0-$에서는 $x^{2}-2x+1$, $x\\to0+$에서는 $\\frac{1}{x+1}$의 값은?","식":["$\\lim_{x\\to0-}f(x)=\\lim_{x\\to0-}(x^{2}-2x+1)=1$","$\\lim_{x\\to0+}f(x)=\\lim_{x\\to0+}\\frac{1}{x+1}=1$","좌극한과 우극한이 같아 극한이 존재하므로 ㄱ은 조건에 맞지 않음"],"설명":"$x<0$이면 $f(x)=(x-1)^{2}$이다. 좌극한과 우극한이 같으면 극한값이 존재한다.","확인":null,"스킬":"C2"},{"제목":"ㄴ의 좌극한과 우극한","힌트":"$x<0$과 $x>0$에서 $|x|$를 풀어 $g(x)$를 간단히 하면?","식":["$x<0$: $g(x)=\\frac{x^{2}-x}{-x}=-x+1\\to1$","$x>0$: $g(x)=\\frac{x^{2}-x}{x}=x-1\\to-1$","좌극한 $1$은 존재하고 우극한 $-1$과 달라 극한값이 없으므로 ㄴ은 조건에 맞음"],"설명":"$x<0$이면 $|x|=-x$, $x>0$이면 $|x|=x$이다. 두 쪽에서 약분한 식이 다르므로 $x=0$에서 좌극한과 우극한을 따로 구한다.","확인":null,"스킬":"C2","고비":true},{"제목":"ㄷ의 판정과 선지 고르기","힌트":"$x\\to0$에서 $x|x|$의 좌극한과 우극한은?","식":["$\\lim_{x\\to0-}x|x|=\\lim_{x\\to0-}(-x^{2})=0,\\ \\lim_{x\\to0+}x^{2}=0$","극한이 존재하므로 ㄷ은 조건에 맞지 않음, 조건에 맞는 것은 ㄴ뿐"],"설명":"좌극한과 우극한이 같아 극한값 $0$이 존재한다.","확인":null,"스킬":"C2"}]},"ns-4d4c0ecdebbb":{"길":"x=1 좌우의 극한값으로 곱의 극한 조건을 세우고 주기 3으로 a를 찾는다","단계":[{"제목":"f의 좌극한과 우극한 읽기","힌트":"각 구간의 식으로 $x=1$, $x=2$, $x=3$ 좌우의 극한을 구하면?","식":["$x=1$: $\\lim_{x\\to1-}f(x)=2,\\ \\lim_{x\\to1+}f(x)=1$","$x=2$: $\\lim_{x\\to2-}f(x)=1,\\ \\lim_{x\\to2+}f(x)=2$","$x=3$: $\\lim_{x\\to3-}f(x)=\\lim_{x\\to3+}f(x)=0$"],"설명":"$x=3$의 오른쪽은 주기 $3$에 의해 $x=0$ 오른쪽과 같아 $2x\\to0$이다. $x=3$의 왼쪽은 $-2x+6\\to0$이다.","확인":null,"스킬":"T2"},{"제목":"곱의 극한이 존재할 조건","힌트":"$x\\to1-$와 $x\\to1+$에서 $f(x)f(x+a)$의 극한을 각각 나타내면?","식":["$\\lim_{x\\to1-}f(x)f(x+a)=2\\cdot\\lim_{x\\to(1+a)-}f(x)$","$\\lim_{x\\to1+}f(x)f(x+a)=1\\cdot\\lim_{x\\to(1+a)+}f(x)$","$2\\lim_{x\\to(1+a)-}f(x)=\\lim_{x\\to(1+a)+}f(x)$"],"설명":"$x=1$에서 $f(x)$의 좌극한이 $2$, 우극한이 $1$이므로 곱의 좌극한과 우극한이 같아야 한다. $f(x+a)$의 극한은 $x+a\\to1+a$일 때의 극한이다.","확인":null,"스킬":"C2","고비":true},{"제목":"조건을 만족하는 a의 꼴","힌트":"$f$의 주기가 $3$이므로 $1+a$를 $3$으로 나눈 나머지에 따라 어떻게 되는가?","식":["$1+a\\equiv0$: $2\\cdot0=0$이므로 성립 ($a=2,\\ 5,\\ 8$)","$1+a\\equiv1$: $2\\cdot2=4\\neq1$이므로 불성립","$1+a\\equiv2$: $2\\cdot1=2$이므로 성립 ($a=1,\\ 4,\\ 7,\\ 10$)"],"설명":"$1+a$가 $3$의 배수이면 좌극한과 우극한이 모두 $0$이다. $1+a\\equiv2$이면 좌극한 $1$, 우극한 $2$로 조건이 성립한다. $1+a\\equiv1$이면 $x=1$ 좌우 극한 $2$, $1$이라 $4\\neq1$이다.","확인":null,"스킬":"T2"},{"제목":"a의 값의 합","힌트":"$1\\le a\\le10$에서 성립하는 $a$를 모두 더하면?","식":["$a=1,\\ 2,\\ 4,\\ 5,\\ 7,\\ 8,\\ 10$","$1+2+4+5+7+8+10=37$"],"설명":"$a=3,\\ 6,\\ 9$는 $1+a\\equiv1$이므로 제외한다.","확인":"37","스킬":"T2"}]},"ns-4e1d5676321b":{"길":"f를 두 근의 곱으로 쓰고 극한을 대입한 뒤 합과 곱으로 정리한다","단계":[{"제목":"f(x)와 두 근의 합, 곱","힌트":"$f(x)=2x^{2}-8x+7$을 두 근 $\\alpha$, $\\beta$로 나타내면?","식":["$f(x)=2(x-\\alpha)(x-\\beta)$","$\\alpha+\\beta=4,\\ \\alpha\\beta=\\frac{7}{2}$"],"설명":"최고차항의 계수가 $2$이므로 $f(x)=2(x-\\alpha)(x-\\beta)$이다. 근과 계수의 관계로 합과 곱을 얻는다.","확인":null,"스킬":"A2"},{"제목":"두 극한을 값으로 나타내기","힌트":"$f(x)f(2x)$를 인수의 곱으로 쓰고 $x-\\alpha$로 약분하면?","식":["$f(x)f(2x)=4(x-\\alpha)(x-\\beta)(2x-\\alpha)(2x-\\beta)$","$\\lim_{x\\to\\alpha}\\frac{f(x)f(2x)}{x-\\alpha}=4\\alpha(\\alpha-\\beta)(2\\alpha-\\beta)$","$\\lim_{x\\to\\beta}\\frac{f(x)f(2x)}{x-\\beta}=4\\beta(\\beta-\\alpha)(2\\beta-\\alpha)$"],"설명":"$f(2x)=2(2x-\\alpha)(2x-\\beta)$이다. 약분하고 $x=\\alpha$, $x=\\beta$를 대입하면 $2\\alpha-\\alpha=\\alpha$, $2\\beta-\\beta=\\beta$가 된다.","확인":null,"스킬":"A2","고비":true},{"제목":"두 극한의 합 정리","힌트":"두 식을 $4(\\alpha-\\beta)$로 묶으면?","식":["$4(\\alpha-\\beta)\\{\\alpha(2\\alpha-\\beta)-\\beta(2\\beta-\\alpha)\\}$","$=4(\\alpha-\\beta)\\left(2\\alpha^{2}-2\\beta^{2}\\right)=8(\\alpha-\\beta)^{2}(\\alpha+\\beta)$"],"설명":"$\\beta-\\alpha=-(\\alpha-\\beta)$이므로 둘째 항에서 부호가 바뀐다. $\\alpha(2\\alpha-\\beta)-\\beta(2\\beta-\\alpha)=2\\alpha^{2}-2\\beta^{2}$이다.","확인":null,"스킬":"A2"},{"제목":"합과 곱으로 값 구하기","힌트":"$(\\alpha-\\beta)^{2}$을 $\\alpha+\\beta$와 $\\alpha\\beta$로 나타내면?","식":["$(\\alpha-\\beta)^{2}=(\\alpha+\\beta)^{2}-4\\alpha\\beta=16-14=2$","$8\\cdot2\\cdot4=64$"],"설명":"$\\alpha+\\beta=4$, $\\alpha\\beta=\\frac{7}{2}$를 대입한다.","확인":"64","스킬":"A2"}]},"ns-557f090fbfed":{"길":"보기마다 그래프에서 좌극한과 우극한을 읽어 값을 비교한다","단계":[{"제목":"ㄱ의 극한 읽기","힌트":"$x\\to\\infty$일 때 $\\frac{x+1}{x}$와 $-\\frac{x}{x^{2}+1}$은 각각 어느 쪽에서 어떤 값에 가까워지는가?","식":["$\\frac{x+1}{x}=1+\\frac{1}{x}\\to1+,\\ -\\frac{x}{x^{2}+1}\\to0-$","$\\lim_{x\\to1+}f(x)=-1,\\ \\lim_{x\\to0-}f(x)=2$이므로 ㄱ의 값은 $-1\\times2=-2$, ㄱ은 참"],"설명":"$x\\to\\infty$일 때 $\\frac{1}{x}>0$이므로 $1$보다 큰 쪽에서 $1$로 간다. $-\\frac{x}{x^{2}+1}$은 음수이므로 $0$보다 작은 쪽에서 $0$으로 간다. 그래프에서 $x=1$ 오른쪽 값은 $-1$, $x=0$ 왼쪽 값은 $2$이다.","확인":null,"스킬":"T6"},{"제목":"ㄴ의 판정","힌트":"$x\\to1-$이면 $1-x$는, $x\\to0-$이면 $-1+x$는 어느 쪽에서 어떤 값에 가까워지는가?","식":["$x\\to1-$이면 $1-x\\to0+$, $x\\to0-$이면 $-1+x\\to-1-$","$\\lim_{x\\to0+}f(x)=1,\\ \\lim_{x\\to-1-}f(x)=-1$이므로 곱은 $-1$, ㄴ은 거짓"],"설명":"그래프에서 $x=0$ 오른쪽 극한값은 $1$이고 $x=-1$ 왼쪽 극한값은 $-1$이다. 곱이 $-1$이므로 $1$이 아니다.","확인":"-1","스킬":"T6"},{"제목":"ㄷ의 판정과 선지 고르기","힌트":"역함수의 그래프에서 우극한이 $f(a)$와 다른 $a$는 어디인가?","식":["$a=0$: $\\lim_{x\\to0+}f^{-1}(x)=1\\neq f(0)=2$","$a=1$: $\\lim_{x\\to1+}f^{-1}(x)=-1\\neq f(1)=0$","그 밖의 $a$에서는 같으므로 $a$의 합은 $0+1=1\\neq0$, ㄷ은 거짓이고 옳은 것은 ㄱ뿐"],"설명":"$y=f^{-1}(x)$의 그래프는 $f$의 그래프를 $y=x$에 대칭시킨 것이다. $x=-1$에서는 $\\lim_{x\\to-1+}f^{-1}(x)=1=f(-1)$로 같다. $x=0$과 $x=1$에서만 값이 다르다.","확인":null,"스킬":"T1","고비":true}]},"ns-5a32badc2ef7":{"길":"차수와 최고차항을 비교해 a를 정하고 (나)로 나머지 계수를 구한다","단계":[{"제목":"f(x)의 차수 정하기","힌트":"$f(x)$의 차수를 $n$이라 할 때 분자의 두 항과 분모의 차수는 각각 얼마인가?","식":["$f(x^{3})$: $3n$차, $\\{xf\\,'(x)\\}^{3}$: $3n$차, $x^{2}f(x^{2})$: $2n+2$차","$2n+2=3n$, $n=2$"],"설명":"극한값 $73$이 유한한 값이므로 분자와 분모의 차수가 같아야 한다. 최고차항의 계수가 양수라 분자의 두 최고차항은 서로 상쇄되지 않는다.","확인":"2","스킬":"A11","고비":true},{"제목":"최고차항의 계수 a","힌트":"$f(x)=ax^{2}+bx+c$로 놓고 최고차항끼리 비교하면?","식":["분자의 최고차항 $\\left(a+8a^{3}\\right)x^{6}$, 분모의 최고차항 $ax^{6}$","$\\frac{a+8a^{3}}{a}=1+8a^{2}=73$, $a=3$"],"설명":"$f(x^{3})$의 최고차항은 $ax^{6}$이고 $xf\\,'(x)$의 최고차항은 $2ax^{2}$이므로 세제곱하면 $8a^{3}x^{6}$이다. $a>0$이므로 $a=3$이다.","확인":"3","스킬":"A3"},{"제목":"(나)로 b, c 구하기","힌트":"분모가 $0$으로 가므로 분자 $f(x)+f\\,'(x)$의 상수항은? 그리고 일차항의 계수는?","식":["$f(0)+f\\,'(0)=0$에서 $b+c=0$","$\\lim_{x\\to0}\\frac{ax^{2}+(b+2a)x}{x}=b+2a=2$에서 $b=-4,\\ c=4$"],"설명":"$f(x)+f\\,'(x)=ax^{2}+(b+2a)x+(b+c)$이다. 상수항 $b+c$가 $0$이어야 극한이 존재하고, 그때 극한값은 일차항의 계수 $b+2a$이다.","확인":"-4","스킬":"A3"},{"제목":"f(2)의 값","힌트":"$f(x)=3x^{2}-4x+4$에 $x=2$를 대입하면?","식":["$f(2)=3\\cdot4-4\\cdot2+4=8$"],"설명":"$a=3$, $b=-4$, $c=4$를 대입한다.","확인":"8","스킬":"A3"}]},"ns-5a88f57d665c":{"길":"(가)로 f(x)-3x의 인수를 찾고 (나)로 차수와 계수를 정한다","단계":[{"제목":"분자가 0이 되는 조건","힌트":"분모 $x^{2}+2x-3$이 $0$이 되는 $x$의 값에서 분자는 어떻게 되어야 하는가?","식":["$x^{2}+2x-3=(x-1)(x+3)$이므로 $f(1)-3=0,\\ f(-3)+9=0$","$f(x)-3x=(x-1)(x+3)g(x)$ ($g(x)$는 다항식)"],"설명":"모든 실수 $a$에서 극한이 존재하려면 분모가 $0$이 되는 $x=1$, $x=-3$에서 분자도 $0$이 되어야 한다. 다항함수이므로 $f(x)-3x$는 $(x-1)(x+3)$으로 나누어떨어진다.","확인":null,"스킬":"D11"},{"제목":"f(x)의 차수와 최고차항의 계수","힌트":"$\\sqrt{f(x)}-(2x-1)$을 유리화하면 분모의 차수는? 극한이 존재하려면 분자의 차수는?","식":["$\\sqrt{f(x)}-(2x-1)=\\frac{f(x)-(2x-1)^{2}}{\\sqrt{f(x)}+(2x-1)}$","분모가 일차이므로 분자의 차수가 $1$ 이하, 곧 $f(x)$는 최고차항이 $4x^{2}$인 이차식","$g(x)=4$"],"설명":"$f(x)-3x$가 이차 이상이고 $f(x)$가 $n$차이면 분모는 $\\frac{n}{2}$차, 분자는 $(2x-1)^{2}$과 겹치지 않으면 $n$차이다. 분자의 차수가 분모 이하이려면 $f(x)$가 이차이고 $x^{2}$의 계수가 $4$로 $(2x-1)^{2}$과 같아야 한다.","확인":"4","스킬":"A11","고비":true},{"제목":"f(2)의 값","힌트":"$f(x)-3x=4(x-1)(x+3)$에 $x=2$를 대입하면?","식":["$f(2)-6=4\\cdot1\\cdot5=20$","$f(2)=26$"],"설명":"$x=2$일 때 $3x=6$이고 $(x-1)(x+3)=1\\cdot5$이다.","확인":"26","스킬":"A4"}]},"ns-673a6b223eba":{"길":"보기마다 안쪽 함수의 극한 방향을 정한 뒤 바깥 함수의 극한을 읽는다","단계":[{"제목":"ㄱ의 판정","힌트":"$x\\to1-$와 $x\\to1+$에서 $f(x)$의 극한은 각각?","식":["$\\lim_{x\\to1-}f(x)=1,\\ \\lim_{x\\to1+}f(x)=0$","좌극한과 우극한이 달라 극한이 없으므로 ㄱ은 거짓"],"설명":"$x<1$ 근처에서 $f(x)=x$이므로 $1$로 가고, $x>1$ 근처에서 $f(x)=x-1$이므로 $0$으로 간다.","확인":null,"스킬":"T6"},{"제목":"ㄴ의 판정","힌트":"$x\\to1+$일 때 $f(x)$는 어느 쪽에서 어떤 값에 가까워지는가?","식":["$x\\to1+$이면 $f(x)=x-1\\to0+$","$\\lim_{x\\to1+}f(f(x))=\\lim_{t\\to0+}f(t)=0$이므로 ㄴ은 참"],"설명":"$f(x)=t$로 놓으면 $x\\to1+$일 때 $t$가 $0$보다 큰 쪽에서 $0$으로 간다. $0<t<1$에서 $f(t)=t$이므로 극한은 $0$이다.","확인":null,"스킬":"T6","고비":true},{"제목":"ㄷ의 판정과 선지 고르기","힌트":"$x\\to1-$일 때 $f(x)$는 어느 쪽에서 어떤 값에 가까워지는가?","식":["$x\\to1-$이면 $f(x)=x\\to1-$","$\\lim_{x\\to1-}f(f(x))=\\lim_{t\\to1-}f(t)=1$이므로 ㄷ은 참, 옳은 것은 ㄴ, ㄷ"],"설명":"$f(x)=t$로 놓으면 $x\\to1-$일 때 $t$가 $1$보다 작은 쪽에서 $1$로 간다. $0<t<1$에서 $f(t)=t$이므로 극한은 $1$이다.","확인":null,"스킬":"T6"}]},"ns-6c4d2a528299":{"길":"삼차식의 꼴을 정하고 f(1)=g(1)=2와 미분계수 조건으로 계수를 구한다","단계":[{"제목":"f, g의 꼴 정하기","힌트":"(가)와 (다)의 첫째 극한에서 두 삼차식의 $x^{2}$의 계수의 차는?","식":["$f(x)=x^{3}+ax^{2}+bx+2,\\ g(x)=x^{3}+(a-3)x^{2}+cx+2$"],"설명":"$f(0)=g(0)=2$이므로 상수항이 $2$이다. $\\frac{f(x)-g(x)}{x^{2}}$의 극한이 $3$이므로 $f(x)-g(x)$의 이차항의 계수가 $3$이다.","확인":null,"스킬":"A3"},{"제목":"f(1)=g(1)=2 알아내기","힌트":"(나)에서 $f(1)g(1)$의 값은? (다)의 둘째 극한에서 $f(1)+g(1)$의 값은?","식":["(나): $f(x)g(x)=(x-1)^{2}Q(x)+18x-14$에 $x=1$을 넣으면 $f(1)g(1)=4$","(다): 분모 $\\to0$이므로 $f(1)+g(1)-4=0$","$f(1)\\{4-f(1)\\}=4$, $\\{f(1)-2\\}^{2}=0$, $f(1)=g(1)=2$"],"설명":"합이 $4$이고 곱이 $4$이므로 $f(1)$은 $t^{2}-4t+4=0$의 중근 $2$이다.","확인":null,"스킬":"A4","고비":true},{"제목":"a, b, c 구하기","힌트":"$f(1)=2$, $g(1)=2$와 둘째 극한을 $f\\,'(1)+g\\,'(1)$로 바꾸면?","식":["$f(1)=a+b+3=2$에서 $a+b=-1$, $g(1)=a+c=2$","$\\lim_{x\\to1}\\frac{f(x)+g(x)-4}{x-1}=f\\,'(1)+g\\,'(1)=4a+b+c=9$","$a=4,\\ b=-5,\\ c=-2$"],"설명":"$f(1)+g(1)=4$이므로 극한은 $\\frac{\\{f(x)+g(x)\\}-\\{f(1)+g(1)\\}}{x-1}$이고 미분계수의 정의에 의해 $f\\,'(1)+g\\,'(1)$이다. $f\\,'(1)=3+2a+b$, $g\\,'(1)=3+2(a-3)+c$이다.","확인":null,"스킬":"A3"},{"제목":"f(3)+g(3)의 값","힌트":"$f(x)=x^{3}+4x^{2}-5x+2$, $g(x)=x^{3}+x^{2}-2x+2$에 $x=3$을 대입하면?","식":["$f(3)=27+36-15+2=50,\\ g(3)=27+9-6+2=32$","$f(3)+g(3)=82$"],"설명":"$a=4$, $b=-5$, $c=-2$를 대입한다.","확인":"82","스킬":"A3"}]},"ns-7363d21bd7c6":{"길":"f(x)의 값을 구해 x와 2f(x)를 비교하며 좌우의 g(x)를 정한다","단계":[{"제목":"x=6 근처에서 f(x)의 값","힌트":"$x$가 $6$ 근처일 때 $x$보다 작은 자연수 중 소수는 몇 개인가?","식":["$5<x<7$에서 $x$보다 작은 소수는 $2,\\ 3,\\ 5$","$f(x)=3$"],"설명":"$x\\to6-$이면 $5<x<6$이고 $x\\to6+$이면 $6<x<7$이다. 어느 쪽이든 $x$보다 작은 소수는 $2$, $3$, $5$뿐이다.","확인":"3","스킬":"C6"},{"제목":"좌우에서 g(x) 정하기","힌트":"$x\\to6+$와 $x\\to6-$에서 $x$와 $2f(x)$의 크기를 비교하면?","식":["$x\\to6+$: $x>6=2f(x)$이므로 $g(x)=f(x)=3$, $\\alpha=3$","$x\\to6-$: $x<6=2f(x)$이므로 $g(x)=\\frac{1}{f(x)}=\\frac{1}{3}$, $\\beta=\\frac{1}{3}$"],"설명":"$2f(x)=6$이다. $x\\ge2f(x)$이면 $g(x)=f(x)$이고 $x<2f(x)$이면 $g(x)=\\frac{1}{f(x)}$이다.","확인":null,"스킬":"C6","고비":true},{"제목":"$\\frac{\\alpha}{\\beta}$의 값","힌트":"$\\alpha=3$, $\\beta=\\frac{1}{3}$일 때 $\\frac{\\alpha}{\\beta}$는?","식":["$\\frac{\\alpha}{\\beta}=\\frac{3}{\\frac{1}{3}}=9$"],"설명":"$3$을 $\\frac{1}{3}$로 나누면 $3\\times3=9$이다.","확인":"9","스킬":"C6"}]},"ns-73c74e93be49":{"길":"A, B, C의 좌표를 a로 나타내 두 선분의 길이의 비를 약분한다","단계":[{"제목":"점 A, B의 좌표","힌트":"직선 $y=a$와 $y=f(x)$, $y=g(x)$의 교점의 $x$좌표를 각각 구하면?","식":["$\\sqrt{x+2}=a$에서 $x=a^{2}-2$, $\\mathrm{A}(a^{2}-2,\\ a)$","$-\\sqrt{x-2}+2=a$에서 $x=(2-a)^{2}+2=a^{2}-4a+6$, $\\mathrm{B}(a^{2}-4a+6,\\ a)$"],"설명":"$y=f(x)$에서 $x=y^{2}-2$이고 $y=g(x)$에서 $\\sqrt{x-2}=2-a>0$이므로 양변을 제곱한다. $0<a<2$이다.","확인":null,"스킬":"G1","고비":true},{"제목":"선분 AB, BC의 길이","힌트":"C는 B를 지나는 $y$축에 평행한 직선과 $y=x$의 교점이다. C의 좌표와 두 길이는?","식":["$\\mathrm{C}(a^{2}-4a+6,\\ a^{2}-4a+6)$","$\\overline{\\mathrm{AB}}=(a^{2}-4a+6)-(a^{2}-2)=-4a+8$","$\\overline{\\mathrm{BC}}=(a^{2}-4a+6)-a=a^{2}-5a+6$"],"설명":"AB는 $x$축에 평행하므로 $x$좌표의 차이다. BC는 $y$축에 평행하므로 $y$좌표의 차이이고 $y=x$ 위의 C는 $x$좌표와 $y$좌표가 같다.","확인":null,"스킬":"G1"},{"제목":"극한값 계산","힌트":"분자 $a^{2}-5a+6$을 인수분해하면?","식":["$\\lim_{a\\to2}\\frac{a^{2}-5a+6}{-4a+8}=\\lim_{a\\to2}\\frac{(a-2)(a-3)}{-4(a-2)}$","$=\\lim_{a\\to2}\\frac{a-3}{-4}=\\frac{1}{4}$"],"설명":"$a\\to2$에서 분모와 분자가 모두 $0$으로 가므로 $a-2$를 약분한다.","확인":"1/4","스킬":"D11"}]},"ns-83697211626d":{"길":"교점의 좌표를 α로 나타내 사다리꼴의 넓이 S(t)를 t의 식으로 만든다","단계":[{"제목":"교점의 x좌표 사이의 관계","힌트":"$y=\\frac{1}{|x|}$을 원의 방정식에 대입하면 $x^{2}$에 대한 방정식은?","식":["$x^{2}+\\frac{1}{x^{2}}=t$에서 $(x^{2})^{2}-tx^{2}+1=0$","$x>0$인 두 근 $\\alpha<\\beta$에서 $\\alpha^{2}$, $\\beta^{2}$은 $s^{2}-ts+1=0$의 두 근이므로 $\\alpha^{2}+\\beta^{2}=t,\\ \\alpha^{2}\\beta^{2}=1$","$\\alpha\\beta=1$"],"설명":"$x^{2}=s$로 놓으면 $s$에 대한 이차방정식이 되고 근과 계수의 관계를 쓸 수 있다. $\\alpha$, $\\beta$가 양수이므로 $\\alpha\\beta=1$이고 $\\beta=\\frac{1}{\\alpha}$이다.","확인":null,"스킬":"A2"},{"제목":"네 점의 좌표와 두 밑변","힌트":"$y=\\frac{1}{|x|}$ 위의 점이므로 $x=\\alpha$인 점의 $y$좌표는? 대칭인 점들은?","식":["$\\mathrm{A}\\left(\\alpha,\\ \\frac{1}{\\alpha}\\right),\\ \\mathrm{B}\\left(-\\alpha,\\ \\frac{1}{\\alpha}\\right),\\ \\mathrm{C}\\left(-\\frac{1}{\\alpha},\\ \\alpha\\right),\\ \\mathrm{D}\\left(\\frac{1}{\\alpha},\\ \\alpha\\right)$","$\\overline{\\mathrm{BA}}=2\\alpha,\\ \\overline{\\mathrm{CD}}=\\frac{2}{\\alpha}$, 두 선분 사이의 거리 $\\frac{1}{\\alpha}-\\alpha$"],"설명":"$\\alpha<1<\\beta=\\frac{1}{\\alpha}$이다. 두 곡선이 $y$축에 대해 대칭이므로 B, C는 A, D와 $y$축 대칭이다. BA와 CD는 $x$축에 평행하다.","확인":null,"스킬":"G1"},{"제목":"사다리꼴의 넓이","힌트":"윗변 $2\\alpha$, 아랫변 $\\frac{2}{\\alpha}$, 높이 $\\frac{1}{\\alpha}-\\alpha$인 사다리꼴의 넓이는?","식":["$S(t)=\\frac{1}{2}\\left(2\\alpha+\\frac{2}{\\alpha}\\right)\\left(\\frac{1}{\\alpha}-\\alpha\\right)=\\frac{1}{\\alpha^{2}}-\\alpha^{2}$"],"설명":"$\\left(\\alpha+\\frac{1}{\\alpha}\\right)\\left(\\frac{1}{\\alpha}-\\alpha\\right)$는 합과 차의 곱이므로 $\\frac{1}{\\alpha^{2}}-\\alpha^{2}$이다.","확인":null,"스킬":"A2"},{"제목":"S(t)를 t의 식으로","힌트":"$\\left(\\frac{1}{\\alpha^{2}}-\\alpha^{2}\\right)^{2}$을 $\\alpha^{2}+\\frac{1}{\\alpha^{2}}$으로 나타내면?","식":["$\\left(\\frac{1}{\\alpha^{2}}-\\alpha^{2}\\right)^{2}=\\left(\\alpha^{2}+\\frac{1}{\\alpha^{2}}\\right)^{2}-4=t^{2}-4$","$S(t)=\\sqrt{t^{2}-4}$"],"설명":"$\\alpha^{2}+\\beta^{2}=\\alpha^{2}+\\frac{1}{\\alpha^{2}}=t$이다. $\\frac{1}{\\alpha^{2}}>\\alpha^{2}$이므로 $S(t)>0$이다.","확인":null,"스킬":"A2","고비":true},{"제목":"극한값 계산","힌트":"$\\frac{\\sqrt{t^{2}-4}}{6t+8}$의 분모와 분자를 $t$로 나누면?","식":["$\\lim_{t\\to\\infty}\\frac{\\sqrt{t^{2}-4}}{6t+8}=\\lim_{t\\to\\infty}\\frac{\\sqrt{1-\\frac{4}{t^{2}}}}{6+\\frac{8}{t}}=\\frac{1}{6}$"],"설명":"$t>0$이므로 $\\sqrt{t^{2}-4}$를 $t$로 나누면 $\\sqrt{1-\\frac{4}{t^{2}}}$이다.","확인":"1/6","스킬":"A2"}]},"ns-8f033fb681c8":{"길":"OP=PQ로 Q를 t로 나타내고 직선 PQ의 y절편을 구해 극한을 취한다","단계":[{"제목":"점 P, Q의 좌표","힌트":"$\\overline{\\mathrm{OP}}=\\overline{\\mathrm{PQ}}$이면 P의 $x$좌표와 Q의 $x$좌표는 어떤 관계인가?","식":["$\\mathrm{P}(t,\\ f(t))$, $\\mathrm{Q}(2t,\\ 0)$"],"설명":"$\\overline{\\mathrm{OP}}=\\overline{\\mathrm{PQ}}$이면 P는 선분 OQ의 수직이등분선 위에 있으므로 P의 $x$좌표는 Q의 $x$좌표의 절반이다. 그림에서 P는 제1사분면에 있으므로 $t>0$이다.","확인":null,"스킬":"S4"},{"제목":"R의 y좌표","힌트":"직선 PQ의 식에 $x=0$을 넣으면?","식":["직선 PQ의 기울기 $\\frac{0-f(t)}{2t-t}=-\\frac{f(t)}{t}$","$y-f(t)=-\\frac{f(t)}{t}(x-t)$에 $x=0$을 넣으면 $y=2f(t)=\\frac{4t^{2}}{1+t^{2}}$"],"설명":"$x=0$이면 $y=f(t)+\\frac{f(t)}{t}\\cdot t=2f(t)$이다. $f(t)=\\frac{2t^{2}}{1+t^{2}}$를 대입한다.","확인":null,"스킬":"S4","고비":true},{"제목":"극한값 계산","힌트":"P가 원점에서 한없이 멀어지면 $t$는 어떻게 되는가?","식":["$\\lim_{t\\to\\infty}\\frac{4t^{2}}{1+t^{2}}=\\lim_{t\\to\\infty}\\frac{4}{\\frac{1}{t^{2}}+1}=4$"],"설명":"P가 한없이 멀어지면 $t\\to\\infty$이고 R의 $y$좌표는 이 극한값에 가까워진다.","확인":"4","스킬":"S4"}]},"ns-92de1bcc05d4":{"길":"마름모의 대각선으로 OD를 OE로 나타내고 분모를 유리화해 극한을 구한다","단계":[{"제목":"사각형 ABCD의 모양과 교점 E","힌트":"$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{BC}}$이고 $\\overline{\\mathrm{AD}}\\parallel\\overline{\\mathrm{BC}}$, $\\overline{\\mathrm{CD}}\\parallel\\overline{\\mathrm{AB}}$이면 사각형 ABCD는?","식":["사각형 ABCD는 마름모","AC와 BD의 교점 E는 두 대각선의 중점이고 $\\overline{\\mathrm{AC}}\\perp\\overline{\\mathrm{BD}}$"],"설명":"두 쌍의 대변이 평행하면 평행사변형이고 이웃한 두 변이 같으면 마름모이다. $\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OC}}$이므로 O도 AC의 수직이등분선 위에 있어 B, O, E, D가 한 직선 위에 놓인다.","확인":null,"스킬":"S2"},{"제목":"OD를 OE로 나타내기","힌트":"$\\overline{\\mathrm{ED}}=\\overline{\\mathrm{BE}}$이고 $\\overline{\\mathrm{BE}}=\\overline{\\mathrm{BO}}+\\overline{\\mathrm{OE}}$이면 $\\overline{\\mathrm{ED}}$는?","식":["$\\overline{\\mathrm{ED}}=\\overline{\\mathrm{BE}}=1+\\overline{\\mathrm{OE}}$","$\\overline{\\mathrm{OD}}=\\overline{\\mathrm{OE}}+\\overline{\\mathrm{ED}}=1+2\\overline{\\mathrm{OE}}$"],"설명":"마름모의 대각선은 서로를 이등분하므로 $\\overline{\\mathrm{ED}}=\\overline{\\mathrm{BE}}$이다. $\\overline{\\mathrm{BO}}$는 원의 반지름 $1$이다.","확인":null,"스킬":"S2","고비":true},{"제목":"OE의 길이","힌트":"직각삼각형 OEA에서 $\\overline{\\mathrm{OA}}=1$, $\\overline{\\mathrm{AE}}=\\frac{t}{2}$일 때 $\\overline{\\mathrm{OE}}$는?","식":["$\\overline{\\mathrm{OE}}=\\sqrt{1-\\frac{t^{2}}{4}}$"],"설명":"O가 AC의 수직이등분선 위에 있으므로 $\\angle\\mathrm{OEA}=90^{\\circ}$이다. E가 AC의 중점이므로 $\\overline{\\mathrm{AE}}=\\frac{t}{2}$이다.","확인":null,"스킬":"S3"},{"제목":"분모를 t로 나타내기","힌트":"$12-t^{2}-4\\overline{\\mathrm{OD}}$에 $\\overline{\\mathrm{OD}}=1+2\\overline{\\mathrm{OE}}$를 대입하면?","식":["$12-t^{2}-4\\left(1+2\\sqrt{1-\\frac{t^{2}}{4}}\\right)=8-t^{2}-4\\sqrt{4-t^{2}}$"],"설명":"$8\\sqrt{1-\\frac{t^{2}}{4}}=4\\sqrt{4-t^{2}}$이다.","확인":null,"스킬":"S3"},{"제목":"유리화와 극한","힌트":"분모에 켤레식 $(8-t^{2})+4\\sqrt{4-t^{2}}$를 곱하면 분모는?","식":["$(8-t^{2})^{2}-16(4-t^{2})=t^{4}$","$\\lim_{t\\to0+}\\left\\{(8-t^{2})+4\\sqrt{4-t^{2}}\\right\\}=8+8=16$"],"설명":"$t\\to0+$에서 분모와 분자가 모두 $0$으로 가므로 켤레식을 곱한다. 분모가 $t^{4}$이 되어 분자의 $t^{4}$과 약분된다.","확인":"16","스킬":"A5"}]},"ns-97b58f87a3e9":{"길":"BQ=AP=t로 두 직선의 교점 M의 좌표를 t로 나타내고 극한을 취한다","단계":[{"제목":"P, Q의 좌표와 두 직선의 방정식","힌트":"$\\overline{\\mathrm{BQ}}=\\overline{\\mathrm{AP}}=t$일 때 P와 Q의 좌표는?","식":["$\\mathrm{P}(4-t,\\ 0),\\ \\mathrm{Q}(0,\\ 2+t)$","직선 AB: $\\frac{x}{4}+\\frac{y}{2}=1$, 직선 PQ: $\\frac{x}{4-t}+\\frac{y}{2+t}=1$"],"설명":"그림에서 P는 A보다 원점 쪽에 있고 Q는 B보다 위쪽에 있다. $x$절편과 $y$절편을 알면 직선의 방정식을 절편꼴로 쓸 수 있다.","확인":null,"스킬":"G1"},{"제목":"교점 M의 y좌표","힌트":"직선 AB의 식에서 $x=4-2y$를 직선 PQ의 식에 대입하면?","식":["$(2+t)(4-2y)+(4-t)y=(4-t)(2+t)$","$-3ty=-t^{2}-2t$, $y=\\frac{t+2}{3}$"],"설명":"양변에 $(4-t)(2+t)$를 곱해 분모를 없앤다. $t\\neq0$이므로 $t$로 나누어 $y$를 구한다.","확인":null,"스킬":"G1","고비":true},{"제목":"b의 값","힌트":"P, Q가 A, B에 가까워지면 $t$는 어디로 가는가?","식":["$b=\\lim_{t\\to0}\\frac{t+2}{3}=\\frac{2}{3}$"],"설명":"P, Q가 각각 A, B에 한없이 가까워지면 $\\overline{\\mathrm{AP}}=\\overline{\\mathrm{BQ}}=t\\to0$이다.","확인":"2/3","스킬":"G1"},{"제목":"a의 값과 a+b","힌트":"M은 직선 AB 위의 점이다. $y=\\frac{2}{3}$일 때 $x$는?","식":["$a=4-2b=4-\\frac{4}{3}=\\frac{8}{3}$","$a+b=\\frac{8}{3}+\\frac{2}{3}=\\frac{10}{3}$"],"설명":"직선 AB의 식 $x=4-2y$에 $y=b=\\frac{2}{3}$를 넣으면 $a$를 얻는다.","확인":"10/3","스킬":"G1"}]},"ns-9937541784d7":{"길":"주기 4로 조건을 만족하는 n의 꼴을 정하고 40 이하의 합을 구한다","단계":[{"제목":"한 주기에서 조건을 만족하는 n","힌트":"그래프에서 $n=0,\\ \\pm1,\\ \\pm2$의 좌극한과 우극한의 절댓값의 합을 구하면?","식":["$n=\\pm1$: $|-1|+|-1|=2,\\ |1|+|1|=2$","$n=\\pm2$: $|1|+|-1|=2$","$n=0$: $|0|+|0|=0\\neq2$"],"설명":"$n=2$의 극한은 주기 $4$로 $n=-2$에서 읽는다. $x\\to-2-$와 $x\\to2-$의 극한은 $1$이고 $x\\to-2+$와 $x\\to2+$의 극한은 $-1$이다.","확인":null,"스킬":"T2","고비":true},{"제목":"자연수 n의 꼴","힌트":"$f(x+4)=f(x)$이면 조건을 만족하는 $n$에 $4$를 더해도 조건이 유지되는가?","식":["조건을 만족하는 $n$: $-2,\\ -1,\\ 1,\\ 2$이므로 $4$로 나눈 나머지가 $1,\\ 2,\\ 3$","$40$ 이하에서는 $4$의 배수가 아닌 자연수 전부"],"설명":"주기가 $4$이므로 $n$에 $4$를 더해도 극한이 같다. $-1$은 $3$과 같은 위치이고 $4$의 배수는 $n=0$과 같은 위치라 조건을 만족하지 않는다.","확인":null,"스킬":"T2"},{"제목":"조건을 만족하는 n의 합","힌트":"$1$부터 $40$까지의 합에서 $4$의 배수의 합을 빼면?","식":["$\\sum_{n=1}^{40}n-4\\sum_{k=1}^{10}k=820-220$","$=600$"],"설명":"$1$부터 $40$까지의 합은 $\\frac{40\\cdot41}{2}=820$이고, $4$의 배수 $4,\\ 8,\\ \\cdots,\\ 40$의 합은 $4\\cdot\\frac{10\\cdot11}{2}=220$이다.","확인":"600","스킬":"P6"}]},"ns-a29ac05d4aa6":{"길":"안쪽 식을 한 문자로 바꿔 우극한 방향을 정하고 그래프에서 값을 읽는다","단계":[{"제목":"한 문자로 바꾸어 극한의 방향 정하기","힌트":"$t=x+1$, $s=x-1$로 놓으면 $x\\to0+$, $x\\to1+$일 때 $t$, $s$는 각각 어디로 가는가?","식":["$t=x+1$: $x\\to0+$이면 $t\\to1+$","$s=x-1$: $x\\to1+$이면 $s\\to0+$","$\\lim_{x\\to0+}f(x+1)+\\lim_{x\\to1+}f(x-1)=\\lim_{t\\to1+}f(t)+\\lim_{s\\to0+}f(s)$"],"설명":"$x$가 $0$보다 큰 쪽에서 $0$으로 가면 $x+1$은 $1$보다 큰 쪽에서 $1$로 간다. $x$가 $1$보다 큰 쪽에서 $1$로 가면 $x-1$은 $0$보다 큰 쪽에서 $0$으로 간다.","확인":null,"스킬":"C2","고비":true},{"제목":"그래프에서 우극한 읽기","힌트":"그래프에서 $x=1$의 오른쪽과 $x=0$의 오른쪽에서 $f$의 값은 각각 어디로 가는가?","식":["$\\lim_{t\\to1+}f(t)=2,\\ \\lim_{s\\to0+}f(s)=0$","$2+0=2$"],"설명":"$x=1$ 오른쪽 선분은 점 $(1,\\ 2)$에서 시작하고, $x=0$ 오른쪽 선분은 비어 있는 점 $(0,\\ 0)$에서 시작한다. 극한은 함숫값 $f(1)$, $f(0)$과 관계없이 그 점의 높이로 정해진다.","확인":"2","스킬":"C2"}]},"ns-b41d99a77746":{"길":"AQ를 x의 식으로 나타내고 분자를 유리화해 약분한다","단계":[{"제목":"두 점 A, Q의 좌표","힌트":"$\\mathrm{O}$를 원점으로 두면 $\\mathrm{A}$의 좌표는? 원 위의 점 $\\mathrm{Q}$의 $y$좌표는?","식":["$\\mathrm{A}(-4,\\ 0)$, $\\mathrm{Q}\\left(x,\\ \\sqrt{16-x^{2}}\\right)$"],"설명":"지름이 $8$이므로 반지름은 $4$이고 원의 방정식은 $x^{2}+y^{2}=16$이다. $\\overline{\\mathrm{OP}}=x$이므로 $\\mathrm{Q}$의 $x$좌표는 $x$이고, $y$좌표는 양수이므로 $\\sqrt{16-x^{2}}$이다.","확인":null,"스킬":"S4"},{"제목":"f(x)의 식","힌트":"$\\overline{\\mathrm{AQ}}^{2}$을 두 점의 좌표로 쓰면?","식":["$f(x)^{2}=(x+4)^{2}+\\left(\\sqrt{16-x^{2}}\\right)^{2}=8x+32$","$f(x)=\\sqrt{8x+32}$"],"설명":"두 점 사이의 거리의 제곱은 좌표의 차의 제곱의 합이다. $x^{2}$ 항이 서로 없어져 $x$의 일차식이 남는다.","확인":null,"스킬":"S3"},{"제목":"분자를 유리화해 약분","힌트":"$\\frac{8-f(x)}{4-x}$의 분모·분자에 $8+f(x)$를 곱하면 분자는?","식":["$\\frac{8-f(x)}{4-x}=\\frac{64-f(x)^{2}}{(4-x)\\left(8+f(x)\\right)}$","$64-f(x)^{2}=64-(8x+32)=8(4-x)$이므로 $\\frac{8-f(x)}{4-x}=\\frac{8}{8+f(x)}$"],"설명":"$f(x)^{2}=8x+32$를 대입하면 분자가 $8(4-x)$가 되어 분모의 $4-x$와 약분된다. $x\\to4-$에서 $x\\ne4$이므로 약분해도 된다.","확인":null,"스킬":"D3","고비":true},{"제목":"극한값 계산","힌트":"$x\\to4-$일 때 $f(x)$는 어떤 값에 가까워지는가?","식":["$\\lim_{x\\to4-}f(x)=\\sqrt{8\\cdot4+32}=8$","$\\lim_{x\\to4-}\\frac{8}{8+f(x)}=\\frac{8}{16}=\\frac{1}{2}$"],"설명":"$f(x)=\\sqrt{8x+32}$는 $x=4$에서 연속이므로 $f(x)\\to8$이다. 분모 $8+f(x)$는 $16$에 가까워진다.","확인":"1/2","스킬":"D3"}]},"ns-b54e5f949978":{"길":"수직 조건으로 Q의 좌표를 t로 나타내 두 길이의 제곱을 비교한다","단계":[{"제목":"점 Q의 좌표","힌트":"주어진 직선에 수직인 직선의 기울기는? 이 직선이 점 $\\mathrm{P}$를 지날 때 $y$절편은?","식":["수직인 직선 $y=ax+b$에서 $\\frac{1}{2}a=-1$이므로 $a=-2$","$-2t+b=\\frac{1}{2}t+1$에서 $b=\\frac{5}{2}t+1$","$\\mathrm{Q}\\left(0,\\ \\frac{5}{2}t+1\\right)$"],"설명":"두 직선이 수직이면 기울기의 곱이 $-1$이다. $y$축 위의 점 $\\mathrm{Q}$의 $y$좌표는 직선의 $y$절편 $b$와 같다.","확인":null,"스킬":"G9","고비":true},{"제목":"두 길이의 제곱","힌트":"$\\mathrm{A}(-2,\\ 0)$과 $\\mathrm{Q}$, $\\mathrm{P}$ 사이의 거리의 제곱을 좌표로 쓰면?","식":["$\\overline{\\mathrm{AQ}}^{2}=2^{2}+\\left(\\frac{5}{2}t+1\\right)^{2}=\\frac{25}{4}t^{2}+5t+5$","$\\overline{\\mathrm{AP}}^{2}=(t+2)^{2}+\\left(\\frac{1}{2}t+1\\right)^{2}=\\frac{5}{4}t^{2}+5t+5$"],"설명":"두 점 사이의 거리의 제곱은 $x$좌표의 차의 제곱과 $y$좌표의 차의 제곱의 합이다. 두 식 모두 $t$에 대한 이차식이다.","확인":null,"스킬":"S4"},{"제목":"극한값 계산","힌트":"분모·분자를 $t^{2}$으로 나누면?","식":["$\\lim_{t\\to\\infty}\\frac{\\frac{25}{4}t^{2}+5t+5}{\\frac{5}{4}t^{2}+5t+5}=\\lim_{t\\to\\infty}\\frac{\\frac{25}{4}+\\frac{5}{t}+\\frac{5}{t^{2}}}{\\frac{5}{4}+\\frac{5}{t}+\\frac{5}{t^{2}}}=\\frac{\\frac{25}{4}}{\\frac{5}{4}}=5$"],"설명":"분모와 분자의 차수가 같으면 극한값은 최고차항의 계수의 비이다. $\\frac{5}{t}$, $\\frac{5}{t^{2}}$은 $0$으로 간다.","확인":"5","스킬":"A11"}]},"ns-b6840e63ae51":{"길":"네 점의 좌표로 두 넓이를 t의 식으로 쓰고 공통인수를 약분한다","단계":[{"제목":"점 M과 직선 l","힌트":"두 함수의 식을 같다고 놓으면 제$1$사분면의 교점은?","식":["$-x^{2}+4=x^{2}+2x$에서 $x^{2}+x-2=0$, $(x+2)(x-1)=0$","$x>0$이므로 $x=1$, $\\mathrm{M}(1,\\ 3)$","$l:\\ y=-(x-1)+3=-x+4$"],"설명":"제$1$사분면에서 만나므로 $x>0$인 근 $x=1$을 택한다. 직선 $l$은 기울기가 $-1$이고 $\\mathrm{M}$을 지난다.","확인":null,"스킬":"G1"},{"제목":"선분 PQ, QR의 길이","힌트":"직선 $x=t$ 위의 세 점 $\\mathrm{P}$, $\\mathrm{Q}$, $\\mathrm{R}$의 $y$좌표는?","식":["$\\mathrm{P}(t,\\ t^{2}+2t)$, $\\mathrm{Q}(t,\\ -t+4)$, $\\mathrm{R}(t,\\ -t^{2}+4)$","$\\overline{\\mathrm{PQ}}=(t^{2}+2t)-(-t+4)=(t+4)(t-1)$","$\\overline{\\mathrm{QR}}=(-t+4)-(-t^{2}+4)=t(t-1)$"],"설명":"세 점의 $x$좌표가 모두 $t$이므로 선분은 $y$축에 평행하고 길이는 $y$좌표의 차이다. $t>1$이면 $\\mathrm{P}$, $\\mathrm{Q}$, $\\mathrm{R}$ 순서로 위에서 아래로 놓인다.","확인":null,"스킬":"G10"},{"제목":"두 삼각형의 넓이","힌트":"$\\overline{\\mathrm{PQ}}$, $\\overline{\\mathrm{QR}}$를 밑변으로 보면 높이는 $\\mathrm{M}$에서 직선 $x=t$까지의 거리이다. 높이는?","식":["높이 $=t-1$","$S(t)=\\frac{1}{2}(t+4)(t-1)\\cdot(t-1)=\\frac{1}{2}(t+4)(t-1)^{2}$","$T(t)=\\frac{1}{2}t(t-1)\\cdot(t-1)=\\frac{1}{2}t(t-1)^{2}$"],"설명":"두 삼각형은 꼭짓점 $\\mathrm{M}$을 공유하고 밑변이 모두 직선 $x=t$ 위에 있으므로 높이가 $t-1$로 같다.","확인":null,"스킬":"G10","고비":true},{"제목":"극한값 계산","힌트":"$\\frac{S(t)}{T(t)}$에서 공통인 인수를 약분하면?","식":["$\\frac{S(t)}{T(t)}=\\frac{(t+4)(t-1)^{2}}{t(t-1)^{2}}=\\frac{t+4}{t}$","$\\lim_{t\\to1+}\\frac{t+4}{t}=5$"],"설명":"$t>1$이므로 $(t-1)^{2}\\ne0$이어서 약분할 수 있다. 약분한 식은 $t=1$에서 분모가 $0$이 아니므로 대입하면 된다.","확인":"5","스킬":"D11"}]},"ns-c75fae526444":{"길":"각 항의 안쪽 변수를 바꿔 그래프에서 좌극한·우극한을 읽는다","단계":[{"제목":"첫째 항의 극한","힌트":"$x=-1$ 양쪽에서 $f(x)$는 각각 어떤 값에 가까워지는가?","식":["$\\lim_{x\\to-1-}f(x)=1$, $\\lim_{x\\to-1+}f(x)=1$","$\\lim_{x\\to-1}f(x)=1$"],"설명":"$x=-1$에서 함숫값은 $f(-1)=-1$이지만 극한은 함숫값과 무관하다. 좌극한과 우극한이 같으므로 극한이 존재한다.","확인":"1","스킬":"C2"},{"제목":"둘째 항의 극한","힌트":"$t=-x$로 놓으면 $x\\to1+$일 때 $t$는 어느 쪽에서 어떤 값으로 가까워지는가?","식":["$t=-x$로 놓으면 $x\\to1+$일 때 $t\\to-1-$","$\\lim_{x\\to1+}f(-x)=\\lim_{t\\to-1-}f(t)=1$"],"설명":"$x$가 $1$보다 큰 쪽에서 가까워지면 $-x$는 $-1$보다 작은 쪽에서 가까워진다. 그래프에서 $x<-1$인 부분은 $y=1$로 다가간다.","확인":"1","스킬":"T6","고비":true},{"제목":"셋째 항과 세 값의 합","힌트":"$t=x-1$로 놓으면 $x\\to2-$일 때 $t$는? $t\\to1-$일 때 $f(t)$의 값은?","식":["$t=x-1$로 놓으면 $x\\to2-$일 때 $t\\to1-$","$\\lim_{x\\to2-}f(x-1)=\\lim_{t\\to1-}f(t)=1$","$1+1+1=3$"],"설명":"$0<t<1$에서 그래프는 $y=t$ 꼴의 선분이고 $(1,\\ 1)$은 비어 있지만 $t\\to1-$이면 $y\\to1$이다. $f(1)=-1$은 극한에 영향을 주지 않는다.","확인":"3","스킬":"T6"}]},"ns-caf92d21b961":{"길":"접선 조건으로 반지름을 구하고 d를 a의 식으로 나타낸다","단계":[{"제목":"원의 반지름","힌트":"원이 직선 $x-y=0$에 접하므로 반지름은 중심에서 이 직선까지의 거리와 같다. 그 거리는?","식":["$r=\\frac{\\left|a-\\left(a-\\frac{1}{a}\\right)\\right|}{\\sqrt{1^{2}+1^{2}}}=\\frac{\\frac{1}{a}}{\\sqrt{2}}=\\frac{1}{\\sqrt{2}\\,a}$"],"설명":"접선과 중심 사이의 거리가 반지름이다. $a>1$이므로 $\\frac{1}{a}>0$이어서 절댓값이 그대로 벗겨진다.","확인":null,"스킬":"S5"},{"제목":"d를 a의 식으로","힌트":"원점에서 원 위의 점까지 거리의 최솟값은 원점에서 중심까지의 거리에서 반지름을 뺀 값이다. 중심까지의 거리는?","식":["$\\overline{\\mathrm{OC}}=\\sqrt{a^{2}+\\left(a-\\frac{1}{a}\\right)^{2}}=\\sqrt{2a^{2}-2+\\frac{1}{a^{2}}}$","$d=\\sqrt{2a^{2}-2+\\frac{1}{a^{2}}}-\\frac{1}{\\sqrt{2}\\,a}$"],"설명":"원점이 원 바깥에 있으므로 원점과 중심을 잇는 선분이 원과 만나는 점이 가장 가깝다. 그 거리는 중심까지의 거리에서 반지름을 뺀 값이다.","확인":null,"스킬":"S5","고비":true},{"제목":"극한값 계산","힌트":"$\\frac{d}{a}$에서 $a$를 $\\sqrt{a^{2}}$으로 보고 근호 안의 식을 $a^{2}$으로 나누면?","식":["$\\frac{d}{a}=\\sqrt{2-\\frac{2}{a^{2}}+\\frac{1}{a^{4}}}-\\frac{1}{\\sqrt{2}\\,a^{2}}$","$\\lim_{a\\to\\infty}\\frac{d}{a}=\\sqrt{2}$"],"설명":"$a>0$이므로 $a=\\sqrt{a^{2}}$이다. $\\frac{2}{a^{2}}$, $\\frac{1}{a^{4}}$, $\\frac{1}{\\sqrt{2}\\,a^{2}}$은 모두 $0$으로 간다.","확인":null,"스킬":"A11"}]},"ns-cce2cdf3696b":{"길":"안쪽 함수의 값과 접근 방향을 정한 뒤 바깥 함수의 값을 읽는다","단계":[{"제목":"첫째 항의 극한","힌트":"$x<-1$에서 $f(x)$의 값은? 그 값에서 $g$의 값은?","식":["$x<-1$이면 $f(x)=1$이므로 $g(f(x))=g(1)$","$g(1)=-1$이므로 $\\lim_{x\\to-1-}g(f(x))=-1$"],"설명":"$f$가 $x<-1$에서 상수 $1$이므로 안쪽 값이 변하지 않는다. $g(1)$은 $x=1$에서 속이 찬 점 $(1,\\ -1)$의 값으로 읽는다.","확인":"-1","스킬":"T6"},{"제목":"둘째 항의 극한","힌트":"$x>1$에서 $g(x)$의 값은? 그 값에서 $f$의 값은?","식":["$x>1$이면 $g(x)=-1$이므로 $f(g(x))=f(-1)$","$f(-1)=1$이므로 $\\lim_{x\\to1+}f(g(x))=1$"],"설명":"$f(-1)$은 $x=-1$에서 속이 찬 점 $(-1,\\ 1)$의 값이다. 이 항은 극한이 아니라 함숫값을 읽는다.","확인":"1","스킬":"T6"},{"제목":"셋째 항과 세 값의 합","힌트":"$x\\to0+$일 때 $f(x)$는 어느 쪽에서 어떤 값으로 가까워지는가? 그때 $g$의 값은?","식":["$x\\to0+$이면 $f(x)\\to-1+$ ($f(x)>-1$)","$t=f(x)$로 놓으면 $-1\\le t<1$에서 $g(t)=t$이므로 $\\lim_{t\\to-1+}g(t)=-1$","$-1+1+(-1)=-1$"],"설명":"$f$는 $x=0$ 근처에서 $-1$이 최솟값이므로 $f(x)$는 $-1$보다 큰 쪽에서 $-1$에 가까워진다. $g$의 그래프는 $t=-1$에서 시작하는 선분 $y=t$이다.","확인":"-1","스킬":"T6","고비":true}]},"ns-db9f28918cc8":{"길":"두 원의 교점 Q를 r로 나타내 직선 PQ의 x절편의 극한을 구한다","단계":[{"제목":"교점 Q의 좌표","힌트":"두 원의 방정식을 변끼리 빼면 교점의 $x$좌표는?","식":["$x^{2}+y^{2}=r^{2}$, $(x-2)^{2}+y^{2}=4$를 빼면 $4x-4=r^{2}-4$이므로 $x=\\frac{r^{2}}{4}$","$y^{2}=r^{2}-\\frac{r^{4}}{16}$에서 $y=\\frac{r}{4}\\sqrt{16-r^{2}}$","$\\mathrm{Q}\\left(\\frac{r^{2}}{4},\\ \\frac{r}{4}\\sqrt{16-r^{2}}\\right)$"],"설명":"첫째 식에서 둘째 식을 변끼리 빼면 $y^{2}$이 없어져 $x$만 남는다. $\\mathrm{Q}$의 $y$좌표가 양수이므로 양의 제곱근을 택한다.","확인":null,"스킬":"G1"},{"제목":"직선 PQ와 점 R의 좌표","힌트":"$\\mathrm{P}(0,\\ r)$와 $\\mathrm{Q}$를 지나는 직선의 기울기는? $y=0$일 때 $x$는?","식":["기울기 $=\\frac{\\frac{r}{4}\\sqrt{16-r^{2}}-r}{\\frac{r^{2}}{4}}=\\frac{\\sqrt{16-r^{2}}-4}{r}$","$y=\\frac{\\sqrt{16-r^{2}}-4}{r}x+r$에 $y=0$을 대입하면 $x=-\\frac{r^{2}}{\\sqrt{16-r^{2}}-4}$","$\\mathrm{R}\\left(-\\frac{r^{2}}{\\sqrt{16-r^{2}}-4},\\ 0\\right)$"],"설명":"$\\mathrm{P}$는 반지름이 $r$인 원이 $y$축과 만나는 점이므로 $(0,\\ r)$이고, 이것이 직선의 $y$절편이다.","확인":null,"스킬":"S4"},{"제목":"분모를 유리화해 정리","힌트":"분모 $\\sqrt{16-r^{2}}-4$에 $\\sqrt{16-r^{2}}+4$를 곱하면 분모는?","식":["$-\\frac{r^{2}}{\\sqrt{16-r^{2}}-4}=-\\frac{r^{2}\\left(\\sqrt{16-r^{2}}+4\\right)}{(16-r^{2})-16}=\\sqrt{16-r^{2}}+4$"],"설명":"$\\left(\\sqrt{16-r^{2}}-4\\right)\\left(\\sqrt{16-r^{2}}+4\\right)=-r^{2}$이므로 분자의 $r^{2}$과 약분된다. $r\\to0+$에서 분모가 $0$으로 가므로 이 정리가 필요하다.","확인":null,"스킬":"D11","고비":true},{"제목":"R의 극한 위치","힌트":"$r\\to0+$일 때 $\\sqrt{16-r^{2}}+4$는 어떤 값에 가까워지는가?","식":["$\\lim_{r\\to0+}\\left(\\sqrt{16-r^{2}}+4\\right)=4+4=8$","$\\mathrm{R}$의 $y$좌표는 $0$이므로 $\\mathrm{R}$은 $(8,\\ 0)$에 가까워진다"],"설명":"$r\\to0+$이면 $\\sqrt{16-r^{2}}\\to4$이다. 점의 $x$좌표만 극한을 취하고 $y$좌표는 계속 $0$이다.","확인":"8","스킬":"D11"}]},"ns-e003851befa9":{"길":"지름이 만드는 직각삼각형으로 대각선을 구해 S(r)를 쓰고 약분한다","단계":[{"제목":"지름 AB와 직각삼각형 APB","힌트":"원 $\\mathrm{O}$의 지름 $\\overline{\\mathrm{AB}}$를 그으면 $\\angle\\mathrm{APB}$의 크기는? $\\overline{\\mathrm{PB}}$의 길이는?","식":["$\\overline{\\mathrm{AB}}=2$, $\\angle\\mathrm{APB}=90^{\\circ}$, $\\overline{\\mathrm{AP}}=r$","$\\overline{\\mathrm{PB}}=\\sqrt{4-r^{2}}$"],"설명":"지름에 대한 원주각은 직각이다. 점 $\\mathrm{P}$는 점 $\\mathrm{A}$를 중심으로 하는 원 위에 있으므로 $\\overline{\\mathrm{AP}}=r$이고, 직각삼각형 $\\mathrm{APB}$에서 피타고라스 정리를 쓴다.","확인":null,"스킬":"S5"},{"제목":"대각선 PQ의 길이","힌트":"점 $\\mathrm{P}$에서 $\\overline{\\mathrm{AB}}$에 내린 수선의 길이는? 점 $\\mathrm{Q}$는 $\\mathrm{P}$와 어떤 관계인가?","식":["수선의 길이 $=\\frac{\\overline{\\mathrm{AP}}\\cdot\\overline{\\mathrm{PB}}}{\\overline{\\mathrm{AB}}}=\\frac{r\\sqrt{4-r^{2}}}{2}$","$\\overline{\\mathrm{PQ}}=2\\times\\frac{r\\sqrt{4-r^{2}}}{2}=r\\sqrt{4-r^{2}}$"],"설명":"직각삼각형의 넓이를 두 가지로 세면 (빗변)$\\times$(높이)$=$(직각을 낀 두 변의 곱)이다. 두 원이 직선 $\\mathrm{AB}$에 대해 대칭이므로 $\\mathrm{Q}$는 $\\mathrm{P}$의 대칭점이고 $\\overline{\\mathrm{PQ}}\\perp\\overline{\\mathrm{AB}}$이다.","확인":null,"스킬":"S8","고비":true},{"제목":"사각형의 넓이 S(r)","힌트":"두 대각선 $\\overline{\\mathrm{AR}}$, $\\overline{\\mathrm{PQ}}$는 서로 어떤 관계이고 길이는 각각?","식":["$\\overline{\\mathrm{AR}}=r$, $\\overline{\\mathrm{PQ}}=r\\sqrt{4-r^{2}}$","$S(r)=\\frac{1}{2}\\cdot r\\cdot r\\sqrt{4-r^{2}}=\\frac{r^{2}\\sqrt{4-r^{2}}}{2}$"],"설명":"$\\mathrm{R}$는 직선 $\\mathrm{AB}$ 위에서 $\\overline{\\mathrm{AR}}=r$인 점이고 $\\overline{\\mathrm{PQ}}$와 수직이다. 두 대각선이 수직인 사각형의 넓이는 $\\frac{1}{2}\\times$(대각선)$\\times$(대각선)이다.","확인":null,"스킬":"S8"},{"제목":"공통인수 약분","힌트":"$4-r^{2}$과 $8-r^{3}$을 각각 인수분해하면 공통으로 나오는 인수는?","식":["$4-r^{2}=(2-r)(2+r)$, $8-r^{3}=(2-r)\\left(4+2r+r^{2}\\right)$","$\\frac{S(r)}{\\sqrt{8-r^{3}}}=\\frac{r^{2}\\sqrt{(2-r)(2+r)}}{2\\sqrt{(2-r)\\left(4+2r+r^{2}\\right)}}=\\frac{r^{2}\\sqrt{2+r}}{2\\sqrt{4+2r+r^{2}}}$"],"설명":"$r\\to2-$이면 $2-r>0$이므로 $\\sqrt{2-r}$로 약분할 수 있다. $8-r^{3}$은 $a^{3}-b^{3}=(a-b)\\left(a^{2}+ab+b^{2}\\right)$로 인수분해한다.","확인":null,"스킬":"D11"},{"제목":"극한값 계산","힌트":"약분한 식에 $r=2$를 대입하면?","식":["$\\lim_{r\\to2-}\\frac{r^{2}\\sqrt{2+r}}{2\\sqrt{4+2r+r^{2}}}=\\frac{4\\cdot2}{2\\sqrt{12}}=\\frac{8}{4\\sqrt{3}}=\\frac{2\\sqrt{3}}{3}$"],"설명":"약분한 식은 $r=2$에서 분모가 $0$이 아니므로 그대로 대입한다. $\\sqrt{4}=2$, $\\sqrt{12}=2\\sqrt{3}$이다.","확인":null,"스킬":"D11"}]},"ns-e377bbcc3c56":{"길":"두 현의 길이를 x로 나타내 T(x)와 S(x)의 비를 약분한다","단계":[{"제목":"현 AB, CD의 길이","힌트":"$\\overline{\\mathrm{OQ}}$, $\\overline{\\mathrm{OP}}$를 $x$로 나타내고 직각삼각형 $\\mathrm{OQA}$, $\\mathrm{OPC}$에서 $\\overline{\\mathrm{AQ}}$, $\\overline{\\mathrm{CP}}$는?","식":["$\\overline{\\mathrm{OQ}}=2-2x$, $\\overline{\\mathrm{OP}}=2-x$","$\\overline{\\mathrm{AQ}}=\\sqrt{4-(2-2x)^{2}}=\\sqrt{8x-4x^{2}}$, $\\overline{\\mathrm{CP}}=\\sqrt{4-(2-x)^{2}}=\\sqrt{4x-x^{2}}$","$\\overline{\\mathrm{AB}}=2\\overline{\\mathrm{AQ}}$, $\\overline{\\mathrm{CD}}=2\\overline{\\mathrm{CP}}$"],"설명":"$\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OC}}=2$는 반지름이다. 현 $\\mathrm{AB}$, $\\mathrm{CD}$는 $\\overline{\\mathrm{OM}}$에 수직이므로 $\\mathrm{Q}$, $\\mathrm{P}$가 각각 현의 중점이다.","확인":null,"스킬":"S3"},{"제목":"S(x), T(x)의 식","힌트":"사다리꼴의 높이는 $\\overline{\\mathrm{PQ}}$이다. 높이는? 직사각형의 가로와 세로는?","식":["$\\overline{\\mathrm{PQ}}=x$","$S(x)=\\frac{1}{2}x\\left(\\overline{\\mathrm{AB}}+\\overline{\\mathrm{CD}}\\right)=x\\left(\\sqrt{8x-4x^{2}}+\\sqrt{4x-x^{2}}\\right)$","$T(x)=x\\cdot\\overline{\\mathrm{CD}}=2x\\sqrt{4x-x^{2}}$"],"설명":"$\\overline{\\mathrm{EF}}=\\overline{\\mathrm{CD}}$이고 직사각형의 세로는 두 평행한 현 사이의 거리 $x$이다.","확인":null,"스킬":"S12"},{"제목":"비 T/S의 약분","힌트":"$\\frac{T(x)}{S(x)}$에서 공통인수 $x$를 약분하고 근호 안에서 $\\sqrt{x}$를 묶어 약분하면?","식":["$\\frac{T(x)}{S(x)}=\\frac{2\\sqrt{4x-x^{2}}}{\\sqrt{8x-4x^{2}}+\\sqrt{4x-x^{2}}}=\\frac{2\\sqrt{4-x}}{\\sqrt{8-4x}+\\sqrt{4-x}}$"],"설명":"$x>0$이므로 분모·분자를 $x$로 약분할 수 있다. 남은 근호 안은 모두 $x$를 공통으로 가지므로 $\\sqrt{x}$로 묶어 약분한다.","확인":null,"스킬":"D11","고비":true},{"제목":"극한값 계산","힌트":"$x\\to0$이면 $\\sqrt{4-x}$, $\\sqrt{8-4x}$는 각각 어떤 값에 가까워지는가?","식":["$\\lim_{x\\to0}\\frac{2\\sqrt{4-x}}{\\sqrt{8-4x}+\\sqrt{4-x}}=\\frac{2\\cdot2}{2\\sqrt{2}+2}=\\frac{2}{\\sqrt{2}+1}=2\\left(\\sqrt{2}-1\\right)$"],"설명":"약분한 식은 $x=0$에서 분모가 $0$이 아니므로 대입한다. 분모를 유리화하면 $\\frac{2}{\\sqrt{2}+1}=2(\\sqrt{2}-1)$이다.","확인":null,"스킬":"D11"}]},"ns-e83d7aabfdcc":{"길":"두 삼각형이 내심을 공유함을 이용해 닮음비와 넓이로 S(x)를 쓴다","단계":[{"제목":"두 삼각형의 닮음비","힌트":"내접원의 중심 $\\mathrm{I}$에서 큰 삼각형의 각 변까지의 거리는?","식":["$\\mathrm{I}$에서 $\\triangle\\mathrm{ABC}$의 각 변까지의 거리 $=r$","$\\mathrm{I}$에서 $\\triangle\\mathrm{A'B'C'}$의 각 변까지의 거리 $=r+x$","닮음비 $r:(r+x)$"],"설명":"대응하는 변이 평행하고 변 사이의 거리가 모두 $x$이므로 $\\mathrm{I}$는 큰 삼각형의 내심이기도 하다. 닮음인 두 삼각형에서 내접원의 반지름의 비가 닮음비이다.","확인":null,"스킬":"S7","고비":true},{"제목":"두 삼각형의 넓이 P, Q","힌트":"내접원의 반지름과 둘레로 $\\triangle\\mathrm{ABC}$의 넓이를 나타내면? 넓이의 비는 닮음비의 제곱이다.","식":["$P=\\triangle\\mathrm{ABC}=\\frac{1}{2}rl$","$Q=\\triangle\\mathrm{A'B'C'}=\\frac{(r+x)^{2}}{r^{2}}P$"],"설명":"내심 $\\mathrm{I}$와 세 꼭짓점을 이은 세 삼각형은 높이가 모두 $r$이므로 넓이의 합이 $\\frac{1}{2}r\\times l$이다. 닮은 도형의 넓이의 비는 닮음비의 제곱이다.","확인":null,"스킬":"S1"},{"제목":"색칠된 넓이 S(x)","힌트":"$S(x)=Q-P$를 $P$로 묶으면?","식":["$S(x)=Q-P=\\left(\\frac{(r+x)^{2}}{r^{2}}-1\\right)P=\\frac{x(2r+x)}{r^{2}}\\cdot\\frac{rl}{2}=\\frac{lx(2r+x)}{2r}$"],"설명":"색칠된 영역은 큰 삼각형에서 작은 삼각형을 뺀 부분이다. $(r+x)^{2}-r^{2}=x(2r+x)$이다.","확인":null,"스킬":"S12"},{"제목":"극한값 계산","힌트":"$\\frac{2S(x)}{x^{2}}$을 $x$로 약분한 뒤 $x\\to\\infty$를 취하면?","식":["$\\frac{2S(x)}{x^{2}}=\\frac{l(2r+x)}{rx}=\\frac{l}{r}\\left(\\frac{2r}{x}+1\\right)$","$\\lim_{x\\to\\infty}\\frac{2S(x)}{x^{2}}=\\frac{l}{r}$"],"설명":"$l$, $r$은 $x$와 무관한 상수이다. $x\\to\\infty$이면 $\\frac{2r}{x}\\to0$이다.","확인":null,"스킬":"A11"}]},"ns-ea150ab273fe":{"길":"원의 중심이 직선 l 위에 있다는 조건으로 r(n)을 구해 극한을 본다","단계":[{"제목":"점 P와 직선 l의 y절편","힌트":"$\\frac{1}{3}x^{2}=nx$의 원점이 아닌 해는? 직선 $y=nx$에 수직인 직선의 기울기는?","식":["$\\frac{1}{3}x^{2}=nx$에서 $x=3n$이므로 $\\mathrm{P}\\left(3n,\\ 3n^{2}\\right)$","$l:\\ y=-\\frac{1}{n}(x-3n)+3n^{2}$","$s(n)=3n^{2}+3$"],"설명":"$n>0$이므로 원점이 아닌 해는 $x=3n$이다. 직선 $y=nx$에 수직인 직선의 기울기는 $-\\frac{1}{n}$이고, $x=0$을 대입한 값이 $y$절편이다.","확인":null,"스킬":"G9"},{"제목":"원의 중심의 조건","힌트":"원이 $x$축에 접하므로 중심의 $y$좌표는? 접점 $\\mathrm{P}$에서의 반지름은 접선 $y=nx$와 어떤 관계인가?","식":["중심 $\\mathrm{C}(a,\\ r)$ $(a>0)$이 직선 $l$ 위에 있으므로 $r=-\\frac{1}{n}(a-3n)+3n^{2}$","$a-3n=3n^{3}-nr=n\\left(3n^{2}-r\\right)$"],"설명":"$x$축에 접하는 원의 중심의 $y$좌표는 반지름 $r(n)$과 같다. 접점 $\\mathrm{P}$에서의 반지름은 접선에 수직이므로 중심은 $\\mathrm{P}$를 지나고 $y=nx$에 수직인 직선 $l$ 위에 있다.","확인":null,"스킬":"S5"},{"제목":"r(n)에 대한 방정식","힌트":"$\\overline{\\mathrm{CP}}=r$을 좌표로 쓰고 $a-3n=n\\left(3n^{2}-r\\right)$를 대입하면?","식":["$(a-3n)^{2}+\\left(3n^{2}-r\\right)^{2}=r^{2}$","$\\left(n^{2}+1\\right)\\left(3n^{2}-r\\right)^{2}=r^{2}$","$r^{2}-6\\left(n^{2}+1\\right)r+9n^{2}\\left(n^{2}+1\\right)=0$"],"설명":"$\\overline{\\mathrm{CP}}$는 반지름이므로 $\\overline{\\mathrm{CP}}^{2}=r^{2}$이다. $(a-3n)^{2}=n^{2}\\left(3n^{2}-r\\right)^{2}$이므로 공통인수 $\\left(3n^{2}-r\\right)^{2}$로 묶고, 전개해서 정리하면 $n^{2}$으로 나누어 떨어진다.","확인":null,"스킬":"S13","고비":true},{"제목":"알맞은 근 선택","힌트":"근의 공식으로 구한 두 근 중 $r(n)<s(n)$인 것은?","식":["$r=3\\left(n^{2}+1\\right)\\pm3\\sqrt{n^{2}+1}$","$r<s(n)=3\\left(n^{2}+1\\right)$이므로 $r(n)=3\\left(n^{2}+1\\right)-3\\sqrt{n^{2}+1}$"],"설명":"판별식의 $\\frac{1}{4}$은 $9\\left(n^{2}+1\\right)$이므로 근이 위와 같다. 중심은 기울기가 음수인 직선 $l$ 위에서 $a>0$인 점이므로 $y$절편 $s(n)$보다 아래에 있다.","확인":null,"스킬":"C2"},{"제목":"극한값 계산","힌트":"$s(n)-r(n)$을 먼저 정리하면?","식":["$s(n)-r(n)=3\\sqrt{n^{2}+1}$","$\\lim_{n\\to\\infty}\\frac{3\\sqrt{n^{2}+1}}{4n}=\\lim_{n\\to\\infty}\\frac{3}{4}\\sqrt{1+\\frac{1}{n^{2}}}=\\frac{3}{4}$"],"설명":"$n>0$이므로 $n=\\sqrt{n^{2}}$로 보고 근호 안에서 $n^{2}$으로 나눈다. $\\frac{1}{n^{2}}$은 $0$으로 간다.","확인":"3/4","스킬":"A11"}]},"ns-eb0bfc9ee232":{"길":"대칭으로 네 점을 한 문자로 잡고 두 변을 t로 나타내 넓이를 구한다","단계":[{"제목":"네 교점의 좌표","힌트":"두 곡선은 모두 원점과 직선 $y=x$에 대해 대칭이다. 한 교점을 $\\mathrm{D}\\left(a,\\ \\frac{1}{a}\\right)$로 두면 나머지 세 점은?","식":["$\\mathrm{D}\\left(a,\\ \\frac{1}{a}\\right)$, $\\mathrm{A}\\left(\\frac{1}{a},\\ a\\right)$, $\\mathrm{B}\\left(-a,\\ -\\frac{1}{a}\\right)$, $\\mathrm{C}\\left(-\\frac{1}{a},\\ -a\\right)$","$\\mathrm{D}$가 원 위의 점이므로 $a^{2}+\\frac{1}{a^{2}}=t$"],"설명":"$y=x$에 대해 대칭이면 $x$, $y$좌표를 서로 바꾼 점도 교점이고, 원점에 대해 대칭이면 두 좌표의 부호를 모두 바꾼 점도 교점이다.","확인":null,"스킬":"G11"},{"제목":"두 변 AD, AB의 길이","힌트":"$(a-\\frac{1}{a})^{2}$과 $(a+\\frac{1}{a})^{2}$을 $a^{2}+\\frac{1}{a^{2}}$로 나타내면?","식":["$\\overline{\\mathrm{AD}}=\\sqrt{\\left(a-\\frac{1}{a}\\right)^{2}+\\left(\\frac{1}{a}-a\\right)^{2}}=\\sqrt{2\\left(a^{2}+\\frac{1}{a^{2}}\\right)-4}=\\sqrt{2(t-2)}$","$\\overline{\\mathrm{AB}}=\\sqrt{\\left(\\frac{1}{a}+a\\right)^{2}+\\left(a+\\frac{1}{a}\\right)^{2}}=\\sqrt{2\\left(a^{2}+\\frac{1}{a^{2}}\\right)+4}=\\sqrt{2(t+2)}$"],"설명":"$\\mathrm{A}$와 $\\mathrm{C}$, $\\mathrm{B}$와 $\\mathrm{D}$가 원점에 대해 대칭이므로 두 대각선은 원의 지름이고 길이가 같다. 두 대각선이 서로 같고 서로를 이등분하므로 $\\mathrm{ABCD}$는 직사각형이다.","확인":null,"스킬":"A2","고비":true},{"제목":"넓이 f(t)","힌트":"직사각형의 넓이는 가로$\\times$세로이다. $f(t)$는?","식":["$f(t)=\\overline{\\mathrm{AD}}\\times\\overline{\\mathrm{AB}}=\\sqrt{2(t-2)}\\cdot\\sqrt{2(t+2)}=2\\sqrt{t^{2}-4}$"],"설명":"$t>2$이므로 두 근호 안이 모두 양수이고, 곱하면 $\\sqrt{4(t-2)(t+2)}=2\\sqrt{t^{2}-4}$이다.","확인":null,"스킬":"A2"},{"제목":"극한값 계산","힌트":"$\\frac{f(t)}{t}$에서 $t$를 $\\sqrt{t^{2}}$으로 보고 근호 안을 $t^{2}$으로 나누면?","식":["$\\lim_{t\\to\\infty}\\frac{2\\sqrt{t^{2}-4}}{t}=\\lim_{t\\to\\infty}2\\sqrt{1-\\frac{4}{t^{2}}}=2$"],"설명":"$t>0$이므로 $t=\\sqrt{t^{2}}$이다. $\\frac{4}{t^{2}}$은 $0$으로 간다.","확인":"2","스킬":"A11"}]},"ns-f178f24e0fa9":{"길":"그래프에서 세 한쪽 극한을 각각 읽어 더한다","단계":[{"제목":"세 한쪽 극한 읽기","힌트":"$x=-2$의 오른쪽, $x=0$의 왼쪽, $x=1$의 오른쪽에서 그래프는 각각 어떤 높이에 가까워지는가?","식":["$\\lim_{x\\to-2+}f(x)=1$","$\\lim_{x\\to0-}f(x)=1$","$\\lim_{x\\to1+}f(x)=1$"],"설명":"속이 빈 점 $(-2,\\ 1)$, $(0,\\ 1)$, $(1,\\ 1)$은 함숫값이 아니라 그래프가 다가가는 높이를 뜻한다. 속이 찬 점의 함숫값은 극한에 영향을 주지 않는다.","확인":null,"스킬":"C2","고비":true},{"제목":"세 값의 합","힌트":"세 극한값을 더하면?","식":["$1+1+1=3$"],"설명":"각 항의 극한이 모두 존재하므로 합의 값은 극한값의 합이다.","확인":"3","스킬":"C2"}]},"ns-f31934c2ad7b":{"길":"AQ를 x의 식으로 나타내고 분자를 유리화해 약분한다","단계":[{"제목":"f(x)의 식","힌트":"$\\overline{\\mathrm{OQ}}=3$이므로 직각삼각형 $\\mathrm{OPQ}$에서 $\\overline{\\mathrm{PQ}}$는? 직각삼각형 $\\mathrm{APQ}$에서 $f(x)$는?","식":["$\\overline{\\mathrm{PQ}}=\\sqrt{9-x^{2}}$","$f(x)=\\sqrt{(x+3)^{2}+\\left(\\sqrt{9-x^{2}}\\right)^{2}}=\\sqrt{6x+18}$"],"설명":"$\\overline{\\mathrm{OQ}}$는 반지름이므로 $3$이다. $\\overline{\\mathrm{AP}}=x+3$이고 직각삼각형 $\\mathrm{APQ}$에서 피타고라스 정리를 쓰면 $x^{2}$ 항이 없어진다.","확인":null,"스킬":"S3"},{"제목":"분자를 유리화해 약분","힌트":"$\\frac{6-f(x)}{3-x}$의 분모·분자에 $6+f(x)$를 곱하면 분자는?","식":["$\\frac{6-f(x)}{3-x}=\\frac{36-f(x)^{2}}{(3-x)\\left(6+f(x)\\right)}$","$36-f(x)^{2}=36-(6x+18)=6(3-x)$이므로 $\\frac{6-f(x)}{3-x}=\\frac{6}{6+f(x)}$"],"설명":"$f(x)^{2}=6x+18$을 대입하면 분자가 $6(3-x)$가 되어 분모의 $3-x$와 약분된다. $x\\to3-$에서 $x\\ne3$이므로 약분해도 된다.","확인":null,"스킬":"D3","고비":true},{"제목":"극한값 계산","힌트":"$x\\to3-$일 때 $f(x)$는 어떤 값에 가까워지는가?","식":["$\\lim_{x\\to3-}f(x)=\\sqrt{6\\cdot3+18}=6$","$\\lim_{x\\to3-}\\frac{6}{6+f(x)}=\\frac{6}{12}=\\frac{1}{2}$"],"설명":"$f(x)=\\sqrt{6x+18}$은 $x=3$에서 연속이므로 $f(x)\\to6$이다. 분모 $6+f(x)$는 $12$에 가까워진다.","확인":"1/2","스킬":"D3"}]},"ns-f3fa4f015d36":{"길":"ㄱ, ㄴ은 안쪽 변수의 접근 방향을, ㄷ은 역함수 그래프를 읽어 판정한다","단계":[{"제목":"ㄱ의 두 극한","힌트":"$t=\\frac{x+1}{x}$, $s=-\\frac{x}{x^{2}+1}$로 놓으면 $x\\to\\infty$일 때 $t$, $s$는 각각 어느 쪽에서 어떤 값으로 가까워지는가?","식":["$t=1+\\frac{1}{x}\\to1+$, $s=-\\frac{x}{x^{2}+1}\\to0-$","$\\lim_{t\\to1+}f(t)=-1$, $\\lim_{s\\to0-}f(s)=2$","곱이 $(-1)\\times2=-2$이므로 ㄱ은 참"],"설명":"$x\\to\\infty$이면 $\\frac{1}{x}>0$이므로 $t$는 $1$보다 큰 쪽에서 $1$로 가고, $s$는 음수이면서 $0$으로 간다. 그래프에서 $1<x<2$인 부분은 $(1,\\ -1)$을 향하고 $-1\\le x<0$인 부분은 $(0,\\ 2)$를 향한다.","확인":null,"스킬":"T6"},{"제목":"ㄴ의 두 극한","힌트":"$t=1-x$로 놓으면 $x\\to1-$일 때 $t$는? $s=-1+x$로 놓으면 $x\\to0-$일 때 $s$는?","식":["$x\\to1-$이면 $t=1-x\\to0+$이므로 $\\lim f(1-x)=\\lim_{t\\to0+}f(t)=1$","$x\\to0-$이면 $s=-1+x\\to-1-$이므로 $\\lim f(-1+x)=\\lim_{s\\to-1-}f(s)=-1$","곱이 $1\\times(-1)=-1$이므로 ㄴ은 거짓"],"설명":"$x$가 $1$보다 작은 쪽에서 가까워지면 $1-x$는 $0$보다 큰 쪽에서 $0$으로 간다. $x\\to0-$이면 $-1+x$는 $-1$보다 작은 쪽에서 $-1$로 간다. $x<-1$ 부분의 그래프는 $(-1,\\ -1)$을 향한다.","확인":"-1","스킬":"T6"},{"제목":"역함수의 식","힌트":"$f$의 그래프의 각 점 $(p,\\ q)$를 $(q,\\ p)$로 바꾸면 $f^{-1}(x)$는 구간마다 어떻게 되는가?","식":["$f^{-1}(x)=x$ $(-2\\le x<-1)$, $f^{-1}(-1)=2$","$f^{-1}(x)=x+2$ $(-1<x<0)$, $f^{-1}(x)=1-x$ $(0\\le x<1)$","$f^{-1}(x)=x-2$ $(1\\le x\\le2)$"],"설명":"$f$는 구간마다 일대일이고 치역이 서로 겹치지 않아 역함수가 있다. 구간을 이은 그래프는 $y=x$에 대해 대칭이어서 열린 구간에서는 $f^{-1}(x)$와 $f(x)$의 식이 같고, 속이 찬 점과 빈 점의 위치만 바뀐다.","확인":null,"스킬":"T1","고비":true},{"제목":"ㄷ의 판정과 선지 고르기","힌트":"구간의 경계 $a=-1,\\ 0,\\ 1$에서 $\\lim_{x\\to a+}f^{-1}(x)$와 $f(a)$를 비교하면?","식":["$a=-1$: $\\lim_{x\\to-1+}f^{-1}(x)=1=f(-1)$, $a=0$: $\\lim_{x\\to0+}f^{-1}(x)=1\\ne f(0)=2$","$a=1$: $\\lim_{x\\to1+}f^{-1}(x)=-1\\ne f(1)=0$이고 그 밖의 $a$에서는 같다","조건을 만족하는 $a$는 $0$, $1$이고 합이 $1\\ne0$이므로 ㄷ은 거짓. 옳은 것은 ㄱ뿐이다"],"설명":"경계가 아닌 점에서는 $a$ 근방에서 $f^{-1}(x)=f(x)$이고 $f$가 연속이므로 우극한이 $f(a)$와 같다. $a=-1$에서는 $f(-1)=1$이어서 같다.","확인":null,"스킬":"C3"}]},"ns-f9fea4113733":{"길":"R의 좌표로 두 길이를 쓰고 두 근호의 차를 유리화한다","단계":[{"제목":"점 M, R의 좌표","힌트":"$\\mathrm{M}$은 $\\overline{\\mathrm{PQ}}$의 중점이다. $\\mathrm{M}$과 같은 높이에서 곡선과 만나는 점 $\\mathrm{R}$의 $x$좌표는?","식":["$\\mathrm{M}\\left(t,\\ \\frac{\\sqrt{t}}{2}\\right)$","$\\sqrt{a}=\\frac{\\sqrt{t}}{2}$에서 $a=\\frac{t}{4}$","$\\mathrm{R}\\left(\\frac{t}{4},\\ \\frac{\\sqrt{t}}{2}\\right)$"],"설명":"$\\mathrm{R}$의 $y$좌표는 $\\mathrm{M}$과 같고 곡선 $y=\\sqrt{x}$ 위의 점이므로 $x$좌표는 $y$좌표의 제곱이다.","확인":null,"스킬":"S4"},{"제목":"PR, MR의 길이","힌트":"$\\overline{\\mathrm{MR}}$은 $x$축에 평행하다. 길이는? $\\overline{\\mathrm{PR}}$는 두 점 사이의 거리로 구하면?","식":["$\\overline{\\mathrm{MR}}=t-\\frac{t}{4}=\\frac{3}{4}t$","$\\overline{\\mathrm{PR}}=\\sqrt{\\left(\\frac{3}{4}t\\right)^{2}+\\left(\\frac{\\sqrt{t}}{2}\\right)^{2}}=\\sqrt{\\frac{9}{16}t^{2}+\\frac{1}{4}t}$"],"설명":"$\\overline{\\mathrm{PR}}$는 직각삼각형 $\\mathrm{PMR}$의 빗변이다. 가로가 $\\overline{\\mathrm{MR}}=\\frac{3}{4}t$이고 세로가 $\\overline{\\mathrm{PM}}=\\frac{\\sqrt{t}}{2}$이다.","확인":null,"스킬":"S3"},{"제목":"두 길이의 차를 유리화","힌트":"$\\infty-\\infty$ 꼴이다. $\\overline{\\mathrm{PR}}-\\overline{\\mathrm{MR}}$의 분모·분자에 $\\overline{\\mathrm{PR}}+\\overline{\\mathrm{MR}}$를 곱하면 분자는?","식":["$\\overline{\\mathrm{PR}}-\\overline{\\mathrm{MR}}=\\frac{\\overline{\\mathrm{PR}}^{2}-\\overline{\\mathrm{MR}}^{2}}{\\overline{\\mathrm{PR}}+\\overline{\\mathrm{MR}}}=\\frac{\\frac{1}{4}t}{\\sqrt{\\frac{9}{16}t^{2}+\\frac{1}{4}t}+\\frac{3}{4}t}$"],"설명":"$\\overline{\\mathrm{PR}}^{2}-\\overline{\\mathrm{MR}}^{2}=\\overline{\\mathrm{PM}}^{2}=\\frac{t}{4}$이다. 두 값이 모두 커지는 차이므로 곱하고 나누어 분자를 $t$의 일차식으로 만든다.","확인":null,"스킬":"A5","고비":true},{"제목":"극한값 계산","힌트":"분모·분자를 $t$로 나누면?","식":["$4\\lim_{t\\to\\infty}\\frac{\\frac{1}{4}t}{\\sqrt{\\frac{9}{16}t^{2}+\\frac{1}{4}t}+\\frac{3}{4}t}=4\\lim_{t\\to\\infty}\\frac{\\frac{1}{4}}{\\sqrt{\\frac{9}{16}+\\frac{1}{4t}}+\\frac{3}{4}}=4\\cdot\\frac{\\frac{1}{4}}{\\frac{3}{4}+\\frac{3}{4}}=\\frac{2}{3}$"],"설명":"$t>0$이므로 $t=\\sqrt{t^{2}}$로 보고 근호 안을 $t^{2}$으로 나눈다. $\\frac{1}{4t}$은 $0$으로 간다.","확인":"2/3","스킬":"A11"}]},"ns-fd9de4f4e0c9":{"길":"점근선의 교점이 대각선 위를 움직일 때 정사각형 변과 만나는 점을 센다","단계":[{"제목":"곡선의 모양","힌트":"$y=\\frac{1}{x-a}+a$의 점근선은? $x$와 $y$를 바꾸어도 같은 식인가?","식":["점근선 $x=a$, $y=a$이고 교점 $(a,\\ a)$는 직선 $y=x$ 위를 움직인다","$(x-a)(y-a)=1$이므로 곡선은 $y=x$에 대해 대칭"],"설명":"$y-a=\\frac{1}{x-a}$를 정리하면 $(x-a)(y-a)=1$이다. 두 점근선이 나누는 오른쪽 위 영역과 왼쪽 아래 영역에 곡선이 한 가지씩 있다.","확인":null,"스킬":"T4"},{"제목":"a가 1보다 조금 클 때","힌트":"왼쪽 변 $x=0$, 아랫변 $y=0$, 오른쪽 변 $x=3$, 윗변 $y=3$과 곡선이 만나는 점의 좌표는?","식":["$x=0$일 때 $y=a-\\frac{1}{a}$, $y=0$일 때 $x=a-\\frac{1}{a}$이고 $1<a<2$이면 $0<a-\\frac{1}{a}<3$","$x=3$일 때 $y=a+\\frac{1}{3-a}$, $y=3$일 때 $x=a+\\frac{1}{3-a}$이고 $a<2$이면 $a<a+\\frac{1}{3-a}<3$","$1<a<2$에서 네 변과 한 번씩 만나므로 $f(a)=4$, $\\lim_{a\\to1+}f(a)=4$"],"설명":"$a=1$이면 왼쪽 변·아랫변과는 꼭짓점 $\\mathrm{O}$ 한 점에서만 만나 $f(1)=3$이다. 극한값은 $a=1$에서의 값이 아니라 $1$보다 조금 큰 $a$에서의 값이다.","확인":"4","스킬":"G1","고비":true},{"제목":"a가 4보다 조금 작을 때","힌트":"$x=0$일 때 $y=a-\\frac{1}{a}$는 $3$과 어떤 관계인가? 오른쪽 변·윗변과는 어떤가?","식":["$a$가 $4$에 가까우면 $a-\\frac{1}{a}>3$이므로 왼쪽 변·아랫변과는 만나지 않는다","$x=3$일 때 $y=a-\\frac{1}{a-3}$, $y=3$일 때 $x=a-\\frac{1}{a-3}$이고 $a<4$이면 이 값이 $0$보다 크고 $3$보다 작다","오른쪽 변·윗변과 한 번씩 만나므로 $f(a)=2$, $\\lim_{a\\to4-}f(a)=2$"],"설명":"$a=4$이면 곡선은 꼭짓점 $\\mathrm{B}$ 한 점에서만 만나 $f(4)=1$이다. $a$가 $4$보다 조금 작으면 점근선이 바깥에 있고 곡선의 한 가지가 오른쪽 변과 윗변을 각각 지난다.","확인":"2","스킬":"T4"},{"제목":"두 극한값의 합","힌트":"구한 두 극한값을 더하면?","식":["$\\lim_{a\\to1+}f(a)+\\lim_{a\\to4-}f(a)=4+2=6$"],"설명":"함숫값 $f(1)$, $f(4)$가 아니라 극한값을 더한다.","확인":"6","스킬":"T4"}]},"ns-04d06f210c7b":{"길":"g를 f의 부호로 풀어 쓰고 x=0 근처의 극한을 보기마다 비교한다","단계":[{"제목":"g(x)의 그래프와 ㄱ","힌트":"$g(x)=\\frac{|f(x)|+f(x)}{2}$는 $f(x)$의 부호에 따라 어떤 식이 되는가?","식":["$f(x)\\ge0$이면 $g(x)=f(x)$, $f(x)<0$이면 $g(x)=0$","$g(x)=-x$ $(-1\\le x<0)$, $g(0)=1$, $g(x)=0$ $(0<x\\le1)$","$\\lim_{x\\to0}g(x)=0\\ne g(0)=1$이므로 ㄱ은 거짓"],"설명":"$f\\ge0$이면 $\\frac{f+f}{2}=f$이고 $f<0$이면 $\\frac{-f+f}{2}=0$이다. $f(0)=1>0$이므로 $g(0)=1$이지만, $0$의 양쪽에서 $g$는 $0$으로 간다.","확인":null,"스킬":"G5"},{"제목":"ㄴ의 우극한","힌트":"$x\\to0+$일 때 $f(x)$와 $f(-x)$는 각각 어떤 값에 가까워지는가?","식":["$\\lim_{x\\to0+}f(x)=-1$","$\\lim_{x\\to0+}f(-x)=\\lim_{u\\to0-}f(u)=0$","$\\lim_{x\\to0+}h(x)=-1-0=-1\\ne1$이므로 ㄴ은 거짓"],"설명":"$x\\to0+$이면 $-x\\to0-$이다. 그래프에서 $x>0$인 부분은 $(0,\\ -1)$을 향하고 $x<0$인 부분은 $(0,\\ 0)$을 향한다.","확인":"-1","스킬":"T6","고비":true},{"제목":"ㄷ의 연속 판정","힌트":"$x=0$에서 $g(x)h(x)$의 우극한, 좌극한, 함숫값을 각각 구하면?","식":["$x\\to0+$: $g\\to0$, $h\\to-1$이므로 $g(x)h(x)\\to0$. $x\\to0-$: $g\\to0$, $h\\to1$이므로 $g(x)h(x)\\to0$","$g(0)h(0)=1\\times\\{f(0)-f(0)\\}=0$","우극한, 좌극한, 함숫값이 모두 $0$이므로 ㄷ은 참. 옳은 것은 ㄷ뿐이다"],"설명":"$x\\to0-$이면 $f(x)\\to0$, $f(-x)\\to f(0+)=-1$이므로 $h(x)\\to0-(-1)=1$이다. $g$가 $0$으로 가고 $h$는 유한한 값으로 가므로 곱은 $0$으로 간다.","확인":null,"스킬":"C3"}]},"ns-055442e47cd1":{"길":"g의 극한값과 f의 주기성으로 f(a)=0을 만족하는 a를 찾는다","단계":[{"제목":"g(x)의 극한","힌트":"$x\\to1$일 때 분모·분자가 모두 $0$이다. 분모를 $\\sqrt{x+3}-2$로 묶고 유리화하면?","식":["$g(x)=\\frac{(x-1)(x+1)}{4\\left(\\sqrt{x+3}-2\\right)}=\\frac{(x-1)(x+1)\\left(\\sqrt{x+3}+2\\right)}{4(x-1)}=\\frac{(x+1)\\left(\\sqrt{x+3}+2\\right)}{4}$","$\\lim_{x\\to1}g(x)=\\frac{2\\cdot4}{4}=2$"],"설명":"$4\\sqrt{x+3}-8=4\\left(\\sqrt{x+3}-2\\right)$이고 $\\left(\\sqrt{x+3}-2\\right)\\left(\\sqrt{x+3}+2\\right)=x-1$이다. $x\\ne1$이므로 $x-1$로 약분한다.","확인":"2","스킬":"D11"},{"제목":"f의 주기와 t→2에서의 극한","힌트":"$f(x-2)=f(x+2)$는 어떤 뜻인가? $t\\to2$일 때 $f(t)$의 좌극한과 우극한은?","식":["$f(x+4)=f(x)$이므로 $f$는 주기가 $4$인 함수","$\\lim_{t\\to2-}f(t)=f(2)=0$","$\\lim_{t\\to2+}f(t)=\\lim_{t\\to-2+}f(t)=(-4)(-5)(0)=0$이므로 $\\lim_{t\\to2}f(t)=0$"],"설명":"$x$ 자리에 $x+2$를 넣으면 $f(x)=f(x+4)$이다. $t>2$인 부분은 주기 $4$로 $t-4$의 값과 같아서 $t\\to2+$는 $t-4\\to-2+$로 옮겨 계산한다.","확인":null,"스킬":"T2","고비":true},{"제목":"연속 조건","힌트":"$f(g(x))$가 $x=1$에서 연속이려면 극한값과 $f(g(1))$이 같아야 한다. $f(a)$의 값은?","식":["$\\lim_{x\\to1}f(g(x))=\\lim_{t\\to2}f(t)=0$","$f(g(1))=f(a)$이므로 $f(a)=0$"],"설명":"$g(x)\\to2$이고 $f$는 $t=2$에서 극한과 함숫값이 모두 $0$이므로 $\\lim_{x\\to1}f(g(x))=0$이다. 연속이면 함숫값 $f(a)$도 $0$이어야 한다.","확인":null,"스킬":"T6"},{"제목":"f(a)=0인 a의 최솟값","힌트":"구간 $(-2,\\ 2]$에서 $f(x)=0$의 해는? 주기 $4$로 $a>6$인 해를 찾으면?","식":["$(x-2)(2x-1)(x+2)=0$에서 $x=\\frac{1}{2}$ 또는 $x=2$ $(-2<x\\le2)$","$f(x)=0$의 해는 $x=\\frac{1}{2}+4k$, $2+4k$ ($k$는 정수)","$a>6$이면 $a=\\frac{17}{2},\\ 10,\\ \\frac{25}{2},\\ \\cdots$이므로 최솟값은 $\\frac{17}{2}$"],"설명":"$a=6=2+4\\cdot1$은 $a>6$을 만족하지 않아 $2+4k$ 꼴에서는 $10$부터이다. $\\frac{1}{2}+4k$ 꼴에서는 $\\frac{17}{2}$이므로 $\\frac{17}{2}<10$이다.","확인":"17/2","스킬":"T2"}]},"ns-0692c528dcd3":{"길":"f(-x)를 식으로 쓰고 x=±2에서 극한과 함숫값을 비교한다","단계":[{"제목":"f(-x)의 식","힌트":"$|x|>2$, $|x|<2$, $x=2$, $x=-2$에서 $f(-x)$의 값은 각각?","식":["$|x|>2$일 때 $f(-x)=0$, $|x|<2$일 때 $f(-x)=2-|x|$","$x=2$일 때 $f(-x)=f(-2)=2$, $x=-2$일 때 $f(-x)=f(2)=-2$"],"설명":"$f(-x)$는 $f$의 식에 $x$ 대신 $-x$를 넣은 값이다. $|x|$와 $|-x|$는 같으므로 $x=\\pm2$ 이외에서는 식이 그대로이고, $x=\\pm2$에서만 값이 서로 바뀐다.","확인":null,"스킬":"G4"},{"제목":"f(x)+f(-x)의 불연속점","힌트":"$x=\\pm2$에서 $f(x)+f(-x)$의 값은? $x\\to\\pm2$일 때의 극한은?","식":["$|x|<2$일 때 $4-2|x|$, $|x|\\ge2$일 때 $0$ ($x=2$: $-2+2=0$, $x=-2$: $2+(-2)=0$)","$x\\to\\pm2$이면 $4-2|x|\\to0$이고 함숫값도 $0$이므로 모든 점에서 연속, $m=0$"],"설명":"$x=\\pm2$에서 $f(x)$의 값 $\\mp2$가 $f(-x)$의 값 $\\pm2$와 합쳐져 $0$이 되므로 극한 $0$과 맞는다.","확인":"0","스킬":"C2"},{"제목":"f(x)-f(-x)의 불연속점","힌트":"$x=\\pm2$에서 $f(x)-f(-x)$의 값은? $x\\to\\pm2$일 때의 극한은?","식":["$|x|\\ne2$일 때 $0$, $x=2$일 때 $-2-2=-4$, $x=-2$일 때 $2-(-2)=4$","$x\\to\\pm2$일 때 극한은 $0$이지만 함숫값은 $\\mp4$이므로 불연속","불연속인 $x$의 값은 $2$, $-2$이므로 $n=2$"],"설명":"$|x|<2$에서 $(2-|x|)-(2-|x|)=0$이므로 $x\\to\\pm2$의 극한은 $0$이다. 함숫값이 극한과 다른 점은 모두 불연속이다.","확인":"2","스킬":"C2","고비":true},{"제목":"m-2n의 값","힌트":"$m=0$, $n=2$를 $m-2n$에 대입하면?","식":["$m-2n=0-2\\cdot2=-4$"],"설명":"$m$은 $f(x)+f(-x)$, $n$은 $f(x)-f(-x)$의 불연속점의 개수이다.","확인":"-4","스킬":"C2"}]},"ns-07c243d87c34":{"길":"x=1과 x=0 근처에서 좌극한·우극한·함숫값을 그래프에서 읽어 보기를 판정한다","단계":[{"제목":"ㄱ의 극한","힌트":"$x\\to1-$, $x\\to1+$일 때 $f(x)$, $g(x)$는 각각 어떤 값에 가까워지는가?","식":["$x\\to1-$: $f(x)\\to1$, $g(x)\\to-1$이므로 $f(x)g(x)\\to-1$","$x\\to1+$: $f(x)=-1$, $g(x)=1$이므로 $f(x)g(x)=-1$","좌극한과 우극한이 모두 $-1$이므로 ㄱ은 참"],"설명":"속이 빈 점 $(1,\\ 1)$과 $(1,\\ -1)$은 그래프가 다가가는 값이다. $x>1$에서는 $f$, $g$가 상수함수이다.","확인":null,"스킬":"C2"},{"제목":"ㄴ의 연속 판정","힌트":"$x=1$에서 $f(1)$, $g(1)$의 값은? (속이 찬 점을 읽는다)","식":["$f(1)=-1$, $g(1)=1$","$f(1)g(1)=-1=\\lim_{x\\to1}f(x)g(x)$이므로 ㄴ은 참"],"설명":"연속이려면 극한값과 함숫값이 같아야 한다. 극한값은 ㄱ에서 $-1$로 구했다.","확인":null,"스킬":"C3"},{"제목":"ㄷ의 연속 판정","힌트":"$x=1$에서 $f(x)+g(x)$의 좌극한, 우극한, 함숫값은?","식":["$\\lim_{x\\to1-}\\left\\{f(x)+g(x)\\right\\}=1+(-1)=0$, $\\lim_{x\\to1+}\\left\\{f(x)+g(x)\\right\\}=-1+1=0$","$f(1)+g(1)=-1+1=0$이므로 ㄷ은 참"],"설명":"각 함수는 $x=1$에서 불연속이지만 두 함수의 합은 좌극한, 우극한, 함숫값이 모두 같아 연속이다.","확인":null,"스킬":"C3"},{"제목":"ㄹ의 연속 판정과 선지 고르기","힌트":"$x\\to0$일 때 $g(x)$는 어느 쪽에서 어떤 값에 가까워지는가? $f(g(0))$는?","식":["$x\\to0$일 때 $g(x)\\to1-$이므로 $\\lim_{x\\to0}f(g(x))=\\lim_{t\\to1-}f(t)=1$","$f(g(0))=f(1)=-1\\ne1$이므로 ㄹ은 거짓","옳은 것은 ㄱ, ㄴ, ㄷ이다"],"설명":"$g$의 꼭짓점이 $(0,\\ 1)$이므로 $x=0$ 양쪽에서 $g(x)$는 $1$보다 작은 값이다. $f$는 $t=1$에서 좌극한이 $1$이고 함숫값이 $-1$이다.","확인":null,"스킬":"T6","고비":true}]},"ns-09f0aa0b2ecb":{"길":"f(-x)의 끊김과 |f(x)|의 극한을 구해 보기를 하나씩 판정한다","단계":[{"제목":"ㄱ의 극한","힌트":"$x\\to-1+$일 때 $-x$는 어느 쪽에서 어떤 값으로 가까워지는가?","식":["$t=-x$로 놓으면 $x\\to-1+$일 때 $t\\to1-$","$\\lim_{x\\to-1+}f(-x)=\\lim_{t\\to1-}f(t)=-1\\ne0$이므로 ㄱ은 거짓"],"설명":"$x$가 $-1$보다 큰 쪽에서 가까워지면 $-x$는 $1$보다 작은 쪽에서 $1$로 간다. 그래프에서 $x<1$인 곡선은 $(1,\\ -1)$을 향한다.","확인":"-1","스킬":"T6"},{"제목":"f(-x)의 식과 끊어지는 점","힌트":"$f(-x)$는 $f(x)$를 $y$축에 대칭시킨 그래프이다. 구간마다 식과 끊어지는 점의 양쪽 극한은?","식":["$x\\le-1$일 때 $f(-x)=-x-1$, $-1<x<1$일 때 $f(-x)=x^{3}$, $x\\ge1$일 때 $f(-x)=x-2$","$x=-1$: 좌극한 $0$, 우극한 $-1$이므로 불연속","$x=1$: 좌극한 $1$, 우극한 $-1$이므로 불연속"],"설명":"$f$의 각 구간에서 $x$ 대신 $-x$를 넣는다. $-1<x<1$에서는 $-(-x)^{3}=x^{3}$이다.","확인":null,"스킬":"G4"},{"제목":"ㄴ의 a의 값","힌트":"$x=\\pm1$에서 $\\left(x^{2}-a^{2}\\right)f(-x)$의 좌극한·우극한·함숫값이 같으려면 $x^{2}-a^{2}$는 어떤 값이어야 하는가?","식":["$x=1$: 좌극한 $(1-a^{2})\\cdot1$, 우극한·함숫값 $(1-a^{2})\\cdot(-1)$이므로 $1-a^{2}=0$","$x=-1$: 좌극한·함숫값 $(1-a^{2})\\cdot0=0$, 우극한 $(1-a^{2})\\cdot(-1)$이므로 $1-a^{2}=0$","$a=\\pm1$이고 합이 $0$이므로 ㄴ은 참"],"설명":"다른 점에서는 $f(-x)$가 연속이므로 곱도 연속이다. 끊어지는 점에서는 곱해지는 $x^{2}-a^{2}$가 $0$이 되어야 좌우의 차이가 사라진다.","확인":null,"스킬":"C1","고비":true},{"제목":"ㄷ의 |f(x)| 불연속점과 선지 고르기","힌트":"$f$가 끊어지는 $x=-1$, $x=1$에서 $|f(x)|$의 좌극한, 우극한, 함숫값은?","식":["$x=-1$: 좌극한 $|-1|=1$, 우극한 $|1|=1$, 함숫값 $|f(-1)|=1$이므로 연속","$x=1$: 좌극한 $|-1|=1$, 우극한·함숫값 $|0|=0$이므로 불연속","$|f(x)|$는 $x=1$에서만 불연속이므로 ㄷ은 참. 옳은 것은 ㄴ, ㄷ이다"],"설명":"$x=-1$에서는 $f$가 부호만 바꾸어 뛰었으므로 절댓값을 씌우면 끊김이 사라진다. $x=1$에서는 크기가 달라 끊김이 남는다.","확인":null,"스킬":"G5"}]},"ns-0f9c6812c3ab":{"길":"경계 x=-1, 1의 좌극한·우극한·함숫값을 적고 보기마다 판정한다","단계":[{"제목":"경계에서의 f의 값","힌트":"$x=-1$, $x=1$에서 $f$의 좌극한, 우극한, 함숫값을 적으면?","식":["$x=-1$: 좌극한 $1$, 우극한 $1$, 함숫값 $0$","$x=1$: 좌극한 $1$, 우극한 $-1$, 함숫값 $-1$"],"설명":"$x<-1$에서 $f=x+2$는 $x\\to-1-$일 때 $1$이고, $-1<x<1$에서 $f=x^{2}$은 $x\\to-1+$, $x\\to1-$일 때 모두 $1$이다. $x\\ge1$에서 $f=x-2$이다.","확인":null,"스킬":"C2"},{"제목":"ㄱ의 극한","힌트":"$x\\to1+$일 때 $f(x)$와 $f(-x)$는 각각 어떤 값에 가까워지는가?","식":["$x\\to1+$이면 $f(x)=x-2\\to-1$","$-x\\to-1-$이므로 $f(-x)=-x+2\\to1$","$\\lim_{x\\to1+}\\left\\{f(x)+f(-x)\\right\\}=-1+1=0$이므로 ㄱ은 참"],"설명":"$x$가 $1$보다 큰 쪽에서 가까워지면 $-x$는 $-1$보다 작은 쪽에서 가까워지므로 $x<-1$일 때의 식 $f(t)=t+2$를 쓴다.","확인":null,"스킬":"T6"},{"제목":"ㄴ의 연속 판정","힌트":"$f(x)-|f(x)|$는 $f(x)$의 부호에 따라 어떤 식이 되는가? $x=-1$ 근처에서 $f(x)$의 부호는?","식":["$f(x)\\ge0$이면 $f(x)-|f(x)|=0$, $f(x)<0$이면 $2f(x)$","$x=-1$ 근처에서 $f(x)>0$이고 $f(-1)=0$이므로 값이 모두 $0$이어서 연속","$x=1$: 좌극한 $0$, 우극한·함숫값 $-2$이므로 불연속. ㄴ은 $x=-1$에서 연속이므로 거짓"],"설명":"$x=-1$에서 함숫값이 $0$으로 튀어 있어도 $f-|f|$는 $f\\ge0$인 곳에서 항상 $0$이므로 끊기지 않는다.","확인":null,"스킬":"G5"},{"제목":"ㄷ의 a의 존재와 선지 고르기","힌트":"$a=1$이면 $f(x)f(x-1)$이 끊어질 수 있는 $x=-1,\\ 0,\\ 1,\\ 2$에서 두 인수는 각각 어떤가?","식":["$f(x)$는 $x=-1,\\ 1$에서, $f(x-1)$은 $x=0,\\ 2$에서 끊어진다","끊어지지 않는 쪽 인수의 값이 $0$이다: $x=-1$에서 $f(-2)=0$, $x=1$에서 $f(0)=0$, $x=0$에서 $f(0)=0$, $x=2$에서 $f(2)=0$","좌극한, 우극한, 함숫값이 모두 $0$이므로 $a=1$에서 연속. ㄷ은 거짓이고 옳은 것은 ㄱ뿐이다"],"설명":"끊어지는 쪽 인수는 좌극한과 우극한이 모두 유한하므로, $0$으로 가는 인수와 곱하면 좌극한과 우극한이 모두 $0$이다. 그 밖의 점에서는 두 인수가 모두 연속이다.","확인":null,"스킬":"C3","고비":true}]},"ns-104dc353f079":{"길":"g가 f의 끊긴 점의 값을 지나는 x와 좌우 접근 방향으로 n, m을 센다","단계":[{"제목":"f가 끊어지는 점","힌트":"그림에서 $f$가 불연속인 $x$의 값과 그 점의 좌극한, 우극한, 함숫값은?","식":["$f$는 $x=-1,\\ 0,\\ 1,\\ 2$에서 불연속","$x=-1$: 좌극한 $1$, 우극한 $0$ / $x=0$: 양쪽 극한 $1$, 함숫값 $0$ / $x=1$: 좌극한 $2$, 우극한 $0$ / $x=2$: 좌극한 $1$, 함숫값 $0$"],"설명":"$f(g(x))$는 $g(x)$의 값이 이 네 값을 지나는 $x$에서만 불연속일 수 있다. 다른 값에서는 $f$가 연속이므로 합성함수도 연속이다.","확인":null,"스킬":"C2"},{"제목":"g(x)=c인 x의 개수","힌트":"$g(x)=-4(x-1)^{2}+2$는 $x=1$에서 최댓값 $2$를 갖는다. $g(x)=2,\\ 1,\\ 0,\\ -1$인 $x$는 각각 몇 개인가?","식":["$g(x)=c$이면 $(x-1)^{2}=\\frac{2-c}{4}$","$c=2$: $x=1$ ($1$개)","$c=1,\\ 0,\\ -1$: $x=1\\pm\\frac{\\sqrt{2-c}}{2}$ (각각 $0<x<2$ 안에서 $2$개)"],"설명":"$g$는 $x=1$에 대해 대칭이고 $x=1$에서 극대이다. $-2<c<2$인 값은 $x=1$의 양쪽에서 한 번씩 가진다.","확인":null,"스킬":"G7"},{"제목":"불연속인 x의 개수 n","힌트":"각 $c$에서 $g(x)$가 어느 쪽에서 $c$로 가까워지는지와 $f$의 극한·함숫값을 비교하면?","식":["$c=2$: $g(x)\\to2-$, $\\lim_{t\\to2-}f(t)=1\\ne f(2)=0$이므로 불연속 ($1$개)","$c=1,\\ -1$: $g$가 $c$의 양쪽에서 가까워져 좌극한 $\\ne$ 우극한이므로 불연속 ($2+2=4$개)","$c=0$: $\\lim_{t\\to0}f(t)=1\\ne f(0)=0$이므로 불연속 ($2$개), $n=1+4+2=7$"],"설명":"$g(x)=1$인 점에서는 한쪽에서 $g\\to1-$, 다른 쪽에서 $g\\to1+$이므로 $f$의 좌극한 $2$와 우극한 $0$이 갈라진다. $g(x)=-1$도 같다.","확인":"7","스킬":"T6"},{"제목":"m의 조건을 k로 바꾸기","힌트":"$g(a)=k$라 하자. $a\\ne1$이면 $g(a+x)$, $g(a-x)$는 $k$의 어느 쪽에서 가까워지는가?","식":["$a\\ne1$이면 $g$가 $a$ 근처에서 단조이므로 $g(a+x)$, $g(a-x)$는 $k+$, $k-$로 서로 반대쪽에서 $k$로 간다","$\\lim_{x\\to0+}\\left\\{f(g(a+x))+f(g(a-x))\\right\\}=\\lim_{t\\to k+}f(t)+\\lim_{t\\to k-}f(t)=1$","$a=1$이면 $g(1\\pm x)\\to2-$이므로 합이 $1+1=2\\ne1$"],"설명":"$a=1$은 극대점이라 양쪽의 값이 모두 $2$보다 작은 쪽에서 $2$로 가므로 조건을 만족하지 않는다. $a\\ne1$이면 $k$의 좌극한과 우극한의 합이 $1$이어야 한다.","확인":null,"스킬":"T6","고비":true},{"제목":"f(k+)+f(k-)=1인 k","힌트":"$k$의 범위마다 $\\lim_{t\\to k+}f(t)+\\lim_{t\\to k-}f(t)$를 구해 $1$이 되는 $k$를 찾으면?","식":["$-2<k<-1$: $-2k>2$이므로 해가 없다. $k=-1$: $1+0=1$이므로 성립","$-1<k<1$, $k\\ne0$: $2(k+1)=1$에서 $k=-\\frac{1}{2}$ (성립). $k=0$: $1+1=2$, $k=1$: $2+0=2$이므로 불성립","$1<k<2$: $f$가 $0$에서 $1$까지 연속으로 증가하므로 $f(k)=\\frac{1}{2}$인 $k=\\beta$가 하나 있다"],"설명":"$f$가 연속인 $k$에서는 좌극한과 우극한이 모두 $f(k)$이므로 $2f(k)=1$, 즉 $f(k)=\\frac{1}{2}$이어야 한다. $k=-1$은 좌극한 $1$, 우극한 $0$의 합이 $1$이 되는 끊어진 점이다.","확인":null,"스킬":"C2"},{"제목":"m과 n+m의 값","힌트":"각 $k$에 대해 $g(a)=k$인 $a$는 $0<a<2$에서 몇 개인가?","식":["$k=-1,\\ -\\frac{1}{2},\\ \\beta$는 모두 $-2<k<2$이므로 $g(a)=k$인 $a$가 $2$개씩","$m=3\\times2=6$","$n+m=7+6=13$"],"설명":"$g$는 $x=1$에 대해 대칭이고 $-2<k<2$인 값은 양쪽에서 한 번씩 가지므로 $a$가 두 개씩 나온다.","확인":"13","스킬":"G7"}]},"ns-12b03aea3f21":{"길":"식을 h(x)=h(t) 꼴로 바꿔 수평선과 곡선의 교점 개수로 g를 구한다","단계":[{"제목":"h(x)로 바꾸기","힌트":"$t\\{f(x)+4\\}=x\\{f(t)+4\\}$의 양변을 $xt$로 나누면?","식":["$\\frac{f(x)+4}{x}=\\frac{f(t)+4}{t}$","$h(x)=\\frac{f(x)+4}{x}$로 놓으면 $g(t)$는 곡선 $y=h(x)$와 직선 $y=h(t)$의 교점의 개수"],"설명":"$x>0$, $t>0$이므로 양변을 $xt$로 나눌 수 있다. $t$를 고정하면 오른쪽은 상수 $h(t)$이다.","확인":null,"스킬":"G1"},{"제목":"h(x)의 식과 그래프","힌트":"$0<x\\le4$, $x>4$에서 $h(x)$를 각각 정리하면? 증가·감소하는 구간은?","식":["$0<x\\le4$: $h(x)=\\frac{x^{2}-4x+4}{x}=x+\\frac{4}{x}-4$ ($x=2$에서 최솟값 $0$, $h(4)=1$)","$x>4$: $h(x)=\\frac{-2x+12}{x}=-2+\\frac{12}{x}$ (감소, $h(6)=0$)","$h$는 $x=2$까지 감소, $2\\le x\\le4$에서 증가, $x\\ge4$에서 감소하는 연속함수"],"설명":"$x+\\frac{4}{x}-4=\\frac{(x-2)^{2}}{x}\\ge0$이고 등호는 $x=2$일 때이다. $x=4$에서 두 식의 값이 모두 $1$이므로 이어진다.","확인":null,"스킬":"D4"},{"제목":"수평선과의 교점의 개수","힌트":"$c=h(t)$의 범위마다 직선 $y=c$와 $y=h(x)$의 교점의 개수를 세면?","식":["$c>1$: $1$개, $c=1$: $2$개 ($x=1,\\ 4$)","$0<c<1$: $3$개, $c=0$: $2$개 ($x=2,\\ 6$)","$c<0$: $1$개"],"설명":"$c>1$이면 $x<1$쪽의 가파른 감소 부분과만 만난다. $0<c<1$이면 세 부분과 모두 만난다. $c=0$이면 $x=2$는 접점이고 $x=6$에서 한 번 더 만난다.","확인":null,"스킬":"D6","고비":true},{"제목":"g(t)의 불연속점의 합","힌트":"$t$의 범위마다 $h(t)$가 어느 구간에 있는지 보고 $g(t)$를 구하면? $g$가 끊어지는 $t$는?","식":["$0<t<1$: $g=1$, $1<t<2$, $2<t<4$, $4<t<6$: $g=3$, $t>6$: $g=1$","$t=1,\\ 2,\\ 4,\\ 6$에서 $g=2$이므로 모두 불연속","$1+2+4+6=13$"],"설명":"$h(1)=h(4)=1$, $h(2)=h(6)=0$이다. 이 네 점에서 $g$의 값 $2$가 주변의 값 $1$ 또는 $3$과 다르다.","확인":"13","스킬":"D6"}]},"ns-1332db8e5bc9":{"길":"f가 정수값을 가로지르는 x를 찾아 가우스 기호가 끊어지는 점을 센다","단계":[{"제목":"f의 그래프의 모양","힌트":"$f(x)$는 각 구간에서 증가인가 감소인가? 최솟값은?","식":["$0<x\\le2$: $f(x)=-x+3$은 감소하며 $f(2)=1$","$2<x<4$: $f(x)=(x-2)^{2}+1$은 증가하며 $x\\to4-$일 때 $5$에 가까워진다","$f$는 $0<x<4$에서 연속이고 $x=2$에서 최솟값 $1$"],"설명":"$x=2$에서 두 식의 값이 모두 $1$이므로 이어진다. 치역은 $1\\le f(x)<5$이다.","확인":null,"스킬":"G7"},{"제목":"불연속이 되는 조건","힌트":"$[f(x)]$는 $f(x)$가 정수값을 어떻게 지날 때 끊어지는가? $x=2$ 근처($f=1$)는?","식":["$[f(x)]$는 $f(x)=n$ ($n$은 정수)이고 그 근처에 $f(x)<n$인 값도 있는 점에서 불연속","$f(x)=1$은 $x=2$뿐이고 그 양쪽에서 $f(x)>1$이므로 $[f(x)]=1$로 일정해 연속","$1\\le f(x)<5$이므로 확인할 정수값은 $2,\\ 3,\\ 4$"],"설명":"정수값을 아래에서 위로, 또는 위에서 아래로 가로지르면 가우스 기호의 값이 갑자기 바뀐다. 최솟값에 닿기만 하는 $x=2$에서는 값이 바뀌지 않는다.","확인":null,"스킬":"N7","고비":true},{"제목":"f(x)=2, 3, 4인 x의 개수","힌트":"각 정수값 $n$에 대해 $f(x)=n$의 해를 두 구간에서 구하면?","식":["$f(x)=2$: $-x+3=2$에서 $x=1$, $(x-2)^{2}+1=2$에서 $x=3$ ($2$개)","$f(x)=3$: $-x+3=3$은 $x=0$으로 범위 밖, $(x-2)^{2}=2$에서 $x=2+\\sqrt{2}$ ($1$개). $f(x)=4$: $x=2+\\sqrt{3}$ ($1$개)","불연속인 $x$는 $1,\\ 3,\\ 2+\\sqrt{2},\\ 2+\\sqrt{3}$의 $4$개"],"설명":"$0<x\\le2$에서 $f$는 $1$ 이상 $3$ 미만의 값을 가져 $f=3$은 나오지 않는다. $2<x<4$에서 $f$는 $1$에서 $5$까지 증가하며 $2,\\ 3,\\ 4$를 한 번씩 지난다.","확인":"4","스킬":"N7"}]},"ns-15af01766090":{"길":"구간 경계에서 이웃한 두 식의 값이 같다는 조건으로 점화식을 만든다","단계":[{"제목":"경계에서의 두 식","힌트":"$x=\\frac{1}{2^{n}}$은 어느 두 구간의 경계인가? 양쪽에서 쓰는 식은?","식":["$x=\\frac{1}{2^{n}}$은 $\\left(\\frac{1}{2^{n+1}},\\ \\frac{1}{2^{n}}\\right]$의 오른쪽 끝이고 $\\left(\\frac{1}{2^{n}},\\ \\frac{1}{2^{n-1}}\\right]$의 왼쪽 끝","왼쪽에서는 $f(x)=a_{n+1}x^{n+1}$, 오른쪽에서는 $f(x)=a_{n}x^{n}$"],"설명":"구간의 경계에서만 식이 바뀌므로 연속 조건은 경계에서 두 식의 값이 같다는 것이다.","확인":null,"스킬":"C2"},{"제목":"점화식","힌트":"$x=\\frac{1}{2^{n}}$에서 두 식의 값이 같다고 놓으면?","식":["$a_{n+1}\\left(\\frac{1}{2^{n}}\\right)^{n+1}=a_{n}\\left(\\frac{1}{2^{n}}\\right)^{n}$","양변을 $\\left(\\frac{1}{2^{n}}\\right)^{n}$으로 나누면 $a_{n+1}\\cdot\\frac{1}{2^{n}}=a_{n}$이므로 $\\frac{a_{n+1}}{a_{n}}=2^{n}$"],"설명":"$x=\\frac{1}{2^{n}}$이므로 $x^{n+1}=x^{n}\\cdot\\frac{1}{2^{n}}$이다. $a_{n}\\ne0$이므로 비를 구할 수 있다.","확인":null,"스킬":"A9","고비":true},{"제목":"a_11 / a_10의 값","힌트":"$n=10$을 대입하면?","식":["$\\frac{a_{11}}{a_{10}}=2^{10}=1024$"],"설명":"점화식 $\\frac{a_{n+1}}{a_{n}}=2^{n}$은 모든 자연수 $n$에서 성립하므로 $n=10$을 넣는다.","확인":"1024","스킬":"P7"}]},"ns-15c44996ba28":{"길":"a=0과 판별식의 부호로 실근의 개수를 구간별로 적고 보기를 판정한다","단계":[{"제목":"a의 값에 따른 f(a)","힌트":"$a=0$이면 방정식은? $a\\ne0$이면 판별식 $\\frac{D}{4}$는?","식":["$a=0$: $-4x+2=0$이므로 $f(0)=1$","$a\\ne0$: $\\frac{D}{4}=(a-2)^{2}+a(a-2)=2(a-1)(a-2)$","$a<1$ 또는 $a>2$ ($a\\ne0$): $f(a)=2$, $a=1,\\ 2$: $f(a)=1$, $1<a<2$: $f(a)=0$"],"설명":"$a=0$이면 일차방정식이라 근이 하나이다. $a\\ne0$이면 판별식의 부호로 실근의 개수를 정한다.","확인":null,"스킬":"C2","고비":true},{"제목":"ㄱ의 판정","힌트":"$a=-1$ 근처에서 $f(a)$의 값은? $f(-1)$은?","식":["$a<0$에서 $f(a)=2$이므로 $\\lim_{a\\to-1}f(a)=2$","$f(-1)=2$이므로 $\\lim_{a\\to-1}f(a)=f(-1)$이고 ㄱ은 참"],"설명":"$a=-1$은 $a<0$ 구간의 안쪽 점이어서 $f$가 상수 $2$이다.","확인":null,"스킬":"C2"},{"제목":"ㄴ의 판정","힌트":"$a=0,\\ 1,\\ 2$에서 $f(a)$의 좌극한과 우극한을 비교하면?","식":["$a=0$: 좌극한 $2$, 우극한 $2$이므로 같다","$a=1$: 좌극한 $2$, 우극한 $0$. $a=2$: 좌극한 $0$, 우극한 $2$이므로 다르다","좌극한 $\\ne$ 우극한인 $c$는 $1$, $2$의 $2$개이므로 ㄴ은 거짓"],"설명":"$f$의 값이 바뀌는 곳은 $a=0,\\ 1,\\ 2$뿐이다. $a=0$에서는 함숫값만 다르고 양쪽 극한은 같다.","확인":"2","스킬":"C2"},{"제목":"ㄷ의 판정과 선지 고르기","힌트":"극한과 함숫값이 다른 $a$를 모두 찾으면?","식":["$a=0$: $\\lim_{a\\to0}f(a)=2\\ne f(0)=1$이므로 불연속","$a=1,\\ 2$: 좌극한과 우극한이 달라 불연속","불연속인 점은 $0,\\ 1,\\ 2$의 $3$개이므로 ㄷ은 거짓. 옳은 것은 ㄱ뿐이다"],"설명":"$a=0$에서는 극한이 존재하지만 함숫값과 달라서 불연속이다. 그래서 ㄴ의 $2$개에 $a=0$이 더해진다.","확인":null,"스킬":"C2"}]},"ns-19b2eb3e7f96":{"길":"곱이 연속인 두 경우로 나눠 t 후보를 구하고 조건 (가)로 거른다","단계":[{"제목":"연속이 되는 경우 나누기","힌트":"$f(x+3)$을 정리하면? $f(x)g(x)$가 $x=t$에서 연속이 되는 경우는 어떻게 나뉘는가?","식":["$g(x)=2x-t$ $(x\\le t)$, $g(x)=f(x+3)=(x+3)^{2}-6(x+3)+t=x^{2}+t-9$ $(x>t)$","$f$는 연속이므로 $f(x)g(x)$가 $x=t$에서 연속인 경우는 (i) $g$가 $x=t$에서 연속, (ii) $f(t)=0$"],"설명":"$g$가 $x=t$에서 불연속일 때 $f(t)\\ne0$이면 곱의 좌극한과 우극한이 달라진다. $f(t)=0$이면 $g$의 좌극한과 우극한이 유한하므로 곱의 극한과 함숫값이 모두 $0$이다.","확인":null,"스킬":"C2"},{"제목":"g가 연속인 경우","힌트":"$x=t$에서 $g$의 좌극한, 우극한, 함숫값이 같으려면?","식":["$g(t)=2t-t=t$이므로 좌극한과 함숫값은 같다","$\\lim_{x\\to t+}g(x)=t^{2}+t-9$이므로 $t=t^{2}+t-9$에서 $t^{2}=9$","$t=3$ 또는 $t=-3$"],"설명":"$x\\le t$에서 $g(x)=2x-t$는 연속이므로 우극한만 $g(t)=t$와 같으면 된다.","확인":null,"스킬":"D12"},{"제목":"f(t)=0인 경우","힌트":"$f(t)=t^{2}-6t+t$를 $0$으로 놓으면?","식":["$f(t)=t^{2}-5t=0$에서 $t=0$ 또는 $t=5$"],"설명":"이 경우에는 $g$의 연속 여부와 관계없이 $f(x)g(x)$가 $x=t$에서 연속이다.","확인":null,"스킬":"C2"},{"제목":"조건 (가)로 거르고 합 구하기","힌트":"$f(x)=x^{2}-6x+t$는 $-1<x<1$에서 감소한다. 이 구간에 근이 있으려면 $f(-1)$, $f(1)$의 부호는?","식":["$f(-1)=7+t>0$, $f(1)=t-5<0$이므로 $-7<t<5$","후보 $t=3,\\ -3,\\ 0,\\ 5$ 중 $t=5$는 범위 밖이어서 제외한다 ($f(x)=x^{2}-6x+5$의 근 $1$, $5$는 열린구간 $(-1,\\ 1)$에 없다)","$t=3,\\ -3,\\ 0$이므로 합은 $3+(-3)+0=0$"],"설명":"$f(x)=(x-3)^{2}+t-9$는 $x<3$에서 감소하므로 $-1<x<1$에 근이 있을 조건은 양 끝값의 부호가 서로 다른 것이다. 끝값이 $0$이면 근이 열린구간 밖에 있다.","확인":"0","스킬":"G8","고비":true}]},"ns-1ba34cfa643d":{"길":"꼭짓점이 y=x 위를 움직이는 V자와 정사각형의 교점 개수 그래프로 보기를 판정한다","단계":[{"제목":"f(k)의 값 정리","힌트":"$y=|2x-2k|+k$의 꼭짓점은 어디를 지나는가? $k$에 따라 정사각형과 만나는 점의 개수는?","식":["$y=2|x-k|+k$는 꼭짓점 $(k,\\ k)$가 직선 $y=x$ 위를 움직이는 $\\mathrm{V}$ 모양","$k<-4$: $0$, $k=-4$: $1$, $-4<k<-\\frac{4}{3}$: $2$, $k=-\\frac{4}{3}$: $3$, $-\\frac{4}{3}<k<-1$: $4$","$k=-1$: $3$, $-1<k<1$: $2$, $k=1$: $1$, $k>1$: $0$"],"설명":"교점의 개수가 바뀌는 $k$는 꼭짓점이 정사각형의 변 위에 놓이는 $k=\\pm1$과, 한 가지가 정사각형의 꼭짓점 $(-2,\\ 0)$을 지나는 $k$이다. 왼쪽 가지 $y=3k-2x$가 $(-2,\\ 0)$을 지나면 $k=-\\frac{4}{3}$, 오른쪽 가지 $y=2x-k$가 지나면 $k=-4$이다.","확인":null,"스킬":"G1","고비":true},{"제목":"ㄱ의 판정","힌트":"$k=-4,\\ -\\frac{4}{3},\\ -1,\\ 1$ 각각에서 좌극한과 우극한을 비교하면?","식":["$k=-4$: 좌극한 $0$, 우극한 $2$. $k=-\\frac{4}{3}$: 좌극한 $2$, 우극한 $4$","$k=-1$: 좌극한 $4$, 우극한 $2$. $k=1$: 좌극한 $2$, 우극한 $0$","네 점 모두 좌극한 $\\ne$ 우극한이므로 극한값이 존재하지 않는 값은 $4$개이고 ㄱ은 참"],"설명":"보기에서는 $f$의 변수를 $x$로 쓰므로 $k$ 자리에 $x$를 넣어 읽는다. 그 밖의 값에서는 $f$가 상수이므로 극한이 존재한다.","확인":null,"스킬":"G5"},{"제목":"ㄴ의 판정","힌트":"$f$가 불연속인 $x$의 값을 모두 모아 더하면?","식":["불연속인 값은 극한이 없는 $-4,\\ -\\frac{4}{3},\\ -1,\\ 1$뿐이다","합 $=-4-\\frac{4}{3}-1+1=-\\frac{16}{3}\\ne-4$이므로 ㄴ은 거짓"],"설명":"그 밖의 값에서는 $f$가 상수라 연속이다. 이 네 점은 모두 좌극한과 우극한이 달라 불연속이다.","확인":"-16/3","스킬":"G5"},{"제목":"ㄷ의 판정과 선지 고르기","힌트":"$t\\to\\infty$일 때 $\\frac{t}{t+1}$은 어느 쪽에서 어디로 가까워지는가? $t\\to-\\infty$일 때 $\\frac{3-t}{t-2}$는?","식":["$\\frac{t}{t+1}=1-\\frac{1}{t+1}\\to1-$이므로 $\\lim f\\left(\\frac{t}{t+1}\\right)=\\lim_{k\\to1-}f(k)=2$","$\\frac{3-t}{t-2}=-1+\\frac{1}{t-2}\\to-1-$이므로 $\\lim f\\left(\\frac{3-t}{t-2}\\right)=\\lim_{k\\to-1-}f(k)=4$","합 $=2+4=6\\ne4$이므로 ㄷ은 거짓. 옳은 것은 ㄱ뿐이다"],"설명":"$t\\to\\infty$이면 $\\frac{1}{t+1}>0$이므로 $1$보다 작은 쪽에서 $1$로 간다. $t\\to-\\infty$이면 $\\frac{1}{t-2}<0$이므로 $-1$보다 작은 쪽에서 $-1$로 간다.","확인":null,"스킬":"T6"}]},"ns-1ef11a923b71":{"길":"x=1의 좌극한·우극한·함숫값을 합성 횟수마다 차례로 따라간다","단계":[{"제목":"x=1에서 f의 세 값","힌트":"$x=1$의 왼쪽, 오른쪽에서 $f(x)$가 가까워지는 값과 $f(1)$은?","식":["$f(1-)=2-$ (아래에서 $2$로), $f(1)=2$, $f(1+)=1+$ (위에서 $1$로)","$f$는 $x=1$에서 불연속이므로 $n=1$은 안 된다"],"설명":"그래프에서 $0<x\\le1$인 선분은 $(1,\\ 2)$로 이어지고, $1<x\\le2$인 선분은 속이 빈 점 $(1,\\ 1)$에서 시작한다. 값과 함께 가까워지는 방향도 적어 둔다.","확인":null,"스킬":"C6"},{"제목":"f²의 세 값","힌트":"$f^{2}(x)=f(f(x))$이다. $f(x)$가 $2-$, $2$, $1+$일 때 $f$의 값은 각각?","식":["$f^{2}(1-)=f(2-)=3-$, $f^{2}(1)=f(2)=3$, $f^{2}(1+)=f(1+)=1+$","$f^{2}$도 $x=1$에서 불연속이므로 $n=2$는 안 된다"],"설명":"$x\\to1-$이면 $f(x)\\to2-$이므로 $f$에 다시 넣을 때 $t\\to2-$의 극한을 읽는다. 그래프에서 $x=2$의 왼쪽 선분은 $(2,\\ 3)$으로 올라간다.","확인":null,"스킬":"T6"},{"제목":"f³의 세 값","힌트":"$f^{3}(x)=f^{2}(f(x))$이다. $f(x)$가 $2-$, $2$, $1+$일 때 $f^{2}$의 값은 각각?","식":["$f^{3}(1-)=f^{2}(2-)=f(3-)=1+$ ($f^{2}(2-)=f\\left(f(2-)\\right)=f(3-)$)","$f^{3}(1)=f^{2}(2)=f(3)=1$, $f^{3}(1+)=f^{2}(1+)=1+$","세 값이 모두 $1$이므로 $f^{3}$은 $x=1$에서 연속"],"설명":"$f(3-)$은 $x=3$의 왼쪽에서 곡선이 $1$로 내려오는 값이므로 위에서 $1$에 가까워진다. 방향 표시($+$)가 달라도 극한값과 함숫값이 같으면 연속이다.","확인":null,"스킬":"T6","고비":true},{"제목":"k와 f^k(1)+k의 값","힌트":"연속이 되는 최소의 $n$이 $k$이다. $f^{k}(1)+k$는?","식":["$k=3$","$f^{3}(1)+3=1+3=4$"],"설명":"$n=1,\\ 2$에서는 불연속이고 $n=3$에서 처음 연속이다.","확인":"4","스킬":"C6"}]},"ns-1f07ba6f7719":{"길":"외접과 내접으로 나눠 중심의 위치를 구하고 r 구간마다 원의 개수를 센다","단계":[{"제목":"x축에 접하는 원의 중심","힌트":"$x$축에 접하는 원의 중심의 $y$좌표는? 원 $\\mathrm{C}$와 만날 수 있는 것은 어느 쪽 원인가?","식":["중심 $(h,\\ r)$ 또는 $(h,\\ -r)$","중심이 $(h,\\ -r)$인 원은 $y\\le0$에 있고 원 $\\mathrm{C}$는 $2\\le y\\le4$에 있어 만나지 않는다","따라서 중심은 $(h,\\ r)$"],"설명":"$x$축에 접하는 원의 중심은 $x$축에서 반지름만큼 떨어져 있다. $x$축 아래쪽 원은 $x$축에 접하며 아래에 놓이므로 위쪽의 원 $\\mathrm{C}$와 한 점에서도 만나지 않는다.","확인":null,"스킬":"S5"},{"제목":"외접하는 경우","힌트":"두 원이 바깥에서 접하면 중심 사이의 거리는? 이때 $h^{2}$은?","식":["$h^{2}+(r-3)^{2}=(r+1)^{2}$에서 $h^{2}=8(r-1)$","$r<1$: 없음, $r=1$: $h=0$으로 $1$개, $r>1$: $h=\\pm\\sqrt{8(r-1)}$로 $2$개"],"설명":"외접이면 중심 사이의 거리가 두 반지름의 합 $r+1$이다. $h^{2}\\ge0$이어야 하므로 $r\\ge1$이다.","확인":null,"스킬":"S5"},{"제목":"내접하는 경우","힌트":"한 원이 다른 원 안에서 접하면 중심 사이의 거리는 반지름의 차이다. 이때 $h^{2}$은?","식":["$h^{2}+(r-3)^{2}=(r-1)^{2}$에서 $h^{2}=4(r-2)$","$r<2$: 없음, $r=2$: $h=0$으로 $1$개, $r>2$: $h=\\pm\\sqrt{4(r-2)}$로 $2$개"],"설명":"반지름의 차이의 제곱은 $r$이 $1$보다 작아도 $(r-1)^{2}$이므로 같은 식이 된다. $r<2$이면 $h^{2}<0$이어서 내접하는 원이 없다.","확인":null,"스킬":"S5","고비":true},{"제목":"f(r)와 불연속점의 개수","힌트":"두 경우를 합쳐 $r$의 구간마다 $f(r)$를 구하면?","식":["$0<r<1$: $0$, $r=1$: $1$, $1<r<2$: $2$, $r=2$: $2+1=3$, $2<r<4$: $2+2=4$","좌극한과 우극한이 함숫값과 다른 $r=1,\\ 2$에서 불연속이므로 $m=2$","$f(1)+f(2)+m=1+3+2=6$"],"설명":"$r=1$에서는 좌극한 $0$, 함숫값 $1$, 우극한 $2$이고 $r=2$에서는 좌극한 $2$, 함숫값 $3$, 우극한 $4$이다. 외접하는 원과 내접하는 원은 $h^{2}$ 값이 달라 서로 다른 원이다.","확인":"6","스킬":"C2"}]},"ns-21126dc3e0af":{"길":"정점 (0,4)를 지나는 직선이 접하거나 평행해지는 순간을 경계로 g를 구간별로 센다","단계":[{"제목":"f의 그래프와 정점 (0, 4)","힌트":"$f(x)=-x^{2}+2x+3$을 완전제곱꼴로 쓰면? 정점 $(0,\\ 4)$는 그래프의 어디에 있는가?","식":["$x\\ge-1$일 때 $f(x)=-(x-1)^{2}+4$, 꼭짓점 $(1,\\ 4)$, $f(-1)=0$, $f(3)=0$","$x<-1$일 때 $f(x)=-x-1$은 $(-1,\\ 0)$에서 이어지는 기울기 $-1$인 반직선"],"설명":"정점 $(0,\\ 4)$는 $y$축 위에서 곡선보다 위에 있고 꼭짓점의 높이 $4$와 같은 높이이다. 직선 $l$은 이 정점을 축으로 돌아간다.","확인":null,"스킬":"G3"},{"제목":"교점의 개수가 바뀌는 직선","힌트":"정점 $(0,\\ 4)$를 지나는 직선이 곡선에 접하는 경우, 왼쪽 반직선과 평행한 경우, 수직인 경우의 $t$는?","식":["접하는 직선 $y=4$: $t=-5$ ($-t-1=4$) 또는 $t=1$ ($f(1)=4$)","왼쪽 반직선과 평행한 직선 $y=-x+4$: $-x^{2}+2x+3=-x+4$에서 $x=\\frac{3\\pm\\sqrt{5}}{2}$","수직인 직선 $x=0$: $t=0$"],"설명":"직선의 기울기가 바뀌는 동안 교점의 개수는 접하는 순간, 한 곡선과 평행해지는 순간, 수직이 되는 순간에만 달라진다. 직선 $l$이 곡선 위의 점 $(t,\\ f(t))$를 지나므로, 위 직선들이 곡선과 만나는 점의 $x$좌표가 곧 경계가 되는 $t$의 값이다.","확인":null,"스킬":"G3"},{"제목":"구간별 g(t)의 값","힌트":"각 $t$의 구간에서 직선과 곡선의 교점의 개수는?","식":["$-6\\le t<-5$: $3$, $t=-5$: $2$, $-5<t\\le0$: $1$","$0<t\\le\\frac{3-\\sqrt{5}}{2}$: $2$, $\\frac{3-\\sqrt{5}}{2}<t<1$: $3$, $t=1$: $2$","$1<t<\\frac{3+\\sqrt{5}}{2}$: $3$, $\\frac{3+\\sqrt{5}}{2}\\le t\\le4$: $2$"],"설명":"경계 사이에서는 개수가 바뀌지 않으므로 각 구간에서 $t$를 하나 골라 직선과 곡선의 교점을 세면 된다. 경계값에서는 접하거나 평행해서 개수가 따로 정해진다.","확인":null,"스킬":"G1","고비":true},{"제목":"불연속점의 개수와 합","힌트":"$g(t)$의 값이 좌우와 다르거나 좌우가 서로 다른 $t$를 모두 찾으면?","식":["불연속인 $t$는 $-5,\\ 0,\\ \\frac{3-\\sqrt{5}}{2},\\ 1,\\ \\frac{3+\\sqrt{5}}{2}$의 $5$개이므로 $n=5$","$s=-5+0+\\frac{3-\\sqrt{5}}{2}+1+\\frac{3+\\sqrt{5}}{2}=-1$","$n+s=5+(-1)=4$"],"설명":"$\\frac{3-\\sqrt{5}}{2}$와 $\\frac{3+\\sqrt{5}}{2}$는 합이 $3$이므로 근호가 사라진다.","확인":"4","스킬":"G1"}]},"ns-22f14363f74e":{"길":"연속과 (나)로 f 의 꼴을 정하고 (다)로 a 를 하나로 고른다","단계":[{"제목":"연속 조건으로 f(x) 의 꼴 정하기","힌트":"구간의 양 끝 $x=a\\pm3$ 에서 $f(x)$ 와 $2x-2$ 는 어떤 관계여야 할까?","식":["$f(a-3)=2(a-3)-2,\\ f(a+3)=2(a+3)-2$","$f(x)-(2x-2)=(x-a+3)(x-a-3)$","$f(x)=(x-a+3)(x-a-3)+2x-2$"],"설명":"구간의 두 끝점에서 $f(x)=2x-2$ 가 되어야 이어진다. 최고차항의 계수가 $1$ 인 이차식 $f(x)-(2x-2)$ 의 두 근이 $a-3,\\ a+3$ 이므로 위처럼 쓸 수 있다.","확인":null,"스킬":"D12"},{"제목":"(나)에서 g(5)=0 조건 세우기","고비":true,"힌트":"$x\\to5$ 일 때 분모가 $0$ 이 되는데 극한이 존재하려면 $g(5)$ 는 얼마여야 할까?","식":["$g(5)=0$","$f(5)=(8-a)(2-a)+8=0$"],"설명":"분모가 $0$ 에 가까워지므로 분자 $g(x)$ 도 $x=5$ 에서 $0$ 이어야 한다. $5$ 가 구간 밖이면 $g(5)=2\\times5-2=8$ 이므로 $5$ 는 구간 안에 있고 $f(5)=0$ 이다.","확인":null,"스킬":"D11"},{"제목":"a 의 후보 구하기","힌트":"$(8-a)(2-a)+8=0$ 을 $a$ 에 대한 이차방정식으로 정리하면?","식":["$a^{2}-10a+24=0$","$(a-4)(a-6)=0$","$a=4\\ \\text{또는}\\ a=6$"],"설명":"$(8-a)(2-a)=a^{2}-10a+16$ 이므로 $8$ 을 더해 인수분해한다.","확인":null,"스킬":"C2"},{"제목":"(다) 조건으로 a 를 하나로 정하기","힌트":"두 값 각각에 대해 $f(a-3)$ 의 부호를 따져 (다)를 만족하는 쪽은?","식":["$a=4:\\ f(x)=(x-1)(x-5),\\ f(a-3)=f(1)=0$","$a=6:\\ f(x)=(x-5)^{2},\\ f(a-3)=f(3)=4>0$","$a=6$"],"설명":"(다)가 성립하려면 $f(a-3)>0$ 이어야 한다. $a=4$ 이면 $f(1)=0$ 이어서 조건에 맞지 않고, $a=6$ 일 때 모든 조건을 만족한다.","확인":"6","스킬":"C2"},{"제목":"f(8) 구하기","힌트":"$f(x)=(x-5)^{2}$ 에 $x=8$ 을 넣으면?","식":["$f(8)=(8-5)^{2}=9$"],"설명":"$a=6$ 에서 $f(x)=(x-5)^{2}$ 이므로 $x=8$ 을 대입한다.","확인":"9","스킬":"A6"}]},"ns-262c553dfeca":{"길":"(나)로 세 점을 얻고 x=1 대칭으로 점을 늘려 직선과의 교점을 센다","단계":[{"제목":"(나)에서 세 점의 함숫값 읽기","힌트":"분모가 $0$ 이 되는 $x$ 에서 극한이 존재하려면 분자는 어떤 값이어야 할까?","식":["$f(-2)=0$","$f(1)+1=0\\ \\Rightarrow\\ f(1)=-1$","$f(3)-7=0\\ \\Rightarrow\\ f(3)=7$"],"설명":"각 극한에서 분모가 $0$ 에 가까워지므로 분자가 $0$ 으로 가야 한다. $f$ 가 연속이므로 분자의 함숫값이 $0$ 이다.","확인":null,"스킬":"D11"},{"제목":"대칭으로 f(-1) 과 점 늘리기","힌트":"$f(1-x)=f(1+x)$ 에 $x=2$ 를 넣으면 $f(-1)$ 과 같은 값은?","식":["$f(-1)=f(3)=7$","$f(4)=f(-2)=0$"],"설명":"(가)는 $x=1$ 에 대해 대칭이라는 뜻이다. $x=2$ 를 넣으면 $f(-1)=f(3)$, $x=3$ 을 넣으면 $f(-2)=f(4)$ 이다.","확인":"7","스킬":"T2"},{"제목":"교점 개수 n 구하기","고비":true,"힌트":"$h(x)=f(x)-(2x+1)$ 의 부호를 $x=-1,\\ 1,\\ 3$ 에서 보면?","식":["$h(-1)=7-(-1)=8>0$","$h(1)=-1-3=-4<0$","$h(3)=7-7=0$","$(-1,\\ 1)$ 에서 근 하나, $x=3$ 에서 근 하나"],"설명":"$f$ 가 연속이므로 $h$ 의 부호가 바뀌는 $(-1,\\ 1)$ 에 근이 있고, $h(3)=0$ 이므로 $x=3$ 도 근이다. 두 근은 모두 $(-2,\\ 4)$ 안에 있으므로 보장되는 개수는 $2$ 이다.","확인":"2","스킬":"G1"},{"제목":"f(-1)+n 계산하기","힌트":"$f(-1)=7$, $n=2$ 를 더하면?","식":["$f(-1)+n=7+2=9$"],"설명":"앞에서 구한 $f(-1)$ 과 $n$ 을 더한다.","확인":"9","스킬":"G1"}]},"ns-30e010311a42":{"길":"교점 수가 바뀌는 t 를 찾아 f(t) 를 정리하고 연속 조건으로 a, b 를 정한다","단계":[{"제목":"곡선의 모양과 꼭짓점 찾기","힌트":"$\\sqrt{2x+4}-3=0$ 이 되는 $x$ 는?","식":["$x=-2:\\ y=|0-3|=3$","$\\sqrt{2x+4}=3\\ \\Rightarrow\\ x=\\dfrac{5}{2}$"],"설명":"곡선은 $(-2,\\ 3)$ 에서 시작해 $x=\\frac{5}{2}$ 에서 $x$축에 닿는다. 그 왼쪽은 $y=3-\\sqrt{2x+4}$ 로 감소하고, 오른쪽은 $y=\\sqrt{2x+4}-3$ 으로 증가한다.","확인":"5/2","스킬":"G5"},{"제목":"직선이 접하는 순간의 t 구하기","힌트":"$y=3-\\sqrt{2x+4}$ 의 기울기가 $-1$ 이 되는 점의 좌표는?","식":["$y'=-\\dfrac{1}{\\sqrt{2x+4}}=-1\\ \\Rightarrow\\ \\sqrt{2x+4}=1$","$x=-\\dfrac{3}{2},\\ y=3-1=2$","$2=\\dfrac{3}{2}+t\\ \\Rightarrow\\ t=\\dfrac{1}{2}$"],"설명":"기울기가 $-1$ 인 접선이 되는 순간의 접점을 구하고, 그 점을 직선 $y=-x+t$ 에 대입한다.","확인":"1/2","스킬":"G1"},{"제목":"직선이 시작점을 지나는 순간의 t 구하기","힌트":"$y=-x+t$ 가 $(-2,\\ 3)$ 을 지나려면 $t$ 는?","식":["$3=-(-2)+t$","$t=1$"],"설명":"곡선의 시작점 $(-2,\\ 3)$ 은 곡선에 포함되므로 직선이 이 점을 지나는 순간 교점의 개수가 바뀐다.","확인":"1","스킬":"G5"},{"제목":"f(t) 를 구간별로 정리하기","고비":true,"힌트":"$t$ 가 $\\frac{1}{2}$ 보다 작을 때, $\\frac{1}{2}$ 과 $1$ 사이일 때, $1$ 보다 클 때 교점은 몇 개일까?","식":["$t<\\dfrac{1}{2}:\\ f(t)=0$","$t=\\dfrac{1}{2}:\\ f(t)=1$","$\\dfrac{1}{2}<t\\le1:\\ f(t)=2$","$t>1:\\ f(t)=1$"],"설명":"접하는 순간 이후 왼쪽 가지에서 두 점에서 만나다가, $t=1$ 을 지나면 그중 한 점이 시작점 밖으로 빠진다. $t$ 가 더 커지면 오른쪽 가지와 한 점에서 만나 계속 $1$ 개이다.","확인":null,"스킬":"G1"},{"제목":"연속 조건으로 a, b 구하기","힌트":"$f(t)$ 가 불연속인 $t=\\frac{1}{2},\\ 1$ 에서 곱이 이어지려면 $2t^{2}+at+b$ 의 값은?","식":["$2\\cdot\\dfrac{1}{4}+\\dfrac{a}{2}+b=0,\\ 2+a+b=0$","$2t^{2}+at+b=2\\left(t-\\dfrac{1}{2}\\right)(t-1)=2t^{2}-3t+1$","$a=-3,\\ b=1$"],"설명":"$t=\\frac{1}{2}$ 에서는 $0,\\ 1,\\ 2$ 로, $t=1$ 에서는 $2$ 에서 $1$ 로 값이 뛴다. 곱이 연속이려면 이차식이 두 점에서 $0$ 이어야 하고, 최고차항의 계수가 $2$ 이므로 위와 같이 정해진다.","확인":null,"스킬":"D12"},{"제목":"a-b 계산하기","힌트":"$a=-3,\\ b=1$ 을 $a-b$ 에 넣으면?","식":["$a-b=-3-1=-4$"],"설명":"구한 $a,\\ b$ 의 값을 대입한다.","확인":"-4","스킬":"D12"}]},"ns-30e696791f74":{"길":"직선이 정수점 두 개만 지나게 하고 |a|+b 가 최대인 두 점을 고른다","단계":[{"제목":"곡선 위의 정수점 찾기","힌트":"$x=1,\\ 2,\\ \\cdots,\\ 6$ 일 때 $y=\\frac{12}{x}$ 의 값은?","식":["$(1,\\ 12),\\ (2,\\ 6),\\ (3,\\ 4),\\ (4,\\ 3),\\ \\left(5,\\ \\dfrac{12}{5}\\right),\\ (6,\\ 2)$"],"설명":"열린구간 $(0,\\ 7)$ 안의 정수는 $1$ 부터 $6$ 까지이고, 이 $x$ 에서 $f(x)=ax+b$ 이다. 곡선 $y=\\frac{12}{x}$ 위에서 같은 $x$ 의 점이 $6$ 개 생긴다.","확인":null,"스킬":"P4"},{"제목":"불연속이 4개일 조건 세우기","힌트":"정수 $x=n$ 에서 $f$ 가 연속이려면 $an+b$ 가 어떤 값과 같아야 할까?","식":["$an+b=\\dfrac{12}{n}$","정수 $6$ 개 중 불연속 $4$ 개 $\\Rightarrow$ 연속 $2$ 개"],"설명":"$x=n$ 에서 극한값이 $\\frac{12}{n}$ 이므로 직선이 점 $\\left(n,\\ \\frac{12}{n}\\right)$ 을 지나야 연속이다. 곡선 $y=\\frac{12}{x}$ 는 한 직선과 두 점 이하에서 만나므로, 직선은 정수점 $6$ 개 중 정확히 $2$ 개를 지나야 한다.","확인":null,"스킬":"D12"},{"제목":"|a|+b 가 최대인 두 점 고르기","고비":true,"힌트":"곡선이 감소하므로 두 점을 이은 직선의 기울기 $a$ 의 부호는? 그러면 $|a|+b$ 가 커지는 조건은?","식":["$a<0\\ \\Rightarrow\\ |a|+b=-a+b$","$-a$ 도 $b$ 도 클수록 최대","$(1,\\ 12),\\ (2,\\ 6)$ 을 지나는 직선"],"설명":"어느 두 점을 이어도 기울기가 음수이므로 $|a|+b=-a+b$ 이다. 가파르게 내려가고 $y$절편이 큰 직선은 가장 왼쪽의 두 점을 지날 때 얻어진다.","확인":null,"스킬":"G9"},{"제목":"직선을 구해 |a|+b 계산하기","힌트":"두 점 $(1,\\ 12),\\ (2,\\ 6)$ 으로 $a,\\ b$ 를 구하면?","식":["$a=\\dfrac{6-12}{2-1}=-6$","$b=12-(-6)\\times1=18$","$|a|+b=6+18=24$"],"설명":"기울기를 구한 뒤 한 점을 대입해 $y$절편을 구한다. 직선 $y=-6x+18$ 에서 $|a|+b$ 가 최댓값이다.","확인":"24","스킬":"G9"}]},"ns-35471e06283a":{"길":"x=1 의 좌극한·우극한·함숫값을 g 에 넣어 세 값을 같게 한다","단계":[{"제목":"그래프에서 x=1 의 세 값 읽기","힌트":"$x=1$ 에서 왼쪽 극한, 오른쪽 극한, 함숫값은 각각 얼마일까?","식":["$\\lim_{x\\to1-}f(x)=0$","$\\lim_{x\\to1+}f(x)=2$","$f(1)=1$"],"설명":"빈 점은 극한값을, 채운 점은 함숫값을 나타낸다. 왼쪽에서는 $0$ 에, 오른쪽에서는 $2$ 에 가까워지고 $f(1)=1$ 이다.","확인":null,"스킬":"D12"},{"제목":"합성함수의 연속 조건 쓰기","고비":true,"힌트":"$x\\to1-$ 일 때 $f(x)\\to0$ 이면 $g(f(x))$ 는 어느 값에 가까워질까?","식":["$\\lim_{x\\to1-}g(f(x))=g(0)$","$\\lim_{x\\to1+}g(f(x))=g(2)$","$g(f(1))=g(1)$","$g(0)=g(1)=g(2)$","$g(0)=-1$"],"설명":"$g$ 는 다항함수이므로 안쪽 함수의 극한값을 그대로 $g$ 에 넣을 수 있다. 세 값이 같아야 $x=1$ 에서 연속이고, 다른 점에서는 $f$ 가 연속이라 합성함수도 연속이다.","확인":"-1","스킬":"T6"},{"제목":"a, b 에 대한 연립방정식 세우기","힌트":"$g(1)=-1$ 과 $g(2)=-1$ 을 $a,\\ b$ 의 식으로 쓰면?","식":["$g(1)=-1+a+b-1=-1\\ \\Rightarrow\\ a+b=1$","$g(2)=-8+4a+2b-1=-1\\ \\Rightarrow\\ 2a+b=4$"],"설명":"$g(x)=-x^{3}+ax^{2}+bx-1$ 에 $x=1,\\ 2$ 를 넣고 $-1$ 과 같다고 놓는다.","확인":null,"스킬":"A10"},{"제목":"a, b 를 구해 10a+b 계산하기","힌트":"두 식을 변끼리 빼면 $a$ 는?","식":["$a=3,\\ b=-2$","$10a+b=30-2=28$"],"설명":"두 식을 빼면 $a=3$ 이고, 이를 $a+b=1$ 에 넣으면 $b=-2$ 이다.","확인":"28","스킬":"A10"}]},"ns-36645831f4bd":{"길":"감소함수라 f(□)=0 은 □=α 하나로 바뀐다","단계":[{"제목":"f(x)=0 의 유일한 근 α 정하기","힌트":"(가)로 보면 $f(x)=0$ 인 $x$ 는 최대 몇 개이고, (나)로 보면 어디에 있을까?","식":["$f(\\alpha)=0,\\ 0<\\alpha<1$","$f(\\square)=0\\ \\Leftrightarrow\\ \\square=\\alpha$"],"설명":"(가)에서 $f$ 는 감소함수이므로 같은 값을 두 번 갖지 않는다. (나)에서 근이 $(0,\\ 1)$ 에 있으므로 이를 $\\alpha$ 라 하면 $f(\\square)=0$ 은 $\\square=\\alpha$ 와 같다.","확인":null,"스킬":"T6"},{"제목":"ㄱ 판정하기","힌트":"$f(-2x)=0$ 이면 $-2x$ 는 어떤 값이고, 그때 $x$ 의 범위는?","식":["$-2x=\\alpha$","$x=-\\dfrac{\\alpha}{2}$","$-\\dfrac{1}{2}<x<0$"],"설명":"$0<\\alpha<1$ 이므로 근 $x$ 는 $(0,\\ 1)$ 이 아니라 $\\left(-\\frac{1}{2},\\ 0\\right)$ 에 있다. 따라서 ㄱ은 옳지 않다.","확인":null,"스킬":"T6"},{"제목":"ㄴ 판정하기","고비":true,"힌트":"$-4x^{2}+4x$ 의 $0<x<1$ 에서의 최댓값은? 그 값과 $\\alpha$ 를 비교하면?","식":["$-4x^{2}+4x=-4\\left(x-\\dfrac{1}{2}\\right)^{2}+1$","$-4x^{2}+4x=\\alpha$","$0<\\alpha<1$ 이므로 $(0,\\ 1)$ 에서 서로 다른 두 근"],"설명":"$x=\\frac{1}{2}$ 에서 최댓값 $1$ 을 갖고 양쪽으로 $0$ 까지 내려간다. $0<\\alpha<1$ 이면 $y=\\alpha$ 와 두 점에서 만나므로 ㄴ은 옳다.","확인":null,"스킬":"T6"},{"제목":"ㄷ 판정하고 옳은 보기 고르기","힌트":"$|x+1|=\\alpha$ 의 해 중 $-1<x<1$ 에 들어가는 것은 몇 개일까?","식":["$x+1=\\pm\\alpha\\ \\Rightarrow\\ x=-1\\pm\\alpha$","$-1-\\alpha<-1,\\ -1<-1+\\alpha<0$","$(-1,\\ 1)$ 에서 근 하나"],"설명":"$x=-1-\\alpha$ 는 구간 밖이므로 근은 하나뿐이다. 따라서 ㄷ은 옳지 않고, 옳은 것은 ㄴ뿐이다.","확인":null,"스킬":"G1"}]},"ns-3a455945dae8":{"길":"g 의 W자 개형을 (가)로 고르고 (나)로 c 와 f(0) 을 정해 보기를 판정한다","단계":[{"제목":"(가)로 g(x) 의 개형 고르기","힌트":"$g(x)=f(|x|)$ 는 $y$축 대칭이다. $t$ 가 커질 때 $h(t)$ 가 어떻게 변해야 $h(-1)<h(3)<h(2)$ 가 될까?","식":["$a>0,\\ b>0$ 이면 W자 꼴","$t<c:\\ 0,\\ \\ t=c:\\ 2,\\ \\ c<t<f(0):\\ 4,\\ \\ t=f(0):\\ 3,\\ \\ t>f(0):\\ 2$","$h(-1)<h(3)<h(2)\\ \\Rightarrow\\ a>0,\\ b>0$"],"설명":"$x\\ge0$ 부분은 $f$ 그대로이고 $x<0$ 부분은 $y$축 대칭이다. 꼭짓점의 위치와 $a$ 의 부호에 따라 개형이 달라지는데, $h(-1)<h(3)<h(2)$ 를 만들 수 있는 개형은 W자 꼴뿐이다.","확인":null,"스킬":"G5"},{"제목":"(나)로 c 와 f(0) 의 값 정하기","고비":true,"힌트":"$(t^{2}-2t)h(t)$ 가 연속이려면 $h(t)$ 의 불연속점은 $t^{2}-2t=0$ 인 $t$ 중에서만 나올 수 있다. 그러면 $c$ 와 $f(0)$ 은?","식":["$t^{2}-2t=0\\ \\Rightarrow\\ t=0,\\ 2$","불연속점은 $t=c,\\ t=f(0)$ 이고 $c<f(0)$","$c=0,\\ f(0)=2$"],"설명":"$t^{2}-2t\\ne0$ 인 곳에서는 $h$ 가 연속이어야 곱도 연속이다. 따라서 W자의 두 불연속점이 $0$ 과 $2$ 이고, 작은 쪽이 $c$ 이다. 이때 $h(-1)=0,\\ h(3)=2,\\ h(2)=3$ 이어서 (가)도 성립한다.","확인":"0","스킬":"G5"},{"제목":"정수 a, b 구하기","힌트":"$f(0)=ab^{2}+c=2$ 를 만족하는 양의 정수 $a,\\ b$ 는?","식":["$ab^{2}=2$","$b=1,\\ a=2$","$f(x)=2(x-1)^{2}$"],"설명":"$a,\\ b$ 는 양의 정수이고 $b^{2}$ 은 $2$ 의 약수여야 하므로 $b=1$ 이다.","확인":"1","스킬":"G1"},{"제목":"ㄱ 판정하기","힌트":"$a,\\ b,\\ c$ 를 모두 더하면?","식":["$a+b+c=2+1+0=3>0$"],"설명":"구한 값을 그대로 더한다. $a>0,\\ b>0,\\ c=0$ 이므로 ㄱ은 옳다.","확인":"3","스킬":"G5"},{"제목":"ㄴ 판정하기","힌트":"$h(t)$ 가 불연속인 $t$ 는 몇 개일까?","식":["$t<0:\\ 0,\\ \\ t=0:\\ 2,\\ \\ 0<t<2:\\ 4,\\ \\ t=2:\\ 3,\\ \\ t>2:\\ 2$","불연속점은 $t=0,\\ t=2$"],"설명":"$t=0$ 과 $t=2$ 에서 좌우의 값이 달라진다. 불연속점은 $2$ 개이므로 ㄴ은 옳다.","확인":null,"스킬":"G5"},{"제목":"ㄷ 판정하기","힌트":"$g(x)=2(|x|-1)^{2}$ 이 $-2<x<2$ 에서 가장 큰 값과 가장 작은 값에 닿는 곳은?","식":["$g(0)=2,\\ g(\\pm1)=0$","$-2<x<2$ 에서 $0\\le g(x)\\le2$"],"설명":"$x=\\pm2$ 는 구간에 포함되지 않지만 $x=0$ 에서 $g(0)=2$ 에 도달하므로 최댓값이 있다. 최솟값은 $x=\\pm1$ 에서의 $0$ 이다. 따라서 ㄷ은 옳다.","확인":null,"스킬":"G5"},{"제목":"ㄹ 판정하고 옳은 보기 고르기","힌트":"$f(x)=2(x-1)^{2}$ 에 $x=3$ 을 넣으면?","식":["$f(3)=2(3-1)^{2}=8\\ne4$","ㄱ, ㄴ, ㄷ 이 옳다"],"설명":"$f(3)=8$ 이어서 ㄹ은 옳지 않다. 옳은 것은 ㄱ, ㄴ, ㄷ 이다.","확인":null,"스킬":"G1"}]},"ns-3b01df78adef":{"길":"꼭짓점이 곡선을 지나는 t 에서 교점 수가 바뀌고 그곳이 g 의 근이다","단계":[{"제목":"꼭짓점 B 가 곡선 위에 오는 t 구하기","힌트":"$x<0$ 에서 곡선은 $y=x(x-2)$ 이다. 이 곡선이 $\\mathrm{B}(-t,\\ 2-t)$ 를 지나려면?","식":["$2-t=(-t)(-t-2)$","$t^{2}+3t-2=0$","$t=\\dfrac{-3+\\sqrt{17}}{2}\\ (t>0)$"],"설명":"정사각형은 중심이 $(0,\\ 2)$ 이고 한 변의 길이가 $2t$ 이다. $B$ 가 곡선에 닿는 순간 교점의 개수가 바뀐다. 이 값을 $p=\\frac{-3+\\sqrt{17}}{2}$ 라 하자.","확인":null,"스킬":"G1"},{"제목":"꼭짓점 C 가 곡선 위에 오는 t 구하기","힌트":"$0\\le x\\le2$ 에서 곡선은 $y=x(2-x)$ 이다. 이 곡선이 $\\mathrm{C}(t,\\ 2-t)$ 를 지나려면?","식":["$2-t=t(2-t)$","$(2-t)(1-t)=0$","$t=1,\\ t=2$"],"설명":"$t=1$ 이면 $\\mathrm{C}(1,\\ 1)$ 은 곡선의 꼭대기이고, $t=2$ 이면 $\\mathrm{C}(2,\\ 0)$ 은 $x$축 위의 꺾인 점이다.","확인":null,"스킬":"G1"},{"제목":"f(t) 를 구간별로 세어 불연속점 찾기","고비":true,"힌트":"$t$ 가 $p,\\ 1,\\ 2$ 를 지날 때마다 정사각형과 곡선이 만나는 점의 개수는 어떻게 달라질까?","식":["$0<t<p:\\ f(t)=0$","$p<t<1:\\ f(t)=2$","$1<t<2:\\ f(t)=4$","$t>2:\\ f(t)=2$"],"설명":"이웃한 구간의 개수가 서로 달라서 $t=p,\\ 1,\\ 2$ 에서 $f(t)$ 가 불연속이다. 그 밖의 꼭짓점이 곡선을 지날 때는 교점이 한 변에서 다른 변으로 옮겨 갈 뿐 개수는 그대로이다.","확인":null,"스킬":"G5"},{"제목":"(나)로 삼차함수 g(x) 정하기","힌트":"$f(t)g(t)$ 가 연속이려면 $f$ 가 불연속인 점에서 $g$ 의 값은 얼마여야 할까?","식":["$g(p)=g(1)=g(2)=0$","$g(x)=(x-p)(x-1)(x-2)$"],"설명":"$f$ 의 좌우극한이 서로 다른 점에서 곱이 이어지려면 $g$ 의 값이 $0$ 이어야 한다. 삼차함수이고 최고차항의 계수가 $1$ 이므로 세 근으로 바로 쓸 수 있다.","확인":null,"스킬":"D12"},{"제목":"g 의 값 계산하기","힌트":"$u=\\frac{3+\\sqrt{17}}{2}$ 일 때 $u-p,\\ u-1,\\ u-2$ 는 각각?","식":["$u-p=3$","$(u-1)(u-2)=\\dfrac{1+\\sqrt{17}}{2}\\times\\dfrac{-1+\\sqrt{17}}{2}=\\dfrac{16}{4}=4$","$g(u)=3\\times4=12$"],"설명":"$u-p=3$ 이고 나머지 두 인수의 곱은 합차 공식으로 간단히 정리된다.","확인":"12","스킬":"A5"}]},"ns-3b8a003c5659":{"길":"좌우 극한이 다른 점과 극한은 있는데 함숫값이 다른 점을 나눠 센다","단계":[{"제목":"극한이 없는 점의 개수 a 구하기","힌트":"$x=1,\\ 2,\\ 3$ 에서 좌극한과 우극한은 각각 얼마일까?","식":["$x=1:\\ 1,\\ 1$","$x=2:\\ 2,\\ 3$","$x=3:\\ 3,\\ 1$","$a=2$"],"설명":"좌극한과 우극한이 다르면 극한이 존재하지 않는다. $x=2,\\ 3$ 에서만 두 값이 다르다.","확인":"2","스킬":"C2"},{"제목":"불연속인 점의 개수 b 구하기","고비":true,"힌트":"극한이 있는 $x=1$ 에서는 극한값과 함숫값이 같을까?","식":["$x=1:\\ \\lim_{x\\to1}f(x)=1,\\ f(1)=0$","$x=2,\\ 3$ 은 극한이 없으므로 불연속","$b=3$"],"설명":"극한이 존재해도 함숫값과 다르면 불연속이다. $x=1$ 에서 극한값은 $1$ 이고 $f(1)=0$ 이므로 불연속이다.","확인":"3","스킬":"C2"},{"제목":"a+b 계산하기","힌트":"$a=2,\\ b=3$ 을 더하면?","식":["$a+b=2+3=5$"],"설명":"앞에서 구한 두 개수를 더한다.","확인":"5","스킬":"C2"}]},"ns-3b92397828a8":{"길":"분모가 0 인 구간을 먼저 빼고 후보 n 에서 좌우 값을 비교한다","단계":[{"제목":"분모가 0 인 구간을 빼고 후보 n 정하기","힌트":"분모 $f(x)-2$ 가 $0$ 이 되는 $x$ 의 범위는?","식":["$f(x)=2:\\ x<-3,\\ x\\ge2$","$-3<n<2$ 의 정수 $n=-2,\\ -1,\\ 0,\\ 1$"],"설명":"$x<-3$ 과 $x\\ge2$ 에서는 분모가 $0$ 이어서 함수가 정의되지 않는다. $x=n$ 에서 연속이려면 $n$ 과 그 양쪽 근처에서 모두 정의되어야 하므로 위의 네 값만 후보이다.","확인":null,"스킬":"C2"},{"제목":"n=-2, 1 에서 좌우 값 비교하기","고비":true,"힌트":"$f(x+n)$ 이 $x=n$ 의 왼쪽과 오른쪽에서 어느 식으로 바뀌는지 $x+n$ 의 범위로 살피면?","식":["$n=-2:\\ x\\to-2-$ 에서 $\\dfrac{2+2}{-1}=-4,\\ \\ x\\to-2+$ 에서 $\\dfrac{2+1}{-1}=-3$","$n=1:\\ x\\to1-$ 에서 $\\dfrac{-1+1}{-1}=0,\\ \\ x\\to1+$ 에서 $\\dfrac{2+1}{-1}=-3$"],"설명":"$n=-2$ 에서는 $f(x-1)$ 이 $x=-2$ 를 지나며 $2$ 에서 $1$ 로 바뀌고, $n=1$ 에서는 $f(x+1)$ 이 $x=1$ 을 지나며 $-2(x+1)+3$ 에서 $2$ 로 바뀐다. 두 경우 모두 좌극한과 우극한이 달라 불연속이다.","확인":null,"스킬":"C2"},{"제목":"n=-1, 0 에서 연속 확인하기","힌트":"$x=-1,\\ 0$ 근처에서 $f(x)$ 와 $f(x-1)$ 의 값은?","식":["$n=-1:\\ \\dfrac{2f(x-1)}{f(x)-2}=\\dfrac{2\\times1}{1-2}=-2$","$n=0:\\ \\dfrac{f(x)+f(x-1)}{f(x)-2}=\\dfrac{1+1}{1-2}=-2$"],"설명":"두 점 근처에서 $f(x)=1$ 이고 $f(x-1)=1$ 로 일정하다. 좌극한, 우극한, 함숫값이 모두 $-2$ 로 같아 연속이다.","확인":"-2","스킬":"C2"},{"제목":"n 의 값의 합 구하기","힌트":"연속인 $n$ 은 $-1$ 과 $0$ 이다. 더하면?","식":["$-1+0=-1$"],"설명":"연속이 되는 $n$ 은 $-1,\\ 0$ 이므로 그 합을 구한다.","확인":"-1","스킬":"C2"}]},"ns-3dff8509967a":{"길":"부호가 뒤집히는 함수로 반례를 만들어 보기를 하나씩 가린다","단계":[{"제목":"ㄱ, ㄴ 의 반례 찾기","고비":true,"힌트":"$f(x)=\\frac{1}{x},\\ g(x)=\\frac{2}{x}$ 의 $x\\to\\infty$ 극한은? $f(x)=g(x)=\\frac{1}{x-a}$ 의 $x\\to a$ 극한은?","식":["ㄱ: $x>0$ 에서 $f<g$ 이지만 $\\lim f=\\lim g=0$","ㄴ: $f-g=0$ 이지만 $x\\to a$ 에서 $f,\\ g$ 의 극한은 존재하지 않는다"],"설명":"부등호는 극한에서 등호가 될 수 있다. 또 $f-g$ 의 극한이 있어도 $f,\\ g$ 각각의 극한이 존재한다는 보장이 없다. 따라서 ㄱ, ㄴ 은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 판정하기","힌트":"연속인 함수끼리의 곱은 어떻게 될까?","식":["$\\{f(x)\\}^{2}=f(x)\\times f(x)$","$x=1$ 에서 연속"],"설명":"연속함수의 곱은 연속이다. $f(x)$ 가 $x=1$ 에서 연속이므로 $\\{f(x)\\}^{2}$ 도 연속이고 ㄷ은 옳다.","확인":null,"스킬":"C3"},{"제목":"ㄹ, ㅁ 의 반례 찾기","힌트":"$x\\ge0$ 에서 $1$, $x<0$ 에서 $-1$ 인 함수를 쓰면 $f+g$ 와 $|f|$ 는 어떻게 될까?","식":["ㄹ: $f=1,\\ g=-1\\ (x\\ge0),\\ f=-1,\\ g=1\\ (x<0)\\ \\Rightarrow\\ f+g=0$ 은 연속, $f,\\ g$ 는 불연속","ㅁ: 같은 $f$ 에서 $|f|=1$ 은 연속, $f$ 는 불연속"],"설명":"부호가 뒤집히는 함수는 $0$ 에서 불연속이지만 더하거나 절댓값을 취하면 연속이 된다. 따라서 ㄹ, ㅁ 은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"옳은 보기의 개수 세기","힌트":"옳은 보기는 몇 개일까?","식":["옳은 것은 ㄷ 하나이므로 $1$ 개"],"설명":"ㄱ, ㄴ, ㄹ, ㅁ 은 반례가 있고 ㄷ 만 항상 성립한다.","확인":"1","스킬":"C3"}]},"ns-3f923d38e0ca":{"길":"합성함수는 안쪽 함수가 다가가는 값과 방향을 바깥 함수에 넣어 본다","단계":[{"제목":"ㄱ 판정하기","힌트":"$x=1$ 의 왼쪽과 오른쪽에서 $f(x)$ 는 각각 어떤 값에 가까워질까?","식":["$\\lim_{x\\to1-}f(x)=1$","$\\lim_{x\\to1+}f(x)=1$","$\\lim_{x\\to1}f(x)=1$ 로 존재"],"설명":"빈 점은 함숫값이 아니라 그래프가 다가가는 값을 나타낸다. 좌극한과 우극한이 같으므로 극한이 존재하고, ㄱ은 옳지 않다.","확인":"1","스킬":"T6"},{"제목":"ㄴ 판정하기","고비":true,"힌트":"$x\\to-1+$ 일 때 $f(x)$ 는 어느 값에 어느 쪽에서 가까워지고, 그 값에서 $f$ 의 좌극한은 얼마일까?","식":["$x\\to-1+\\ \\Rightarrow\\ f(x)\\to1-$","$\\lim_{x\\to-1+}f(f(x))=\\lim_{t\\to1-}f(t)=1$"],"설명":"$t=f(x)$ 로 놓는다. $x$ 가 $-1$ 의 오른쪽에서 다가가면 $t$ 는 $1$ 보다 작은 값으로 $1$ 에 다가가므로 $f$ 의 $x=1$ 에서의 좌극한을 본다. 따라서 ㄴ은 옳다.","확인":null,"스킬":"T6"},{"제목":"ㄷ 판정하고 옳은 보기 고르기","힌트":"$x\\to-1-$ 일 때 $f(f(x))$ 의 극한은 얼마이고, ㄴ 의 값과 같을까?","식":["$x\\to-1-\\ \\Rightarrow\\ f(x)\\to0-$","$\\lim_{x\\to-1-}f(f(x))=\\lim_{t\\to0-}f(t)=0$","좌극한 $0$ 과 우극한 $1$ 이 달라 불연속, 옳은 것은 ㄴ"],"설명":"$x=-1$ 에서 좌극한과 우극한이 다르므로 극한이 없고 연속이 아니다. 따라서 ㄷ은 옳지 않고, 옳은 것은 ㄴ뿐이다.","확인":null,"스킬":"T6"}]},"ns-40b02f405924":{"길":"주기 2 와 f(x)-x 의 한 마디 모양으로 교점 수를 구간별로 정한다","단계":[{"제목":"주기 2 로 ㄴ 판정하기","힌트":"$f(x)=x+k$ 의 해 $x$ 가 있으면 $x+2$ 는 어떤 직선과의 교점일까?","식":["$f(x)=x+k\\ \\Rightarrow\\ f(x+2)=(x+2)+(k-2)$","$g(k)=g(k-2)$, 즉 $g(k+2)=g(k)$"],"설명":"$f(x+2)=f(x)$ 이므로 교점을 오른쪽으로 $2$ 옮기면 $k$ 가 $2$ 작은 직선과의 교점이 된다. 두 경우의 교점 개수는 같으므로 ㄴ은 옳다.","확인":null,"스킬":"T2"},{"제목":"g(k) 를 f(x)-x 의 해의 개수로 바꾸기","힌트":"$f(x)=x+k$ 를 $f(x)-x=k$ 로 보면 $-1\\le x<1$ 에서 $f(x)-x$ 의 식은?","식":["$\\varphi(x)=f(x)-x$","$-1\\le x<1:\\ \\varphi(x)=-x^{2}-x+1$","$\\varphi(x+2)=\\varphi(x)-2$"],"설명":"$g(k)$ 는 $y=\\varphi(x)$ 와 $y=k$ 의 교점의 개수이다. $\\varphi$ 는 한 주기가 지날 때마다 $2$ 씩 내려간다.","확인":null,"스킬":"G1"},{"제목":"한 마디에서 φ 의 값 읽기","힌트":"$-x^{2}-x+1$ 을 완전제곱 꼴로 고치면 최댓값은 얼마일까?","식":["$-x^{2}-x+1=-\\left(x+\\dfrac{1}{2}\\right)^{2}+\\dfrac{5}{4}$","$\\varphi(-1)=1,\\ \\ \\varphi\\left(-\\dfrac{1}{2}\\right)=\\dfrac{5}{4},\\ \\ \\varphi(1-)=-1$"],"설명":"마디 $[-1,\\ 1)$ 에서 $\\varphi$ 는 $1$ 에서 시작해 $\\frac{5}{4}$ 까지 올랐다가 $-1$ 까지 내려간다. 다음 마디 $[1,\\ 3)$ 은 이 값들에서 $2$ 를 뺀 것으로 $-1$ 에서 $-\\frac{3}{4}$ 까지 올랐다가 $-3$ 까지 내려간다.","확인":"5/4","스킬":"G1"},{"제목":"-1≤v<1 에서 g(v) 의 값 정하기","고비":true,"힌트":"두 마디 $[-1,\\ 1)$, $[1,\\ 3)$ 의 그래프와 직선 $y=v$ 는 몇 점에서 만날까?","식":["$v=-1:\\ g=2$","$-1<v<-\\dfrac{3}{4}:\\ g=3$","$v=-\\dfrac{3}{4}:\\ g=2$","$-\\dfrac{3}{4}<v<1:\\ g=1$"],"설명":"첫째 마디는 $-1<v<1$ 이면 내려가는 부분에서 한 점이 나온다. 둘째 마디는 $-1\\le v<-\\frac{3}{4}$ 이면 올라가는 부분과 내려가는 부분에서 두 점, $v=-\\frac{3}{4}$ 이면 꼭대기 한 점이 나온다. 다른 마디는 이 범위의 $v$ 를 지나지 않는다.","확인":null,"스킬":"C2"},{"제목":"ㄱ 판정하기","힌트":"$k\\to1+$ 이면 $k-2$ 는 $-1$ 의 어느 쪽에서 가까워지고, 그때 $g$ 의 값은?","식":["$g(k)=g(k-2),\\ \\ k-2\\to-1+$","$-1<v<-\\dfrac{3}{4}$ 에서 $g=3$"],"설명":"주기 $2$ 로 $k-2$ 로 옮겨 구간별 값을 읽는다. $-1$ 의 오른쪽 구간에서 $g=3$ 이므로 극한이 $3$ 이고 ㄱ은 옳다.","확인":null,"스킬":"C2"},{"제목":"ㄷ 판정하기","힌트":"$g$ 의 값이 바뀌는 $v$ 는 $-1,\\ -\\frac{3}{4}$ 이다. $-5<k<5$ 에서 그런 $k$ 는 모두 몇 개일까?","식":["$k=-1+2j:\\ -3,\\ -1,\\ 1,\\ 3$ (4개)","$k=-\\dfrac{3}{4}+2j:\\ -\\dfrac{19}{4},\\ -\\dfrac{11}{4},\\ -\\dfrac{3}{4},\\ \\dfrac{5}{4},\\ \\dfrac{13}{4}$ (5개)","$4+5=9$"],"설명":"각 값에서 좌극한, 함숫값, 우극한이 서로 달라 모두 불연속이다. 불연속인 $k$ 는 $9$ 개이므로 $10$ 개라는 ㄷ은 옳지 않다.","확인":"9","스킬":"C2"},{"제목":"옳은 보기 고르기","힌트":"ㄱ, ㄴ, ㄷ 중 옳은 것은?","식":["ㄱ 옳음, ㄴ 옳음, ㄷ 옳지 않음"],"설명":"ㄱ, ㄴ 이 옳고 ㄷ 은 옳지 않다.","확인":null,"스킬":"C2"}]},"ns-4cb3b10c33dc":{"길":"f 를 x(x-4)g(x) 로 두고 g(0), g(4) 의 부호가 반대일 조건을 쓴다","단계":[{"제목":"f(x) 를 x(x-4)g(x) 꼴로 나타내기","힌트":"$x\\to0$, $x\\to4$ 에서 분모가 $0$ 이 되는데 극한이 존재하려면 $f(0),\\ f(4)$ 는 얼마일까?","식":["$f(0)=0,\\ f(4)=0$","$f(x)=x(x-4)g(x)$ ($g$ 는 다항함수)"],"설명":"분모가 $0$ 으로 가는데 극한이 유한하므로 분자도 $0$ 으로 가야 한다. 다항함수 $f$ 가 $x=0,\\ 4$ 에서 $0$ 이므로 $x(x-4)$ 로 나누어떨어진다.","확인":null,"스킬":"A4"},{"제목":"g(0) 구하기","힌트":"$\\dfrac{f(x)}{x}=(x-4)g(x)$ 에서 $x\\to0$ 의 극한을 $g(0)$ 으로 쓰면?","식":["$\\lim_{x\\to0}\\dfrac{f(x)}{x}=\\lim_{x\\to0}(x-4)g(x)=-4g(0)$","$-4g(0)=-1$","$g(0)=\\dfrac{1}{4}$"],"설명":"$g$ 는 다항함수이므로 연속이어서 극한값이 $g(0)$ 의 식으로 바로 나온다.","확인":"1/4","스킬":"D11"},{"제목":"g(4) 를 a 로 나타내기","힌트":"$\\dfrac{f(x)}{x-4}=xg(x)$ 에서 $x\\to4$ 의 극한을 $g(4)$ 로 쓰면?","식":["$\\lim_{x\\to4}\\dfrac{f(x)}{x-4}=\\lim_{x\\to4}xg(x)=4g(4)$","$4g(4)=a^{2}-3a+2$","$g(4)=\\dfrac{a^{2}-3a+2}{4}$"],"설명":"앞 단계와 같은 방식으로 $x=4$ 에서의 극한값을 $g(4)$ 로 나타낸다.","확인":null,"스킬":"D11"},{"제목":"사잇값 정리로 a 의 범위 정하기","고비":true,"힌트":"$g(0)>0$ 일 때 $g(x)=0$ 이 $(0,\\ 4)$ 에서 근을 가지려면 $g(4)$ 의 부호는?","식":["$g(0)g(4)<0$","$a^{2}-3a+2<0$","$(a-1)(a-2)<0\\ \\Rightarrow\\ 1<a<2$"],"설명":"$0<x<4$ 에서는 $x(x-4)\\ne0$ 이므로 $f(x)=0$ 은 $g(x)=0$ 과 같다. $g$ 는 연속이므로 양 끝값의 부호가 다르면 사잇값 정리로 근이 보장된다. $g(0)=\\frac{1}{4}>0$ 이므로 $g(4)<0$ 이어야 한다.","확인":null,"스킬":"C8"}]},"ns-4cff71cc72f8":{"길":"분모가 0 이 되는 점이 각 구간에 들어오지 않을 조건을 따진다","단계":[{"제목":"x>a 쪽 분모 조건 구하기","힌트":"$x^{2}+5x+6=0$ 의 해가 $x>a$ 범위에 들어오면 $g$ 는 어떻게 될까?","식":["$x^{2}+5x+6=(x+2)(x+3)=0\\ \\Rightarrow\\ x=-2,\\ -3$","$-2,\\ -3$ 이 $x>a$ 에 없어야 하므로 $a\\ge-2$"],"설명":"분모가 $0$ 이 되는 $x$ 가 구간 안에 있으면 그 점에서 $g$ 가 정의되지 않아 연속이 될 수 없다.","확인":null,"스킬":"T3"},{"제목":"x≤a 쪽 분모 조건 구하기","고비":true,"힌트":"$ax-9=0$ 의 해 $x=\\frac{9}{a}$ 가 $x\\le a$ 범위에 있으면 안 된다. $a$ 의 부호별로 따지면?","식":["$a=0:\\ ax-9=-9\\ne0$","$a>0:\\ \\dfrac{9}{a}>a\\ \\Rightarrow\\ a^{2}<9\\ \\Rightarrow\\ 0<a<3$","$a<0:\\ \\dfrac{9}{a}>a\\ \\Rightarrow\\ a<-3$ 이므로 $a\\ge-2$ 와 모순"],"설명":"$a<0$ 이면 $\\frac{9}{a}>a$ 의 양변에 음수 $a$ 를 곱해 부등호가 바뀌어 $a^{2}>9$ 가 된다. 이는 $a\\ge-2$ 와 맞지 않아 $a<0$ 은 제외되고 $0\\le a<3$ 이다.","확인":null,"스킬":"C2"},{"제목":"x=a 에서 이어지는지 확인하기","힌트":"$0\\le a<3$ 일 때 $x=a$ 에서 $g$ 의 함숫값과 좌우 극한은?","식":["$g(a)=\\dfrac{a-a}{a^{2}-9}=0$","$\\lim_{x\\to a+}g(x)=\\dfrac{0}{a^{2}+5a+6}=0$"],"설명":"$0\\le a<3$ 이면 $a^{2}-9\\ne0$ 이고 $a^{2}+5a+6\\ne0$ 이다. 분자가 $0$ 이므로 함숫값과 좌극한, 우극한이 모두 $0$ 이어서 $x=a$ 에서도 연속이다.","확인":null,"스킬":"D12"},{"제목":"정수 a 의 개수 세기","힌트":"$0\\le a<3$ 을 만족하는 정수는 몇 개일까?","식":["$a=0,\\ 1,\\ 2$","$3$ 개"],"설명":"구한 범위 $0\\le a<3$ 안의 정수를 센다.","확인":"3","스킬":"C2"}]},"ns-4f362f75eab2":{"길":"극한 0·분모 0 반례를 떠올려 보기를 하나씩 가린다","단계":[{"제목":"ㄱ, ㄷ 의 반례 찾기","힌트":"ㄱ: $x\\to0$ 에서 $f=\\frac{2}{x^{2}},\\ g=\\frac{1}{x^{2}}$ 이면 분수식의 값은? ㄷ: $f=0,\\ g=\\frac{1}{x-a}$ 이면?","식":["ㄱ: $\\dfrac{f-g}{f+g}=\\dfrac{1/x^{2}}{3/x^{2}}=\\dfrac{1}{3}\\ne0$","ㄷ: $\\lim f=0,\\ \\lim fg=0$ 이지만 $\\lim g$ 는 존재하지 않는다"],"설명":"ㄱ 은 극한이 $\\infty$ 인 두 함수의 비가 $0$ 으로 정해지지 않고, ㄷ 은 $\\lim f=0$ 이면 곱의 극한으로 $g$ 의 극한을 알 수 없다. 따라서 ㄱ, ㄷ 은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄴ, ㄹ 판정하기","힌트":"ㄴ: 두 극한값을 $\\alpha,\\ \\beta$ 라 하고 $g$ 를 극한의 성질로 쓰면? ㄹ: $f<g$ 이면 극한값 사이에 등호가 생길 수 있을까?","식":["ㄴ: $\\lim g=\\dfrac{1}{2}(\\beta-\\alpha)$","ㄹ: $f<g$ 이어도 $\\lim f\\le\\lim g$"],"설명":"ㄴ 은 $g=\\frac{1}{2}\\{(f+2g)-f\\}$ 이므로 두 극한이 있으면 $g$ 의 극한도 있다. ㄹ 은 부등호가 극한에서 등호가 될 수 있어 $\\le$ 가 맞다. 따라서 ㄴ, ㄹ 은 옳다.","확인":null,"스킬":"C3"},{"제목":"ㅁ 이 성립하는 예 찾기","고비":true,"힌트":"$g$ 의 값이 $f$ 가 상수인 곳에만 놓이도록 하면 $f(g(x))$ 는 어떻게 될까?","식":["$f(x)=\\begin{cases}1&(x\\ge0)\\\\-1&(x<0)\\end{cases},\\ \\ g(x)=\\begin{cases}1&(x\\ne0)\\\\2&(x=0)\\end{cases}$","$f(g(x))=f(1)=f(2)=1$"],"설명":"$f,\\ g$ 는 모두 $x=0$ 에서 불연속이다. 그러나 $g$ 의 값이 $1,\\ 2$ 뿐이고 $f$ 는 $x\\ge0$ 에서 상수이므로 합성함수가 상수이다. 따라서 ㅁ 은 옳다.","확인":null,"스킬":"C3"},{"제목":"ㅂ 판정하고 옳은 보기 고르기","힌트":"$f(a)$ 가 $0$ 일 수 있는지, $f(x+1)$ 이 $x=a$ 에서 연속이려면 $f$ 가 어느 점에서 연속이어야 하는지 따지면?","식":["$f(a)=0$ 이면 $\\dfrac{-2g(x)}{f(x)}$ 는 $x=a$ 에서 정의되지 않는다","$f(x+1)$ 은 $f$ 가 $x=a+1$ 에서 연속이어야 한다","옳은 것은 ㄴ, ㄹ, ㅁ"],"설명":"$f$ 가 $x=a$ 에서만 연속이라고 했으므로 $x=a+1$ 에서의 연속성은 보장되지 않는다. 따라서 ㅂ 은 옳지 않고, 옳은 것은 ㄴ, ㄹ, ㅁ 이다.","확인":null,"스킬":"C3"}]},"ns-57349db57e62":{"길":"f 나 g 가 끊기는 점만 살피고 g 가 0 인 점은 곱이 이어진다","단계":[{"제목":"불연속 후보 찾기","힌트":"그래프에서 $f$ 와 $g$ 가 각각 끊기는 $x$ 는 어디일까?","식":["$f:\\ x=-1,\\ 0,\\ 1$","$g:\\ x=-1$","후보 $x=-1,\\ 0,\\ 1$"],"설명":"두 함수가 모두 연속인 곳에서는 곱도 연속이다. 따라서 $f$ 나 $g$ 가 끊기는 점만 살피면 된다.","확인":null,"스킬":"C2"},{"제목":"x=-1, 0 에서 좌우 극한 비교하기","고비":true,"힌트":"각 점의 왼쪽과 오른쪽에서 $f(x)$, $g(x)$ 가 가까워지는 값을 곱하면?","식":["$x=-1:\\ \\lim_{x\\to-1-}fg=1\\times(-1)=-1,\\ \\ \\lim_{x\\to-1+}fg=0\\times1=0$","$x=0:\\ \\lim_{x\\to0-}fg=0\\times1=0,\\ \\ \\lim_{x\\to0+}fg=1\\times1=1$"],"설명":"두 점 모두 좌극한과 우극한이 달라 극한이 존재하지 않으므로 불연속이다.","확인":null,"스킬":"C2"},{"제목":"x=1 에서 연속 확인하고 개수 세기","힌트":"$g(1)$ 이 $0$ 이면 $f$ 가 끊겨도 곱은 어떻게 될까?","식":["$\\lim_{x\\to1-}fg=1\\times0=0,\\ \\ \\lim_{x\\to1+}fg=0\\times0=0$","$f(1)g(1)=1\\times0=0$","불연속인 $x$ 는 $-1,\\ 0$ 의 $2$ 개"],"설명":"$g(1)=0$ 이어서 $f$ 가 끊겨도 좌극한, 우극한, 함숫값이 모두 $0$ 으로 같다. 따라서 $x=1$ 에서는 연속이다.","확인":"2","스킬":"C2"}]},"ns-57a9d2e28ecb":{"길":"원의 중심이 y=x 위라 직선 y=x±1 에는 항상 접하는 것을 이용해 교점 수를 센다","단계":[{"제목":"ㄱ 판정하기: 꺾이는 점 찾기","힌트":"$f(x)=||x|-1|$ 의 그래프에서 미분계수가 존재하지 않는 곳은 어떤 점일까?","식":["$f(x)=-x-1\\ (x<-1),\\ \\ x+1\\ (-1\\le x<0),\\ \\ -x+1\\ (0\\le x<1),\\ \\ x-1\\ (x\\ge1)$","꺾이는 점 $x=-1,\\ 0,\\ 1$"],"설명":"주어진 극한은 $x=a$ 에서의 미분계수이다. 그래프가 꺾이는 점에서는 좌우의 기울기가 달라 이 극한이 존재하지 않는다. 따라서 ㄱ은 옳다.","확인":null,"스킬":"G5"},{"제목":"원과 그래프가 만나는 방식 정하기","힌트":"중심 $(t,\\ t)$ 가 직선 $y=x$ 위에 있으면 직선 $y=x+1$, $y=x-1$ 까지의 거리는 $t$ 와 상관없이 얼마일까?","식":["중심에서 $y=x\\pm1$ 까지의 거리 $\\dfrac{1}{\\sqrt{2}}=$ 반지름, 항상 접한다","접점 $\\left(t-\\dfrac12,\\ t+\\dfrac12\\right)$ 은 $-\\dfrac12\\le t\\le\\dfrac12$ 에서, 접점 $\\left(t+\\dfrac12,\\ t-\\dfrac12\\right)$ 은 $t\\ge\\dfrac12$ 에서 그래프 위의 점","$y=-x+1$ 과는 $0<t<1$ 에서 두 점, $t=0,\\ 1$ 에서 한 점"],"설명":"접점은 중심에서 직선에 내린 수선의 발이고, 그 점이 그래프의 해당 선분 위에 있을 때만 교점이 된다. 중심에서 $y=-x+1$ 까지의 거리는 $\\frac{|2t-1|}{\\sqrt{2}}$ 이고 교점은 모두 $0\\le x\\le1$ 인 선분 위에 있다. $y=-x-1$ 위의 교점은 모두 $x\\ge-1$ 이어서 그래프의 $x<-1$ 부분에는 없다.","확인":null,"스킬":"G2"},{"제목":"g(t) 를 구간별로 정리하기","고비":true,"힌트":"접점이 선분 위에 있는 범위와 $y=-x+1$ 과의 교점 수를 더하면?","식":["$t<-\\dfrac12:\\ 0,\\ \\ -\\dfrac12\\le t<0:\\ 1$","$t=0:\\ 2,\\ \\ 0<t<\\dfrac12:\\ 3,\\ \\ t=\\dfrac12:\\ 2$","$\\dfrac12<t<1:\\ 3,\\ \\ t=1:\\ 2,\\ \\ t>1:\\ 1$"],"설명":"$t=0,\\ 1$ 에서는 $y=-x+1$ 과의 접점이 하나이다. $t=\\frac12$ 에서는 접점과 $y=-x+1$ 과의 교점이 모두 꺾이는 점 $(0,\\ 1),\\ (1,\\ 0)$ 에 겹쳐 $2$ 개가 된다.","확인":null,"스킬":"G2"},{"제목":"ㄴ 판정하기","힌트":"$g(t)$ 의 값이 바뀌는 $t$ 에서 좌극한과 우극한, 함숫값을 비교하면?","식":["$t=-\\dfrac12,\\ 0,\\ 1:\\ $ 좌극한과 우극한이 다르다","$t=\\dfrac12:\\ $ 극한 $3$, 함숫값 $2$","불연속점은 $-\\dfrac12,\\ 0,\\ \\dfrac12,\\ 1$ 의 $4$ 개"],"설명":"$t=\\frac12$ 에서는 좌극한과 우극한이 같아도 함숫값이 달라 불연속이다. 따라서 불연속점은 $4$ 개이고 ㄴ은 옳다.","확인":null,"스킬":"G5"},{"제목":"ㄷ 판정하고 옳은 보기 고르기","힌트":"$\\lim_{t\\to0+}g(t)$, $g\\left(\\frac12\\right)$, $\\lim_{t\\to1+}g(t)$ 를 각각 읽으면?","식":["$\\lim_{t\\to0+}g(t)=3,\\ \\ g\\left(\\dfrac12\\right)=2,\\ \\ \\lim_{t\\to1+}g(t)=1$","$3+2+1=6$ 이므로 ㄷ 옳음","ㄱ, ㄴ, ㄷ 모두 옳다"],"설명":"표에서 $0$ 의 오른쪽 값은 $3$, $t=\\frac12$ 의 함숫값은 $2$, $1$ 의 오른쪽 값은 $1$ 이다. 합이 $6$ 이어서 ㄷ도 옳다.","확인":null,"스킬":"G5"}]},"ns-58c511f9cdb9":{"길":"|f(x)|=1 이 되는 x=0, ±1 에서 g∘f 가 끊기는 것을 중심으로 본다","단계":[{"제목":"그래프에서 f(x) 의 식 구하기","힌트":"꼭짓점이 $(0,\\ -1)$ 인 이차함수가 $(1,\\ 1)$ 을 지나면 $f(x)$ 의 식은?","식":["$f(x)=ax^{2}-1$","$f(1)=a-1=1\\ \\Rightarrow\\ a=2$","$f(x)=2x^{2}-1$"],"설명":"그래프의 꼭짓점이 $y$축 위의 $(0,\\ -1)$ 이므로 $ax^{2}-1$ 꼴이고, $(1,\\ 1)$ 을 지난다는 조건으로 $a$ 를 정한다.","확인":"2","스킬":"T6"},{"제목":"(g∘f)(x) 를 구간별로 나타내기","고비":true,"힌트":"$|f(x)|$ 가 $1$ 보다 작을 때, $1$ 일 때, $1$ 보다 클 때의 $x$ 의 범위는?","식":["$|2x^{2}-1|=1\\ \\Rightarrow\\ x=0,\\ \\pm1$","$0<|x|<1:\\ (g\\circ f)(x)=|2x^{2}-1|$","$|x|>1:\\ (g\\circ f)(x)=0,\\ \\ x=0,\\ \\pm1:\\ \\dfrac12$"],"설명":"$2x^{2}-1=1$ 에서 $x=\\pm1$ 이고 $2x^{2}-1=-1$ 에서 $x=0$ 이다. $|f(x)|<1$ 은 $0<|x|<1$ 에, $|f(x)|>1$ 은 $|x|>1$ 에 해당한다.","확인":null,"스킬":"T6"},{"제목":"ㄱ 판정하기: 불연속점의 개수 세기","힌트":"$x=0$ 과 $x=\\pm1$ 에서 극한값과 함숫값은 각각 얼마일까?","식":["$x=0:\\ \\lim|2x^{2}-1|=1,\\ \\ (g\\circ f)(0)=\\dfrac12$","$x=\\pm1:\\ $ 좌우 극한이 $1$ 과 $0$, 함숫값 $\\dfrac12$","불연속점은 $x=-1,\\ 0,\\ 1$"],"설명":"극한값과 함숫값이 다르거나 좌우 극한이 다른 점이 불연속점이다. 불연속점은 $3$ 개이므로 ㄱ은 옳지 않다.","확인":"3","스킬":"G5"},{"제목":"ㄴ 판정하기: 미분가능하지 않은 점 세기","힌트":"불연속인 점 외에 그래프가 꺾이는 점은 어디일까?","식":["불연속인 $x=-1,\\ 0,\\ 1$ 은 미분가능하지 않다","$|2x^{2}-1|=0\\ \\Rightarrow\\ x=\\pm\\dfrac{1}{\\sqrt{2}}$ 에서 꺾인다","미분가능하지 않은 점은 $3+2$ 개"],"설명":"연속이 아닌 점에서는 미분가능하지 않다. 또 $|2x^{2}-1|$ 은 $2x^{2}-1=0$ 인 두 점에서 꺾인다. 따라서 ㄴ은 옳다.","확인":null,"스킬":"G5"},{"제목":"ㄷ 판정하고 옳은 보기 고르기","힌트":"$0<t<1$ 에서 $|2x^{2}-1|=t$ 의 해는 모두 몇 개일까?","식":["$x=\\pm\\sqrt{\\dfrac{1+t}{2}},\\ \\ x=\\pm\\sqrt{\\dfrac{1-t}{2}}$","$t\\ne\\dfrac12$ 이면 $h(t)=4$ 이므로 $\\lim_{t\\to1/2}h(t)=4$, ㄷ 옳음","옳은 것은 ㄴ, ㄷ"],"설명":"네 근은 모두 $0<|x|<1$ 에 있어 서로 다르다. $t=\\frac12$ 에서의 값 $h\\left(\\frac12\\right)$ 은 극한에 영향을 주지 않는다. 따라서 ㄷ은 옳고 옳은 것은 ㄴ, ㄷ 이다.","확인":null,"스킬":"G5"}]},"ns-59eefa529799":{"길":"x→0+ 로 b 를 정하고 분모가 x>0 에서 0 이 안 되게 a 를 좁힌다","단계":[{"제목":"g(0) 과 f(x) 의 꼴 정하기","힌트":"$g$ 가 $x=0$ 에서 연속이므로 $g(0)$ 은 $x<0$ 쪽 식 $h(x)$ 의 극한과 같다. 그 값은?","식":["$g(0)=\\lim_{x\\to0-}(x^{2}-3x+1)^{2}=1$","$f(0)g(0)=0\\ \\Rightarrow\\ f(0)=0$","$f(x)=x^{3}+ax^{2}+bx$"],"설명":"(가)에 $x=0$ 을 넣으면 $f(0)g(0)=0$ 이고 $g(0)=1$ 이므로 $f(0)=0$ 이다. 최고차항의 계수가 $1$ 인 삼차함수에서 상수항이 $0$ 이다.","확인":"1","스킬":"D12"},{"제목":"b 의 값 구하기","힌트":"$x>0$ 에서 (가)를 $x$ 로 나눈 식에서 $x\\to0+$ 의 극한을 취하면?","식":["$x>0:\\ (x^{2}+ax+b)g(x)=x+4$","$b\\cdot g(0)=4$","$b=4$"],"설명":"$g$ 가 연속이므로 $x\\to0+$ 일 때 $g(x)\\to g(0)=1$ 이다.","확인":null,"스킬":"D11"},{"제목":"분모 조건으로 a 의 범위 정하기","고비":true,"힌트":"$g(x)=\\frac{x+4}{x^{2}+ax+4}$ 가 $x>0$ 에서 연속이려면 분모는 어떤 조건을 만족해야 할까?","식":["$x>0$ 에서 $x^{2}+ax+4>0$","$a\\ge0$ 이면 성립","$a<0$ 이면 $D=a^{2}-16<0\\ \\Rightarrow\\ -4<a<0$, 따라서 $a>-4$"],"설명":"$g(x)$ 는 $x>0$ 에서 연속이므로 분모가 $0$ 이 될 수 없고, $x=0$ 에서 분모가 $4>0$ 이므로 $x>0$ 전체에서 양수이다. $a<0$ 이면 대칭축이 $x>0$ 에 있어 판별식이 음수여야 한다.","확인":null,"스킬":"C1"},{"제목":"(f∘g)(0) 조건으로 정수 a 구하기","힌트":"$(f\\circ g)(0)=f(g(0))=f(1)$ 을 $a$ 로 나타내면?","식":["$f(1)=1+a+4=5+a$","$5+a\\le8\\ \\Rightarrow\\ a\\le3$","정수 $a=-3,\\ -2,\\ \\cdots,\\ 3$"],"설명":"$f(1)=5+a$ 가 정수이므로 $a$ 도 정수이다. $a>-4$ 와 $a\\le3$ 을 합치면 $-3$ 부터 $3$ 까지의 정수이다.","확인":null,"스킬":"T3"},{"제목":"g(1) 의 최솟값과 최댓값의 합 구하기","힌트":"$g(1)=\\frac{5}{f(1)}$ 이므로 $a$ 가 어느 값일 때 가장 크고 가장 작을까?","식":["$g(1)=\\dfrac{1+4}{1+a+4}=\\dfrac{5}{a+5}$","$a=-3:\\ \\dfrac52$ (최대), $\\ a=3:\\ \\dfrac58$ (최소)","$\\dfrac52+\\dfrac58=\\dfrac{25}{8}$"],"설명":"$a+5$ 가 $2,\\ 3,\\ \\cdots,\\ 8$ 이므로 분모가 가장 작을 때 최대, 가장 클 때 최소이다. 두 값을 더한다.","확인":"25/8","스킬":"T3"}]},"ns-6085d9b043b5":{"길":"g 는 f 의 음수 부분을 0 으로, h 는 양수 부분을 0 으로 누른 그래프다","단계":[{"제목":"g 와 h 의 뜻 정리하기","힌트":"$f(x)>0$ 일 때와 $f(x)<0$ 일 때 $g,\\ h$ 는 각각 어떤 함수가 될까?","식":["$f>0:\\ g=f,\\ h=0$","$f<0:\\ g=0,\\ h=f$","$f(0)=1:\\ g(0)=1,\\ h(0)=0$"],"설명":"$f>0$ 이면 $|f|=f$ 이므로 $g=f$, $h=0$ 이다. $f<0$ 이면 $|f|=-f$ 이므로 $g=0$, $h=f$ 이다.","확인":null,"스킬":"G5"},{"제목":"ㄱ 판정하기","힌트":"$x\\to0-$ 에서는 $f$ 의 부호가, $x\\to0+$ 에서는 $f$ 의 부호가 어떨까?","식":["$x\\to0-:\\ f<0\\ \\Rightarrow\\ g=0$","$x\\to0+:\\ f>0\\ \\Rightarrow\\ g=f\\to1$","좌극한 $0$, 우극한 $1$"],"설명":"좌극한과 우극한이 달라 $\\lim_{x\\to0}g(x)$ 가 존재하지 않는다. 따라서 ㄱ은 옳다.","확인":null,"스킬":"G5"},{"제목":"ㄴ 판정하기","고비":true,"힌트":"$x<0$ 일 때와 $x>0$ 일 때 $g(x)$ 의 값이 $h$ 의 어느 부분으로 들어가는지 살피면?","식":["$x<0:\\ g(x)=0\\ \\Rightarrow\\ h(g(x))=h(0)=0$","$x\\to0+:\\ g(x)\\to1+,\\ h=0\\ \\Rightarrow\\ (h\\circ g)(x)\\to0$","$(h\\circ g)(0)=h(1)=0$"],"설명":"$g(x)$ 가 $1$ 보다 큰 값일 때 그 구간에서 $f>0$ 이어서 $h=0$ 이다. 좌극한, 우극한, 함숫값이 모두 $0$ 이므로 $x=0$ 에서 연속이고 ㄴ은 옳다.","확인":null,"스킬":"T6"},{"제목":"ㄷ 판정하기","힌트":"$x\\to0-$ 일 때 $f(x)$ 의 값과 부호는?","식":["$x\\to0-:\\ f(x)=-1<0\\ \\Rightarrow\\ h(x)=f(x)=-1$","$\\lim_{x\\to0-}h(x)=-1\\ne0$"],"설명":"$0$ 의 왼쪽에서 $f$ 는 일정하게 $-1$ 이므로 $h$ 도 $-1$ 이다. 따라서 ㄷ은 옳지 않다.","확인":"-1","스킬":"G5"},{"제목":"옳은 보기 고르기","힌트":"ㄱ, ㄴ, ㄷ 중 옳은 것은?","식":["ㄱ 옳음, ㄴ 옳음, ㄷ 옳지 않음"],"설명":"ㄱ, ㄴ 이 옳고 ㄷ 은 옳지 않다.","확인":null,"스킬":"G5"}]},"ns-60ced4a3e776":{"길":"두 함수가 끊기는 점마다 다른 함수의 값이 0 이어야 곱이 연속이다","단계":[{"제목":"곱이 연속이 되는 조건 세우기","고비":true,"힌트":"$f$ 가 끊기는 점과 $g$ 가 끊기는 점이 서로 다를 때, 곱이 연속이려면 그 점에서 다른 함수의 값은?","식":["$f$ 는 $x=-2$ 에서 불연속 (좌극한 $0$, 우극한 $4$)","$g(x)=f(x-a)+b$ 는 $x=a-2$ 에서 불연속","$a\\ne0$ 이면 $g(-2)=0,\\ f(a-2)=0$"],"설명":"끊기는 점에서 곱의 끊김이 사라지려면 다른 함수의 값이 $0$ 이어야 한다. $a\\ne0$ 이면 두 불연속점이 달라서 서로의 점에서 상대 함수는 연속이다.","확인":null,"스킬":"D12"},{"제목":"a≠0 일 때 a, b 구하기","힌트":"$a>0$ 이면 $a-2>-2$, $a<0$ 이면 $a-2<-2$ 이다. 각각 $f(a-2)=0$ 을 풀면?","식":["$a>0:\\ f(a-2)=|a-4|=0\\ \\Rightarrow\\ a=4,\\ \\ g(-2)=f(-6)+b=4+b=0\\ \\Rightarrow\\ b=-4$","$a<0:\\ f(a-2)=-a=0\\ \\Rightarrow\\ a=0$ 이므로 모순"],"설명":"$a<0$ 이면 $a-2<-2$ 에서 $f(x)=-x-2$ 이므로 $f(a-2)=-a$ 이다. 이것이 $0$ 이면 $a=0$ 이어서 가정에 맞지 않는다. 따라서 $(a,\\ b)=(4,\\ -4)$ 이다.","확인":null,"스킬":"C2"},{"제목":"a=0 일 때 b 구하기","힌트":"$a=0$ 이면 $g(x)=f(x)+b$ 이고 두 함수가 $x=-2$ 에서 함께 끊긴다. $x=-2$ 의 좌극한, 우극한, 함숫값을 비교하면?","식":["좌극한 $0\\times b=0$","우극한 $4(4+b)$, 함숫값 $f(-2)g(-2)=4(4+b)$","$4(4+b)=0\\ \\Rightarrow\\ b=-4$"],"설명":"$x\\to-2-$ 에서 $f\\to0$, $g\\to b$ 이고 $x\\to-2+$ 에서 $f\\to4$, $g\\to4+b$ 이다. 좌극한 $0$ 과 우극한이 같아야 하므로 $b=-4$ 이고 $(a,\\ b)=(0,\\ -4)$ 이다.","확인":null,"스킬":"D12"},{"제목":"p+q+r+s 계산하기","힌트":"두 순서쌍 $(4,\\ -4)$, $(0,\\ -4)$ 의 네 수를 모두 더하면?","식":["$p+q+r+s=4+(-4)+0+(-4)=-4$"],"설명":"구한 두 순서쌍의 성분을 모두 더한다.","확인":"-4","스킬":"C2"}]},"ns-63694ff4b979":{"길":"(가)로 a 의 범위를 잡고 (나)를 f(a)=0 인 경우와 극한이 같은 경우로 나눈다","단계":[{"제목":"(가)로 a 의 범위 정하기","힌트":"아래로 볼록한 $f$ 가 $(0,\\ 2)$ 에서 근을 가지려면 $f(0)$ 과 $f(2)$ 의 부호는?","식":["$f(0)=a>0$","$f(2)=4-12+a=a-8<0$","$0<a<8$"],"설명":"아래로 볼록한 이차함수이므로 두 끝에서 부호가 서로 다르면 $(0,\\ 2)$ 에 근이 있다. 이 조건이 근의 존재와 같다.","확인":null,"스킬":"C8"},{"제목":"(나)의 연속 조건식 세우기","고비":true,"힌트":"$x=a$ 에서 $g$ 의 함숫값, 우극한, 좌극한은 각각 얼마일까?","식":["$g(a)=\\lim_{x\\to a+}g(x)=2a+3a=5a$","$\\lim_{x\\to a-}g(x)=f(a+4)=a^{2}+3a-8,\\ \\ f(a)=a^{2}-5a$","$f(a)\\{5a-(a^{2}+3a-8)\\}=0$"],"설명":"$f(a)g(a)$ 가 연속이려면 좌극한과 우극한과 함숫값이 같아야 한다. 세 값에서 공통인 $f(a)$ 를 묶으면 $f(a)=0$ 이거나 $g$ 의 두 쪽 값이 같아야 한다.","확인":null,"스킬":"D12"},{"제목":"f(a)=0 인 경우 구하기","힌트":"$f(a)=a(a-5)=0$ 의 해 중 $0<a<8$ 에 맞는 것은?","식":["$a(a-5)=0\\ \\Rightarrow\\ a=0,\\ 5$","$0<a<8$ 이므로 $a=5$"],"설명":"$f(a)=a^{2}-6a+a=a(a-5)$ 이다. $a=0$ 은 (가)의 범위에 들어가지 않는다.","확인":"5","스킬":"C2"},{"제목":"g 의 두 쪽 값이 같은 경우 구하기","힌트":"$5a=a^{2}+3a-8$ 을 정리해 풀고 $0<a<8$ 에 맞는 것을 고르면?","식":["$a^{2}-2a-8=0\\ \\Rightarrow\\ (a+2)(a-4)=0$","$a=-2,\\ 4$ 중 $0<a<8$ 이므로 $a=4$"],"설명":"$a=-2$ 는 (가)의 범위 $0<a<8$ 에 들어가지 않는다.","확인":"4","스킬":"C2"},{"제목":"모든 a 의 값의 합 구하기","힌트":"두 경우에서 얻은 $a$ 를 더하면?","식":["$5+4=9$"],"설명":"조건을 만족하는 $a$ 는 $5,\\ 4$ 이다.","확인":"9","스킬":"C2"}]},"ns-63d4652d997a":{"길":"f 를 (x-1)(x-3)g(x) 로 두고 g(1), g(3) 의 부호가 반대임을 쓴다","단계":[{"제목":"f(x) 를 (x-1)(x-3)g(x) 꼴로 나타내기","힌트":"$x\\to1$, $x\\to3$ 에서 극한이 값을 가지려면 $f(1),\\ f(3)$ 은 얼마일까?","식":["$f(1)=0,\\ f(3)=0$","$f(x)=(x-1)(x-3)g(x)$ ($g$ 는 다항함수)"],"설명":"첫째 식은 분모가 $0$ 으로 가므로 $f(1)=0$ 이다. 둘째 식은 분자가 $0$ 으로 가는데 극한이 $100$ 이므로 분모 $f(x)$ 도 $0$ 으로 가서 $f(3)=0$ 이다.","확인":null,"스킬":"A4"},{"제목":"g(1) 구하기","힌트":"$\\frac{f(x)}{x-1}=(x-3)g(x)$ 에서 $x\\to1$ 의 극한을 $g(1)$ 로 쓰면?","식":["$\\lim_{x\\to1}(x-3)g(x)=-2g(1)=1$","$g(1)=-\\dfrac12$"],"설명":"$g$ 는 다항함수이므로 극한값이 $g(1)$ 의 식으로 바로 나온다.","확인":"-1/2","스킬":"D11"},{"제목":"g(3) 구하기","힌트":"$\\frac{x-3}{f(x)}=\\frac{1}{(x-1)g(x)}$ 에서 $x\\to3$ 의 극한을 $g(3)$ 으로 쓰면?","식":["$\\lim_{x\\to3}\\dfrac{1}{(x-1)g(x)}=\\dfrac{1}{2g(3)}=100$","$g(3)=\\dfrac{1}{200}$"],"설명":"앞 단계와 같은 방식으로 $x=3$ 에서의 극한을 $g(3)$ 으로 나타낸다.","확인":"1/200","스킬":"D11"},{"제목":"실근의 최소 개수 구하기","고비":true,"힌트":"$g(1)$ 과 $g(3)$ 의 부호가 다르면 $(1,\\ 3)$ 에서 $g$ 는 어떻게 될까?","식":["$g(1)<0<g(3)\\ \\Rightarrow\\ g(c)=0\\ (1<c<3)$ 인 $c$ 가 있다","근은 $x=1,\\ x=c,\\ x=3$","$g(x)=\\dfrac{101x-301}{400}$ 이면 $f$ 는 삼차이고 근이 정확히 $3$ 개"],"설명":"$g$ 는 연속이므로 사잇값 정리로 $(1,\\ 3)$ 에 근이 있고, $f$ 의 근은 서로 다른 세 개 이상이다. $g$ 를 일차식으로 잡으면 근이 정확히 $3$ 개여서 $3$ 이 최소이다.","확인":"3","스킬":"C8"}]},"ns-67d10b03a8f9":{"길":"두 식의 차 g(x) 와 수평선 y=t² 의 교점 수로 바꿔 센다","단계":[{"제목":"두 식의 차를 g(x) 로 놓기","힌트":"교점의 $x$ 좌표는 두 식의 차가 $0$ 인 곳이다. $x$ 에 관한 식과 $t^{2}$ 로 갈라 놓으면?","식":["$g(x)=3x^{2}-5|x|+2-(x^{2}+x)=2x^{2}-5|x|-x+2$","교점 $\\Leftrightarrow\\ g(x)=t^{2}$"],"설명":"$3x^{2}-5|x|+2=x^{2}+x+t^{2}$ 에서 $t^{2}$ 만 한쪽으로 모으면 된다. 따라서 $f(t)$ 는 $y=g(x)$ 와 수평선 $y=t^{2}$ 의 교점의 개수이다.","확인":null,"스킬":"G1"},{"제목":"g(x) 를 절댓값 없이 쓰기","힌트":"$x\\ge0$ 일 때와 $x<0$ 일 때 $|x|$ 를 각각 어떻게 쓸까?","식":["$x\\ge0:\\ g(x)=2x^{2}-6x+2$","$x<0:\\ g(x)=2x^{2}+4x+2=2(x+1)^{2}$"],"설명":"$x\\ge0$ 이면 $|x|=x$, $x<0$ 이면 $|x|=-x$ 이다.","확인":null,"스킬":"G5"},{"제목":"g 의 그래프 모양 파악하기","힌트":"$x\\ge0$ 쪽 이차함수의 꼭짓점의 $y$ 좌표는?","식":["$x<0:\\ x=-1$ 에서 최솟값 $0$","$g(0)=2$","$x\\ge0:\\ g(x)=2\\left(x-\\dfrac32\\right)^{2}-\\dfrac52$"],"설명":"$x<0$ 쪽은 $x=-1$ 에서 $0$ 이고 $x=0$ 으로 가면서 $2$ 에 가까워진다. $x\\ge0$ 쪽은 $x=0$ 에서 $2$ 이고 $x=\\frac32$ 에서 최솟값 $-\\frac52$ 를 가진 뒤 다시 올라간다.","확인":"-5/2","스킬":"G5"},{"제목":"수평선 y=s 와의 교점 수 정리하기","고비":true,"힌트":"$s=t^{2}\\ge0$ 일 때 $s=0$, $0<s<2$, $s=2$, $s>2$ 에서 각 쪽의 교점은 몇 개일까?","식":["$s=0:\\ 3,\\ \\ 0<s<2:\\ 4$","$s=2:\\ 3,\\ \\ s>2:\\ 2$"],"설명":"$0<s<2$ 이면 $x<0$ 쪽에서 두 점, $x\\ge0$ 쪽에서 두 점이다. $s=0$ 이면 $x<0$ 쪽은 꼭짓점 한 점과 $x\\ge0$ 쪽 두 점이고, $s=2$ 이면 $x=-2$ 와 $x=0,\\ 3$ 의 세 점이다. $s>2$ 이면 두 쪽에서 한 점씩이다.","확인":null,"스킬":"G5"},{"제목":"불연속인 t 구하기","힌트":"$t=0$ 과 $t=\\pm\\sqrt{2}$ 에서 $f(t)$ 를 이웃한 구간의 값과 비교하면?","식":["$t=0:\\ f=3,\\ \\ 0<|t|<\\sqrt{2}:\\ f=4$","$t=\\pm\\sqrt{2}:\\ f=3,\\ \\ |t|>\\sqrt{2}:\\ f=2$","불연속인 $t=-\\sqrt{2},\\ 0,\\ \\sqrt{2}$"],"설명":"$s=t^{2}$ 이므로 $t$ 가 $0$ 과 $\\pm\\sqrt{2}$ 를 지날 때 $s$ 가 $0$, $2$ 를 지나며 값이 바뀐다. 세 점 모두 함숫값이 이웃한 구간의 값과 달라 불연속이다.","확인":null,"스킬":"G1"}]},"ns-68510a872bf6":{"길":"f(x)+b 가 끊기는 x=1 에서는 f(1-a)=0, f(x-a) 가 끊기는 x=a+1 에서는 f(a+1)+b=0","단계":[{"제목":"곱이 연속이 되는 조건 정리하기","힌트":"$f$ 가 끊기는 곳은 $x=1$ 이다. $f(x-a)$ 와 $f(x)+b$ 는 각각 어느 $x$ 에서 끊길까?","식":["$f(x-a):\\ x=a+1$ 에서 불연속","$f(x)+b:\\ x=1$ 에서 불연속","$a\\ne0$ 이므로 두 점이 다르다"],"설명":"두 인수가 서로 다른 점에서 끊기므로 각 점에서 상대 인수는 연속이다. 그 점에서 상대 인수의 값이 $0$ 이어야 끊김이 사라진다.","확인":null,"스킬":"C2"},{"제목":"x=1 에서의 연속 조건으로 a 구하기","고비":true,"힌트":"$x=1$ 에서 곱이 연속이려면 연속인 인수 $f(x-a)$ 의 $x=1$ 에서의 값은?","식":["$f(1-a)=0$","$1-a<1:\\ \\dfrac13(1-a+4)=0\\ \\Rightarrow\\ a=5$","$1-a\\ge1:\\ -2-(1-a)=a-3=0\\ \\Rightarrow\\ a=3$ 은 조건에 맞지 않는다"],"설명":"$f(x)+b$ 의 좌우 극한이 다르므로 $f(1-a)$ 가 $0$ 이어야 한다. $1-a\\ge1$ 이면 $a\\le0$ 이어야 하는데 $a=3$ 이 나와 모순이다.","확인":"5","스킬":"C2"},{"제목":"x=a+1 에서의 연속 조건으로 b 구하기","힌트":"$a=5$ 일 때 $x=a+1=6$ 에서 연속인 인수 $f(x)+b$ 의 값이 $0$ 이어야 한다. $f(6)$ 은?","식":["$f(6)+b=0$","$f(6)=-2-6=-8$","$b=8$"],"설명":"$6\\ge1$ 이므로 $f(x)=-2-x$ 를 쓴다.","확인":"8","스킬":"C2"},{"제목":"a+b 계산하기","힌트":"$a=5,\\ b=8$ 을 더하면?","식":["$a+b=5+8=13$"],"설명":"구한 두 상수를 더한다.","확인":"13","스킬":"C2"}]},"ns-686ac588134c":{"길":"합과 곱으로 표현되는 식은 연속이고 그렇지 않은 식은 반례를 찾는다","단계":[{"제목":"주어진 조건 정리하기","힌트":"$f+g$ 와 $fg$ 가 연속일 때 어떤 꼴의 식이 연속이 될까?","식":["$f+g,\\ fg$ 는 $x=a$ 에서 연속","두 함수의 대칭식은 $f+g$ 와 $fg$ 로 나타낼 수 있다"],"설명":"연속인 함수끼리의 합, 곱, 분모가 $0$ 이 아닌 나눗셈은 연속이다. 따라서 보기를 $f+g$ 와 $fg$ 로 나타낼 수 있는지가 핵심이다.","확인":null,"스킬":"A2"},{"제목":"ㄱ 판정하기","힌트":"$\\frac{1}{f}+\\frac{1}{g}$ 를 통분하면?","식":["$\\dfrac{1}{f(x)}+\\dfrac{1}{g(x)}=\\dfrac{f(x)+g(x)}{f(x)g(x)}$","분모 $f(a)g(a)\\ne0$","$x=a$ 에서 연속"],"설명":"분자 $f+g$ 와 분모 $fg$ 가 모두 연속이고 분모의 값이 $0$ 이 아니므로 연속이다. 따라서 ㄱ은 항상 연속이다.","확인":null,"스킬":"A2"},{"제목":"ㄴ 의 반례 찾기","고비":true,"힌트":"$f$ 와 $g$ 의 값을 $x=a$ 에서 서로 바꿔 놓으면 $f+g$, $fg$ 는 어떻게 될까?","식":["$f=1,\\ g=2\\ (x\\ge a),\\ \\ f=2,\\ g=1\\ (x<a)$","$f+g=3,\\ fg=2$ 로 모두 연속","$f^{2}-g^{2}:\\ x\\to a-$ 에서 $3,\\ x\\to a+$ 에서 $-3$"],"설명":"두 값을 맞바꾸면 합과 곱은 그대로이지만 $f^{2}-g^{2}$ 은 부호가 바뀌어 불연속이다. 따라서 ㄴ은 반드시 연속이라고 할 수 없다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 판정하고 옳은 보기 고르기","힌트":"$p_{n}=f^{n}+g^{n}$ 을 $f+g$, $fg$, $p_{n-1}$, $p_{n-2}$ 로 나타내면?","식":["$p_{n}=(f+g)p_{n-1}-fg\\,p_{n-2}$","$p_{1}=f+g,\\ p_{2}=(f+g)^{2}-2fg$ 가 연속이므로 차례로 모든 $p_{n}$ 이 연속","옳은 것은 ㄱ, ㄷ"],"설명":"$f^{n}+g^{n}=(f+g)(f^{n-1}+g^{n-1})-fg(f^{n-2}+g^{n-2})$ 이므로 앞의 두 항이 연속이면 다음 항도 연속이다. 따라서 $2019$ 제곱의 합도 연속이고, 반드시 연속인 것은 ㄱ, ㄷ 이다.","확인":null,"스킬":"A2"}]},"ns-6c04fb947258":{"길":"연속 조건에서 f(±t)=t 를 얻고 b=0 으로 t 의 이차방정식의 양의 근 조건을 쓴다","단계":[{"제목":"x=±t 에서의 연속 조건 세우기","고비":true,"힌트":"$x=t$ 에서 $|f(t)-2t|$ 와 $f(t)$ 가 같아지려면 $f(t)-2t$ 는 $f(t)$ 와 어떤 관계여야 할까?","식":["$|f(t)-2t|=f(t)$","$f(t)-2t=-f(t)\\ \\Rightarrow\\ f(t)=t$","같은 방식으로 $f(-t)=t$"],"설명":"$f(t)-2t=f(t)$ 는 $t>0$ 이어서 불가능하므로 $f(t)-2t=-f(t)$ 이다. $x=-t$ 에서도 같은 조건이 나온다.","확인":null,"스킬":"A2"},{"제목":"b 의 값과 t 에 대한 방정식 구하기","힌트":"$f(t)=t$ 와 $f(-t)=t$ 를 빼면 $b$ 는?","식":["$at^{2}+bt+a=t,\\ \\ at^{2}-bt+a=t$","$2bt=0\\ \\Rightarrow\\ b=0$","$at^{2}-t+a=0$"],"설명":"$t>0$ 이므로 $b=0$ 이다. 이때 $f(t)=t$ 는 $t$ 에 대한 이차방정식 $at^{2}-t+a=0$ 이 된다.","확인":"0","스킬":"A2"},{"제목":"서로 다른 두 양의 근 조건으로 a 의 범위 정하기","힌트":"$at^{2}-t+a=0$ 이 서로 다른 두 양의 실근을 가질 조건은 판별식과 두 근의 합·곱으로 어떻게 쓸까?","식":["$D=1-4a^{2}>0\\ \\Rightarrow\\ -\\dfrac12<a<\\dfrac12$","두 근의 합 $\\dfrac1a>0\\ \\Rightarrow\\ a>0$","$0<a<\\dfrac12$"],"설명":"$t$ 는 양수이고 서로 다른 값이 $2$ 개여야 하므로 판별식이 양수이고 두 근의 합이 양수이다. 두 근의 곱은 $1$ 로 항상 양수이다.","확인":null,"스킬":"A2"}]},"ns-6c88875fad8c":{"길":"t=-8 의 직선이 (4, 0) 을 지날 때 오른쪽 가지의 기울기와 2 를 비교한다","단계":[{"제목":"직선이 (4, 0) 에서 접하는 a 구하기","힌트":"$t=-8$ 이면 $y=2x-8$ 은 $(4,\\ 0)$ 을 지난다. 곡선의 $x\\ge4$ 부분의 $x=4$ 에서의 기울기가 $2$ 가 되려면?","식":["$y=\\dfrac{1}{a}(x^{2}-4x),\\ \\ y'=\\dfrac{1}{a}(2x-4)$","$\\dfrac{1}{a}(2\\cdot4-4)=2$","$a=2$"],"설명":"$(4,\\ 0)$ 은 곡선의 꺾이는 점이다. 직선이 $x\\ge4$ 쪽 곡선과 이 점에서 접하는 때가 경계이다.","확인":"2","스킬":"D1"},{"제목":"a≤2 일 때 f(t) 의 극한 구하기","고비":true,"힌트":"$a\\le2$ 이면 오른쪽 가지는 $(4,\\ 0)$ 에서 직선보다 가파르다. $t$ 가 $-8$ 보다 작을 때와 클 때 교점은 몇 개일까?","식":["$\\lim_{t\\to-8-}f(t)=0$","$\\lim_{t\\to-8+}f(t)=2$","좌극한 $\\ne$ 우극한이므로 불연속"],"설명":"$t<-8$ 이면 직선이 곡선 아래를 지나 만나지 않고, $t>-8$ 이면 꺾이는 점 왼쪽의 산 모양과 오른쪽 가지에서 한 점씩 만난다. 두 극한이 달라 연속이 아니다.","확인":null,"스킬":"G5"},{"제목":"a>2 일 때 연속 확인하기","힌트":"$a>2$ 이면 오른쪽 가지는 $(4,\\ 0)$ 에서 직선보다 완만하다. $t=-8$ 의 직선과 그 양쪽의 직선은 교점이 몇 개일까?","식":["$\\lim_{t\\to-8-}f(t)=\\lim_{t\\to-8+}f(t)=f(-8)=2$","$a>2$ 이면 연속"],"설명":"$t=-8$ 의 직선은 $(4,\\ 0)$ 과 $x>4$ 의 한 점에서 곡선과 만나 $2$ 개이다. $t$ 가 $-8$ 의 양쪽에서 조금 달라져도 $2$ 개이므로 연속이다.","확인":null,"스킬":"G5"},{"제목":"자연수 a 의 최솟값 구하기","힌트":"$a>2$ 인 자연수 중 가장 작은 수는?","식":["$a>2$ 인 자연수 중 최솟값은 $3$"],"설명":"연속이 되려면 $a>2$ 이어야 하므로 자연수 중 가장 작은 값을 고른다.","확인":"3","스킬":"G5"}]},"ns-700377856711":{"길":"m=n, m<n 은 곱이 이어지지 않고 m>n 에서 2m=3n 일 때만 이어진다","단계":[{"제목":"ㄱ 판정하기","힌트":"$f$ 가 $x=m$ 에서 연속이려면 $x^{2}$ 와 $x$ 의 값이 어떤 관계여야 할까?","식":["$m^{2}=m\\ \\Rightarrow\\ m=0,\\ 1$","자연수 $m=1$ 하나"],"설명":"$f$ 는 $x=m$ 에서만 끊길 수 있고, 두 식이 같은 값이 될 때 연속이다. 자연수 $m$ 은 $1$ 하나이므로 ㄱ은 옳다.","확인":null,"스킬":"C2"},{"제목":"ㄴ 판정하기","힌트":"$m=1$ 일 때 $g$ 가 $x=n$ 에서 연속이려면 $n$ 은?","식":["$g(x)=-2x+1\\ (x\\le n),\\ \\ x-1\\ (x>n)$","$-2n+1=n-1\\ \\Rightarrow\\ n=\\dfrac23$"],"설명":"$n$ 은 자연수이므로 $\\frac{2}{3}$ 는 될 수 없다. 따라서 $g$ 는 연속일 수 없고 ㄴ은 옳지 않다.","확인":null,"스킬":"C2"},{"제목":"m=n, m<n 인 경우 제외하기","힌트":"$m=n$ 일 때 $x=m$ 에서 $f(x)g(x)$ 의 좌극한, 우극한, 함숫값은? $m<n$ 일 때 $x=m$ 에서 $g(m)$ 의 값은?","식":["$m=n:\\ $ 좌극한과 함숫값 $-m^{3}$, 우극한 $0$, $-m^{3}=0$ 인 자연수 없음","$m<n:\\ g(m)=-m\\ne0$ 이므로 $f$ 가 연속이어야 해 $m=1$","$m=1$ 이면 $x=n$ 에서 $-2n+1=n-1$, 즉 $n=\\dfrac23$ 이어서 불가능"],"설명":"$m<n$ 이면 $x=m$ 에서 $g$ 는 연속이고 값이 $0$ 이 아니므로 $f$ 가 끊기지 않아야 한다. $m=1$ 이어도 $x=n$ 에서 $f(n)=n\\ne0$ 이라 $g$ 가 연속이어야 하는데 $n$ 이 자연수가 아니다.","확인":null,"스킬":"C2"},{"제목":"m>n 인 경우 순서쌍 세기","고비":true,"힌트":"$x=n$ 에서 $f(n)=n^{2}\\ne0$ 이면 $g$ 는 어떻게 되어야 할까? $x=m$ 에서 $g(m)$ 은?","식":["$x=n:\\ -2n+m=n-m\\ \\Rightarrow\\ 2m=3n$","$x=m:\\ g(m)=m-m=0$ 이므로 곱은 연속","$(n,\\ m)=(2,\\ 3),\\ (4,\\ 6),\\ (6,\\ 9)$ 의 $3$ 쌍"],"설명":"$n<m$ 이므로 $x=n$ 에서 $f$ 는 연속이고 값이 $0$ 이 아니어서 $g$ 가 연속이어야 한다. $m\\le10$ 에서 $n=2k,\\ m=3k$ 이고 $k=1,\\ 2,\\ 3$ 이다.","확인":"3","스킬":"C2"},{"제목":"ㄷ 판정하고 옳은 보기 고르기","힌트":"순서쌍의 개수가 $10$ 개일까?","식":["순서쌍은 $3$ 개이므로 $10$ 개라는 ㄷ은 옳지 않다","ㄱ 옳음, ㄴ 옳지 않음, ㄷ 옳지 않음"],"설명":"세 경우를 모두 합쳐도 순서쌍은 $3$ 개뿐이다. 따라서 옳은 것은 ㄱ뿐이다.","확인":null,"스킬":"C2"}]},"ns-7071822068f9":{"길":"g(x) 가 0 의 오른쪽에서 1 보다 큰 쪽으로 다가간다는 점을 쓴다","단계":[{"제목":"그래프에서 x=0 의 극한과 함숫값 읽기","힌트":"$x=0$ 에서 $f$ 와 $g$ 의 좌극한, 우극한, 함숫값은 각각 얼마일까?","식":["$f:\\ $ 좌극한 $0$, 우극한 $0$, $f(0)=1$","$g:\\ $ 좌극한 $0$, 우극한 $1$, $g(0)=0$"],"설명":"빈 점은 그래프가 다가가는 값이고 채운 점은 함숫값이다. $g$ 는 오른쪽에서 $1$ 보다 큰 값으로 $1$ 에 다가간다.","확인":null,"스킬":"T6"},{"제목":"ㄱ 판정하기","힌트":"$f(x)g(x)$ 의 좌극한, 우극한, 함숫값을 각각 곱으로 구하면?","식":["$\\lim_{x\\to0-}fg=0\\times0=0$","$\\lim_{x\\to0+}fg=0\\times1=0$","$f(0)g(0)=1\\times0=0$"],"설명":"세 값이 모두 $0$ 으로 같으므로 $x=0$ 에서 연속이다. 따라서 ㄱ은 옳다.","확인":null,"스킬":"T6"},{"제목":"ㄴ 판정하기","고비":true,"힌트":"$x\\to0-$ 일 때와 $x\\to0+$ 일 때 $g(x)$ 는 어떤 값에 가까워지고, 그 값에서 $f$ 는?","식":["$x\\to0-:\\ g(x)\\to0-,\\ \\ f(g(x))\\to0$","$x\\to0+:\\ g(x)\\to1+,\\ \\ f(g(x))\\to f(1)>0$","좌극한 $0\\ne$ 우극한"],"설명":"$x\\to0+$ 이면 $g(x)$ 는 $1$ 보다 큰 값으로 $1$ 에 다가가고 $f$ 는 $x=1$ 에서 연속이며 $f(1)>0$ 이다. 좌극한과 우극한이 달라 불연속이므로 ㄴ은 옳지 않다.","확인":null,"스킬":"T6"},{"제목":"ㄷ 판정하고 옳은 보기 고르기","힌트":"$x\\to0$ 일 때 $f(x)$ 는 어느 쪽에서 $0$ 에 가까워지고, 그때 $g(f(x))$ 의 극한과 $g(f(0))$ 은?","식":["$x\\to0:\\ f(x)\\to0+,\\ \\ g(f(x))\\to1$","$g(f(0))=g(1)>1$","극한 $1\\ne$ 함숫값이므로 불연속, 옳은 것은 ㄱ"],"설명":"$f(x)$ 는 $0$ 보다 큰 값으로 $0$ 에 다가가므로 $g$ 의 우극한 $1$ 이 극한이 된다. 그러나 $g(1)$ 은 $1$ 이 아니므로 연속이 아니고, 옳은 것은 ㄱ뿐이다.","확인":null,"스킬":"T6"}]},"ns-716709e6a16d":{"길":"|x|=1 경계의 좌우 극한을 구간별 식에 넣어 비교한다","단계":[{"제목":"ㄱ 판정하기","힌트":"$x=-1$ 의 왼쪽은 $|x|>1$ 의 식, 오른쪽은 $|x|<1$ 의 식이다. 각각 대입하면?","식":["$\\lim_{x\\to-1-}\\dfrac{ax}{x-1}=\\dfrac{-a}{-2}=\\dfrac{a}{2}$","$\\lim_{x\\to-1+}\\dfrac{a}{1-x}=\\dfrac{a}{2},\\ \\ f(-1)=\\dfrac{a}{2}$"],"설명":"좌극한, 우극한, 함숫값이 모두 $\\frac{a}{2}$ 로 같으므로 $x=-1$ 에서 연속이다. 따라서 ㄱ은 옳다.","확인":null,"스킬":"C2"},{"제목":"ㄴ 판정하기","고비":true,"힌트":"$x\\to1-$ 일 때 $\\frac{a}{1-x}$ 는 어떻게 될까? $a=0$ 이면 $f(x)$ 는?","식":["$a\\ne0:\\ \\lim_{x\\to1-}\\dfrac{a}{1-x}$ 는 발산하므로 $x=1$ 에서 불연속","$a=0:\\ f(x)=0$ 이므로 모든 실수에서 연속"],"설명":"$a\\ne0$ 이면 분모가 $0$ 에 가까워져 극한이 존재하지 않는다. $a=0$ 이면 어느 구간에서나 $0$ 이어서 연속이다. 따라서 ㄴ은 옳다.","확인":null,"스킬":"C2"},{"제목":"ㄷ 판정하고 옳은 보기 고르기","힌트":"$a\\ne0$ 일 때 $|x|>1$, $|x|<1$, $|x|=1$ 에서 $f(x)=a$ 의 해를 각각 구하면?","식":["$|x|>1:\\ \\dfrac{ax}{x-1}=a\\ \\Rightarrow\\ ax=ax-a$, 해 없음","$|x|<1:\\ \\dfrac{a}{1-x}=a\\ \\Rightarrow\\ x=0$","$|x|=1:\\ \\dfrac{a}{2}=a$, 해 없음, 옳은 것은 ㄱ, ㄴ"],"설명":"실근은 $x=0$ 하나뿐이어서 두 개라는 ㄷ은 옳지 않다. 따라서 옳은 것은 ㄱ, ㄴ 이다.","확인":null,"스킬":"C2"}]},"ns-804124bbfde8":{"길":"꼭짓점 (0, k) 를 올리며 포물선과 정사각형 둘레의 교점 수를 구간별로 센다","단계":[{"제목":"꼭짓점이 아래변에 닿는 순간 찾기","힌트":"꼭짓점 $(0,\\ k)$ 가 정사각형 아래변 $y=-1$ 에 처음 닿을 때 $k$ 는 얼마일까?","식":["$k<-1$ 이면 교점 $0$ 개","$k=-1$ 이면 꼭짓점 $(0,\\ -1)$ 에서 닿아 교점 $1$ 개","$k$ 가 조금 더 커지면 아래변이나 좌우변과 $2$ 점에서 만나 교점 $2$ 개"],"설명":"포물선은 꼭짓점이 가장 높다. $k<-1$ 이면 정사각형 아래를 지나고, $k=-1$ 에서 아래변에 접한다. $k=0$ 일 때는 아래 모서리 $(\\pm1,\\ -1)$ 을 지나며 역시 $2$ 개이다.","확인":"-1","스킬":"G1"},{"제목":"꼭짓점이 윗변에 닿는 순간의 교점 수 세기","힌트":"$k=1$ 이면 꼭짓점 $(0,\\ 1)$ 이 윗변 위에 있다. 이때 포물선과 정사각형의 교점은 모두 몇 개일까?","식":["$k=1$: 윗변과 $(0,\\ 1)$ 에서 접한다","$x=\\pm1$ 이면 $y=-1+1=0$ 이므로 좌우변과 $(\\pm1,\\ 0)$ 에서 만난다","교점은 $1+2$ 개"],"설명":"$y=-x^{2}+1$ 에 $x=\\pm1$ 을 넣으면 $y=0$ 이고 $-1\\le0\\le1$ 이므로 좌우변 위의 점이다. 윗변과의 접점까지 합하면 $f(1)$ 이 정해진다.","확인":"3","스킬":"G1"},{"제목":"윗변을 넘어선 뒤 교점 수 따지기","고비":true,"힌트":"$1<k<2$ 이면 포물선은 윗변과 몇 점, 좌우변과 몇 점에서 만날까?","식":["$1<k<2$: 윗변 $y=1$ 과 $x=\\pm\\sqrt{k-1}$ 에서 $2$ 점, 좌우변과 $(\\pm1,\\ k-1)$ 에서 $2$ 점","$k=2$: 모서리 $(\\pm1,\\ 1)$ 만 지나 $2$ 개","$k>2$: 정사각형 위를 지나 $0$ 개"],"설명":"$0<k-1<1$ 이면 $\\sqrt{k-1}<1$ 이므로 윗변 위의 두 점과 좌우변 위의 두 점이 모두 정사각형 둘레에 있다. $k=2$ 이면 이 점들이 합쳐져 모서리 두 곳만 남는다.","확인":"4","스킬":"C2"},{"제목":"불연속인 k 의 값을 모아 합 구하기","힌트":"$f(k)$ 의 값이 바뀌는 곳 중 좌극한, 우극한, 함숫값이 모두 같지 않은 $k$ 는 어디일까?","식":["$k=-1$: 좌극한 $0$, 함숫값 $1$","$k=1$: 극한 $2$, 함숫값 $3$ 이고 $k=2$: 좌극한 $4$, 함숫값 $2$","$k=0$ 은 앞뒤 값이 모두 $2$ 로 연속이므로 합은 $-1+1+2$"],"설명":"구간마다 $f(k)$ 는 $0,\\ 1,\\ 2,\\ 3,\\ 4,\\ 2,\\ 0$ 으로 바뀐다. 접하거나 모서리를 지나는 $k=-1,\\ 1,\\ 2$ 에서만 극한과 함숫값이 어긋난다.","확인":"2","스킬":"D12"}]},"ns-a0698122e221":{"길":"x=-1 근처의 좌우 극한을 그래프에서 읽어 보기마다 따진다","단계":[{"제목":"ㄱ: x=-1 에서 f-g 의 좌우 극한 비교","힌트":"$x\\to-1+$ 일 때 $f(x)$ 와 $g(x)$ 가 가까워지는 값을 읽고 빼면?","식":["$\\lim_{x\\to-1-}\\{f(x)-g(x)\\}=1-(-1)=2$","$\\lim_{x\\to-1+}\\{f(x)-g(x)\\}=2-1=1$","좌극한 $\\ne$ 우극한이므로 불연속 (ㄱ 거짓)"],"설명":"$f$ 는 $x=-1$ 왼쪽에서 $1$, 오른쪽에서 $2$ 로 가까워지고, $g$ 는 왼쪽에서 $-1$, 오른쪽에서 $1$ 로 가까워진다. 좌우 극한이 서로 달라 연속이 아니다.","확인":"1","스킬":"C3"},{"제목":"ㄴ: 안쪽 식이 다가가는 방향 확인하기","힌트":"$x\\to\\infty$ 일 때 $\\frac{1}{x}-1$ 은 $-1$ 의 오른쪽에서 다가간다. 이때 $f$ 의 값이 가까워지는 곳은?","식":["$x\\to\\infty$ 이면 $\\dfrac{1}{x}-1\\to-1+$","$\\lim_{x\\to\\infty}f\\left(\\dfrac{1}{x}-1\\right)=\\lim_{t\\to-1+}f(t)=2$","ㄴ 참"],"설명":"$\\dfrac1x$ 은 양수이면서 $0$ 으로 가므로 $\\dfrac1x-1$ 은 $-1$ 보다 큰 쪽에서 $-1$ 에 다가간다. $f$ 의 $x=-1$ 에서의 우극한 $2$ 를 읽는다.","확인":"2","스킬":"T6"},{"제목":"ㄷ: (f∘f)(x) 의 좌극한 구하기","고비":true,"힌트":"$x\\to-1-$ 일 때 $f(x)$ 는 $1$ 의 왼쪽에서 다가간다. 이때 바깥 $f$ 의 값이 가까워지는 곳은?","식":["$x\\to-1-$ 이면 $f(x)\\to1-$","$\\lim_{x\\to-1-}f(f(x))=\\lim_{t\\to1-}f(t)=1$","$f(f(-1))=f(2)=2$ 이므로 좌극한 $\\ne$ 함숫값 (ㄷ 거짓)"],"설명":"안쪽 $f(x)$ 가 $1$ 보다 작은 쪽에서 $1$ 로 가므로 바깥 $f$ 는 $x=1$ 의 왼쪽 극한을 읽어야 한다. $f(1)$ 의 함숫값과 혼동하지 않는다.","확인":"1","스킬":"T6"},{"제목":"참인 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 옳은 것은 어느 것일까?","식":["ㄱ 거짓, ㄴ 참, ㄷ 거짓","옳은 것은 ㄴ"],"설명":"세 보기 모두 함숫값이 아니라 좌우 극한을 비교해 판정한다. 옳은 것은 ㄴ 하나이다.","확인":null,"스킬":"C3"}]},"ns-acdf2a09adbd":{"길":"포물선이 V자 그래프에 접하는 두 t 에서 f 가 바뀌는 것을 이용해 g 의 두 근을 정한다","단계":[{"제목":"직선 y=x-1 에 접하는 t 구하기","고비":true,"힌트":"포물선과 $y=x-1$ 을 연립한 이차방정식의 판별식이 $0$ 이 되려면 $t$ 는?","식":["$-x^{2}+2tx-t^{2}+1=x-1\\ \\Rightarrow\\ x^{2}+(1-2t)x+t^{2}-2=0$","$D=(1-2t)^{2}-4(t^{2}-2)=9-4t=0$","$t=\\dfrac94$"],"설명":"$f(t)$ 는 꼭짓점 $(t,\\ 1)$ 이 움직일 때 포물선과 $y=|x-1|$ 의 교점 수이므로 개수가 바뀌는 때는 접할 때이다. 접점의 $x$ 좌표가 $\\dfrac74\\ge1$ 이어서 $y=x-1$ 쪽 가지 위의 점이다.","확인":"9/4","스킬":"G2"},{"제목":"직선 y=-x+1 에 접하는 t 구하기","힌트":"같은 방법으로 포물선이 $y=-x+1$ 에 접하게 하는 $t$ 는?","식":["$-x^{2}+2tx-t^{2}+1=-x+1\\ \\Rightarrow\\ x^{2}-(2t+1)x+t^{2}=0$","$D=(2t+1)^{2}-4t^{2}=4t+1=0$","$t=-\\dfrac14$"],"설명":"접점의 $x$ 좌표는 $\\dfrac14\\le1$ 이어서 $y=-x+1$ 쪽 가지 위의 점이다. 두 직선이 $x=1$ 에 대해 대칭이므로 $\\dfrac94$ 와 $-\\dfrac14$ 도 $1$ 에 대해 대칭인 값이다.","확인":"-1/4","스킬":"G2"},{"제목":"t 에 따른 교점 수 f(t) 정하기","힌트":"$t$ 가 두 접하는 값 사이에 있을 때 교점은 몇 개일까? $f(2)$ 는?","식":["$f(t)=0\\ \\left(t<-\\dfrac14\\right),\\ \\ 1\\ \\left(t=-\\dfrac14\\right),\\ \\ 2\\ \\left(-\\dfrac14<t<\\dfrac94\\right)$","$f(t)=1\\ \\left(t=\\dfrac94\\right),\\ \\ 0\\ \\left(t>\\dfrac94\\right)$","$-\\dfrac14<2<\\dfrac94$ 이므로 $f(2)$ 를 읽는다"],"설명":"두 접하는 값 사이에서는 포물선이 V자 그래프와 두 점에서 만나고, 접할 때 한 점으로 줄며 그 밖에서는 만나지 않는다.","확인":"2","스킬":"G2"},{"제목":"연속 조건으로 g(t) 정하고 g(3) 구하기","힌트":"$f(t)g(t)$ 가 $t=-\\frac14$ 와 $t=\\frac94$ 에서 연속이려면 $g$ 는 이 두 점에서 얼마여야 할까? 그때 $g(3)$ 은?","식":["$g\\left(-\\dfrac14\\right)=0,\\ \\ g\\left(\\dfrac94\\right)=0$","$g(t)=\\left(t+\\dfrac14\\right)\\left(t-\\dfrac94\\right)$","$g(3)=\\dfrac{13}{4}\\cdot\\dfrac34$"],"설명":"$t=-\\dfrac14$ 왼쪽에서 $f$ 는 $0$ 이고 $f\\left(-\\dfrac14\\right)=1$ 이므로 연속이려면 $g\\left(-\\dfrac14\\right)=0$ 이어야 한다. $t=\\dfrac94$ 도 같다. 최고차항의 계수가 $1$ 인 이차함수이므로 두 근이 이 두 값이다.","확인":"39/16","스킬":"A4"},{"제목":"g(3)-f(2) 계산하기","힌트":"앞에서 구한 $g(3)$ 에서 $f(2)$ 를 빼면?","식":["$g(3)-f(2)=\\dfrac{39}{16}-2$","$=\\dfrac{39}{16}-\\dfrac{32}{16}$"],"설명":"$2=\\dfrac{32}{16}$ 로 통분하여 뺀다.","확인":"7/16","스킬":"A2"}]},"ns-b64afd6581fc":{"길":"h 가 x=1 에서 최대인 점을 이용해 좌극한만 보고, f∘g 가 왼쪽에서 이어지지 않는 점을 찾는다","단계":[{"제목":"x=1 의 양쪽 극한을 한쪽 극한으로 바꾸기","힌트":"$h(x)=-(x-1)^{2}+1+k$ 는 $x=1$ 근처에서 $1+k$ 보다 큰 값을 가질까, 작은 값을 가질까?","식":["$h(1)=1+k,\\ \\ (f\\circ g\\circ h)(1)=(f\\circ g)(1+k)$","$h(x)\\le1+k$ 이므로 $x\\to1$ 일 때 $h(x)\\to(1+k)-$","$\\lim_{x\\to1\\pm}f(g(h(x)))=\\lim_{t\\to(1+k)-}(f\\circ g)(t)$"],"설명":"$h$ 는 $x=1$ 에서 최댓값 $1+k$ 를 가지므로 $x$ 가 $1$ 의 어느 쪽에서 다가가도 $h(x)$ 는 $1+k$ 의 왼쪽에서 다가간다. 좌극한과 우극한은 항상 같다.","확인":null,"스킬":"T6"},{"제목":"x≤0 에서 (f∘g)(x) 구하기","고비":true,"힌트":"$g(x)$ 의 값이 $f$ 의 어느 구간에 들어가는지 나누어 본다. $x=-1$ 에서 $f(g(-1))$ 은?","식":["$x<-1$: $g(x)=-1,\\ f(-1)=1$ 이고 $x=-1$: $g(-1)=1,\\ f(1)=-1$","$-1<x\\le-\\dfrac12$: $g(x)=-2x-1\\in[0,\\ 1)$ 이므로 $f(g(x))=-2x-1$","$-\\dfrac12\\le x\\le0$: $g(x)=-2x-1\\in[-1,\\ 0]$ 이므로 $f(g(x))=2x+1$"],"설명":"$f$ 는 $[-1,\\ 0]$ 에서 $-u$, $[0,\\ 1)$ 에서 $u$ 이다. $x=-1$ 에서 $g$ 의 값은 닫힌 점 $1$ 이고 $f(1)$ 은 닫힌 점 $-1$ 이다.","확인":"-1","스킬":"T6"},{"제목":"x>0 에서 (f∘g)(x) 구하기","힌트":"$0<x\\le1$ 에서 $g(x)=x-1$ 은 어느 구간의 값일까? $x=1$ 에서 $f(g(1))$ 은?","식":["$0<x\\le1$: $g(x)=x-1\\in(-1,\\ 0]$ 이므로 $f(g(x))=1-x$","$x>1$: $g(x)=1,\\ f(1)=-1$","$f(g(1))=f(0)$"],"설명":"$g(x)=x-1$ 은 $-1$ 이상 $0$ 이하이므로 $f(u)=-u$ 를 쓴다. $x>1$ 에서는 $g$ 가 열린 점 $1$ 이 아니라 값 $1$ 을 갖는 상수 부분이다.","확인":"0","스킬":"T6"},{"제목":"왼쪽에서 이어지지 않는 점 찾기","힌트":"$f\\circ g$ 의 그래프에서 $t$ 의 왼쪽에서 다가갈 때의 극한과 $(f\\circ g)(t)$ 가 다른 점은 어디일까?","식":["$t=-1$: $\\lim_{t\\to-1-}(f\\circ g)(t)=1,\\ \\ (f\\circ g)(-1)=-1$","$t=1$: $\\lim_{t\\to1-}(f\\circ g)(t)=0=(f\\circ g)(1)$","$t=-\\dfrac12,\\ 0$ 을 포함한 나머지 점은 왼쪽에서 이어진다"],"설명":"한쪽 극한만 보므로 $t=1$ 오른쪽의 값 $-1$ 은 따지지 않는다. 왼쪽에서 다가간 극한이 함숫값과 다른 점은 $t=-1$ 하나이다.","확인":null,"스킬":"D12"},{"제목":"k 의 값과 개수 구하기","힌트":"$1+k$ 가 어떤 값일 때 불연속이 되고, 그런 $k$ 는 몇 개일까?","식":["$1+k=-1\\ \\Rightarrow\\ k=-2$","조건을 만족시키는 $k$ 는 $-2$ 하나"],"설명":"$1+k$ 가 $-1$ 이 아니면 좌극한과 함숫값이 같아 연속이다. 따라서 불연속이 되는 $k$ 는 $-2$ 뿐이다.","확인":"1","스킬":"C2"}]},"ns-cd0fe193386d":{"길":"(0, -1) 을 축으로 직선을 돌리며 접할 때와 꺾이는 점을 지날 때를 경계로 g(t) 를 정한다","단계":[{"제목":"포물선 부분에 접하는 기울기 구하기","힌트":"직선 $y=mx-1$ 과 $y=x^{2}-4x+3$ 의 판별식이 $0$ 이 되는 $m$ 중 음수는?","식":["$x^{2}-4x+3=mx-1\\ \\Rightarrow\\ x^{2}-(m+4)x+4=0$","$D=(m+4)^{2}-16=m^{2}+8m=0$","$m=0,\\ -8$ 이고 접점의 $x$ 좌표는 $2,\\ -2$"],"설명":"직선 $l$ 은 $(0,\\ -1)$ 을 지나므로 $y=mx-1$ 로 둔다. $x\\le4$ 인 부분의 식은 $y=(x-2)^{2}-1=x^{2}-4x+3$ 이다.","확인":"-8","스킬":"G2"},{"제목":"꺾이는 점을 지나는 직선과 교점 구하기","힌트":"$(0,\\ -1)$ 과 $(4,\\ 3)$ 을 지나는 직선의 기울기는?","식":["$m=\\dfrac{3-(-1)}{4-0},\\ \\ y=x-1$","$x^{2}-4x+3=x-1\\ \\Rightarrow\\ x=1,\\ 4$","교점 $(1,\\ 0),\\ (4,\\ 3)$ 이므로 $t=1,\\ 4$"],"설명":"$t=4$ 일 때 직선은 꺾이는 점 $(4,\\ 3)$ 을 지난다. $t=1$ 일 때는 포물선 위의 다른 교점 $(1,\\ 0)$ 에서 같은 직선이 된다.","확인":"1","스킬":"G3"},{"제목":"수평 직선과 오른쪽 가지의 교점 구하기","힌트":"$m=0$ 인 직선 $y=-1$ 은 꼭짓점 $(2,\\ -1)$ 에서 접한다. $y=-x+7$ 과는 $x$ 좌표 어디에서 만날까?","식":["$-x+7=-1$","$x=8$, 교점 $(8,\\ -1)$","$t=2$ 일 때와 $t=8$ 일 때 직선이 모두 $y=-1$"],"설명":"$m=0$ 이면 직선은 꼭짓점에서 접하면서 $x>4$ 인 가지와도 한 점 더 만난다. $f(2)=f(8)=-1$ 이므로 $t=2,\\ 8$ 이 같은 직선을 준다.","확인":"8","스킬":"G3"},{"제목":"t 에 따른 교점 수 g(t) 정하기","고비":true,"힌트":"접하는 때와 꺾이는 점을 지나는 때를 경계로 $t$ 의 범위를 나누어 센다. $t=1$ 일 때 $g(1)$ 은?","식":["$t<-2$: $2,\\ \\ t=-2$: $1,\\ \\ -2<t<0$: $2,\\ \\ 0\\le t<1$: $1$","$t=1$: $2,\\ \\ 1<t<2$: $3,\\ \\ t=2$: $2,\\ \\ 2<t<4$: $3,\\ \\ t=4$: $2$","$4<t<8$: $3,\\ \\ t=8$: $2,\\ \\ t>8$: $1$"],"설명":"기울기가 $-8,\\ 0,\\ 1$ 이 되는 $t$ 와 $t=0$ 을 경계로 교점 수가 달라진다. $2<t<4$ 에서는 직선이 포물선과 $2$ 점, $x>4$ 의 가지와 $1$ 점에서 만난다. $t=1$ 에서는 $(1,\\ 0),\\ (4,\\ 3)$ 두 점이다.","확인":"2","스킬":"G3"},{"제목":"좌극한과 우극한이 다른 a 의 개수 세기","힌트":"$g(t)$ 의 값이 바뀌는 점 중 좌극한과 우극한이 서로 다른 $a$ 는 몇 개일까?","식":["$a=0$: 좌극한 $2$, 우극한 $1$","$a=1$: 좌극한 $1$, 우극한 $3$ 이고 $a=8$: 좌극한 $3$, 우극한 $1$","$a=-2,\\ 2,\\ 4$ 는 양쪽 극한이 같으므로 제외"],"설명":"$t=-2,\\ 2,\\ 4$ 에서는 $g$ 의 값만 하나 작을 뿐 양쪽 극한이 같다. 조건은 극한의 비교이므로 함숫값은 쓰지 않는다.","확인":"3","스킬":"D12"},{"제목":"n 과 a 의 합으로 값 구하기","힌트":"$a$ 의 합과 $n$ 을 곱하면?","식":["$n=3,\\ \\ a_{1}+a_{2}+a_{3}=0+1+8=9$","$n(a_{1}+a_{2}+\\cdots+a_{n})=3\\times9$"],"설명":"구한 세 값 $0,\\ 1,\\ 8$ 을 더한 뒤 $n=3$ 을 곱한다.","확인":"27","스킬":"A2"}]},"ns-d21bb934d7c9":{"길":"보기마다 x=1 근처에서 안쪽 함수가 다가가는 방향을 그래프에서 읽어 바깥 함수의 극한을 본다","단계":[{"제목":"ㄱ: 우극한의 곱 구하기","힌트":"$x\\to1+$ 일 때 $f(x)$ 가 가까워지는 값은? $g(x)$ 는 어떤 값을 가질까?","식":["$\\lim_{x\\to1+}f(x)=-1$ ($x\\ge1$ 에서 $f(x)=x-2$)","$\\lim_{x\\to1+}g(x)=1$ ($x\\ge1$ 에서 $g(x)=1$)","$\\lim_{x\\to1+}f(x)g(x)=(-1)\\times1$ (ㄱ 참)"],"설명":"$f$ 는 $x=1$ 의 오른쪽에서 닫힌 점 $(1,\\ -1)$ 에서 출발하는 직선이고, $g$ 는 $x\\ge1$ 에서 상수 $1$ 이다. 곱의 극한은 극한의 곱이다.","확인":"-1","스킬":"C3"},{"제목":"ㄴ: g(f(x)) 의 좌우 극한 비교","힌트":"$x\\to1+$ 일 때 $f(x)$ 는 $-1$ 의 오른쪽에서 다가간다. 이때 $g$ 의 값이 가까워지는 곳은?","식":["$x\\to1-$: $f(x)\\to1-$ 이므로 $g(f(x))\\to g(1-)=-1$","$x\\to1+$: $f(x)\\to-1+$ 이므로 $g(f(x))\\to g(-1+)=1$","좌극한 $\\ne$ 우극한이므로 $\\lim_{x\\to1}g(f(x))$ 는 존재하지 않는다 (ㄴ 거짓)"],"설명":"안쪽 $f(x)$ 가 다가가는 방향에 따라 바깥 $g$ 의 극한을 읽는다. $x<1$ 에서 $g(x)=-x$ 이므로 $g(1-)=-1,\\ g(-1+)=1$ 이다.","확인":"1","스킬":"T6"},{"제목":"ㄷ: f(g(x)) 의 x=1 에서의 연속 확인","고비":true,"힌트":"$x\\to1-$ 일 때 $g(x)$ 는 $-1$ 의 오른쪽에서 다가간다. 이때 $f(g(x))$ 의 극한은?","식":["$x\\to1-$: $g(x)\\to-1+$ 이므로 $f(g(x))\\to f(-1+)=-1$","$x\\ge1$ 에서 $g(x)=1$ 이므로 $f(g(x))=f(1)=-1$","좌극한 $=$ 우극한 $=f(g(1))$ 이므로 연속 (ㄷ 참)"],"설명":"$x<1$ 에서 $g(x)=-x$ 는 $-1$ 보다 큰 값이고 $f(x)=x$ 이므로 극한은 $-1$ 이다. 오른쪽은 $g$ 가 상수 $1$ 이라서 함숫값 $f(1)$ 과 같다.","확인":"-1","스킬":"T6"},{"제목":"옳은 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 옳은 것은 어느 것일까?","식":["ㄱ 참, ㄴ 거짓, ㄷ 참","옳은 것은 ㄱ, ㄷ"],"설명":"ㄴ 만 좌극한과 우극한이 달라 거짓이다. 옳은 것은 ㄱ 과 ㄷ 이다.","확인":null,"스킬":"C3"}]},"ns-dc884172f467":{"길":"g 가 x=2 에서 최대이므로 f 의 좌극한만 보고, f 가 왼쪽에서 이어지지 않는 점을 찾는다","단계":[{"제목":"x=2 의 양쪽 극한을 한쪽 극한으로 바꾸기","힌트":"$g(x)=-(x-2)^{2}+4+k$ 는 $x=2$ 근처에서 $g(2)$ 보다 큰 값을 가질까, 작은 값을 가질까?","식":["$g(2)=k+4,\\ \\ (f\\circ g)(2)=f(k+4)$","$g(x)\\le k+4$ 이므로 $x\\to2$ 일 때 $g(x)\\to(k+4)-$","$\\lim_{x\\to2}f(g(x))=\\lim_{t\\to(k+4)-}f(t)$"],"설명":"$g$ 는 $x=2$ 에서 최댓값 $k+4$ 를 가지므로 $x$ 가 $2$ 의 어느 쪽에서 다가가도 $g(x)$ 는 $k+4$ 의 왼쪽에서 다가간다. 불연속이 되려면 $f$ 의 좌극한이 $f(k+4)$ 와 달라야 한다.","확인":null,"스킬":"T6"},{"제목":"f 가 왼쪽에서 이어지지 않는 점 찾기","고비":true,"힌트":"$x=1,\\ 2,\\ 3$ 에서 $f$ 의 좌극한과 함숫값을 비교한다. $x=2$ 에서의 좌극한은?","식":["$x=1$: 좌극한 $1,\\ f(1)=3$ 이므로 다르다","$x=2$: 좌극한 $2,\\ f(2)=1$ 이므로 다르다","$x=3$: 좌극한 $1,\\ f(3)=1$ 이므로 같다"],"설명":"$x=3$ 은 우극한이 $2$ 로 달라 불연속이지만 좌극한은 함숫값과 같으므로 해당하지 않는다. $x=2$ 에서는 열린 점 $(2,\\ 2)$ 와 닫힌 점 $(2,\\ 1)$ 을 구별한다.","확인":"2","스킬":"D12"},{"제목":"k 의 값 구하기","힌트":"$k+4$ 가 $1$ 또는 $2$ 일 때 $k$ 의 두 값 중 작은 것은?","식":["$k+4=1\\ \\Rightarrow\\ k=-3$","$k+4=2\\ \\Rightarrow\\ k=-2$"],"설명":"$f$ 가 왼쪽에서 이어지지 않는 점이 $x=1,\\ 2$ 이므로 $k+4$ 가 이 값일 때만 불연속이다.","확인":"-3","스킬":"C2"},{"제목":"k 값들의 곱 구하기","힌트":"두 $k$ 값을 곱하면?","식":["$(-3)\\times(-2)=6$"],"설명":"구한 두 값 $-3,\\ -2$ 를 곱한다.","확인":"6","스킬":"A2"}]},"ns-dc94c633dca1":{"길":"f(x-a) 는 x=a, f(x)+b 는 x=0 에서만 끊기니 a=0 인 경우와 아닌 경우를 나누어 두 점의 연속 조건을 쓴다","단계":[{"제목":"a=0 일 때 b 구하기","힌트":"$a=0$ 이면 $g(x)=f(x)\\{f(x)+b\\}$ 이다. $x=0$ 에서 좌극한과 함숫값이 같으려면 $b$ 는?","식":["$g(0)=0\\times(0+b)=0$","$\\lim_{x\\to0-}g(x)=1\\times(1+b),\\ \\ \\lim_{x\\to0+}g(x)=0\\times(0+b)=0$","$1+b=0\\ \\Rightarrow\\ b=-1$"],"설명":"$f$ 는 $x=0$ 에서만 불연속이므로 $a=0$ 일 때는 $x=0$ 에서의 연속만 조사하면 된다. 순서쌍 $(0,\\ -1)$ 이 하나 나온다.","확인":"-1","스킬":"C2"},{"제목":"a≠0 일 때 x=0 에서의 연속 조건","힌트":"$a\\ne0$ 이면 $x=0$ 에서 $f(x-a)$ 는 연속이고 $f(x)+b$ 는 끊긴다. 연속이려면 $f(-a)$ 는 얼마여야 할까?","식":["$g(0-)=f(-a)(1+b),\\ \\ g(0)=g(0+)=f(-a)\\,b$","$f(-a)=0$","$-a=-1$ 또는 $-a=2\\ \\Rightarrow\\ a=1$ 또는 $a=-2$"],"설명":"좌극한과 함숫값의 차가 $f(-a)$ 이므로 이것이 $0$ 이어야 한다. $f(x)=0$ 의 해는 $x=-1,\\ 0,\\ 2$ 이고 $a\\ne0$ 이므로 $x=0$ 은 뺀다.","확인":null,"스킬":"C2"},{"제목":"a≠0 일 때 x=a 에서의 연속 조건과 b","고비":true,"힌트":"$x=a$ 에서는 $f(x-a)$ 가 끊기고 $f(x)+b$ 는 연속이다. $f(a)+b$ 가 $0$ 이 되게 하는 $b$ 의 값은?","식":["$g(a-)=1\\times\\{f(a)+b\\},\\ \\ g(a)=g(a+)=0$","$f(a)+b=0\\ \\Rightarrow\\ b=-f(a)$","$f(1)=-1,\\ f(-2)=-1$ 이므로 $(a,\\ b)=(1,\\ 1),\\ (-2,\\ 1)$"],"설명":"$f(x-a)$ 는 $x=a$ 에서 좌극한 $1$, 우극한과 함숫값 $0$ 이다. 곱이 이어지려면 같은 점에서 $f(x)+b$ 가 $0$ 이어야 한다.","확인":"1","스킬":"C2"},{"제목":"순서쌍의 개수 세기","힌트":"세 경우에서 나온 순서쌍을 모두 모으면 몇 개일까?","식":["$(0,\\ -1),\\ (1,\\ 1),\\ (-2,\\ 1)$","순서쌍은 $3$ 개"],"설명":"$a=0$ 에서 하나, $a\\ne0$ 에서 두 개가 나왔다.","확인":"3","스킬":"C2"}]},"ns-e33c051d4ff2":{"길":"|f| 의 그래프로 g(t) 를 구해 불연속인 t 를 찾고, 그 두 점이 h 의 근이 되게 한다","단계":[{"제목":"y=|f(x)| 의 식 구하기","힌트":"$f(x)$ 가 음수인 부분의 부호를 바꾸면 $x\\le-2$ 와 $x>0$ 에서 $|f(x)|$ 는 어떻게 될까?","식":["$x\\le-2$: $|f(x)|=-x-2$","$-2\\le x\\le0$: $|f(x)|=x+2$","$x>0$: $|f(x)|=\\dfrac12x$ ($(0,\\ 0)$ 은 열린 점)"],"설명":"$x+2$ 는 $x<-2$ 에서, $-\\dfrac12x$ 는 $x>0$ 에서 음수이므로 이 부분만 부호를 바꾼다. $|f(0)|=2$ 이다.","확인":null,"스킬":"G5"},{"제목":"t 에 따른 교점 수 g(t) 정하기","고비":true,"힌트":"직선 $y=t$ 를 위아래로 움직이며 센다. $0<t\\le2$ 일 때 교점은 몇 개일까?","식":["$t<0$: $0$ 개, $t=0$: $x=-2$ 한 점뿐이라 $1$ 개","$0<t\\le2$: $x=-t-2,\\ t-2,\\ 2t$ 의 $3$ 개","$t>2$: $x=-t-2,\\ 2t$ 의 $2$ 개"],"설명":"$t=0$ 일 때 $x=0$ 은 열린 점이라 제외한다. $t>2$ 이면 가운데 가지 $y=x+2\\ (x\\le0)$ 가 $y=t$ 에 닿지 못해 한 개가 줄어든다.","확인":"3","스킬":"G1"},{"제목":"불연속인 t 와 h(t) 구하기","힌트":"$g(t)h(t)$ 가 연속이려면 $g$ 가 끊기는 점에서 $h$ 는 어떤 값이어야 할까? 그때 $h(1)$ 은?","식":["$g$ 는 $t=0,\\ 2$ 에서 불연속","$h(0)=h(2)=0$","$h(t)=t(t-2),\\ \\ h(1)=-1$"],"설명":"$t=0$ 에서 $g$ 의 좌극한 $0$, 함숫값 $1$, 우극한 $3$ 이므로 $h(0)=0$ 이어야 한다. $t=2$ 에서는 좌극한 $3$ 과 우극한 $2$ 가 다르므로 $h(2)=0$ 이다. 최고차항의 계수가 $1$ 이므로 $h$ 가 정해진다.","확인":"-1","스킬":"A4"},{"제목":"g(0)+h(1) 계산하기","힌트":"$g(0)$ 과 $h(1)$ 을 더하면?","식":["$g(0)=1,\\ \\ h(1)=-1$","$g(0)+h(1)=0$"],"설명":"$t=0$ 일 때 교점은 $x=-2$ 하나뿐이므로 $g(0)=1$ 이다.","확인":"0","스킬":"A2"}]},"ns-fbbab7837b8e":{"길":"분모 f(x-a+3) 의 좌우 극한이 3 에서 달라지는 것을 이용해 f(a)=0 인 a 를 찾고 a=3 은 따로 본다","단계":[{"제목":"f 의 x=3 에서의 좌우 극한 구하기","힌트":"$x\\to3-$ 일 때와 $x\\to3+$ 일 때 $f(x)$ 가 가까워지는 값을 각각 구하면? 우극한은?","식":["$f(x)=(x-1)(x-2)(x-4)\\ (x\\le3),\\ \\ f(x)=(x+2)(x+1)(x-4)\\ (x>3)$","$\\lim_{x\\to3-}f(x)=2\\cdot1\\cdot(-1)=-2$","$\\lim_{x\\to3+}f(x)=5\\cdot4\\cdot(-1)=-20$"],"설명":"$f$ 는 $x=3$ 에서 불연속이고 $f(3)=-2$ 이다. 분모 $f(x-a+3)$ 은 $x\\to a$ 일 때 $f(3)$ 쪽으로 가므로 이 두 극한이 쓰인다.","확인":"-20","스킬":"A4"},{"제목":"a≠3 일 때 좌우 극한을 세워 f(a)=0 얻기","고비":true,"힌트":"$x\\to a-$ 이면 $x-a+3\\to3-$ 이다. 좌극한과 우극한이 같으려면 $f(a)$ 는?","식":["$\\lim_{x\\to a-}g(x)=\\dfrac{f(a)}{-2},\\ \\ \\lim_{x\\to a+}g(x)=\\dfrac{f(a)}{-20}$","$g(a)=\\dfrac{f(a)}{f(3)}=\\dfrac{f(a)}{-2}$","$\\dfrac{f(a)}{-2}=\\dfrac{f(a)}{-20}\\ \\Rightarrow\\ f(a)=0$"],"설명":"분자 $f(x)+(x-a)^{2}$ 은 $a\\ne3$ 이면 $x=a$ 에서 연속이므로 $f(a)$ 로 간다. 분모의 좌우 극한이 $-2,\\ -20$ 으로 달라서 분자가 $0$ 이어야 두 극한이 같다.","확인":"0","스킬":"D12"},{"제목":"f(a)=0 인 a 구하기","힌트":"$a<3$ 과 $a>3$ 으로 나누어 $f(a)=0$ 을 푼다. $3$ 보다 큰 근은?","식":["$a<3$: $(a-1)(a-2)(a-4)=0\\ \\Rightarrow\\ a=1,\\ 2$","$a>3$: $(a+2)(a+1)(a-4)=0\\ \\Rightarrow\\ a=4$","조건에 맞는 $a=1,\\ 2,\\ 4$"],"설명":"각 식의 근 중 범위에 맞는 것만 남긴다. $a<3$ 인 식의 근 $4$ 와 $a>3$ 인 식의 근 $-2,\\ -1$ 은 제외한다.","확인":"4","스킬":"C2"},{"제목":"a=3 일 때 연속 확인하기","힌트":"$a=3$ 이면 분모는 $f(x)$ 이다. $g(x)$ 를 $1+\\frac{(x-3)^{2}}{f(x)}$ 로 쓰면 $x\\to3$ 의 극한은?","식":["$g(x)=\\dfrac{f(x)+(x-3)^{2}}{f(x)}=1+\\dfrac{(x-3)^{2}}{f(x)}$","$\\lim_{x\\to3-}g(x)=1+\\dfrac{0}{-2}=1,\\ \\ \\lim_{x\\to3+}g(x)=1+\\dfrac{0}{-20}=1$","$g(3)=1$ 이므로 $a=3$ 도 연속"],"설명":"이때는 분자 $(x-3)^{2}$ 이 $0$ 으로 가고 분모가 $-2$ 또는 $-20$ 으로 가서 좌우 극한이 모두 $1$ 이다.","확인":"1","스킬":"D12"},{"제목":"모든 a 의 합 구하기","힌트":"연속이 되는 $a$ 를 모두 더하면?","식":["$a=1,\\ 2,\\ 3,\\ 4$","$1+2+3+4=10$"],"설명":"$a\\ne3$ 에서 세 값, $a=3$ 에서 한 값이 나왔다.","확인":"10","스킬":"A2"}]},"ns-00f93a8600d1":{"길":"(나)를 x 로 나눠 f'(0) 이 만족하는 방정식을 얻고, 두 기울기가 한 이차방정식의 두 근임을 쓴다","단계":[{"제목":"(나)를 f'(0) 에 대한 방정식으로 바꾸기","고비":true,"힌트":"분자·분모를 $x$ 로 나누고 $\\frac{f_i(x)}{x}$ 의 극한을 미분계수로 바꾸면, $f_1'(0)=a$ 가 만족하는 식은?","식":["$f_i'(0)=\\lim_{x\\to0}\\dfrac{f_i(x)-f_i(0)}{x-0}=\\lim_{x\\to0}\\dfrac{f_i(x)}{x}$","$\\lim_{x\\to0}\\dfrac{\\frac{f_i(x)}{x}+2k}{\\frac{f_i(x)}{x}+k}=\\dfrac{f_i'(0)+2k}{f_i'(0)+k}$","$a=f_1'(0),\\ b=f_2'(0)$ 이면 $a=\\dfrac{a+2k}{a+k},\\ \\ b=\\dfrac{b+2k}{b+k}$"],"설명":"(가) 에서 $f_i(0)=0$ 이므로 $\\dfrac{f_i(x)}{x}$ 의 극한이 바로 $f_i'(0)$ 이다. $f_1,\\ f_2$ 모두 같은 꼴의 식이 나온다.","확인":null,"스킬":"D3"},{"제목":"a, b 가 한 이차방정식의 두 근임을 보이기","힌트":"$a=\\frac{a+2k}{a+k}$ 를 정리한 이차방정식에서 $b$ 도 같은 식을 만족한다. 두 근이 서로 다른 값인 까닭은?","식":["$a(a+k)=a+2k\\ \\Rightarrow\\ a^{2}+(k-1)a-2k=0$","$b$ 도 같은 식: $b^{2}+(k-1)b-2k=0$","(다) 에서 $ab=-1$ 이므로 $a\\ne b$, 따라서 $a,\\ b$ 는 $x^{2}+(k-1)x-2k=0$ 의 서로 다른 두 근"],"설명":"두 접선이 수직이면 기울기의 곱이 $-1$ 이다. $a=b$ 이면 $a^{2}=-1$ 이 되어 불가능하므로 두 값은 같은 방정식의 서로 다른 두 근이다.","확인":null,"스킬":"A2"},{"제목":"근과 계수의 관계로 k 구하기","힌트":"두 근의 곱이 $-1$ 이 되도록 $k$ 를 정하면?","식":["$ab=-2k$","$-2k=-1$","$k=\\dfrac12$"],"설명":"이때 $x^{2}-\\dfrac12x-1=0$ 의 판별식이 $\\dfrac14+4>0$ 이어서 서로 다른 두 실근이 있다.","확인":"1/2","스킬":"A2"}]},"ns-00fe9ec67c7c":{"길":"나머지를 삼차식으로 놓고 f(±2) 와 f'(±2) 의 네 조건을 R 에 옮겨 계수를 정한다","단계":[{"제목":"f(2), f(-2) 의 값 구하기","힌트":"$f(x)=(x^{2}-4)Q(x)+x+3$ 에 $x=2$ 를 넣으면 $f(2)$ 는?","식":["$f(x)=(x^{2}-4)Q(x)+x+3$","$f(2)=5,\\ \\ f(-2)=1$"],"설명":"$x^{2}-4=(x-2)(x+2)$ 이므로 $x=\\pm2$ 에서 $(x^{2}-4)Q(x)$ 가 $0$ 이다.","확인":"5","스킬":"A4"},{"제목":"나머지를 삼차식으로 놓고 네 조건 옮기기","고비":true,"힌트":"$f(x)=(x^{2}-4)^{2}P(x)+R(x)$ 를 미분하면 $x=\\pm2$ 에서 $P$ 가 들어간 항은 어떻게 될까?","식":["$f(x)=(x^{2}-4)^{2}P(x)+R(x),\\ \\ R(x)=ax^{3}+bx^{2}+cx+d$","$f'(x)=2(x^{2}-4)\\cdot2x\\,P(x)+(x^{2}-4)^{2}P'(x)+R'(x)$","$x=\\pm2$ 에서 $P$ 가 든 항은 $0$ 이어서 $R(2)=5,\\ R(-2)=1,\\ R'(2)=R'(-2)=-15$"],"설명":"$(x^{2}-4)^{2}$ 으로 나눈 나머지는 사차식 미만이므로 삼차 이하로 둔다. 미분한 식에서도 $(x^{2}-4)$ 인수가 남는 항은 $x=\\pm2$ 에서 $0$ 이다.","확인":null,"스킬":"A4"},{"제목":"미분 조건으로 b 구하기","힌트":"$R'(x)=3ax^{2}+2bx+c$ 이다. $R'(2)-R'(-2)$ 를 계산하면 $b$ 는?","식":["$R'(2)=12a+4b+c,\\ \\ R'(-2)=12a-4b+c$","$R'(2)-R'(-2)=8b=0$","$b=0,\\ \\ 12a+c=-15$"],"설명":"두 식의 차에서 $a,\\ c$ 항이 사라지고 $b$ 만 남는다. 두 값이 모두 $-15$ 이므로 차가 $0$ 이다.","확인":"0","스킬":"A3"},{"제목":"함숫값 조건으로 d 구하기","힌트":"$R(2)+R(-2)$ 를 계산하면 $d$ 는? (단, $b=0$)","식":["$R(2)+R(-2)=8b+2d=6$","$d=3$","$R(2)-R(-2)=16a+4c=4\\ \\Rightarrow\\ 4a+c=1$"],"설명":"$R(2)=8a+4b+2c+d=5$ 와 $R(-2)=-8a+4b-2c+d=1$ 을 더하면 $a,\\ c$ 항이 사라지고, 빼면 $b,\\ d$ 항이 사라진다.","확인":"3","스킬":"A3"},{"제목":"a, c 를 구해 나머지 쓰기","힌트":"$12a+c=-15$ 와 $4a+c=1$ 을 연립하면 $a,\\ c$ 는?","식":["$(12a+c)-(4a+c)=8a=-16\\ \\Rightarrow\\ a=-2$","$c=1-4a=9$","$R(x)=-2x^{3}+9x+3$"],"설명":"$b=0,\\ d=3$ 이므로 나머지에는 $x^{2}$ 항이 없다.","확인":null,"스킬":"A3"}]},"ns-03a6b8a14b77":{"길":"열린구간 (0, 4) 안의 x=1, 2, 3 에서 극한·연속·미분 가능을 차례로 따져 a, b, c 를 센다","단계":[{"제목":"극한값이 존재하지 않는 점의 개수 a 구하기","힌트":"$x=1,\\ 2,\\ 3$ 에서 좌극한과 우극한이 서로 다른 점은 몇 개일까?","식":["$x=1$: 좌극한 $1,\\ $ 우극한 $2$ 이므로 극한이 없다","$x=2$: 좌극한 $2,\\ $ 우극한 $2$ 이므로 극한이 있다","$x=3$: 좌극한 $=$ 우극한 $=3$ 이므로 극한이 있다"],"설명":"극한의 존재는 함숫값과 무관하게 좌우 극한이 같은지로 정한다. $x=2$ 의 닫힌 점 $(2,\\ 3)$ 은 극한에 영향을 주지 않는다.","확인":"1","스킬":"D12"},{"제목":"불연속인 점의 개수 b 구하기","힌트":"극한이 없는 점과 극한이 있어도 함숫값과 다른 점을 합치면 몇 개일까?","식":["$x=1$: 극한이 없어 불연속","$x=2$: 극한 $2,\\ f(2)=3$ 이므로 불연속","$x=3$: 극한 $3=f(3)$ 이므로 연속"],"설명":"연속이려면 극한이 존재하고 그 값이 함숫값과 같아야 한다.","확인":"2","스킬":"D12"},{"제목":"미분 불가능한 점의 개수 c 구하기","고비":true,"힌트":"불연속인 점 외에 연속이지만 뾰족하게 꺾인 점이 더 있을까? 미분 불가능한 점은 모두 몇 개일까?","식":["$x=1,\\ 2$: 불연속이므로 미분 불가능","$x=3$: 연속이지만 왼쪽 기울기 $1$, 오른쪽 기울기 $-1$ 로 달라 미분 불가능","미분 불가능한 점은 $x=1,\\ 2,\\ 3$"],"설명":"미분가능하면 연속이므로 불연속인 점은 모두 포함된다. 연속인 점 중에서는 좌우 기울기가 다른 꺾인 점을 더한다.","확인":"3","스킬":"D1"},{"제목":"a+b+c 계산하기","힌트":"세 개수를 모두 더하면?","식":["$a=1,\\ b=2,\\ c=3$","$a+b+c=6$"],"설명":"구한 세 값을 더한다.","확인":"6","스킬":"C2"}]},"ns-03e2e26b0474":{"길":"(다)를 x 로 나눠 f'(0) 이 만족하는 식을 얻고, 두 기울기가 한 이차방정식의 두 근임을 이용한다","단계":[{"제목":"(다)를 f'(0) 에 대한 방정식으로 바꾸기","고비":true,"힌트":"분자·분모를 $x$ 로 나누고 $\\frac{f(x)}{x}$ 의 극한을 미분계수로 바꾸면, $f'(0)=\\alpha$ 가 만족하는 식은?","식":["$\\dfrac{f(x)}{x}=\\dfrac{f(x)-f(0)}{x-0}\\to f'(0)$","$f'(0)=\\lim_{x\\to0}\\dfrac{a+\\frac{f(x)}{x}}{2+\\frac{f(x)}{x}}=\\dfrac{a+f'(0)}{2+f'(0)}$","$\\alpha=f'(0),\\ \\beta=g'(0)$ 이면 $\\alpha=\\dfrac{a+\\alpha}{2+\\alpha},\\ \\ \\beta=\\dfrac{a+\\beta}{2+\\beta}$"],"설명":"(가) 에서 $f(0)=0$ 이므로 $\\dfrac{f(x)}{x}$ 의 극한이 $f'(0)$ 이다. $g$ 도 같은 꼴의 식이 나온다.","확인":null,"스킬":"D3"},{"제목":"α, β 가 한 이차방정식의 두 근임을 보이기","힌트":"$x=\\frac{a+x}{2+x}$ 를 정리한 이차방정식에서 두 근의 합은?","식":["$x(2+x)=a+x\\ \\Rightarrow\\ x^{2}+x-a=0$","$\\alpha\\beta=-1$ 이므로 $\\alpha\\ne\\beta$, 따라서 $\\alpha,\\ \\beta$ 는 이 방정식의 서로 다른 두 근","$\\alpha+\\beta=-1$"],"설명":"수직인 두 접선의 기울기의 곱이 $-1$ 이므로 $\\alpha=\\beta$ 이면 $\\alpha^{2}=-1$ 이 되어 불가능하다.","확인":"-1","스킬":"A2"},{"제목":"두 근의 곱으로 a 구하기","힌트":"두 근의 곱이 $-1$ 이 되도록 $a$ 를 정하면?","식":["$\\alpha\\beta=-a$","$\\alpha\\beta=-1$ 이므로 $-a=-1$","$a=1$"],"설명":"$a=1$ 일 때 $x^{2}+x-1=0$ 의 판별식이 $5$ 로 양수여서 서로 다른 두 실근이 있다.","확인":"1","스킬":"A2"}]},"ns-06ae26f27446":{"길":"분자에 f(1) 을 빼고 더해 f'(1) 의 몇 배끼리의 차로 바꾼다","단계":[{"제목":"분자를 f(1) 기준의 두 차로 가르기","힌트":"분자에 $f(1)$ 을 빼고 더하면 두 개의 차로 어떻게 나눌 수 있을까?","식":["$f(1+4h+h^{2})-f(1+3h)=\\{f(1+4h+h^{2})-f(1)\\}-\\{f(1+3h)-f(1)\\}$"],"설명":"각 조각이 $f(1+\\text{증분})-f(1)$ 꼴이 되어 미분계수의 정의를 쓸 수 있다.","확인":null,"스킬":"D3"},{"제목":"각 조각을 미분계수의 배수로 바꾸기","고비":true,"힌트":"증분 $4h+h^{2}$ 과 $3h$ 로 각각 나누고 곱하면, 합친 식에서 $f'(1)$ 의 계수는?","식":["$\\dfrac{f(1+4h+h^{2})-f(1)}{4h+h^{2}}\\times\\dfrac{4h+h^{2}}{h}\\to f'(1)\\times4$","$\\dfrac{f(1+3h)-f(1)}{3h}\\times3\\to f'(1)\\times3$","$4f'(1)-3f'(1)=f'(1)$"],"설명":"$h\\to0$ 이면 $4h+h^{2}\\to0,\\ 3h\\to0$ 이므로 둘 다 미분계수의 정의 꼴이다. $\\dfrac{4h+h^{2}}{h}=4+h\\to4$ 이다.","확인":"1","스킬":"D3"},{"제목":"f'(1) 의 값 구하기","힌트":"$f(x)=\\int(3x-1)\\,dx$ 이면 $f'(x)$ 는? 그때 $f'(1)$ 은?","식":["$f'(x)=3x-1$","$f'(1)=3\\times1-1=2$"],"설명":"부정적분을 미분하면 피적분함수가 된다.","확인":"2","스킬":"D3"}]},"ns-07b23a287a96":{"길":"f 가 꺾이는 점마다 g 가 0 이어야 곱이 미분가능하다는 것으로 g 의 영점을 고른다","단계":[{"제목":"f 가 미분 불가능한 점 찾기","힌트":"$|x+2|,\\ |x-2|$ 가 꺾이는 점과 $x=0$ 의 좌우 기울기를 살피면 $f$ 가 미분 불가능한 점은 몇 개일까?","식":["$x<0$: $f(x)=|x+2|$ 는 $x=-2$ 에서 꺾인다","$x\\ge0$: $f(x)=|x-2|$ 는 $x=2$ 에서 꺾인다","$x=0$: $f(0^{-})=f(0)=2$ 로 이어지고 기울기가 $1$ 에서 $-1$ 로 바뀌어 꺾인다"],"설명":"$x=-2,\\ 0,\\ 2$ 가 꺾인 점이다. 이 밖의 점에서는 $f$ 가 일차식이라 미분가능하다.","확인":"3","스킬":"D1"},{"제목":"곱이 미분가능할 조건 세우기","고비":true,"힌트":"꺾인 점 $c$ 에서 $fg$ 가 미분가능하려면 $g(c)$ 는 얼마여야 할까? 미분 불가능한 점이 $1$ 개이면 $g=0$ 인 꺾인 점은 몇 개일까?","식":["$c$ 에서 $f$ 의 좌우 기울기를 $s_1,\\ s_2$ 라 하면 $(fg)'$ 의 좌우 값은 $s_1g(c)+f(c)g'(c),\\ \\ s_2g(c)+f(c)g'(c)$","$s_1\\ne s_2$ 이므로 미분가능하려면 $g(c)=0$","세 꺾인 점 중 $g(c)\\ne0$ 인 점이 정확히 $1$ 개"],"설명":"곱의 미분에서 $f$ 의 좌우 기울기 차이가 $g(c)$ 에 곱해져 남는다. 그래서 꺾인 점에서 $g(c)\\ne0$ 이면 미분 불가능이다. 이차함수 $g$ 가 세 점 모두에서 $0$ 일 수는 없다.","확인":"2","스킬":"C2"},{"제목":"세 가지 경우의 g(x) 구하기","힌트":"근이 $-2,\\ 0$ 일 때 $g(x)=ax(x+2)$ 에 $g(1)=-1$ 을 넣으면 $a$ 는?","식":["근 $-2,\\ 0$: $g(x)=ax(x+2),\\ \\ 3a=-1\\ \\Rightarrow\\ g(x)=-\\dfrac13x(x+2)$","근 $0,\\ 2$: $g(x)=ax(x-2),\\ \\ -a=-1\\ \\Rightarrow\\ g(x)=x(x-2)$","근 $-2,\\ 2$: $g(x)=a(x^{2}-4),\\ \\ -3a=-1\\ \\Rightarrow\\ g(x)=\\dfrac13(x^{2}-4)$"],"설명":"세 경우 모두 나머지 한 꺾인 점에서 $g\\ne0$ 이므로 미분 불가능한 점이 정확히 하나이다.","확인":"-1/3","스킬":"A4"},{"제목":"g(4) 의 합 구하기","힌트":"세 경우의 $g(4)$ 를 구해 더하면?","식":["$-\\dfrac13\\cdot4\\cdot6=-8,\\ \\ \\ 4\\cdot2=8,\\ \\ \\ \\dfrac13\\cdot12=4$","$-8+8+4=4$"],"설명":"세 함수의 $x=4$ 에서의 값을 더한다.","확인":"4","스킬":"A2"}]},"ns-080c6fd43c9a":{"길":"g 가 x=0 에서 이어지는 k 와 아닌 k 를 나누고, 꺾인 점마다 h 가 0 이어야 한다는 조건으로 h 를 정한다","단계":[{"제목":"g 가 x=0 에서 이어지는 k 찾기","힌트":"$x\\to0+$ 일 때 $g(x)$ 는 $9$ 로 간다. $x\\to0-$ 의 극한도 $9$ 가 되려면 $|k-3|$ 은?","식":["$\\lim_{x\\to0+}g(x)=f(0)=9$","$\\lim_{x\\to0-}g(x)=\\dfrac32|3k-9|=\\dfrac92|k-3|$","$\\dfrac92|k-3|=9\\ \\Rightarrow\\ |k-3|=2\\ \\Rightarrow\\ k=1$ 또는 $k=5$"],"설명":"$g$ 가 $x=0$ 에서 이어지는 경우와 끊기는 경우로 나누어 $h$ 를 조사한다. 이어지는 경우는 $k=1,\\ 5$ 이다.","확인":"2","스킬":"C2"},{"제목":"k=1 일 때 곱이 미분가능할 조건","고비":true,"힌트":"$k=1$ 이면 $g$ 는 $x=0$ 과 $x=3$ 에서 꺾인다. 곱이 미분가능하려면 두 점에서 $h$ 는 어떤 값이어야 할까?","식":["$x<0$: $g(x)=\\dfrac92(2-x)$ 의 기울기 $-\\dfrac92$, $x\\ge0$: $g(x)=3(3-x)$ 의 기울기 $-3$","$(gh)'(0)$ 의 좌우 값 $-\\dfrac92h(0)+9h'(0),\\ \\ -3h(0)+9h'(0)$ 이 같으려면 $h(0)=0$","$x=3$: $g(3)=0$ 이고 기울기가 $-3,\\ 3$ 이므로 $h(3)=0$"],"설명":"곱의 미분에서 $g$ 의 좌우 기울기 차이가 $h$ 의 값에 곱해져 남는다. 꺾인 점에서 $h$ 가 $0$ 이어야 좌우 미분계수가 같아진다.","확인":null,"스킬":"D1"},{"제목":"k=1 일 때 h 를 정하고 h(1) 구하기","힌트":"$h(x)=x(x-3)(x+\\alpha)$ 로 두고 $h'(3)=15$ 를 쓰면 $\\alpha$ 는? 그때 $h(1)$ 은?","식":["$h(x)=x(x-3)(x+\\alpha),\\ \\ h'(3)=3(3+\\alpha)=15\\ \\Rightarrow\\ \\alpha=2$","$h(x)=x(x-3)(x+2)$","$h(1)=1\\cdot(-2)\\cdot3$"],"설명":"$h(0)=h(3)=0$ 이고 최고차항의 계수가 $1$ 인 삼차함수이다. $x=3$ 에서의 미분계수는 나머지 두 인수 $x(x+\\alpha)$ 의 값 $3(3+\\alpha)$ 이다.","확인":"-6","스킬":"A4"},{"제목":"k=5 일 때 h 를 정하고 h(5) 구하기","힌트":"$k=5$ 이면 $x<0$ 에서 $g(x)=\\frac92|x+2|$ 로 $x=-2$ 에서도 꺾인다. $h$ 의 근은 어디일까? 그때 $h(5)$ 는?","식":["$g(-2)=0$ 이고 꺾이므로 $h(-2)=0$","$x=0$ 에서 기울기가 $\\dfrac92,\\ -3$ 으로 달라 $h(0)=0$, $x=3$ 에서 $h(3)=0$","$h(x)=x(x-3)(x+2),\\ \\ h(5)=5\\cdot2\\cdot7$"],"설명":"근 세 개 $-2,\\ 0,\\ 3$ 이 정해지므로 $k=1$ 일 때와 같은 $h$ 이다. $h'(3)=15$ 도 만족한다.","확인":"70","스킬":"A4"},{"제목":"k≠1, 5 일 때 h 가 존재하는지 확인하기","힌트":"$g$ 가 $x=0$ 에서 끊기면 $gh$ 의 연속과 미분가능에서 $h(0)$ 과 $h'(0)$ 은 어떤 값이어야 할까?","식":["$\\lim_{x\\to0-}g(x)h(x)=g(0)h(0)$ 에서 $h(0)=0$","$\\dfrac92|k-3|\\,h'(0)=9h'(0)$ 이고 $\\dfrac92|k-3|\\ne9$ 이므로 $h'(0)=0$","$h(3)=0$ 이므로 $h(x)=x^{2}(x-3),\\ \\ h'(3)=9\\ne15$ 이어서 $h$ 가 없다"],"설명":"$k=1,\\ 5$ 가 아니면 $x=0$ 에서 $g$ 의 좌극한과 함숫값이 달라 $h(0)=0$ 이 먼저 필요하다. $x=3$ 에서는 $g$ 가 $k$ 와 무관하게 꺾이므로 $h(3)=0$ 이다.","확인":null,"스킬":"C2"},{"제목":"h(k) 의 합 구하기","힌트":"가능한 $h(k)$ 를 모두 더하면?","식":["$k=1$: $h(1)=-6,\\ \\ k=5$: $h(5)=70$","$-6+70=64$"],"설명":"조건을 만족하는 $h$ 는 두 경우에서만 존재한다.","확인":"64","스킬":"A2"}]},"ns-08aba462a0c8":{"길":"연속 조건으로 f(±1) 을 얻고, (나)를 기울기가 0 이거나 부호가 바뀌는 점의 개수로 읽어 f 의 이차항 계수를 정한다","단계":[{"제목":"연속 조건으로 f(-1), f(1) 구하기","힌트":"$g$ 가 $x=-1$ 에서 연속이므로 $f(-1)$ 은 $-x^{2}-4x$ 에 $x=-1$ 을 넣은 값이다. $f(-1)$ 은?","식":["$f(-1)=-(-1)^{2}-4(-1)=3$","$f(1)=1^{2}-4\\cdot1+2=-1$"],"설명":"$f$ 의 구간 $[-1,\\ 1]$ 양 끝값이 이웃한 식의 경곗값과 같아야 $g$ 가 이어진다.","확인":"3","스킬":"D12"},{"제목":"(가)로 f 의 꼴 정하기","힌트":"$f(x)=ax^{2}+bx+c$ 로 놓고 $f(-1)=3,\\ f(1)=-1$ 을 쓰면 $b$ 는?","식":["$f$ 는 이차 이하이고 $a=\\lim_{x\\to\\infty}\\dfrac{f(x)}{x^{2}}\\in\\{-2,\\ -1,\\ 0,\\ 1,\\ 2\\}$","$a-b+c=3,\\ \\ a+b+c=-1$","$b=-2,\\ \\ a+c=1$"],"설명":"차수가 $3$ 이상이면 극한이 발산한다. $a=0$ 이면 일차함수 $f(x)=-2x+1$ 이다.","확인":"-2","스킬":"C2"},{"제목":"(나)가 뜻하는 점 찾기","고비":true,"힌트":"(좌미분계수)×(우미분계수)$\\le0$ 이 되는 점은 어떤 점일까? $x<-1$ 과 $x>1$ 에서 그런 점은 모두 몇 개일까?","식":["미분가능한 점: $g'(x)^{2}\\le0$ 이므로 $g'(x)=0$ 인 점","꺾인 점: 좌우 미분계수의 부호가 다르거나 하나가 $0$ 인 점","$x<-1$: $g'(x)=-2x-4=0\\ \\Rightarrow\\ x=-2$, $x>1$: $g'(x)=2x-4=0\\ \\Rightarrow\\ x=2$"],"설명":"(나)를 만족하는 점이 $x=-2,\\ 2$ 로 이미 정해지므로 $x=\\pm1$ 과 구간 $(-1,\\ 1)$ 에서 나머지 두 개가 나와야 한다.","확인":"2","스킬":"D1"},{"제목":"x=±1 과 구간 안에서 조건 정리하기","힌트":"$f'(x)=2ax-2$ 이다. $x=-1$ 에서 좌우 미분계수의 곱, $x=1$ 에서의 곱, $f'(x)=0$ 의 해가 $(-1,\\ 1)$ 에 들어갈 조건을 쓰면?","식":["$x=-1$: $-2\\,(-2a-2)\\le0\\ \\Rightarrow\\ a\\le-1$","$x=1$: $(2a-2)(-2)\\le0\\ \\Rightarrow\\ a\\ge1$","$-1<x<1$: $f'(x)=0$ 의 해 $x=\\dfrac1a$ 가 있으려면 $|a|>1$"],"설명":"$x=-1$ 의 왼쪽 미분계수는 $-2\\cdot(-1)-4=-2$ 이고 $x=1$ 의 오른쪽 미분계수는 $2\\cdot1-4=-2$ 이다.","확인":null,"스킬":"D1"},{"제목":"4 개가 되는 a 구하기","힌트":"$a=1$ 일 때 (나)를 만족하는 $x$ 는 몇 개일까?","식":["$a=2$: $x=-2,\\ 2,\\ 1,\\ \\dfrac12$ 의 $4$ 개","$a=-2$: $x=-2,\\ 2,\\ -1,\\ -\\dfrac12$ 의 $4$ 개","$a=\\pm1$ 은 $3$ 개, 일차함수($a=0$)는 $2$ 개로 부적합"],"설명":"$a=\\pm1$ 이면 $f'(x)=0$ 의 해가 $x=\\pm1$ 이어서 구간 안의 점이 하나 줄어든다.","확인":"3","스킬":"C2"},{"제목":"f(0) 의 최댓값과 최솟값의 합 구하기","힌트":"$f(0)=c=1-a$ 이다. 두 경우의 $f(0)$ 을 더하면?","식":["$a=2$: $f(x)=2x^{2}-2x-1,\\ \\ f(0)=-1$","$a=-2$: $f(x)=-2x^{2}-2x+3,\\ \\ f(0)=3$","$3+(-1)=2$"],"설명":"두 값 중 큰 것이 최댓값 $3$, 작은 것이 최솟값 $-1$ 이다.","확인":"2","스킬":"A2"}]},"ns-0c5670171cac":{"길":"g 는 f 의 우미분계수, h 는 f 의 좌미분계수임을 읽어 x=0 에서만 값이 갈리는 것을 따진다","단계":[{"제목":"g, h 를 우미분계수·좌미분계수로 읽기","고비":true,"힌트":"$h^{2}>0$ 이므로 $x+h^{2}$ 은 $x$ 의 오른쪽에서 다가간다. $f(x)=|x|$ 일 때 $x=0$ 에서 $g(0)$ 은?","식":["$g(x)=\\lim_{t\\to0+}\\dfrac{f(x+t)-f(x)}{t}$ 는 우미분계수: $x\\ge0$ 에서 $1$, $x<0$ 에서 $-1$","$h(x)=\\lim_{t\\to0+}\\dfrac{f(x)-f(x-t)}{t}$ 는 좌미분계수: $x>0$ 에서 $1$, $x\\le0$ 에서 $-1$","$g(0)=1,\\ h(0)=-1$"],"설명":"$h^{2}$ 은 항상 양수이므로 $t=h^{2}$ 로 두면 $t\\to0+$ 의 극한이다. $|x|$ 의 $x=0$ 에서 우미분계수는 $1$, 좌미분계수는 $-1$ 이다.","확인":"1","스킬":"D3"},{"제목":"ㄱ: g(x)h(x) 의 값 확인하기","힌트":"$x=0$ 에서 $g(0)h(0)$ 의 값은? $x\\ne0$ 에서의 값과 같을까?","식":["$x>0$: $1\\times1=1,\\ \\ x<0$: $(-1)(-1)=1$","$x=0$: $g(0)h(0)=1\\times(-1)=-1$","$x=0$ 에서 불연속이므로 미분 불가능 (ㄱ 제외)"],"설명":"미분가능하면 연속이어야 한다. $x=0$ 에서 함숫값만 $-1$ 이고 주위는 $1$ 이다.","확인":"-1","스킬":"C2"},{"제목":"ㄴ: f(x){g(x)+h(x)} 가 미분가능한지 확인하기","힌트":"$x=0$ 에서 $g(0)+h(0)$ 은? 세 구간에서 곱의 식은?","식":["$x>0$: $x\\,(1+1)=2x$","$x=0$: $0\\cdot(1-1)=0$","$x<0$: $(-x)(-1-1)=2x$"],"설명":"세 경우가 모두 $2x$ 와 같으므로 $f(g+h)=2x$ 이고 실수 전체에서 미분가능하다 (ㄴ 포함).","확인":"0","스킬":"C2"},{"제목":"ㄷ: f(x){g(x)-h(x)} 가 미분가능한지 확인하기","힌트":"$x=0$ 에서 $g(0)-h(0)$ 은? 세 구간에서 곱의 식은?","식":["$x>0$: $x\\,(1-1)=0$","$x=0$: $0\\cdot\\{1-(-1)\\}=0$","$x<0$: $(-x)\\{-1-(-1)\\}=0$"],"설명":"세 경우가 모두 $0$ 이므로 $f(g-h)=0$ 이고 실수 전체에서 미분가능하다 (ㄷ 포함).","확인":"2","스킬":"C2"},{"제목":"미분가능한 보기 모으기","힌트":"세 보기 중 실수 전체에서 미분가능한 것은?","식":["ㄱ 불가능, ㄴ 가능, ㄷ 가능","ㄴ, ㄷ"],"설명":"ㄱ 만 $x=0$ 에서 불연속이다.","확인":null,"스킬":"C3"}]},"ns-0ce239eb52f2":{"길":"x≠1 에서 f'(x) 를 식으로 풀고, f' 의 연속을 이용해 x→1 극한을 미분계수 꼴로 만든다","단계":[{"제목":"x=1 대입으로 f(1) 구하기","힌트":"(나)에 $x=1$ 을 넣으면 $(x^{3}-1)f'(x)$ 항이 사라진다. $f(1)$ 은?","식":["$2\\cdot1^{2}f(1)=(1-1)f'(1)+2\\cdot1$","$2f(1)=2$","$f(1)=1$"],"설명":"$x=1$ 이면 $x^{3}-1=0$ 이므로 $f'(1)$ 의 값과 상관없이 $f(1)$ 만 남는다.","확인":"1","스킬":"A3"},{"제목":"x≠1 에서 f'(x) 를 식으로 쓰고 극한으로 연결하기","힌트":"(나)를 $f'(x)$ 에 대해 풀고, $f'$ 이 $x=1$ 에서 연속이면 $f'(1)$ 은 이 식의 어떤 극한과 같을까?","식":["$f'(x)=\\dfrac{2x^{2}f(x)-2x}{x^{3}-1}\\ (x\\ne1)$","$f'(1)=\\lim_{x\\to1}f'(x)=\\lim_{x\\to1}\\dfrac{2x^{2}f(x)-2x}{x^{3}-1}$"],"설명":"(가) 에서 $f'$ 이 $x=1$ 에서 연속이므로 $f'(1)$ 은 $x\\to1$ 일 때 $f'(x)$ 의 극한이다.","확인":null,"스킬":"D3"},{"제목":"분자를 f(x)-1 꼴로 고쳐 미분계수로 바꾸기","고비":true,"힌트":"$f(1)=1$ 을 써서 분자를 $f(x)-1$ 이 든 항과 $x-1$ 이 든 항으로 나누면?","식":["$2x^{2}f(x)-2x=2x^{2}\\{f(x)-1\\}+2x(x-1)$","$x^{3}-1=(x-1)(x^{2}+x+1)$","$\\lim_{x\\to1}\\left\\{\\dfrac{f(x)-1}{x-1}\\cdot\\dfrac{2x^{2}}{x^{2}+x+1}+\\dfrac{2x}{x^{2}+x+1}\\right\\}=\\dfrac23f'(1)+\\dfrac23$"],"설명":"$\\dfrac{f(x)-f(1)}{x-1}$ 이 $f'(1)$ 로 가고, 나머지 인수는 $x=1$ 을 그대로 넣는다. $2x^{2}-2x=2x(x-1)$ 이어서 $x-1$ 이 약분된다.","확인":null,"스킬":"D3"},{"제목":"f'(1) 에 대한 방정식 풀기","힌트":"$f'(1)=\\frac23f'(1)+\\frac23$ 에서 $f'(1)$ 은?","식":["$f'(1)=\\dfrac23f'(1)+\\dfrac23$","$\\dfrac13f'(1)=\\dfrac23$","$f'(1)=2$"],"설명":"양변에서 $\\dfrac23f'(1)$ 을 옮겨 정리한다.","확인":"2","스킬":"D3"}]},"ns-0d5258482cdf":{"길":"x=y=0 으로 f(0) 을 정하고, f(h)≥h 로 좌우 미분계수를 조여 f'(0) 을 얻은 뒤 일반의 x 로 넓힌다","단계":[{"제목":"x=y=0 을 넣어 f(0) 구하기","힌트":"㉠ 에 $x=y=0$ 을 넣고 ㉡ 의 $f(0)\\ge0$ 과 합치면 $f(0)$ 은?","식":["㉠ $x=y=0$: $f(0)\\ge f(0)+f(0)\\ \\Rightarrow\\ f(0)\\le0$","㉡ $x=0$: $f(0)\\ge0$","$f(0)=0$"],"설명":"두 부등식이 서로 반대 방향으로 $0$ 을 조여서 $f(0)$ 이 정해진다.","확인":"0","스킬":"C1"},{"제목":"f(h)≥h 로 f'(0) 구하기","고비":true,"힌트":"$f(h)\\ge h$ 를 $h$ 로 나눌 때 $h>0$ 인 경우와 $h<0$ 인 경우에 부등호의 방향은 어떻게 다를까?","식":["$h>0$: $\\dfrac{f(h)-f(0)}{h}=\\dfrac{f(h)}{h}\\ge1$","$h<0$: $\\dfrac{f(h)}{h}\\le1$ (음수로 나누면 부등호가 바뀐다)","$f'(0)$ 이 존재하므로 $1\\le f'(0)\\le1$, 즉 $f'(0)=1$"],"설명":"우극한은 $1$ 이상이고 좌극한은 $1$ 이하이다. 미분계수가 존재하면 두 극한이 같으므로 $1$ 이 된다. 문제는 $f'(x)$ 가 존재한다고 전제한다.","확인":null,"스킬":"D3"},{"제목":"임의의 x 에서 f'(x) 구하기","힌트":"㉠ 에서 $y=h$ 라 하면 $f(x+h)-f(x)$ 와 $f(h)$ 의 크기는? 양변을 $h$ 로 나눠 극한을 취하면 $f'(x)$ 는?","식":["㉠ 에서 $f(x+h)-f(x)\\ge f(h)$","$h>0$: $\\dfrac{f(x+h)-f(x)}{h}\\ge\\dfrac{f(h)}{h}\\to1$, $h<0$: $\\dfrac{f(x+h)-f(x)}{h}\\le\\dfrac{f(h)}{h}\\to1$","$f'(x)\\ge1,\\ \\ f'(x)\\le1\\ \\Rightarrow\\ f'(x)=1$"],"설명":"$f(0)=0$ 이므로 $f(h)=f(h)-f(0)$ 이고 $\\dfrac{f(h)}{h}$ 의 극한이 $f'(0)=1$ 이다. 좌우로 나눈 극한이 $1$ 을 위아래에서 조인다.","확인":"1","스킬":"D3"}]},"ns-0dc63d861750":{"길":"나누어떨어짐으로 f=f'g 를 쓰고, g 의 최고차항 계수로 g' 를 정해 h' 을 f 로 나타낸다","단계":[{"제목":"몫 g 의 차수와 g' 구하기","힌트":"$f$ 의 최고차항 $x^{3}$ 을 $f'$ 의 최고차항 $3x^{2}$ 으로 나누면 $g$ 의 최고차항 계수는? 그러면 $g'(x)$ 는?","식":["$f(x)=x^{3}+\\cdots,\\ \\ f'(x)=3x^{2}+\\cdots$","$g$ 는 일차이고 최고차항 계수가 $\\dfrac13$","$g'(x)=\\dfrac13$"],"설명":"일차함수의 도함수는 최고차항의 계수와 같은 상수이다. $g$ 의 상수항은 몰라도 $g'$ 에는 영향이 없다.","확인":"1/3","스킬":"A4"},{"제목":"h'(x) 를 f(x) 로 나타내기","고비":true,"힌트":"(가) 에서 $f=f'g$ 이다. $h=fg$ 를 곱의 미분으로 미분하면 $f'g$ 항은 무엇이 될까?","식":["$f(x)=f'(x)g(x)$","$h'(x)=f'(x)g(x)+f(x)g'(x)$","$h'(x)=f(x)+\\dfrac13f(x)=\\dfrac43f(x)$"],"설명":"$f'g$ 는 나누어떨어짐 때문에 $f$ 와 같다. 그래서 $f$ 의 구체적인 식을 모르고도 $h'$ 이 $f$ 의 상수배로 정해진다.","확인":null,"스킬":"A4"},{"제목":"x=-1 을 넣어 h'(-1) 구하기","힌트":"$f(-1)=9$ 를 넣으면 $h'(-1)$ 은?","식":["$h'(-1)=\\dfrac43f(-1)$","$=\\dfrac43\\times9$"],"설명":"(나) 에서 $f(-1)=9$ 이다.","확인":"12","스킬":"A4"}]},"ns-0e3a43a5a6e0":{"길":"주기 1 이므로 x=1 에서 값과 기울기가 이어지는 조건을 f 로 옮겨 보기마다 따진다","단계":[{"제목":"ㄱ: g 가 x=1 에서 이어지고 미분가능한 조건","힌트":"$x=1$ 에서 $g$ 의 좌극한·좌미분계수는 $f$ 의 어느 값이고, 우극한·우미분계수는 $f$ 의 어느 값일까?","식":["$g(1-)=2f(1),\\ \\ g(1+)=g(0+)=2f(0)$","$g'(1-)=2f'(1),\\ \\ g'(1+)=g'(0+)=2f'(0)$","$f(0)=f(1),\\ f'(0)=f'(1)$ 이면 $x=1$ 에서 연속이고 미분가능 (ㄱ 참)"],"설명":"$g$ 는 주기 $1$ 이므로 $x=1$ 근처의 오른쪽 식은 $x=0$ 근처의 오른쪽 식과 같다. 다른 정수에서도 같다. 정수가 아닌 점에서는 다항식이라 미분가능하다.","확인":null,"스킬":"T2"},{"제목":"ㄴ: 미분가능 조건으로 f 의 식 정하기","고비":true,"힌트":"$f(x)=x^{3}+ax^{2}+bx+c$ 에서 $f(0)=f(1)$ 과 $f'(0)=f'(1)$ 을 쓰면 $a$ 는?","식":["$f(1)-f(0)=1+a+b=0$","$f'(1)-f'(0)=(3+2a+b)-b=3+2a=0\\ \\Rightarrow\\ a=-\\dfrac32$","$b=\\dfrac12,\\ \\ f'(1)=3+2a+b=\\dfrac12$ (ㄴ 참)"],"설명":"미분가능하면 ㄱ 의 두 조건이 성립해야 한다. 최고차항의 계수가 $1$ 인 삼차함수이므로 $x^{3}$ 의 계수는 정해져 있다.","확인":"-3/2","스킬":"T2"},{"제목":"ㄷ: 반례로 근의 존재 확인하기","힌트":"$f(x)=x^{3}-\\frac32x^{2}+\\frac12x+c$ 에서 $c=0$ 이면 $g(0)$ 은?","식":["$f(x)=x\\left(x-\\dfrac12\\right)(x-1)+c$","$c=0$ 이면 $g(0)=2f(0)=0$","$g(x)=0$ 인 실수 $x$ 가 존재하므로 (ㄷ 거짓)"],"설명":"$c$ 는 $f$ 의 상수항으로 미분가능 조건에 영향을 주지 않는다. 한 가지 $c$ 에서 근이 있으면 보기의 「존재하지 않는다」는 거짓이다.","확인":"0","스킬":"C3"},{"제목":"옳은 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 옳은 것은?","식":["ㄱ 참, ㄴ 참, ㄷ 거짓","옳은 것은 ㄱ, ㄴ"],"설명":"ㄷ 만 반례가 있어 거짓이다.","확인":null,"스킬":"C3"}]},"ns-0ea561f80f43":{"길":"극한이 존재하므로 f(2)=g(2) 를 얻고, 극한을 f'(2)-g'(2) 로 쪼개 곱의 미분과 연립한다","단계":[{"제목":"f(2)=g(2) 이고 값 구하기","힌트":"(나)의 극한이 유한하려면 분자는 $x=2$ 에서 얼마여야 할까? (가)에 $x=2$ 를 넣으면 $f(2)$ 는?","식":["분모가 $0$ 으로 가므로 $f(2)-g(2)=0$","$g(2)=8f(2)-14$ 이므로 $f(2)=8f(2)-14$","$f(2)=2,\\ \\ g(2)=2$"],"설명":"분모 $x-2$ 가 $0$ 으로 가는데 극한이 $4$ 로 존재하므로 분자도 $0$ 으로 가야 한다.","확인":"2","스킬":"D3"},{"제목":"극한을 f'(2)-g'(2) 로 바꾸기","고비":true,"힌트":"$f(2)=g(2)=2$ 를 분자에 빼고 더해 $\\frac{f(x)-f(2)}{x-2}$ 와 $\\frac{g(x)-g(2)}{x-2}$ 로 나누면?","식":["$\\dfrac{f(x)-g(x)}{x-2}=\\dfrac{f(x)-f(2)}{x-2}-\\dfrac{g(x)-g(2)}{x-2}$","$\\lim_{x\\to2}\\dfrac{f(x)-g(x)}{x-2}=f'(2)-g'(2)=4$","$f'(2)=g'(2)+4$"],"설명":"$f(2)=g(2)$ 이므로 분자에서 같은 값을 빼고 더해도 식이 같다. 두 항이 각각 미분계수의 정의 꼴이다.","확인":null,"스킬":"D3"},{"제목":"곱의 미분으로 g'(2) 를 f'(2) 로 쓰기","힌트":"$g(x)=x^{3}f(x)-14$ 를 곱의 미분으로 미분하고 $x=2$ 를 넣으면?","식":["$g'(x)=3x^{2}f(x)+x^{3}f'(x)$","$g'(2)=12f(2)+8f'(2)$","$g'(2)=24+8f'(2)$"],"설명":"$f(2)=2$ 를 넣어 $12f(2)=24$ 로 계산한다.","확인":null,"스킬":"D3"},{"제목":"연립하여 g'(2) 구하기","힌트":"$f'(2)=g'(2)+4$ 를 $g'(2)=24+8f'(2)$ 에 넣으면 $g'(2)$ 는?","식":["$g'(2)=24+8\\{g'(2)+4\\}$","$-7g'(2)=56$","$g'(2)=-8$"],"설명":"미지수 $g'(2)$ 만 남는 일차방정식이다.","확인":"-8","스킬":"D3"}]},"ns-0fba50ac1f12":{"길":"보기마다 그래프에서 좌우 극한과 꺾임을 읽어 참 거짓을 가린다","단계":[{"제목":"ㄱ: x=2 에서 f-g 의 극한 확인","힌트":"$x=2$ 근처에서 $f$ 와 $g$ 는 이어져 있을까? $x\\to2$ 일 때 $f(x)-g(x)$ 가 가까워지는 값은?","식":["$f(2)=1,\\ \\ g(2)=1$ 이고 $x=2$ 근처에서 두 그래프가 모두 이어져 있다","$\\lim_{x\\to2}\\{f(x)-g(x)\\}=1-1=0$","극한이 존재 (ㄱ 참)"],"설명":"$g$ 는 $0\\le x\\le3$ 에서 상수 $1$ 이고 $f$ 는 $x=2$ 에서 꺾이지만 끊기지 않는다. 이어진 점에서 극한은 함숫값과 같다.","확인":"0","스킬":"C3"},{"제목":"ㄴ: (f∘f)(-x) 의 x=-1 에서의 연속 확인","고비":true,"힌트":"$u=-x$ 로 두면 $x\\to-1$ 은 $u\\to1$ 이다. $u\\to1+$ 일 때 $f(f(u))$ 가 가까워지는 값은?","식":["$u\\to1-$: $f(u)\\to2-$ 이므로 $f(f(u))\\to f(2-)=1$","$u\\to1+$: $f(u)=1$ 이므로 $f(f(u))=f(1)=2$","좌극한 $1\\ne$ 우극한 $2$ 이므로 불연속 (ㄴ 거짓)"],"설명":"$f$ 는 $x\\le1$ 에서 $x+1$ 이라 $1$ 의 왼쪽에서 $2$ 의 왼쪽 값을 갖고, $1<x\\le2$ 에서 상수 $1$ 이다. $f(1)=2$ 인 닫힌 점과 $f(1+)=1$ 인 열린 점을 구별한다.","확인":"2","스킬":"T6"},{"제목":"ㄷ: x=2 에서 f×g 의 미분가능 확인","힌트":"$x=2$ 근처에서 $g(x)=1$ 이면 $f(x)g(x)$ 는 무엇과 같을까? $x=2$ 에서 $f$ 의 우미분계수는?","식":["$x=2$ 근처에서 $g(x)=1$ 이므로 $f(x)g(x)=f(x)$","$f$ 의 좌미분계수 $0$ ($y=1$), 우미분계수 $1$ ($y=x-1$)","좌우 미분계수가 달라 미분 불가능 (ㄷ 참)"],"설명":"$g$ 가 상수이면 곱의 모양이 $f$ 와 같아 $f$ 의 꺾임이 그대로 남는다.","확인":"1","스킬":"D1"},{"제목":"옳은 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 옳은 것은?","식":["ㄱ 참, ㄴ 거짓, ㄷ 참","옳은 것은 ㄱ, ㄷ"],"설명":"ㄴ 만 좌우 극한이 달라 거짓이다.","확인":null,"스킬":"C3"}]},"ns-1316abbc0db6":{"길":"x=1 의 좌우에서 식을 따로 써서 좌미분계수와 우미분계수를 비교한다","단계":[{"제목":"ㄱ: x f(x) 의 좌우 미분계수 비교","힌트":"$x<1$ 에서 $xf(x)=x(1-x)$ 이다. $x=1$ 에서의 좌미분계수는?","식":["$x<1$: $xf(x)=x-x^{2}$, 미분계수 $1-2x\\to-1$","$x\\ge1$: $xf(x)=x^{2}-x$, 미분계수 $2x-1\\to1$","좌우가 달라 미분 불가능 (ㄱ 제외)"],"설명":"$xf(x)$ 는 $x=1$ 에서 이어지지만 좌우 기울기가 다르다.","확인":"-1","스킬":"C2"},{"제목":"ㄴ: f(x)g(x) 의 좌우 미분계수 비교","고비":true,"힌트":"$f(1)g(1)=0$ 이다. $\\frac{f(x)g(x)-0}{x-1}$ 의 우극한은?","식":["$x\\ge1$: $\\dfrac{(x-1)(2x+1)}{x-1}=2x+1\\to3$","$x<1$: $\\dfrac{(1-x)(-x-2)}{x-1}=x+2\\to3$","좌우 미분계수가 모두 $3$ 이므로 미분가능 (ㄴ 포함)"],"설명":"$g$ 는 $x=1$ 에서 끊기지만 $f(1)=0$ 이어서 곱이 $x=1$ 에서 $0$ 으로 이어지고 인수 $x-1$ 이 약분된다.","확인":"3","스킬":"C2"},{"제목":"ㄷ: |f-g| 의 좌우 미분계수 비교","힌트":"$f-g$ 를 $x\\ge1$ 과 $x<1$ 로 나눠 쓰면? $x=1$ 에서 우미분계수는?","식":["$x\\ge1$: $f-g=-x-2,\\ \\ |f-g|=x+2$","$x<1$: $f-g=3,\\ \\ |f-g|=3$","좌미분계수 $0$, 우미분계수 $1$ 이어서 미분 불가능 (ㄷ 제외)"],"설명":"$x=1$ 에서 두 식의 값이 $3$ 으로 같아 이어지지만 기울기가 다르다.","확인":"1","스킬":"G5"},{"제목":"미분가능한 보기 가려내기","힌트":"세 보기 중 $x=1$ 에서 미분가능한 것은?","식":["ㄱ 불가능, ㄴ 가능, ㄷ 불가능","ㄴ"],"설명":"ㄴ 하나만 좌우 미분계수가 같다.","확인":null,"스킬":"C3"}]},"ns-14ac2bda3ce2":{"길":"|3x²-12| 의 도함수를 구간별로 갈라 b 에서 좌미분계수가 우미분계수와 같은 b 를 찾고, 연속 조건으로 a 를 구한다","단계":[{"제목":"|3x²-12| 의 도함수를 구간별로 구하기","힌트":"$3x^{2}-12<0$ 이 되는 $x$ 의 범위에서 절댓값을 벗기면 도함수는?","식":["$|x|<2$: $|3x^{2}-12|=12-3x^{2}$, 도함수 $-6x$","$|x|>2$: $|3x^{2}-12|=3x^{2}-12$, 도함수 $6x$","$x=\\pm2$ 에서는 꺾여 미분 불가능"],"설명":"$3x^{2}-12=3(x-2)(x+2)$ 이므로 $-2<x<2$ 에서 음수이다.","확인":null,"스킬":"G5"},{"제목":"좌미분계수와 우미분계수가 같은 b 구하기","고비":true,"힌트":"$x\\ge b$ 의 식 $6x+a$ 의 미분계수는 $6$ 이다. $|b|<2$ 일 때와 $|b|>2$ 일 때 좌미분계수가 $6$ 이 되는 $b$ 는?","식":["$|b|<2$: $-6b=6\\ \\Rightarrow\\ b=-1$ (범위 만족)","$|b|>2$: $6b=6\\ \\Rightarrow\\ b=1$ (범위 불만족)","$b=\\pm2$ 는 꺾이는 점이어서 불가, 따라서 $b=-1$"],"설명":"구한 값이 처음 가정한 범위 안에 들어야 한다.","확인":"-1","스킬":"C2"},{"제목":"연속 조건으로 a 구하기","힌트":"$x=b=-1$ 에서 $|3b^{2}-12|=6b+a$ 이다. $a$ 는?","식":["$|3\\cdot(-1)^{2}-12|=9$","$9=6\\cdot(-1)+a$","$a=15$"],"설명":"미분가능하면 연속이므로 두 식의 $x=b$ 에서의 값이 같아야 한다.","확인":"15","스킬":"D12"},{"제목":"a+b 계산하기","힌트":"구한 $a$ 와 $b$ 를 더하면?","식":["$a+b=15+(-1)=14$"],"설명":"구한 두 값을 더한다.","확인":"14","스킬":"A2"}]},"ns-14c7a314ea50":{"길":"h 의 부호에 따라 2±h 가 어느 식에 들어가는지 나누어 두 극한을 구한다","단계":[{"제목":"첫 극한 구하기","힌트":"$-1-|h|\\le-1$ 이므로 $f(-1-|h|)$ 는 어느 식을 쓸까? 극한은?","식":["$f(-1)=-(-1)-1=0$","$f(-1-|h|)=-(-1-|h|)-1=|h|$","$\\lim_{h\\to0}\\dfrac{|h|-0}{-|h|}=-1$"],"설명":"$h\\ne0$ 이면 $-1-|h|<-1$ 이므로 $x\\le-1$ 인 식 $-x-1$ 을 쓴다.","확인":"-1","스킬":"D3"},{"제목":"둘째 극한 구하기","고비":true,"힌트":"$h>0$ 이면 $2+h>2,\\ 2-h<2$ 이다. 각 식을 넣어 $f(2+h)-f(2-h)$ 를 정리하면 극한은?","식":["$h>0$: $f(2+h)=4h,\\ \\ f(2-h)=3h-h^{2}$, 차는 $h+h^{2}$","$h<0$: $f(2+h)=-3h-h^{2},\\ \\ f(2-h)=-4h$, 차는 $h-h^{2}$","두 경우 모두 $\\dfrac{\\text{차}}{h}\\to1$"],"설명":"$h$ 의 부호에 따라 $2+h$ 와 $2-h$ 가 들어가는 식이 서로 바뀐다. $h$ 로 나누면 $1+h$ 또는 $1-h$ 이다.","확인":"1","스킬":"C2"},{"제목":"두 극한의 합 구하기","힌트":"두 극한값을 더하면?","식":["$-1+1=0$"],"설명":"첫 극한 $-1$ 과 둘째 극한 $1$ 을 더한다.","확인":"0","스킬":"A2"}]},"ns-155a5826dd2f":{"길":"미분가능 조건으로 g 의 네 조건을 세우고 이차가 안 되는 것을 보인 뒤 삼차로 올려 k 와 m 을 정한다","단계":[{"제목":"연속·미분가능 조건 옮기기","힌트":"$x=0$ 과 $x=2$ 에서 $f$ 가 이어지고 기울기가 같으려면 $g$ 가 만족할 네 조건은?","식":["$x=0$: $g(0)=0+1=1,\\ \\ g'(0)=1$","$x=2$: $g(2)=k(2-2)+1=1,\\ \\ g'(2)=k$"],"설명":"$f$ 가 이어지려면 이웃한 식의 값이 같고, 미분가능하려면 기울기도 같아야 한다.","확인":null,"스킬":"D12"},{"제목":"이차함수로는 안 되는 까닭 확인하기","힌트":"$g(x)=mx^{2}+x+1$ 로 두고 $g(2)=1$ 을 쓰면 $g(1)$ 은?","식":["$g(x)=mx^{2}+x+1$ ($g(0)=1,\\ g'(0)=1$ 을 만족)","$g(2)=4m+3=1\\ \\Rightarrow\\ m=-\\dfrac12$","$g(1)=m+2=\\dfrac32$"],"설명":"$g(1)=\\dfrac32$ 는 $\\dfrac14<g(1)<\\dfrac34$ 에 맞지 않으므로 이차함수는 불가능하다. 일차 이하는 $g(2)=1$ 을 만족하지 못한다.","확인":"3/2","스킬":"A3"},{"제목":"삼차함수로 올려 p, m, k 사이의 관계 구하기","고비":true,"힌트":"$g(x)=px^{3}+mx^{2}+x+1$ 에 $g(2)=1$ 과 $g'(2)=k$ 를 넣으면 $m,\\ k$ 를 $p$ 로 어떻게 쓸까?","식":["$g(2)=8p+4m+3=1\\ \\Rightarrow\\ 2m=-1-4p$","$g'(2)=12p+4m+1=k$","$k=12p+2(-1-4p)+1=4p-1$"],"설명":"$g(0)=1,\\ g'(0)=1$ 로 상수항과 일차항이 정해지고, $x=2$ 의 두 조건이 $p,\\ m,\\ k$ 의 관계가 된다.","확인":null,"스킬":"A3"},{"제목":"g(1) 범위로 p 와 k 정하기","힌트":"$g(1)=-p+\\frac32$ 가 $\\frac14$ 와 $\\frac34$ 사이이면 $p$ 의 범위는? 그 범위에서 $k=4p-1$ 이 자연수가 되는 값은?","식":["$g(1)=p+m+2=-p+\\dfrac32$","$\\dfrac14<-p+\\dfrac32<\\dfrac34\\ \\Rightarrow\\ \\dfrac34<p<\\dfrac54$","$2<k=4p-1<4$ 이므로 $k=3,\\ p=1$"],"설명":"$p$ 의 범위를 $4$ 배하고 $1$ 을 빼면 $k$ 의 범위가 된다. 그 안의 자연수는 하나뿐이다.","확인":"3","스킬":"A3"},{"제목":"m 을 구하고 km 계산하기","힌트":"$2m=-1-4p$ 에 $p=1$ 을 넣어 $m$ 을 구하면 $km$ 은?","식":["$2m=-1-4=-5\\ \\Rightarrow\\ m=-\\dfrac52$","$km=3\\times\\left(-\\dfrac52\\right)=-\\dfrac{15}{2}$"],"설명":"$m$ 은 $g$ 의 이차항의 계수이다.","확인":"-15/2","스킬":"A3"}]},"ns-1591611afd9e":{"길":"x=0 을 넣어 g(0) 을 정하고, 끼인 함수와의 차가 x=0 에서 최소라는 것으로 미분계수를 얻는다","단계":[{"제목":"x=0 대입으로 g(0) 구하기","힌트":"부등식에 $x=0$ 을 넣고 $f(0)=0$ 을 쓰면 $g(0)$ 은?","식":["$2-f(0)\\le g(0)\\le2+f(0)$","$f(0)=0$ 이므로 $2\\le g(0)\\le2$","$g(0)=2$"],"설명":"$x=0$ 은 $|x|<1$ 안에 있어 부등식이 성립한다. 양쪽 끝이 같아져 $g(0)$ 이 정해진다.","확인":"2","스킬":"C9"},{"제목":"x=0 에서 최소가 되는 차함수 세우기","고비":true,"힌트":"$A(x)=g(x)-\\{x^{2}+2x+2-f(x)\\}$ 는 $|x|<1$ 에서 $0$ 이상이다. $A(0)$ 은 얼마일까?","식":["$A(x)=g(x)-x^{2}-2x-2+f(x)\\ge0,\\ \\ A(0)=2-2+0=0$","$B(x)=x^{4}+2x+2+f(x)-g(x)\\ge0,\\ \\ B(0)=0$","$A,\\ B$ 는 $x=0$ 에서 최솟값 $0$ 이므로 $A'(0)=B'(0)=0$"],"설명":"$A,\\ B$ 는 미분가능하고 $x=0$ 이 구간 $(-1,\\ 1)$ 의 안쪽이라서, 최솟값을 갖는 점에서 미분계수가 $0$ 이다.","확인":null,"스킬":"C9"},{"제목":"미분계수 조건으로 g'(0) 구하기","힌트":"$A'(0)=0,\\ B'(0)=0$ 에서 $g'(0)$ 을 $f'(0)$ 으로 나타내면? $g'(0)$ 은?","식":["$A'(0)=g'(0)-2+f'(0)=0\\ \\Rightarrow\\ g'(0)=2-f'(0)$","$B'(0)=2+f'(0)-g'(0)=0\\ \\Rightarrow\\ g'(0)=2+f'(0)$","$f'(0)=0,\\ \\ g'(0)=2$"],"설명":"두 식에서 $f'(0)$ 의 부호가 반대이므로 $f'(0)=0$ 이 되고 $g'(0)$ 이 정해진다.","확인":"2","스킬":"D1"},{"제목":"g(0)+g'(0) 계산하기","힌트":"앞에서 구한 두 값을 더하면?","식":["$g(0)+g'(0)=2+2=4$"],"설명":"구한 두 값을 더한다.","확인":"4","스킬":"A2"}]},"ns-1c7c029941be":{"길":"(나)로 f(2)>0 을 확인하고 (다)로 a, c 를 정한 뒤 f(2) 가 최소인 식을 확정해 미분계수를 구한다","단계":[{"제목":"(나)에서 읽는 f 의 부호","힌트":"$x<2$ 에서 $f$ 는 아래로 볼록한 이차식이다. 이 구간에서 $f$ 의 부호가 바뀌면 $|f|$ 는 어떻게 될까?","식":["$x<2$ 에서 $f$ 의 부호가 바뀌면 $|f|$ 가 $x<2$ 에서도 꺾인다","꺾이는 곳은 $x=p\\ (p>2)$ 뿐이므로 $x<2$ 에서 $f(x)\\ge0$","$x>2$ 에서 $f$ 가 $0$ 을 지나야 하므로 $f(2)>0$"],"설명":"$f(2)>0$ 이어야 $x=2$ 근처에서 $|f|=f$ 이고 $x=p>2$ 에서만 부호가 바뀐다.","확인":null,"스킬":"G5"},{"제목":"(다)에서 f'(2) 조건을 읽어 a, c 구하기","고비":true,"힌트":"$f(2)>0$ 이면 $x=2$ 근처에서 $|f|=f$ 이다. $f(x)-f(2)$ 는 $x=2$ 에서 $0$ 인데 그 절댓값이 미분가능하려면 $f'(2)$ 는?","식":["$h(x)=f(x)-f(2)$ 로 두면 $h(2)=0$ 이고 $|h|$ 가 $x=2$ 에서 미분가능하다","$h(2)=0$ 인 점에서 $|h|$ 가 미분가능하려면 $h'(2)=f'(2)=0$","$f'(x)=2x+a\\ (x<2),\\ -2x+c\\ (x\\ge2)$ 이므로 $4+a=0,\\ -4+c=0$ 에서 $a=-4,\\ c=4$"],"설명":"$h(2)=0$ 일 때 $|h|$ 는 $h'(2)\\ne0$ 이면 $x=2$ 에서 꺾인다. 따라서 $f'(2)=0$ 이어야 하고 (가)에서 좌우 미분계수는 같다.","확인":"-4","스킬":"G5"},{"제목":"f 를 f(2) 로 나타내고 p 찾기","힌트":"$a=-4,\\ c=4$ 를 넣고 각 구간의 식을 $(x-2)^{2}$ 꼴로 고치면 $x>2$ 에서 $f(x)=0$ 이 되는 $x$ 는?","식":["$x<2$: $f(x)=x^{2}-4x+b=(x-2)^{2}+f(2)$","$x\\ge2$: $f(x)=-x^{2}+4x+d=-(x-2)^{2}+f(2)$","$x>2$ 에서 $f(x)=0$ 이 되는 점은 $p=2+\\sqrt{f(2)}$"],"설명":"$x<2$ 에서는 $f(x)\\ge f(2)>0$ 이므로 $|f|$ 가 꺾이지 않고, $x>2$ 에서만 $f$ 가 $0$ 을 지난다.","확인":null,"스킬":"A6"},{"제목":"f(2) 의 최솟값으로 b, d, p 정하기","힌트":"$f(2)=b-4$ 이고 $b$ 는 정수이다. $f(2)>0$ 인 정수 중 가장 작은 값을 쓰면 $p$ 는?","식":["$f(2)=b-4=4+d$ 가 양의 정수이므로 최솟값은 $1$","$b=5,\\ d=-3$","$p=2+\\sqrt{1}=3$"],"설명":"$a,\\ b,\\ c,\\ d$ 가 정수이므로 $f(2)=b-4$ 도 정수이고 $f(2)>0$ 이다.","확인":"3","스킬":"C7"},{"제목":"f'(a-c+p) 계산","힌트":"$a-c+p$ 의 값이 $2$ 보다 큰지 작은지에 따라 쓸 도함수의 식이 달라진다. $f'(a-c+p)$ 는?","식":["$a-c+p=-4-4+3=-5$","$-5<2$ 이므로 $f'(x)=2x-4$ 에서 $f'(-5)=-14$"],"설명":"$a=-4$ 이므로 $x<2$ 구간의 도함수 $2x+a$ 를 쓴다.","확인":"-14","스킬":"D1"}]},"ns-203470b59201":{"길":"x<1, x≥1 에서 두 거리 제곱을 식으로 써서 크기가 바뀌는 점과 도함수 계수를 읽는다","단계":[{"제목":"x<1 에서 두 거리 제곱이 바뀌는 점","힌트":"$x<1$ 에서 $\\mathrm{P}(x,\\,x+1)$ 이다. $\\overline{\\mathrm{PA}}^{2}\\le\\overline{\\mathrm{PB}}^{2}$ 이 되는 $x$ 의 범위는?","식":["$\\overline{\\mathrm{PA}}^{2}=(x+1)^{2}+(x+2)^{2}=2x^{2}+6x+5$","$\\overline{\\mathrm{PB}}^{2}=(x-1)^{2}+(x-1)^{2}=2x^{2}-4x+2$","$\\overline{\\mathrm{PA}}^{2}\\le\\overline{\\mathrm{PB}}^{2}\\iff x\\le-\\frac{3}{10}$ 이므로 $\\alpha=-\\frac{3}{10}$"],"설명":"$x<-\\frac{3}{10}$ 에서는 A 까지의 값이 작고, 그 오른쪽에서는 B 까지의 값이 작아 $g$ 의 식이 바뀐다.","확인":"-3/10","스킬":"C2"},{"제목":"x≥1 에서 두 거리 제곱이 바뀌는 점","힌트":"$x\\ge1$ 에서 $\\mathrm{P}(x,\\,-2x+4)$ 이다. $\\overline{\\mathrm{PA}}^{2}\\le\\overline{\\mathrm{PB}}^{2}$ 이 되는 $x$ 의 범위는?","식":["$\\overline{\\mathrm{PA}}^{2}=(x+1)^{2}+(-2x+5)^{2}=5x^{2}-18x+26$","$\\overline{\\mathrm{PB}}^{2}=(x-1)^{2}+(-2x+2)^{2}=5x^{2}-10x+5$","$\\overline{\\mathrm{PA}}^{2}\\le\\overline{\\mathrm{PB}}^{2}\\iff x\\ge\\frac{21}{8}$ 이므로 $\\beta=\\frac{21}{8}$"],"설명":"$1\\le x<\\frac{21}{8}$ 에서는 B 까지의 값이, $x>\\frac{21}{8}$ 에서는 A 까지의 값이 작다.","확인":"21/8","스킬":"C2"},{"제목":"가운데 두 구간의 도함수에서 a, b, c, d 읽기","고비":true,"힌트":"$\\alpha<x\\le1$ 과 $1\\le x<\\beta$ 에서는 어느 쪽 거리 제곱이 $g$ 일까? 그 도함수에서 계수를 읽으면 $a+b+c+d$ 는?","식":["$\\alpha<x\\le1$: $g=\\overline{\\mathrm{PB}}^{2}=2x^{2}-4x+2$, $g'=4x-4$ 이므로 $a=4,\\ b=-4$","$1\\le x<\\beta$: $g=\\overline{\\mathrm{PB}}^{2}=5x^{2}-10x+5$, $g'=10x-10$ 이므로 $c=10,\\ d=-10$","$a+b+c+d=0$"],"설명":"두 구간 모두 B 까지의 거리 제곱이 작은 쪽이라 $x=1$ 에서 식은 다르지만 도함수 값은 $0$ 으로 같다.","확인":"0","스킬":"D1"},{"제목":"40(a+b+c+d+α+β) 계산","힌트":"$\\alpha+\\beta$ 를 통분해 더한 뒤 $40$ 을 곱하면?","식":["$\\alpha+\\beta=-\\frac{3}{10}+\\frac{21}{8}=\\frac{93}{40}$","$40\\left(0+\\frac{93}{40}\\right)=93$"],"설명":"$a+b+c+d=0$ 이므로 $40(\\alpha+\\beta)$ 만 남는다.","확인":"93","스킬":"A2"}]},"ns-2949c53a18f5":{"길":"절댓값을 구간별로 벗겨 x=±1 에서 미분계수가 같아지는 a, b 를 구하고 f(a+b-2) 를 g 의 값으로 바꾼다","단계":[{"제목":"절댓값을 벗겨 구간별 g 쓰기","힌트":"$x+1,\\ x^{2}-1,\\ x^{3}+1$ 의 부호가 모두 정해지는 구간은 $x=-1,\\ 1$ 을 경계로 어떻게 나뉠까?","식":["$x<-1$: $g(x)=x^{3}+bx^{2}-ax-a-b+1$","$-1\\le x<1$: $g(x)=-x^{3}-bx^{2}+ax+a+b-1$","$x\\ge1$: $g(x)=-x^{3}+bx^{2}+ax+a-b-1$"],"설명":"$x^{3}+1=(x+1)(x^{2}-x+1)$ 이고 $x^{2}-x+1>0$ 이므로 $x^{3}+1$ 의 부호는 $x+1$ 과 같다.","확인":null,"스킬":"C2"},{"제목":"x=1 에서 미분계수가 같아지는 b","고비":true,"힌트":"$g$ 가 $x=1$ 에서 미분가능하려면 왼쪽 구간과 오른쪽 구간의 도함수가 $x=1$ 에서 같아야 한다. 이때 $b$ 는?","식":["$-1\\le x<1$: $g'(x)=-3x^{2}-2bx+a$ 이므로 $g'(1^{-})=-3-2b+a$","$x\\ge1$: $g'(x)=-3x^{2}+2bx+a$ 이므로 $g'(1^{+})=-3+2b+a$","$-3-2b+a=-3+2b+a$ 에서 $b=0$"],"설명":"$g$ 는 두 구간에서 값도 같게 이어지므로 미분계수만 맞추면 된다.","확인":"0","스킬":"G5"},{"제목":"x=-1 에서 미분계수가 같아지는 a","힌트":"$b=0$ 을 넣고 $x=-1$ 의 왼쪽 구간과 오른쪽 구간의 도함수를 같게 놓으면 $a$ 는?","식":["$x<-1$: $g'(x)=3x^{2}+2bx-a$ 이므로 $g'(-1^{-})=3-2b-a$","$-1\\le x<1$: $g'(-1^{+})=-3+2b+a$","$3-2b-a=-3+2b+a$ 에서 $a+2b=3$, $b=0$ 이므로 $a=3$"],"설명":"두 식 모두 $b$ 를 포함하므로 앞 단계에서 구한 $b=0$ 을 대입한다.","확인":"3","스킬":"G5"},{"제목":"f(a+b-2) 를 g 의 값으로 바꿔 계산","힌트":"$a+b-2$ 의 값은? 그 점에서 $f$ 와 $g$ 의 함숫값이 같으므로 $g$ 의 값을 구하면?","식":["$a+b-2=3+0-2=1$","(나)에서 $f(1)=g(1)$ 이고 $x\\ge1$ 구간의 식에서 $g(1)=-1+b+a+a-b-1=2a-2$","$f(1)=2\\cdot3-2=4$"],"설명":"(나)(다)의 조건은 $a,\\ b$ 를 구하는 데 쓰였고, 구하는 값은 $f(1)=g(1)$ 로 바로 계산된다.","확인":"4","스킬":"C5"}]},"ns-3015932ddd3b":{"길":"보기마다 구간별 식과 좌우 미분계수를 비교해 참 거짓을 가린다","단계":[{"제목":"ㄱ: x=1 에서 f 의 좌우 미분계수 비교","힌트":"$0<x<1$ 의 식을 미분해 $x=1$ 을 넣으면 좌미분계수는? $1<x<2$ 에서는?","식":["$0<x<1$: $f'(x)=9x^{2}-12x+6$ 이므로 $f'(1^{-})=3$","$1<x<2$: $f'(x)=3$ 이므로 $f'(1^{+})=3$","$f(1)=3$ 으로 이어지고 좌우 미분계수가 같아 미분가능 (ㄱ 참)"],"설명":"그래프가 $x=1$ 에서 부드럽게 이어져 꺾이지 않는다.","확인":"3","스킬":"D1"},{"제목":"g(t) 를 구간별 식으로 쓰기","힌트":"$g(t)=\\frac{f(t)-f(0)}{t-0}$ 이고 $f(0)=0$ 이다. 각 구간에서 $f(t)$ 를 $t$ 로 나누면?","식":["$f(0)=0$ 이므로 $g(t)=\\dfrac{f(t)}{t}$","$0<t<1$: $g(t)=3t^{2}-6t+6$, $1\\le t<2$: $g(t)=3$","$2\\le t<5$: $g(t)=-t+5$"],"설명":"평균변화율은 원점과 점 $(t,\\,f(t))$ 를 잇는 직선의 기울기이다.","확인":null,"스킬":"G9"},{"제목":"ㄴ: g 가 상수인 구간 찾기","고비":true,"힌트":"$1\\le t<2$ 에서 $g$ 의 값은 $t$ 가 변해도 어떻게 될까? 그 안에서 $a<b$ 를 잡으면?","식":["$1<a<b<2$ 이면 $g(a)=g(b)=3$","$g(a)>g(b)$ 가 성립하지 않는 $a,\\ b$ 가 있으므로 ㄴ 거짓"],"설명":"'모든 $a,\\ b$ 에 대하여' 로 시작하는 명제는 반례 하나로 거짓이 된다.","확인":null,"스킬":"C3"},{"제목":"ㄷ: t=1 에서 g 의 좌우 미분계수 비교","힌트":"$0<t<1$ 의 식을 미분해 $t=1$ 을 넣으면? $1<t<2$ 에서 $g'$ 는?","식":["$0<t<1$: $g'(t)=6t-6$ 이므로 $g'(1^{-})=0$","$1<t<2$: $g(t)=3$ 이므로 $g'(1^{+})=0$","$g(1)=3$ 으로 이어지고 좌우 미분계수가 같아 미분가능 (ㄷ 참)"],"설명":"$g(1)=3-6+6=3$ 이어서 두 구간의 값도 맞는다.","확인":"0","스킬":"D1"},{"제목":"옳은 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 옳은 것은?","식":["ㄱ 참, ㄴ 거짓, ㄷ 참","옳은 것은 ㄱ, ㄷ"],"설명":"ㄴ 만 $g$ 가 상수인 구간이 있어 거짓이다.","확인":null,"스킬":"C3"}]},"ns-377579ca4c2c":{"길":"x=y=0 대입으로 f(0) 을 정하고, 부등식을 미분계수 꼴로 바꿔 y 의 부호별로 f'(x) 를 양쪽에서 끼운다","단계":[{"제목":"x=y=0 을 대입해 f(0) 구하기","힌트":"(가)에 $x=y=0$ 을 넣으면 $f(0)$ 은 어떤 값 이상일까? (나)와 합치면?","식":["$f(0)\\ge f(0)-f(0)+(0-\\sqrt{2})^{2}-1=1$","(나) $f(0)\\le1$ 과 합쳐 $f(0)=1$"],"설명":"한 부등식에서는 $f(0)\\ge1$, 다른 부등식에서는 $f(0)\\le1$ 이므로 $f(0)$ 은 $1$ 로 정해진다.","확인":"1","스킬":"C1"},{"제목":"부등식을 f(x+y)-f(x) 꼴로 정리","힌트":"$(xy-\\sqrt{2})^{2}-1$ 을 전개하고 상수 $1$ 을 $f(0)$ 으로 바꾸면 우변은?","식":["$(xy-\\sqrt{2})^{2}-1=x^{2}y^{2}-2\\sqrt{2}xy+1$","$1=f(0)$ 이므로 $f(x+y)-f(x)\\ge-\\{f(y)-f(0)\\}+x^{2}y^{2}-2\\sqrt{2}xy$"],"설명":"좌변이 $f(x+y)-f(x)$, 우변에 $f(y)-f(0)$ 이 나타나 미분계수의 정의와 같은 모양이 된다.","확인":null,"스킬":"D3"},{"제목":"y>0 으로 나눠 y→0+ 보내기","고비":true,"힌트":"양변을 $y\\ (>0)$ 로 나누고 $y\\to0+$ 로 보내면 $\\frac{f(x+y)-f(x)}{y}$ 는 무엇에 가까워질까?","식":["$\\dfrac{f(x+y)-f(x)}{y}\\ge-\\dfrac{f(y)-f(0)}{y}+x^{2}y-2\\sqrt{2}x$","$y\\to0+$ 이면 $f'(x)\\ge-f'(0)-2\\sqrt{2}x$","(다) $f'(0)=0$ 이므로 $f'(x)\\ge-2\\sqrt{2}x$"],"설명":"$f$ 가 미분가능하므로 $f(y)-f(0)$ 을 $y$ 로 나눈 극한이 $f'(0)$ 이고 $x^{2}y$ 항은 $0$ 으로 간다.","확인":null,"스킬":"D3"},{"제목":"y<0 쪽 부등식과 합쳐 f'(x) 확정","힌트":"$y<0$ 으로 나누면 부등호 방향은 어떻게 될까? 두 부등식을 합치면 $f'(x)$ 는?","식":["$y<0$ 으로 나누면 부등호가 바뀌어 $y\\to0-$ 에서 $f'(x)\\le-2\\sqrt{2}x$","$f'(x)\\ge-2\\sqrt{2}x$ 와 합쳐 $f'(x)=-2\\sqrt{2}x$"],"설명":"음수로 나누면 부등호가 뒤집히므로 같은 식에서 반대 방향의 부등식이 나온다.","확인":null,"스킬":"C1"}]},"ns-39ef1d02d0aa":{"길":"g 의 연속 조건으로 f 의 값과 미분계수를 읽고, |f| 의 미분가능 조건으로 a 를 정한다","단계":[{"제목":"연속 조건에서 f(1) 과 f'(1) 읽기","힌트":"$x\\to1-$ 일 때 $\\frac{f(x)}{x-1}$ 의 극한이 존재하려면 분자 $f(x)$ 는 $x\\to1$ 에서 어떤 값이어야 할까?","식":["$x=1$ 에서 연속이므로 $\\lim_{x\\to1-}\\dfrac{f(x)}{x-1}=g(1)=a-2$","분모가 $0$ 으로 가므로 분자도 $0$ 으로 가야 하여 $f(1)=0$","그러면 극한은 미분계수의 정의와 같아 $f'(1)=a-2$"],"설명":"$f$ 는 다항함수라 $x=1$ 에서 연속이고 미분가능하므로 $f(1)=0$ 이다.","확인":null,"스킬":"D1"},{"제목":"|f| 의 미분가능 조건에서 f'(1) 읽기","고비":true,"힌트":"$f(1)=0$ 인 점에서 $|f|$ 의 좌미분계수와 우미분계수는 $f'(1)$ 로 어떻게 표현될까? 둘이 같으려면 $f'(1)$ 은?","식":["$f(1)=0$ 이면 $x=1$ 근처에서 $|f|$ 의 우미분계수는 $|f'(1)|$, 좌미분계수는 $-|f'(1)|$","두 값이 같으려면 $|f'(1)|=-|f'(1)|$ 이므로 $f'(1)=0$"],"설명":"$f(1)=0$ 이고 $f'(1)\\ne0$ 이면 $f$ 의 부호가 $x=1$ 에서 바뀌어 $|f|$ 의 그래프가 꺾인다.","확인":"0","스킬":"G5"},{"제목":"a 와 g(a) 구하기","힌트":"$f'(1)=a-2$ 와 $f'(1)=0$ 을 연결하면 $a$ 는? 그 값이 $1$ 이상인지 보고 쓸 식을 정하면?","식":["$a-2=0$ 에서 $a=2$","$2\\ge1$ 이므로 $g(2)=-2\\cdot2+2=-2$"],"설명":"$a=2$ 는 $x\\ge1$ 구간에 속하므로 $g(x)=-2x+a$ 를 쓴다.","확인":"-2","스킬":"A1"}]},"ns-3adf25713988":{"길":"t-2 를 h 로 치환해 분자를 f(1)을 기준으로 한 두 미분계수 꼴로 만들고 분모를 정리한다","단계":[{"제목":"t-2=h 로 치환해 극한식 다시 쓰기","힌트":"$t=2$ 일 때 $2t-3$ 과 $5-2t$ 의 값은? $t=2+h$ 로 두면 두 인수는?","식":["$t=2$ 이면 $2t-3=1,\\ 5-2t=1$ 로 두 값이 같다","$t=2+h$ 이면 $2t-3=1+2h,\\ 5-2t=1-2h,\\ t^{2}-4=h(h+4)$","$\\lim_{h\\to0}\\dfrac{f(1+2h)-f(1-2h)}{h(h+4)}$"],"설명":"$t\\to2$ 는 $h\\to0$ 이고, 두 인수가 모두 $1$ 근처에서 $\\pm2h$ 만큼 벌어진다.","확인":null,"스킬":"D3"},{"제목":"분자를 f'(1) 의 배수로 나타내기","고비":true,"힌트":"$f(1+2h)-f(1-2h)$ 에 $f(1)$ 을 더하고 빼 $h$ 로 나누면 $f'(1)$ 의 몇 배에 가까워질까?","식":["$f(1+2h)-f(1-2h)=\\{f(1+2h)-f(1)\\}-\\{f(1-2h)-f(1)\\}$","$\\dfrac{f(1+2h)-f(1)}{h}\\to2f'(1),\\ \\ \\dfrac{f(1-2h)-f(1)}{h}\\to-2f'(1)$","$\\dfrac{f(1+2h)-f(1-2h)}{h}\\to4f'(1)$"],"설명":"$\\frac{f(1+2h)-f(1)}{2h}$ 가 $f'(1)$ 로 가므로 분모 $h$ 에 맞추려면 $2$ 를 곱한다.","확인":"4","스킬":"D3"},{"제목":"분모의 h+4 를 처리해 값 확정","힌트":"$\\frac{1}{h(h+4)}=\\frac{1}{h}\\cdot\\frac{1}{h+4}$ 이다. $h\\to0$ 일 때 $\\frac{1}{h+4}$ 는 가까워지는 값은?","식":["$\\dfrac{f(1+2h)-f(1-2h)}{h(h+4)}=\\dfrac{f(1+2h)-f(1-2h)}{h}\\cdot\\dfrac{1}{h+4}$","$h\\to0$ 이면 $4f'(1)\\cdot\\dfrac14=f'(1)$"],"설명":"$\\frac{1}{h+4}$ 는 $\\frac14$ 로 가므로 앞 단계의 $4f'(1)$ 과 곱해 $f'(1)$ 이 남는다.","확인":null,"스킬":"D3"}]},"ns-3e87fcea4891":{"길":"보기마다 x=1 에서 좌우 식을 따로 써서 미분계수를 비교한다","단계":[{"제목":"ㄱ: (x-1)f(x) 의 좌우 미분계수","힌트":"$(x-1)|x-1|$ 을 $x\\ge1$ 과 $x<1$ 로 나눠 쓰면? $x=1$ 에서 미분계수는?","식":["$x\\ge1$: $(x-1)^{2}$, 도함수 $2(x-1)\\to0$","$x<1$: $-(x-1)^{2}$, 도함수 $-2(x-1)\\to0$","좌우 미분계수가 같아 미분가능 (ㄱ 포함)"],"설명":"$x=1$ 에서 값은 $0$ 으로 이어지고 두 식 모두 $x=1$ 에서 기울기가 $0$ 이다.","확인":"0","스킬":"C2"},{"제목":"ㄴ: f(x)g(x) 의 좌우 미분계수","힌트":"$x\\ge1$ 에서 $f(x)g(x)=(x-1)(2x-1)$ 이다. $x<1$ 의 식과 함께 $x=1$ 에서 미분계수는?","식":["$x\\ge1$: $(x-1)(2x-1)=2x^{2}-3x+1$, 도함수 $4x-3\\to1$","$x<1$: $(1-x)(-x)=x^{2}-x$, 도함수 $2x-1\\to1$","값이 $0$ 으로 이어지고 좌우 미분계수가 같아 미분가능 (ㄴ 포함)"],"설명":"$f(1)=0$ 이어서 $g$ 가 $x=1$ 에서 끊기지 않는 것과 상관없이 곱은 $0$ 으로 이어진다.","확인":"1","스킬":"C2"},{"제목":"ㄷ: 절댓값 안의 식을 구간별로 정리","고비":true,"힌트":"$f(x)-xg(x)+g(x)=|x-1|-(x-1)g(x)$ 이다. $x<1$ 과 $x\\ge1$ 에서 각각 어떻게 될까?","식":["$x<1$: $-(x-1)-(x-1)(-x)=(x-1)^{2}$","$x\\ge1$: $(x-1)-(x-1)(2x-1)=-2(x-1)^{2}$","$H(x)=\\left|f(x)-xg(x)+g(x)\\right|$ 는 $x<1$ 에서 $(x-1)^{2}$, $x\\ge1$ 에서 $2(x-1)^{2}$"],"설명":"두 구간 모두 $(x-1)^{2}$ 꼴이라 절댓값을 쉽게 벗길 수 있다.","확인":null,"스킬":"A1"},{"제목":"ㄷ: H(x) 의 좌우 미분계수","힌트":"$H(x)$ 의 두 식을 미분해 $x=1$ 을 넣으면 좌우 미분계수는?","식":["$x<1$: $H'(x)=2(x-1)\\to0$","$x\\ge1$: $H'(x)=4(x-1)\\to0$","$H(1)=0$ 으로 이어지고 좌우 미분계수가 같아 미분가능 (ㄷ 포함)"],"설명":"$(x-1)^{2}$ 의 배수는 $x=1$ 에서 기울기가 $0$ 이다.","확인":"0","스킬":"D1"},{"제목":"미분가능한 보기 가려내기","힌트":"세 보기의 미분가능 여부를 모으면?","식":["ㄱ, ㄴ, ㄷ 모두 $x=1$ 에서 미분가능","ㄱ, ㄴ, ㄷ"],"설명":"세 보기 모두 좌우 미분계수가 같다.","확인":null,"스킬":"C3"}]},"ns-3f2e2f8338d1":{"길":"연속이 아닌 선지를 먼저 걸러내고, 남은 선지는 좌우 미분계수를 비교한다","단계":[{"제목":"불연속인 ④, ⑤ 제외","힌트":"④ 에서 $x\\to0+$ 와 $x\\to0-$ 의 극한은 같을까? ⑤ 에서 $\\lim_{x\\to0}f(x)$ 와 $f(0)$ 은?","식":["④: $\\lim_{x\\to0+}f(x)=0,\\ \\lim_{x\\to0-}f(x)=-1$ 이므로 극한이 없어 불연속","⑤: $\\lim_{x\\to0}f(x)=0\\ne f(0)=1$ 이므로 불연속"],"설명":"미분가능하면 반드시 연속이므로 '연속이지만 미분 불가능' 의 후보는 ①②③ 이다.","확인":null,"스킬":"C2"},{"제목":"② 의 좌우 미분계수 비교","힌트":"$x|x|$ 를 $x\\ge0$ 과 $x<0$ 으로 나눠 쓰면? $x=0$ 에서 좌우 미분계수는?","식":["$x\\ge0$: $x|x|=x^{2}$, 도함수 $2x\\to0$","$x<0$: $x|x|=-x^{2}$, 도함수 $-2x\\to0$","좌우가 같아 미분가능, ①은 다항함수라 미분가능"],"설명":"두 식의 값이 $0$ 으로 이어지고 기울기도 $0$ 으로 같다.","확인":"0","스킬":"C2"},{"제목":"③ 의 우미분계수와 좌미분계수 비교","고비":true,"힌트":"$|x|+x$ 를 $x\\ge0$ 과 $x<0$ 으로 나눠 쓰면 $x=0$ 에서 우미분계수는?","식":["$x\\ge0$: $|x|+x=2x$, 우미분계수 $2$","$x<0$: $|x|+x=0$, 좌미분계수 $0$","값은 $0$ 으로 이어지지만 좌우가 달라 연속이면서 미분 불가능"],"설명":"$x=0$ 에서 그래프는 끊기지 않고 꺾인다.","확인":"2","스킬":"C2"},{"제목":"조건에 맞는 선지 고르기","힌트":"연속이지만 미분 불가능한 함수는 몇 번 선지의 함수일까?","식":["①② 미분가능, ③ 연속이면서 미분 불가능, ④⑤ 불연속","③ $f(x)=|x|+x$"],"설명":"조건을 만족하는 것은 ③ 하나뿐이다.","확인":null,"스킬":"C2"}]},"ns-41d1f5319e1b":{"길":"보기마다 x=0 에서 좌우 미분계수를 따져 f(0) 의 값과 상관없이 성립하는지 확인한다","단계":[{"제목":"ㄱ: |x|f(x) 의 좌우 미분계수","고비":true,"힌트":"$\\frac{|h|f(h)-0}{h}$ 의 $h\\to0+$ 와 $h\\to0-$ 극한은 각각 무엇일까? $f(0)=0$ 이 보장될까?","식":["$h\\to0+$: $\\dfrac{hf(h)}{h}=f(h)\\to f(0)$","$h\\to0-$: $\\dfrac{-hf(h)}{h}=-f(h)\\to-f(0)$","$f(0)\\ne0$ 이면 좌우가 달라 미분 불가능이므로 항상 미분가능하지는 않다 (ㄱ 제외)"],"설명":"$f(x)=|x|+1$ 은 $x=0$ 에서 연속이지만 미분 불가능하고 $f(0)=1$ 이어서 ㄱ 이 성립하지 않는 예이다.","확인":null,"스킬":"C3"},{"제목":"ㄴ: n≥2 일 때 x^n f(x) 의 미분계수","힌트":"$h(x)=x^{2}f(x)$ 이면 $\\frac{h(x)-h(0)}{x-0}=xf(x)$ 이다. $x\\to0$ 일 때 극한은?","식":["$h(0)=0$ 이므로 $\\dfrac{h(x)-h(0)}{x}=x^{n-1}f(x)$","$n\\ge2$: $x^{n-1}\\to0$ 이고 $f$ 는 $x=0$ 에서 연속이므로 극한 $0$","$n=1$: $\\lim_{x\\to0}f(x)=f(0)$ 이므로 극한이 존재하여 모든 자연수 $n$ 에서 미분가능 (ㄴ 포함)"],"설명":"$f$ 가 $x=0$ 에서 연속이므로 $f(x)$ 는 $f(0)$ 으로 가까워지고, $x^{n-1}$ 이 곱해지면 극한이 존재한다.","확인":"0","스킬":"D1"},{"제목":"ㄷ: 역수 꼴의 미분가능 확인","힌트":"$xf(x)-1$ 은 $x=0$ 에서 미분가능한가? 그 값이 $0$ 이 아니면 역수는?","식":["$xf(x)$ 는 ㄴ($n=1$)에서 $x=0$ 에서 미분가능하므로 $xf(x)-1$ 도 미분가능","$x=0$ 에서 $xf(x)-1=-1\\ne0$ 이므로 분모가 $0$ 이 아니다","미분가능하고 $0$ 이 아닌 함수의 역수는 미분가능하므로 ㄷ 포함"],"설명":"$\\frac{1}{u(x)}$ 은 $u$ 가 미분가능하고 $u(0)\\ne0$ 이면 $x=0$ 에서 미분가능하다.","확인":null,"스킬":"C3"},{"제목":"미분가능한 보기 가려내기","힌트":"세 보기 중 항상 미분가능한 것은?","식":["ㄱ 제외, ㄴ 포함, ㄷ 포함","ㄴ, ㄷ"],"설명":"ㄱ 만 $f(0)=0$ 일 때에만 성립한다.","확인":null,"스킬":"C3"}]},"ns-474af2b5f8dc":{"길":"다항함수와 x|x| 의 미분가능성을 확인하고 남은 함수의 좌우 미분계수를 비교한다","단계":[{"제목":"①②③ 과 ⑤ 의 미분가능성 확인","힌트":"$x|x|$ 를 $x\\ge0$ 과 $x<0$ 으로 나눠 쓰면 $x=0$ 에서 좌우 미분계수는?","식":["①②③ 은 다항함수라 실수 전체에서 미분가능","⑤ $x\\ge0$: $x^{2}$, $x<0$: $-x^{2}$ 이므로 좌우 미분계수가 모두 $0$ 으로 미분가능"],"설명":"연속이면서 미분 불가능한 후보는 ④ 만 남는다.","확인":"0","스킬":"C2"},{"제목":"④ 의 좌우 미분계수 비교","고비":true,"힌트":"$x+|x|$ 를 $x\\ge0$ 과 $x<0$ 으로 나눠 쓰면 $x=0$ 에서 우미분계수는?","식":["$x\\ge0$: $x+|x|=2x$, 우미분계수 $2$","$x<0$: $x+|x|=0$, 좌미분계수 $0$","값이 $0$ 으로 이어지지만 좌우가 달라 연속이면서 미분 불가능"],"설명":"두 직선 $y=2x$ 와 $y=0$ 이 $x=0$ 에서 만나 꺾인다.","확인":"2","스킬":"C2"},{"제목":"조건에 맞는 선지 고르기","힌트":"연속이지만 미분 불가능한 함수는 몇 번 선지일까?","식":["①②③⑤ 미분가능, ④ 연속이면서 미분 불가능","④ $f(x)=x+|x|$"],"설명":"조건을 만족하는 것은 ④ 하나뿐이다.","확인":null,"스킬":"C2"}]},"ns-49b0c510d4e8":{"길":"보기마다 x=2 에서 좌우 식을 따로 써서 곱의 미분계수를 구한다","단계":[{"제목":"ㄱ: f 의 불연속과 g 의 좌우 미분계수","힌트":"그림에서 $f$ 는 $x=2$ 에서 이어질까? $g(x)=|2x-4|$ 의 $x<2$ 에서의 식을 미분하면 좌미분계수는?","식":["$f(2^{-})=2\\ne f(2)=-2$ 이므로 $f$ 는 불연속이어서 미분 불가능","$g$: $x<2$ 에서 $-(2x-4)$ 이므로 좌미분계수 $-2$, $x>2$ 에서 우미분계수 $2$","좌우가 달라 $g$ 도 미분 불가능 (ㄱ 참)"],"설명":"미분가능하면 연속이어야 하므로 $f$ 는 미분 불가능이고, $g$ 는 $x=2$ 에서 꺾인다.","확인":"-2","스킬":"D1"},{"제목":"ㄴ: f(x)g(x) 의 좌우 미분계수","힌트":"$x<2$ 에서는 $f=x,\\ g=4-2x$, $x>2$ 에서는 $f=2x-6,\\ g=2x-4$ 이다. 곱을 미분해 $x=2$ 를 넣으면?","식":["$x<2$: $f(x)g(x)=4x-2x^{2}$, 도함수 $4-4x\\to-4$","$x>2$: $f(x)g(x)=(2x-6)(2x-4)$, 도함수 $8x-20\\to-4$","$f(2)g(2)=0$ 으로 이어지고 좌우 미분계수가 같아 미분가능 (ㄴ 거짓)"],"설명":"$g(2)=0$ 이어서 $f$ 가 끊겨도 곱은 $x=2$ 에서 $0$ 으로 이어지고 기울기도 맞는다.","확인":"-4","스킬":"C2"},{"제목":"ㄷ: |f(x)|g(x) 의 좌우 미분계수","고비":true,"힌트":"$x>2$ 근처에서 $2x-6<0$ 이므로 $|f(x)|=-(2x-6)$ 이다. 곱을 미분해 $x=2$ 를 넣으면 우미분계수는?","식":["$x<2$: $|f(x)|g(x)=x(4-2x)$, 도함수 $4-4x\\to-4$","$x>2$: $|f(x)|g(x)=(6-2x)(2x-4)$, 도함수 $20-8x\\to4$","$|f(2)|g(2)=0$ 이지만 좌우 미분계수 $-4\\ne4$ 이므로 미분 불가능 (ㄷ 참)"],"설명":"$f$ 의 부호가 $x=2$ 근처에서 오른쪽은 음수이므로 절댓값을 벗길 때 부호가 반대로 바뀌어 우미분계수가 달라진다.","확인":"4","스킬":"G5"},{"제목":"옳은 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 옳은 것은?","식":["ㄱ 참, ㄴ 거짓, ㄷ 참","옳은 것은 ㄱ, ㄷ"],"설명":"ㄴ 만 좌우 미분계수가 같아 거짓이다.","확인":null,"스킬":"C3"}]},"ns-4a0e5817444b":{"길":"(나)로 f(1)=0 을 읽어 삼차함수를 중근 꼴로 두고, f' 로 나누어떨어질 조건에서 근을 정한다","단계":[{"제목":"(나)에서 f(1) 의 값 읽기","힌트":"(나)에서 $f(x)=f'(x)(px+q)$ 로 쓸 수 있다. 양변에 $x=1$ 을 넣으면 $f(1)$ 은?","식":["$f(x)=f'(x)(px+q)$ 이므로 $f(1)=f'(1)(p+q)$","(가)에서 $f'(1)=0$ 이므로 $f(1)=0$"],"설명":"나누어떨어지면 몫이 일차식이므로 $f$ 는 $f'$ 의 배수이고 $f'(1)=0$ 이면 $f(1)$ 도 $0$ 이다.","확인":"0","스킬":"A4"},{"제목":"f 를 중근 꼴로 두고 f(0) 조건 쓰기","힌트":"$f(1)=0$ 이고 $f'(1)=0$ 이면 $x=1$ 은 $f$ 의 몇 중근일까? 삼차함수의 나머지 근을 $b$ 로 두면?","식":["$f(x)=a(x-1)^{2}(x-b)$","$f(0)=a\\cdot1\\cdot(-b)=-ab=-2$ 이므로 $ab=2$"],"설명":"$f(1)=f'(1)=0$ 은 $x=1$ 이 중근이라는 뜻이고 삼차이므로 근이 하나 더 있다.","확인":null,"스킬":"A4"},{"제목":"f' 로 나누어떨어질 조건에서 b 정하기","고비":true,"힌트":"$f'(x)=a(x-1)(3x-2b-1)$ 이다. $\\frac{f(x)}{f'(x)}$ 가 일차식이 되려면 $3x-2b-1$ 은 $f$ 의 어떤 일차 인수의 상수배여야 할까?","식":["$f'(x)=2a(x-1)(x-b)+a(x-1)^{2}=a(x-1)(3x-2b-1)$","$\\dfrac{f(x)}{f'(x)}=\\dfrac{(x-1)(x-b)}{3x-2b-1}$ 이므로 $3x-2b-1$ 이 $x-1$ 또는 $x-b$ 의 상수배","$3x-2b-1=3(x-1)$ 이면 $b=1$, $3x-2b-1=3(x-b)$ 이면 $b=1$"],"설명":"두 경우 모두 $b=1$ 로 같은 값이 나온다.","확인":"1","스킬":"A4"},{"제목":"a 를 구하고 f(2) 계산","힌트":"$ab=2$ 에 $b$ 를 넣어 $a$ 를 구하면 $f(x)$ 는? 그 식에 $x=2$ 를 넣으면?","식":["$ab=2,\\ b=1$ 에서 $a=2$","$f(x)=2(x-1)^{3}$","$f(2)=2\\cdot1^{3}=2$"],"설명":"$f(0)=2\\cdot(-1)^{3}=-2$ 로 (가)와 맞는다.","확인":"2","스킬":"A4"}]},"ns-4c89d38661c3":{"길":"x=y=1 로 f(1) 을 구하고 f(2+h)-f(2) 를 f(1+h/2) 로 바꿔 미분계수 꼴을 만든다","단계":[{"제목":"x=y=1 을 대입해 f(1) 구하기","힌트":"주어진 관계식에 $x=y=1$ 을 넣으면 $f(1)$ 은?","식":["$f(1)=f(1)+f(1)$","$f(1)=0$"],"설명":"양변에서 $f(1)$ 을 빼면 $f(1)=0$ 이다.","확인":"0","스킬":"C6"},{"제목":"f(2+h)-f(2) 를 f(1+h/2) 로 바꾸기","고비":true,"힌트":"$2+h=2\\left(1+\\frac{h}{2}\\right)$ 로 보고 관계식 $f(xy)=f(x)+f(y)$ 를 쓰면 $f(2+h)-f(2)$ 는?","식":["$f(2+h)=f\\left(2\\left(1+\\dfrac{h}{2}\\right)\\right)=f(2)+f\\left(1+\\dfrac{h}{2}\\right)$","$f(2+h)-f(2)=f\\left(1+\\dfrac{h}{2}\\right)=f\\left(1+\\dfrac{h}{2}\\right)-f(1)$"],"설명":"$f(1)=0$ 이므로 빼 주어도 값이 변하지 않고, 이렇게 하면 $f'(1)$ 의 정의 꼴이 나타난다.","확인":null,"스킬":"D3"},{"제목":"미분계수 꼴로 맞추어 극한 구하기","힌트":"분모를 $h$ 에서 $\\frac{h}{2}$ 로 맞추려면 앞에 곱해야 하는 수는?","식":["$f'(2)=\\lim_{h\\to0}\\dfrac{f\\left(1+\\frac{h}{2}\\right)-f(1)}{h}=\\dfrac12\\lim_{h\\to0}\\dfrac{f\\left(1+\\frac{h}{2}\\right)-f(1)}{\\frac{h}{2}}$","$\\frac{h}{2}=s$ 로 두면 $s\\to0$ 이고 극한은 $f'(1)=a$"],"설명":"분모를 $h=2\\cdot\\frac{h}{2}$ 로 쓰면 $\\frac12$ 이 앞으로 나온다.","확인":"1/2","스킬":"D3"},{"제목":"f'(2) 의 값 확정","힌트":"앞 단계의 곱해 둔 수와 극한값을 곱하면 $f'(2)$ 는?","식":["$f'(2)=\\dfrac12\\cdot a=\\dfrac{a}{2}$"],"설명":"$f$ 는 로그함수와 같은 성질이라 $f'(x)=\\frac{a}{x}$ 이다.","확인":null,"스킬":"D3"}]},"ns-4f3fbe6a6738":{"길":"g 가 꺾인 직선이라 x=1, 2, 3 의 값만 비교해 t 의 범위별로 최대·최소를 가린다","단계":[{"제목":"(1) x=1, 2, 3 에서 g 의 값","힌트":"$g(x)=f(x)-tx$ 에 $x=1,\\ 2,\\ 3$ 을 넣고 $f(1),\\ f(2),\\ f(3)$ 은 정의에서 읽으면?","식":["$g(1)=f(1)-t=1-t$","$g(2)=f(2)-2t=1-2t$","$g(3)=f(3)-3t=2-3t$"],"설명":"$f(1)=1,\\ f(2)=2-1=1,\\ f(3)=3-1=2$ 이다.","확인":null,"스킬":"C2"},{"제목":"최대·최소가 되는 위치 좁히기","힌트":"$g$ 는 $1\\le x<2$ 와 $2\\le x\\le3$ 에서 각각 직선이다. 직선의 최대·최소는 어디에서 생길까?","식":["$1\\le x<2$ 에서 $g=1-tx$, $2\\le x\\le3$ 에서 $g=(1-t)x-1$ 이고 $x=2$ 에서 이어진다","각 구간이 직선이므로 최댓값·최솟값은 $x=1,\\ 2,\\ 3$ 의 값 $1-t,\\ 1-2t,\\ 2-3t$ 중에 있다"],"설명":"직선은 양 끝점에서 최대·최소를 가지므로 꺾이는 점과 양 끝점의 값만 비교하면 된다.","확인":null,"스킬":"G7"},{"제목":"(2)(3) t≤0 과 t≥1 에서의 h(t)","힌트":"$t\\le0$ 일 때 세 값 $1-t,\\ 1-2t,\\ 2-3t$ 의 크기 순서는? $t\\ge1$ 이면 순서는 어떻게 바뀔까?","식":["$t\\le0$: $1-t\\le1-2t\\le2-3t$ 이므로 $h(t)=(2-3t)-(1-t)=1-2t$","$t\\ge1$: $1-t\\ge1-2t\\ge2-3t$ 이므로 $h(t)=(1-t)-(2-3t)=2t-1$"],"설명":"서로 이웃한 값의 차 $(1-2t)-(1-t)=-t$ 와 $(2-3t)-(1-2t)=1-t$ 의 부호로 순서가 정해진다.","확인":null,"스킬":"C2"},{"제목":"0<t<1 에서 h(t) 를 둘로 나누기","고비":true,"힌트":"$0<t<1$ 에서는 세 값 중 어느 것이 가장 작을까? 가장 큰 값은 $t$ 가 $\\frac12$ 보다 작을 때와 클 때 어느 것일까?","식":["$0<t<1$: 최솟값은 $1-2t$","$(2-3t)-(1-t)=1-2t$ 이므로 $0<t\\le\\frac12$ 이면 최댓값 $2-3t$, $h(t)=(2-3t)-(1-2t)=1-t$","$\\frac12<t<1$ 이면 최댓값 $1-t$, $h(t)=(1-t)-(1-2t)=t$"],"설명":"$2-3t$ 와 $1-t$ 의 크기가 $t=\\frac12$ 에서 바뀐다.","확인":null,"스킬":"C2"},{"제목":"(4) 미분 불가능한 점의 개수","힌트":"구간별 $h(t)$ 의 기울기가 바뀌는 점마다 좌우 기울기를 비교하면 미분 불가능한 점은 몇 개일까?","식":["$h(t)=1-2t\\ (t\\le0),\\ 1-t\\ (0<t\\le\\frac12),\\ t\\ (\\frac12<t<1),\\ 2t-1\\ (t\\ge1)$","$t=0$ 에서 기울기 $-2,\\ -1$, $t=\\frac12$ 에서 $-1,\\ 1$, $t=1$ 에서 $1,\\ 2$","세 점 모두 좌우 미분계수가 달라 미분 불가능한 점은 $3$ 개"],"설명":"세 점 모두 $h$ 의 값은 이어지지만 기울기가 달라 꺾인다.","확인":"3","스킬":"G5"},{"제목":"(5) h(t) 의 최솟값","힌트":"$h$ 는 어느 구간에서 감소하고 어느 구간에서 증가할까? 방향이 바뀌는 점의 값은?","식":["$t\\le\\frac12$ 에서 기울기가 $-2,\\ -1$ 로 $h$ 는 감소","$t\\ge\\frac12$ 에서 기울기가 $1,\\ 2$ 로 $h$ 는 증가","$t=\\frac12$ 에서 최소이고 $h\\left(\\frac12\\right)=1-\\frac12=\\frac12$"],"설명":"그래프가 $t=\\frac12$ 에서 내려오다 올라가는 꼴이다.","확인":"1/2","스킬":"G7"}]},"ns-54a07dd3644e":{"길":"g 가 꺾이거나 끊기는 점마다 h 가 0 이어야 곱이 미분가능해지는 조건을 모아 k 별로 h 를 정한다","단계":[{"제목":"x=3 에서 h(3) 의 조건","힌트":"$x=3$ 근처에서 $g(x)=|2x-6|$ 이다. $gh$ 의 좌미분계수와 우미분계수를 같게 놓으면 $h(3)$ 은?","식":["$g(3)=0,\\ g'(3^{-})=-2,\\ g'(3^{+})=2$","$gh$ 의 좌미분계수 $g'(3^{-})h(3)+g(3)h'(3)=-2h(3)$, 우미분계수 $2h(3)$","$-2h(3)=2h(3)$ 에서 $h(3)=0$"],"설명":"$g(3)=0$ 이어서 곱의 미분에서 $h'(3)$ 항이 사라지고 $h(3)$ 만 남는다.","확인":"0","스킬":"D1"},{"제목":"g 가 x=0 에서 연속일 조건과 k 의 후보","힌트":"$x<0$ 에서 $g(x)=\\frac32|2x+2k-6|$ 이다. $x\\to0-$ 의 극한과 $g(0)$ 을 같게 놓으면?","식":["$g(0)=|{-6}|=6,\\ \\lim_{x\\to0-}g(x)=\\dfrac32|2k-6|$","연속이면 $\\dfrac32|2k-6|=6$ 에서 $|k-3|=2$","$k=1$ 또는 $k=5$"],"설명":"$k>0$ 이므로 두 값 모두 후보가 된다.","확인":null,"스킬":"C2"},{"제목":"g 가 x=0 에서 불연속인 경우의 모순","고비":true,"힌트":"$k\\ne1,\\ 5$ 이면 $g$ 는 $x=0$ 에서 끊긴다. $gh$ 가 연속이고 미분가능하려면 $h(0)$ 과 $h'(0)$ 은 어떤 값이어야 할까?","식":["$gh$ 가 $x=0$ 에서 연속이려면 $h(0)=0$, 미분가능하려면 $h'(0)=0$","$h$ 는 $x^{2}$ 과 $x-3$ 을 인수로 갖는 최고차항 $1$ 인 삼차식이므로 $h(x)=x^{2}(x-3)$","$h'(x)=3x^{2}-6x$ 에서 $h'(3)=9\\ne15$ 이므로 (나)에 모순"],"설명":"$k>3$ 이면 $x=3-k<0$ 에서도 $g$ 가 꺾여 $h$ 가 인수를 하나 더 가져야 하므로 삼차식이 될 수 없다. 따라서 $k=1,\\ 5$ 만 남는다.","확인":"9","스킬":"C2"},{"제목":"k=1 일 때 h 를 정하고 h(1) 구하기","힌트":"$k=1$ 이면 $x<0$ 에서 $g(x)=\\frac32(4-2x)$ 이다. $x=0$ 의 좌우 미분계수를 비교해 $h(0)$ 을 구하고 $h$ 를 쓰면 $h(1)$ 은?","식":["$g'(0^{-})=-3,\\ g'(0^{+})=-2,\\ g(0)=6$ 이므로 $-3h(0)+6h'(0)=-2h(0)+6h'(0)$ 에서 $h(0)=0$","$h(x)=x(x-3)(x+\\alpha)$ 이고 $h'(3)=3(3+\\alpha)=15$ 에서 $\\alpha=2$","$h(1)=1\\cdot(-2)\\cdot3=-6$"],"설명":"$h(0)=h(3)=0$ 이고 최고차항이 $1$ 인 삼차식이므로 나머지 근을 $-\\alpha$ 로 둘 수 있다.","확인":"-6","스킬":"A4"},{"제목":"k=5 일 때 h 를 정하고 h(5) 구하기","힌트":"$k=5$ 이면 $x<0$ 에서 $g(x)=\\frac32|2x+4|$ 가 $x=-2$ 에서 꺾인다. $h$ 의 근을 모으면 $h(5)$ 는?","식":["$x=-2$ 에서 $g$ 가 꺾이므로 $h(-2)=0$","$g'(0^{-})=3,\\ g'(0^{+})=-2$ 이므로 $3h(0)=-2h(0)$ 에서 $h(0)=0$","$h(x)=x(x-3)(x+2)$ 이고 $h'(3)=15$ 를 만족하며 $h(5)=5\\cdot2\\cdot7=70$"],"설명":"근 $-2,\\ 0,\\ 3$ 을 가진 최고차항 $1$ 인 삼차식은 하나뿐이어서 $k=1$ 일 때와 같은 $h$ 이다.","확인":"70","스킬":"A4"},{"제목":"k 와 h(k) 의 값 정리","힌트":"$k=1$ 일 때와 $k=5$ 일 때의 $h(k)$ 를 짝지으면?","식":["$k=1$ 일 때 $h(1)=-6$, $k=5$ 일 때 $h(5)=70$","⑴ $k=1,\\ 5$ ⑵ $h(k)=-6,\\ 70$"],"설명":"$k$ 값이 둘이므로 $h(k)$ 의 값도 둘이다.","확인":null,"스킬":"C2"}]},"ns-57221ef87f0a":{"길":"대칭과 연속으로 b 를 정하고, 꺾일 수 있는 점 x=0,1,2 의 미분가능 조건에서 a 를 정한다","단계":[{"제목":"대칭과 연속으로 b 구하기","힌트":"(나)에 $x=0$ 을 넣으면 $f(2)$ 는 $f(0)$ 과 같다. $f(2)$ 를 둘째 식으로 쓰면 $b$ 는?","식":["$f(0)=-2$ 이고 (나)에서 $f(2)=f(0)=-2$","$f(2)=4+2b+10=-2$ 에서 $b=-8$"],"설명":"첫째 식에서 $f(0)=0+0-2=-2$ 이다.","확인":"-8","스킬":"T2"},{"제목":"x=1 에서 좌우 미분계수","힌트":"(나)에서 $f'(x)=-f'(2-x)$ 이다. $x=1$ 에서 좌미분계수 $3+a$ 와 우미분계수의 관계는?","식":["(나)로 그래프는 $x=1$ 대칭이고 $x=0,\\ 1,\\ 2$ 이외에서는 다항식이라 미분가능","$f'(1^{-})=3\\cdot1^{2}+a=3+a$, $f'(1^{+})=-(3+a)$","$x=1$ 에서 미분가능 $\\iff a=-3$"],"설명":"대칭인 그래프는 $x=1$ 의 좌우 기울기가 부호만 반대이다.","확인":null,"스킬":"T2"},{"제목":"x=2 의 우미분계수와 x=0, 2 의 미분가능 조건","고비":true,"힌트":"$x\\ge2$ 의 식 $x^{2}-8x+10$ 에서 $f'(2^{+})$ 는? 대칭을 이용하면 $f'(2^{-})$ 는 $a$ 로 어떻게 표현될까?","식":["$f'(2^{+})=2\\cdot2-8=-4$","대칭이라 $f'(2^{-})=-f'(0^{+})=-a$, $f'(0^{-})=-f'(2^{+})=4$","$x=2$ 에서 $-a=-4$, $x=0$ 에서 $a=4$ 이므로 둘 다 $a=4$ 일 때만 미분가능"],"설명":"$x=0$ 과 $x=2$ 는 $x=1$ 에 대해 대칭이어서 미분가능성이 함께 정해진다.","확인":"-4","스킬":"T2"},{"제목":"한 점에서만 미분 불가능하도록 a 정하기","힌트":"$a=-3$ 일 때와 $a=4$ 일 때 미분 불가능한 점이 각각 몇 개일까?","식":["$a=-3$ 이면 $x=0,\\ 2$ 두 점에서 미분 불가능이라 (다)에 모순","$a=4$ 이면 $f'(1^{-})=7,\\ f'(1^{+})=-7$ 로 $x=1$ 에서만 미분 불가능","$a=4$"],"설명":"$x=0,\\ 1,\\ 2$ 중 미분 불가능한 점이 정확히 하나가 되는 경우만 택한다.","확인":"4","스킬":"C2"},{"제목":"f'(0)-f(-2) 계산","힌트":"$f'(0)$ 은 $0\\le x\\le1$ 의 식에서, $f(-2)$ 는 (나)로 $f(4)$ 로 바꿔 구하면?","식":["$f'(0)=3\\cdot0^{2}+4=4$","$f(-2)=f(4)=16-32+10=-6$","$f'(0)-f(-2)=4-(-6)=10$"],"설명":"(나)에서 $f(-2)=f(2-(-2))=f(4)$ 이다.","확인":"10","스킬":"T2"}]},"ns-595f4cdc4a9b":{"길":"그래프에서 만나는 점은 같은 거리, 순간변화율은 접선 기울기, 평균변화율은 원점과 잇는 직선 기울기로 읽는다","단계":[{"제목":"ㄱ: x=3 에서 두 그래프의 위치","힌트":"세로축이 달린 거리이다. $x=3$ 에서 두 그래프가 만난다면 두 자동차의 거리는?","식":["$x=3$ 에서 두 그래프가 만나므로 세로 좌표가 같다","출발 후 $3$ 시간 동안 달린 거리가 같다 (ㄱ 참)"],"설명":"그래프의 높이가 곧 그 시각까지 달린 거리이다.","확인":null,"스킬":"G9"},{"제목":"ㄴ: x=2 에서 접선의 기울기 비교","고비":true,"힌트":"순간변화율은 접선의 기울기이다. $x=2$ 에서 A 와 B 중 그래프가 더 가파르게 올라가는 쪽은?","식":["$x=2$ 에서 A 는 위로 볼록해 올라가는 폭이 완만하다","B 는 $x=2$ 근처에서 가파르게 올라가 접선의 기울기가 더 크다","순간변화율이 더 큰 자동차는 B 이므로 ㄴ 거짓"],"설명":"A 는 일찍 달리다 속도가 줄고 B 는 늦게 속도를 올려 $x=3$ 에서 따라잡는다.","확인":null,"스킬":"D1"},{"제목":"ㄷ: 4시간 평균변화율 비교","힌트":"평균변화율은 $\\frac{y(4)-y(0)}{4-0}$ 이고 $y(0)=0$ 이다. $x=4$ 에서 더 높은 그래프는?","식":["평균변화율 $=\\dfrac{y(4)-y(0)}{4-0}=\\dfrac{y(4)}{4}$","$x=4$ 에서 B 의 거리가 A 보다 크므로 B 의 평균변화율이 더 크다 (ㄷ 참)"],"설명":"원점과 $x=4$ 의 점을 잇는 직선의 기울기가 더 큰 쪽이 B 이다.","확인":null,"스킬":"G9"},{"제목":"옳은 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 옳은 것은?","식":["ㄱ 참, ㄴ 거짓, ㄷ 참","옳은 것은 ㄱ, ㄷ"],"설명":"ㄴ 만 접선의 기울기가 반대로 비교되어 거짓이다.","확인":null,"스킬":"C3"}]},"ns-59ae6975e12f":{"길":"ㄱ 은 미분가능이면 연속임을 쓰고, ㄴ ㄷ 은 간단한 함수로 반례를 넣는다","단계":[{"제목":"ㄱ: 미분계수가 존재하면 연속","힌트":"$\\lim_{h\\to0}\\frac{f(1+h)-f(1)}{h}$ 이 존재한다는 것은 $f$ 가 $x=1$ 에서 무엇이라는 뜻일까?","식":["극한이 $0$ 으로 존재하므로 $f$ 는 $x=1$ 에서 미분가능","미분가능하면 연속이므로 $f(1)=\\lim_{x\\to1}f(x)$ (ㄱ 참)"],"설명":"이 극한은 미분계수의 정의 그대로이다.","확인":null,"스킬":"C3"},{"제목":"ㄴ: f(x)=x² 으로 반례 확인","힌트":"$f(x)=x^{2}$ 이면 $\\lim_{x\\to1}f(x)$ 는 존재한다. $\\frac{f(1+h)-f(1-h)}{h}$ 를 계산하면?","식":["$f(1+h)-f(1-h)=(1+h)^{2}-(1-h)^{2}=4h$","$\\dfrac{4h}{h}=4\\ne0$ 이므로 ㄴ 거짓"],"설명":"연속인 함수라도 이 극한은 $2f'(1)$ 이 되어 $0$ 이 아닐 수 있다.","확인":"4","스킬":"C3"},{"제목":"ㄷ: 불연속 함수로 반례 찾기","고비":true,"힌트":"$f(a+h)+f(a-h)-2f(a)$ 가 항상 $0$ 이 되는 함수 중 $x=a$ 에서 미분가능하지 않은 것은 무엇일까?","식":["$f(x)=1\\ (x>a),\\ 0\\ (x=a),\\ -1\\ (x<a)$ 이면 $f(a+h)+f(a-h)-2f(a)=1+(-1)-0=0$","주어진 극한은 $0$ 이지만 $f$ 는 $x=a$ 에서 불연속이므로 미분 불가능 (ㄷ 거짓)"],"설명":"분자는 $x=a$ 의 좌우 값이 서로 상쇄되기만 하면 $0$ 이어서 미분가능함을 보장하지 못한다.","확인":null,"스킬":"C3"},{"제목":"항상 옳은 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 항상 옳은 것은?","식":["ㄱ 참, ㄴ 거짓, ㄷ 거짓","항상 옳은 것은 ㄱ"],"설명":"ㄱ 만 모든 함수에서 성립한다.","확인":null,"스킬":"C3"}]},"ns-59e93a7be384":{"길":"연속·미분 조건을 식으로 쓰고 g 의 차수를 정한 뒤 g(1) 의 범위에서 k 를 좁힌다","단계":[{"제목":"x=0, 3 에서 연속·미분가능 조건","힌트":"$x=0$ 과 $x=3$ 에서 좌우의 함숫값과 미분계수가 같아야 한다. $g$ 에 대한 조건 네 개를 쓰면?","식":["연속: $g(0)=2\\cdot0+2=2,\\ \\ g(3)=k\\cdot0+2=2$","미분가능: $g'(0)=2,\\ \\ g'(3)=k$"],"설명":"$x\\le0$ 의 식 $2x+2$ 와 $x\\ge3$ 의 식 $k(x-3)+2$ 의 값과 기울기를 $g$ 가 이어받는다.","확인":null,"스킬":"A3"},{"제목":"g 의 가장 낮은 차수 정하기","고비":true,"힌트":"$g(0)=2,\\ g'(0)=2,\\ g(3)=2$ 를 만족하는 이차식 $g$ 를 구해 $g(1)$ 을 범위와 비교하면 $g(1)$ 은?","식":["일차식이면 $g(x)=2x+2$ 이고 $g(3)=8\\ne2$ 이므로 불가능","이차식이면 $g(x)=bx^{2}+2x+2$ 에서 $g(3)=9b+8=2$, $b=-\\frac23$, $g(1)=\\frac{10}{3}$","$\\frac{10}{3}$ 은 $\\frac{16}{9}<g(1)<\\frac{20}{9}$ 를 벗어나므로 $g$ 는 삼차식"],"설명":"범위 조건이 이차식을 배제하므로 가장 낮은 차수는 $3$ 이다.","확인":"10/3","스킬":"C1"},{"제목":"삼차식의 계수 정리","힌트":"$g(x)=ax^{3}+bx^{2}+cx+d$ 로 두고 $g(0),\\ g'(0),\\ g(3)$ 의 조건에서 $b$ 를 $a$ 로 나타내면?","식":["$g(0)=2$ 에서 $d=2$, $g'(0)=2$ 에서 $c=2$","$g(3)=27a+9b+8=2$ 에서 $b=-3a-\\frac23$"],"설명":"미지수 $a,\\ b,\\ c,\\ d$ 중 $c,\\ d,\\ b$ 가 정해지고 $a$ 만 남는다.","확인":null,"스킬":"A3"},{"제목":"g(1) 의 범위로 a 의 범위 구하기","힌트":"$g(1)=a+b+c+d$ 에 $b,\\ c,\\ d$ 를 넣어 $a$ 로 나타내고 부등식에 넣으면?","식":["$g(1)=a+b+2+2=a-3a-\\frac23+4=-2a+\\frac{10}{3}$","$\\frac{16}{9}<-2a+\\frac{10}{3}<\\frac{20}{9}$ 에서 $\\frac59<a<\\frac79$"],"설명":"음수를 곱하거나 이항할 때 부등호 방향이 바뀌지 않도록 차례로 정리한다.","확인":null,"스킬":"C1"},{"제목":"k 의 범위와 자연수 k","힌트":"$k=g'(3)$ 을 $a$ 로 나타내고 $a$ 의 범위를 넣으면 $k$ 의 범위는?","식":["$k=g'(3)=27a+6b+2=27a-18a-4+2=9a-2$","$5<9a<7$ 에서 $3<k<5$","자연수 $k=4$"],"설명":"$g'(x)=3ax^{2}+2bx+2$ 에 $x=3$ 을 넣은 값이다.","확인":"4","스킬":"C1"}]},"ns-5a08ca885e4e":{"길":"절댓값 안의 값이 h² 의 부호로 정해지는 첫 극한과 분자가 0 이 되는 둘째 극한을 따로 구해 더한다","단계":[{"제목":"첫째 극한: h² 의 부호로 절댓값 벗기기","힌트":"$f(1)=0$ 이고 $f(1+h^{2})=|h^{2}|$ 이다. $h^{2}$ 의 부호는 항상 어떨까?","식":["$f(1)=0,\\ f(1+h^{2})=|h^{2}|=h^{2}$","$\\dfrac{h^{2}-0}{h^{2}}=1$ 이므로 첫째 극한은 $1$"],"설명":"$h\\ne0$ 이면 $h^{2}>0$ 이므로 절댓값을 그대로 벗길 수 있다.","확인":"1","스킬":"D3"},{"제목":"둘째 극한: 분자가 0 이 되는 식","고비":true,"힌트":"$f(1+h)=|h|$ 와 $f(1-h)=|-h|$ 는 서로 어떤 관계일까? 분자는?","식":["$f(1+h)=|h|,\\ f(1-h)=|-h|=|h|$","분자 $f(1+h)-f(1-h)=0$ 이므로 둘째 극한은 $0$"],"설명":"$f$ 가 $x=1$ 에 대해 좌우 대칭이어서 두 값이 같다.","확인":"0","스킬":"D3"},{"제목":"두 극한의 합","힌트":"첫째 극한과 둘째 극한을 더하면?","식":["$1+0=1$"],"설명":"각 극한이 모두 존재하므로 합은 극한값의 합이다.","확인":"1","스킬":"D3"}]},"ns-6000235e2405":{"길":"f 의 그래프에서 |f-t| 가 뾰족해지는 점을 t 의 범위별로 세어 a, b 를 구한다","단계":[{"제목":"f 의 그래프 개형과 x=1 의 꺾임","힌트":"$-2<x<1$ 에서는 직선, $1\\le x<3$ 에서는 포물선이다. $x=1$ 에서 우미분계수는?","식":["$-2<x<1$: 직선 $y=x$, $1\\le x<3$: 꼭짓점 $(2,\\,-1)$ 인 아래로 볼록한 포물선","$f(1)=2\\cdot1-1=1$ 로 이어지고 좌미분계수 $1$","우미분계수 $4(1-2)=-4$ 이므로 $x=1$ 에서 꺾인다"],"설명":"$x\\to3-$ 일 때 $f\\to1$ 이지만 $x=3$ 은 정의역에 없고, $x\\to-2+$ 일 때 $f\\to-2$ 이다.","확인":"-4","스킬":"G5"},{"제목":"|f-t| 가 미분 불가능한 점의 종류","고비":true,"힌트":"$|f(x)-t|$ 는 $y=f(x)$ 에서 $y=t$ 아래 부분을 위로 접은 그래프이다. 어떤 점이 뾰족해질까?","식":["$f(k)=t$ 이고 $f'(k)\\ne0$ 인 점 $x=k$ 에서 접혀 뾰족해진다","$f$ 가 꺾이는 $x=1$ 은 $f-t$ 의 부호가 양쪽에서 같으면 절댓값을 취해도 꺾임이 남는다","꼭짓점 $x=2$ 에서 $f(2)=t$ 가 아니면 접힘이 없다"],"설명":"접힌 점은 그래프가 $y=t$ 를 비스듬히 가로지르는 곳이다.","확인":null,"스킬":"G5"},{"제목":"(나) -1<t<1 일 때 a","힌트":"$y=t$ 와 $y=f(x)$ 가 만나는 점은 직선 부분과 포물선 부분에서 각각 몇 개일까? 여기에 $x=1$ 을 더하면?","식":["직선 $y=x$ 부분에서 $1$ 번, 포물선의 $1<x<2$ 와 $2<x<3$ 에서 각각 $1$ 번으로 교점 $3$ 개","교점에서 $f'\\ne0$ 이어서 모두 뾰족해지고 $x=2$ 에서는 $f(2)=-1<t$ 라 접힘이 없다","$x=1$ 을 더해 $a=4$"],"설명":"$-1<t<1$ 이면 직선 $y=t$ 는 포물선의 꼭짓점 위, 점 $(1,\\,1)$ 아래를 지난다.","확인":"4","스킬":"C2"},{"제목":"(다) t≥1 일 때 b","힌트":"$t\\ge1$ 이면 $f(x)=t$ 가 되는 점이 있을까? $x=1$ 에서는?","식":["$-2<x<3$ 에서 $f(x)\\le1\\le t$ 이고 $f(x)=t$ 인 점은 $t=1,\\ x=1$ 뿐","$x=1$ 에서는 $f-t$ 가 양쪽에서 $0$ 이하여서 절댓값을 취해도 꺾임이 남는다","$x=1$ 하나만 미분 불가능하므로 $b=1$"],"설명":"그래프 전체가 직선 $y=t$ 아래에 있어 접히는 부분이 없다.","확인":"1","스킬":"C2"},{"제목":"2a+b 계산","힌트":"$a=4,\\ b=1$ 을 $2a+b$ 에 넣으면?","식":["$2a+b=2\\cdot4+1=9$"],"설명":"구한 두 개수를 그대로 대입한다.","확인":"9","스킬":"C2"}]},"ns-6229f220c3c6":{"길":"분자가 0 이 되는 조건으로 f(3)g(3) 을 얻고 h=fg 로 묶어 미분계수의 정의 꼴로 바꾼다","단계":[{"제목":"극한이 수렴하는 조건으로 f(3)g(3) 구하기","힌트":"$x\\to3$ 에서 분모 $x^{3}-27$ 은 $0$ 으로 간다. 극한이 존재하려면 분자는 어떻게 되어야 할까?","식":["$x\\to3$ 일 때 분모가 $0$ 이고 극한이 존재하므로 분자도 $0$ 으로 간다","$3-f(3)g(3)=0$ 이므로 $f(3)g(3)=3$"],"설명":"$f,\\ g$ 가 미분가능해 연속이므로 분자의 극한은 $3-f(3)g(3)$ 이다.","확인":null,"스킬":"D3"},{"제목":"h=fg 로 묶어 h'(3) 구하기","고비":true,"힌트":"$h(x)=f(x)g(x)$ 이면 $h(3)=3$ 이다. $x^{3}-27$ 을 인수분해해 $\\frac{h(x)-h(3)}{x-3}$ 꼴을 만들면 $h'(3)$ 은?","식":["$x^{3}-27=(x-3)(x^{2}+3x+9)$","$\\dfrac{3-h(x)}{x^{3}-27}=-\\dfrac{h(x)-h(3)}{x-3}\\cdot\\dfrac{1}{x^{2}+3x+9}\\to-h'(3)\\cdot\\dfrac{1}{27}$","$-\\dfrac{h'(3)}{27}=-1$ 에서 $h'(3)=27$"],"설명":"$x\\to3$ 일 때 $x^{2}+3x+9\\to27$ 이다.","확인":"27","스킬":"D3"},{"제목":"구하는 식을 h'(3)/h(3) 으로 바꿔 계산","힌트":"$\\frac{f'}{f}+\\frac{g'}{g}$ 를 통분하면 분자는 $(fg)'$ 와 같다. 값은?","식":["$\\dfrac{f'(3)}{f(3)}+\\dfrac{g'(3)}{g(3)}=\\dfrac{f'(3)g(3)+f(3)g'(3)}{f(3)g(3)}=\\dfrac{h'(3)}{h(3)}$","$\\dfrac{27}{3}=9$"],"설명":"곱의 미분법에서 $h'=f'g+fg'$ 이다.","확인":"9","스킬":"D1"}]},"ns-64834982e8bd":{"길":"(가)로 f-g 를 인수 꼴로 쓰고 (나)로 남는 이차식의 판별식 조건을 얻어, f'(0)=2 와 묶어 a 의 범위에서 최솟값을 구한다","단계":[{"제목":"(가)에서 f-g 의 꼴 쓰기","힌트":"$f-g$ 는 최고차항의 계수가 $1$ 인 사차식이고 $x=2$ 에서 $x$ 축에 접한다. 인수를 어떻게 쓸까?","식":["$x=2$ 에서 접하므로 $(x-2)^{2}$ 을 인수로 갖는다","$f(x)-g(x)=(x-2)^{2}(x^{2}+ax+b)$"],"설명":"접한다는 것은 $x=2$ 가 중근이라는 뜻이고, 남는 인수는 최고차항이 $1$ 인 이차식이다.","확인":null,"스킬":"G5"},{"제목":"(나)에서 이차식의 판별식 조건 얻기","고비":true,"힌트":"$x^{2}+ax+b$ 가 서로 다른 두 실근을 가지면 그중 하나는 $2$ 가 아니다. 그 근에서 $|f-g|$ 는 어떻게 될까?","식":["서로 다른 두 실근이 있으면 $2$ 가 아닌 근에서 $f-g$ 의 부호가 바뀌어 $|f-g|$ 가 꺾인다","따라서 $x^{2}+ax+b$ 는 서로 다른 두 실근을 갖지 않는다","$D=a^{2}-4b\\le0$"],"설명":"판별식이 $0$ 이하이면 이차식이 항상 $0$ 이상이어서 $|f-g|=f-g$ 이다.","확인":null,"스킬":"G5"},{"제목":"f'(0)=2 로 a, b 의 관계 구하기","힌트":"$f(x)=(x-2)^{2}(x^{2}+ax+b)+2x^{2}-x-4$ 를 미분해 $x=0$ 을 넣으면?","식":["$f'(x)=2(x-2)(x^{2}+ax+b)+(x-2)^{2}(2x+a)+4x-1$","$f'(0)=-4b+4a-1=2$","$b=a-\\frac34$"],"설명":"$f'(0)$ 에서 $x=0$ 을 넣으면 $(x-2)=-2,\\ (x-2)^{2}=4$ 이다.","확인":null,"스킬":"C1"},{"제목":"판별식 조건으로 a 의 범위 구하기","힌트":"$b=a-\\frac34$ 를 $a^{2}-4b\\le0$ 에 넣고 인수분해하면 $a$ 의 범위는?","식":["$a^{2}-4\\left(a-\\frac34\\right)=a^{2}-4a+3\\le0$","$(a-1)(a-3)\\le0$ 에서 $1\\le a\\le3$"],"설명":"아래로 볼록한 이차식이 $0$ 이하이려면 두 근 사이에 있어야 한다.","확인":null,"스킬":"C1"},{"제목":"f(1) 의 최솟값과 4p","힌트":"$f(1)$ 을 $a$ 로 나타내면 $a$ 에 대한 일차식이다. 범위의 어느 끝에서 최소가 될까?","식":["$f(1)=1\\cdot(1+a+b)+2-1-4=a+b-2=2a-\\frac{11}{4}$","$a=1$ 일 때 최소이고 $p=2-\\frac{11}{4}=-\\frac34$","$4p=-3$"],"설명":"$a$ 의 계수가 양수이므로 $a$ 가 가장 작은 $1$ 에서 $f(1)$ 이 최소이다.","확인":"-3","스킬":"C1"}]},"ns-64bcdf15deca":{"길":"연속·미분 조건을 식으로 쓰고 이차식을 배제한 뒤 삼차식의 계수와 k 를 g(1) 의 범위로 좁힌다","단계":[{"제목":"x=0, 2 에서 연속·미분가능 조건","힌트":"$x=0$ 과 $x=2$ 에서 좌우의 함숫값과 미분계수가 같다. $g$ 에 대한 조건을 쓰면?","식":["연속: $g(0)=0+1=1,\\ \\ g(2)=k\\cdot0+1=1$","미분가능: $g'(0)=1,\\ \\ g'(2)=k$"],"설명":"$x\\le0$ 의 식 $x+1$ 과 $x\\ge2$ 의 식 $k(x-2)+1$ 의 값과 기울기를 $g$ 가 이어받는다.","확인":null,"스킬":"A3"},{"제목":"이차식 g 의 g(1) 확인","고비":true,"힌트":"$g(0)=1,\\ g'(0)=1$ 인 이차식은 $g(x)=ax^{2}+x+1$ 이다. $g(2)=1$ 로 $a$ 를 구하면 $g(1)$ 은?","식":["$g(2)=4a+2+1=1$ 에서 $a=-\\frac12$","$g(1)=-\\frac12+1+1=\\frac32$","$\\frac32$ 은 $\\frac14<g(1)<\\frac34$ 를 벗어나므로 $g$ 는 삼차식"],"설명":"일차식은 $g(x)=x+1$ 뿐이고 $g(2)=3\\ne1$ 이어서 이미 불가능하다.","확인":"3/2","스킬":"C1"},{"제목":"삼차식의 계수와 k 를 a 로 나타내기","힌트":"$g(x)=ax^{3}+bx^{2}+x+1$ 로 두고 $g(2)=1$ 에서 $b$ 를, $g'(2)=k$ 에서 $k$ 를 $a$ 로 나타내면?","식":["$g(2)=8a+4b+3=1$ 에서 $b=-2a-\\frac12$","$g'(x)=3ax^{2}+2bx+1$ 이므로 $k=g'(2)=12a+4b+1=4a-1$"],"설명":"$g(0)=1,\\ g'(0)=1$ 은 상수항 $1$ 과 일차항 계수 $1$ 로 이미 반영했다.","확인":null,"스킬":"A3"},{"제목":"g(1) 의 범위로 a 와 자연수 k 정하기","힌트":"$g(1)=a+b+2$ 를 $a$ 로 나타내 부등식에 넣으면 $a$ 의 범위는? 그때 $k=4a-1$ 의 범위는?","식":["$g(1)=a+b+2=-a+\\frac32$","$\\frac14<-a+\\frac32<\\frac34$ 에서 $\\frac34<a<\\frac54$","$2<k=4a-1<4$ 에서 자연수 $k=3$, $a=1$"],"설명":"$k=4a-1=3$ 이면 $a=1$ 이고 범위 안에 있다.","확인":"3","스킬":"C1"},{"제목":"2차항의 계수 m 과 km","힌트":"$b=-2a-\\frac12$ 에 $a=1$ 을 넣으면 $g$ 의 2차항의 계수 $m$ 은? $km$ 은?","식":["$m=b=-2\\cdot1-\\frac12=-\\frac52$","$km=3\\cdot\\left(-\\frac52\\right)=-\\frac{15}{2}$"],"설명":"$g(x)=x^{3}-\\frac52x^{2}+x+1$ 이다.","확인":"-15/2","스킬":"A3"}]},"ns-66793ce1b4a2":{"길":"나누어떨어지는 조건을 함숫값과 미분계수 조건으로 바꾸고 f' 의 두 근으로 f 의 꼴을 정해 정수 a 를 구한다","단계":[{"제목":"(나)(다)에서 얻는 함숫값·미분계수 조건","힌트":"$f(x)+2$ 가 $(x-a)^{2}$ 으로 나누어떨어진다는 것은 $x=a$ 에서 $f(x)+2$ 의 값과 미분계수가 어떻다는 뜻일까?","식":["(나): $f(x)+2$ 가 $x=a$ 에서 중근이므로 $f(a)=-2,\\ f'(a)=0$","(다): $f(x)-2$ 가 $x=-a$ 에서 중근이므로 $f(-a)=2,\\ f'(-a)=0$"],"설명":"$(x-a)^{2}$ 으로 나누어떨어지면 그 점에서 값이 $0$ 이고 접한다.","확인":null,"스킬":"A4"},{"제목":"f' 를 정하고 f 의 꼴 쓰기","고비":true,"힌트":"$a=0$ 이면 어떤 모순이 생길까? $a\\ne0$ 이면 $f'$ 는 어떤 두 근을 가진 이차식일까?","식":["$a=0$ 이면 $f(0)=-2$ 와 $f(0)=2$ 가 동시에 성립해 모순이므로 $a\\ne0$","$f'(a)=f'(-a)=0$ 이고 $f'$ 는 이차식이므로 $f'(x)=3k(x^{2}-a^{2})$","$f(x)=kx^{3}-3ka^{2}x+c$"],"설명":"삼차식의 도함수는 이차식이고 서로 다른 두 근 $\\pm a$ 를 가지면 이 꼴이 된다.","확인":null,"스킬":"D1"},{"제목":"상수항 c 와 ka³ 구하기","힌트":"$f(a)=-2$ 와 $f(-a)=2$ 를 더하고 빼면 $c$ 와 $ka^{3}$ 은?","식":["$f(a)=-2ka^{3}+c=-2,\\ \\ f(-a)=2ka^{3}+c=2$","두 식을 더하면 $c=0$, 빼면 $ka^{3}=1$"],"설명":"$f$ 는 원점 대칭인 꼴 $kx^{3}-3ka^{2}x$ 에 상수 $c$ 가 더해진 것이다.","확인":"0","스킬":"A3"},{"제목":"f(1)=2 로 정수 a 구하기","힌트":"$k=\\frac{1}{a^{3}}$ 을 $f(1)=k(1-3a^{2})=2$ 에 넣고 정리해 정수근을 찾으면?","식":["$\\dfrac{1-3a^{2}}{a^{3}}=2$ 에서 $2a^{3}+3a^{2}-1=0$","$(a+1)^{2}(2a-1)=0$","$a$ 가 정수이므로 $a=-1,\\ k=-1$"],"설명":"$a=\\frac12$ 은 정수가 아니어서 제외한다.","확인":"-1","스킬":"A4"},{"제목":"f(2) 계산","힌트":"$f(x)=kx^{3}-3ka^{2}x$ 에 $k=-1,\\ a=-1$ 을 넣어 $x=2$ 를 대입하면?","식":["$f(x)=-x^{3}+3x$","$f(2)=-8+6=-2$"],"설명":"$f(1)=-1+3=2$ 로 (가)와 맞는다.","확인":"-2","스킬":"A4"}]},"ns-68da5cfc26db":{"길":"보기마다 구간별 식을 따로 보고 좌극한과 도함수의 극한을 구해 참 거짓을 가린다","단계":[{"제목":"ㄱ: x=0 에서 좌미분계수","힌트":"$x\\le0$ 에서 $f(x)=x^{3}-3x$ 이다. $f(0)$ 은? $h<0$ 일 때 $\\frac{f(h)-f(0)}{h}$ 를 정리하면?","식":["$f(0)=0$","$h<0$: $\\dfrac{f(h)-f(0)}{h}=\\dfrac{h^{3}-3h}{h}=h^{2}-3$","$h\\to0-$ 이면 $h^{2}-3\\to-3$ (ㄱ 참)"],"설명":"그래프에서 $x=0$ 의 값은 $0$ 이고 왼쪽 식으로 계산한다.","확인":"0","스킬":"D1"},{"제목":"ㄴ: x→0 일 때 f'(x) 의 극한","힌트":"$x<0$ 과 $0<x<1$ 에서 각각 $f'(x)$ 를 구하면? 상수 $2$ 를 미분하면?","식":["$x<0$: $f'(x)=3x^{2}-3$","$0<x<1$: $f'(x)=3x^{2}-3$ (상수 $2$ 는 미분하면 사라진다)","$x\\to0$ 에서 좌우 극한이 모두 $-3$ 이므로 ㄴ 참"],"설명":"$x=0$ 에서 $f$ 는 끊기지만 양쪽 도함수의 극한은 같다.","확인":null,"스킬":"D1"},{"제목":"ㄷ: x→1- 일 때 f'(x) 가 가까워지는 값과 방향","고비":true,"힌트":"$0<x<1$ 에서 $f'(x)=3x^{2}-3$ 이다. $x\\to1-$ 일 때 가까워지는 값은? 그 값의 왼쪽일까 오른쪽일까?","식":["$f'(x)=3x^{2}-3=3(x-1)(x+1)$","$x\\to1-$ 이면 $f'(x)\\to0$","$0<x<1$ 에서 $f'(x)<0$ 이므로 $0$ 의 왼쪽에서 가까워진다"],"설명":"$u=f'(x)$ 로 두면 $x\\to1-$ 일 때 $u\\to0-$ 이다.","확인":"0","스킬":"T6"},{"제목":"ㄷ: 바깥 함수 f 의 좌극한","힌트":"$u\\to0-$ 일 때 $f(u)$ 는 $u<0$ 의 식 $u^{3}-3u$ 를 쓴다. 가까워지는 값은?","식":["$\\lim_{x\\to1-}f(f'(x))=\\lim_{u\\to0-}f(u)$","$u<0$ 에서 $f(u)=u^{3}-3u\\to0$ 이므로 ㄷ 참"],"설명":"$f$ 는 $x=0$ 에서 불연속이어서 왼쪽에서 가까워지는지 오른쪽인지 구분해야 한다.","확인":null,"스킬":"T6"},{"제목":"옳은 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 옳은 것은?","식":["ㄱ 참, ㄴ 참, ㄷ 참","옳은 것은 ㄱ, ㄴ, ㄷ"],"설명":"세 보기 모두 성립한다.","확인":null,"스킬":"C3"}]},"ns-691e80843802":{"길":"특수한 값 대입으로 f(1), f(-1) 을 얻고, y→0 극한으로 차수를 정해 이차식의 계수를 구한다","단계":[{"제목":"두 번의 대입으로 f(1), f(-1) 구하기","힌트":"$x=1,\\ y=1$ 을 넣으면 좌변이 $0$ 이 된다. $f(1)$ 은? 이어서 $x=0,\\ y=1$ 을 넣으면 $f(-1)$ 은?","식":["$x=1,\\ y=1$: $0=4\\{f(1)+g(1)\\}$ 이므로 $f(1)=-g(1)=-2$","$x=0,\\ y=1$: $-\\{f(1)-f(-1)\\}=4\\{f(0)+g(1)\\}=12$","$f(-1)=f(1)+12=10$"],"설명":"$x-1=0$ 이 되는 값을 넣으면 $f$ 만 남는다.","확인":"-2","스킬":"A3"},{"제목":"y→0 극한으로 f 의 차수 정하기","고비":true,"힌트":"$y=h$ 로 두고 양변을 $h$ 로 나눈 뒤 $h\\to0$ 을 취하면 좌변은 $f'(x)$ 의 몇 배일까? 최고차항을 비교하면 차수는?","식":["$(x-1)\\dfrac{f(x+h)-f(x-h)}{h}=4\\{f(x)+g(h)\\}$ 에서 $h\\to0$ 이면 $2(x-1)f'(x)=4\\{f(x)+g(0)\\}$","$f$ 의 최고차항을 $ax^{n}$ 으로 두면 좌변 최고차항의 계수는 $2an$, 우변은 $4a$","$2an=4a$ 에서 $n=2$"],"설명":"$\\frac{f(x+h)-f(x-h)}{h}$ 는 $2f'(x)$ 로 간다.","확인":"2","스킬":"D3"},{"제목":"이차식 f 의 계수 구하기","힌트":"$f(x)=ax^{2}+bx+1$ 에 $f(1)=-2$ 와 $f(-1)=10$ 을 넣으면 $a$ 는?","식":["$f(1)=a+b+1=-2$ 에서 $a+b=-3$","$f(-1)=a-b+1=10$ 에서 $a-b=9$","$a=3,\\ b=-6$"],"설명":"$f(0)=1$ 이므로 상수항이 $1$ 이다.","확인":"3","스킬":"A3"},{"제목":"f(3) 계산","힌트":"$f(x)=3x^{2}-6x+1$ 에 $x=3$ 을 넣으면?","식":["$f(3)=27-18+1=10$"],"설명":"구한 이차식에 그대로 대입한다.","확인":"10","스킬":"A3"}]},"ns-6cd3e86ac6b2":{"길":"보기마다 x=3 근처의 구간별 식으로 연속·좌우 미분계수를 따지고, 곱의 꺾임이 남는 조건을 확인한다","단계":[{"제목":"ㄱ: x=3 에서 f|g| 의 연속","힌트":"$x\\to3$ 에서 $f(x)$ 는 어떤 값으로 가까워지고 $|g(x)|$ 는 좌우에서 어떤 값에 가까워질까?","식":["$f(3)=|9-9|=0$ 이므로 $x\\to3$ 에서 $f(x)\\to0$","$|g(x)|$ 는 좌우 모두 일정한 값에 가까워지므로 곱의 극한은 $0$","$\\lim_{x\\to3}f(x)|g(x)|=0=f(3)|g(3)|$ 이므로 연속 (ㄱ 참)"],"설명":"$g$ 는 $x=3$ 에서 값이 뛰지만 $f(3)=0$ 이어서 곱은 $0$ 으로 이어진다.","확인":null,"스킬":"C2"},{"제목":"ㄴ: x=3 에서 f g 의 좌우 미분계수","힌트":"$x>3$ 에서는 $f=x^{2}-3x,\\ g=2x-9$ 이고 $0<x<3$ 에서는 $f=-(x^{2}-3x),\\ g=x$ 이다. $\\frac{F(x)-F(3)}{x-3}$ 의 좌우 극한은?","식":["$F=fg$ 로 두면 $F(3)=0$","$x>3$: $\\dfrac{(x^{2}-3x)(2x-9)}{x-3}=x(2x-9)\\to-9$","$0<x<3$: $\\dfrac{-(x^{2}-3x)x}{x-3}=-x^{2}\\to-9$ 이므로 좌우가 같아 미분가능 (ㄴ 참)"],"설명":"$f(x)=|x||x-3|$ 의 인수 $x-3$ 이 약분되어 극한이 존재한다.","확인":"-9","스킬":"C2"},{"제목":"ㄷ: (x-t)f(x) 의 꺾임이 남는 점","고비":true,"힌트":"$f$ 가 꺾이는 점은 $x=0,\\ 3$ 이다. 곱 $(x-t)f(x)$ 에서 인수 $x-t$ 가 그 점에서 $0$ 이 아니면 꺾임은 어떻게 될까?","식":["$f(x)=|x||x-3|$ 은 $x=0,\\ 3$ 에서 좌우 미분계수가 달라 꺾인다","$f(0)=f(3)=0$ 이므로 곱의 좌우 미분계수는 $(x-t)f'(x)$ 의 좌우 값이고 $x-t\\ne0$ 이면 서로 달라 꺾임이 남는다","$t<0$ 이면 $x=0$ 에서 $-t\\ne0$, $x=3$ 에서 $3-t\\ne0$ 이므로 미분 불가능한 점은 $0,\\ 3$ 두 개 (ㄷ 참)"],"설명":"$t=0$ 또는 $t=3$ 일 때만 인수 $x-t$ 가 꺾임을 지워 준다.","확인":null,"스킬":"G5"},{"제목":"옳은 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 옳은 것은?","식":["ㄱ 참, ㄴ 참, ㄷ 참","옳은 것은 ㄱ, ㄴ, ㄷ"],"설명":"세 보기 모두 성립한다.","확인":null,"스킬":"C3"}]},"ns-6d104c89d4dc":{"길":"x=1 대입으로 f(1) 을 구하고 식을 f'(x) 로 풀어 f' 의 연속성을 이용해 f'(1) 에 대한 방정식을 세운다","단계":[{"제목":"x=1 을 대입해 f(1) 구하기","힌트":"주어진 식에 $x=1$ 을 넣으면 $(x-1)f'(x)$ 항은 어떻게 될까? $f(1)$ 은?","식":["$0\\cdot f'(1)+f(1)-1+1=0$","$f(1)=0$"],"설명":"$x-1=0$ 이므로 $f'(1)$ 이 사라지고 $f(1)$ 만 남는다.","확인":"0","스킬":"D3"},{"제목":"f'(x) 를 풀어 f'(1) 을 극한으로 나타내기","힌트":"$x\\ne1$ 일 때 식을 $f'(x)=\\cdots$ 로 풀면? $f'$ 가 연속이므로 $f'(1)$ 은 어떻게 쓸까?","식":["$x\\ne1$: $f'(x)=\\dfrac{x^{2}-1-f(x^{2})}{x-1}$","$f'$ 가 연속이므로 $f'(1)=\\lim_{x\\to1}\\dfrac{x^{2}-1-f(x^{2})}{x-1}$"],"설명":"연속이면 극한값이 그 점의 값과 같다.","확인":null,"스킬":"D3"},{"제목":"극한을 두 부분으로 나누어 미분계수 꼴 만들기","고비":true,"힌트":"$f(1)=0$ 을 이용해 분자를 $(x^{2}-1)$ 부분과 $f(x^{2})-f(1)$ 부분으로 나눈 뒤, 둘째 부분에 $\\frac{x^{2}-1}{x^{2}-1}$ 을 곱하면?","식":["$\\dfrac{x^{2}-1-f(x^{2})}{x-1}=(x+1)-\\dfrac{f(x^{2})-f(1)}{x-1}$","$\\dfrac{f(x^{2})-f(1)}{x-1}=\\dfrac{f(x^{2})-f(1)}{x^{2}-1}\\cdot(x+1)$","$x\\to1$ 이면 첫째는 $2$, 둘째는 $f'(1)\\cdot2$ 로 가까워진다"],"설명":"$x^{2}\\to1$ 이므로 $\\frac{f(x^{2})-f(1)}{x^{2}-1}$ 은 $f'(1)$ 로 간다.","확인":null,"스킬":"D3"},{"제목":"f'(1) 에 대한 방정식 풀기","힌트":"$f'(1)=2-2f'(1)$ 을 $f'(1)$ 에 대해 풀면?","식":["$f'(1)=2-2f'(1)$","$3f'(1)=2$ 에서 $f'(1)=\\dfrac23$"],"설명":"양변에 $f'(1)$ 이 나타나므로 이항해 정리한다.","확인":"2/3","스킬":"D3"}]},"ns-6e3987a5af3f":{"길":"ㄱ 은 분모가 0 이 되는 극한에서 분자의 값을 읽고, ㄴ ㄷ 은 절댓값 함수로 반례나 값을 확인한다","단계":[{"제목":"ㄱ: 분모가 0 으로 갈 때 f(3) 읽기","힌트":"$\\lim_{h\\to0}\\frac{f(3-h)}{h}=1$ 에서 분모가 $0$ 으로 가려면 분자 $f(3-h)$ 는 어떤 값으로 가야 할까? $f$ 가 연속일 때 $f(3)$ 은?","식":["분모 $h\\to0$ 이고 극한이 존재하므로 $f(3-h)\\to0$","$f$ 가 연속이므로 $f(3)=0$"],"설명":"극한이 유한한 값이려면 분자도 $0$ 으로 가야 한다.","확인":"0","스킬":"D3"},{"제목":"ㄱ: 부호를 맞춰 f'(3) 구하기","고비":true,"힌트":"$f(3)=0$ 이므로 분자는 $f(3-h)-f(3)$ 이다. 분모를 $-h$ 로 맞추려면 앞에 곱해야 하는 수는?","식":["$\\dfrac{f(3-h)-f(3)}{h}=-\\dfrac{f(3+(-h))-f(3)}{-h}$","$h\\to0$ 이면 $-f'(3)=1$","$f'(3)=-1$ 이므로 ㄱ 참"],"설명":"$h$ 대신 $-h$ 가 증분이므로 분모와 부호가 반대이다.","확인":null,"스킬":"D3"},{"제목":"ㄴ: f(x)=|x| 로 반례 확인","힌트":"$f(x)=|x|$ 이면 $f(h)-f(-h)$ 는 얼마일까? $x=0$ 에서 $f'(0)$ 은 존재할까?","식":["$f(h)-f(-h)=|h|-|-h|=0$ 이므로 $\\lim_{h\\to0}\\dfrac{f(h)-f(-h)}{2h}=0$","그러나 $|x|$ 는 $x=0$ 에서 미분 불가능이므로 $f'(0)=0$ 이 아니다 (ㄴ 거짓)"],"설명":"분자가 $f(h)-f(-h)$ 이면 좌우 값이 상쇄되어 미분가능성을 보장하지 못한다.","확인":null,"스킬":"C3"},{"제목":"ㄷ: h<0 에서 절댓값 벗겨 극한 구하기","힌트":"$f(1+h)=|h|,\\ f(1-2h)=|-2h|$ 이다. $h<0$ 일 때 각각 $h$ 로 어떻게 쓸까? 극한은?","식":["$h<0$: $f(1+h)=|h|=-h,\\ f(1-2h)=|-2h|=-2h$","$\\dfrac{-h-(-2h)}{3h}=\\dfrac{h}{3h}=\\dfrac13$","$\\dfrac13\\ne-1$ 이므로 ㄷ 거짓"],"설명":"$h<0$ 이면 $-2h>0$ 이므로 $|-2h|=-2h$ 이다.","확인":"1/3","스킬":"D3"},{"제목":"옳은 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 옳은 것은?","식":["ㄱ 참, ㄴ 거짓, ㄷ 거짓","옳은 것은 ㄱ"],"설명":"ㄱ 만 성립한다.","확인":null,"스킬":"C3"}]},"ns-715dea44699b":{"길":"f 와 이동한 g 가 꺾이는 점마다 상대 함수의 값이 0 이어야 곱이 미분가능해진다는 조건에서 a, b 를 구한다","단계":[{"제목":"f 와 g 의 꺾이는 점","힌트":"$f$ 는 $x=1$ 의 좌우에서 기울기가 어떻게 다를까? $g(x)=f(x-a)+b$ 는 $f$ 를 어떻게 옮긴 것일까?","식":["$f(1)=2$ 로 이어지고 기울기는 $-2,\\ -\\frac12$ 이므로 $f$ 는 $x=1$ 에서만 꺾인다","$g(x)=f(x-a)+b$ 는 $f$ 를 오른쪽으로 $a$, 위로 $b$ 옮긴 것이어서 $x=1+a$ 에서만 꺾인다","$a>0$ 이므로 두 점 $x=1,\\ 1+a$ 는 서로 다르다"],"설명":"$g$ 는 $x=1$ 에서 미분가능하고 $f$ 는 $x=1+a$ 에서 미분가능하다.","확인":null,"스킬":"C2"},{"제목":"곱이 꺾이지 않을 조건 세우기","고비":true,"힌트":"$h=fg$ 의 $x=1$ 에서 좌우 미분계수의 차는 $f'(1^{-})-f'(1^{+})$ 에 어떤 값을 곱한 것일까?","식":["$h'(1^{\\mp})=f'(1^{\\mp})g(1)+f(1)g'(1)$ 이므로 차는 $\\{f'(1^{-})-f'(1^{+})\\}g(1)$","$f'(1^{-})\\ne f'(1^{+})$ 이므로 $g(1)=0$","같은 이유로 $x=1+a$ 에서는 $f(1+a)=0$"],"설명":"꺾이지 않는 쪽 함수의 미분계수 항은 좌우가 같아 차에서 사라진다.","확인":null,"스킬":"C2"},{"제목":"f(1+a)=0 으로 a 구하기","힌트":"$x<1$ 과 $x\\ge1$ 에서 각각 $f(x)=0$ 을 풀면? 범위 안에 드는 해는?","식":["$x<1$: $-2x+4=0$ 에서 $x=2$ 는 범위 밖","$x\\ge1$: $-\\frac12x+\\frac52=0$ 에서 $x=5$","$1+a=5$ 이므로 $a=4$"],"설명":"$f(x)=0$ 인 점은 $x=5$ 하나뿐이다.","확인":"4","스킬":"C2"},{"제목":"g(1)=0 으로 b 구하기","힌트":"$g(1)=f(1-4)+b$ 이다. $f(-3)$ 은 $x<1$ 의 식으로 구하면? $b$ 는?","식":["$g(1)=f(-3)+b=0$","$f(-3)=-2\\cdot(-3)+4=10$","$b=-10$"],"설명":"$-3<1$ 이므로 $x<1$ 의 식을 쓴다.","확인":"-10","스킬":"C2"},{"제목":"a²+b² 계산","힌트":"$a=4,\\ b=-10$ 을 $a^{2}+b^{2}$ 에 넣으면?","식":["$a^{2}+b^{2}=16+100=116$"],"설명":"제곱하면 $b$ 의 부호는 상관없다.","확인":"116","스킬":"C2"}]},"ns-73a47ca77b59":{"길":"분자에 f(1) 을 더하고 빼 (h+1)³-1 부분과 f 의 증분 부분으로 나누어 각각 극한을 구한다","단계":[{"제목":"분자를 두 부분으로 나누기","힌트":"분자 $(h+1)^{3}f(1)-f\\{(h+1)^{3}\\}$ 에 $f(1)$ 을 더하고 빼면 어떤 두 식의 차가 될까?","식":["$(h+1)^{3}f(1)-f\\{(h+1)^{3}\\}=f(1)\\{(h+1)^{3}-1\\}-\\left[f\\{(h+1)^{3}\\}-f(1)\\right]$","극한은 $\\lim_{h\\to0}\\dfrac{f(1)\\{(h+1)^{3}-1\\}}{h}-\\lim_{h\\to0}\\dfrac{f\\{(h+1)^{3}\\}-f(1)}{h}$"],"설명":"$(h+1)^{3}\\to1$ 이므로 두 번째 부분이 $f$ 의 미분계수 꼴로 바뀐다.","확인":null,"스킬":"D3"},{"제목":"첫째 극한 구하기","힌트":"$(h+1)^{3}-1=h\\{(h+1)^{2}+(h+1)+1\\}$ 이다. $h\\to0$ 일 때 $\\frac{(h+1)^{3}-1}{h}$ 는 가까워지는 값은? $f(1)=6$ 을 곱하면?","식":["$\\dfrac{(h+1)^{3}-1}{h}=(h+1)^{2}+(h+1)+1\\to3$","$f(1)\\cdot3=6\\cdot3=18$"],"설명":"$(h+1)^{3}-1$ 은 $a^{3}-1=(a-1)(a^{2}+a+1)$ 로 인수분해된다.","확인":"18","스킬":"D3"},{"제목":"둘째 극한을 f'(1) 의 배수로 나타내기","고비":true,"힌트":"$u=(h+1)^{3}$ 으로 두면 $u\\to1$ 이다. $\\frac{f(u)-f(1)}{u-1}\\cdot\\frac{u-1}{h}$ 로 나누면 극한은?","식":["$\\dfrac{f\\{(h+1)^{3}\\}-f(1)}{h}=\\dfrac{f(u)-f(1)}{u-1}\\cdot\\dfrac{(h+1)^{3}-1}{h}$","$h\\to0$ 이면 $f'(1)\\cdot3$","$3f'(1)=3\\cdot5=15$"],"설명":"$u\\to1$ 일 때 $\\frac{f(u)-f(1)}{u-1}$ 은 $f'(1)$ 이고 $\\frac{(h+1)^{3}-1}{h}$ 는 $3$ 이다.","확인":"15","스킬":"D3"},{"제목":"두 극한의 차 계산","힌트":"첫째 극한에서 둘째 극한을 빼면?","식":["$18-15=3$"],"설명":"구하는 극한은 $3f(1)-3f'(1)$ 이다.","확인":"3","스킬":"D3"}]},"ns-7457d4829536":{"길":"f'(0) 을 읽어 두고 보기마다 반례나 f(x)/x 를 곱한 극한 꼴로 따진다","단계":[{"제목":"조건에서 f 의 미분계수 읽기","힌트":"$f(0)=0$ 이므로 $\\frac{f(x)}{x}$ 는 $\\frac{f(x)-f(0)}{x-0}$ 와 같다. 이 극한은 무엇일까?","식":["$\\dfrac{f(x)}{x}=\\dfrac{f(x)-f(0)}{x-0}$ 이므로 $f'(0)$ 이 존재한다","$f'(0)=\\lim_{x\\to0}\\dfrac{f(x)}{x}=1\\ne0$"],"설명":"$\\frac{f(x)}{x}$ 가 $0$ 이 아닌 값으로 가까워지므로 나눗셈에 쓸 수 있다.","확인":null,"스킬":"C3"},{"제목":"ㄱ: g 가 불연속인 반례","힌트":"$f(x)g(x)$ 의 극한이 $f(0)g(0)=0$ 이 되도록 하면서 $g$ 는 $x=0$ 에서 끊기게 하려면 $g(0)$ 과 $\\lim g(x)$ 를 어떻게 잡을까?","식":["$g(0)=1,\\ g(x)=2\\ (x\\ne0)$ 이면 $\\lim_{x\\to0}f(x)g(x)=0\\cdot2=0=f(0)g(0)$","$\\lim_{x\\to0}g(x)=2\\ne g(0)=1$ 이므로 $g$ 는 불연속 (ㄱ 거짓)"],"설명":"$f(x)\\to0$ 이면 $g$ 가 유한한 값에 가까워지기만 해도 곱의 극한은 $0$ 이 된다.","확인":null,"스킬":"C3"},{"제목":"ㄴ: f g 의 미분계수에서 g 의 극한 읽기","고비":true,"힌트":"$f(0)=0$ 이면 $\\frac{f(x)g(x)-f(0)g(0)}{x}$ 는 $\\frac{f(x)}{x}g(x)$ 와 같다. $\\frac{f(x)}{x}\\to1$ 일 때 $g(x)$ 는?","식":["$f(x)g(x)$ 가 미분가능하면 $\\lim_{x\\to0}\\dfrac{f(x)g(x)}{x}=\\lim_{x\\to0}\\dfrac{f(x)}{x}g(x)$ 가 존재한다","$\\dfrac{f(x)}{x}\\to1\\ne0$ 이므로 $g(x)=\\dfrac{\\frac{f(x)}{x}g(x)}{\\frac{f(x)}{x}}$ 의 극한도 존재한다 (ㄴ 참)"],"설명":"존재하는 극한을 $0$ 이 아닌 값으로 가는 함수로 나누어도 극한이 존재한다.","확인":null,"스킬":"D3"},{"제목":"ㄷ: f=x, g=|x| 반례 확인","힌트":"$f(x)=x,\\ g(x)=|x|$ 는 조건을 만족한다. $f(x)g(x)=x|x|$ 의 $x=0$ 에서 좌우 미분계수는?","식":["$x\\ge0$: $x|x|=x^{2}$, $x<0$: $x|x|=-x^{2}$ 이므로 좌우 미분계수가 모두 $0$ 으로 $fg$ 는 미분가능","$g(x)=|x|$ 는 $x=0$ 에서 미분 불가능 (ㄷ 거짓)"],"설명":"$f(0)=0$ 이고 $\\lim\\frac{f(x)}{x}=1$ 도 성립하는 반례이다.","확인":"0","스킬":"C3"},{"제목":"옳은 보기 가려내기","힌트":"세 보기의 참 거짓을 모으면 옳은 것은?","식":["ㄱ 거짓, ㄴ 참, ㄷ 거짓","옳은 것은 ㄴ"],"설명":"ㄴ 만 성립한다.","확인":null,"스킬":"C3"}]},"ns-750a04c5fafb":{"길":"f(x)−x 의 근을 이용해 삼차식 꼴로 세운다","단계":[{"제목":"f(x) 의 차수 정하기","힌트":"$f(x)$ 의 차수가 $n$ 일 때 분자 $f(x)-x^{2}f\\,'(x)$ 의 차수는 얼마일까?","식":["$f(x)$ 가 $n$ 차이면 $x^{2}f\\,'(x)$ 는 $n+1$ 차","분자의 차수 $n+1=4$","$n=3$"],"설명":"분모가 $4$ 차이고 극한이 $0$ 이 아닌 실수이므로 분자도 $4$ 차여야 한다. $x^{2}f\\,'(x)$ 는 $f(x)$ 보다 차수가 $1$ 높아 분자의 차수를 정한다.","확인":"3","스킬":"A11"},{"제목":"조건 (나) 에서 함숫값과 미분계수 읽기","힌트":"극한이 존재하려면 분모가 $0$ 이 되는 $x=m$ 에서 분자는 얼마여야 할까?","식":["$f(1)=1,\\ f(2)=2,\\ f(3)=3$","$f\\,'(1)=5,\\ f\\,'(2)=-1,\\ f\\,'(3)=5$"],"설명":"$x\\to m$ 일 때 분모가 $0$ 으로 가는데 극한이 있으므로 분자도 $0$ 으로 가서 $f(m)=m$ 이다. 이때 극한값이 $f\\,'(m)$ 이므로 $6(m-2)^{2}-1$ 에 $m=1,\\ 2,\\ 3$ 을 넣는다.","확인":null,"스킬":"D11"},{"제목":"f(x)−x 를 인수분해 꼴로 쓰고 미분하기","고비":true,"힌트":"$f(x)-x$ 는 삼차식이고 $x=1,\\ 2,\\ 3$ 에서 $0$ 이다. 어떤 꼴로 쓸 수 있을까?","식":["$f(x)-x=a(x-1)(x-2)(x-3)$","$f\\,'(x)=a(x-2)(x-3)+a(x-1)(x-3)+a(x-1)(x-2)+1$"],"설명":"삼차식 $f(x)-x$ 가 $x=1,\\ 2,\\ 3$ 에서 $0$ 이므로 인수정리에 의해 세 일차식의 곱에 상수 $a$ 를 곱한 꼴이다. 곱의 미분법으로 $f\\,'(x)$ 를 구한다.","확인":null,"스킬":"A4"},{"제목":"미분계수 조건으로 a 구하기","힌트":"$x=1$ 을 $f\\,'(x)$ 에 대입하면 $a$ 에 대한 식은 어떻게 될까?","식":["$f\\,'(1)=a(-1)(-2)+1=2a+1$","$2a+1=5$","$a=2$"],"설명":"$x=1$ 을 대입하면 $(x-1)$ 이 들어 있는 두 항은 $0$ 이 되고 한 항만 남는다. 이 값을 $f\\,'(1)=5$ 와 같게 놓는다.","확인":"2","스킬":"D1"},{"제목":"f(4) 계산하기","힌트":"$f(x)=2(x-1)(x-2)(x-3)+x$ 에 $x=4$ 를 넣으면?","식":["$f(4)=2\\times3\\times2\\times1+4$","$f(4)=16$"],"설명":"구한 $a=2$ 를 $f(x)=a(x-1)(x-2)(x-3)+x$ 에 넣고 $x=4$ 를 대입한다.","확인":"16","스킬":"A4"}]},"ns-9b787ac71cfa":{"길":"거리 조건을 (a−1)² 으로 나눠 미분계수의 제곱 꼴로 만든다","단계":[{"제목":"거리 조건을 식으로 쓰기","힌트":"두 점 사이 거리의 제곱을 좌표의 차로 쓰면?","식":["$(a-1)^{2}+\\left(f(a)-f(1)\\right)^{2}=(a^{2}-1)^{2}$"],"설명":"두 점의 $x$ 좌표의 차는 $a-1$, $y$ 좌표의 차는 $f(a)-f(1)$ 이다. 거리가 $a^{2}-1$ 이므로 양변을 제곱한 식을 세운다.","확인":null,"스킬":"C7"},{"제목":"f(a)−f(1) 의 제곱만 남기고 인수분해하기","힌트":"$(a^{2}-1)^{2}-(a-1)^{2}$ 을 공통인수로 묶으면?","식":["$\\left(f(a)-f(1)\\right)^{2}=(a-1)^{2}(a+1)^{2}-(a-1)^{2}$","$=(a-1)^{2}\\left[(a+1)^{2}-1\\right]$","$=a(a+2)(a-1)^{2}$"],"설명":"$a^{2}-1=(a-1)(a+1)$ 이므로 두 항에 $(a-1)^{2}$ 이 공통으로 들어 있다. 묶고 남은 $(a+1)^{2}-1$ 은 $a(a+2)$ 로 인수분해된다.","확인":null,"스킬":"A1"},{"제목":"평균변화율의 제곱 꼴로 만들기","고비":true,"힌트":"양변을 $(a-1)^{2}$ 으로 나누면 좌변은 어떤 꼴이 될까?","식":["$\\left(\\dfrac{f(a)-f(1)}{a-1}\\right)^{2}=a(a+2)$"],"설명":"$a>1$ 이므로 $(a-1)^{2}\\ne0$ 이어서 나눌 수 있다. 좌변은 $x=1$ 에서의 평균변화율의 제곱이라 $a\\to1$ 일 때 미분계수의 제곱 꼴이 된다.","확인":null,"스킬":"D3"},{"제목":"극한으로 미분계수의 제곱 구하기","힌트":"$a\\to1+$ 일 때 양변의 극한값은 각각 얼마일까?","식":["$\\lim_{a\\to1+}\\left(\\dfrac{f(a)-f(1)}{a-1}\\right)^{2}=\\lim_{a\\to1+}a(a+2)$","$\\left(f\\,'(1)\\right)^{2}=3$"],"설명":"$f$ 가 $x=1$ 에서 미분가능하므로 우극한이 $f\\,'(1)$ 이다. 우변은 $a=1$ 을 대입한 $1\\times3$ 이다.","확인":"3","스킬":"D3"},{"제목":"증가 조건으로 부호 정하기","힌트":"증가하는 함수의 $x=1$ 에서의 미분계수는 $0$ 이상일까, 이하일까?","식":["$f\\,'(1)\\ge0$","$f\\,'(1)=\\sqrt{3}$"],"설명":"증가하는 함수의 평균변화율은 $0$ 이상이므로 미분계수도 $0$ 이상이다. 제곱이 $3$ 인 음이 아닌 수는 $\\sqrt{3}$ 이다.","확인":null,"스킬":"D1"}]},"ns-a838554bf39c":{"길":"세 보기를 그래프의 값과 극한으로 하나씩 판정한다","단계":[{"제목":"ㄱ: 미분불가능한 점 찾기","힌트":"그래프가 끊기거나 꺾이는 곳은 어디일까?","식":["$x=0$ 에서 $f(0)=2,\\ \\lim_{x\\to0-}f(x)=1$ : 불연속","$x=1$ 에서 $f(1)=1,\\ \\lim_{x\\to1-}f(x)=2$ : 불연속","$a=0,\\ 1$"],"설명":"미분가능하려면 연속이어야 한다. 불연속인 $x=0,\\ 1$ 에서는 미분계수가 없고, 나머지 구간은 이차함수·상수·일차함수이므로 미분가능하다. 합이 $1$ 이므로 ㄱ 은 참이다.","확인":null,"스킬":"D12"},{"제목":"ㄴ: 치환해 우미분계수 꼴로 만들기","고비":true,"힌트":"$x^{2}-2x+1$ 을 $t$ 로 두면 $x\\to1$ 일 때 $t$ 는 어디로 갈까?","식":["$t=(x-1)^{2}$","$x\\to1$ 이면 $t\\to0+$","$\\lim_{t\\to0+}\\dfrac{f(t)-f(0)}{t-0}$"],"설명":"$(x-1)^{2}\\ge0$ 이므로 $t$ 는 $0$ 보다 큰 쪽에서만 $0$ 에 가까워진다. 분모가 $(x-1)^{2}=t-0$ 이므로 $x=0$ 에서의 우미분계수 꼴이다.","확인":null,"스킬":"A1"},{"제목":"ㄴ: 0 오른쪽에서 함숫값 읽기","힌트":"그래프에서 $f(0)$ 과 $0<t<1$ 에서의 $f(t)$ 는 얼마일까?","식":["$f(0)=2$","$0<t<1$ 에서 $f(t)=2$","$\\lim_{t\\to0+}\\dfrac{2-2}{t}=0$"],"설명":"그래프에서 $x=0$ 의 점은 속이 찬 점 $(0,\\ 2)$ 이고 $0<x<1$ 에서 $f(x)=2$ 이다. 분자가 $0$ 이므로 우미분계수는 $0$ 이고 ㄴ 은 참이다.","확인":"2","스킬":"D1"},{"제목":"ㄷ: 구간 끝에서 g 의 값 구하기","힌트":"$g(x)=x^{2}f(x)$ 로 두고 $x=-2,\\ -1$ 에서의 값은?","식":["$f(-2)=1,\\ f(-1)=2$","$g(-2)=4f(-2)=4$","$g(-1)=1\\times f(-1)=2$"],"설명":"이차함수 부분의 꼭짓점이 $(-1,\\ 2)$ 이므로 대칭축은 $x=-1$ 이다. $x=-2$ 의 함숫값은 $x\\to0-$ 일 때의 값 $1$ 과 같다.","확인":"4","스킬":"G11"},{"제목":"ㄷ: 사잇값 정리로 판정하기","힌트":"$\\frac{5}{2}$ 는 $g(-1)$ 과 $g(-2)$ 사이에 있을까?","식":["$g$ 는 $[-2,\\ -1]$ 에서 연속","$g(-1)=2<\\dfrac{5}{2}<4=g(-2)$","ㄱ, ㄴ, ㄷ 모두 참"],"설명":"$[-2,\\ -1]$ 에서 $f$ 는 이차함수이므로 연속이고 $g$ 도 연속이다. 사잇값 정리에 의해 $g(x)=\\frac{5}{2}$ 인 $x$ 가 열린 구간 $(-2,\\ -1)$ 에 있다. 세 보기가 모두 참이다.","확인":null,"스킬":"C8"}]},"ns-ad3dd1d3c145":{"길":"가까운 점이 바뀌는 경계에서 도함수가 끊기는지 따진다","단계":[{"제목":"가까운 점이 바뀌는 경계 찾기","고비":true,"힌트":"두 점 $\\mathrm{A},\\ \\mathrm{B}$ 에서 같은 거리에 있는 점들은 어떤 직선 위에 있을까?","식":["$\\overline{\\mathrm{AB}}$ 의 중점 $\\left(0,\\ \\dfrac{1}{2}\\right)$","$\\overline{\\mathrm{AB}}$ 의 기울기 $\\dfrac{3}{2}$","수직이등분선 $y=-\\dfrac{2}{3}x+\\dfrac{1}{2}$"],"설명":"$g(x)$ 는 점 $\\mathrm{P}(x,\\ f(x))$ 에서 더 가까운 점까지의 거리의 제곱이다. 가까운 점이 바뀌는 곳은 선분 $\\mathrm{AB}$ 의 수직이등분선과 그래프가 만나는 곳이다.","확인":null,"스킬":"C2"},{"제목":"x<1 에서 교점의 x 좌표 구하기","힌트":"$y=x+1$ 과 수직이등분선의 식을 같게 놓으면?","식":["$x+1=-\\dfrac{2}{3}x+\\dfrac{1}{2}$","$\\dfrac{5}{3}x=-\\dfrac{1}{2}$","$x=-\\dfrac{3}{10}$"],"설명":"$x<1$ 에서 $f(x)=x+1$ 이므로 두 직선의 식을 연립한다. 구한 값이 $x<1$ 을 만족한다.","확인":"-3/10","스킬":"G1"},{"제목":"x≥1 에서 교점의 x 좌표 구하기","힌트":"$y=-2x+4$ 와 수직이등분선의 식을 같게 놓으면?","식":["$-2x+4=-\\dfrac{2}{3}x+\\dfrac{1}{2}$","$\\dfrac{4}{3}x=\\dfrac{7}{2}$","$x=\\dfrac{21}{8}$"],"설명":"$x\\ge1$ 에서 $f(x)=-2x+4$ 이므로 같은 방법으로 연립한다. 구한 값이 $x\\ge1$ 을 만족한다.","확인":"21/8","스킬":"G1"},{"제목":"두 교점에서 좌우 도함수 비교하기","힌트":"교점에서 $\\overline{\\mathrm{PA}}^{2}$ 과 $\\overline{\\mathrm{PB}}^{2}$ 의 도함수 값이 같을까?","식":["$x<1$ : $\\overline{\\mathrm{PA}}^{2}=2x^{2}+6x+5,\\ \\overline{\\mathrm{PB}}^{2}=2x^{2}-4x+2$","$x\\ge1$ : $\\overline{\\mathrm{PA}}^{2}=5x^{2}-18x+26,\\ \\overline{\\mathrm{PB}}^{2}=5x^{2}-10x+5$","$x=-\\dfrac{3}{10}$ 에서 $4x+6\\ne4x-4$","$x=\\dfrac{21}{8}$ 에서 $10x-18\\ne10x-10$"],"설명":"교점의 좌우에서 $g$ 는 서로 다른 식이 되고 교점에서 두 식의 값은 같다. 그러나 도함수는 다르므로 두 교점에서 $g$ 는 미분가능하지 않다.","확인":null,"스킬":"D12"},{"제목":"x=1 에서 미분가능한지 확인하기","힌트":"$x=1$ 에서 $g$ 의 좌미분계수와 우미분계수는 각각 얼마일까?","식":["$-\\dfrac{3}{10}<1<\\dfrac{21}{8}$ 이므로 $g=\\overline{\\mathrm{PB}}^{2}$","$x<1$ : $(2x^{2}-4x+2)\\,'=4x-4\\to0$","$x>1$ : $(5x^{2}-10x+5)\\,'=10x-10\\to0$"],"설명":"$f$ 의 그래프는 $x=1$ 에서 꺾이지만 $x=1$ 근처의 $g$ 는 점 $\\mathrm{B}$ 까지의 거리의 제곱이다. 좌우 미분계수가 모두 $0$ 으로 같으므로 $x=1$ 에서는 미분가능하다.","확인":"0","스킬":"D12"},{"제목":"p 와 80p 구하기","힌트":"미분불가능한 두 $x$ 값의 합을 구한 뒤 $80$ 을 곱하면?","식":["$p=-\\dfrac{3}{10}+\\dfrac{21}{8}=\\dfrac{186}{80}$","$80p=186$"],"설명":"미분불가능한 점은 두 교점뿐이다. 분모를 $80$ 으로 통분해 더한다.","확인":"186","스킬":"C2"}]},"ns-d5090de08011":{"길":"구간별 식을 쓰고 x=0, 1 에서 좌우 극한을 비교한다","단계":[{"제목":"그래프에서 구간별 식 읽기","힌트":"각 구간에서 그래프가 지나는 두 점으로 직선의 식을 구하면?","식":["$x\\le0$ : $f(x)=x$","$0<x<1$ : $f(x)=-x+1$","$x\\ge1$ : $f(x)=x-1$"],"설명":"$x\\le0$ 에서는 점 $(-1,\\ -1),\\ (0,\\ 0)$ 을, $0<x<1$ 에서는 속이 빈 점 $(0,\\ 1)$ 과 점 $(1,\\ 0)$ 을, $x\\ge1$ 에서는 점 $(1,\\ 0),\\ (2,\\ 1)$ 을 지난다.","확인":null,"스킬":"G9"},{"제목":"ㄱ: h 의 부호별로 분자 계산하기","힌트":"$h>0$ 일 때와 $h<0$ 일 때 $f(1+h),\\ f(1-h)$ 는 각각 어느 구간의 식일까?","식":["$h>0$ : $f(1+h)=h,\\ f(1-h)=-(1-h)+1=h$","$h<0$ : $f(1+h)=-(1+h)+1=-h,\\ f(1-h)=(1-h)-1=-h$","두 경우 모두 분자 $=0$"],"설명":"$h$ 의 부호에 따라 $1\\pm h$ 가 놓이는 구간이 바뀐다. 그러나 두 경우 모두 분자가 $0$ 이므로 극한은 $0$ 이고 ㄱ 은 참이다.","확인":null,"스킬":"C2"},{"제목":"ㄴ: 0 근처에서 f(x)f(−x) 식 세우기","고비":true,"힌트":"$-x$ 가 $0$ 이하일 때와 $0$ 과 $1$ 사이일 때로 나누어 $f(-x)$ 를 구하면?","식":["$0<x<1$ : $f(x)f(-x)=(-x+1)(-x)=x^{2}-x$","$-1<x<0$ : $f(x)f(-x)=x(x+1)=x^{2}+x$"],"설명":"$0<x<1$ 이면 $-x\\le0$ 이므로 $f(-x)=-x$ 이다. $-1<x<0$ 이면 $0<-x<1$ 이므로 $f(-x)=-(-x)+1=x+1$ 이다.","확인":null,"스킬":"G4"},{"제목":"ㄴ: x=0 에서 우미분계수 구하기","힌트":"$x^{2}-x$ 와 $x^{2}+x$ 의 $x=0$ 에서의 미분계수는 각각 얼마일까?","식":["우미분계수 $(x^{2}-x)\\,'=2x-1\\to-1$","좌미분계수 $(x^{2}+x)\\,'=2x+1\\to1$","$-1\\ne1$"],"설명":"$x=0$ 에서 함숫값은 $f(0)f(0)=0$ 으로 이어져 있으나 좌우 미분계수가 다르므로 미분가능하지 않다. ㄴ 은 거짓이다.","확인":"-1","스킬":"D12"},{"제목":"ㄷ: k=1 일 때 x=0 에서의 우미분계수 구하기","힌트":"$k=1$ 일 때 $xf(x)$ 의 $x=0$ 좌우 식과 미분계수는?","식":["$x\\le0$ : $xf(x)=x^{2}$, 미분계수 $2x\\to0$","$0<x<1$ : $xf(x)=-x^{2}+x$, 미분계수 $-2x+1\\to1$","$0\\ne1$"],"설명":"좌우 미분계수가 다르므로 $k=1$ 이면 $x=0$ 에서 미분가능하지 않다.","확인":"1","스킬":"D12"},{"제목":"ㄷ: k=2 일 때 확인과 결론","힌트":"$k=2$ 일 때 $x^{2}f(x)$ 의 $x=0$ 좌우 미분계수는?","식":["$x\\le0$ : $x^{2}f(x)=x^{3}$, 미분계수 $3x^{2}\\to0$","$0<x<1$ : $x^{2}f(x)=-x^{3}+x^{2}$, 미분계수 $-3x^{2}+2x\\to0$","ㄱ, ㄷ 만 옳다"],"설명":"$k=2$ 이면 좌우 미분계수가 모두 $0$ 으로 같아 미분가능하다. 따라서 최소의 자연수 $k$ 는 $2$ 이므로 ㄷ 은 참이고, 옳은 것은 ㄱ, ㄷ 이다.","확인":null,"스킬":"D12"}]},"ns-0989aa8ba45e":{"길":"그림 속 직선의 기울기와 역함수의 대응으로 네 보기를 판정한다","단계":[{"제목":"그림에서 함숫값과 접선 읽기","힌트":"점선이 가리키는 $f(a),\\ f(b)$ 는 각각 어느 값과 같을까?","식":["$f(a)=b,\\ f(b)=c$","$f\\,'(b)=2$ (접선 $y=2x$ 의 기울기)","접선 $y=2x$ 는 원점을 지나고 곡선은 접선 위쪽에 있다"],"설명":"$x=a$ 에서 그은 점선은 직선 $y=x$ 와 $x=b$ 에서 만나므로 $f(a)=b$ 이다. 같은 방법으로 $f(b)=c$ 이다. 접점 $(b,\\ f(b))$ 에서의 접선이 $y=2x$ 이므로 미분계수는 $2$ 이다.","확인":null,"스킬":"G9"},{"제목":"ㄱ: 접점과 오른쪽 점을 잇는 기울기 비교하기","힌트":"접점 $(b,\\ f(b))$ 와 $b<x<c$ 인 점을 잇는 직선의 기울기는 접선의 기울기보다 클까, 작을까?","식":["$\\lim_{x\\to b}\\dfrac{f(b)-f(x)}{b-x}=f\\,'(b)=2$","$\\dfrac{f(x)-f(b)}{x-b}>2$","ㄱ 은 거짓"],"설명":"곡선이 접선 위쪽에 있으므로 접점에서 오른쪽으로 멀어질수록 곡선 위 점과 접점을 잇는 기울기가 접선의 기울기보다 커진다. 보기 ㄱ 의 부등호는 반대 방향이다.","확인":null,"스킬":"D1"},{"제목":"ㄴ: 원점과 잇는 기울기로 바꾸기","고비":true,"힌트":"$\\frac{x}{f(x)}<\\frac{1}{2}$ 의 양변에 역수를 취하면 $\\frac{f(x)}{x}$ 는 어떤 기울기일까?","식":["$a<x<b$ 에서 $x>0,\\ f(x)>0$","$\\dfrac{x}{f(x)}<\\dfrac{1}{2}\\iff\\dfrac{f(x)}{x}>2$","$\\dfrac{f(x)}{x}$ : 원점과 $(x,\\ f(x))$ 를 잇는 직선의 기울기","ㄴ 은 참"],"설명":"$x$ 와 $f(x)$ 가 모두 양수이므로 역수를 취하면 부등호 방향이 바뀐다. 원점은 접선 $y=2x$ 위의 점이고 곡선이 접선 위쪽에 있으므로, 원점과 곡선 위 점을 잇는 기울기는 $2$ 보다 크다.","확인":null,"스킬":"G9"},{"제목":"ㄷ: 도함수의 증감 따지기","힌트":"곡선이 아래로 볼록할 때 $x$ 가 커지면 접선의 기울기 $f\\,'(x)$ 는 어떻게 변할까?","식":["$b<x<c$ 에서 $f\\,'(x)>f\\,'(b)=2$","ㄷ 은 거짓"],"설명":"접점에서 오른쪽으로 갈수록 접선의 기울기가 커지므로 $f\\,'(x)>2$ 이다. 보기 ㄷ 의 $f\\,'(x)\\le f\\,'(b)$ 는 성립하지 않는다.","확인":null,"스킬":"D4"},{"제목":"ㄹ: 역함수의 평균변화율 구하고 결론 내기","힌트":"$f(a)=b,\\ f(b)=c$ 에서 $g(b),\\ g(c)$ 는 각각 얼마일까?","식":["$g(b)=a,\\ g(c)=b$","$\\dfrac{g(b)-g(c)}{b-c}=\\dfrac{a-b}{b-c}=\\dfrac{b-a}{c-b}$","ㄹ 은 참, 옳은 것은 ㄴ, ㄹ"],"설명":"$f$ 의 역함수 $g$ 는 $f$ 의 입력과 출력을 바꾼다. $x$ 가 $c$ 에서 $b$ 까지 변할 때 $g$ 의 평균변화율은 $\\frac{g(b)-g(c)}{b-c}$ 이다.","확인":null,"스킬":"T1"}]},"ns-0a0b8e51eb2d":{"길":"세 점 사이 평균변화율에 평균값 정리와 사잇값 정리를 쓴다","단계":[{"제목":"세 점 사이의 평균변화율 구하기","힌트":"두 점씩 골라 $y$ 의 변화량을 $x$ 의 변화량으로 나누면?","식":["$(-1,\\ 0),\\ (3,\\ -2)$ : $\\dfrac{-2-0}{3-(-1)}=-\\dfrac{1}{2}$","$(-1,\\ 0),\\ (1,\\ 2)$ : $\\dfrac{2-0}{1-(-1)}=1$","$(1,\\ 2),\\ (3,\\ -2)$ : $\\dfrac{-2-2}{3-1}=-2$"],"설명":"다항함수는 모든 실수에서 연속이고 미분가능하므로 어느 구간에서든 평균값 정리를 쓸 수 있다. 쓸 평균변화율을 먼저 구해 둔다.","확인":null,"스킬":"D2"},{"제목":"ㄱ: 평균값 정리로 접선의 기울기 찾기","힌트":"구간 $(-1,\\ 3)$ 의 평균변화율과 같은 미분계수가 있을까?","식":["$f\\,'(c)=\\dfrac{f(3)-f(-1)}{3-(-1)}=-\\dfrac{1}{2}$ 인 $c$ 가 $(-1,\\ 3)$ 에 존재","ㄱ 은 참"],"설명":"평균값 정리에 의해 구간의 평균변화율과 같은 미분계수를 갖는 점이 구간 안에 있다. 그 점에서의 접선의 기울기가 $-\\frac{1}{2}$ 이다.","확인":null,"스킬":"D2"},{"제목":"ㄴ: 두 미분계수 사이에서 0 이 되는 점 찾기","고비":true,"힌트":"$f\\,'$ 이 $1$ 인 점과 $-2$ 인 점이 있다면 그 사이에서 $f\\,'$ 은 어떤 값을 지날까?","식":["$f\\,'(d)=1$ 인 $d$ 가 $(-1,\\ 1)$ 에 존재","$f\\,'(e')=-2$ 인 $e'$ 가 $(1,\\ 3)$ 에 존재","$f\\,'$ 은 다항함수라 연속이므로 $d$ 와 $e'$ 사이에서 $f\\,'(e)=0$","ㄴ 은 참"],"설명":"구간 $(-1,\\ 1)$ 과 $(1,\\ 3)$ 에 평균값 정리를 각각 쓰면 도함수의 값 $1$ 과 $-2$ 가 나온다. 다항함수의 도함수도 다항함수이므로 연속이다. 따라서 사잇값 정리에 의해 두 점 사이에서 도함수가 $0$ 이 되는 점이 있고 그곳의 접선은 $x$ 축과 평행하다.","확인":null,"스킬":"C8"},{"제목":"ㄷ: 반례를 찾아 판정하고 결론 내기","힌트":"세 점을 지나는 이차함수에서 $f\\,'(1)$ 을 계산하면 $0$ 이 될까?","식":["$f(x)=-\\dfrac{3}{4}x^{2}+x+\\dfrac{7}{4}$ 는 세 점을 지난다","$f\\,'(x)=-\\dfrac{3}{2}x+1$ 에서 $f\\,'(1)\\ne0$","ㄷ 은 거짓, 옳은 것은 ㄱ, ㄴ"],"설명":"도함수가 $0$ 이 되는 점이 반드시 $x=1$ 일 필요는 없다. 세 점을 지나는 이차함수를 반례로 들면 $f\\,'(1)\\ne0$ 이다.","확인":null,"스킬":"C3"}]},"ns-0becf1c5ace6":{"길":"두 접점을 한 이차방정식의 두 근으로 보고 직선 AB 를 a 의 식으로 쓴다","단계":[{"제목":"접점 A 에서 접선의 방정식 세우기","힌트":"접점을 $(t,\\ t^{2}+2)$ 로 두면 그 점에서 접선의 기울기는?","식":["$y'=2x$ 이므로 기울기 $2t$","$y=2t(x-t)+t^{2}+2$"],"설명":"곡선 위의 점 $(t,\\ t^{2}+2)$ 에서 접선의 기울기는 $x=t$ 에서의 미분계수 $2t$ 이다.","확인":null,"스킬":"D7"},{"제목":"점 (a, 0) 을 지나는 조건 쓰기","힌트":"접선의 식에 $x=a,\\ y=0$ 을 넣으면 $t$ 에 대한 식은?","식":["$0=2t(a-t)+t^{2}+2$","$t^{2}-2at-2=0$"],"설명":"접선이 점 $(a,\\ 0)$ 을 지나므로 좌표를 대입한다. 전개하면 $t$ 에 대한 이차방정식이 된다.","확인":null,"스킬":"G3"},{"제목":"두 접점의 좌표를 근과 계수로 묶기","고비":true,"힌트":"접점 B 를 $(s,\\ s^{2}+2)$ 로 두면 $s$ 도 같은 이차방정식을 만족할까?","식":["$s^{2}-2as-2=0$","$t,\\ s$ 는 $x^{2}-2ax-2=0$ 의 두 근","$t+s=2a,\\ ts=-2$"],"설명":"접점 B 도 같은 과정을 거치므로 $s$ 가 같은 식을 만족한다. 서로 다른 두 접점이므로 $t,\\ s$ 는 이차방정식의 두 근이고, 근과 계수의 관계를 쓴다.","확인":null,"스킬":"A2"},{"제목":"직선 AB 의 방정식 구하기","힌트":"두 점 $(t,\\ t^{2}+2),\\ (s,\\ s^{2}+2)$ 를 지나는 직선의 기울기와 $y$ 절편은?","식":["기울기 $\\dfrac{(t^{2}+2)-(s^{2}+2)}{t-s}=t+s$","$y=(t+s)(x-t)+t^{2}+2=(t+s)x-ts+2$","$y=2ax+4$"],"설명":"기울기는 $(t+s)$ 로 간단해지고 $-t(t+s)+t^{2}=-ts$ 이다. $t+s=2a,\\ ts=-2$ 를 대입하면 $y$ 절편이 $-(-2)+2$ 로 정해진다.","확인":"4","스킬":"A2"},{"제목":"a 에 관한 항등식으로 점 P 찾기","힌트":"$y=2ax+4$ 를 $a$ 에 대해 정리하면 $a$ 의 계수와 상수항은 각각 무엇이어야 할까?","식":["$(2x)a+(4-y)=0$","$2x=0,\\ 4-y=0$","$\\mathrm{P}(0,\\ 4)$"],"설명":"$a$ 의 값에 관계없이 성립해야 하므로 $a$ 의 계수와 상수항이 모두 $0$ 이어야 한다.","확인":null,"스킬":"A3"}]},"ns-0db948004979":{"길":"평균값 정리로 f(1)−f(0) 의 범위를 잡는다","단계":[{"제목":"평균값 정리로 f(1)−f(0) 을 도함수로 바꾸기","힌트":"$[0,\\ 1]$ 에서 평균변화율과 같은 미분계수를 갖는 $c$ 는 어디에 있을까?","식":["$\\dfrac{f(1)-f(0)}{1-0}=f\\,'(c)$ 인 $c$ 가 $(0,\\ 1)$ 에 존재","$f(1)-f(0)=f\\,'(c)$"],"설명":"닫힌구간에서 연속이고 열린구간에서 미분가능하므로 평균값 정리를 쓸 수 있다. 구간의 길이가 $1$ 이라 평균변화율이 $f(1)-f(0)$ 이다.","확인":null,"스킬":"D2"},{"제목":"f(1) 의 범위 구하기","고비":true,"힌트":"$|f\\,'(c)|\\le5$ 이면 $f\\,'(c)$ 는 어느 범위에 있을까?","식":["$-5\\le f\\,'(c)\\le5$","$f(0)-5\\le f(1)\\le f(0)+5$","$-2\\le f(1)\\le8$"],"설명":"절댓값 부등식을 풀어 $f\\,'(c)$ 의 범위를 잡고 $f(1)=f(0)+f\\,'(c)$ 에 $f(0)=3$ 을 넣는다.","확인":null,"스킬":"C9"},{"제목":"f(1) 의 최댓값 정하기","힌트":"범위의 위쪽 끝값을 실제로 가질 수 있는 함수가 있을까?","식":["$f(x)=5x+3$ 이면 $f(1)=8$","최댓값 $8$"],"설명":"$f(x)=5x+3$ 은 모든 조건을 만족하고 $f(1)=8$ 이므로 범위의 위쪽 끝값이 실제로 나온다.","확인":"8","스킬":"C9"}]},"ns-0e7f5166832b":{"길":"원점과 잇는 기울기와 접선의 기울기, 평균값 정리로 보기를 판정한다","단계":[{"제목":"f(a)/a 를 직선의 기울기로 읽기","힌트":"$\\frac{f(a)}{a}$ 는 어느 두 점을 잇는 직선의 기울기일까?","식":["$\\dfrac{f(a)}{a}=\\dfrac{f(a)-0}{a-0}$","원점과 $(a,\\ f(a))$ 를 잇는 직선의 기울기","직선 $y=-x$ 는 원점과 접점 $(1,\\ -1)$ 을 지난다"],"설명":"분모와 분자를 두 점의 좌표의 차로 보면 원점과 곡선 위 점을 잇는 직선의 기울기이다. 접선 $y=-x$ 가 원점을 지난다는 점이 이후 판정의 기준이 된다.","확인":null,"스킬":"G9"},{"제목":"ㄱ: 원점과 잇는 기울기의 최솟값 찾기","힌트":"원점을 지나는 직선이 곡선에 접할 때의 기울기는 얼마일까?","식":["$a>0$ 인 점과 원점을 잇는 기울기의 최솟값은 접할 때의 기울기 $-1$","$\\dfrac{f(a)}{a}\\ge-1$","ㄱ 은 참"],"설명":"곡선이 접선 $y=-x$ 위쪽에 있으므로 곡선 위 점과 원점을 잇는 기울기는 접선의 기울기 $-1$ 이상이다.","확인":null,"스킬":"G9"},{"제목":"ㄴ: a 의 위치에 따라 기울기 비교하기","고비":true,"힌트":"$0<a<1$ 과 $a>1$ 일 때, 원점과 잇는 기울기와 $x=a$ 에서의 접선의 기울기 중 어느 쪽이 클까?","식":["$0<a<1$ : $\\dfrac{f(a)}{a}>f\\,'(a)$","$a>1$ : $\\dfrac{f(a)}{a}<f\\,'(a)$","$f(a)<af\\,'(a)$ 이면 $a>1$","ㄴ 은 거짓"],"설명":"$f(a)<af\\,'(a)$ 의 양변을 $a\\,(>0)$ 로 나누면 $\\frac{f(a)}{a}<f\\,'(a)$ 이다. 이 부등식은 $a>1$ 일 때 성립하므로 $0<a<1$ 이라는 결론은 틀리다.","확인":null,"스킬":"G9"},{"제목":"ㄷ: 평균값 정리로 판정하고 결론 내기","힌트":"$\\frac{f(a)+1}{a-1}$ 은 어느 구간의 평균변화율일까?","식":["$\\dfrac{f(a)-f(1)}{a-1}=\\dfrac{f(a)+1}{a-1}=f\\,'(k)$ 인 $k$ 가 $(1,\\ a)$ 에 존재","$f\\,'$ 은 증가하므로 $k<a$ 에서 $f\\,'(k)<f\\,'(a)$","ㄷ 은 참, 옳은 것은 ㄱ, ㄷ"],"설명":"접점에서 $f(1)=-1$ 이므로 분자는 $f(a)-f(1)$ 이다. 최고차항의 계수가 양수인 이차함수의 도함수는 증가하는 일차함수이다.","확인":null,"스킬":"D2"}]},"ns-0e9aa6df0248":{"길":"접점을 (a, a²+1) 로 두면 1−t=a² 이라 넓이를 a 의 식으로 쓸 수 있다","단계":[{"제목":"접점 B 에서 접선 l₂ 의 방정식 세우기","힌트":"$\\mathrm{B}(a,\\ a^{2}+1)$ 로 두면 $l_{2}$ 의 기울기는?","식":["$y'=2x$ 이므로 기울기 $2a$","$l_{2}$ : $y=2a(x-a)+a^{2}+1$"],"설명":"$\\mathrm{B}$ 의 $x$ 좌표를 $a\\,(>0)$ 로 두면 접선의 기울기는 $x=a$ 에서의 미분계수 $2a$ 이다.","확인":null,"스킬":"D7"},{"제목":"점 P 를 지나는 조건으로 t 와 a 연결하기","힌트":"$l_{2}$ 가 $(0,\\ t)$ 를 지나므로 $x=0$ 을 대입하면?","식":["$t=-2a^{2}+a^{2}+1=-a^{2}+1$","$1-t=a^{2}$, $\\sqrt{1-t}=a$"],"설명":"$x=0,\\ y=t$ 를 접선의 식에 대입해 $t$ 를 $a$ 로 나타낸다. $t<1$ 이므로 $a>0$ 이고 $\\sqrt{1-t}=a$ 이다.","확인":null,"스킬":"G3"},{"제목":"수직인 직선의 방정식과 점 C 구하기","고비":true,"힌트":"$l_{2}$ 에 수직이고 $\\mathrm{B}$ 를 지나는 직선의 기울기는? 점 C 는 어느 축 위에 있을까?","식":["기울기 $-\\dfrac{1}{2a}$","$y=-\\dfrac{1}{2a}(x-a)+a^{2}+1$","$x=0$ 일 때 $y=a^{2}+\\dfrac{3}{2}$","$\\mathrm{C}\\left(0,\\ a^{2}+\\dfrac{3}{2}\\right)$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$ 이다. 점 A 와 B 는 $y$ 축에 대칭이므로 두 수직선의 교점 C 는 $y$ 축 위에 있어 $x=0$ 일 때의 $y$ 값이 C 의 $y$ 좌표이다.","확인":null,"스킬":"G9"},{"제목":"사각형 PACB 의 넓이 s(t) 구하기","힌트":"사각형을 $y$ 축으로 나눈 삼각형 하나의 밑변 $\\overline{\\mathrm{PC}}$ 와 높이는 얼마일까?","식":["$\\overline{\\mathrm{PC}}=a^{2}+\\dfrac{3}{2}-t=2a^{2}+\\dfrac{1}{2}$","$s(t)=2\\times\\dfrac{1}{2}\\times\\overline{\\mathrm{PC}}\\times a=a\\left(2a^{2}+\\dfrac{1}{2}\\right)$"],"설명":"사각형은 $y$ 축에 대칭이므로 삼각형 $\\mathrm{PCB}$ 넓이의 $2$ 배이다. 밑변은 $y$ 축 위의 $\\overline{\\mathrm{PC}}$ 이고 높이는 B 의 $x$ 좌표 $a$ 이다. $t=1-a^{2}$ 을 대입해 정리한다.","확인":null,"스킬":"G10"},{"제목":"극한값 구하기","힌트":"$t\\to1-$ 일 때 $a=\\sqrt{1-t}$ 는 어디로 갈까?","식":["$\\dfrac{s(t)}{\\sqrt{1-t}}=\\dfrac{a\\left(2a^{2}+\\frac{1}{2}\\right)}{a}=2a^{2}+\\dfrac{1}{2}$","$a\\to0+$","$\\lim_{a\\to0+}\\left(2a^{2}+\\dfrac{1}{2}\\right)=\\dfrac{1}{2}$"],"설명":"$\\sqrt{1-t}=a$ 이므로 분모와 분자의 $a$ 가 약분된다. $t\\to1-$ 이면 $a\\to0+$ 이다.","확인":"1/2","스킬":"A1"}]},"ns-1228ea2935fb":{"길":"평균값 정리로 f(2)−f(1) 을 기울기의 범위 안에 가둔다","단계":[{"제목":"평균값 정리로 f(2)−f(1) 을 도함수로 바꾸기","힌트":"구간 $[1,\\ 2]$ 의 평균변화율과 같은 미분계수를 갖는 $c$ 는 어디에 있을까?","식":["$f\\,'(c)=\\dfrac{f(2)-f(1)}{2-1}$ 인 $c$ 가 $(1,\\ 2)$ 에 존재","$f\\,'(c)=f(2)-f(1)=5-f(1)$"],"설명":"$f$ 는 실수 전체에서 미분가능하므로 $[1,\\ 2]$ 에서 연속이고 $(1,\\ 2)$ 에서 미분가능하다. 구간의 길이가 $1$ 이라 평균변화율이 $f(2)-f(1)$ 이다.","확인":null,"스킬":"D2"},{"제목":"f(1) 의 범위 구하기","고비":true,"힌트":"$-1\\le f\\,'(c)\\le1$ 에 $f\\,'(c)=5-f(1)$ 을 넣고 $f(1)$ 에 대해 풀면?","식":["$-1\\le5-f(1)\\le1$","$-6\\le-f(1)\\le-4$","$4\\le f(1)\\le6$"],"설명":"(나) 조건에서 $-1\\le f\\,'(x)\\le1$ 이므로 $f\\,'(c)$ 도 이 범위에 있다. 부등식에 음수를 곱하면 부등호 방향이 바뀐다.","확인":null,"스킬":"C9"},{"제목":"최댓값과 최솟값의 곱 구하기","힌트":"범위의 양 끝값을 $M,\\ m$ 으로 잡고 곱하면?","식":["$M=6,\\ m=4$","$M\\times m=24$"],"설명":"$f(x)=-x+7$ 이면 $f(1)=6$, $f(x)=x+3$ 이면 $f(1)=4$ 이고 둘 다 조건을 만족하므로 양 끝값이 실제로 나온다.","확인":"24","스킬":"C9"}]},"ns-17e84bd083d2":{"길":"접점과 교점의 x 좌표 관계를 구해 두 기울기를 한 문자로 쓴다","단계":[{"제목":"접선과 곡선의 교점 방정식 세우기","힌트":"접점에서는 중근, 다른 교점에서는 단근이므로 접선과 곡선의 차는 어떤 꼴일까?","식":["$\\mathrm{P}(a,\\ f(a)),\\ \\mathrm{Q}(b,\\ f(b))$","$f(x)-\\left\\{f\\,'(a)(x-a)+f(a)\\right\\}=(x-a)^{2}(x-b)$"],"설명":"접선과 곡선이 접하는 점 P 의 $x$ 좌표 $a$ 는 중근이고, 다른 교점 Q 의 $x$ 좌표 $b$ 는 단근이다. 최고차항의 계수가 $1$ 이므로 곱의 꼴로 쓸 수 있다.","확인":null,"스킬":"G1"},{"제목":"삼차식의 성질로 b 를 a 로 나타내기","고비":true,"힌트":"$f(x)$ 에 $x^{2}$ 항이 없으니 접선을 빼도 $x^{2}$ 항이 없다. 세 근의 합은?","식":["$(x-a)^{2}(x-b)=x^{3}-(2a+b)x^{2}+\\cdots$","$2a+b=0$","$b=-2a$"],"설명":"좌변 $f(x)-\\left\\{f\\,'(a)(x-a)+f(a)\\right\\}$ 에는 $x^{2}$ 항이 없다. 우변의 $x^{2}$ 의 계수가 $0$ 이어야 하므로 세 근의 합이 $0$ 이다.","확인":null,"스킬":"D5"},{"제목":"두 기울기를 a 의 식으로 쓰기","힌트":"$f\\,'(x)=3x^{2}-3$ 에 $x=a$ 와 $x=b$ 를 넣고 $b=-2a$ 를 쓰면?","식":["$m_{1}=f\\,'(a)=3a^{2}-3$","$m_{2}=f\\,'(b)=3b^{2}-3=3(-2a)^{2}-3=12a^{2}-3$"],"설명":"접선의 기울기는 접점의 $x$ 좌표에서의 미분계수이다. $m_{2}$ 는 $b=-2a$ 를 대입해 $a$ 만으로 나타낸다.","확인":null,"스킬":"D1"},{"제목":"m₁≥2 에서 a² 의 범위 구하기","힌트":"$3a^{2}-3\\ge2$ 를 $a^{2}$ 에 대해 풀면?","식":["$3a^{2}-3\\ge2$","$a^{2}\\ge\\dfrac{5}{3}$"],"설명":"부등식의 양변에 $3$ 을 더하고 $3$ 으로 나눈다.","확인":"5/3","스킬":"G6"},{"제목":"m₂ 의 최솟값 구하기","힌트":"$m_{2}=12a^{2}-3$ 은 $a^{2}$ 이 클수록 어떻게 변할까?","식":["$m_{2}=12a^{2}-3\\ge12\\times\\dfrac{5}{3}-3$","$m_{2}\\ge17$"],"설명":"$m_{2}$ 는 $a^{2}$ 에 대해 증가하므로 $a^{2}$ 의 최솟값에서 $m_{2}$ 가 최소이다. 따라서 $m_{2}\\ge\\alpha$ 가 항상 성립하는 $\\alpha$ 의 값은 최솟값이다.","확인":"17","스킬":"G6"}]},"ns-19d90194e8ef":{"길":"g=x^k f 를 미분하고 접선의 x 절편 조건으로 k 를 먼저 구한다","단계":[{"제목":"g(x)=x^k f(x) 를 미분해 x=2 대입하기","힌트":"곱의 미분법으로 $g\\,'(x)$ 를 쓰고 $g\\,'(2)=0$ 을 넣으면?","식":["$g\\,'(x)=kx^{k-1}f(x)+x^{k}f\\,'(x)$","$g\\,'(2)=k\\cdot2^{k-1}f(2)+2^{k}f\\,'(2)=0$","$kf(2)+2f\\,'(2)=0$"],"설명":"$f(x)=\\frac{g(x)}{x^{k}}$ 에서 $g(x)=x^{k}f(x)$ 이다. 양변을 $2^{k-1}\\,(>0)$ 으로 나누어 식을 간단히 한다.","확인":null,"스킬":"D13"},{"제목":"접선의 x 절편 조건 쓰기","힌트":"접선 $y-f(2)=f\\,'(2)(x-2)$ 가 점 $\\left(\\frac{5}{2},\\ 0\\right)$ 을 지난다. $f\\,'(2)$ 는 $f(2)$ 의 몇 배일까?","식":["$0-f(2)=f\\,'(2)\\left(\\dfrac{5}{2}-2\\right)$","$-f(2)=\\dfrac{1}{2}f\\,'(2)$","$f\\,'(2)=-2f(2)$"],"설명":"접선의 식에 $x$ 절편의 좌표를 대입한다. $\\frac{5}{2}-2=\\frac{1}{2}$ 이다.","확인":"-2","스킬":"D1"},{"제목":"두 식을 연립해 k 구하기","고비":true,"힌트":"$f\\,'(2)=-2f(2)$ 를 $kf(2)+2f\\,'(2)=0$ 에 넣으면 $k$ 는 얼마일까?","식":["$kf(2)-4f(2)=0$","$(k-4)f(2)=0$","$k=4$"],"설명":"$g(2)\\ne0$ 이고 $f(2)=\\frac{g(2)}{2^{k}}$ 이므로 $f(2)\\ne0$ 이다. 그러므로 $f(2)$ 를 나눌 수 있다.","확인":null,"스킬":"A10"},{"제목":"x=1 에서 g(1) 과 g′(1) 을 f 로 나타내기","힌트":"$k=4$ 일 때 $g(1)$ 과 $g\\,'(1)$ 은 $f(1),\\ f\\,'(1)$ 로 어떻게 쓸까?","식":["$g(1)=1^{4}f(1)=f(1)$","$g\\,'(1)=4\\cdot1^{3}f(1)+1^{4}f\\,'(1)=4f(1)+f\\,'(1)$"],"설명":"$g\\,'(x)=4x^{3}f(x)+x^{4}f\\,'(x)$ 에 $x=1$ 을 넣는다.","확인":null,"스킬":"D13"},{"제목":"구하는 식의 값 계산하기","힌트":"$\\frac{g\\,'(1)}{g(1)}-\\frac{f\\,'(1)}{f(1)}$ 에 앞 단계의 두 식을 넣으면?","식":["$\\dfrac{4f(1)+f\\,'(1)}{f(1)}-\\dfrac{f\\,'(1)}{f(1)}$","$=\\dfrac{4f(1)}{f(1)}=4$"],"설명":"$g(1)=f(1)$ 이므로 분모가 같고, $f\\,'(1)$ 항이 서로 없어진다. $g(1)\\ne0$ 이므로 $f(1)\\ne0$ 이다.","확인":"4","스킬":"D13"}]},"ns-1b2a82eb8688":{"길":"네 함숫값으로 계수를 구해 접선과 두 축의 삼각형 넓이를 잰다","단계":[{"제목":"네 조건을 식으로 쓰고 이웃한 값의 차 구하기","힌트":"$f(x)=ax^{3}+bx^{2}+cx+d$ 로 두고 이웃한 두 식을 빼면 $d$ 가 사라진다. 어떤 식이 남을까?","식":["$f(1)=7,\\ f(2)=4,\\ f(3)=9,\\ f(4)=16$","$f(2)-f(1)$ : $7a+3b+c=-3$","$f(3)-f(2)$ : $19a+5b+c=5$","$f(4)-f(3)$ : $37a+7b+c=7$"],"설명":"조건 $f(a)=a^{2}$ 에서 $f(2)=4,\\ f(3)=9,\\ f(4)=16$ 이다. 이웃한 두 식의 차를 구하면 상수항 $d$ 가 없어진다.","확인":null,"스킬":"A10"},{"제목":"다시 차를 구해 a 와 b 구하기","고비":true,"힌트":"세 식을 이웃끼리 빼면 $c$ 가 사라진다. $a,\\ b$ 에 대한 두 식에서 $a$ 는 얼마일까?","식":["$12a+2b=8,\\ 18a+2b=2$","$6a+b=4,\\ 9a+b=1$","$a=-1,\\ b=10$"],"설명":"두 식을 다시 이웃끼리 빼면 $c$ 가 없어져 $a,\\ b$ 만 남는다. 두 식을 빼서 $3a=-3$ 을 얻는다.","확인":"-1","스킬":"A10"},{"제목":"c, d 를 구해 f(x) 쓰기","힌트":"$7a+3b+c=-3$ 과 $a+b+c+d=7$ 에 $a,\\ b$ 를 넣어 $c,\\ d$ 를 구하면?","식":["$c=-3-7a-3b=-26$","$d=7-(a+b+c)=24$","$f(x)=-x^{3}+10x^{2}-26x+24$"],"설명":"구한 $a,\\ b$ 를 앞의 식에 넣어 $c$ 를 먼저 구하고, 그다음 $d$ 를 구한다.","확인":null,"스킬":"A10"},{"제목":"x=1 에서 접선의 방정식 구하기","힌트":"$f\\,'(x)$ 에 $x=1$ 을 넣어 접선의 기울기를 구하면?","식":["$f\\,'(x)=-3x^{2}+20x-26$","$f\\,'(1)=-9$","$y=-9(x-1)+7=-9x+16$"],"설명":"접선의 기울기는 접점의 $x$ 좌표에서의 미분계수이다. 점 $(1,\\ 7)$ 을 지나는 직선으로 쓴다.","확인":"-9","스킬":"D1"},{"제목":"삼각형의 넓이 S 와 9S 구하기","힌트":"접선의 $x$ 절편과 $y$ 절편으로 직각삼각형의 넓이를 구하면?","식":["$y$ 절편 $16$, $x$ 절편 $\\dfrac{16}{9}$","$S=\\dfrac{1}{2}\\times16\\times\\dfrac{16}{9}=\\dfrac{128}{9}$","$9S=128$"],"설명":"$y=-9x+16$ 에서 $x=0$ 일 때 $y=16$, $y=0$ 일 때 $x=\\frac{16}{9}$ 이다. 두 절편이 직각을 낀 두 변이다.","확인":"128","스킬":"G10"}]},"ns-2063611b9c30":{"길":"위로 볼록한 곡선의 접선·극값의 성질로 보기를 판정한다","단계":[{"제목":"그림에서 곡선의 모양 읽기","힌트":"곡선의 양 끝 값, 부호, 볼록한 방향, 최고점의 위치는?","식":["$f(0)=0,\\ f(c)=0$","$0<x<c$ 에서 $f(x)>0$","위로 볼록하고 $x=b$ 에서 최대이므로 $f\\,'(b)=0$"],"설명":"그래프가 두 점 $(0,\\ 0),\\ (c,\\ 0)$ 에서 $x$ 축과 만나고 그 사이에서는 $x$ 축 위쪽에 있다. 점선이 가리키는 $x=b$ 에서 가장 높다.","확인":null,"스킬":"G9"},{"제목":"ㄱ: f′(b) 와 원점과 잇는 기울기 비교하기","힌트":"$f\\,'(b)$ 와 $\\frac{f(a)}{a}$ 의 부호는 각각 무엇일까?","식":["$f\\,'(b)=0$","$\\dfrac{f(a)}{a}>0$ ($f(a)>0,\\ a>0$)","$f\\,'(b)<\\dfrac{f(a)}{a}$ 이므로 ㄱ 은 거짓"],"설명":"최고점에서의 접선은 $x$ 축과 평행해 기울기가 $0$ 이다. 반면 원점과 $(a,\\ f(a))$ 를 잇는 직선은 오른쪽 위로 향해 기울기가 양수이다.","확인":null,"스킬":"D4"},{"제목":"ㄴ: 접선과 곡선의 위치 비교하기","고비":true,"힌트":"위로 볼록한 곡선은 한 점에서 그은 접선의 위쪽과 아래쪽 중 어느 쪽에 있을까?","식":["$f\\,'(a)(b-a)+f(a)$ : $x=a$ 에서의 접선의 $x=b$ 에서 값","곡선은 접선 아래쪽 : $f(b)<f\\,'(a)(b-a)+f(a)$","ㄴ 은 참"],"설명":"위로 볼록한 곡선은 접선보다 아래에 있다. 접선의 식 $y=f\\,'(a)(x-a)+f(a)$ 에 $x=b$ 를 넣은 값이 보기의 좌변이다.","확인":null,"스킬":"G9"},{"제목":"ㄷ: 부호 따지고 결론 내기","힌트":"$0<x<c$ 일 때 분자 $f(x)-f(c)$ 와 분모 $x-c$ 의 부호는 각각 무엇일까?","식":["분자 $f(x)-f(c)=f(x)>0$","분모 $x-c<0$","분수의 값은 음수이므로 ㄷ 은 거짓","옳은 것은 ㄴ"],"설명":"$f(c)=0$ 이므로 분자는 $f(x)$ 이고 양수이다. 양수를 음수로 나누면 음수이다.","확인":null,"스킬":"G6"}]},"ns-21d71540b995":{"길":"접점 조건 두 식을 연립해 kb 를 k 만의 식으로 만든다","단계":[{"제목":"접점 조건 두 개 쓰기","힌트":"곡선과 직선이 점 $(b,\\ f(b))$ 에서 접하면 함숫값과 미분계수는 각각 무엇이 같을까?","식":["$f(x)=(x-a)^{2}+2,\\ f\\,'(x)=2(x-a)$","$f(b)=kb$ : $(b-a)^{2}+2=kb$","$f\\,'(b)=k$ : $2(b-a)=k$"],"설명":"접점에서는 곡선과 직선의 $y$ 좌표가 같고 접선의 기울기가 $k$ 이다. 곡선의 식은 완전제곱 꼴로 고친다.","확인":null,"스킬":"D7"},{"제목":"kb 를 k 만의 식으로 나타내기","힌트":"$b-a=\\frac{k}{2}$ 를 $(b-a)^{2}+2=kb$ 에 넣으면?","식":["$b-a=\\dfrac{k}{2}$","$kb=\\left(\\dfrac{k}{2}\\right)^{2}+2=\\dfrac{k^{2}}{4}+2$"],"설명":"미분계수 조건에서 $b-a$ 를 $k$ 로 나타내고 함숫값 조건의 $(b-a)^{2}$ 자리에 넣는다.","확인":null,"스킬":"A10"},{"제목":"a 를 k 의 식으로 나타내기","고비":true,"힌트":"$b=a+\\frac{k}{2}$ 를 $kb=\\frac{k^{2}}{4}+2$ 에 넣고 $a$ 에 대해 풀면?","식":["$k\\left(a+\\dfrac{k}{2}\\right)=\\dfrac{k^{2}}{4}+2$","$a+\\dfrac{k}{2}=\\dfrac{k}{4}+\\dfrac{2}{k}$","$a=\\dfrac{2}{k}-\\dfrac{k}{4}$"],"설명":"양변을 $k$ 로 나누고 $\\frac{k}{2}$ 를 이항한다. 접점이 제$1$사분면에 있으므로 $b>0,\\ f(b)>0$ 이고 $k=\\frac{f(b)}{b}>0$ 이어서 $k$ 로 나눌 수 있다.","확인":null,"스킬":"A10"},{"제목":"a→∞ 일 때 k 의 극한 구하기","힌트":"$a=\\frac{2}{k}-\\frac{k}{4}$ 가 한없이 커지려면 $k$ 는 어떤 값에 가까워질까?","식":["$a\\to\\infty$ 이면 $\\dfrac{2}{k}\\to\\infty$","$k\\to0+$"],"설명":"$k>0$ 이고 $\\frac{k}{4}$ 는 작은 값이므로 $a$ 가 커지려면 $\\frac{2}{k}$ 가 커져야 한다. 그러려면 $k$ 가 $0$ 에 가까워진다.","확인":"0","스킬":"A1"},{"제목":"kb 의 극한값 구하기","힌트":"$kb=\\frac{k^{2}}{4}+2$ 에서 $k\\to0+$ 이면 값은?","식":["$\\lim_{a\\to\\infty}kb=\\lim_{k\\to0+}\\left(\\dfrac{k^{2}}{4}+2\\right)$","$=2$"],"설명":"$kb$ 는 $k$ 만의 식으로 나타나 있으므로 $k\\to0+$ 일 때의 극한을 구하면 된다.","확인":"2","스킬":"A1"}]},"ns-303d4e16aba5":{"길":"평행한 두 접점의 중점이 대칭의 중심임을 써서 a, b 를 이차방정식의 근으로 만든다","단계":[{"제목":"평행 조건으로 a+b 구하기","힌트":"두 접선이 평행하면 $f\\,'(a)$ 와 $f\\,'(b)$ 는 어떤 관계일까?","식":["$f\\,'(x)=3x^{2}-12x+11$","$f\\,'(a)=f\\,'(b)$","$3(a-b)(a+b)-12(a-b)=0$","$a+b=4$"],"설명":"평행한 두 직선의 기울기는 같다. 두 점이 서로 다르므로 $a\\ne b$ 이고 $a-b$ 로 나눌 수 있다.","확인":null,"스킬":"D1"},{"제목":"중점 M 의 좌표 구하기","고비":true,"힌트":"$f(x)$ 를 $x-2$ 의 거듭제곱으로 고쳐 쓰면 어떤 점에 대해 대칭일까?","식":["$f(x)=(x-2)^{3}-(x-2)+4$","$f(2+h)+f(2-h)=8$","$\\dfrac{a+b}{2}=2$ 이므로 M 의 $y$ 좌표는 $\\dfrac{f(a)+f(b)}{2}=4$","$\\mathrm{M}(2,\\ 4)$"],"설명":"삼차함수는 변곡점에 대해 점대칭이고 이 함수의 대칭의 중심은 $(2,\\ 4)$ 이다. $a+b=4$ 이므로 두 점 A, B 는 $x=2$ 에서 같은 거리에 있어 중점이 대칭의 중심이 된다.","확인":"4","스킬":"D5"},{"제목":"직선 l 의 기울기 구하기","힌트":"M 에서의 접선의 기울기 $f\\,'(2)$ 와 수직인 직선의 기울기는?","식":["$f\\,'(2)=12-24+11=-1$","$l$ 의 기울기 $\\times(-1)=-1$","$f\\,'(a)=1$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$ 이다. 직선 $l$ 의 기울기는 $f\\,'(a)$ 이다.","확인":"1","스킬":"D1"},{"제목":"a, b 가 만족하는 이차방정식 세우기","힌트":"$f\\,'(a)=f\\,'(b)=1$ 이면 $a,\\ b$ 는 어떤 방정식의 해일까?","식":["$3x^{2}-12x+11=1$","$3x^{2}-12x+10=0$","$a,\\ b$ 는 이 방정식의 서로 다른 두 근"],"설명":"두 접선의 기울기가 같으므로 $f\\,'(b)$ 도 $1$ 이다. 판별식이 양수이므로 서로 다른 두 실근을 가진다.","확인":null,"스킬":"A2"},{"제목":"근과 계수의 관계로 ab 구하기","힌트":"$3x^{2}-12x+10=0$ 의 두 근의 곱은 상수항과 이차항 계수로 어떻게 나타낼까?","식":["$ab=\\dfrac{10}{3}$"],"설명":"이차방정식 $px^{2}+qx+r=0$ 의 두 근의 곱은 $\\frac{r}{p}$ 이다.","확인":"10/3","스킬":"A2"}]},"ns-39d835e06c9b":{"길":"접점을 t 로 두고 원점 대입 후 접선과 곡선을 다시 연립한다","단계":[{"제목":"접점 t 로 두고 원점을 지나는 조건 쓰기","고비":true,"힌트":"접점 $(t,\\ f(t))$ 에서의 접선이 원점을 지나려면 $t$ 가 만족할 식은?","식":["$f\\,'(x)=3x^{2}-6x+3$","$y-(t^{3}-3t^{2}+3t)=(3t^{2}-6t+3)(x-t)$","$(0,\\ 0)$ 대입 : $2t^{3}-3t^{2}=0$","$t^{2}(2t-3)=0$, $t=0,\\ \\dfrac{3}{2}$"],"설명":"접선의 방정식에 $x=0,\\ y=0$ 을 넣어 $t$ 에 대한 방정식을 만든다. 접점이 원점인 경우($t=0$)도 포함된다.","확인":null,"스킬":"D7"},{"제목":"두 접선의 방정식 구하기","힌트":"$t=0$ 과 $t=\\frac{3}{2}$ 에서 접선의 기울기 $f\\,'(t)$ 는 각각 얼마일까?","식":["$f\\,'(0)=3$ : $y=3x$","$f\\,'\\left(\\dfrac{3}{2}\\right)=\\dfrac{3}{4}$ : $y=\\dfrac{3}{4}x$"],"설명":"두 접선 모두 원점을 지나므로 기울기만 구하면 $y=mx$ 꼴로 쓸 수 있다.","확인":null,"스킬":"D1"},{"제목":"접선 y=3x 와 곡선의 교점 구하기","힌트":"$x^{3}-3x^{2}+3x=3x$ 를 풀어 원점이 아닌 교점의 $y$ 좌표는?","식":["$x^{3}-3x^{2}=0$","$x^{2}(x-3)=0$","원점이 아닌 교점 $(3,\\ 9)$"],"설명":"$x=0$ 은 원점이므로 제외하고 $x=3$ 에서 $y=3x=9$ 이다.","확인":"9","스킬":"G1"},{"제목":"접선 y=3x/4 와 곡선의 교점 구하기","힌트":"$x^{3}-3x^{2}+3x=\\frac{3}{4}x$ 를 인수분해하면 원점이 아닌 근은?","식":["$x^{3}-3x^{2}+\\dfrac{9}{4}x=0$","$x\\left(x-\\dfrac{3}{2}\\right)^{2}=0$","원점이 아닌 교점 $\\left(\\dfrac{3}{2},\\ \\dfrac{9}{8}\\right)$"],"설명":"이 접선은 $x=\\frac{3}{2}$ 에서 곡선에 접하므로 그 점이 중근이다. $y=\\frac{3}{4}\\times\\frac{3}{2}=\\frac{9}{8}$ 이다.","확인":"9/8","스킬":"G1"},{"제목":"y 좌표의 곱 T 와 16T/9 구하기","힌트":"$T=9\\times\\frac{9}{8}$ 을 구한 뒤 $\\frac{16}{9}$ 을 곱하면?","식":["$T=9\\times\\dfrac{9}{8}=\\dfrac{81}{8}$","$\\dfrac{16}{9}T=\\dfrac{16}{9}\\times\\dfrac{81}{8}=18$"],"설명":"원점이 아닌 교점은 두 개이고 $y$ 좌표는 각각 $9,\\ \\frac{9}{8}$ 이다.","확인":"18","스킬":"G1"}]},"ns-3b3a2d0d11e9":{"길":"|f′(a)|=m 을 f′ 의 그래프와 수평선 y=±m 의 교점 수로 센다","단계":[{"제목":"할선의 기울기 m 구하기","힌트":"$f(2)=0$ 이므로 $\\frac{f(t)-f(2)}{t-2}$ 에서 $t-2$ 를 약분하면?","식":["$f(2)=0$","$\\dfrac{f(t)-f(2)}{t-2}=\\dfrac{k(t-2)(t-8)^{2}}{t-2}=k(t-8)^{2}$","$m=k(t-8)^{2}\\ge0$"],"설명":"$t>2$ 이므로 $t-2\\ne0$ 이어서 약분된다. 이 값을 $m$ 으로 두면 $m$ 은 $0$ 이상이다.","확인":null,"스킬":"D2"},{"제목":"f′(x) 의 꼴과 최솟값 구하기","힌트":"곱의 미분법으로 $f\\,'(x)$ 를 구해 인수분해하면?","식":["$f\\,'(x)=k(x-8)^{2}+2k(x-2)(x-8)$","$f\\,'(x)=3k(x-4)(x-8)$","$f\\,'(6)=-12k$ 가 $f\\,'$ 의 최솟값"],"설명":"$f\\,'(x)$ 는 아래로 볼록한 이차함수이고 $x=4,\\ 8$ 에서 $0$ 이다. 대칭축이 $x=6$ 이므로 그곳에서 최솟값을 가진다.","확인":null,"스킬":"D13"},{"제목":"m 의 크기에 따라 n(P_t) 세기","고비":true,"힌트":"$|f\\,'(a)|=m$ 은 $f\\,'(a)=m$ 또는 $f\\,'(a)=-m$ 이다. 포물선 $y=f\\,'(x)$ 와 수평선 $y=\\pm m$ 의 교점은 각각 몇 개일까?","식":["$0<m<12k$ : $y=m,\\ y=-m$ 모두 $2$ 개씩, $n(P_{t})=4$","$m=12k$ : $y=m$ 은 $2$ 개, $y=-m$ 은 $1$ 개, $n(P_{t})=3$","$m=0$ 또는 $m>12k$ : $n(P_{t})=2$"],"설명":"$m\\ge0$ 이므로 $y=m$ 은 항상 포물선과 두 점에서 만난다. $y=-m$ 은 $-m>-12k$ 일 때 두 점, $-m=-12k$ 일 때 한 점(꼭짓점)에서 만난다. $m=0$ 이면 두 직선이 겹쳐 $2$ 개이다.","확인":null,"스킬":"G1"},{"제목":"ㄱ: t=8 일 때 원소의 개수 구하기","힌트":"$t=8$ 이면 $m$ 은 얼마이고 $f\\,'(a)=0$ 의 해는?","식":["$m=k(8-8)^{2}=0$","$f\\,'(a)=0$ 에서 $a=4,\\ 8$","$n(P_{t})=2$ 이므로 ㄱ 은 참"],"설명":"$m=0$ 인 경우이므로 앞 단계의 표에서 $n(P_{t})=2$ 인 경우에 해당한다.","확인":null,"스킬":"G1"},{"제목":"ㄴ: n(P_t)=4 일 때 |f′(a)| 비교하기","힌트":"$n(P_{t})=4$ 일 때 $m$ 의 범위와 $|f\\,'(6)|$ 의 값은?","식":["$n(P_{t})=4$ 이면 $0<m<12k$","$|f\\,'(a)|=m<12k=|f\\,'(6)|$","ㄴ 은 참"],"설명":"$a\\in P_{t}$ 이면 $|f\\,'(a)|=m$ 이다. $|f\\,'(6)|=12k$ 이므로 $m$ 의 범위에서 바로 부등식이 나온다.","확인":null,"스킬":"G6"},{"제목":"ㄷ: n(P_t)=3 일 때 a₁a₃ 구하고 결론 내기","힌트":"$m=12k$ 일 때 $f\\,'(a)=-12k$ 와 $f\\,'(a)=12k$ 의 해는?","식":["$f\\,'(a)=-12k$ : $a=6$","$3k(x-4)(x-8)=12k$ : $x^{2}-12x+28=0$","두 근 $a_{1},\\ a_{3}$ 의 곱 $a_{1}a_{3}=28$","ㄱ, ㄴ, ㄷ 모두 참"],"설명":"$a_{2}=6$ 이고 나머지 두 원소는 이차방정식의 두 근이다. 두 근 $6\\pm2\\sqrt{2}$ 가 각각 $6$ 의 양쪽에 있어 $a_{1},\\ a_{3}$ 이고, 근과 계수의 관계로 곱이 정해진다.","확인":null,"스킬":"A2"}]},"ns-3dd7e5da93b5":{"길":"밑변이 고정이므로 높이가 최대인 곳, 즉 AB 에 평행한 접선의 접점을 찾는다","단계":[{"제목":"직선 AB 의 기울기 구하기","힌트":"두 점 $\\mathrm{A}(3,\\ 0),\\ \\mathrm{B}(0,\\ -3)$ 을 지나는 직선의 기울기는?","식":["$\\dfrac{0-(-3)}{3-0}=1$","직선 AB : $y=x-3$"],"설명":"삼각형 ABP 에서 밑변 AB 는 고정되어 있다. 따라서 점 P 와 직선 AB 사이의 거리가 최대일 때 넓이가 최대이다.","확인":"1","스킬":"G10"},{"제목":"접선의 기울기 조건 세우기","고비":true,"힌트":"직선 AB 와의 거리가 최대인 점에서의 접선은 직선 AB 와 어떤 관계일까?","식":["접선 $\\parallel$ 직선 AB","$f\\,'(c)=2c-2=1$"],"설명":"$0<c<3$ 에서 곡선은 직선 AB 아래쪽에 있다. 직선 AB 와 평행한 직선을 아래로 밀다가 곡선에 접하는 점이 거리가 최대인 점이다. 접선의 기울기는 직선 AB 의 기울기와 같다.","확인":null,"스킬":"D1"},{"제목":"c 의 값 구하기","힌트":"$2c-2=1$ 을 풀어 $0<c<3$ 을 만족하는지 확인하면?","식":["$2c=3$","$c=\\dfrac{3}{2}$"],"설명":"구한 값이 $0<c<3$ 안에 있으므로 조건에 맞는다.","확인":"3/2","스킬":"D1"}]},"ns-4232e1df0bb8":{"길":"도함수의 증감과 인수분해로 세 보기를 차례로 판정한다","단계":[{"제목":"ㄱ: f′ 의 증감 확인하기","힌트":"$f\\,'(x)=-2x+1$ 은 증가함수일까, 감소함수일까?","식":["$f\\,'(x)=-2x+1$","$f\\,'$ 은 감소함수이므로 $a<b$ 에서 $f\\,'(a)>f\\,'(b)$","ㄱ 은 참"],"설명":"일차함수 $-2x+1$ 은 $x$ 의 계수가 음수이므로 $x$ 가 커질수록 값이 작아진다.","확인":null,"스킬":"D4"},{"제목":"ㄴ: f′(x)/x 의 증감 확인하기","고비":true,"힌트":"$\\frac{f\\,'(x)}{x}$ 를 $x$ 의 식으로 쓰면 $0<x<1$ 에서 증가할까, 감소할까?","식":["$\\dfrac{f\\,'(x)}{x}=\\dfrac{-2x+1}{x}=\\dfrac{1}{x}-2$","$0<x<1$ 에서 $\\dfrac{1}{x}$ 은 감소","$\\dfrac{f\\,'(a)}{a}>\\dfrac{f\\,'(b)}{b}$ 이므로 ㄴ 은 참"],"설명":"분자를 분모로 나누어 $\\frac{1}{x}-2$ 로 고치면 증감이 바로 보인다. $0<a<b$ 이면 $\\frac{1}{a}>\\frac{1}{b}$ 이다.","확인":null,"스킬":"D13"},{"제목":"ㄷ: 함숫값의 차와 x 의 차 비교하고 결론 내기","힌트":"$f(b)-f(a)$ 를 $b-a$ 를 공통인수로 묶어 정리하면?","식":["$f(b)-f(a)=-(b^{2}-a^{2})+(b-a)$","$=(b-a)\\left(1-a-b\\right)$","$a+b>0$ 이므로 $f(b)-f(a)<b-a$","ㄷ 은 거짓, 옳은 것은 ㄱ, ㄴ"],"설명":"$b-a>0$ 이고 $1-(a+b)<1$ 이므로 $(b-a)(1-a-b)$ 는 $b-a$ 보다 작다. 곡선이 직선 $y=x$ 의 아래쪽에서 기울기가 $1$ 보다 작게 오른다는 뜻이다.","확인":null,"스킬":"G9"}]},"ns-4a61918ed4de":{"길":"같은 점에서 접한다는 조건을 함숫값과 미분계수 두 식으로 옮긴다","단계":[{"제목":"점 (1, 3) 을 지나는 조건 쓰기","힌트":"두 곡선의 식에 $x=1,\\ y=3$ 을 넣으면 $a,\\ b,\\ c$ 에 대한 식은?","식":["$1+a+b=3$, $a+b=2$","$1+c=3$, $c=2$"],"설명":"두 곡선이 모두 점 $(1,\\ 3)$ 을 지나므로 좌표를 대입한다. 두 번째 식에서 $c$ 가 바로 정해진다.","확인":null,"스킬":"D1"},{"제목":"접선의 기울기가 같다는 조건으로 a 구하기","고비":true,"힌트":"A, B 가 같은 직선 C 에 접하므로 $x=1$ 에서 두 곡선의 미분계수는 어떤 관계일까?","식":["$y'=3x^{2}+a$ 에서 기울기 $3+a$","$y'=2x+c$ 에서 기울기 $2+c=4$","$3+a=4$, $a=1$"],"설명":"같은 점에서 같은 직선에 접하면 접선의 기울기가 같다. $c=2$ 를 넣어 B 의 기울기를 먼저 구한다.","확인":"1","스킬":"D1"},{"제목":"b 와 a−b+c 구하기","힌트":"$a+b=2$ 에 $a=1$ 을 넣으면 $b$ 는? 그다음 $a-b+c$ 는?","식":["$b=2-a=1$","$a-b+c=1-1+2=2$"],"설명":"구한 $a,\\ b,\\ c$ 를 $a-b+c$ 에 대입한다.","확인":"2","스킬":"A10"}]},"ns-4d464bd4053b":{"길":"점 (1, 3) 이 곡선 밖에 있으니 접점을 t 로 두고 l 을 먼저 정한다","단계":[{"제목":"접선 l 의 접점 구하기","고비":true,"힌트":"접점을 $(t,\\ f(t))$ 로 두고 접선의 식에 점 $(1,\\ 3)$ 을 넣으면 $t$ 에 대한 식은?","식":["$f\\,'(t)=3t^{2}-6t+6$","$3=(3t^{2}-6t+6)(1-t)+t^{3}-3t^{2}+6t+1$","$t^{3}-3t^{2}+3t-2=0$","$(t-2)(t^{2}-t+1)=0$, $t=2$"],"설명":"$f(1)=5\\ne3$ 이므로 점 $(1,\\ 3)$ 은 곡선 위의 점이 아니다. 접선 위에 있다는 조건으로 접점의 $x$ 좌표를 구한다. $t^{2}-t+1=0$ 은 실근이 없다.","확인":"2","스킬":"D7"},{"제목":"접선 l 의 기울기 구하기","힌트":"접점의 $x$ 좌표 $t=2$ 에서의 미분계수는?","식":["$f\\,'(2)=12-12+6=6$"],"설명":"접선의 기울기는 접점에서의 미분계수이다. 직선 $m$ 은 $l$ 과 평행하므로 기울기가 같다.","확인":"6","스킬":"D1"},{"제목":"기울기가 6 인 다른 접점 찾기","힌트":"$f\\,'(t)=6$ 의 해 중 $l$ 의 접점이 아닌 것은?","식":["$3t^{2}-6t+6=6$","$3t(t-2)=0$","$t=0$ 또는 $t=2$"],"설명":"기울기가 $6$ 인 접선은 두 개이고 $t=2$ 가 직선 $l$ 의 접점이므로 직선 $m$ 의 접점은 $t=0$ 이다.","확인":"0","스킬":"D5"},{"제목":"직선 m 의 방정식과 k 구하기","힌트":"접점 $(0,\\ f(0))$ 에서 기울기 $6$ 인 직선의 식에 $x=1$ 을 넣으면?","식":["$f(0)=1$","$m$ : $y=6x+1$","$k=6\\times1+1=7$"],"설명":"접점이 $(0,\\ 1)$ 이고 기울기가 $6$ 이므로 $y=6x+1$ 이다. 이 직선이 점 $(1,\\ k)$ 를 지난다.","확인":"7","스킬":"D1"}]},"ns-52aaaa3a5435":{"길":"두 접점의 접선이 같은 직선이 되도록 기울기와 y 절편을 맞춘다","단계":[{"제목":"두 곡선의 접선을 각각 쓰기","힌트":"$f$ 의 접점을 $(t,\\ t^{2}-t)$, $g$ 의 접점을 $(s,\\ -s^{2}+3s-4)$ 로 두고 접선을 쓰면?","식":["$f\\,'(x)=2x-1$ : $y=(2t-1)(x-t)+t^{2}-t=(2t-1)x-t^{2}$","$g\\,'(x)=-2x+3$ : $y=(-2s+3)(x-s)-s^{2}+3s-4=(-2s+3)x+s^{2}-4$"],"설명":"각 접선을 $x$ 에 대해 정리하면 기울기와 $y$ 절편이 한눈에 보인다.","확인":null,"스킬":"D7"},{"제목":"같은 직선이 될 조건 세우기","힌트":"두 직선이 일치하려면 기울기와 $y$ 절편이 각각 어떻게 되어야 할까?","식":["$2t-1=-2s+3$, $t+s=2$","$-t^{2}=s^{2}-4$, $t^{2}+s^{2}=4$"],"설명":"같은 직선이므로 기울기가 같고 $y$ 절편도 같다. 두 식을 정리해 $t+s$ 와 $t^{2}+s^{2}$ 의 값을 얻는다.","확인":null,"스킬":"A10"},{"제목":"연립해서 접점의 짝 구하기","고비":true,"힌트":"$(t+s)^{2}=t^{2}+s^{2}+2ts$ 에 앞의 두 값을 넣으면 $ts$ 는?","식":["$4=4+2ts$","$ts=0$","$(t,\\ s)=(2,\\ 0)$ 또는 $(0,\\ 2)$"],"설명":"$t+s=2$ 이고 $ts=0$ 이므로 두 수 중 하나는 $0$ 이고 다른 하나는 $2$ 이다.","확인":"0","스킬":"A2"},{"제목":"공통 접선 두 개의 방정식 구하기","힌트":"$(t,\\ s)=(0,\\ 2)$ 와 $(2,\\ 0)$ 을 접선의 식에 각각 넣으면?","식":["$t=0,\\ s=2$ : $y=-x$","$t=2,\\ s=0$ : $y=3x-4$"],"설명":"$y=(2t-1)x-t^{2}$ 에 $t=0$ 을 넣으면 $y=-x$ 이고, $t=2$ 를 넣으면 $y=3x-4$ 이다.","확인":null,"스킬":"D1"},{"제목":"교점과 a−b 구하기","힌트":"두 직선의 식을 같게 놓아 교점을 구하면?","식":["$-x=3x-4$, $x=1$","교점 $(1,\\ -1)$","$a-b=1-(-1)=2$"],"설명":"교점의 $x$ 좌표를 구한 뒤 $y=-x$ 에 넣어 $y$ 좌표를 구한다.","확인":"2","스킬":"G1"}]},"ns-5a3347c9d0d3":{"길":"극한식을 f′(2)−g′(2) 로 쪼개 g′(2) 를 먼저 구한다","단계":[{"제목":"f(2) 와 g(2) 의 값 구하기","고비":true,"힌트":"$x\\to2$ 일 때 분모가 $0$ 으로 가는데 극한이 있으면 분자는 어떻게 될까?","식":["$f(2)-g(2)=0$, $f(2)=g(2)$","$g(2)=8f(2)-7$","$f(2)=8f(2)-7$, $f(2)=g(2)=1$"],"설명":"분모가 $0$ 으로 가는데 극한값이 존재하므로 분자도 $0$ 으로 간다. 조건 (가) 에 $x=2$ 를 넣어 $g(2)$ 와 $f(2)$ 의 관계를 얻는다.","확인":"1","스킬":"D3"},{"제목":"극한식을 미분계수의 차로 바꾸기","힌트":"$f(2)=g(2)$ 를 이용해 분자를 $f(x)-f(2)$ 와 $g(x)-g(2)$ 로 나누면?","식":["$\\lim_{x\\to2}\\left\\{\\dfrac{f(x)-f(2)}{x-2}-\\dfrac{g(x)-g(2)}{x-2}\\right\\}=f\\,'(2)-g\\,'(2)$","$f\\,'(2)-g\\,'(2)=2$"],"설명":"$f(x)-g(x)=\\{f(x)-f(2)\\}-\\{g(x)-g(2)\\}$ 이다. 각 항이 미분계수의 정의 꼴이 된다.","확인":null,"스킬":"D3"},{"제목":"g(x) 를 미분해 x=2 대입하기","힌트":"곱의 미분법으로 $g\\,'(x)$ 를 쓰고 $x=2$ 를 넣으면?","식":["$g\\,'(x)=3x^{2}f(x)+x^{3}f\\,'(x)$","$g\\,'(2)=12f(2)+8f\\,'(2)=12+8f\\,'(2)$"],"설명":"$f(2)=1$ 을 넣어 $g\\,'(2)$ 를 $f\\,'(2)$ 로 나타낸다.","확인":null,"스킬":"D13"},{"제목":"연립해서 g′(2) 구하기","힌트":"$f\\,'(2)=g\\,'(2)+2$ 를 $g\\,'(2)=12+8f\\,'(2)$ 에 넣으면?","식":["$g\\,'(2)=12+8\\{g\\,'(2)+2\\}=28+8g\\,'(2)$","$-7g\\,'(2)=28$","$g\\,'(2)=-4$"],"설명":"$f\\,'(2)$ 를 소거하면 $g\\,'(2)$ 만 남는 일차방정식이 된다.","확인":"-4","스킬":"A10"},{"제목":"접선의 방정식과 a+b 구하기","힌트":"점 $(2,\\ g(2))$ 를 지나고 기울기가 $g\\,'(2)$ 인 직선의 식은?","식":["$y=-4(x-2)+1=-4x+9$","$a=-4,\\ b=9$","$a+b=5$"],"설명":"접점의 $y$ 좌표는 $g(2)=1$ 이다. 직선의 식을 $y=ax+b$ 꼴로 정리해 계수를 읽는다.","확인":"5","스킬":"D1"}]},"ns-5e4ea06ee25a":{"길":"평균변화율을 평균값 정리로 도함수의 값으로 바꿔 범위를 잡는다","단계":[{"제목":"평균변화율을 도함수의 값으로 바꾸기","고비":true,"힌트":"$[1,\\ 4]$ 안의 서로 다른 두 수 $\\alpha<\\beta$ 의 평균변화율과 같은 미분계수는 어디에 있을까?","식":["$m=\\dfrac{f(\\beta)-f(\\alpha)}{\\beta-\\alpha}=f\\,'(\\gamma)$","$\\gamma$ 는 $(\\alpha,\\ \\beta)$ 안에 있으므로 $1<\\gamma<4$"],"설명":"다항함수는 연속이고 미분가능하므로 평균값 정리를 쓸 수 있다. $\\gamma$ 가 $(1,\\ 4)$ 안의 값이면 평균변화율 $m$ 의 범위는 $f\\,'(\\gamma)$ 의 범위와 같다.","확인":null,"스킬":"D2"},{"제목":"f′(x) 의 증감 확인하기","힌트":"$f\\,'(x)$ 를 완전제곱 꼴로 쓰면 $x>1$ 에서 증가할까, 감소할까?","식":["$f\\,'(x)=x^{2}-2x+2=(x-1)^{2}+1$","$x\\ge1$ 에서 $f\\,'(x)$ 는 증가"],"설명":"꼭짓점이 $x=1$ 인 아래로 볼록한 포물선이므로 $1<x<4$ 에서 $x$ 가 커질수록 값이 커진다.","확인":null,"스킬":"A6"},{"제목":"양 끝에서 f′ 의 값 구하기","힌트":"$f\\,'(1)$ 과 $f\\,'(4)$ 는 각각 얼마일까?","식":["$f\\,'(1)=1$","$f\\,'(4)=(4-1)^{2}+1=10$","$1<f\\,'(\\gamma)<10$"],"설명":"증가하는 구간에서 열린구간 $(1,\\ 4)$ 의 $\\gamma$ 는 양 끝값 사이의 값을 가진다. 양 끝은 포함되지 않는다.","확인":"10","스킬":"D4"},{"제목":"b−a 구하기","힌트":"$a<m<b$ 와 $1<m<10$ 을 비교하면 $a,\\ b$ 는?","식":["$a=1,\\ b=10$","$b-a=9$"],"설명":"$m$ 이 가질 수 있는 값의 범위가 $1<m<10$ 이다.","확인":"9","스킬":"D2"}]},"ns-5f838c1309aa":{"길":"접선이 다시 만나는 점의 위치를 구해 기울기의 곱 −1 을 t² 의 이차방정식으로 쓴다","단계":[{"제목":"접선 l 과 곡선의 다른 교점 Q 구하기","힌트":"접점에서는 중근이므로 접선과 곡선의 차는 어떤 꼴일까? 세 근의 합은?","식":["$\\mathrm{P}(t,\\ t^{3}-at)$, $l$ : $y=(3t^{2}-a)(x-t)+t^{3}-at$","$x^{3}-ax-\\{(3t^{2}-a)(x-t)+t^{3}-at\\}=(x-t)^{2}(x+2t)$","Q 의 $x$ 좌표 $-2t$"],"설명":"접선과 곡선의 방정식의 차는 $x^{2}$ 항이 없는 삼차식이다. 근이 $t,\\ t,\\ q$ 이면 세 근의 합이 $0$ 이어서 $q=-2t$ 이다.","확인":null,"스킬":"D5"},{"제목":"두 접선의 기울기 구하기","힌트":"$f\\,'(x)=3x^{2}-a$ 에 $x=t$ 와 $x=-2t$ 를 넣으면?","식":["$l$ 의 기울기 $f\\,'(t)=3t^{2}-a$","$m$ 의 기울기 $f\\,'(-2t)=12t^{2}-a$"],"설명":"접선의 기울기는 접점의 $x$ 좌표에서의 미분계수이다.","확인":null,"스킬":"D1"},{"제목":"수직 조건을 t 의 식으로 쓰기","힌트":"수직인 두 직선의 기울기의 곱은 얼마일까? 전개하면?","식":["$(3t^{2}-a)(12t^{2}-a)=-1$","$36t^{4}-15at^{2}+a^{2}+1=0$"],"설명":"기울기의 곱이 $-1$ 이어야 두 직선이 수직이다. 괄호를 전개해 $t^{2}$ 의 내림차순으로 정리한다.","확인":null,"스킬":"A10"},{"제목":"t² 에 대한 이차방정식이 실근을 가질 조건 쓰기","고비":true,"힌트":"$t^{2}=u$ 로 두면 $u$ 에 대한 이차방정식의 판별식은? $u$ 는 어떤 부호여야 할까?","식":["$36u^{2}-15au+a^{2}+1=0$ ($u=t^{2}\\ge0$)","$D=(15a)^{2}-4\\cdot36(a^{2}+1)=81a^{2}-144\\ge0$","두 근의 합 $\\dfrac{15a}{36}>0$, 곱 $\\dfrac{a^{2}+1}{36}>0$"],"설명":"실수 $t$ 가 있으려면 $u=t^{2}$ 이 $0$ 이상인 실근이어야 한다. 판별식이 $0$ 이상이면 두 근의 합과 곱이 모두 양수이므로 근이 모두 양수이다.","확인":null,"스킬":"G2"},{"제목":"a 의 최솟값 구하기","힌트":"$81a^{2}\\ge144$ 와 $a>0$ 에서 $a$ 의 범위는?","식":["$a^{2}\\ge\\dfrac{16}{9}$","$a\\ge\\dfrac{4}{3}$"],"설명":"$a$ 가 양수이므로 부등식의 양변에 제곱근을 취하면 $a$ 의 하한이 정해지고 그 값이 최솟값이다.","확인":"4/3","스킬":"G2"}]},"ns-616a4bf19b96":{"길":"a+c=8 이면 할선의 기울기가 고정됨을 이용해 다섯 보기를 가린다","단계":[{"제목":"두 점 사이의 평균변화율 구하기","고비":true,"힌트":"$f(c)-f(a)$ 를 $c-a$ 로 나눠 인수분해하면?","식":["$f(x)=x^{2}-5x+4$","$\\dfrac{f(c)-f(a)}{c-a}=\\dfrac{(c^{2}-a^{2})-5(c-a)}{c-a}=a+c-5$","$a+c=8$ 이므로 평균변화율 $=3$"],"설명":"$c^{2}-a^{2}=(c-a)(c+a)$ 이므로 $c-a$ 가 약분된다. $1<a<c$ 이므로 $c-a>0$ 이다.","확인":"3","스킬":"G9"},{"제목":"① 과 ③ 판정하기","힌트":"$f(c)-f(a)=3(c-a)$ 에서 $c-a>0$ 이므로 부호와 $c-a$ 와의 크기는?","식":["$f(c)-f(a)=3(c-a)>0$","① $f(a)<f(c)$ 참","$3(c-a)>c-a$","③ $f(c)-f(a)<c-a$ 거짓"],"설명":"양수 $c-a$ 에 $3$ 을 곱하면 $c-a$ 보다 커진다.","확인":null,"스킬":"G9"},{"제목":"② 와 ④ 판정하기","힌트":"$f\\,'(x)=2x-5$ 의 증감과, $\\frac{f(x)}{x}=x-5+\\frac{4}{x}$ 의 두 점 사이의 차는?","식":["$f\\,'(x)=2x-5$ 는 증가이므로 $f\\,'(a)<f\\,'(c)$, ② 참","$\\dfrac{f(c)}{c}-\\dfrac{f(a)}{a}=(c-a)\\left(1-\\dfrac{4}{ac}\\right)$","$ac=a(8-a)=16-(a-4)^{2}>7>4$ 이므로 ④ 참"],"설명":"$\\frac{4}{c}-\\frac{4}{a}=-\\frac{4(c-a)}{ac}$ 이므로 $c-a$ 로 묶인다. $1<a<4$ 이면 $(a-4)^{2}<9$ 이다.","확인":null,"스킬":"G9"},{"제목":"⑤ 판정하고 결론 내기","힌트":"$f\\,'(4)$ 는 얼마이고 $3$ 과 비교하면?","식":["$f\\,'(4)=2\\times4-5=3$","$\\dfrac{f(c)-f(a)}{c-a}=3<3$ 은 성립하지 않으므로 ⑤ 거짓","옳지 않은 것은 ③, ⑤"],"설명":"할선의 기울기와 $f\\,'(4)$ 가 같아 부등호가 성립하지 않는다.","확인":null,"스킬":"D2"}]},"ns-621b549d4056":{"길":"평균값 정리로 차를 3 배의 도함수 값으로 바꾸고 x→∞ 를 적용한다","단계":[{"제목":"평균값 정리로 f(x+1)−f(x−2) 를 도함수로 바꾸기","힌트":"구간 $[x-2,\\ x+1]$ 의 평균변화율과 같은 미분계수를 갖는 $c$ 는 어디에 있을까?","식":["$\\dfrac{f(x+1)-f(x-2)}{(x+1)-(x-2)}=f\\,'(c)$, $x-2<c<x+1$","$f(x+1)-f(x-2)=3f\\,'(c)$"],"설명":"$f$ 는 모든 실수에서 미분가능하므로 닫힌구간에서 연속이고 열린구간에서 미분가능하다. 구간의 길이가 $3$ 이라 분모가 $3$ 이다.","확인":null,"스킬":"D2"},{"제목":"x→∞ 일 때 c 의 변화 확인하기","고비":true,"힌트":"$c>x-2$ 이면 $x\\to\\infty$ 일 때 $c$ 는 어떻게 될까?","식":["$c>x-2$ 이므로 $x\\to\\infty$ 이면 $c\\to\\infty$","$\\lim_{c\\to\\infty}f\\,'(c)=1$"],"설명":"$c$ 가 $x-2$ 보다 크므로 $x$ 가 한없이 커지면 $c$ 도 한없이 커진다. 그러면 $f\\,'(c)$ 의 극한은 조건에서 주어진 $\\lim_{x\\to\\infty}f\\,'(x)$ 와 같다.","확인":null,"스킬":"D2"},{"제목":"극한값 구하기","힌트":"$f(x+1)-f(x-2)=3f\\,'(c)$ 의 극한은 얼마일까?","식":["$\\lim_{x\\to\\infty}\\{f(x+1)-f(x-2)\\}=3\\lim_{c\\to\\infty}f\\,'(c)=3\\times1$","$=3$"],"설명":"상수 $3$ 은 극한 밖으로 나온다.","확인":"3","스킬":"D2"}]},"ns-691dca5fdd35":{"길":"f(x)+2x 로 두면 A, B 가 두 근이라 두 점의 접선 기울기가 부호만 반대가 된다","단계":[{"제목":"g(x)=f(x)+2x 로 두고 인수분해 꼴 쓰기","힌트":"$f(x)=-2x$ 의 두 해가 $\\alpha,\\ \\beta$ 이다. $g(x)=f(x)+2x$ 는 어떤 꼴로 쓸 수 있을까?","식":["$\\mathrm{A}(\\alpha,\\ -2\\alpha),\\ \\mathrm{B}(\\beta,\\ -2\\beta)$","$g(\\alpha)=g(\\beta)=0$","$g(x)=a(x-\\alpha)(x-\\beta)$"],"설명":"점 A, B 의 $x$ 좌표가 $f(x)+2x=0$ 의 두 근이다. $g(x)$ 는 $f(x)$ 와 이차항의 계수가 같은 이차함수이므로 두 근으로 인수분해된다.","확인":null,"스킬":"A2"},{"제목":"g′ 의 두 근에서의 값 비교하기","고비":true,"힌트":"곱의 미분법으로 $g\\,'(x)$ 를 구해 $x=\\alpha$ 와 $x=\\beta$ 를 넣으면 두 값은 어떤 관계일까?","식":["$g\\,'(x)=a(x-\\beta)+a(x-\\alpha)$","$g\\,'(\\alpha)=a(\\alpha-\\beta)$","$g\\,'(\\beta)=a(\\beta-\\alpha)=-g\\,'(\\alpha)$"],"설명":"$\\alpha-\\beta$ 와 $\\beta-\\alpha$ 는 부호만 반대이므로 두 점에서의 $g$ 의 접선의 기울기도 부호만 반대이다.","확인":null,"스킬":"A2"},{"제목":"g′(α) 의 값 구하기","힌트":"$g\\,'(x)=f\\,'(x)+2$ 이므로 $f\\,'(\\alpha)=-6$ 을 넣으면?","식":["$g\\,'(x)=f\\,'(x)+2$","$g\\,'(\\alpha)=f\\,'(\\alpha)+2=-6+2=-4$"],"설명":"$2x$ 의 미분은 $2$ 이다. 점 A 에서 $f$ 의 접선의 기울기가 $-6$ 이다.","확인":"-4","스킬":"D1"},{"제목":"점 B 에서의 접선의 기울기 구하기","힌트":"$g\\,'(\\beta)=-g\\,'(\\alpha)$ 에서 $f\\,'(\\beta)$ 는?","식":["$g\\,'(\\beta)=4$","$f\\,'(\\beta)+2=4$","$f\\,'(\\beta)=2$"],"설명":"$g\\,'(\\beta)=f\\,'(\\beta)+2$ 이므로 $2$ 를 빼면 점 B 에서의 접선의 기울기가 나온다.","확인":"2","스킬":"D1"}]},"ns-6993aa7dada7":{"길":"교점에서 그은 두 접점이 한 이차방정식의 두 근임을 이용해 k 를 구한다","단계":[{"제목":"교점에서 그은 접선의 접점이 만족할 식 세우기","힌트":"두 접선의 교점을 $(a,\\ 0)$ 이라 하고 접점 $(t,\\ t^{2}+k)$ 에서의 접선이 이 점을 지나면?","식":["$f\\,'(x)=2x$","접선 $y=2t(x-t)+t^{2}+k$","$(a,\\ 0)$ 대입 : $0=2t(a-t)+t^{2}+k$","$t^{2}-2at-k=0$"],"설명":"접선의 식에 교점의 좌표를 넣어 $t$ 에 대한 이차방정식을 얻는다.","확인":null,"스킬":"D7"},{"제목":"두 접점을 근으로 보고 근과 계수의 관계 쓰기","고비":true,"힌트":"두 접선의 접점의 $x$ 좌표를 $t_{1},\\ t_{2}$ 라 하면 이 이차방정식과 어떤 관계일까?","식":["$t_{1},\\ t_{2}$ 는 $t^{2}-2at-k=0$ 의 두 근","$t_{1}+t_{2}=2a,\\ t_{1}t_{2}=-k$"],"설명":"교점 $(a,\\ 0)$ 을 지나는 접선이 두 개이므로 접점도 두 개이고 이 이차방정식의 서로 다른 두 근이다.","확인":null,"스킬":"A2"},{"제목":"수직 조건으로 두 근의 곱 구하기","힌트":"두 접선의 기울기 $2t_{1},\\ 2t_{2}$ 가 수직이면 곱은 얼마일까?","식":["$2t_{1}\\times2t_{2}=-1$","$t_{1}t_{2}=-\\dfrac{1}{4}$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$ 이다.","확인":"-1/4","스킬":"C7"},{"제목":"k 의 값 구하기","힌트":"$t_{1}t_{2}=-k$ 와 $t_{1}t_{2}=-\\frac{1}{4}$ 를 비교하면?","식":["$-k=-\\dfrac{1}{4}$","$k=\\dfrac{1}{4}$"],"설명":"근과 계수의 관계에서 구한 곱과 수직 조건에서 구한 곱이 같다.","확인":"1/4","스킬":"A2"}]},"ns-6b5f7b7a9809":{"길":"위로 볼록한 곡선의 기울기 성질과 평균값 정리로 세 보기를 판정한다","단계":[{"제목":"그림에서 곡선의 성질 읽기","힌트":"곡선이 원점을 지나는지, 위로 볼록한지, 직선 $y=x$ 와의 관계는?","식":["$f(0)=0$","$y=x$ 는 원점에서 곡선에 접하므로 $f\\,'(0)=1$","위로 볼록하므로 $f\\,'$ 은 감소, $x>0$ 에서 $f\\,'(x)<1$"],"설명":"그림에서 곡선은 원점에서 직선 $y=x$ 와 만나며 그 직선 아래쪽에 있다. 위로 볼록한 곡선에서는 $x$ 가 커질수록 접선의 기울기가 작아진다.","확인":null,"스킬":"G9"},{"제목":"ㄱ: 원점과 잇는 기울기 비교하기","고비":true,"힌트":"$\\frac{f(a)}{a}$ 는 원점과 $(a,\\ f(a))$ 를 잇는 기울기이다. $x$ 가 커지면 이 기울기는 어떻게 변할까?","식":["$\\dfrac{f(x)}{x}=\\dfrac{f(x)-f(0)}{x-0}$","$0<a<b$ 이면 $\\dfrac{f(a)}{a}>\\dfrac{f(b)}{b}$","ㄱ 은 거짓"],"설명":"위로 볼록한 곡선에서는 원점과 잇는 기울기가 $x$ 가 클수록 작아진다. 보기 ㄱ 의 부등호는 반대 방향이다.","확인":null,"스킬":"G9"},{"제목":"ㄴ: 평균값 정리로 평균변화율 비교하기","힌트":"$[a,\\ b]$ 의 평균변화율과 같은 미분계수 $f\\,'(c)$ 는 $1$ 과 비교해 어느 쪽일까?","식":["$\\dfrac{f(b)-f(a)}{b-a}=f\\,'(c)$, $a<c<b$","$f\\,'(c)<1$","$f(b)-f(a)<b-a$ 이므로 ㄴ 은 참"],"설명":"$0<a<c$ 이므로 $f\\,'(c)<1$ 이다. $b-a>0$ 이므로 양변에 $b-a$ 를 곱해도 부등호의 방향이 그대로다.","확인":null,"스킬":"D2"},{"제목":"ㄷ: 도함수의 증감으로 판정하고 결론 내기","힌트":"위로 볼록한 곡선에서 $f\\,'$ 은 증가할까, 감소할까?","식":["$f\\,'$ 은 감소이므로 $a<b$ 에서 $f\\,'(a)>f\\,'(b)$","ㄷ 은 참, 옳은 것은 ㄴ, ㄷ"],"설명":"접선의 기울기가 $x$ 가 커질수록 작아지는 것이 위로 볼록의 뜻이다.","확인":null,"스킬":"D4"}]},"ns-6b799075c640":{"길":"접점과 다른 교점의 x 좌표 관계로 m₂ 를 한 문자로 쓴다","단계":[{"제목":"접선과 곡선의 다른 교점 Q 구하기","고비":true,"힌트":"접점은 중근이고 곡선과 접선의 차에는 $x^{2}$ 항이 없다. 세 근의 합은?","식":["$\\mathrm{P}(t,\\ 4t^{3}-3t)$ ($t\\ne0$)","$4x^{3}-3x-\\{f\\,'(t)(x-t)+f(t)\\}=4(x-t)^{2}(x-q)$","$2t+q=0$, $q=-2t$"],"설명":"접선과 곡선의 식의 차는 $x^{2}$ 항이 없는 삼차식이다. 근이 $t,\\ t,\\ q$ 이므로 세 근의 합이 $0$ 이어서 Q 의 $x$ 좌표는 $-2t$ 이다.","확인":null,"스킬":"D5"},{"제목":"두 접선의 기울기를 t 의 식으로 쓰기","힌트":"$f\\,'(x)=12x^{2}-3$ 에 $x=t$ 와 $x=-2t$ 를 넣으면?","식":["$m_{1}=f\\,'(t)=12t^{2}-3$","$m_{2}=f\\,'(-2t)=12\\times4t^{2}-3=48t^{2}-3$"],"설명":"접선의 기울기는 접점의 $x$ 좌표에서의 미분계수이다.","확인":null,"스킬":"D1"},{"제목":"m₁≥1 에서 t² 의 범위 구하기","힌트":"$12t^{2}-3\\ge1$ 을 $t^{2}$ 에 대해 풀면?","식":["$12t^{2}-3\\ge1$","$t^{2}\\ge\\dfrac{1}{3}$"],"설명":"부등식의 양변에 $3$ 을 더하고 $12$ 로 나눈다.","확인":"1/3","스킬":"G6"},{"제목":"m₂ 의 최솟값과 k 의 최댓값 구하기","힌트":"$m_{2}=48t^{2}-3$ 에 $t^{2}$ 의 최솟값을 넣으면?","식":["$m_{2}=48t^{2}-3\\ge48\\times\\dfrac{1}{3}-3$","$m_{2}\\ge13$","$k$ 의 최댓값 $13$"],"설명":"$m_{2}\\ge k$ 가 항상 성립하려면 $k$ 는 $m_{2}$ 의 최솟값 이하여야 한다. 따라서 $k$ 의 최댓값은 $m_{2}$ 의 최솟값이다.","확인":"13","스킬":"G6"}]},"ns-842b6070440a":{"길":"밑변 OA 가 고정이므로 y=x 에 평행한 접선의 접점에서 넓이가 최대가 된다","단계":[{"제목":"넓이가 최대일 조건을 접선의 기울기로 바꾸기","고비":true,"힌트":"삼각형 OAP 에서 밑변 OA 가 고정이면 높이가 최대일 때는 접선이 직선 OA 와 어떤 관계일까?","식":["직선 OA : $y=x$","높이 최대 $\\iff$ P 에서의 접선이 $y=x$ 와 평행","$f\\,'\\left(\\dfrac{1}{2}\\right)=1$"],"설명":"곡선이 직선 OA 위쪽에 있는 구간이므로 직선 OA 와 평행한 직선을 위로 올리다가 곡선에 접하는 점에서 거리가 최대이다. 그 접점의 $x$ 좌표가 $\\frac{1}{2}$ 이다.","확인":null,"스킬":"D1"},{"제목":"f′(1/2) 를 a 로 나타내기","힌트":"곱의 미분법으로 $f\\,'(x)$ 를 구해 $x=\\frac{1}{2}$ 를 넣으면?","식":["$f\\,'(x)=a(x-2)^{2}+2ax(x-2)=a(x-2)(3x-2)$","$f\\,'\\left(\\dfrac{1}{2}\\right)=a\\left(-\\dfrac{3}{2}\\right)\\left(-\\dfrac{1}{2}\\right)=\\dfrac{3}{4}a$"],"설명":"$(x-2)$ 를 공통인수로 묶어 정리한다.","확인":null,"스킬":"D1"},{"제목":"a 의 값 구하기","힌트":"$\\frac{3}{4}a=1$ 을 풀고 $a>\\frac{1}{2}$ 을 확인하면?","식":["$\\dfrac{3}{4}a=1$","$a=\\dfrac{4}{3}$"],"설명":"구한 값이 조건 $a>\\frac{1}{2}$ 을 만족한다.","확인":"4/3","스킬":"D1"},{"제목":"k 의 값 구하기","힌트":"$f(x)=\\frac{4}{3}x(x-2)^{2}$ 에 $x=\\frac{1}{2}$ 를 넣으면?","식":["$k=f\\left(\\dfrac{1}{2}\\right)=\\dfrac{4}{3}\\times\\dfrac{1}{2}\\times\\left(\\dfrac{3}{2}\\right)^{2}$","$k=\\dfrac{3}{2}$"],"설명":"점 P 가 곡선 위의 점이므로 $y$ 좌표 $k$ 는 $x=\\frac{1}{2}$ 에서의 함숫값이다.","확인":"3/2","스킬":"D1"}]},"ns-8957488121fc":{"길":"곡선과 y=x 의 위아래 관계와 볼록성으로 세 보기를 판정한다","단계":[{"제목":"그림에서 곡선과 직선 y=x 의 위치 읽기","힌트":"$f(0)$ 과 $f(1)$ 은 얼마이고, $0<x<1$ 과 $x>1$ 에서 곡선은 직선 $y=x$ 의 어느 쪽에 있을까?","식":["$f(0)=0,\\ f(1)=1$ : 곡선은 $y=x$ 와 $x=0,\\ 1$ 에서 만난다","$0<a<1$ : $f(a)<a$","$b>1$ : $f(b)>b$"],"설명":"그림에서 곡선은 두 점 $(0,\\ 0),\\ (1,\\ 1)$ 에서 직선과 만나고, 그 사이에서는 직선 아래쪽, $x>1$ 에서는 직선 위쪽에 있다.","확인":null,"스킬":"G9"},{"제목":"ㄱ: 두 인수의 부호 판정하기","힌트":"$f(a)<a$ 와 $f(b)>b$ 를 $2^{a}-a-1,\\ 2^{b}-b-1$ 의 부호로 바꾸면?","식":["$2^{a}-1<a$, $2^{a}-a-1<0$","$2^{b}-1>b$, $2^{b}-b-1>0$","$(2^{a}-a-1)(2^{b}-b-1)<0$","ㄱ 은 참"],"설명":"음수와 양수의 곱은 음수이다.","확인":null,"스킬":"C3"},{"제목":"ㄴ: 두 부등식을 이용해 함숫값의 차 비교하기","힌트":"$f(b)>b$ 와 $f(a)<a$ 를 이용해 $f(b)-f(a)$ 와 $b-a$ 를 비교하면?","식":["$f(b)-f(a)>b-a$","$(2^{b}-1)-(2^{a}-1)>b-a$","$b-a<2^{b}-2^{a}$ 이므로 ㄴ 은 참"],"설명":"$f(b)>b$ 에서 $f(a)<a$ 를 빼면 부등호 방향이 같은 쪽으로 더해져 $f(b)-f(a)>b-a$ 가 된다.","확인":null,"스킬":"G6"},{"제목":"ㄷ: 원점과 잇는 기울기와 접선의 기울기 비교하고 결론 내기","고비":true,"힌트":"$f(a)=f(a)-f(0)$ 이다. $\\frac{f(a)-f(0)}{a-0}$ 과 $f\\,'(a)$ 는 어느 쪽이 클까?","식":["$\\dfrac{f(a)-f(0)}{a-0}=f\\,'(\\xi)$, $0<\\xi<a$","$f\\,'(x)=2^{x}\\ln2$ 는 증가하므로 $f\\,'(\\xi)<f\\,'(a)$","$\\dfrac{f(a)}{a}<f\\,'(a)$, $f(a)<af\\,'(a)$","ㄷ 은 참, 옳은 것은 ㄱ, ㄴ, ㄷ"],"설명":"$f(0)=0$ 이고 $a>0$ 이다. 아래로 볼록한 곡선에서는 원점과 잇는 기울기가 $x=a$ 에서의 접선의 기울기보다 작다. 양변에 $a$ 를 곱하면 보기의 부등식이 된다.","확인":null,"스킬":"D2"}]},"ns-9ceee57fb54c":{"길":"세 식을 원점·할선·접선의 기울기로 바꿔 부호와 크기를 비교한다","단계":[{"제목":"그림에서 부호 읽기","힌트":"그림에서 $a$, $b$와 $f(a)$, $f(b)$, 접선 기울기의 부호는 어떤가?","식":["$a<0<b$, $f(a)>f(b)>0$","$f'(a)>0$, $f'(b)=0$"],"설명":"$x=a$에서는 그래프가 오르는 중이므로 $f'(a)>0$이다. $x=b$는 극소인 점이므로 $f'(b)=0$이다. 두 점 모두 $x$축 위쪽에 있고 $f(a)>f(b)$이다.","확인":null,"스킬":"G9"},{"제목":"ㄱ: 원점·할선 기울기 비교","힌트":"원점과 두 점을 잇는 직선, 두 점을 잇는 할선의 기울기를 크기순으로 놓으면?","식":["$\\frac{f(a)}{a}<0<\\frac{f(b)}{b}$","$\\frac{f(a)}{a}<\\frac{f(b)-f(a)}{b-a}<\\frac{f(b)}{b}$"],"설명":"$\\frac{f(a)}{a}$, $\\frac{f(b)}{b}$는 원점과 각 점을 잇는 직선의 기울기이다. 점 $(b,\\,f(b))$는 원점과 $(a,\\,f(a))$를 잇는 직선보다 위에 있어 할선 기울기가 $\\frac{f(a)}{a}$보다 크다. 점 $(a,\\,f(a))$는 원점과 $(b,\\,f(b))$를 잇는 직선보다 위에 있어 할선 기울기가 $\\frac{f(b)}{b}$보다 작으므로 ㄱ은 참이다.","확인":null,"스킬":"G9","고비":true},{"제목":"ㄴ: 할선·접선 기울기 비교","힌트":"$f(b)<f(a)$일 때 $a$에서 $b$까지 할선 기울기의 부호는?","식":["$\\frac{f(b)-f(a)}{b-a}<0$","$f'(b)=0<f'(a)$"],"설명":"$f(b)<f(a)$이고 $b>a$이므로 할선 기울기는 음수이다. $f'(b)=0$이고 $f'(a)>0$이므로 ㄴ의 부등식이 성립한다. ㄴ은 참이다.","확인":null,"스킬":"D2"},{"제목":"ㄷ 판정과 보기 고르기","힌트":"$f'(b)$와 $\\frac{f(b)}{b}$의 크기는 어떻게 되는가?","식":["$f'(b)=0<\\frac{f(b)}{b}$","ㄷ은 거짓, 옳은 것은 ㄱ, ㄴ"],"설명":"극소점에서 $f'(b)=0$이고 $f(b)>0$, $b>0$이므로 $\\frac{f(b)}{b}>0$이다. 따라서 $f'(b)>\\frac{f(b)}{b}$가 성립하지 않아 ㄷ은 거짓이다. 옳은 것은 ㄱ, ㄴ이다.","확인":null,"스킬":"G9"}]},"ns-a5343eb13d58":{"길":"점선으로 함숫값을 읽고 평균변화율과 기울기를 선지마다 비교한다","단계":[{"제목":"점선에서 함숫값 읽기","힌트":"곡선 위 점에서 수평으로 그은 점선이 $y=x$와 만나는 점의 $x$좌표는?","식":["$f(a)=b$, $f(b)=c$, $f(c)=d$","$g(b)=a$, $g(c)=b$, $g(d)=c$"],"설명":"점선은 축에 평행하므로 $y=x$ 위의 점에서 $x$좌표와 $y$좌표가 같다. 이 점으로 $f(a)=b$, $f(b)=c$, $f(c)=d$를 읽는다. 역함수는 $x$와 $y$를 바꾼 대응이므로 $g(b)=a$, $g(c)=b$, $g(d)=c$이다.","확인":null,"스킬":"T1","고비":true},{"제목":"①·④: 기울기 크기 비교","힌트":"$x$가 커질수록 원점과 곡선 위의 점을 잇는 직선과 접선의 기울기는 어떻게 변하는가?","식":["$\\frac{f(a)}{a}>\\frac{f(b)}{b}$","$f'(a)<f'(c)$"],"설명":"원점과 $(a,\\,f(a))$를 잇는 직선이 원점과 $(b,\\,f(b))$를 잇는 직선보다 가파르므로 ①은 참이다. $x=a$ 부근보다 $x=c$ 부근에서 접선이 더 가파르므로 ④도 참이다.","확인":null,"스킬":"G9"},{"제목":"②·⑤: 역함수의 평균변화율","힌트":"$g(b)$, $g(c)$, $g(d)$를 써서 $g$의 평균변화율을 나타내면?","식":["$\\frac{g(c)-g(b)}{c-b}=\\frac{b-a}{c-b}$","$\\frac{g(d)-g(b)}{d-b}=\\frac{c-a}{d-b}$"],"설명":"$g(b)=a$, $g(c)=b$, $g(d)=c$를 평균변화율에 대입하면 ②와 ⑤가 모두 성립한다.","확인":null,"스킬":"T1"},{"제목":"③ 판정","힌트":"두 점 $(b,\\,f(b))$, $(c,\\,f(c))$를 잇는 직선과 $y=x$ 중 어느 쪽 기울기가 큰가?","식":["$\\frac{f(c)-f(b)}{c-b}>1$","$f(c)-f(b)>c-b$"],"설명":"$b$에서 $c$까지 곡선이 $y=x$보다 가파르게 오르므로 할선 기울기는 $1$보다 크다. ③은 $f(c)-f(b)<c-b$라고 했으므로 옳지 않다.","확인":null,"스킬":"G9"}]},"ns-ba86f533d04c":{"길":"끝점을 잇는 할선과 같은 기울기의 접선 수를 그래프에서 센다","단계":[{"제목":"끝점을 잇는 할선의 기울기","힌트":"두 끝점의 높이를 비교하면 할선 기울기의 부호는?","식":["$f(a)=0<f(b)$","$\\frac{f(b)-f(a)}{b-a}>0$"],"설명":"점 $(a,\\,f(a))$는 $x$축 위에 있고 점 $(b,\\,f(b))$는 그보다 위에 있어 할선 기울기는 완만한 양수이다. 이 기울기와 같은 접선의 접점을 세는 것이 목표이다.","확인":null,"스킬":"D2"},{"제목":"할선과 평행한 접선 세기","힌트":"그래프가 오르는 구간마다 접선 기울기가 할선 기울기와 같아지는 점은 몇 개인가?","식":["$a$에서 첫 극대까지: 1개","첫 극소에서 둘째 극대까지: 2개","둘째 극소에서 $b$까지: 1개"],"설명":"할선 기울기가 양수이므로 접점은 그래프가 오르는 구간에만 있다. 처음과 마지막 구간은 접선 기울기가 한 방향으로 변하므로 한 번씩 같아지고, 가운데 구간은 기울기가 커졌다 작아지므로 두 번 같아진다. 평균값 정리의 조건을 만족하므로 $f'(c)=\\frac{f(b)-f(a)}{b-a}$인 $c$는 모두 $4$개이다.","확인":"4","스킬":"D2","고비":true}]},"ns-c9fbe287fa52":{"길":"삼차식을 세 근의 곱으로 쓴 뒤 미분해 점 C의 접선 기울기를 구한다","단계":[{"제목":"세 근의 곱으로 나타내기","힌트":"$f(x)=k$의 세 근이 $\\alpha,\\,\\beta,\\,\\gamma$이다. $f(x)-k$를 인수분해하면?","식":["$f(x)-k=2(x-\\alpha)(x-\\beta)(x-\\gamma)$"],"설명":"$f(x)-k$는 최고차항 계수가 $2$인 삼차식이고 $\\alpha,\\,\\beta,\\,\\gamma$를 근으로 가지므로 인수정리에 의해 위와 같이 쓸 수 있다.","확인":null,"스킬":"A4"},{"제목":"미분 후 $x=\\gamma$ 대입","힌트":"곱의 미분으로 $f'(x)$를 쓴 뒤 $x=\\gamma$를 넣으면 어떤 항만 남는가?","식":["$f'(x)=2\\{(x-\\beta)(x-\\gamma)+(x-\\alpha)(x-\\gamma)+(x-\\alpha)(x-\\beta)\\}$","$f'(\\gamma)=2(\\gamma-\\alpha)(\\gamma-\\beta)$"],"설명":"$k$는 상수이므로 미분하면 사라진다. $x=\\gamma$를 넣으면 $(x-\\gamma)$를 포함한 두 항이 $0$이 되어 한 항만 남는다.","확인":null,"스킬":"D13","고비":true},{"제목":"점 A, C 사이의 거리","힌트":"$\\gamma-\\alpha$를 $\\overline{\\mathrm{AB}}$와 $\\overline{\\mathrm{BC}}$로 나타내면?","식":["$\\gamma-\\alpha=\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BC}}=6$"],"설명":"세 점의 $x$좌표가 $\\alpha<\\beta<\\gamma$ 순이므로 $\\gamma-\\alpha$는 두 선분의 길이의 합이다.","확인":"6","스킬":"G1"},{"제목":"접선의 기울기 계산","힌트":"$f'(\\gamma)=2(\\gamma-\\alpha)(\\gamma-\\beta)$에 길이를 넣으면?","식":["$f'(\\gamma)=2\\times6\\times2=24$"],"설명":"$\\gamma-\\beta=\\overline{\\mathrm{BC}}=2$, $\\gamma-\\alpha=6$을 넣으면 점 $\\mathrm{C}$에서의 접선의 기울기가 나온다.","확인":"24","스킬":"D1"}]},"ns-d91cabc62498":{"길":"닮은 직각삼각형으로 접선 기울기를 정하고 삼차함수의 대칭으로 합을 구한다","단계":[{"제목":"점 B에서 접선의 기울기","힌트":"$f'(3)$의 값은?","식":["$f'(x)=-3x^{2}+8x-3$","$f'(3)=-6$"],"설명":"$f'(x)$에 $x=3$을 넣으면 점 $\\mathrm{B}$에서 접선의 기울기가 나온다. 그 절댓값이 $\\frac{\\overline{\\mathrm{CD}}}{\\overline{\\mathrm{DB}}}$이므로 $\\overline{\\mathrm{CD}}=6\\,\\overline{\\mathrm{DB}}$이다.","확인":"-6","스킬":"D1"},{"제목":"점 A쪽 접선의 기울기","힌트":"$\\overline{\\mathrm{AD}}=3\\,\\overline{\\mathrm{DB}}$일 때 직선 $\\mathrm{AC}$의 기울기 $\\frac{\\overline{\\mathrm{CD}}}{\\overline{\\mathrm{AD}}}$는?","식":["$\\overline{\\mathrm{CD}}=6\\,\\overline{\\mathrm{DB}}$, $\\overline{\\mathrm{AD}}=3\\,\\overline{\\mathrm{DB}}$","$f'(a)=\\frac{\\overline{\\mathrm{CD}}}{\\overline{\\mathrm{AD}}}=2$"],"설명":"직각삼각형 $\\mathrm{ACD}$에서 직선 $\\mathrm{AC}$의 기울기는 $\\frac{\\overline{\\mathrm{CD}}}{\\overline{\\mathrm{AD}}}$이고 이 값이 $f'(a)$이다. $\\overline{\\mathrm{DB}}$를 공통 단위로 두면 $\\overline{\\mathrm{CD}}:\\overline{\\mathrm{AD}}=6:3$이다.","확인":"2","스킬":"G9","고비":true},{"제목":"기울기가 같은 두 접점","힌트":"$f'(x)=2$를 만족하는 접점은 몇 개이고, 삼차함수 그래프에서 두 접점은 어떤 위치인가?","식":["$f'(x)=2$의 두 근을 $a$, $a'$이라 한다","$\\frac{a+a'}{2}=$ 변곡점의 $x$좌표"],"설명":"$f'(x)=2$는 $x$에 대한 이차방정식이므로 기울기가 $2$인 접점은 두 개이고 두 접점 모두 조건을 만족한다. 삼차함수의 그래프는 변곡점에 대해 대칭이므로 두 접점의 $x$좌표의 중점이 변곡점의 $x$좌표이다.","확인":null,"스킬":"D5"},{"제목":"변곡점의 $x$좌표","힌트":"$f''(x)=0$을 풀면?","식":["$f''(x)=-6x+8$","$f''(x)=0$에서 $x=\\frac{4}{3}$"],"설명":"$f'(x)=-3x^{2}+8x-3$을 한 번 더 미분한 $f''(x)=-6x+8$이 $0$이 되는 $x$가 변곡점의 $x$좌표이다.","확인":"4/3","스킬":"D5"},{"제목":"$a$의 값들의 합","힌트":"$\\frac{a+a'}{2}=\\frac{4}{3}$이면 $a+a'$은?","식":["$a+a'=2\\times\\frac{4}{3}=\\frac{8}{3}$"],"설명":"구하는 합은 두 접점의 $x$좌표의 합 $a+a'$이다. $3x^{2}-8x+5=0$의 두 근의 합과도 같다.","확인":"8/3","스킬":"D5"}]},"ns-da32036aa092":{"길":"평균변화율을 구간별 식으로 쓰고 보기마다 미분가능성·증가·롤의 정리를 확인한다","단계":[{"제목":"구간별 평균변화율 $g(t)$","힌트":"$f(0)=0$일 때 $g(2)=\\frac{f(2)}{2}$의 값은?","식":["$g(t)=\\frac{f(t)-f(0)}{t-0}=\\frac{f(t)}{t}$","$0<t<2$: $-t^{2}+4t-6$, $2\\le t<3$: $-2$, $3\\le t<6$: $\\frac{2}{3}t-4$"],"설명":"각 구간의 식을 $t$로 나눈다. $f(0)=0$이므로 $g(t)=\\frac{f(t)}{t}$이다.","확인":"-2","스킬":"D2"},{"제목":"ㄱ: $t=2$에서 미분가능성","힌트":"$t=2$의 왼쪽과 오른쪽에서 $g$의 도함수 값은?","식":["$t\\to2-$: $g'(t)=-2t+4\\to0$","$t\\to2+$: $g'(t)=0$"],"설명":"왼쪽 구간에서 $g(t)=-(t-2)^{2}-2$이므로 $g'(t)$의 극한은 $0$이고, 오른쪽에서 $g$는 상수이므로 도함수는 $0$이다. 두 값이 같아 $t=2$에서 미분가능하므로 ㄱ은 거짓이다.","확인":"0","스킬":"D12","고비":true},{"제목":"ㄴ: $g(t)$의 증가 여부","힌트":"세 구간에서 $g(t)$는 증가·감소·상수 중 어느 모양인가?","식":["$0<t<2$: $g(t)=-(t-2)^{2}-2$, 증가","$2\\le t<3$: 상수 $-2$","$3\\le t<6$: 증가"],"설명":"$g(2)=g(3)=-2$로 구간의 이음새에서 값이 이어지므로 $g$는 감소하는 곳이 없다. 따라서 $0<a<b<6$이면 $g(a)\\le g(b)$이고 ㄴ은 참이다.","확인":null,"스킬":"D4"},{"제목":"ㄷ 판정과 보기 고르기","힌트":"$[2,\\,3]$에서 롤의 정리의 세 조건이 모두 성립하는가?","식":["$g$는 $[2,\\,3]$에서 연속, $(2,\\,3)$에서 미분가능","$g(2)=g(3)=-2$"],"설명":"세 조건이 모두 성립하므로 $g'(c)=0$인 $c$가 $(2,\\,3)$에 존재한다. ㄷ은 참이고 옳은 것은 ㄴ, ㄷ이다.","확인":null,"스킬":"D2"}]},"ns-db4162653246":{"길":"그림에서 볼록성과 교점을 읽고 선지를 기울기로 하나씩 가려낸다","단계":[{"제목":"그림에서 읽을 수 있는 조건","힌트":"그림에서 $f(b)$와 $f(a)$는 각각 $b$, $a$와 어떤 관계인가?","식":["$f(b)=b$, $f(a)>a$","곡선은 위로 볼록하므로 $f'$은 감소"],"설명":"곡선이 $x=b$에서 직선 $y=x$와 만나고 $0<x<b$에서는 직선 위쪽에 있다. 또 위로 볼록하므로 접선의 기울기는 $x$가 커질수록 작아진다.","확인":null,"스킬":"G9"},{"제목":"①·②·③·⑤ 확인","힌트":"$x=b$ 오른쪽에서 곡선과 직선의 위아래 관계로 $f'(b)$를 $1$과 비교하면?","식":["$f'(b)<1$, $f'(a)>f'(b)$","$\\frac{f(a)}{a}>1=\\frac{f(b)}{b}$"],"설명":"$x=b$를 지난 뒤 곡선이 직선 아래로 내려가므로 $f'(b)<1$이다. $\\frac{f(a)}{a}$는 원점과 $(a,\\,f(a))$를 잇는 직선의 기울기로 $1$보다 크다. 위로 볼록한 곡선에서 할선의 기울기는 $f'(b)$와 $f'(a)$ 사이에 있으므로 ⑤도 성립한다. ①, ②, ③, ⑤는 옳다.","확인":null,"스킬":"G9"},{"제목":"④ 판정","힌트":"$f(b)=b$를 써서 할선 기울기 $\\frac{f(b)-f(a)}{b-a}$를 $f(a)$와 $a$로 나타내면?","식":["$\\frac{f(b)-f(a)}{b-a}=\\frac{b-f(a)}{b-a}<\\frac{b-a}{b-a}=1$","$f(b)-f(a)<b-a$"],"설명":"$f(a)>a$이므로 $b-f(a)<b-a$이다. 따라서 $f(b)-f(a)<b-a$이고 ④는 옳지 않다.","확인":null,"스킬":"D2","고비":true}]},"ns-e24ae17697fa":{"길":"점 Q의 접선 기울기와 직선 PQ의 기울기를 같게 놓아 a와 b의 관계를 얻는다","단계":[{"제목":"점 Q에서 접선의 기울기","힌트":"$f(x)=\\frac{1}{3}x^{3}-x$에서 $f'(b)$는?","식":["$f'(x)=x^{2}-1$","점 $\\mathrm{Q}$에서 접선의 기울기: $b^{2}-1$"],"설명":"직선 $\\mathrm{PQ}$는 점 $\\mathrm{Q}$에서 곡선에 접하므로 기울기가 $f'(b)=b^{2}-1$이다.","확인":null,"스킬":"D7"},{"제목":"두 점으로 구한 PQ의 기울기","힌트":"$\\frac{f(a)-f(b)}{a-b}$를 $a^{3}-b^{3}$의 인수분해로 정리하면?","식":["$\\frac{f(a)-f(b)}{a-b}=\\frac{a^{3}-b^{3}}{3(a-b)}-1$","$=\\frac{a^{2}+ab+b^{2}}{3}-1$"],"설명":"$f(a)-f(b)=\\frac{a^{3}-b^{3}}{3}-(a-b)$이고 $a^{3}-b^{3}=(a-b)(a^{2}+ab+b^{2})$이다.","확인":null,"스킬":"A2"},{"제목":"두 기울기를 같게 놓기","힌트":"$b^{2}-1$과 $\\frac{a^{2}+ab+b^{2}}{3}-1$을 같게 놓으면 어떤 식이 되는가?","식":["$b^{2}-1=\\frac{a^{2}+ab+b^{2}}{3}-1$","$a^{2}+ab-2b^{2}=0$"],"설명":"직선 $\\mathrm{PQ}$의 기울기를 두 방법으로 나타낸 것이므로 같다. 양변에 $3$을 곱하고 $-1$을 소거하면 $3b^{2}=a^{2}+ab+b^{2}$이다.","확인":null,"스킬":"D7","고비":true},{"제목":"비 $\\frac{b}{a}$ 구하기","힌트":"$a^{2}+ab-2b^{2}$을 인수분해하면?","식":["$(a-b)(a+2b)=0$","$a\\ne b$이므로 $a=-2b$"],"설명":"두 점 $\\mathrm{P}$, $\\mathrm{Q}$는 서로 다른 점이므로 $a\\ne b$이고 $a+2b=0$이다. 따라서 $\\frac{b}{a}=-\\frac{1}{2}$이다.","확인":"-1/2","스킬":"A2"}]},"ns-0d15f2ebd85a":{"길":"a의 부호로 나누어 극소가 생기는 위치를 찾고 극솟값을 방정식으로 푼다","단계":[{"제목":"구간별 도함수","힌트":"$x<0$, $x>0$ 각각에서 $f'(x)$는?","식":["$x<0$: $f'(x)=3a(x+2)(x-2)$","$x>0$: $f'(x)=-3x^{2}+a$"],"설명":"두 식은 $x=0$에서 도함수 값이 $-12a$와 $a$로 달라 $x=0$에서 꺾인다. $x=0$도 극값의 후보이다.","확인":null,"스킬":"D4"},{"제목":"$a>0$인 경우 걸러내기","힌트":"$a>0$일 때 $x=0$ 좌우의 $f'$ 부호는?","식":["$a>0$: $f'(0-)=-12a<0<a=f'(0+)$","극소는 $x=0$뿐이고 극솟값 $f(0)=0$"],"설명":"$a>0$이면 $x=0$의 왼쪽에서 감소, 오른쪽에서 증가하여 극소이다. 다른 극소는 없고 극솟값이 $0$이므로 $-4$가 될 수 없다. 따라서 $a<0$이다.","확인":null,"스킬":"C2","고비":true},{"제목":"$a<0$일 때 극소의 위치","힌트":"$a<0$일 때 $x<0$에서 $f'$의 부호가 $-$에서 $+$로 바뀌는 곳은?","식":["$x<-2$: $f'<0$, $-2<x<0$: $f'>0$","$x>0$: $f'<0$"],"설명":"$a<0$이면 $3a<0$이므로 $x<-2$에서 감소, $-2<x<0$에서 증가하여 $x=-2$에서 극소이다. $x=0$은 증가에서 감소로 바뀌어 극대이고 $x>0$에서는 계속 감소한다.","확인":"-2","스킬":"D4"},{"제목":"극솟값으로 $a$ 구하기","힌트":"$f(-2)$를 $a$로 나타내어 $-4$와 같게 놓으면?","식":["$f(-2)=a(-8)-12a(-2)=16a$","$16a=-4$, $a=-\\frac{1}{4}$"],"설명":"$x<0$에서 $f(x)=ax^{3}-12ax$에 $x=-2$를 대입한다.","확인":"-1/4","스킬":"D4"}]},"ns-1481855fe45a":{"길":"x-1의 부호로 나눠 f'의 부호표를 만들고 증감과 극값을 읽는다","단계":[{"제목":"$(x-1)f'(x)$의 부호 읽기","힌트":"그림에서 $x$축 위쪽·아래쪽인 구간은 각각 어디인가?","식":["$(x-1)f'(x)>0$: $-2<x<1$, $1<x<3$, $x>5$","$(x-1)f'(x)<0$: $x<-2$, $3<x<5$"],"설명":"그래프가 $x$축 위쪽이면 양수, 아래쪽이면 음수이다. $x=1$에서는 $x$축에 닿기만 하므로 부호가 바뀌지 않는다.","확인":null,"스킬":"D4"},{"제목":"$f'(x)$의 부호 정하기","힌트":"$x-1$의 부호로 나누면 각 구간의 $f'(x)$ 부호는?","식":["$x<1$: 부호 반대, $x<-2$는 $+$, $-2<x<1$은 $-$","$x>1$: 부호 같음, $1<x<3$은 $+$, $3<x<5$는 $-$, $x>5$는 $+$"],"설명":"$f'(x)=\\frac{(x-1)f'(x)}{x-1}$이므로 $x<1$에서는 분모가 음수라 부호가 반대이고, $x>1$에서는 부호가 같다.","확인":null,"스킬":"C2","고비":true},{"제목":"증감과 극값의 위치","힌트":"$f'$의 부호가 바뀌는 점에서 증가·감소는 어떻게 바뀌는가?","식":["$x=-2$: 증가 → 감소, 극대","$x=1$: 감소 → 증가, 극소","$x=3$: 증가 → 감소, 극대"],"설명":"$f'$이 $+$에서 $-$로 바뀌면 극대, $-$에서 $+$로 바뀌면 극소이다. $x=5$에서는 $-$에서 $+$로 바뀌어 극소이다.","확인":null,"스킬":"D4"},{"제목":"보기 판정","힌트":"$(-2,\\,1)$에서 $f$는 증가하는가 감소하는가?","식":["ㄱ: $(-2,\\,1)$에서 $f'<0$이므로 거짓","ㄴ: $x=1$에서 극소이므로 참","ㄷ: $x=-2$, $x=3$에서 극대이므로 참"],"설명":"옳은 것은 ㄴ, ㄷ이다.","확인":null,"스킬":"D4"}]},"ns-16adb5c31ee6":{"길":"두 도함수 그래프의 위아래로 h'의 부호를 읽어 증감과 극값을 정한다","단계":[{"제목":"$h'$의 영점","힌트":"$h'(x)=f'(x)-g'(x)$가 $0$이 되는 점은 그림에서 어디인가?","식":["$h'(x)=f'(x)-g'(x)$","$h'(x)=0$: $x=b$, $d$, $e$"],"설명":"$h'(x)=0$은 $f'(x)=g'(x)$, 곧 두 도함수 그래프가 만나는 점이다. 그림에서 교점의 $x$좌표는 $b$, $d$, $e$이다.","확인":null,"스킬":"G1"},{"제목":"구간별 $h'$의 부호","힌트":"각 구간에서 $y=f'(x)$와 $y=g'(x)$ 중 어느 쪽이 위에 있는가?","식":["$x<b$: $f'>g'$ → $h'>0$, $b<x<d$: $g'>f'$ → $h'<0$","$d<x<e$: $f'>g'$ → $h'>0$, $x>e$: $g'>f'$ → $h'<0$"],"설명":"$h'=f'-g'$이므로 $f'$의 그래프가 위쪽인 구간에서 $h'>0$이고 아래쪽인 구간에서 $h'<0$이다.","확인":null,"스킬":"G6","고비":true},{"제목":"증감과 극값의 개수","힌트":"$h'$의 부호가 바뀌는 $x$는 몇 개이고 각각 극대인가 극소인가?","식":["$x=b$: 증가 → 감소, 극대","$x=d$: 감소 → 증가, 극소","$x=e$: 증가 → 감소, 극대"],"설명":"세 점 모두 $h'$의 부호가 바뀌므로 극값을 갖는 $x$의 값은 $3$개이다.","확인":null,"스킬":"D4"},{"제목":"보기 판정","힌트":"ㄱ의 구간 $(b,\\,d)$에서 $h'$의 부호는?","식":["ㄱ: $(b,\\,d)$에서 $h'<0$이므로 감소, 거짓","ㄴ: 극값을 갖는 $x$는 $3$개, 참","ㄷ: $x=d$에서 극소, 참"],"설명":"옳은 것은 ㄴ, ㄷ이다.","확인":null,"스킬":"D4"}]},"ns-2e9994f197fd":{"길":"f'(2)=0과 곱의 조건으로 계수를 정하고 |f|의 극대가 f의 극소임을 이용한다","단계":[{"제목":"$f'(2)=0$으로 $b$ 나타내기","힌트":"$|f|$가 $x=2$에서 극대이면 $f'(2)$의 값은?","식":["$f'(x)=3x^{2}+2ax+b$","$f'(2)=12+4a+b=0$, $b=-4a-12$"],"설명":"$|f(2)|=3\\ne0$이므로 $x=2$ 근처에서 $|f|$는 $f$ 또는 $-f$와 같다. 따라서 $f$도 $x=2$에서 극값을 가져 $f'(2)=0$이다.","확인":null,"스킬":"A3"},{"제목":"곱의 조건으로 $a$ 정하기","힌트":"$f'(0)$과 $f'(1)$을 $a$로 나타내어 곱하면?","식":["$f'(0)=-4a-12$, $f'(1)=-2a-9$","$(4a+12)(2a+9)=-4$, $(2a+7)(a+4)=0$","$a$는 정수이므로 $a=-4$, $b=4$"],"설명":"$f'(1)=3+2a+b$에 $b=-4a-12$를 넣으면 $-2a-9$이다. 곱의 식을 정리하면 $2a^{2}+15a+28=0$이고 $a=-\\frac{7}{2}$ 또는 $a=-4$이다. $a$가 정수이므로 $a=-4$이다.","확인":"-4","스킬":"A3","고비":true},{"제목":"$x=2$에서 극소 확인","힌트":"$f'(x)$를 인수분해하면 $x=2$는 극대인가 극소인가?","식":["$f'(x)=3x^{2}-8x+4=(3x-2)(x-2)$","$x=2$에서 $f$는 극소이므로 $f(2)<0$"],"설명":"$f'$의 부호가 $x=2$에서 $-$에서 $+$로 바뀌므로 극소이다. $|f|$가 극대가 되려면 $f(2)$가 음수이어야 하므로 $f(2)=-3$이다.","확인":null,"스킬":"C2"},{"제목":"$c$ 구하기","힌트":"$f(2)=-3$에 $a=-4$, $b=4$를 넣으면?","식":["$f(2)=8-16+8+c=-3$","$c=-3$"],"설명":"$f(x)=x^{3}-4x^{2}+4x+c$에서 $f(2)=c$이다.","확인":"-3","스킬":"A3"},{"제목":"$f(1)$ 계산","힌트":"$f(x)=x^{3}-4x^{2}+4x-3$에 $x=1$을 넣으면?","식":["$f(1)=1-4+4-3=-2$"],"설명":"계수가 모두 정해졌으므로 $x=1$을 대입한다.","확인":"-2","스킬":"A3"}]},"ns-3110522982c5":{"길":"h'의 부호를 두 도함수 그래프의 위아래로 읽어 증감과 방정식의 실근을 판정한다","단계":[{"제목":"$h'$의 영점","힌트":"$h'(x)=f'(x)-g'(x)$가 $0$이 되는 점은 그림에서 어디인가?","식":["$h'(x)=f'(x)-g'(x)$","$h'(x)=0$: $x=1$, $x=7$"],"설명":"$h'(x)=0$은 $f'(x)=g'(x)$, 곧 두 도함수 그래프가 만나는 점이다. $x=1$에서는 직선과 곡선이 교차하고 $x=7$에서는 접한다.","확인":null,"스킬":"G1"},{"제목":"구간별 $h'$의 부호","힌트":"각 구간에서 곡선 $y=f'(x)$와 직선 $y=g'(x)$ 중 어느 쪽이 위에 있는가?","식":["$x<1$: $f'<g'$ → $h'<0$","$x>1$: $f'>g'$ → $h'>0$ ($x=7$에서만 $0$)"],"설명":"$x=7$에서는 곡선이 직선에 접하기만 하고 위아래가 바뀌지 않으므로 $h'$의 부호는 그대로이다.","확인":null,"스킬":"G6","고비":true},{"제목":"증감과 극값","힌트":"$x=1$, $x=7$ 좌우에서 $h$의 증감은 어떻게 바뀌는가?","식":["$x=1$: 감소 → 증가, 극소","$x=7$: 증가 → 증가, 극값 아님","ㄱ은 $1<x<7$에서 증가하므로 거짓, ㄴ은 참"],"설명":"$h'$이 $x=1$에서 $-$에서 $+$로 바뀌므로 극소이다. $x=7$에서는 부호가 바뀌지 않아 극값이 아니다.","확인":null,"스킬":"D4"},{"제목":"ㄷ: 방정식의 실근 개수","힌트":"극솟값 $h(1)$의 값은 얼마이고, 그 값이 최솟값인가?","식":["$h(1)=f(1)-g(1)=0$","$x\\ne1$이면 $h(x)>0$이므로 실근은 $x=1$ 하나"],"설명":"$h$는 $x<1$에서 감소하고 $x>1$에서 증가하므로 $h(1)=0$이 최솟값이다. 따라서 $h(x)=0$은 서로 다른 두 실근을 갖지 않아 ㄷ은 거짓이고, 옳은 것은 ㄴ이다.","확인":null,"스킬":"D4"}]},"ns-348ec3eda376":{"길":"구간 [a, a+1]이 극소점을 품는지로 나눠 g(a)를 쓰고 양 끝값을 비교한다","단계":[{"제목":"$f(x)$의 증감","힌트":"$f'(x)$를 구하고 부호를 조사하면?","식":["$f'(x)=-3x(x-4)$","$x<0$ 감소, $0<x<4$ 증가, $x>4$ 감소","$x=0$에서 극솟값 $f(0)=0$"],"설명":"$f(x)=-x^{3}+6x^{2}$이므로 $f'(x)=-3x^{2}+12x=-3x(x-4)$이다. $a$의 범위 $-3\\le a\\le3$에서는 극소점 $x=0$이 구간 $[a,\\,a+1]$에 들어가는지가 관건이다.","확인":null,"스킬":"D4"},{"제목":"구간별 $g(a)$","힌트":"구간 $[a,\\,a+1]$이 $x=0$의 왼쪽, 포함, 오른쪽에 있을 때 최솟값은 어디서 나는가?","식":["$-3\\le a\\le-1$: $g(a)=f(a+1)$","$-1\\le a\\le0$: $g(a)=f(0)=0$","$0\\le a\\le3$: $g(a)=f(a)$"],"설명":"$a+1\\le0$이면 구간 전체에서 $f$가 감소하므로 오른쪽 끝에서 최솟값이다. $x=0$을 포함하면 극솟값 $0$이 최솟값이다. $a\\ge0$이면 $[a,\\,a+1]$이 $[0,\\,4]$ 안에 있어 증가하므로 왼쪽 끝에서 최솟값이다.","확인":null,"스킬":"G7","고비":true},{"제목":"$M$, $m$ 구하기","힌트":"각 구간에서 $g$의 증감을 보고 가장 큰 값과 작은 값을 찾으면?","식":["$[-3,\\,-1]$: $g$ 감소, $g(-3)=f(-2)=32$","$[0,\\,3]$: $g$ 증가, $g(3)=f(3)=27$","$M=32$, $m=0$"],"설명":"$g(-3)=f(-2)=-4\\times(-8)=32$이고 $g(3)=f(3)=-9\\times(-3)=27$이므로 $M=32$이다. $g(a)\\ge0$이고 $[-1,\\,0]$에서 $0$이므로 $m=0$이다.","확인":null,"스킬":"G7"},{"제목":"$M+m$","힌트":"$M$과 $m$을 더하면?","식":["$M+m=32+0=32$"],"설명":"구하는 값은 최댓값과 최솟값의 합이다.","확인":"32","스킬":"G7"}]},"ns-36d761eca0ae":{"길":"f'의 부호로 증감과 극값을 읽고 f'의 기울기로 평균값 정리의 점을 센다","단계":[{"제목":"$f'$의 부호 읽기","힌트":"그래프가 $x$축을 지나며 부호가 바뀌는 점과 닿기만 하는 점은 어디인가?","식":["$x<-4$: $f'<0$, $-4<x<0$: $f'>0$","$0<x<2$: $f'<0$, $x>2$: $f'>0$","$x=4$에서는 $f'=0$이지만 부호는 그대로"],"설명":"$f'$의 그래프가 $x$축 아래이면 $f'<0$, 위이면 $f'>0$이다. $x=4$에서는 그래프가 $x$축에 닿기만 한다.","확인":null,"스킬":"D4"},{"제목":"ㄱ·ㄴ 판정","힌트":"$f'\\le0$인 구간과 부호가 바뀌는 점의 개수는?","식":["ㄱ: $(-\\infty,\\,-4]$, $[0,\\,2]$에서 감소, 참","ㄴ: $x=-4,\\,0,\\,2$에서 극값, $x=4$는 아님 → $3$개, 참"],"설명":"$f'\\le0$인 구간에서 $f$가 감소한다. 극값은 $f'$의 부호가 바뀌는 점에서만 생기므로 $x=4$는 극값이 아니다.","확인":null,"스킬":"D4"},{"제목":"ㄷ: 평균값 정리의 점 세기","힌트":"$f'$에 평균값 정리를 쓰면 평균변화율의 부호는? 그 값과 같은 $f''(c)$는 몇 곳인가?","식":["$\\frac{f'(2)-f'(-3)}{2-(-3)}=\\frac{-f'(-3)}{5}<0$","$f''(c)$가 이 음수와 같은 점: $(-3,\\,-2)$에 $2$개, $(-1,\\,1)$에 $2$개"],"설명":"$f'(2)=0$이고 $f'(-3)>0$이므로 평균변화율은 음수이다. $f'$이 감소하는 두 구간 $(-3,\\,-2)$, $(-1,\\,1)$에서 접선 기울기가 그 음수와 같아지는 점이 각각 두 개씩이다. $c$는 $4$개이므로 ㄷ은 거짓이다.","확인":null,"스킬":"D2","고비":true},{"제목":"ㄹ 판정과 보기 고르기","힌트":"$f'(4)=0$이면 $f(4)=0$인가?","식":["$f'(4)=0$일 뿐 $f(4)=0$인지는 알 수 없음, ㄹ은 거짓","옳은 것은 ㄱ, ㄴ"],"설명":"$f'(4)=0$은 접선이 수평이라는 뜻일 뿐 $f(4)$의 값은 알려 주지 않는다. $f$에 상수를 더해도 $f'$은 그대로이므로 ㄹ은 거짓이다.","확인":null,"스킬":"C3"}]},"ns-3aba84b529be":{"길":"차수별 그래프의 끝 모양과 도함수의 부호 변화로 보기마다 반례를 찾는다","단계":[{"제목":"삼차함수 ㄱ·ㄴ","힌트":"삼차함수의 양 끝 모양은 어떻고, $x^{3}$은 극값을 갖는가?","식":["ㄱ: 양 끝이 $-\\infty$와 $\\infty$이고 연속이므로 $x$축과 만남, 참","ㄴ: 반례 $f(x)=x^{3}$은 극값이 없음, 거짓"],"설명":"삼차함수는 한쪽 끝이 양수, 다른 쪽 끝이 음수이므로 중간에 반드시 $0$이 된다. $x^{3}$은 $f'(x)=3x^{2}\\ge0$이라 증가만 한다.","확인":null,"스킬":"C3"},{"제목":"사차함수 ㄷ·ㄹ과 보기 고르기","힌트":"$x^{4}+1$은 $x$축과 만나는가, 사차함수의 도함수는 몇 차이고 부호가 바뀌는가?","식":["ㄷ: 반례 $f(x)=x^{4}+1$은 $x$축과 만나지 않음, 거짓","ㄹ: $f'$이 삼차함수라 부호가 바뀌는 실근을 가짐 → 극값 있음, 참","옳은 것은 ㄱ, ㄹ"],"설명":"삼차함수 $f'$은 홀수 차수이므로 부호가 바뀌는 실근이 반드시 있다. 그 근에서 $f$의 증감이 바뀌므로 사차함수는 항상 극값을 갖는다.","확인":null,"스킬":"C3","고비":true}]},"ns-4d75a1b0206b":{"길":"원뿔의 높이를 변수로 부피를 삼차식으로 세워 미분해 최댓값을 구한다","단계":[{"제목":"밑면 반지름과 높이의 관계","힌트":"구의 중심에서 밑면까지의 거리를 $h$로 나타내고 직각삼각형에서 $r^{2}$을 쓰면?","식":["$r^{2}+(h-3)^{2}=3^{2}$","$r^{2}=h(6-h)$"],"설명":"구의 반지름이 $3$이므로 중심에서 밑면까지의 거리는 $|h-3|$이다. 밑면의 반지름 $r$, 이 거리, 구의 반지름 $3$이 직각삼각형을 이루어 위 식이 나온다.","확인":null,"스킬":"S3","고비":true},{"제목":"부피를 $h$의 식으로","힌트":"$V=\\frac{1}{3}\\pi r^{2}h$에 $r^{2}=h(6-h)$를 넣으면?","식":["$V=\\frac{\\pi}{3}(6h^{2}-h^{3})$, $0<h<6$"],"설명":"$r^{2}$을 $h$로 나타내면 부피가 $h$ 하나의 삼차식이 된다. $h$의 범위는 원뿔의 높이가 구의 지름 이하인 $0<h<6$이다.","확인":null,"스킬":"C7"},{"제목":"미분해서 극대인 $h$ 찾기","힌트":"$V'=0$을 만족하는 $h$는?","식":["$V'=\\frac{\\pi}{3}(12h-3h^{2})=\\pi h(4-h)$","$0<h<4$에서 증가, $4<h<6$에서 감소"],"설명":"$0<h<6$에서 $V'=0$이 되는 값은 $h=4$이고 $V'$의 부호가 $+$에서 $-$로 바뀌므로 $h=4$에서 최대이다.","확인":"4","스킬":"D4"},{"제목":"최대 부피 계산","힌트":"$h=4$를 $V$에 대입하면?","식":["$V=\\frac{\\pi}{3}(6\\times16-64)=\\frac{32}{3}\\pi$"],"설명":"$6h^{2}-h^{3}=96-64=32$이므로 $V=\\frac{32}{3}\\pi$이다.","확인":null,"스킬":"D4"}]},"ns-7eef78e4af4e":{"길":"f'의 부호가 바뀌는 곳만 극값으로 세고 선지를 하나씩 대조한다","단계":[{"제목":"$f'$의 부호 읽기","힌트":"그래프가 $x$축 위쪽·아래쪽인 구간은 각각 어디인가?","식":["$-7<x<-5$: $f'>0$","$-5<x<5$: $f'<0$ ($x=-1$에서만 $0$)","$5<x<6$: $f'>0$"],"설명":"$x=-1$에서는 그래프가 $x$축에 닿기만 하므로 $f'$의 부호는 바뀌지 않는다.","확인":null,"스킬":"D4"},{"제목":"극값의 위치와 개수","힌트":"$f'$의 부호가 바뀌는 점은 몇 개이고 각각 극대인가 극소인가?","식":["$x=-5$: 증가 → 감소, 극대","$x=5$: 감소 → 증가, 극소","$x=-1$은 부호가 안 바뀌어 극값 아님 → 극값 $2$개"],"설명":"극값은 $f'$의 부호가 바뀌는 점에서만 생긴다. $f'(-1)=0$이어도 좌우 모두 $f'\\le0$이라 극값이 아니다.","확인":null,"스킬":"D4","고비":true},{"제목":"선지 대조","힌트":"각 선지의 구간에서 $f'$의 부호를 확인하면?","식":["①: $x=-1$은 극값 아님, ②: $x=5$는 극소","③: $(-3,\\,-1)$에서 $f'<0$이라 감소, ④: $(2,\\,5)$에서 감소","⑤: 극값은 $2$개, 참"],"설명":"①~④는 모두 $f'$의 부호와 맞지 않아 거짓이고, ⑤만 극값의 개수와 일치한다.","확인":null,"스킬":"D4"}]},"ns-bca85e021b0b":{"길":"f'의 부호가 바뀌는 곳만 극값으로 세고 f의 값은 알 수 없다는 점에 유의한다","단계":[{"제목":"$f'$의 부호 읽기","힌트":"그래프가 $x$축 위쪽·아래쪽인 구간은 각각 어디인가?","식":["$x<d$: $f'\\ge0$ ($x=b$에서만 $0$)","$d<x<f$: $f'<0$","$x>f$: $f'>0$"],"설명":"$x=b$에서는 그래프가 $x$축에 닿기만 하므로 $f'$의 부호는 바뀌지 않는다.","확인":null,"스킬":"D4"},{"제목":"증감과 극값","힌트":"$f'$의 부호가 바뀌는 점은 몇 개이고 각각 극대인가 극소인가?","식":["$x=d$: 증가 → 감소, 극대","$x=f$: 감소 → 증가, 극소","$x=b$는 극값 아님 → 극값 $2$개"],"설명":"극값은 $f'$의 부호가 바뀌는 $x=d$, $x=f$ 두 곳뿐이다.","확인":null,"스킬":"D4","고비":true},{"제목":"선지 대조","힌트":"$f'$의 그래프만으로 $f(x)$의 부호나 실근 개수를 알 수 있는가?","식":["①·⑤: $f$의 값은 $f'$으로 알 수 없어 거짓","②: 극값 $3$개가 아니므로 거짓, ③: $(a,\\,b)$에서 $f'>0$이라 증가하므로 거짓","④: $x=d$에서 극대, 참"],"설명":"도함수의 그래프는 $f$의 증감만 알려 주고 $f$의 값은 알려 주지 않는다. 그러므로 ①과 ⑤는 판단할 수 없어 옳지 않다.","확인":null,"스킬":"C3"}]},"ns-bedf791d17db":{"길":"h'의 부호표로 증감과 극값을 정하고 방정식의 실근과 접선의 개수를 센다","단계":[{"제목":"$h'$의 영점과 부호","힌트":"$h'=f'-g'$이므로 두 그래프의 교점과 위아래를 구간별로 보면?","식":["$h'(x)=0$: $x=\\alpha,\\,\\beta,\\,\\gamma$","$x<\\alpha$: $h'<0$, $\\alpha<x<\\beta$: $h'>0$","$\\beta<x<\\gamma$: $h'<0$, $x>\\gamma$: $h'>0$"],"설명":"$f'$의 그래프가 $g'$보다 위에 있으면 $h'>0$, 아래에 있으면 $h'<0$이다. 왼쪽 끝에서는 삼차함수 $f'$이 아래로 내려가고 이차함수 $g'$은 위로 올라가므로 $h'<0$으로 시작한다.","확인":null,"스킬":"G6"},{"제목":"ㄱ 판정과 극값의 위치","힌트":"$h'$의 부호가 $x=\\alpha,\\,\\beta,\\,\\gamma$ 좌우에서 어떻게 바뀌는가?","식":["$x=\\alpha$: 극소, $x=\\beta$: 극대, $x=\\gamma$: 극소","ㄱ: $(\\alpha,\\,\\beta)$에서 $h'>0$이므로 증가, 참"],"설명":"$h'$이 $-$에서 $+$로 바뀌면 극소, $+$에서 $-$로 바뀌면 극대이다.","확인":null,"스킬":"D4"},{"제목":"ㄴ: 방정식의 실근 개수","힌트":"극댓값 $h(\\beta)=-1$이면 $[\\alpha,\\,\\gamma]$에서 $h$의 부호는?","식":["$[\\alpha,\\,\\gamma]$에서 $h(x)\\le h(\\beta)=-1<0$","$x<\\alpha$, $x>\\gamma$에서 각각 실근 $1$개 → 실근 $2$개, 거짓"],"설명":"$h$는 사차함수이고 최고차항의 계수가 양수이므로 양 끝에서 $+\\infty$로 간다. $h(\\alpha)$, $h(\\gamma)$는 극대 $h(\\beta)=-1$보다 작아서 $[\\alpha,\\,\\gamma]$에서는 $h<0$이다. 따라서 근은 $x<\\alpha$와 $x>\\gamma$에서 하나씩이다.","확인":null,"스킬":"D6","고비":true},{"제목":"ㄷ: 평균변화율과 같은 접선 기울기","힌트":"$h'(x)=\\frac{h(\\beta)-h(\\alpha)}{\\beta-\\alpha}$의 해는 구간별로 몇 개인가?","식":["$m=\\frac{h(\\beta)-h(\\alpha)}{\\beta-\\alpha}>0$","$h'(x)=m$: $(\\alpha,\\,\\beta)$에서 $2$개, $x>\\gamma$에서 $1$개","모두 $3$개이므로 ㄷ은 참, 옳은 것은 ㄱ, ㄷ"],"설명":"$h$가 $(\\alpha,\\,\\beta)$에서 증가하므로 $m>0$이고, 평균값 정리에 의해 $m$은 이 구간에서 $h'$의 최댓값보다 작다. $h'$은 이 구간에서 $0$에서 최대까지 올랐다가 $0$으로 내려오므로 $m$과 두 번 같아진다. $x>\\gamma$에서는 $0$에서 계속 커지므로 한 번 같아지고 나머지 구간에서는 $h'<0$이다.","확인":null,"스킬":"D2"}]},"ns-e06487034ec7":{"길":"도함수의 근과 최고차항 계수로 f'을 세워 f를 구한 뒤 보기를 판정한다","단계":[{"제목":"$f'(x)$의 식 세우기","힌트":"그림에서 $f'$의 근은 어디이고, $f$의 최고차항 계수가 $1$이면 $f'$의 최고차항 계수는?","식":["$f'(x)=4x(x+1)(x-1)$","$=4x^{3}-4x$"],"설명":"그림에서 $f'(x)=0$의 근이 $-1$, $0$, $1$이다. $f(x)$의 최고차항이 $x^{4}$이므로 $f'(x)$의 최고차항은 $4x^{3}$이다.","확인":null,"스킬":"A4","고비":true},{"제목":"$f(x)$의 꼴","힌트":"$f'(x)=4x^{3}-4x$를 적분하면?","식":["$f(x)=x^{4}-2x^{2}+C$"],"설명":"$C$는 적분상수이고 주어진 조건으로는 정해지지 않는다.","확인":null,"스킬":"A11"},{"제목":"ㄱ 판정","힌트":"$f(0)-f(1)$의 값은?","식":["$f(0)-f(1)=C-(1-2+C)=1>0$","ㄱ은 참"],"설명":"$f'(x)<0$인 $0<x<1$에서 $f$가 감소하므로 $f(0)>f(1)$이다. 값으로 계산해도 차가 양수이다.","확인":"1","스킬":"D4"},{"제목":"ㄴ·ㄷ 판정","힌트":"$f(-x)$와 $f(x)$를 비교하고, $C$의 값에 따라 실근은 어떻게 달라지는가?","식":["ㄴ: $f(-x)=f(x)$이므로 $y$축 대칭, 참","ㄷ: $C=5$이면 $f(x)=(x^{2}-1)^{2}+4>0$이라 실근 없음, 거짓","옳은 것은 ㄱ, ㄴ"],"설명":"$f$는 짝수 차수의 항만 가지므로 $y$축에 대하여 대칭이다. $C$는 정해지지 않았으므로 $f(x)=0$의 실근 개수는 $C$에 따라 달라지고, 실근이 세 개가 되지 않는 반례 하나로 ㄷ은 거짓이다.","확인":null,"스킬":"C3"}]},"ns-eb44dcbb8e3d":{"길":"도함수 그래프 아래의 부호 있는 넓이로 함숫값의 차를 비교하고 대칭으로 넓이를 옮긴다","단계":[{"제목":"$g(c)$, $f(b)$, $f(a)$의 순서","힌트":"$a<x<b$에서 $f'$의 부호와 $b<x<c$에서 $g'$의 부호는?","식":["$a<x<b$: $f'<0$ → $f(a)>f(b)$","$b<x<c$: $g'<0$ → $g(c)<g(b)=f(b)$","$g(c)<f(b)<f(a)$"],"설명":"도함수가 음수인 구간에서는 함수가 감소한다. $f'<0$이므로 $f(a)>f(b)$이고, $g'<0$이므로 $g(c)<g(b)$이며 $f(b)=g(b)$이다. 선지 중 $g(c)<f(b)<f(a)$를 만족하는 것은 ④와 ⑤이다.","확인":null,"스킬":"D4"},{"제목":"$g(e)-f(a)$를 넓이의 차로","힌트":"$f(b)=g(b)$를 이용해 $g(e)-f(a)$를 두 적분의 차로 쓰면?","식":["$g(e)-f(a)=\\{g(e)-g(b)\\}-\\{f(a)-f(b)\\}$","$=\\int_{b}^{e}g'(x)\\,dx-\\int_{a}^{b}\\left|f'(x)\\right|dx$"],"설명":"$f(a)-f(b)=\\int_{a}^{b}\\{-f'(x)\\}dx=\\int_{a}^{b}|f'(x)|dx$이다. $f(b)=g(b)$이므로 $g(e)-f(a)$는 두 넓이의 차이다.","확인":null,"스킬":"D8"},{"제목":"대칭점으로 구간 옮기기","힌트":"$f'$은 $x=c$에 대해, $g'$은 점 $(c,\\,0)$에 대해 대칭이다. $b$의 대칭점 $b'=2c-b$를 쓰면?","식":["$\\int_{b}^{e}g'(x)\\,dx=\\int_{b'}^{e}g'(x)\\,dx$","$\\int_{a}^{b}\\left|f'(x)\\right|dx=\\int_{b'}^{d}\\left|f'(x)\\right|dx$"],"설명":"$f'$은 꼭짓점이 $x=c$인 포물선이라 $a$와 $d$, $b$와 $b'$가 서로 대칭이다. 직선 $g'$은 $x=c$에서 $0$이므로 $[b,\\,b']$의 위쪽 넓이와 아래쪽 넓이가 같아 적분이 $0$이다.","확인":null,"스킬":"G11","고비":true},{"제목":"$[b',\\,d]$에서 두 값 비교","힌트":"$x=b'$에서 $g'$과 $|f'|$의 값은 같은가, 그 뒤로 각각 증가인가 감소인가?","식":["$g'(b')=|f'(b')|$","$b'<x<d$: $g'(x)$ 증가, $|f'(x)|$ 감소 → $g'(x)>|f'(x)|$"],"설명":"$g'(b')=-g'(b)=-f'(b)=|f'(b)|=|f'(b')|$이다. $b'$ 이후에 직선 $g'$은 올라가고 $|f'|$은 $d$에서 $0$이 될 때까지 줄어든다.","확인":null,"스킬":"G6"},{"제목":"대소 결론","힌트":"$g(e)-f(a)$의 부호와 네 수의 순서는?","식":["$g(e)-f(a)=\\int_{b'}^{d}\\{g'-|f'|\\}dx+\\int_{d}^{e}g'\\,dx>0$","$g(c)<f(b)<f(a)<g(e)$"],"설명":"$[b',\\,d]$에서 $g'>|f'|$이고 그림에서 $d<e$이므로 $[d,\\,e]$에서 $g'>0$이다. 따라서 $g(e)>f(a)$이고 앞에서 얻은 $g(c)<f(b)<f(a)$와 합하면 ④이다.","확인":null,"스킬":"D8"}]},"ns-f45fec0c471e":{"길":"닮음으로 원기둥 높이를 반지름으로 나타내고 부피 합을 미분해 최댓값을 구한다","단계":[{"제목":"원기둥의 높이를 $r$로","힌트":"원기둥 윗면 가장자리가 원뿔의 옆면 위에 있다. 그 점의 가운데 축으로부터의 거리는?","식":["윗면 가장자리의 축에서의 거리 $=2r$","$\\frac{6-h}{6}=\\frac{2r}{2}$, $h=6(1-r)$"],"설명":"두 원기둥이 맞닿아 있어 가운데 축에서 가장 먼 가장자리까지 거리가 $2r$이다. 그 높이에서 원뿔의 반지름이 $2r$이므로 꼭짓점에서의 닮음비 $\\frac{6-h}{6}=\\frac{2r}{2}$가 성립한다.","확인":null,"스킬":"S1","고비":true},{"제목":"부피의 합을 $r$로","힌트":"원기둥 두 개의 부피의 합 $2\\pi r^{2}h$에 $h$를 대입하면?","식":["$V=2\\pi r^{2}h=12\\pi(r^{2}-r^{3})$","$0<r<1$"],"설명":"$h=6(1-r)$이므로 $V=2\\pi r^{2}\\cdot6(1-r)$이다. $h>0$에서 $r<1$이다.","확인":null,"스킬":"C7"},{"제목":"미분해서 $r$ 찾기","힌트":"$V'=0$이 되는 $r$은?","식":["$V'=12\\pi(2r-3r^{2})=12\\pi r(2-3r)$","$r=\\frac{2}{3}$에서 극대"],"설명":"$0<r<1$에서 $V'=0$인 값은 $r=\\frac{2}{3}$이고 $V'$이 $+$에서 $-$로 바뀌어 최댓값을 준다.","확인":"2/3","스킬":"D4"},{"제목":"$9M$ 계산","힌트":"$r=\\frac{2}{3}$를 $V$에 대입하면?","식":["$M=12\\pi\\left(\\frac{4}{9}-\\frac{8}{27}\\right)=\\frac{16}{9}\\pi$","$9M=16\\pi$"],"설명":"$r^{2}-r^{3}=\\frac{4}{9}-\\frac{8}{27}=\\frac{4}{27}$이다.","확인":null,"스킬":"D4"}]},"ns-0cfd14f2b1b3":{"길":"시간 t로 AP, AQ를 나타내 넓이를 t의 식으로 만든 뒤 미분한다","단계":[{"제목":"넓이를 시간의 식으로","힌트":"$t$초 후 $\\overline{\\mathrm{AP}}$와 $\\overline{\\mathrm{AQ}}$의 길이는?","식":["$\\overline{\\mathrm{AP}}=3t$, $\\overline{\\mathrm{AQ}}=18-2t$","$S(t)=\\frac{1}{2}\\cdot3t\\cdot(18-2t)=27t-3t^{2}$"],"설명":"점 $\\mathrm{Q}$는 $\\mathrm{D}$에서 $2t$만큼 내려오므로 $\\overline{\\mathrm{AQ}}=18-2t$이다. 삼각형 $\\mathrm{APQ}$는 $\\angle\\mathrm{A}$가 직각이다.","확인":null,"스킬":"C7","고비":true},{"제목":"넓이가 $60$이 되는 첫 시각","힌트":"$27t-3t^{2}=60$을 풀어 두 해 중 이른 쪽은?","식":["$27t-3t^{2}=60$","$t^{2}-9t+20=0$, $(t-4)(t-5)=0$"],"설명":"두 해 중 먼저 도달하는 시각을 고른다. 점 $\\mathrm{P}$가 $\\mathrm{B}$에 닿는 $t=6$ 이전이므로 둘 다 범위 안이다.","확인":"4","스킬":"C7"},{"제목":"그 순간의 변화율","힌트":"$S'(t)$에 구한 시각을 대입하면?","식":["$S'(t)=27-6t$","$S'(4)=27-24=3$"],"설명":"시간에 대한 넓이의 변화율은 $S'(t)$이다.","확인":"3","스킬":"D1"}]},"ns-1013329e3eca":{"길":"h'의 부호로 W자 개형을 그리고 극솟값의 부호에 따라 실근의 개수를 센다","단계":[{"제목":"$h'$의 부호","힌트":"$h'=f'-g'$이므로 교점의 $x$좌표 $-2$, $1$, $4$ 좌우에서 두 그래프의 위아래는?","식":["$x<-2$: $h'<0$, $-2<x<1$: $h'>0$","$1<x<4$: $h'<0$, $x>4$: $h'>0$"],"설명":"$f'$이 $g'$보다 위이면 $h'>0$, 아래이면 $h'<0$이다. 왼쪽 끝에서 $f'$은 아래로, $g'$은 위로 가므로 $h'<0$으로 시작한다.","확인":null,"스킬":"G6"},{"제목":"개형: 극값의 위치","힌트":"$h'$의 부호가 바뀌는 점에서 증가·감소는 어떻게 바뀌는가?","식":["$x=-2$, $x=4$: 극소","$x=1$: 극대","양 끝에서 $+\\infty$인 W자 모양"],"설명":"$h'$의 최고차항 계수가 양수이므로 $h$는 양 끝에서 $+\\infty$로 간다. 극대 $h(1)$은 이웃한 두 극솟값 $h(-2)$, $h(4)$보다 크다.","확인":null,"스킬":"D4"},{"제목":"ㄱ: 극솟값의 부호가 다를 때","힌트":"$h(-2)h(4)<0$이면 두 극솟값의 부호는 어떤가? 근은 몇 개인가?","식":["$h(-2)<0<h(4)$: 근은 $x<-2$, $-2<x<1$에 하나씩","$h(4)<0<h(-2)$: 근은 $1<x<4$, $x>4$에 하나씩","어느 경우도 서로 다른 두 실근, 참"],"설명":"음수인 극솟값 양옆에 근이 하나씩 있고, 양수인 극솟값 쪽에는 근이 없다.","확인":null,"스킬":"D6"},{"제목":"ㄴ: 반례 찾기","힌트":"$h(-2)=0$이고 $h(4)>0$인 경우 실근은 몇 개인가?","식":["$h(-2)=0<h(4)$이면 실근은 $x=-2$ 하나","$h(-2)h(4)=0$이어도 세 실근이 아니므로 ㄴ은 거짓"],"설명":"$h(-2)=0$이고 $h(4)>0$이면 $h$의 최솟값이 $0$이라 $x=-2$에서만 $h(x)=0$이 된다.","확인":null,"스킬":"C3"},{"제목":"ㄷ: $h(1)h(4)>0$","힌트":"$h(1)$, $h(4)$가 모두 양수인 경우와 모두 음수인 경우로 나누면 실근은 각각 몇 개 이하인가?","식":["모두 양수: 실근은 $x<1$에서만 생기고 $h(-2)$의 부호에 따라 $0$, $1$, $2$개","모두 음수: $[-2,\\,4]$에서 $h<0$이므로 양 끝쪽에 하나씩 $2$개","어느 경우도 $2$개 이하이므로 ㄷ은 참, 옳은 것은 ㄱ, ㄷ"],"설명":"$h(1)>0$, $h(4)>0$이면 $x\\ge1$에서 $h>0$이다. $h(1)<0$, $h(4)<0$이면 $h(-2)<h(1)<0$이어서 $[-2,\\,4]$ 전체에서 $h<0$이다.","확인":null,"스킬":"C2","고비":true}]},"ns-11af97ad473d":{"길":"원뿔의 높이를 변수로 부피를 삼차식으로 세워 미분하고 밑면의 반지름을 구한다","단계":[{"제목":"밑면 반지름과 높이의 관계","힌트":"구의 중심에서 밑면까지의 거리를 $h$로 나타내고 직각삼각형을 세우면?","식":["$r^{2}+(h-3)^{2}=3^{2}$","$r^{2}=h(6-h)$"],"설명":"원뿔의 높이를 $h$, 밑면의 반지름을 $r$이라 하면 구의 중심에서 밑면까지 거리가 $|h-3|$이다. 이 거리, $r$, 구의 반지름 $3$이 직각삼각형을 이룬다.","확인":null,"스킬":"S3","고비":true},{"제목":"부피를 $h$의 식으로","힌트":"$V=\\frac{1}{3}\\pi r^{2}h$에 $r^{2}=h(6-h)$를 넣으면?","식":["$V=\\frac{\\pi}{3}(6h^{2}-h^{3})$, $0<h<6$"],"설명":"$r^{2}$을 $h$로 나타내 변수를 하나로 줄인다.","확인":null,"스킬":"C7"},{"제목":"미분으로 극대 찾기","힌트":"$V'=0$인 $h$는?","식":["$V'=\\frac{\\pi}{3}(12h-3h^{2})=\\pi h(4-h)$","$h=4$에서 극대"],"설명":"$0<h<6$에서 $V'$이 $+$에서 $-$로 바뀌는 $h=4$에서 부피가 최대이다.","확인":"4","스킬":"D4"},{"제목":"밑면의 반지름","힌트":"$h=4$를 $r^{2}=h(6-h)$에 넣으면?","식":["$r^{2}=4\\times2=8$","$r=2\\sqrt{2}$"],"설명":"$r>0$이므로 $r=2\\sqrt{2}$이다.","확인":null,"스킬":"S3"}]},"ns-57f0b22bc64d":{"길":"좌변의 최솟값이 0 이상이 되도록 n의 범위를 구한다","단계":[{"제목":"최솟값 조건으로 바꾸기","힌트":"모든 $x\\ge0$에서 $h(x)\\ge0$이려면 $h$의 무엇이 $0$ 이상이어야 하는가?","식":["$h(x)=x^{n+1}-(n+1)x-n(n-3)$","$x\\ge0$에서 $h$의 최솟값 $\\ge0$"],"설명":"부등식이 모든 $x\\ge0$에서 성립하는 것은 $h$의 최솟값이 $0$ 이상인 것과 같다.","확인":null,"스킬":"C1","고비":true},{"제목":"최소가 되는 $x$","힌트":"$h'(x)=0$을 풀면?","식":["$h'(x)=(n+1)(x^{n}-1)$","$0<x<1$에서 감소, $x>1$에서 증가"],"설명":"$n$이 자연수이므로 $x\\ge0$에서 $x^{n}=1$인 값은 $x=1$뿐이다. $h'$이 $-$에서 $+$로 바뀌므로 $x=1$에서 최소이다.","확인":"1","스킬":"D4"},{"제목":"최솟값 $h(1)$","힌트":"$h(1)$을 $n$으로 나타내면?","식":["$h(1)=1-(n+1)-n(n-3)$","$=-n^{2}+2n=-n(n-2)$"],"설명":"$x=1$을 대입해 전개한다.","확인":null,"스킬":"D4"},{"제목":"부등식과 최댓값","힌트":"$-n(n-2)\\ge0$을 만족하는 자연수 $n$은?","식":["$n(n-2)\\le0$, $0\\le n\\le2$","자연수 $n$의 최댓값은 $2$"],"설명":"자연수 $n$은 $1$, $2$이므로 최댓값은 $2$이다.","확인":"2","스킬":"C1"}]},"ns-5c2ec79af20a":{"길":"미분가능 조건으로 a를 정하고 기울기 12인 접선의 x절편으로 k의 최솟값을 구한다","단계":[{"제목":"미분가능 조건으로 $a$ 정하기","힌트":"$x=a$에서 연속이려면 $f(a)$는 어떤 값이어야 하고, 좌·우 미분계수는 어떤가?","식":["$(a-1)^{2}(2a+1)=0$, $a=1$ 또는 $a=-\\frac{1}{2}$","$a=-\\frac{1}{2}$: 우미분계수 $\\frac{9}{2}\\ne0$ → 부적합","$a=1$: 우미분계수 $0$ → 가능"],"설명":"$x\\le a$에서 $f=0$이므로 좌미분계수는 $0$이다. 연속이려면 $(a-1)^{2}(2a+1)=0$이어야 하고, 이 중 우미분계수가 $0$인 $a=1$만 미분가능하다.","확인":"1","스킬":"D12"},{"제목":"경계가 되는 접선","힌트":"기울기가 $12$이고 $x>1$에서 $f$에 접하는 직선의 접점의 $x$좌표는?","식":["$f'(x)=6x(x-1)$","$6m(m-1)=12$, $m=2$ ($m>1$)"],"설명":"$g$의 그래프는 기울기 $12$인 반직선이다. 이 반직선이 $f$의 그래프 아래에 있도록 평행이동하다가 접하는 순간이 $k$의 한계이다. $f(x)=2x^{3}-3x^{2}+1$이므로 $f'(x)=6x(x-1)$이다.","확인":"2","스킬":"D7","고비":true},{"제목":"접선의 방정식","힌트":"접점 $(2,\\,f(2))$에서 기울기가 $12$인 직선의 식은?","식":["$f(2)=5$","$y-5=12(x-2)$, $y=12x-19$"],"설명":"접점의 $y$좌표는 $f(2)=(2-1)^{2}(2\\cdot2+1)=5$이다.","확인":"5","스킬":"D7"},{"제목":"$k$의 최솟값","힌트":"$y=12(x-k)$가 $y=12x-19$ 아래에 있으려면?","식":["$12(x-k)\\le12x-19$","$k\\ge\\frac{19}{12}$"],"설명":"$y=12x-19$의 $x$절편이 $\\frac{19}{12}$이고, $g$의 $x$절편 $k$가 이보다 작지 않아야 $g$가 접선 아래에 놓인다. $x\\le1$에서는 $f=0$이므로 $k\\ge1$도 만족한다.","확인":"19/12","스킬":"C1"},{"제목":"$a+p+q$의 값","힌트":"$\\frac{q}{p}=\\frac{19}{12}$에서 서로소인 $p$, $q$를 정하면?","식":["$p=12$, $q=19$","$a+p+q=1+12+19=32$"],"설명":"$k$의 최솟값 $\\frac{19}{12}$는 이미 기약분수이므로 분모가 $p$, 분자가 $q$이다.","확인":"32","스킬":"C7"}]},"ns-5cbe6f60836e":{"길":"거리의 차가 둘레의 배수일 때 만나므로 차 함수의 증감으로 지나는 횟수를 센다","단계":[{"제목":"만나는 조건","힌트":"두 점이 같은 방향으로 움직일 때 만나려면 움직인 거리의 차는 둘레의 몇 배여야 하는가?","식":["원의 둘레 $=2\\pi\\cdot\\frac{5}{\\pi}=10$","만남: 거리의 차 $d(t)=10n$ ($n$은 정수)"],"설명":"같은 방향으로 도는 두 점은 한 점이 다른 점보다 둘레의 정수배만큼 더 갔을 때 만난다.","확인":"10","스킬":"C7"},{"제목":"거리 차 $d(t)$의 증감","힌트":"$d(t)=(2t^{3}+25t)-(15t^{2}+t)$를 정리하고 $d'(t)$의 부호를 조사하면?","식":["$d(t)=2t^{3}-15t^{2}+24t$","$d'(t)=6(t-1)(t-4)$","$d(1)=11$, $d(4)=-16$, $d(5)=-5$"],"설명":"$0<t<1$과 $t>4$에서 증가하고 $1<t<4$에서 감소한다. 극값과 $t=5$에서의 값으로 $d$가 지나는 범위를 알 수 있다.","확인":"-16","스킬":"D4"},{"제목":"$10$의 배수를 지나는 횟수","힌트":"$d(t)$가 $0\\to11\\to-16\\to-5$로 변하는 동안 $10$의 배수를 몇 번 지나는가?","식":["$0\\to11$: $d=10$ 1번","$11\\to-16$: $d=10,\\,0,\\,-10$ 3번","$-16\\to-5$: $d=-10$ 1번"],"설명":"$d(t)$가 $10$의 배수 값을 지나는 때마다 두 점이 만난다. $t=0$은 출발 시각이므로 세지 않는다. 모두 $5$번이다.","확인":"5","스킬":"G1","고비":true}]},"ns-fbcc7c1934d1":{"길":"BP=t-3일 때 AP²을 코사인법칙으로 쓰고 원의 넓이를 t로 미분한다","단계":[{"제목":"$5$초일 때 점 $\\mathrm{P}$의 위치","힌트":"$t=5$일 때 점 $\\mathrm{P}$는 어느 변 위에 있고 $\\overline{\\mathrm{BP}}$는?","식":["$3\\le t\\le6$: 점 $\\mathrm{P}$는 변 $\\mathrm{BC}$ 위","$\\overline{\\mathrm{BP}}=t-3$"],"설명":"점 $\\mathrm{P}$는 $3$초에 $\\mathrm{B}$, $6$초에 $\\mathrm{C}$에 도착한다. $t=5$는 그 사이이므로 변 $\\mathrm{BC}$ 위에 있다.","확인":"2","스킬":"C7"},{"제목":"코사인법칙으로 $\\overline{\\mathrm{AP}}^{2}$","힌트":"삼각형 $\\mathrm{ABP}$에서 $\\angle\\mathrm{B}=60^{\\circ}$일 때 $\\overline{\\mathrm{AP}}^{2}$을 $s=\\overline{\\mathrm{BP}}$로 나타내면? $s=2$일 때의 값은?","식":["$\\overline{\\mathrm{AP}}^{2}=3^{2}+s^{2}-2\\cdot3\\cdot s\\cos60^{\\circ}$","$=s^{2}-3s+9$"],"설명":"정삼각형이므로 $\\overline{\\mathrm{AB}}=3$, $\\angle\\mathrm{B}=60^{\\circ}$이다. $s=2$를 넣으면 $\\overline{\\mathrm{AP}}^{2}$의 값이 나온다.","확인":"7","스킬":"S6","고비":true},{"제목":"원의 넓이를 $t$의 식으로","힌트":"원의 반지름은 $\\overline{\\mathrm{AP}}$이다. 넓이 $F(t)$를 $t$로 나타내면?","식":["$F(t)=\\pi\\,\\overline{\\mathrm{AP}}^{2}=\\pi(s^{2}-3s+9)$","$s=t-3$이므로 $F(t)=\\pi(t^{2}-9t+27)$, $3<t<6$"],"설명":"$s=t-3$을 대입해 전개한다.","확인":null,"스킬":"C7"},{"제목":"넓이의 변화율","힌트":"$F'(t)$에 $t=5$를 넣으면?","식":["$F'(t)=\\pi(2t-9)$","$F'(5)=\\pi$"],"설명":"시간에 대한 넓이의 변화율은 $F'(t)$이다.","확인":null,"스킬":"D1"}]},"ns-061a3e78989f":{"길":"구간을 0에서 나눠 세 적분의 관계를 쓰면 반쪽 적분이 모두 0임을 알 수 있다","단계":[{"제목":"세 적분 사이의 관계","힌트":"구간 $[-1,\\,1]$을 $0$에서 나눠 쓰면 세 값의 관계는?","식":["$\\int_{-1}^{1}f=\\int_{-1}^{0}f+\\int_{0}^{1}f$","$\\int_{-1}^{0}f=\\int_{0}^{1}f=0$"],"설명":"세 적분의 공통값을 $I$라 하면 $I=I+I$이므로 $I=0$이다.","확인":"0","스킬":"D8","고비":true},{"제목":"적분을 계수로 나타내기","힌트":"$f(x)=px^{2}+qx-2$를 $[0,\\,1]$, $[-1,\\,0]$에서 적분하면?","식":["$\\int_{0}^{1}f(x)dx=\\frac{p}{3}+\\frac{q}{2}-2=0$","$\\int_{-1}^{0}f(x)dx=\\frac{p}{3}-\\frac{q}{2}-2=0$"],"설명":"$f(0)=-2$이므로 상수항이 $-2$이다.","확인":null,"스킬":"D8"},{"제목":"연립해서 $p$, $q$","힌트":"두 식을 더하고 빼면?","식":["더하면 $\\frac{2p}{3}-4=0$, $p=6$","빼면 $q=0$"],"설명":"$q$가 소거되도록 더하면 $p$를, $p$가 소거되도록 빼면 $q$를 얻는다.","확인":"6","스킬":"A10"},{"제목":"$f(2)$ 계산","힌트":"$f(x)=6x^{2}-2$에 $x=2$를 넣으면?","식":["$f(2)=6\\cdot4-2=22$"],"설명":"$q=0$이므로 $f(x)=6x^{2}-2$이다.","확인":"22","스킬":"A3"}]},"ns-0a65457bca2d":{"길":"h'=f-g의 부호로 증감을 읽고 h(1)=0을 이용해 부호와 실근의 개수를 판정한다","단계":[{"제목":"$h'$과 영점","힌트":"$h(x)=\\int_{1}^{x}\\{f(t)-g(t)\\}dt$를 미분하면? $h'=0$인 $x$는 그림에서 어디인가?","식":["$h'(x)=f(x)-g(x)$","$h'(x)=0$: $x=\\alpha$, $x=\\beta$"],"설명":"미적분의 기본정리에 의해 $h'(x)=f(x)-g(x)$이고, 이는 두 그래프의 교점 $x=\\alpha$, $x=\\beta$에서 $0$이다.","확인":null,"스킬":"D9"},{"제목":"증감과 ㄴ 판정","힌트":"곡선이 직선보다 위인 구간과 아래인 구간은 어디인가?","식":["$x<\\alpha$: $h'<0$, $\\alpha<x<\\beta$: $h'>0$, $x>\\beta$: $h'<0$","$x=\\alpha$에서 극소, $x=\\beta$에서 극대 → ㄴ 참"],"설명":"$f$의 그래프가 직선 $g$보다 위에 있으면 $h'>0$, 아래에 있으면 $h'<0$이다. $h'$이 $+$에서 $-$로 바뀌는 $x=\\beta$에서 극대이다.","확인":null,"스킬":"D4"},{"제목":"ㄱ 판정","힌트":"$h(1)$의 값과 $(\\alpha,\\,1)$에서 $h$의 증감으로 $h(\\alpha)$의 부호는?","식":["$h(1)=\\int_{1}^{1}\\{f(t)-g(t)\\}dt=0$","$(\\alpha,\\,1)$에서 $h$ 증가 → $h(\\alpha)<h(1)=0$, ㄱ 거짓"],"설명":"$\\alpha<1<\\beta$이므로 $(\\alpha,\\,1)$은 $h$가 증가하는 구간 $(\\alpha,\\,\\beta)$에 들어 있다.","확인":null,"스킬":"D9"},{"제목":"ㄷ: 실근의 개수와 부호","힌트":"$h(\\alpha)<0<h(\\beta)$이고 $h(1)=0$이다. 양 끝의 모양까지 보면 근은 몇 개이고 부호는?","식":["$x<\\alpha$: 음의 근 $1$개, $x=1$: 근, $x>\\beta$: 양의 근 $1$개","음의 근 $1$개, 양의 근 $2$개이므로 ㄷ 참, 옳은 것은 ㄴ, ㄷ"],"설명":"$h'=f-g$는 위로 볼록한 이차식이므로 $h$는 최고차항 계수가 음수인 삼차식이고 왼쪽 끝에서 $+\\infty$, 오른쪽 끝에서 $-\\infty$로 간다. $h(\\alpha)<0$이라 $x<\\alpha$에서 한 번 $0$이 된다. $h(\\beta)>h(1)=0$이라 $x>\\beta$에서 한 번 더 $0$이 된다.","확인":null,"스킬":"D6","고비":true}]},"ns-0d054daab223":{"길":"|f|의 증감으로 g(t)를 구간별로 쓰고 구간마다 적분한다","단계":[{"제목":"$f$의 증감과 극값","힌트":"$0\\le x\\le2$에서 $f'$의 부호와 $f(\\sqrt{2})$의 값은?","식":["$f'(x)=4x(x+\\sqrt{2})(x-\\sqrt{2})$","$0\\le x\\le\\sqrt{2}$ 감소, $\\sqrt{2}\\le x\\le2$ 증가","$f(\\sqrt{2})=-4$, $f(2)=0$"],"설명":"$f(x)=x^{2}(x^{2}-4)$이므로 $0\\le x\\le2$에서 $f\\le0$이다. $f(\\sqrt{2})=4-8=-4$이다.","확인":"-4","스킬":"D4"},{"제목":"구간별 $g(t)$","힌트":"$|f|$의 증감을 보면 $0\\le x\\le t$에서의 최댓값은 어디서 나는가?","식":["$0\\le t\\le\\sqrt{2}$: $g(t)=|f(t)|=4t^{2}-t^{4}$","$\\sqrt{2}\\le t\\le2$: $g(t)=|f(\\sqrt{2})|=4$"],"설명":"$f\\le0$이므로 $|f|=-f$이다. $|f|$는 $[0,\\,\\sqrt{2}]$에서 $0$에서 $4$까지 증가하고 $[\\sqrt{2},\\,2]$에서 $4$에서 $0$으로 줄어든다. $t\\ge\\sqrt{2}$이면 최댓값 $4$가 이미 구간 안에 들어 있다.","확인":null,"스킬":"G7","고비":true},{"제목":"첫 번째 구간의 적분","힌트":"$\\int_{0}^{\\sqrt{2}}(4t^{2}-t^{4})dt$의 값은?","식":["$\\left[\\frac{4}{3}t^{3}-\\frac{1}{5}t^{5}\\right]_{0}^{\\sqrt{2}}$","$=\\frac{8\\sqrt{2}}{3}-\\frac{4\\sqrt{2}}{5}=\\frac{28\\sqrt{2}}{15}$"],"설명":"$(\\sqrt{2})^{3}=2\\sqrt{2}$, $(\\sqrt{2})^{5}=4\\sqrt{2}$를 대입한다.","확인":null,"스킬":"D8"},{"제목":"둘째 구간과 합","힌트":"$\\int_{\\sqrt{2}}^{2}4\\,dt$를 구해 앞의 값과 더하면?","식":["$\\int_{\\sqrt{2}}^{2}4\\,dt=4(2-\\sqrt{2})=8-4\\sqrt{2}$","$\\int_{0}^{2}g(t)dt=\\frac{28\\sqrt{2}}{15}+8-4\\sqrt{2}=8-\\frac{32\\sqrt{2}}{15}$"],"설명":"$\\sqrt{2}$의 계수를 통분하면 $\\frac{28}{15}-\\frac{60}{15}=-\\frac{32}{15}$이다.","확인":null,"스킬":"D8"}]},"ns-101ee00d2316":{"길":"절댓값을 x=a에서 나눠 적분하고 a의 이차식의 최솟값을 구한다","단계":[{"제목":"절댓값 풀기","힌트":"$0\\le a\\le4$일 때 $|x-a|$는 $x=a$를 경계로 어떻게 달라지는가?","식":["$0\\le x\\le a$: $|x-a|=a-x$","$a\\le x\\le4$: $|x-a|=x-a$"],"설명":"$x=a$에서 식이 바뀌므로 적분 구간을 $[0,\\,a]$와 $[a,\\,4]$로 나눈다.","확인":null,"스킬":"C2","고비":true},{"제목":"$f(a)$ 계산","힌트":"두 구간의 적분을 각각 계산해 더하면?","식":["$\\int_{0}^{a}(a-x+1)dx=\\frac{a^{2}}{2}+a$","$\\int_{a}^{4}(x-a+1)dx=\\frac{(4-a)^{2}}{2}+(4-a)$","$f(a)=a^{2}-4a+12$"],"설명":"두 적분을 더해 $a$의 이차식으로 정리한다.","확인":null,"스킬":"D8"},{"제목":"최소가 되는 $a$","힌트":"$f(a)=a^{2}-4a+12$를 완전제곱 꼴로 쓰면?","식":["$f(a)=(a-2)^{2}+8$","$a=2$에서 최솟값 $8$"],"설명":"$0\\le a\\le4$에 $a=2$가 들어 있으므로 최솟값은 $f(2)=8$이다.","확인":"2","스킬":"A6"},{"제목":"$a$와 최솟값의 합","힌트":"$a$와 $f(a)$의 최솟값을 더하면?","식":["$2+8=10$"],"설명":"구하는 값은 $a=2$와 최솟값 $8$의 합이다.","확인":"10","스킬":"C7"}]},"ns-1380374a1c8a":{"길":"좌우 도함수의 극한이 같다는 조건으로 k를 구하고 적분상수는 연속으로 맞춘다","단계":[{"제목":"$k$ 구하기","힌트":"$x=0$에서 미분가능하려면 $f'(x)$의 좌극한과 우극한은 어떤 관계인가?","식":["$\\lim_{x\\to0-}f'(x)=k$, $\\lim_{x\\to0+}f'(x)=-4$","$k=-4$"],"설명":"미분가능한 함수의 도함수는 $x=0$에서 좌우 극한이 같다.","확인":"-4","스킬":"D12"},{"제목":"극값의 위치","힌트":"$f'(x)=0$의 해와 그 좌우의 부호는?","식":["$x\\le0$: $3x^{2}+4x-4=(3x-2)(x+2)=0$에서 $x=-2$","$x>0$: $2x-4=0$에서 $x=2$","$x=-2$: $+\\to-$ 극대, $x=2$: $-\\to+$ 극소"],"설명":"$x\\le0$에서는 $x=\\frac{2}{3}$이 범위 밖이다. $f'(-3)>0$이고 $f'(-1)<0$이므로 $x=-2$에서 극대이다. $0<x<2$에서 $f'<0$, $x>2$에서 $f'>0$이므로 $x=2$에서 극소이다.","확인":null,"스킬":"D4"},{"제목":"$f(x)$ 구하기","힌트":"각 구간에서 $f'$을 적분하고 $x=0$에서 연속이도록 적분상수를 맞추면?","식":["$x\\le0$: $f(x)=x^{3}+2x^{2}-4x+C_{1}$","$x>0$: $f(x)=x^{2}-4x+C_{2}$","$x=0$에서 연속이므로 $C_{1}=C_{2}$"],"설명":"$f$는 $x=0$에서 미분가능하므로 연속이다. 양쪽 식의 $x=0$에서의 값 $C_{1}$, $C_{2}$가 같아야 한다.","확인":null,"스킬":"D12","고비":true},{"제목":"극댓값과 극솟값의 차","힌트":"$f(-2)$와 $f(2)$를 $C_{1}$로 나타내어 빼면?","식":["$f(-2)=-8+8+8+C_{1}=8+C_{1}$","$f(2)=4-8+C_{1}=-4+C_{1}$","$f(-2)-f(2)=12$"],"설명":"$C_{1}$이 소거되므로 상수에 관계없이 차가 정해진다.","확인":"12","스킬":"D4"}]},"ns-246c75c61ccf":{"길":"g'=(xf)'로 g를 xf+C로 쓰고 극값 조건으로 α를 정한다","단계":[{"제목":"$f(x)$의 꼴","힌트":"$f(0)=0$이고 $x=\\alpha$에서 접하면 인수는 무엇인가?","식":["$f(x)=x(x-\\alpha)^{2}$"],"설명":"$f(0)=0$이므로 $x$가 인수이고, $f(\\alpha)=f'(\\alpha)=0$이므로 $(x-\\alpha)^{2}$이 인수이다. 최고차항의 계수가 $1$이다.","확인":null,"스킬":"A4"},{"제목":"$g(x)$의 꼴","힌트":"$f(x)+xf'(x)$는 어떤 함수의 도함수인가?","식":["$g'(x)=\\{xf(x)\\}'$","$g(x)=xf(x)+C=x^{2}(x-\\alpha)^{2}+C$"],"설명":"곱의 미분법에 의해 $f+xf'=(xf)'$이다. 따라서 $g$는 $xf$에 적분상수를 더한 꼴이다.","확인":null,"스킬":"D13","고비":true},{"제목":"극값의 위치와 $C$","힌트":"$g'(x)=0$인 $x$는? 극솟값이 $0$이면 $C$는?","식":["$g'(x)=2x(x-\\alpha)(2x-\\alpha)$, $x=0,\\ \\dfrac{\\alpha}{2},\\ \\alpha$","$x=0,\\ \\alpha$에서 극소: $g(0)=g(\\alpha)=C=0$"],"설명":"$g'$의 부호는 $x<0$에서 음, $0<x<\\dfrac{\\alpha}{2}$에서 양, $\\dfrac{\\alpha}{2}<x<\\alpha$에서 음, $x>\\alpha$에서 양이다. 극솟값이 $x=0,\\alpha$에서 $C$이므로 $C=0$이다.","확인":null,"스킬":"D4"},{"제목":"극댓값으로 $\\alpha$ 정하기","힌트":"극대가 되는 $x=\\dfrac{\\alpha}{2}$에서 $g$의 값을 $\\alpha$로 나타내면?","식":["$g\\left(\\dfrac{\\alpha}{2}\\right)=\\dfrac{\\alpha^{2}}{4}\\cdot\\dfrac{\\alpha^{2}}{4}=\\dfrac{\\alpha^{4}}{16}=81$","$\\alpha^{4}=1296$"],"설명":"$\\alpha$가 양수이므로 네제곱이 $1296$인 양수를 고른다.","확인":"6","스킬":"D4"},{"제목":"$g\\left(\\dfrac{\\alpha}{6}\\right)$의 값","힌트":"$\\dfrac{\\alpha}{6}$는 얼마이고 $g(x)=x^{2}(x-6)^{2}$에 넣으면?","식":["$g(1)=1^{2}\\cdot(1-6)^{2}=25$"],"설명":"$\\alpha=6$이므로 $\\dfrac{\\alpha}{6}=1$이다.","확인":"25","스킬":"A3"}]},"ns-2986a0c1d9f7":{"길":"|f|의 개형에서 최댓값이 바뀌는 지점을 찾아 g(t)를 구간별로 쓰고 적분한다","단계":[{"제목":"$f$의 극값","힌트":"$f'(x)=0$인 $x$는? $x=2$에서 $f$의 값은?","식":["$f'(x)=3x^{2}-12=3(x+2)(x-2)$","$f(-2)=8,\\ f(2)=-24$"],"설명":"$x=-2$에서 극대, $x=2$에서 극소이다.","확인":"-24","스킬":"D4"},{"제목":"$|f|$가 $8$이 되는 또 다른 점","힌트":"$f(0)$의 값은? $-2\\le x\\le0$에서 $|f(x)|$의 최댓값은?","식":["$f(0)=-8$, $|f(0)|=8=|f(-2)|$","$-2\\le x\\le0$에서 $f$는 $8$에서 $-8$까지 감소하므로 $|f(x)|\\le8$"],"설명":"그림에서 $y=|f(x)|$는 $x=-2$에서 $8$이고, $y$축과 만나는 $x=0$에서 다시 $8$이다. 그 사이에서는 $8$을 넘지 않는다.","확인":"8","스킬":"G5"},{"제목":"구간별 $g(t)$","힌트":"$t<0$일 때와 $0\\le t\\le2$일 때 $|f|$의 최댓값은 각각 어디에서 생기는가?","식":["$-2\\le t<0$: $g(t)=8$","$0\\le t\\le2$: $|f|$가 증가하므로 $g(t)=|f(t)|=-t^{3}+12t+8$"],"설명":"$0\\le t\\le2$에서 $f(t)<0$이므로 $|f(t)|=-f(t)$이고, 이 구간에서 $|f|$는 증가하므로 최댓값은 오른쪽 끝 $t$에서 생긴다.","확인":null,"스킬":"C2","고비":true},{"제목":"구간별 정적분","힌트":"$\\displaystyle\\int_{0}^{2}(-t^{3}+12t+8)\\,dt$의 값은?","식":["$\\displaystyle\\int_{-2}^{0}8\\,dt=16$","$\\displaystyle\\int_{0}^{2}(-t^{3}+12t+8)\\,dt=\\left[-\\dfrac{t^{4}}{4}+6t^{2}+8t\\right]_{0}^{2}=36$"],"설명":"구간이 $t=0$에서 나뉘므로 두 적분을 따로 계산한다.","확인":"36","스킬":"D8"},{"제목":"두 적분의 합","힌트":"두 값을 더하면?","식":["$\\displaystyle\\int_{-2}^{2}g(t)\\,dt=16+36=52$"],"설명":"$[-2,2]$ 전체의 적분은 두 구간의 적분을 더한 값이다.","확인":"52","스킬":"D8"}]},"ns-29e909d0f22a":{"길":"적분 결과를 미분하면 원래 식으로 돌아오는지 선지마다 확인한다","단계":[{"제목":"거듭제곱 적분 공식으로 ①②③ 확인","힌트":"$\\int x^{n}dx=\\dfrac{1}{n+1}x^{n+1}+C$를 각 선지에 쓰면?","식":["①: $\\int4x\\,dx=2x^{2}+C$ (거짓)","②: $\\int2x^{3}dx=\\dfrac{1}{2}x^{4}+C$ (참)","③: $\\int(-6x^{2})dx=-2x^{3}+C$ (거짓)"],"설명":"계수 $c$는 그대로 두고 $x^{n}$만 적분한다. ①의 계수는 $4\\cdot\\dfrac{1}{2}=2$, ③의 계수는 $-6\\cdot\\dfrac{1}{3}=-2$이다.","확인":null,"스킬":"C3","고비":true},{"제목":"④⑤의 성질 확인","힌트":"$\\dfrac{d}{dx}\\int x\\,dx$와 $\\int\\left(\\dfrac{d}{dx}x\\right)dx$는 각각 무엇인가?","식":["④: 좌변 $=x$, 우변 $=x+C$ (거짓)","⑤: $\\int x(x+1)dx=\\dfrac{x^{3}}{3}+\\dfrac{x^{2}}{2}+C$이고 우변은 적분의 곱이므로 다름 (거짓)"],"설명":"적분한 것을 미분하면 원래 함수가 되지만, 미분한 것을 적분하면 적분상수가 붙는다. 또 곱의 적분은 적분의 곱과 같지 않다. 따라서 옳은 것은 ②뿐이다.","확인":null,"스킬":"C3"}]},"ns-2c1d9ac42ae9":{"길":"f, F를 계수로 두고 양변을 비교해 F를 구한 뒤 xF의 구간 최솟값을 찾는다","단계":[{"제목":"$f$, $F$를 미지수로 나타내기","힌트":"$f(x)=ax+b$일 때 $F(0)=1$인 부정적분 $F(x)$는?","식":["$F(x)=\\dfrac{a}{2}x^{2}+bx+1$","$x^{2}f(x)+F(x)=ax^{3}+\\left(b+\\dfrac{a}{2}\\right)x^{2}+bx+1$"],"설명":"$F(0)=1$이므로 $F$의 상수항이 $1$이다. 이를 $x^{2}f(x)$와 더해 전개한다.","확인":null,"스킬":"C7"},{"제목":"계수 비교로 $a$, $b$","힌트":"우변 $\\int(6x^{2}-2x-2)dx=2x^{3}-x^{2}-2x+C$와 각 차수의 계수를 비교하면?","식":["$x^{3}$: $a=2$","$x^{2}$: $b+\\dfrac{a}{2}=-1$, $b=-2$","$x$: $b=-2$, 상수항: $C=1$"],"설명":"모든 실수 $x$에 대해 성립하므로 같은 차수의 계수가 서로 같다.","확인":"2","스킬":"A3","고비":true},{"제목":"$F(x)$와 $xF(x)$","힌트":"$a$, $b$를 $F$에 넣고 인수분해하면?","식":["$F(x)=x^{2}-2x+1=(x-1)^{2}$","$xF(x)=x(x-1)^{2}$"],"설명":"$a=2$, $b=-2$를 대입하면 $F$가 완전제곱식이 된다.","확인":null,"스킬":"A6"},{"제목":"구간 $[0,1]$에서의 최솟값","힌트":"$x\\ge0$이고 $(x-1)^{2}\\ge0$일 때 $x(x-1)^{2}$의 하한은? 그 값이 되는 $x$는?","식":["$0\\le x\\le1$에서 $x(x-1)^{2}\\ge0$","$x=0$ 또는 $x=1$에서 값이 $0$"],"설명":"곱의 두 인수가 모두 $0$ 이상이므로 값이 $0$보다 작아질 수 없다. 구간의 양 끝에서 $0$이 되므로 그 값이 최솟값이다.","확인":"0","스킬":"C9"}]},"ns-33bda6b909e4":{"길":"ㄱ·ㄷ은 f(x)=x를 넣어 반례를 찾고 ㄴ은 구간의 성질로 판정한다","단계":[{"제목":"ㄱ의 반례","힌트":"$f(x)=x$이면 $\\displaystyle\\int_{-1}^{1}x\\,dx$의 값은?","식":["$\\displaystyle\\int_{-1}^{1}x\\,dx=0$","$2\\displaystyle\\int_{0}^{1}x\\,dx=1$"],"설명":"두 값이 다르므로 ㄱ은 거짓이다. 좌변이 우변의 $2$배 꼴이 되려면 $f$가 짝함수여야 한다.","확인":"0","스킬":"C3","고비":true},{"제목":"ㄴ의 구간 성질","힌트":"$\\displaystyle\\int_{0}^{3}f+\\int_{3}^{1}f$는 어느 구간의 적분과 같은가?","식":["$\\displaystyle\\int_{0}^{3}f\\,dx+\\int_{3}^{1}f\\,dx=\\int_{0}^{1}f\\,dx$"],"설명":"정적분은 위끝과 아래끝이 이어지면 구간 사이의 점이 약분되므로 어떤 함수에서도 성립한다. 따라서 ㄴ은 참이다.","확인":null,"스킬":"C3"},{"제목":"ㄷ의 반례와 정리","힌트":"$f(x)=x$이면 $\\displaystyle\\int_{0}^{1}x^{2}dx$와 $\\left(\\displaystyle\\int_{0}^{1}x\\,dx\\right)^{2}$는?","식":["$\\displaystyle\\int_{0}^{1}x^{2}dx=\\dfrac{1}{3}$","$\\left(\\displaystyle\\int_{0}^{1}x\\,dx\\right)^{2}=\\dfrac{1}{4}$"],"설명":"두 값이 다르므로 ㄷ은 거짓이다. 제곱의 적분은 적분의 제곱과 같지 않다. 따라서 옳은 것은 ㄴ뿐이다.","확인":null,"스킬":"C3"}]},"ns-36482792827d":{"길":"홀함수 꼴에서 (가)로 최고차항을, (나)를 f'(0)으로 읽어 f를 정한다","단계":[{"제목":"홀함수인 다항함수의 꼴","힌트":"$f(-x)=-f(x)$이면 어떤 차수의 항만 남는가?","식":["$f(x)$는 홀수 차수의 항만 가진다","$f(0)=0$"],"설명":"$x=0$을 넣으면 $f(0)=-f(0)$이므로 $f(0)=0$이고, 짝수 차수의 항은 모두 없어진다.","확인":null,"스킬":"T2"},{"제목":"(가)로 차수와 최고차항의 계수","힌트":"최고차항을 $cx^{m}$이라 하면 $\\displaystyle\\int_{0}^{n}f\\,dx$를 $n^{4}$으로 나눈 극한이 $\\dfrac{1}{4}$이 되려면 $m$은?","식":["$\\displaystyle\\int_{0}^{n}cx^{m}dx=\\dfrac{c\\,n^{m+1}}{m+1}$이므로 $m+1=4$, $m=3$","$\\dfrac{c}{4}=\\dfrac{1}{4}$, $f(x)=x^{3}+px$"],"설명":"낮은 차수의 항은 $n^{4}$으로 나누면 $0$으로 가므로 최고차항만 극한에 남는다. $m+1$이 $4$보다 작으면 극한이 $0$이고 크면 발산한다.","확인":"1","스킬":"A11","고비":true},{"제목":"(나)로 $p$","힌트":"$n\\displaystyle\\int_{0}^{\\frac{1}{n}}f'(x)dx$를 $f\\left(\\dfrac{1}{n}\\right)$로 쓰면 어떤 극한의 꼴인가?","식":["$n\\left\\{f\\left(\\dfrac{1}{n}\\right)-f(0)\\right\\}=\\dfrac{f\\left(\\frac{1}{n}\\right)-f(0)}{\\frac{1}{n}}\\to f'(0)$","$f'(0)=p=-12$, $f(x)=x^{3}-12x$"],"설명":"$\\dfrac{1}{n}\\to0$이므로 이 극한은 $x=0$에서의 미분계수이다. $f'(x)=3x^{2}+p$에서 $f'(0)=p$이다.","확인":null,"스킬":"D3"},{"제목":"극대가 되는 $x$","힌트":"$f'(x)=3x^{2}-12=0$의 해 중 부호가 양에서 음으로 바뀌는 곳은?","식":["$f'(x)=3(x+2)(x-2)$","$x<-2$: $f'>0$, $-2<x<2$: $f'<0$"],"설명":"$f'$의 부호가 양에서 음으로 바뀌는 $x$에서 극대이다.","확인":"-2","스킬":"D4"},{"제목":"극댓값","힌트":"$f(x)=x^{3}-12x$에 극대가 되는 $x$를 넣으면?","식":["$f(-2)=-8+24=16$"],"설명":"극댓값은 극대가 되는 $x$에서의 함숫값이다.","확인":"16","스킬":"D4"}]},"ns-37dcebc2130f":{"길":"f'=|x+1|-2로 증감을 읽고 극값을 구해 보기를 하나씩 판정한다","단계":[{"제목":"$f'$의 부호와 증감","힌트":"$f'(x)=|x+1|-2=0$의 해는? 그 앞뒤에서 $f'$의 부호는?","식":["$f'(x)=|x+1|-2$, $f'(x)=0$: $x=-3,\\ 1$","$x<-3$: $f'>0$, $-3<x<1$: $f'<0$, $x>1$: $f'>0$"],"설명":"미적분의 기본정리에 의해 $f'(x)=|x+1|-2$이다. $x=1$에서 $f'$의 부호가 음에서 양으로 바뀌므로 극솟값을 가진다. 따라서 ㄴ은 참이다.","확인":null,"스킬":"D9"},{"제목":"ㄱ: $f(0)$의 값","힌트":"$0\\le t\\le2$일 때 $|t+1|$은 어떻게 쓰는가?","식":["$f(0)=\\displaystyle\\int_{2}^{0}(|t+1|-2)\\,dt=-\\int_{0}^{2}(t-1)\\,dt$","$=-\\left[\\dfrac{t^{2}}{2}-t\\right]_{0}^{2}=0$"],"설명":"위끝과 아래끝을 바꾸면 부호가 바뀐다. $0\\le t\\le2$에서 $t+1>0$이므로 $|t+1|=t+1$이다. 따라서 ㄱ은 참이다.","확인":null,"스킬":"D9"},{"제목":"극솟값과 극댓값","힌트":"$f(-3)=-\\displaystyle\\int_{-3}^{2}(|t+1|-2)\\,dt$에서 구간을 어디서 나누는가?","식":["$f(1)=-\\displaystyle\\int_{1}^{2}(t-1)\\,dt=-\\dfrac{1}{2}$","$\\displaystyle\\int_{-3}^{2}|t+1|\\,dt=2+\\dfrac{9}{2}=\\dfrac{13}{2}$, $f(-3)=-\\left(\\dfrac{13}{2}-10\\right)=\\dfrac{7}{2}$"],"설명":"$|t+1|$은 $t=-1$에서 식이 바뀌므로 구간을 $[-3,-1]$, $[-1,2]$로 나눈다. $x=-3$에서 극대, $x=1$에서 극소이다.","확인":"7/2","스킬":"D6","고비":true},{"제목":"ㄷ: 세 실근이 되는 정수 $k$","힌트":"$y=f(x)$와 $y=k$가 세 점에서 만나려면 $k$는 어느 범위에 있어야 하는가?","식":["$-\\dfrac{1}{2}<k<\\dfrac{7}{2}$","정수 $k=0,\\ 1,\\ 2,\\ 3$ → $4$개 (ㄷ 거짓)"],"설명":"극솟값보다 크고 극댓값보다 작을 때 서로 다른 세 실근이 생긴다. $6$개가 아니므로 ㄷ은 거짓이고, 옳은 것은 ㄱ, ㄴ이다.","확인":null,"스킬":"D6"}]},"ns-3b04f9762eff":{"길":"f'가 x=1에 대칭인 이차함수임을 이용해 f를 p로 두고 적분의 최솟값을 구한다","단계":[{"제목":"$f'(x)$의 꼴","힌트":"$f'(1-x)=f'(1+x)$이면 $f'$의 그래프는 어떤 직선에 대칭인가? 최고차항의 계수는?","식":["$f'(x)=3(x-1)^{2}+p$"],"설명":"삼차함수의 도함수는 최고차항의 계수가 $3$인 이차함수이다. $x=1$에 대칭이므로 꼭짓점이 $x=1$에 있다.","확인":null,"스킬":"T2","고비":true},{"제목":"(다)로 $p$의 범위","힌트":"$f'$의 최솟값은 얼마이고 그것이 $2$ 이상이려면?","식":["$f'(x)\\ge f'(1)=p$","$p\\ge2$"],"설명":"$f'$는 아래로 볼록하고 최솟값이 $x=1$에서의 값 $p$이다. 모든 $x$에서 $f'(x)\\ge2$이므로 $p\\ge2$이다.","확인":null,"스킬":"C1"},{"제목":"$f(x)$와 적분상수","힌트":"$f'$를 적분하고 $f(0)=2$를 쓰면 상수항은?","식":["$f(x)=(x-1)^{3}+px+C$","$f(0)=-1+C=2$, $C=3$"],"설명":"$\\int3(x-1)^{2}dx=(x-1)^{3}$이다.","확인":"3","스킬":"A3"},{"제목":"$\\displaystyle\\int_{0}^{1}f(x)\\,dx$를 $p$로","힌트":"$(x-1)^{3}$, $px$, $3$을 각각 $0$에서 $1$까지 적분하면? $p$가 작을수록 값은?","식":["$\\displaystyle\\int_{0}^{1}f(x)\\,dx=-\\dfrac{1}{4}+\\dfrac{p}{2}+3=\\dfrac{p}{2}+\\dfrac{11}{4}$","$p=2$일 때 최소: $k=\\dfrac{15}{4}$"],"설명":"$p$의 계수가 양수이므로 $p$가 가장 작은 $p=2$에서 최솟값을 갖는다.","확인":"15/4","스킬":"D8"},{"제목":"$40k$의 값","힌트":"$k$에 $40$을 곱하면?","식":["$40k=40\\cdot\\dfrac{15}{4}=150$"],"설명":"$k$의 값을 대입해 계산한다.","확인":"150","스킬":"A3"}]},"ns-4b6b73165412":{"길":"그래프에서 f'를 식으로 읽고 f(2)-f(-1)을 구간별 적분으로 써서 이차함수 계수를 정한다","단계":[{"제목":"그래프에서 $f'(x)$ 읽기","힌트":"$x>0$의 직선은 어느 두 점을 지나는가? $x<0$의 포물선의 꼭짓점은?","식":["$x>0$: 점 $(0,-1)$, $(2,-2)$를 지나므로 $f'(x)=-\\dfrac{1}{2}x-1$","$x<0$: 꼭짓점 $(-1,-1)$이므로 $f'(x)=k(x+1)^{2}-1$"],"설명":"직선의 기울기는 $\\dfrac{-2-(-1)}{2-0}=-\\dfrac{1}{2}$이고 $y$절편은 $-1$이다. 이차함수는 꼭짓점 꼴로 두고 계수 $k$를 나중에 정한다.","확인":null,"스킬":"G9"},{"제목":"$\\displaystyle\\int_{0}^{2}f'(x)\\,dx$","힌트":"$f(2)-f(-1)$을 $x=0$에서 나누어 쓰면? 직선 쪽 적분은?","식":["$f(2)-f(-1)=\\displaystyle\\int_{-1}^{0}f'(x)\\,dx+\\int_{0}^{2}f'(x)\\,dx$","$\\displaystyle\\int_{0}^{2}\\left(-\\dfrac{1}{2}x-1\\right)dx=\\left[-\\dfrac{x^{2}}{4}-x\\right]_{0}^{2}=-3$"],"설명":"$f$는 연속이므로 $f'$가 $x=0$에서 끊겨 있어도 구간을 나누어 적분한 값을 더하면 $f(2)-f(-1)$이 된다.","확인":"-3","스킬":"D8","고비":true},{"제목":"계수 $k$","힌트":"$\\displaystyle\\int_{-1}^{0}\\{k(x+1)^{2}-1\\}dx$를 $k$로 나타내고 $f(2)-f(-1)=1$을 쓰면?","식":["$\\displaystyle\\int_{-1}^{0}\\{k(x+1)^{2}-1\\}dx=\\dfrac{k}{3}-1$","$\\left(\\dfrac{k}{3}-1\\right)+(-3)=1$, $k=15$"],"설명":"$f(-1)=0$, $f(2)=1$이므로 $f(2)-f(-1)=1$이다.","확인":"15","스킬":"D8"},{"제목":"$f(-2)$와 $f(4)$","힌트":"$f(-1)=0$에서 $x=-2$까지, $f(2)=1$에서 $x=4$까지 $f'$를 적분하면?","식":["$f(-2)=-\\displaystyle\\int_{-2}^{-1}f'(x)\\,dx=-\\left(\\dfrac{k}{3}-1\\right)=-4$","$f(4)=1+\\displaystyle\\int_{2}^{4}\\left(-\\dfrac{1}{2}x-1\\right)dx=1-5=-4$"],"설명":"$[-2,-1]$에서 $f'$는 $[-1,0]$과 같은 포물선 식을 쓰므로 $k$를 대입해 계산한다. $x=-2$는 $x=-1$보다 왼쪽이므로 적분의 부호가 반대이다.","확인":null,"스킬":"D8"},{"제목":"$f(4)+f(-2)$","힌트":"두 값을 더하면?","식":["$f(4)+f(-2)=-4+(-4)=-8$"],"설명":"앞 단계의 두 값을 더한다.","확인":"-8","스킬":"A3"}]},"ns-542a92fe340c":{"길":"F'=f의 부호로 F의 증감을 읽고 F(1)=0을 기준으로 보기의 부호를 판정한다","단계":[{"제목":"$F$의 증감","힌트":"$F'(x)=f(x)$이므로 $f$의 부호가 바뀌는 곳은? $F(1)$의 값은?","식":["$F'(x)=f(x)$, $F(1)=0$","$x<0$: $f<0$, $0<x<2$: $f>0$, $x>2$: $f>0$"],"설명":"$F$는 $x<0$에서 감소하고 $x>0$에서 증가한다. $x=2$에서 $f=0$이지만 부호가 바뀌지 않으므로 극값이 아니다. 극소는 $x=0$뿐이다.","확인":null,"스킬":"D9"},{"제목":"ㄱ: $F\\left(\\dfrac{1}{2}\\right)$의 부호","힌트":"$F\\left(\\dfrac{1}{2}\\right)=\\displaystyle\\int_{1}^{\\frac{1}{2}}f(t)\\,dt$에서 구간 $\\left[\\dfrac{1}{2},1\\right]$의 $f$의 부호는?","식":["$F\\left(\\dfrac{1}{2}\\right)=-\\displaystyle\\int_{\\frac{1}{2}}^{1}f(t)\\,dt<0$"],"설명":"$0<t<2$에서 $f(t)>0$이므로 적분은 양수이고, 위끝과 아래끝을 바꾸면서 부호가 반대가 된다. 따라서 ㄱ은 참이다.","확인":null,"스킬":"D8"},{"제목":"ㄴ: 극솟값의 부호","힌트":"극소가 되는 $x$에서 $F$의 값을 $f$의 적분으로 쓰면?","식":["$F(0)=-\\displaystyle\\int_{0}^{1}f(t)\\,dt<0$"],"설명":"극솟값은 $F(0)$이고 $[0,1]$에서 $f>0$이므로 $F(0)$은 음수이다. 따라서 ㄴ은 거짓이다.","확인":null,"스킬":"D9","고비":true},{"제목":"ㄷ: $\\displaystyle\\int_{0}^{1}F(x)\\,dx$의 부호","힌트":"$0\\le x<1$에서 $F(x)$의 부호는?","식":["$0\\le x<1$: $F$는 증가하고 $F(1)=0$이므로 $F(x)<0$","$\\displaystyle\\int_{0}^{1}F(x)\\,dx<0$ (참)"],"설명":"$[0,1]$에서 $F$가 증가하며 오른쪽 끝에서 $0$이 되므로 그 안에서는 음수이다. 음수인 함수의 적분은 음수이다. 따라서 옳은 것은 ㄱ, ㄷ이다.","확인":null,"스킬":"D8"}]},"ns-589eca3b4a0c":{"길":"주기와 대칭으로 g(6), g(3)을 f의 값으로 바꾸고 미분가능 조건으로 f'를 정한다","단계":[{"제목":"$g(6)$, $g(3)$을 $f$로 바꾸기","힌트":"주기가 $2$이므로 $g(6)$, $g(3)$은 각각 $g(0)$, $g(1)$과 같다. $g(1)$은 (가)의 어느 줄로 계산하는가?","식":["$g(6)=g(0)=f(0)$","$g(3)=g(1)=f(2-1)=f(1)$"],"설명":"$g(x+2)=g(x)$이므로 $2$씩 줄여 $[0,2)$의 값으로 옮긴다. $x=1$은 $1\\le x<2$ 줄을 쓴다. 따라서 $|g(6)-g(3)|=|f(0)-f(1)|$이다.","확인":null,"스킬":"T2"},{"제목":"이음매에서의 미분가능 조건","힌트":"$x=1$에서 $g$의 왼쪽 미분계수와 오른쪽 미분계수는 각각 $f'$로 어떻게 쓰이는가?","식":["$x=1$: $g'(1-)=f'(1)$, $g'(1+)=-f'(1)$ → $f'(1)=0$","$x=0$: $g'(0+)=f'(0)$, $g'(0-)=g'(2-)=-f'(0)$ → $f'(0)=0$"],"설명":"$1\\le x<2$에서 $g(x)=f(2-x)$이므로 $g'(x)=-f'(2-x)$이다. 주기가 $2$이므로 $x=0$에서의 왼쪽 미분계수는 $x=2$에서의 왼쪽 미분계수와 같다. 두 미분계수가 같아야 미분가능하다.","확인":null,"스킬":"D1","고비":true},{"제목":"$f'(x)$의 꼴","힌트":"최고차항의 계수가 $1$인 사차함수의 도함수는 몇 차이고 최고차항의 계수는? 극점이 한 개이면 근의 겹침은?","식":["$f'(x)=4x(x-1)^{2}=4x^{3}-8x^{2}+4x$"],"설명":"$f'$는 최고차항의 계수가 $4$인 삼차식이고 $0$, $1$을 근으로 가진다. 극점이 한 개이므로 부호가 바뀌는 근은 하나뿐이어서 $x=1$이 중근이다.","확인":null,"스킬":"A11"},{"제목":"$f(0)$과 $f(1)$의 차","힌트":"$f(x)$를 적분상수 $C$로 쓰고 $f(0)$, $f(1)$을 구하면?","식":["$f(x)=x^{4}-\\dfrac{8}{3}x^{3}+2x^{2}+C$","$f(0)=C$, $f(1)=\\dfrac{1}{3}+C$","$|g(6)-g(3)|=|f(0)-f(1)|=\\dfrac{1}{3}$"],"설명":"적분상수 $C$는 두 값의 차에서 사라진다.","확인":"1/3","스킬":"D1"}]},"ns-596fc11565f7":{"길":"g는 짝함수, h는 홀함수, gh는 홀함수임을 먼저 확인하고 보기를 판정한다","단계":[{"제목":"$g$, $h$의 짝홀","힌트":"$g(-x)$, $h(-x)$를 $f(x)$, $f(-x)$로 쓰면?","식":["$g(-x)=f(-x)+f(x)=g(x)$ → $g$는 짝함수","$h(-x)=f(-x)-f(x)=-h(x)$ → $h$는 홀함수"],"설명":"$x$ 대신 $-x$를 넣으면 $f(x)$와 $f(-x)$의 자리만 바뀐다. 합은 그대로이고 차는 부호가 반대가 된다.","확인":null,"스킬":"T2","고비":true},{"제목":"ㄱ, ㄴ 판정","힌트":"짝함수와 홀함수를 $[-1,1]$에서 적분하면 각각?","식":["짝함수: $\\displaystyle\\int_{-1}^{1}g(x)\\,dx=2\\int_{0}^{1}g(x)\\,dx$ (ㄱ 참)","홀함수: $\\displaystyle\\int_{-1}^{1}h(x)\\,dx=0$ (ㄴ 참)"],"설명":"짝함수는 $y$축에 대칭이어서 왼쪽과 오른쪽 넓이가 같고, 홀함수는 원점에 대칭이어서 왼쪽과 오른쪽이 서로 상쇄된다.","확인":null,"스킬":"T2"},{"제목":"ㄷ 판정과 정리","힌트":"$g(x)h(x)$의 짝홀은? $\\displaystyle\\int_{-1}^{2}$를 어디서 나누는가?","식":["$g(-x)h(-x)=-g(x)h(x)$ → $gh$는 홀함수","$\\displaystyle\\int_{-1}^{2}gh\\,dx=\\int_{-1}^{1}gh\\,dx+\\int_{1}^{2}gh\\,dx=\\int_{1}^{2}gh\\,dx$ (ㄷ 참)"],"설명":"짝함수와 홀함수의 곱은 홀함수이므로 $[-1,1]$에서의 적분이 $0$이다. 따라서 ㄱ, ㄴ, ㄷ이 모두 옳다.","확인":null,"스킬":"T2"}]},"ns-5c8cb2ddc087":{"길":"g'=f로 조건을 f의 근과 적분값으로 바꾸고 인수 꼴에서 나머지 근을 정한다","단계":[{"제목":"(가)를 $f$의 조건으로 바꾸기","힌트":"$g'(x)$를 $f$로 쓰면? $x=2$에서 극값이면 $f(2)$는? $g(2)=32$를 적분으로 쓰면?","식":["$g'(x)=f(x)$, $g(-2)=0$","$f(2)=0$, $\\displaystyle\\int_{-2}^{2}f(t)\\,dt=g(2)=32$"],"설명":"미적분의 기본정리에 의해 $g'(x)=f(x)$이다. 극값을 갖는 곳에서는 $g'=0$이므로 $f(2)=0$이다. 아래끝과 위끝이 같으면 적분이 $0$이므로 $g(-2)=0$이다.","확인":null,"스킬":"D9"},{"제목":"(나)로 $f(-2)$","힌트":"$g(-2)$의 값은? 최솟값이 $0$이면 $x=-2$는 $g$의 어떤 점인가?","식":["$g(-2)=0$이 $g$의 최솟값이므로 $x=-2$는 최소점","$g'(-2)=0$, 즉 $f(-2)=0$"],"설명":"$g(-2)$가 최솟값과 같으므로 $x=-2$에서 $g$가 최소이다. 최소점에서는 $g'=0$이다.","확인":null,"스킬":"D4","고비":true},{"제목":"$f(x)$의 꼴","힌트":"$f(-2)=f(2)=0$인 삼차함수에서 나머지 근을 $a$라 하면? $a$는 $2$보다 큰가 작은가?","식":["$f(x)=(x+2)(x-2)(x-a)$, $a>2$","$=x^{3}-ax^{2}-4x+4a$"],"설명":"$g$가 $x=-2$에서 극소, $x=2$에서 극대이므로 $f$의 부호가 $x=-2$에서 음에서 양으로, $x=2$에서 양에서 음으로 바뀐다. 최고차항의 계수가 $1$이므로 나머지 근 $a$는 $2$보다 크다.","확인":null,"스킬":"A4"},{"제목":"적분 조건으로 $a$","힌트":"$\\displaystyle\\int_{-2}^{2}f(t)\\,dt=32$에서 홀수 차수의 항은 어떻게 되는가?","식":["$\\displaystyle\\int_{-2}^{2}(x^{3}-ax^{2}-4x+4a)\\,dx=2\\int_{0}^{2}(-ax^{2}+4a)\\,dx$","$=2\\left[-\\dfrac{a}{3}x^{3}+4ax\\right]_{0}^{2}=\\dfrac{32}{3}a=32$"],"설명":"$x^{3}$과 $-4x$는 홀함수이므로 $[-2,2]$에서 적분하면 $0$이다. 남는 짝함수 부분만 계산한다.","확인":"3","스킬":"D8"},{"제목":"$f(4)$의 값","힌트":"$f(x)=(x+2)(x-2)(x-3)$에 $x=4$를 넣으면?","식":["$f(4)=6\\cdot2\\cdot1=12$"],"설명":"인수분해한 꼴에 그대로 대입한다.","확인":"12","스킬":"A3"}]},"ns-611c7e355a61":{"길":"|f'|의 적분을 극값 차로 쓰면 k≤1, f(k)=0이 나오고 적분값을 k의 함수로 놓는다","단계":[{"제목":"$f'$와 $f$의 꼴","힌트":"$x=0$에서 극대, $x=k$에서 극소이면 $f'$의 근과 최고차항의 계수는? ($k>0$)","식":["$f'(x)=3x(x-k)$","$f(x)=x^{3}-\\dfrac{3}{2}kx^{2}+c$"],"설명":"삼차함수의 도함수는 최고차항의 계수가 $3$인 이차함수이다. $0<x<k$에서 $f'<0$이고 $x<0$, $x>k$에서 $f'>0$이다.","확인":null,"스킬":"D4"},{"제목":"$t<k$인 경우 판정","힌트":"$0<t<k$이면 구간 $[0,t]$에서 $f'$의 부호는? 이때 (나)의 좌변을 $f$로 쓰면?","식":["$\\displaystyle\\int_{0}^{t}|f'(x)|\\,dx=-\\int_{0}^{t}f'(x)\\,dx=-f(t)+f(0)$","$-f(t)+f(0)=f(t)+f(0)$ → $f(t)=0$"],"설명":"삼차함수 $f$는 근이 많아야 세 개이므로 $1$보다 큰 모든 $t$에서 $f(t)=0$일 수 없다. 따라서 $1$보다 큰 $t$가 $k$보다 작은 경우는 없어야 하고, $k\\le1$이다.","확인":null,"스킬":"C2","고비":true},{"제목":"$t\\ge k$인 경우로 $c$ 정하기","힌트":"구간을 $k$에서 나누어 $|f'|$을 벗기면 (나)의 좌변은?","식":["$\\displaystyle\\int_{0}^{t}|f'|\\,dx=\\{-f(k)+f(0)\\}+\\{f(t)-f(k)\\}=-2f(k)+f(t)+f(0)$","$f(k)=0$ → $c=\\dfrac{1}{2}k^{3}$"],"설명":"$[0,k]$에서는 $f'<0$이고 $[k,t]$에서는 $f'>0$이다. 좌변이 $f(t)+f(0)$과 같으려면 $f(k)=0$이어야 한다. $f(k)=k^{3}-\\dfrac{3}{2}k^{3}+c$에서 $c$가 정해진다.","확인":null,"스킬":"D8"},{"제목":"$\\displaystyle\\int_{0}^{1}f(x)\\,dx$를 $k$의 함수로","힌트":"$f(x)=x^{3}-\\dfrac{3}{2}kx^{2}+\\dfrac{1}{2}k^{3}$을 $0$에서 $1$까지 적분하면?","식":["$G(k)=\\displaystyle\\int_{0}^{1}f(x)\\,dx=\\dfrac{1}{4}-\\dfrac{1}{2}k+\\dfrac{1}{2}k^{3}$","$0<k\\le1$"],"설명":"$x$에 대해 적분하므로 $k$는 상수로 본다. 이제 $k$의 범위 $0<k\\le1$에서 $G(k)$의 최댓값과 최솟값을 구하는 문제가 된다.","확인":null,"스킬":"D8"},{"제목":"$G(k)$의 증감","힌트":"$G'(k)=0$의 해는? 그 앞뒤에서 $G'$의 부호는?","식":["$G'(k)=-\\dfrac{1}{2}+\\dfrac{3}{2}k^{2}=0$, $k=\\dfrac{1}{\\sqrt{3}}$","$0<k<\\dfrac{1}{\\sqrt{3}}$: $G'<0$, $\\dfrac{1}{\\sqrt{3}}<k\\le1$: $G'>0$"],"설명":"$k>0$이므로 음수 해는 버린다. $G$는 $k=\\dfrac{1}{\\sqrt{3}}$에서 극소이다.","확인":null,"스킬":"D4"},{"제목":"최댓값 $M$과 최솟값 $m$","힌트":"구간의 오른쪽 끝 $k=1$에서 $G$의 값은? $G(k)-\\dfrac{1}{4}$의 부호는?","식":["$G(1)=\\dfrac{1}{4}-\\dfrac{1}{2}+\\dfrac{1}{2}=\\dfrac{1}{4}$, $G(k)-\\dfrac{1}{4}=\\dfrac{k(k^{2}-1)}{2}\\le0$ → $M=\\dfrac{1}{4}$","$m=G\\left(\\dfrac{1}{\\sqrt{3}}\\right)=\\dfrac{1}{4}-\\dfrac{1}{3\\sqrt{3}}$"],"설명":"$0<k\\le1$에서 $k(k^{2}-1)\\le0$이므로 $G$는 $k=1$에서 최대이다. 최솟값은 극소점의 값이다.","확인":"1/4","스킬":"D4"},{"제목":"$M-m$의 값","힌트":"두 값의 차는?","식":["$M-m=\\dfrac{1}{3\\sqrt{3}}=\\dfrac{\\sqrt{3}}{9}$"],"설명":"분모를 유리화하면 $\\dfrac{\\sqrt{3}}{9}$이다.","확인":null,"스킬":"A3"}]},"ns-712271a94ce0":{"길":"그래프에서 f를 식으로 읽고 g'=f의 부호와 양 끝값으로 보기를 판정한다","단계":[{"제목":"그래프에서 $f(x)$ 읽기","힌트":"$x$절편이 $-1$, $1$이면 $f(x)=a(x+1)(x-1)$이다. $f(2)=-3$에서 $a$는?","식":["$f(x)=a(x+1)(x-1)$, $f(2)=3a=-3$","$f(x)=1-x^{2}$"],"설명":"$f(0)=-a=1$로도 확인된다.","확인":"-1","스킬":"G1"},{"제목":"$g(x)$와 증감","힌트":"$g'(x)=f(x)$이므로 $g$는 어느 구간에서 증가하고 어느 구간에서 감소하는가?","식":["$g(x)=\\displaystyle\\int_{-1}^{x}(1-t^{2})\\,dt=x-\\dfrac{x^{3}}{3}+\\dfrac{2}{3}$","$-1<x<1$: $g'>0$, $1<x<2$: $g'<0$"],"설명":"$f>0$인 구간에서 $g$는 증가하고 $f<0$인 구간에서 $g$는 감소한다.","확인":null,"스킬":"D9"},{"제목":"ㄱ, ㄴ 판정","힌트":"극대인 $x$에서 $g$의 값은? 구간의 양 끝에서 $g$의 값은?","식":["$g(1)=1-\\dfrac{1}{3}+\\dfrac{2}{3}=\\dfrac{4}{3}$ (ㄱ 참)","$g(-1)=0$, $g(2)=2-\\dfrac{8}{3}+\\dfrac{2}{3}=0$이므로 최솟값 $0$ (ㄴ 참)"],"설명":"$g$는 $x=-1$에서 증가해 $x=1$에서 최대가 된 뒤 감소한다. 따라서 최솟값은 양 끝 $g(-1)$, $g(2)$ 중 작은 값이고, 두 값이 모두 $0$이다.","확인":null,"스킬":"D9","고비":true},{"제목":"ㄷ 판정","힌트":"$\\displaystyle\\int_{1}^{2}g'(x)\\,dx$는 $g$의 어떤 값의 차인가?","식":["$\\displaystyle\\int_{1}^{2}g'(x)\\,dx=g(2)-g(1)=0-\\dfrac{4}{3}<0$ (ㄷ 참)"],"설명":"$g'=f$이고 $[1,2]$에서 $f<0$이므로 적분은 음수이다. 따라서 ㄱ, ㄴ, ㄷ이 모두 옳다.","확인":null,"스킬":"D8"}]},"ns-762681008e47":{"길":"(가)(나)로 주기 2를 구하고 홀함수 부분의 적분을 0으로 처리한다","단계":[{"제목":"$f$의 주기","힌트":"$f(x)=f(2-x)$의 $x$ 자리에 $x+2$를 넣고 (가)를 쓰면?","식":["$f(x+2)=f(2-(x+2))=f(-x)=f(x)$"],"설명":"(나)에서 $f(x+2)=f(-x)$이고 (가)에서 $f(-x)=f(x)$이므로 $f(x+2)=f(x)$이다. 따라서 $f$는 주기가 $2$인 주기함수이다.","확인":null,"스킬":"T2","고비":true},{"제목":"홀함수 부분의 적분","힌트":"$(x^{3}-x)f(x)$는 짝함수인가 홀함수인가? 이 함수의 $[-10,10]$ 적분은?","식":["$\\displaystyle\\int_{-10}^{10}(x^{3}-x+2)f(x)\\,dx=\\int_{-10}^{10}(x^{3}-x)f(x)\\,dx+2\\int_{-10}^{10}f(x)\\,dx$","$(x^{3}-x)f(x)$는 홀함수 → 첫째 적분 $=0$"],"설명":"$x^{3}-x$는 홀함수이고 $f$는 (가)에 의해 짝함수이므로 곱은 홀함수이다. 홀함수는 원점 대칭 구간에서 적분하면 $0$이다.","확인":"0","스킬":"T2"},{"제목":"$\\displaystyle\\int_{-10}^{10}f(x)\\,dx$","힌트":"길이 $20$인 구간에는 주기 $2$가 몇 번 들어가는가?","식":["$\\displaystyle\\int_{-10}^{10}f(x)\\,dx=10\\int_{0}^{2}f(x)\\,dx=10\\cdot2=20$"],"설명":"주기함수는 길이가 한 주기인 구간마다 적분값이 같다. $20\\div2=10$개의 구간이 있다.","확인":"20","스킬":"D8"},{"제목":"구하는 값","힌트":"앞의 두 결과를 합하면?","식":["$0+2\\cdot20=40$"],"설명":"둘째 적분에 곱해진 $2$를 잊지 않는다.","확인":"40","스킬":"A3"}]},"ns-9007a319e58e":{"길":"그래프에서 f를 식으로 읽고 g를 구간 적분으로 바꿔 미분해 최솟점을 찾는다","단계":[{"제목":"그래프에서 $f(x)$ 읽기","힌트":"$x$절편이 $0$, $3$이면 $f(x)=cx(x-3)$이다. 최솟값 $-\\dfrac{9}{2}$를 이용하면 $c$는?","식":["$f(x)=cx(x-3)$, 최솟값은 $x=\\dfrac{3}{2}$에서 $-\\dfrac{9c}{4}=-\\dfrac{9}{2}$","$f(x)=2x^{2}-6x$"],"설명":"이차함수는 두 근의 중점에서 최소이다.","확인":"2","스킬":"G7"},{"제목":"$g(x)$를 구간 적분으로 바꾸고 미분","힌트":"$s=t+x$로 치환하면 적분 구간은? 위끝과 아래끝을 미분하면?","식":["$g(x)=\\displaystyle\\int_{x}^{x+1}f(s)\\,ds$","$g'(x)=f(x+1)-f(x)=4x-4$"],"설명":"$t$가 $0$에서 $1$까지 움직이면 $s=t+x$는 $x$에서 $x+1$까지 움직인다. 적분의 위끝이 $x+1$, 아래끝이 $x$인 함수를 미분하면 위끝과 아래끝에서의 $f$의 값의 차가 된다.","확인":null,"스킬":"D9","고비":true},{"제목":"최솟점 $a$","힌트":"$g'(x)=0$인 $x$는? 그 앞뒤에서 $g'$의 부호는?","식":["$g'(x)=4x-4=0$, $x=1$","$x<1$: $g'<0$, $x>1$: $g'>0$ → $a=1$"],"설명":"$g'$의 부호가 음에서 양으로 바뀌므로 $x=1$에서 최소이다.","확인":"1","스킬":"D4"},{"제목":"최솟값 $b$","힌트":"$g(1)=\\displaystyle\\int_{1}^{2}f(s)\\,ds$를 계산하면?","식":["$b=g(1)=\\displaystyle\\int_{1}^{2}(2s^{2}-6s)\\,ds=\\left[\\dfrac{2}{3}s^{3}-3s^{2}\\right]_{1}^{2}=-\\dfrac{13}{3}$"],"설명":"위끝 $2$와 아래끝 $1$을 각각 대입한 값의 차이다.","확인":"-13/3","스킬":"D8"},{"제목":"$a-3b$의 값","힌트":"$a=1$, $b=-\\dfrac{13}{3}$을 넣으면?","식":["$a-3b=1-3\\cdot\\left(-\\dfrac{13}{3}\\right)=14$"],"설명":"$-3b$는 양수가 되므로 $1$에 $13$을 더한다.","확인":"14","스킬":"A3"}]},"ns-9cc0529d43af":{"길":"극값 앞뒤의 증감으로 |f'|의 부호를 벗겨 구간별 함숫값의 변화량을 더한다","단계":[{"제목":"증가·감소 구간 읽기","힌트":"극값이 $x=-2$, $x=3$이면 $[-2,3]$과 $[3,6]$에서 $f$는 각각 증가인가 감소인가?","식":["$-2\\le x\\le3$: $f$ 감소, $f'\\le0$","$3\\le x\\le6$: $f$ 증가, $f'\\ge0$"],"설명":"$x=-2$에서 극대, $x=3$에서 극소이다. 따라서 극대에서 극소까지는 감소하고 극소 이후는 증가한다.","확인":null,"스킬":"D4"},{"제목":"$[-2,3]$ 구간","힌트":"$f'\\le0$인 구간에서 $|f'|$은 $f'$와 부호가 어떻게 다른가? 값은 $f(-2)$, $f(3)$으로 쓰면?","식":["$\\displaystyle\\int_{-2}^{3}|f'(x)|\\,dx=-\\int_{-2}^{3}f'(x)\\,dx=f(-2)-f(3)$","$=3-(-4)=7$"],"설명":"$f'\\le0$이면 $|f'|=-f'$이므로 적분하면 $f$의 감소량이 된다.","확인":"7","스킬":"D8","고비":true},{"제목":"$[3,6]$ 구간","힌트":"$f'\\ge0$인 구간에서 $\\displaystyle\\int|f'|$은 $f$의 어떤 변화량인가?","식":["$\\displaystyle\\int_{3}^{6}|f'(x)|\\,dx=\\int_{3}^{6}f'(x)\\,dx=f(6)-f(3)$","$=6-(-4)=10$"],"설명":"$f'\\ge0$이면 $|f'|=f'$이므로 $f$의 증가량이 된다.","확인":"10","스킬":"D8"},{"제목":"두 구간의 합","힌트":"두 값을 더하면?","식":["$\\displaystyle\\int_{-2}^{6}|f'(x)|\\,dx=7+10=17$"],"설명":"구간을 $x=3$에서 나누어 적분한 값을 더한다.","확인":"17","스킬":"A3"}]},"ns-b01c53607589":{"길":"그래프에서 f를 읽고 g'=(xf)'로 g를 xf+C로 쓴 뒤 극값 조건으로 α를 정한다","단계":[{"제목":"그래프에서 $f(x)$ 읽기","힌트":"그래프는 $x=0$과 $x=\\alpha$에서 $x$축과 어떻게 만나는가? 최고차항의 계수는?","식":["$f(x)=x(x-\\alpha)^{2}$"],"설명":"$x=0$에서는 $x$축을 지나므로 단순근이고, $x=\\alpha$에서는 접하므로 중근이다. 최고차항의 계수가 $1$이다.","확인":null,"스킬":"G1"},{"제목":"$g(x)$의 꼴","힌트":"$f(x)+xf'(x)$는 어떤 함수의 도함수인가?","식":["$g'(x)=\\{xf(x)\\}'$","$g(x)=xf(x)+C=x^{2}(x-\\alpha)^{2}+C$"],"설명":"곱의 미분법에 의해 $f+xf'=(xf)'$이다. 따라서 $g$는 $xf$에 적분상수를 더한 꼴이다.","확인":null,"스킬":"D13","고비":true},{"제목":"극값의 위치와 $C$","힌트":"$g'(x)=0$인 $x$는? 극솟값이 $0$이면 $C$는?","식":["$g'(x)=2x(x-\\alpha)(2x-\\alpha)$, $x=0,\\ \\dfrac{\\alpha}{2},\\ \\alpha$","$x=0,\\ \\alpha$에서 극소: $g(0)=g(\\alpha)=C=0$"],"설명":"$g'$의 부호는 $x=\\dfrac{\\alpha}{2}$에서 양에서 음으로 바뀌므로 극대이고, $x=0$, $x=\\alpha$에서 음에서 양으로 바뀌므로 극소이다. 극솟값이 $C$이므로 $C=0$이다.","확인":null,"스킬":"D4"},{"제목":"극댓값으로 $\\alpha$ 정하기","힌트":"$g\\left(\\dfrac{\\alpha}{2}\\right)$를 $\\alpha$로 나타내고 $16$과 같다고 놓으면?","식":["$g\\left(\\dfrac{\\alpha}{2}\\right)=\\dfrac{\\alpha^{2}}{4}\\cdot\\dfrac{\\alpha^{2}}{4}=\\dfrac{\\alpha^{4}}{16}=16$","$\\alpha^{4}=256$"],"설명":"$\\alpha$가 양수이므로 네제곱이 $256$인 양수를 고른다.","확인":"4","스킬":"D4"},{"제목":"$g\\left(\\dfrac{\\alpha}{4}\\right)$의 값","힌트":"$\\dfrac{\\alpha}{4}$는 얼마이고 $g(x)=x^{2}(x-4)^{2}$에 넣으면?","식":["$g(1)=1^{2}\\cdot(1-4)^{2}=9$"],"설명":"$\\alpha=4$이므로 $\\dfrac{\\alpha}{4}=1$이다.","확인":"9","스킬":"A3"}]},"ns-0dbbe6ee7b5e":{"길":"f와 역함수 g 사이의 넓이를 f와 y=x 사이 넓이의 2배로 바꿔 구간별로 계산한다","단계":[{"제목":"$f$의 값과 교점","힌트":"$f'\\ge0$이면 $f$는 증가함수이다. $f(x)=x$인 세 점에서 $f(0)$, $f(1)$, $f(2)$는?","식":["$f(0)=0,\\ f(1)=1,\\ f(2)=2$","$f$와 $g$는 $y=x$에 대칭이고 교점은 $x=0,1,2$"],"설명":"증가함수는 역함수가 있다. 역함수의 그래프는 $y=x$에 대칭이므로 $f$와 $g$는 $f(x)=x$인 점에서 만난다.","확인":null,"스킬":"T1"},{"제목":"$[0,1]$에서 $f$와 $y=x$ 사이 넓이","힌트":"$\\displaystyle\\int_{0}^{1}f(x)\\,dx=\\dfrac{3}{4}$에서 $\\displaystyle\\int_{0}^{1}x\\,dx$를 빼면?","식":["$\\displaystyle\\int_{0}^{1}\\{f(x)-x\\}\\,dx=\\dfrac{3}{4}-\\dfrac{1}{2}=\\dfrac{1}{4}$"],"설명":"값이 양수이므로 $0<x<1$에서 $f$가 $y=x$보다 위에 있다. 두 그래프는 $x=0,1$ 사이에서 더 만나지 않으므로 이 구간에서 부호가 바뀌지 않는다.","확인":"1/4","스킬":"D8"},{"제목":"$[1,2]$에서 $f$와 $y=x$ 사이 넓이","힌트":"$\\displaystyle\\int_{1}^{2}f(x)\\,dx$를 $\\displaystyle\\int_{0}^{2}$와 $\\displaystyle\\int_{0}^{1}$로 구하면?","식":["$\\displaystyle\\int_{1}^{2}f(x)\\,dx=\\dfrac{25}{12}-\\dfrac{3}{4}=\\dfrac{4}{3}$","$\\displaystyle\\int_{1}^{2}\\{x-f(x)\\}\\,dx=\\dfrac{3}{2}-\\dfrac{4}{3}=\\dfrac{1}{6}$"],"설명":"$x-f(x)$의 적분이 양수이므로 $1<x<2$에서는 $f$가 $y=x$보다 아래에 있다.","확인":"1/6","스킬":"D8"},{"제목":"$f$와 $g$ 사이 넓이와의 관계","힌트":"$y=x$에 대해 $f$의 그래프를 접으면 $g$가 된다. $f$와 $g$ 사이 넓이는 $f$와 $y=x$ 사이 넓이의 몇 배인가?","식":["$\\displaystyle\\int_{a}^{b}|f(x)-g(x)|\\,dx=2\\int_{a}^{b}|f(x)-x|\\,dx$ ($a,b$는 연속한 교점)"],"설명":"$f$와 $y=x$ 사이 영역을 $y=x$에 대칭으로 옮기면 $g$와 $y=x$ 사이 영역이 되어 넓이가 같다. 두 영역이 $y=x$ 양쪽에 있으므로 $f$와 $g$ 사이 넓이는 그 두 배이다.","확인":null,"스킬":"T1","고비":true},{"제목":"구하는 값","힌트":"두 구간의 넓이를 더해 두 배하면?","식":["$\\displaystyle\\int_{0}^{2}|f(x)-g(x)|\\,dx=2\\left(\\dfrac{1}{4}+\\dfrac{1}{6}\\right)=\\dfrac{5}{6}$"],"설명":"구간 $[0,1]$과 $[1,2]$에서 구한 넓이를 더한 값의 두 배이다.","확인":"5/6","스킬":"D8"}]},"ns-289eeabe8fbc":{"길":"S2=S1+S3를 부호 있는 넓이로 읽으면 0에서 2까지의 정적분이 0이다","단계":[{"제목":"조건을 정적분으로 바꾸기","힌트":"$x$축 위의 넓이와 아래의 넓이가 정적분에서 각각 어떤 부호로 들어가는가?","식":["$\\displaystyle\\int_{0}^{2}(x^{2}-2x+a)\\,dx=S_{1}-S_{2}+S_{3}$","$S_{2}=S_{1}+S_{3}$이므로 $\\displaystyle\\int_{0}^{2}(x^{2}-2x+a)\\,dx=0$"],"설명":"정적분은 $x$축 위쪽 넓이를 더하고 아래쪽 넓이를 뺀다. $S_{1}$, $S_{3}$은 위쪽이고 $S_{2}$는 아래쪽이다.","확인":null,"스킬":"D8","고비":true},{"제목":"정적분 계산","힌트":"$\\left[\\dfrac{x^{3}}{3}-x^{2}+ax\\right]_{0}^{2}$를 계산하면 $a$를 뺀 부분은?","식":["$\\displaystyle\\int_{0}^{2}(x^{2}-2x+a)\\,dx=\\dfrac{8}{3}-4+2a$","$-\\dfrac{4}{3}+2a=0$"],"설명":"$a$가 상수이므로 $a$의 적분은 $ax$이다. 상수가 아닌 부분 $\\dfrac{8}{3}-4$를 먼저 정리한다.","확인":"-4/3","스킬":"D8"},{"제목":"$a$의 값","힌트":"$-\\dfrac{4}{3}+2a=0$을 $a$에 대해 풀면?","식":["$2a=\\dfrac{4}{3}$, $a=\\dfrac{2}{3}$"],"설명":"이때 $x^{2}-2x+\\dfrac{2}{3}=0$의 두 근이 $0<x<2$ 안에 있으므로 조건에 맞는다.","확인":"2/3","스킬":"A3"}]},"ns-28f9c1daa4ed":{"길":"네 구간의 넓이를 A, B, C, D로 두고 조건을 A=B+C+D로 옮겨 보기를 판정한다","단계":[{"제목":"조건을 넓이 식으로","힌트":"$[0,a]$, $[a,b]$, $[b,c]$, $[c,d]$에서 $v$와 $t$축 사이의 넓이를 차례로 $\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{C}$, $\\mathrm{D}$라 하면 $\\displaystyle\\int_{0}^{b}v\\,dt$와 $\\displaystyle\\int_{b}^{d}|v|\\,dt$는?","식":["$\\displaystyle\\int_{0}^{b}v\\,dt=\\mathrm{A}-\\mathrm{B}$, $\\displaystyle\\int_{b}^{d}|v|\\,dt=\\mathrm{C}+\\mathrm{D}$","$\\mathrm{A}-\\mathrm{B}=\\mathrm{C}+\\mathrm{D}$, 즉 $\\mathrm{A}=\\mathrm{B}+\\mathrm{C}+\\mathrm{D}$"],"설명":"$[0,a]$에서 $v>0$, $[a,c]$에서 $v<0$, $[c,d]$에서 $v>0$이다. 정적분은 $v<0$인 구간의 넓이를 뺀다.","확인":null,"스킬":"D8","고비":true},{"제목":"ㄱ 판정","힌트":"$\\displaystyle\\int_{0}^{a}|v|\\,dt$와 $\\displaystyle\\int_{a}^{d}|v|\\,dt$를 $\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{C}$, $\\mathrm{D}$로 쓰면?","식":["$\\displaystyle\\int_{0}^{a}|v|\\,dt=\\mathrm{A}$","$\\displaystyle\\int_{a}^{d}|v|\\,dt=\\mathrm{B}+\\mathrm{C}+\\mathrm{D}$ → 서로 같다 (ㄱ 참)"],"설명":"앞 단계에서 $\\mathrm{A}=\\mathrm{B}+\\mathrm{C}+\\mathrm{D}$를 얻었다.","확인":null,"스킬":"D10"},{"제목":"ㄴ 판정","힌트":"$\\displaystyle\\int_{0}^{a}|v|\\,dt+\\int_{c}^{d}v\\,dt$와 $-\\displaystyle\\int_{a}^{c}v\\,dt$를 넓이로 쓰고 비교하면?","식":["좌변 $=\\mathrm{A}+\\mathrm{D}$, 우변 $=\\mathrm{B}+\\mathrm{C}$","$\\mathrm{A}=\\mathrm{B}+\\mathrm{C}+\\mathrm{D}$이므로 $\\mathrm{A}+\\mathrm{D}=\\mathrm{B}+\\mathrm{C}+2\\mathrm{D}\\ne\\mathrm{B}+\\mathrm{C}$ (ㄴ 거짓)"],"설명":"$[a,c]$에서 $v<0$이므로 $-\\displaystyle\\int_{a}^{c}v\\,dt=\\mathrm{B}+\\mathrm{C}$이다. $\\mathrm{D}>0$이므로 두 값이 다르다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 판정","힌트":"시각 $c$에서 점 $\\mathrm{P}$의 위치를 넓이로 쓰면? 부호는?","식":["$t=c$에서의 위치 $=\\mathrm{A}-\\mathrm{B}-\\mathrm{C}=\\mathrm{D}>0$","$t=c$ 이후에는 $v>0$이라 위치가 더 커짐 (ㄷ 거짓)"],"설명":"$[0,a]$에서 위치는 양수로 커지고 $[a,c]$에서 줄어들어 $t=c$에서 가장 작아지는데, 그 값이 양수이다. 원점을 다시 지나지 않는다. 따라서 옳은 것은 ㄱ뿐이다.","확인":null,"스킬":"D10"}]},"ns-3265f1f8d30b":{"길":"위치=출발점+∫v, 거리=∫|v|를 구간별로 나눠 보기를 하나씩 판정한다","단계":[{"제목":"ㄱ: $t=2$의 위치","힌트":"출발점이 $-1$일 때 시각 $t$의 위치를 적분으로 쓰면?","식":["위치 $=-1+\\displaystyle\\int_{0}^{t}v(s)\\,ds$","$t=2$: $-1+4=3$ (ㄱ 참)"],"설명":"위치는 출발점의 좌표에 속도의 정적분을 더한 값이다.","확인":null,"스킬":"D10"},{"제목":"ㄴ: 두 번째 방향 전환의 가속도","힌트":"$v$의 부호가 바뀌는 시각은? 두 번째 시각에서 $v$의 그래프는 오르는가 내리는가?","식":["$v$의 부호가 바뀌는 시각: $t=2$, $t=4$","$t=4$에서 $v$가 음에서 양으로 증가하므로 $v'(4)>0$ (ㄴ 거짓)"],"설명":"가속도는 $v'(t)$이다. 그래프가 오르는 곳에서 기울기가 양수이므로 가속도는 양수이다.","확인":null,"스킬":"D10","고비":true},{"제목":"$\\displaystyle\\int_{2}^{3}|v|\\,dt$","힌트":"$t=2$에서의 위치와 $t=3$에서의 위치의 차는? $[2,3]$에서 $v$의 부호는?","식":["$[2,3]$에서 $v<0$이므로 $\\displaystyle\\int_{2}^{3}|v|\\,dt=($t=2$의 위치$)-($t=3$의 위치$)$","$=3-2=1$"],"설명":"$v<0$인 구간에서는 점이 왼쪽으로 움직여 위치가 줄어든 만큼이 움직인 거리이다.","확인":"1","스킬":"D10"},{"제목":"ㄷ: $t=0$에서 $t=3$까지 움직인 거리","힌트":"$[0,2]$에서 $v>0$일 때 $\\displaystyle\\int_{0}^{2}|v|\\,dt$는? 앞 단계의 값을 더하면?","식":["$\\displaystyle\\int_{0}^{3}|v|\\,dt=\\int_{0}^{2}v\\,dt+\\int_{2}^{3}|v|\\,dt=4+1=5$ (ㄷ 참)"],"설명":"움직인 거리는 속도의 절댓값의 적분이다. 구간을 $t=2$에서 나눈다.","확인":null,"스킬":"D10"},{"제목":"ㄹ: $t=3$에서 $t=5$까지 위치의 변화량","힌트":"$\\displaystyle\\int_{3}^{5}|v|\\,dt$는? $[3,4]$에서 점은 어느 쪽으로 움직이는가?","식":["$\\displaystyle\\int_{3}^{5}|v|\\,dt=\\int_{2}^{5}|v|\\,dt-\\int_{2}^{3}|v|\\,dt=4-1=3$","$[3,4]$에서는 되돌아가므로 변화량 $<3$ (ㄹ 거짓)"],"설명":"거리는 $3$이지만 $[3,4]$에서 $v<0$이므로 위치의 변화량은 거리보다 작다. 따라서 옳은 것은 ㄱ, ㄷ이다.","확인":null,"스킬":"D10"}]},"ns-4a6d74516593":{"길":"그래프와 t축 사이의 넓이로 위치와 거리를 구해 보기를 판정한다","단계":[{"제목":"구간별 넓이","힌트":"$[0,2]$, $[2,4]$는 삼각형이고 $[4,7]$은 윗변 $1$, 아랫변 $3$인 사다리꼴이다. $[4,7]$의 넓이는?","식":["$[0,2]$: $\\dfrac{1}{2}\\cdot2\\cdot2=2$ ($v\\ge0$)","$[2,4]$: $\\dfrac{1}{2}\\cdot2\\cdot2=2$ ($v\\le0$)","$[4,7]$: $\\dfrac{1}{2}(1+3)\\cdot2=4$ ($v\\ge0$)"],"설명":"$[4,7]$에서 $v=2$인 평평한 구간이 $5\\le t\\le6$이므로 윗변이 $1$이고 아랫변이 $4\\le t\\le7$로 $3$이다.","확인":"4","스킬":"D10","고비":true},{"제목":"ㄱ, ㄴ 판정","힌트":"$\\displaystyle\\int_{0}^{4}v\\,dt$는? $t=3$의 좌우에서 $v$의 부호는?","식":["$\\displaystyle\\int_{0}^{4}v\\,dt=2-2=0$ → $t=4$에서 원점 (ㄱ 참)","$t=3$의 좌우에서 모두 $v<0$ → 방향을 바꾸지 않음 (ㄴ 거짓)"],"설명":"위치는 속도의 정적분이다. 운동 방향은 $v$의 부호가 바뀔 때 바뀌며, $t=3$은 $v$가 가장 작아지는 곳일 뿐 부호는 그대로이다.","확인":null,"스킬":"D10"},{"제목":"ㄷ: 움직인 거리","힌트":"움직인 거리는 $\\displaystyle\\int_{0}^{7}|v|\\,dt$이다. 세 구간의 넓이를 모두 더하면?","식":["$\\displaystyle\\int_{0}^{7}|v|\\,dt=2+2+4=8$ (ㄷ 참)"],"설명":"거리는 넓이에 부호를 붙이지 않고 더한다. 따라서 옳은 것은 ㄱ, ㄷ이다.","확인":null,"스킬":"D10"}]},"ns-54bec5a642cd":{"길":"한 꼭짓점 쪽 포물선을 좌표에 올려 모서리 부분의 넓이를 구하고 전체에서 세 배 뺀다","단계":[{"제목":"삼각형을 좌표에 올리기","힌트":"점 $\\mathrm{A}$를 $y$축 위에, 중점 $\\mathrm{P}$, $\\mathrm{R}$를 $x$축 위에 두면 $\\mathrm{P}$, $\\mathrm{R}$, $\\mathrm{A}$의 좌표는?","식":["$\\overline{\\mathrm{PR}}=2$이므로 $\\mathrm{P}(-1,\\,0)$, $\\mathrm{R}(1,\\,0)$","$\\overline{\\mathrm{AP}}=2$이므로 $\\mathrm{A}(0,\\,\\sqrt{3})$"],"설명":"$\\overline{\\mathrm{PR}}$는 $\\overline{\\mathrm{BC}}$의 절반이다. 한 변의 길이가 $2$인 정삼각형 $\\mathrm{APR}$의 높이는 $\\sqrt{3}$이다.","확인":null,"스킬":"S4"},{"제목":"꼭짓점 $\\mathrm{A}$ 쪽 포물선의 식","힌트":"$y=ax^{2}+b$가 $\\mathrm{P}$, $\\mathrm{R}$을 지나면 $b$는? $\\mathrm{P}$에서의 접선은 직선 $\\mathrm{AB}$이다. 그 기울기는?","식":["$a+b=0$, $y=ax^{2}-a$, $y'=2ax$","$x=-1$에서 접선 $\\mathrm{AP}$의 기울기가 $\\sqrt{3}$이므로 $-2a=\\sqrt{3}$","$y=-\\dfrac{\\sqrt{3}}{2}x^{2}+\\dfrac{\\sqrt{3}}{2}$"],"설명":"포물선은 $y$축에 대칭이므로 $y=ax^{2}+b$로 둔다. 직선 $\\mathrm{AP}$는 $(-1,0)$과 $(0,\\sqrt{3})$을 지나므로 기울기가 $\\sqrt{3}$이다.","확인":null,"스킬":"D1","고비":true},{"제목":"한 모서리에서 색칠하지 않는 부분의 넓이","힌트":"삼각형 $\\mathrm{APR}$의 넓이에서 포물선과 $\\overline{\\mathrm{PR}}$ 사이의 넓이를 빼면?","식":["$\\triangle\\mathrm{APR}=\\dfrac{1}{2}\\cdot2\\cdot\\sqrt{3}=\\sqrt{3}$","$\\displaystyle\\int_{-1}^{1}\\left(-\\dfrac{\\sqrt{3}}{2}x^{2}+\\dfrac{\\sqrt{3}}{2}\\right)dx=\\dfrac{2\\sqrt{3}}{3}$","$\\sqrt{3}-\\dfrac{2\\sqrt{3}}{3}=\\dfrac{\\sqrt{3}}{3}$"],"설명":"삼각형 $\\mathrm{APR}$ 안에서 포물선 바깥의 부분이 꼭짓점 $\\mathrm{A}$ 쪽에서 색칠하지 않은 부분이다. 정삼각형이므로 세 꼭짓점에서 모양과 넓이가 같다.","확인":null,"스킬":"D8"},{"제목":"색칠한 부분의 넓이","힌트":"정삼각형 $\\mathrm{ABC}$의 넓이에서 세 모서리의 넓이를 빼면?","식":["$\\triangle\\mathrm{ABC}=\\dfrac{\\sqrt{3}}{4}\\cdot4^{2}=4\\sqrt{3}$","$4\\sqrt{3}-3\\cdot\\dfrac{\\sqrt{3}}{3}=3\\sqrt{3}$"],"설명":"색칠한 부분은 정삼각형에서 세 꼭짓점 쪽의 부분을 뺀 것이다.","확인":null,"스킬":"S8"}]},"ns-5d9fb975f07f":{"길":"세 구간의 넓이를 p, q, r로 두고 조건을 2q=p+r로 옮긴 뒤 위치를 비교한다","단계":[{"제목":"조건을 넓이 식으로","힌트":"$\\displaystyle\\int_{0}^{a}v\\,dt=p$, $\\displaystyle\\int_{a}^{b}|v|\\,dt=q$, $\\displaystyle\\int_{b}^{c}v\\,dt=r$라 하면 $\\displaystyle\\int_{0}^{b}v\\,dt$와 $\\displaystyle\\int_{a}^{c}v\\,dt$는?","식":["$\\displaystyle\\int_{0}^{b}v\\,dt=p-q<0$, $\\displaystyle\\int_{a}^{c}v\\,dt=-q+r$","$|p-q|=q-p=r-q$, 즉 $2q=p+r$"],"설명":"$[0,a]$에서 $v>0$, $[a,b]$에서 $v<0$, $[b,c]$에서 $v>0$이다. 정적분이 음수이므로 절댓값은 $q-p$이다.","확인":null,"스킬":"D8","고비":true},{"제목":"ㄱ 판정","힌트":"$\\displaystyle\\int_{0}^{c}|v|\\,dt$를 $p$, $q$, $r$로 쓰고 $2q=p+r$를 넣으면?","식":["$\\displaystyle\\int_{0}^{c}|v|\\,dt=p+q+r=3q$","$2\\displaystyle\\int_{a}^{b}|v|\\,dt=2q$이고 $q>0$이므로 서로 다르다 (ㄱ 거짓)"],"설명":"$p+r=2q$이므로 $p+q+r=3q$이다. $q$는 양수여서 $3q\\ne2q$이다.","확인":null,"스킬":"C3"},{"제목":"ㄴ 판정: 시각 $a$, $b$, $c$의 위치","힌트":"위치는 $\\displaystyle\\int_{0}^{t}v\\,ds$이다. $t=a$, $b$, $c$에서 각각 부호는?","식":["$t=a$: $p>0$","$t=b$: $p-q<0$","$t=c$: $p-q+r=q>0$"],"설명":"$t=c$의 위치는 $p+r=2q$를 넣어 $p-q+r=q$이다. 위치가 양수에서 음수로, 다시 음수에서 양수로 바뀌므로 $(a,b)$와 $(b,c)$에서 원점을 한 번씩 지난다. 따라서 $t=a$에서 $t=c$ 사이에 두 번 지난다 (ㄴ 참).","확인":null,"스킬":"D10"},{"제목":"ㄷ 판정: 원점에서 가장 먼 시각","힌트":"세 시각의 원점으로부터의 거리 $p$, $q-p$, $q$ 중 가장 큰 것은?","식":["$q-p>0$이므로 $q>p$","$p>0$이므로 $q>q-p$","$t=c$에서 거리가 $q$로 가장 큼 (ㄷ 참)"],"설명":"위치가 꺾이는 곳은 $t=a$, $t=b$뿐이고 $t=c$는 끝점이다. 세 곳의 거리를 비교하면 $t=c$가 가장 크다. 따라서 옳은 것은 ㄴ, ㄷ이다.","확인":null,"스킬":"D10"}]},"ns-73de190a2dca":{"길":"곡선과 직선의 교점으로 S1을 구하고 전체 넓이에서 빼서 S2를 구한다","단계":[{"제목":"곡선과 직선의 교점","힌트":"$-2x^{2}+6x=2x$를 풀면 $x=0$ 외의 해는?","식":["$-2x^{2}+4x=0$, $-2x(x-2)=0$","$x=0,\\ 2$"],"설명":"그림에서 직선은 원점을 지나고 곡선과 다시 만나는 점이 $S_{1}$의 오른쪽 끝이다.","확인":"2","스킬":"G1"},{"제목":"$S_{1}$의 넓이","힌트":"$0\\le x\\le2$에서 곡선이 직선보다 위이다. 두 식의 차를 적분하면?","식":["$S_{1}=\\displaystyle\\int_{0}^{2}\\{(-2x^{2}+6x)-2x\\}\\,dx=\\int_{0}^{2}(-2x^{2}+4x)\\,dx$","$=\\left[-\\dfrac{2}{3}x^{3}+2x^{2}\\right]_{0}^{2}=\\dfrac{8}{3}$"],"설명":"위쪽 식에서 아래쪽 식을 뺀 것을 적분한다.","확인":"8/3","스킬":"D8"},{"제목":"$S_{2}$의 넓이","힌트":"곡선과 $x$축 사이 전체 넓이를 먼저 구하면? $S_{2}$는 전체에서 무엇을 뺀 것인가?","식":["전체 $=\\displaystyle\\int_{0}^{3}(-2x^{2}+6x)\\,dx=\\left[-\\dfrac{2}{3}x^{3}+3x^{2}\\right]_{0}^{3}=9$","$S_{2}=9-S_{1}=9-\\dfrac{8}{3}=\\dfrac{19}{3}$"],"설명":"도형 전체가 직선으로 나뉘어 $S_{1}$과 $S_{2}$가 되므로 $S_{1}+S_{2}$가 전체 넓이이다.","확인":"19/3","스킬":"D8","고비":true},{"제목":"$S_{2}-2S_{1}$의 값","힌트":"$\\dfrac{19}{3}-2\\cdot\\dfrac{8}{3}$을 계산하면?","식":["$S_{2}-2S_{1}=\\dfrac{19}{3}-\\dfrac{16}{3}=1$"],"설명":"분모가 같으므로 분자끼리 뺀다.","확인":"1","스킬":"A3"}]},"ns-76b4bc803267":{"길":"그래프의 넓이로 t=2, 6, 10의 위치를 먼저 구하고 보기를 위치의 변화로 판정한다","단계":[{"제목":"구간별 넓이와 위치","힌트":"$[0,2]$, $[2,6]$, $[6,10]$의 삼각형 넓이와 부호는? $t=6$의 위치는?","식":["$[0,2]$: $\\dfrac{1}{2}\\cdot2\\cdot1=1$ ($v\\ge0$), $[2,6]$: $\\dfrac{1}{2}\\cdot4\\cdot2=4$ ($v\\le0$), $[6,10]$: $\\dfrac{1}{2}\\cdot4\\cdot2=4$ ($v\\ge0$)","위치 $x(2)=1$, $x(6)=1-4=-3$, $x(10)=-3+4=1$"],"설명":"위치는 속도의 정적분이므로 $v<0$인 구간의 넓이는 빼 준다.","확인":"-3","스킬":"D10"},{"제목":"ㄱ 판정","힌트":"위치가 감소하는 구간은 어디인가? 그 구간이 끝나는 시각에서 위치는?","식":["$2<t<6$에서 $v<0$이므로 위치는 감소","최소는 $t=6$에서 $x=-3$ (ㄱ 거짓)"],"설명":"$t=4$는 속도가 가장 작아지는 시각일 뿐이고, 위치는 $v$가 $0$이 되는 $t=6$까지 계속 감소한다.","확인":null,"스킬":"D10"},{"제목":"ㄴ 판정","힌트":"$|x(2)|$, $|x(6)|$, $|x(10)|$ 중 가장 큰 것은?","식":["$|x(2)|=1$, $|x(6)|=3$, $|x(10)|=1$","거리는 $t=6$에서 최대 (ㄴ 참)"],"설명":"위치의 방향이 바뀌는 시각 $t=2$, $t=6$과 끝점 $t=10$에서 원점까지의 거리를 비교한다.","확인":null,"스킬":"D10"},{"제목":"ㄷ 판정: 원점을 지나는 횟수","힌트":"위치의 부호가 바뀌는 구간은 어디인가?","식":["$x(2)=1>0$, $x(6)=-3<0$ → $(2,6)$에서 한 번","$x(6)=-3<0$, $x(10)=1>0$ → $(6,10)$에서 한 번","모두 $2$번 (ㄷ 거짓)"],"설명":"$[0,2]$에서는 위치가 $0$에서 양수로 커지기만 하므로 다시 지나지 않는다. 따라서 옳은 것은 ㄴ뿐이다.","확인":null,"스킬":"D10","고비":true}]},"ns-8b4cc3d6cd9a":{"길":"S1+S2가 삼각형 넓이임을 이용해 S2를 먼저 구하고 교점 조건과 연립한다","단계":[{"제목":"직선 $\\mathrm{AB}$와 $S_{1}+S_{2}$","힌트":"$\\mathrm{A}(3,0)$, $\\mathrm{B}(0,4)$를 지나는 직선과 두 축으로 둘러싸인 삼각형의 넓이는?","식":["$y=-\\dfrac{4}{3}x+4$","$S_{1}+S_{2}=\\dfrac{1}{2}\\cdot3\\cdot4=6$"],"설명":"$S_{1}$과 $S_{2}$를 합하면 곡선이 가르는 두 부분이 모여 삼각형 $\\mathrm{OAB}$ 전체가 된다.","확인":"6","스킬":"G3"},{"제목":"$S_{2}$의 넓이","힌트":"$S_{1}:S_{2}=20:7$이고 합이 $6$이다. $S_{2}$는 합의 몇 분의 몇인가?","식":["$S_{2}=6\\cdot\\dfrac{7}{27}=\\dfrac{14}{9}$"],"설명":"비 $20:7$에서 전체는 $27$이고 $S_{2}$의 몫은 $7$이다.","확인":"14/9","스킬":"A8"},{"제목":"교점 조건과 $S_{2}$를 $a$, $b$로","힌트":"교점 $(b,\\,ab^{2})$는 직선 위의 점이다. $S_{2}$를 곡선 아래 넓이와 삼각형 넓이의 합으로 쓰면?","식":["$ab^{2}=-\\dfrac{4}{3}b+4=\\dfrac{4}{3}(3-b)$","$S_{2}=\\displaystyle\\int_{0}^{b}ax^{2}\\,dx+\\dfrac{1}{2}(3-b)\\cdot\\dfrac{4}{3}(3-b)=\\dfrac{1}{3}ab^{3}+\\dfrac{2}{3}(3-b)^{2}$"],"설명":"$x$축 위의 $0\\le x\\le b$에서는 곡선 아래가, $b\\le x\\le3$에서는 밑변 $3-b$, 높이 $ab^{2}$인 삼각형이 $S_{2}$를 이룬다.","확인":null,"스킬":"C7","고비":true},{"제목":"$b$의 값","힌트":"$\\dfrac{1}{3}ab^{3}=\\dfrac{1}{3}b\\cdot ab^{2}$에 교점 조건을 넣고 $S_{2}=\\dfrac{14}{9}$로 놓으면?","식":["$\\dfrac{4}{9}b(3-b)+\\dfrac{2}{3}(3-b)^{2}=\\dfrac{14}{9}$","$(3-b)(9-b)=7$, $b^{2}-12b+20=0$","$b=2$ ($b<3$)"],"설명":"$b$는 $\\mathrm{A}$의 $x$좌표 $3$보다 작아야 하므로 두 근 $2$, $10$ 중 $2$를 고른다.","확인":"2","스킬":"A10"},{"제목":"$a$와 $a+b$","힌트":"$ab^{2}=\\dfrac{4}{3}(3-b)$에 $b=2$를 넣으면?","식":["$4a=\\dfrac{4}{3}$, $a=\\dfrac{1}{3}$","$a+b=\\dfrac{1}{3}+2=\\dfrac{7}{3}$"],"설명":"교점 조건에 $b$의 값을 대입해 $a$를 구한다.","확인":"7/3","스킬":"A3"}]},"ns-9af028bafe4c":{"길":"두 넓이가 같다는 것을 ∫f=0으로 바꿔 동시에 방향이 바뀌는 시각의 두 위치를 구한다","단계":[{"제목":"$g(t)$의 식","힌트":"직선 $y=g(t)$는 $(0,-5)$와 $(4,0)$을 지난다. 기울기와 $y$절편은?","식":["기울기 $\\dfrac{0-(-5)}{4-0}=\\dfrac{5}{4}$","$g(t)=\\dfrac{5}{4}t-5$"],"설명":"그림에서 직선은 $y$축과 $-5$에서, $t$축과 $4$에서 만난다.","확인":null,"스킬":"G9"},{"제목":"동시에 방향이 바뀌는 시각","힌트":"$g(t)$의 부호가 바뀌는 $t$는? 그 시각에 $f$의 부호도 바뀌는가?","식":["$g(t)=0$: $t=4$","$f(4)=0$이고 $t=4$ 앞뒤에서 $f$의 부호가 양에서 음으로 바뀜"],"설명":"$\\mathrm{P}$는 $f$, $\\mathrm{Q}$는 $g$의 부호가 바뀔 때 방향을 바꾼다. $f$는 $t=4$ 전에도 한 번 더 부호가 바뀌지만, $g$가 $0$이 되는 시각은 $t=4$뿐이다.","확인":"4","스킬":"D10"},{"제목":"$t=4$에서 $\\mathrm{P}$의 위치","힌트":"곡선 $y=f(t)$와 $t$축, $y$축으로 둘러싸인 두 부분의 넓이가 같으면 $\\displaystyle\\int_{0}^{4}f(t)\\,dt$는?","식":["$\\displaystyle\\int_{0}^{4}f(t)\\,dt=(\\text{위쪽 넓이})-(\\text{아래쪽 넓이})=0$"],"설명":"$t$축 아래 부분의 넓이는 빼고 위 부분의 넓이는 더한다. 두 넓이가 같으므로 정적분이 $0$이고, $\\mathrm{P}$는 $t=4$에서 원점에 있다.","확인":"0","스킬":"D8","고비":true},{"제목":"$t=4$에서 $\\mathrm{Q}$의 위치","힌트":"$\\displaystyle\\int_{0}^{4}\\left(\\dfrac{5}{4}t-5\\right)dt$를 계산하면?","식":["$\\displaystyle\\int_{0}^{4}g(t)\\,dt=\\left[\\dfrac{5}{8}t^{2}-5t\\right]_{0}^{4}=10-20=-10$"],"설명":"$\\mathrm{Q}$는 $y$축 위를 움직이므로 $t=4$에서 $y$좌표가 이 값이다.","확인":"-10","스킬":"D10"},{"제목":"두 점 사이의 거리","힌트":"$\\mathrm{P}$는 원점, $\\mathrm{Q}$는 $y$축 위의 점이다. 두 점의 좌표는?","식":["$\\mathrm{P}(0,\\,0)$, $\\mathrm{Q}(0,\\,-10)$","$\\overline{\\mathrm{PQ}}=|0-(-10)|=10$"],"설명":"두 점이 모두 $y$축 위에 있으므로 거리는 $y$좌표의 차의 절댓값이다.","확인":"10","스킬":"D10"}]},"ns-c1f1335c43ec":{"길":"속도의 부호로 방향 전환을 읽고 넓이로 위치를 구하며 포물선의 대칭을 이용한다","단계":[{"제목":"속도의 부호와 방향 전환","힌트":"그래프에서 $v(t)$의 부호는 $0<t<5$, $5<t<15$, $t>15$에서 각각 어떠한가?","식":["$0<t<5$: $v<0$, $5<t<15$: $v>0$, $t>15$: $v<0$","처음으로 방향을 바꾸는 시각은 $t=5$ (ㄱ 참)"],"설명":"점은 $v$의 부호가 바뀔 때 진행방향을 바꾼다. $t=5$에서 부호가 음에서 양으로 처음 바뀐다.","확인":null,"스킬":"D10"},{"제목":"$t=5$, $t=15$에서의 위치","힌트":"$[0,5]$에서 $v<0$이므로 $\\displaystyle\\int_{0}^{5}v\\,dt$는 $\\mathrm{A}$의 넓이와 부호가 어떠한가?","식":["$x(5)=\\displaystyle\\int_{0}^{5}v\\,dt=-10$","$x(15)=-10+20=10$"],"설명":"위치는 속도의 정적분이다. $v<0$인 구간에서는 넓이에 음의 부호를 붙이고 $v>0$인 구간에서는 양의 부호를 붙인다.","확인":"-10","스킬":"D8"},{"제목":"ㄴ: 처음으로 원점을 다시 지나는 시각","힌트":"포물선이 $v(5)=v(15)=0$이면 어느 직선에 대칭인가? $\\displaystyle\\int_{5}^{10}v\\,dt$는 $\\mathrm{B}$의 넓이의 몇 분의 몇인가?","식":["$v$는 $t=10$에 대칭이므로 $\\displaystyle\\int_{5}^{10}v\\,dt=\\dfrac{1}{2}\\cdot20=10$","$x(10)=-10+10=0$, $5<t<10$에서 $x$는 증가 (ㄴ 참)"],"설명":"$x(5)=-10$에서 $x$는 증가하여 $t=10$에서 $0$이 되므로 그때 처음으로 원점을 다시 지난다.","확인":null,"스킬":"T2","고비":true},{"제목":"ㄷ: 좌표의 최댓값","힌트":"$x(t)$가 증가하는 구간과 감소하는 구간은 어디인가?","식":["$5<t<15$에서 $x$ 증가, $t>15$에서 $x$ 감소","최댓값은 $x(15)=10$ (ㄷ 참)"],"설명":"$t=15$ 이후에는 $v<0$이므로 좌표가 줄어든다. 따라서 옳은 것은 ㄱ, ㄴ, ㄷ이다.","확인":null,"스킬":"D10"}]},"ns-c85ea7a4b661":{"길":"OB가 지름임을 이용해 반원 넓이에서 지름과 포물선 사이의 넓이를 뺀다","단계":[{"제목":"원의 지름","힌트":"$t=1$일 때 $\\mathrm{O}$, $\\mathrm{A}$, $\\mathrm{B}$의 좌표와 $\\angle\\mathrm{OAB}$는?","식":["$\\mathrm{O}(0,0)$, $\\mathrm{A}(1,0)$, $\\mathrm{B}(1,1)$, $\\angle\\mathrm{OAB}=90^{\\circ}$","$\\overline{\\mathrm{OB}}$가 지름, $\\overline{\\mathrm{OB}}=\\sqrt{2}$, 반지름 $\\dfrac{\\sqrt{2}}{2}$"],"설명":"원주각이 $90^{\\circ}$이면 그 각에 대한 현이 지름이다. 원의 중심은 $\\overline{\\mathrm{OB}}$의 중점 $\\left(\\dfrac{1}{2},\\dfrac{1}{2}\\right)$이다.","확인":null,"스킬":"S5"},{"제목":"영역의 구성","힌트":"포물선 $y=x^{2}$은 $0<x<1$에서 직선 $y=x$의 위인가 아래인가? 지름 $\\overline{\\mathrm{OB}}$ 아래의 반원과 어떤 관계인가?","식":["원 $\\cap\\ \\{y\\le x^{2}\\}$ = (지름 $\\overline{\\mathrm{OB}}$ 아래 반원) $-$ (직선 $y=x$와 포물선 사이)"],"설명":"포물선과 원은 $\\mathrm{O}$, $\\mathrm{B}$ 두 점에서만 만나고, $0<x<1$에서 $x^{2}<x$이므로 포물선은 반원 안에서 지름 아래에 있다. 그 사이 부분을 반원에서 빼면 $y\\le x^{2}$인 부분만 남는다.","확인":null,"스킬":"D8","고비":true},{"제목":"두 부분의 넓이","힌트":"반원의 넓이는 $\\dfrac{1}{2}\\pi r^{2}$이다. 직선과 포물선 사이는 $\\displaystyle\\int_{0}^{1}(x-x^{2})\\,dx$이다.","식":["반원 $=\\dfrac{1}{2}\\pi\\left(\\dfrac{\\sqrt{2}}{2}\\right)^{2}=\\dfrac{\\pi}{4}$","$\\displaystyle\\int_{0}^{1}(x-x^{2})\\,dx=\\dfrac{1}{2}-\\dfrac{1}{3}=\\dfrac{1}{6}$"],"설명":"위쪽 식 $y=x$에서 아래쪽 식 $y=x^{2}$을 뺀 것을 적분한다.","확인":"1/6","스킬":"D8"},{"제목":"$S(1)$과 $p+q$","힌트":"$\\dfrac{\\pi}{4}-\\dfrac{1}{6}$을 분모가 $12$인 꼴로 쓰면 $p$, $q$는?","식":["$S(1)=\\dfrac{\\pi}{4}-\\dfrac{1}{6}=\\dfrac{3\\pi-2}{12}$","$p=3$, $q=-2$, $p+q=1$"],"설명":"$\\dfrac{\\pi}{4}=\\dfrac{3\\pi}{12}$, $\\dfrac{1}{6}=\\dfrac{2}{12}$이다.","확인":"1","스킬":"A3"}]},"ns-df70cb04b20a":{"길":"반대 방향으로 도는 두 점은 간 거리의 합이 둘레의 배수일 때 만난다","단계":[{"제목":"둘레와 이동 방향","힌트":"직사각형의 둘레는? 그림에서 $\\mathrm{P}$와 $\\mathrm{Q}$는 각각 어느 변을 향해 출발하는가?","식":["둘레 $=2(4+2)=12$","$\\mathrm{P}$는 $\\mathrm{A}\\to\\mathrm{B}$ 방향, $\\mathrm{Q}$는 $\\mathrm{A}\\to\\mathrm{D}$ 방향이므로 서로 반대로 돈다"],"설명":"두 점이 반대 방향으로 돌면 만날 때마다 두 점이 간 거리의 합이 둘레의 정수배가 된다.","확인":"12","스킬":"C7"},{"제목":"각 점이 움직인 거리","힌트":"$\\mathrm{P}$가 출발한 지 $T$초 후이면 $\\mathrm{Q}$가 움직인 시간은? $\\mathrm{Q}$의 거리는 속도 $2s$를 어떻게 적분하는가?","식":["$\\mathrm{P}$: $3T$","$\\mathrm{Q}$: $\\displaystyle\\int_{0}^{T-2}2s\\,ds=(T-2)^{2}$ ($T\\ge2$)"],"설명":"$\\mathrm{Q}$는 $2$초 뒤에 출발하므로 움직인 시간이 $T-2$이다. 속도가 일정한 $\\mathrm{P}$는 속도에 시간을 곱한다.","확인":null,"스킬":"D10","고비":true},{"제목":"두 번째 만남의 조건","힌트":"첫 번째 만남에서 두 거리의 합은 둘레의 몇 배인가? 두 번째는?","식":["첫 번째 만남: $3T+(T-2)^{2}=12$","두 번째 만남: $3T+(T-2)^{2}=24$"],"설명":"두 점이 출발한 뒤 처음 만날 때 합이 $12$이고, 그 뒤 두 번째로 만날 때 합이 $24$이다.","확인":"24","스킬":"C7"},{"제목":"$T$의 값","힌트":"$3T+(T-2)^{2}=24$를 정리하고 인수분해하면?","식":["$T^{2}-T-20=0$, $(T-5)(T+4)=0$","$T\\ge2$이므로 $T=5$"],"설명":"시간은 양수이므로 음수인 근은 버린다.","확인":"5","스킬":"A10"},{"제목":"그때 $\\mathrm{Q}$의 속도","힌트":"$\\mathrm{Q}$가 움직인 시간은 몇 초이고 속도 $2s$에 넣으면?","식":["$\\mathrm{Q}$의 속도 $=2(T-2)=2\\cdot3=6$"],"설명":"$\\mathrm{Q}$가 움직인 시간은 $T-2=3$초이다.","확인":"6","스킬":"D10"}]},"ns-fe65cb49b9dd":{"길":"A와 B의 넓이를 k로 나타내 같다고 놓으면 k³항이 사라져 일차식이 된다","단계":[{"제목":"$A$의 넓이","힌트":"$A$는 $0\\le x\\le k$에서 곡선과 $x$축 사이 영역이다. 넓이를 적분으로 쓰면?","식":["$A=\\displaystyle\\int_{0}^{k}x^{2}\\,dx=\\dfrac{k^{3}}{3}$"],"설명":"$x^{2}$의 부정적분은 $\\dfrac{x^{3}}{3}$이다.","확인":null,"스킬":"D8"},{"제목":"$B$의 넓이","힌트":"곡선과 $y=4$가 만나는 $x$는? $k\\le x\\le2$에서 위쪽 식과 아래쪽 식은?","식":["$x^{2}=4$에서 $x=2$","$B=\\displaystyle\\int_{k}^{2}(4-x^{2})\\,dx=\\left[4x-\\dfrac{x^{3}}{3}\\right]_{k}^{2}=\\dfrac{16}{3}-4k+\\dfrac{k^{3}}{3}$"],"설명":"$B$는 직선 $y=4$ 아래, 곡선 위 영역이므로 $4-x^{2}$를 적분한다. 위끝 $2$를 넣은 값에서 아래끝 $k$를 넣은 값을 뺀다.","확인":null,"스킬":"D8","고비":true},{"제목":"$A=B$에서 $k$","힌트":"양변의 $\\dfrac{k^{3}}{3}$을 지우면 $k$에 대한 몇 차식이 되는가?","식":["$\\dfrac{k^{3}}{3}=\\dfrac{16}{3}-4k+\\dfrac{k^{3}}{3}$","$4k=\\dfrac{16}{3}$, $k=\\dfrac{4}{3}$"],"설명":"$k^{3}$의 항이 양변에서 지워지므로 일차방정식이 된다.","확인":"4/3","스킬":"A3"}]}});
